window.HADITH_CHUNKS['14_1'] = [{"id": 7769, "bookId": 14, "volNo": "1", "hadithNo": 1, "chapter": "ایمان کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِیَ اللّٰہ تَعَالَی عَنْہُ قَالَ: بَیْنَمَا نَحْنُ عِنْدَ رَسُوْلِ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ذَاتَ یَوْمٍ ، إِذْطَلَعَ عَلَیْنَا رَجُلٌ شَدِیْدُ بِیَاضِ الثِّیَابِ، شَدِیْدُ سَوَادِ الشَّعْرِ، لَایُرَی عَلَیْہِ أَثَرُالسَّفَرِ وَلَا یَعْرِفُہُ مِنَّا أَحَدٌ حَتَّی جَلَسَ إِلَی النَّبِیِّ صَلَی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّم، فَأَسْنَدَ رُکْبَتَیْہِ إِلَی رُکْبَتَیْہِ وَوَضَعَ کَفَّیْہِ عَلَی فَخِذَیْہِ وَقَالَ: یَا مُحَمَّدُ أَخْبِرْنِیْ عَنِ الْإِسْلَامِ قَالَ: اَلْإِسْلَامُ أَنْ تَشْھَدَ أَنْ لَاإِلَہَ إِلَّا اللّٰہ وَأَنَّ مُحَمَّداً رَّسُوْلُ اللّٰہ وَتُقِیْمَ الصَّلَوۃَ وَتُؤْتِیَ الزَّکوۃَ وَتَصُوْمَ رَمْضَانَ وَتَحُجَّ الْبَیْتَ إِنِ اسْتَطَعْتَ إِلَیْہِ سَبِیْلاً قَالَ: صَدَقْتَ فَعَجِبْنَا لَہُ یَسْاَلُہُ وَیُصَدِّقُہُ قَالَ: فَأَخْبِرْنِیْ عَنِ الإِیْمَانِ قَالَ: أَنْ تُؤْمِنَ بِاللّٰہ وَمَلاَءِکَتِہِ وَکُتُبِہِ وَرُسُلِہِ وَالْیَوْمِ الْآخِرِوَ تُؤْمِنَ بِالْقَدْرِخَیْرِہِ وَشَرِّہِ‘‘ (مسلم شریف)\nحدیث 2:\nعَنْ عُبَادَۃَ بْنِ الصَّامِتِ قَالَ سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ یَقُوْلُ مَنْ شَھِدَ أَنْ لَا إِلٰہَ إِلَّا اللّٰہُ وَأَنَّ مُحَمَّداً رَّسُوْلُ اللّٰہِ حَرَّمَ اللّٰہُ عَلَیْہِ النّارَ‘‘ (مسلم شریف)\nحدیث 3:\nعَنْ أَنَسٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ لَا یُؤْمِنُ أَحَدُکُمْْ حَتَّی أَکُوْنَ أَحَبَّ إِلَیْہِ مِن وَّالِدِہِ وَوَلَدِہِ وَالنَّاسِ أَجْمَعِیْنَ‘‘ (بخاری ومسلم)", "urdu": "¥ترجمہ حدیث 1:\nحضرت عمر بن خطاب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ایک روز ہم رسولِ خدا صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی خدمت میں حاضر تھے کہ اچانک ایک شخص حاضر ہوا جس کے کپڑے بہت سفید تھے ( اور) بال نہایت سیاہ نہ اس شخص پر سفر کا کوئی نشان تھا اور نہ ہم میں سے کوئی اسے پہچانتا تھا یہاں تک کہ وہ حضور صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کے سامنے بیٹھ گیا اور دو زانو ہو کر اپنے گھٹنے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے گھٹنے سے ملا دیئے اور اپنے دونوں ہاتھ اپنی رانوں پر رکھ لیے اور عرض کیا اے محمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) مجھ کو اسلام کی حقیقت کے بارے میں آگاہ فرمائیے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا اسلام یہ ہے کہ تو گواہی دے اس امر کی کہ خدائے تعالیٰ کے سوا کوئی معبود نہیں، اور محمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) خدائے تعالیٰ کے رسول ہیں اور تو نماز ادا کرے ۔ زکوۃ دے رمضان کے روزے رکھے اور خانۂ کعبہ کا حج کرے اگر توا س کی استطاعت رکھتا ہو اس شخص نے ( یہ سن کر) عرض کیا آپ نے سچ فرمایا (راوی کہتے ہیں کہ) ہم لوگوں کو تعجب ہوا کہ یہ شخص دریافت بھی کرتا ہے اور ( خود ہی) تصدیق بھی کرتا ہے پھر اس نے پوچھا ایمان کی حقیقت بیان فرمائیے ۔ آپ نے فرمایا۔ ( ایمان یہ ہے ) کہ تو خدا تعالیٰ اور اس کے فرشتوں نیز اس کی کتابوں اور اس کے رسولوں اور قیامت کے دن پریقین رکھے اور تقدیر کی بھلائی اور برائی کو دل سے مانے ۔ \n¥ترجمہ حدیث 2:\nحضرت عبادہ بن صامت رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کو فرماتے ہوئے سنا کہ جو شخص اس بات کی گواہی دے کہ خدائے تعالیٰ کے سوا کوئی معبود نہیں اورمحمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم ) خدائے تعالیٰ کے رسول ہیں۔ تو اللّٰہ تعالیٰ اس پر دوزخ کی آگ حر ام فرمادیتا ہے ۔ \n¥ترجمہ حدیث 3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سر کار اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ کوئی شخص اس وقت تک مومن نہیں ہوسکتا جب تک کہ میں اس کے ماں باپ بیٹے اور تمام لوگوں سے زیادہ محبوب نہ ہوجاؤں۔", "roman": "Tarjuma Hadees 1: Hazrat Umar Bin Khattab Radiyallahu Anhu ne farmaya ke ek roz hum Rasool-e-Khuda Sallallahu Alayhi wa Sallam ki khidmat mein hazir thay ke achanak ek shakhs hazir hua jis ke kapray bohat safaid thay (aur) baal nihayat siyah, na us shakhs par safar ka koi nishan tha aur na hum mein se koi usay pehchanta tha yahan tak ke woh huzoor Sallallahu Alayhi wa Sallam ke samnay baith gaya aur do zanu ho kar apnay ghutnay huzoor Sallallahu Alayhi wa Sallam ke ghutnay se mila diye aur apnay dono haath apni raanon par rakh liye aur arz kiya ae Muhammad Sallallahu Alayhi wa Sallam mujh ko Islam ki haqeeqat ke baray mein aagah farmaiye. Huzoor Sallallahu Alayhi wa Sallam ne farmaya Islam yeh hai ke tu gawah de is amar ki ke Khuda-e-Ta'ala ke siwa koi mabood nahi, aur Muhammad Sallallahu Alayhi wa Sallam Khuda-e-Ta'ala ke Rasool hain aur tu Namaz ada karay, Zakat day, Ramzan ke Roze rakhay aur Khana-e-Ka'aba ka Hajj karay agar tu is ki istita'at rakhta ho. Us shakhs ne (yeh sun kar) arz kiya aap ne sach farmaya (raawi kehtay hain ke) hum logon ko ta'ajjub hua ke yeh shakhs daryaft bhi karta hai aur (khud hi) tasdeeq bhi karta hai. Phir us ne poocha Imaan ki haqeeqat bayan farmaiye. Aap ne farmaya: (Imaan yeh hai) ke tu Khuda Ta'ala aur us ke farishton, neez us ki Kitaabon aur us ke Rasoolon aur Qayamat ke din par yaqeen rakhay aur taqdeer ki bhalai aur burai ko dil se manay. Tarjuma Hadees 2: Hazrat Ubaadah Bin Saamit Radiyallahu Anhu ne kaha ke main ne Rasool-e-Kareem Sallallahu Alayhi wa Sallam ko farmatay huay suna ke jo shakhs is baat ki gawah de ke Khuda-e-Ta'ala ke siwa koi mabood nahi aur Muhammad Sallallahu Alayhi wa Sallam Khuda-e-Ta'ala ke Rasool hain, to Allah Ta'ala us par dozakh ki aag haram farma deta hai. Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke koi shakhs us waqt tak momin nahi ho sakta jab tak ke main us ke maa baap, betay aur tamam logon se zyada mehboob na ho jaaun.", "explanation": "¥شرح حدیث 1:\n حضرت شیخ محقق شاہ عبدالحق دہلوی بخار ی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ ’’ اَلْإِسْلَامُ أَنْ تَشْھَدَ أَنْ لَااِلٰہَ إِلَّا اللّٰہُ وَأَنَّ مُحَمَّداً رَّسُوْلُ اللّٰہ ‘‘ کے تحت فرماتے ہیں:\n کہ اسلام اسم ظاہر اعمال ست و ایمان نام باطن اعتقاد و دین عبارت از مجموع اسلام وایمان ست وآنکہ درعقائد مذکورست کہ اسلام وایمان یکے ست بآن معنی ست کہ ہر مومن مسلم است وہر مسلم مومن و نفی یکے مومن دواسم از مسلمان نہ توان کرد ، وبہ حقیقت اسلام ثمرۂ ایمان و فرع ست و علماء رادریں مسئلہ کلام بسیارست وتحقیق ایںاست کہ گفتہ شد ۔\nیعنی اسلام ظاہری اعمال(مثلاً نماز پڑھنے ، روزہ رکھنے ، زکوۃ دینے وغیرہ) کا نام ہے اور ایمان نام ہے اعتقادِ باطن کا ( یعنی اللّٰہ تعالیٰ اور اس کے پیارے رسول صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو دل سے ماننے کا نام ایمان ہے )اور اسلام و ایمان کے مجموعہ کا نام دین ہے اور وہ جو عقائد (کی کتابوں) میں مذکور ہے کہ اسلام و ایمان دونوں ایک ہی ہیں تو اس کا مطلب یہ ہے کہ ہر مومن مسلمان ہے اور ہر مسلمان مومن ہے اور ان دونوں میں سے کسی ایک کی نفی مسلمان سے نہیں کرسکتے ۔ اور حقیقت میں اسلام ایمان کا نتیجہ اور اس کی فرع ہے ۔ علمائے کرام کے کلام اس مسئلہ میں بہت ہیں لیکن تحقیق یہی ہے جو بیان کیا گیا ۔ (اشعۃ اللمعات جلد اول ص ۳۸)\n پھر حضرت شیخ محقق نے ’’ أَنْ تُؤْمِنَ بِاﷲِ ‘‘ کے تحت فرمایا ہے کہ:\n ’’ حقیقت ایمان اینست کہ بگردی بخدائے تعالٰی بذات و صفات ثبوتیہ وسلبیۂ وے و تنزیہ وتقدیس وے تعالی کنی از جمیع نقائص وامارات حدوث ‘‘\n یعنی ایمان کی حقیقت یہ ہے کہ تو خدائے تعالیٰ کی ذات اور اس کی صفاتِ ثبوتیہ و سلبیہ کو دل سے مانے اور تمام عیبوں اور حدوث کی علامتوںسے اسکوپاک ومنزہ یقین کرے ۔ (اشعۃ اللمعات ، ج ۱ ، ص ۴۰)\n اور وَرُسُلِہ کے تحت فرمایا کہ:\n’’ واجب ست ایمان آوردن بہمہ انبیابے فَرْق دراصل نبوت و واجب ست احترام وتنزیہہ ساحتِ عزت ایشاں از وصمت نقص وعصمت ایشاں از جمیع گنا ہاں خرد وبزرگ پیش از نبوت وپس ازوے ہمیں ست قول مختار وآنچہ در قرآن مجید بآدم ( علیہ السلام ) نسبت عصیاں کردہ وعتاب نمودہ مبنی برعلوشان قرب اوست و مالک رامی رسد کہ برترک اولٰی وافضل اگر چہ بحد معصیت نہ رسد بہ بندۂ خود ہر چہ خواہد بگوید وعتاب نماید دیگرے رامجال نہ کہ تواندگفت ۔ واینجا ادبیست کہ لازم است رعایت آں وآں انیست کہ اگر از جانب حضرت بہ بعض انبیاء کہ مقربانِ درگاہ اندعتابے وخطابے رودیا از جانب ایشاں کہ بندگانِ خاص ادیند تواضعے وذلتے وانکسارے صادرگرددکہ موہم نقص بود مارا نباید کہ دراں دخل کنیم وبدان تکلم نمائیم ، ومجمل اعتقاد درحق سید انبیاء صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ آنست کہ ہر چہ جز مرتبۂ الوہیت وصفات اوست حضرت اوراثابت ست ووے ہمہ فضائل وکمالات بشری راشامل و درہمہ راسخ وکامل ‘‘۔ \nیعنی تمام انبیائے کرام علیہم السلام پرایمان لانا واجب ہے ( اس طرح پر کہ کسی کے درمیان ) اصل نبوت میں تفریق نہ کرے اور تعظیم و توقیر کرنا نیز نقص کے عیب سے ان حضر ات کی بارگاہِ عزت کو پاک سمجھنا اور قبلِ نبوت و بعدِ نبوت چھوٹے بڑے تمام گناہوں سے انہیں معصوم جاننا واجب ہے ۔ یہی قول مختار ہے ۔ اور جو قرآنِ مجید میں حضرت آدم علیہ السلام کی طرف عصیان کی نسبت کی گئی اور عتاب فرمایا گیا تو وہ ان کی شانِ قرب کی بلندی پر مبنی ہے اور مالک کو حق پہنچتا ہے کہ اولیٰ اور افضل کے ترک پر اگرچہ وہ گناہ کی حد تک نہ پہنچے ہوں ان پر اپنے بندہ کو جو چاہے کہے اور عتاب فرمائے دوسرے کی مجال نہیں کہ کچھ کہہ سکے اور اس مقام پر ایک معیار ِادب ہے جس کی رعایت ضروری ہے اور وہ یہ ہے کہ اگر خدائے تعالیٰ کی طرف سے بعض انبیاء علیہم السلام پر جو کہ بارگاہِ الہٰی کے مقرب ہیں کوئی عتاب یا خطاب نازل ہو یا ان حضرات کی جانب سے جو کہ خدائے تعالیٰ کے مخصوص بندے ہیں کوئی تواضع، عاجزی اور انکساری کا اظہار ہو جس سے نقص کا وہم ہوتا ہو تو ہم کو جائز نہیں کہ اس میں دخل دیں اور ان ( کلمات ِعتاب یا تواضع) کو ( ان کے حق میں) بولیں اور سید الانبیاء صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے بارے میں اجمالی اعتقاد یہ ہے کہ مرتبہ الوہیت اور خدا کی صفات کے علاوہ جو کچھ ہے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے لیے ثابت ہے اور آنحضرت صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ تمام فضائل و کمالاتِ بشری کے جامع اور سب میں راسخ وکامل ہیں۔ (اشعۃ اللمعات ، ج ۱ ، ص ۴۰)\n¥شرح حدیث :2\nواضح ہو کہ توحید و رسالت کی گواہی کے باوجود اگر آدمی سے کوئی ایسا قول یا فعل پایا گیا جو کفر کی نشانی ہو تو بحکم شریعتِ مطہرہ وہ کافر ہوجائے گا۔ اشعۃ اللمعات جلد اول کتاب الایمان کے شروع میں ہے :\n’’ باوجود تصدیق واقرار چیزے کنند کہ شار ع آں را امارت و علامت کفر ساختہ مثل سجدہ صنم و شد زنّار و امثال آں پس مرتکب ایں امور نیز بحکم شر ع کافراست اگرچہ فرضاً تصدیق واقرار داشتہ باشد ‘‘\nیعنی ( توحید و رسالت کی ) تصدیق و اقرار کے باوجود اگر کوئی ایسا کام کرے جس کو شار ع علیہ السلام نے کفر کی نشانی اور علامت ٹھہرائی ہو جیسے بت کو سجدہ کر نا اور زنار ( یعنی جینو) باندھنا وغیرہ ۔ تو ایسے کاموں کا کرنے والا بھی بحکم شرع کافر ہے اگرچہ بظاہر (توحید و رسالت کی) تصدیق و اقرا رکرتا ہو۔ \n¥شرح حدیث :3\nحضر تِ شیخ محقق شاہ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ نشان ایمان مومن کامل آنست کہ پیغمبر خدا صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ محبوب تر و معظم از ہمہ چیز وہمہ کس باشد نزد مومن ‘‘\nیعنی مومنِ کامل کے ایمان کی نشانی یہ ہے کہ مومن کے نزدیک رسولِ خدا صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم تمام چیزوں اور تمام لوگوں سے زیادہ محبوب و معظم ہوں۔\n پھر چند سطور کے بعد فرماتے ہیں کہ:\n’’ مراد بامحبت ایں جا ترجیح جانب آنحضرت صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ درادائے حق بالتزامِ دین و اتباعِ سنت دررعائت ادب و ایثار رضائے وے برہرکہ و ہر چہ غیر اوست از نفس وولد و والد اہل و مال و منال چنانکہ راضی شود بہلا کہ نفس خود وفقدان ہر محبوب نہ فوات حق وے صلی اللّٰہ تعالی علیہ وسلم ‘‘(1)\n اس حدیث میں حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے زیادہ محبوب ہونے کا مطلب یہ ہے کہ حقوق کی ادائیگی میں حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو اونچا مانے اس طرح کہ حضور کے لائے ہوئے دین کو تسلیم کرے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی سنتوں کی پیروی کرے حضور کی تعظیم و ادب بجالائے اور ہر شخص اور ہر چیز یعنی اپنی ذات ، اپنی اولاد ، اپنے ماں باپ، اپنے عزیز و اقارب اور اپنے مال و اسباب پر حضور کی رضا و خوشی کو مقدم رکھے جس کے معنی یہ ہیں کہ اپنی ہر پیاری چیز یہاں تک کہ اپنی جان کے چلے جانے پر بھی راضی رہے لیکن حضور کے حق کو دبتا ہوا گوارا نہ کرے ۔ (اشعۃ اللمعات ، جلد اول، ص ۴۷)\n اور حضرت مُلا علی قاری علیہ رحمۃ الباری اس حدیث کی شرح میں فرماتے ہیں کہ:\n’’ لَیْسَ الْمُرَادُ الْحُبُّ الطَّبِیْعِیُّ لأنّہ لا یَدْخُلُ تَحْتَ الاخْتِیَارِ وَلَا یُکَلِّفُ اللّٰہُ نَفْسَاً اِلَّا وُسْعَھَا بَلِ الْمُرَادُ الْحُبُّ الْعَقْلِیُّ الَّذِی یُوجِبُ إیْثَارَ مَا یَقْتَضِی العَقْلُ رُجْحَانَہٗ وَیَسْتَدْعِیْ اِخْتِیَارَہٗ وَإِنْ کَانَ عَلٰی خِلافِ الھَوَی کَحُبِّ الْمَرِیْضِ الدَّوَاءَ فإنّہ یَمِیْلُ إلَیہ بِاخْتِیَارِہٖ ویَتَنَاوَلُ بِمُقْتَضَی عَقْلِہٖ لِمَا عَلِمَ وَظَنَّ أنَّ صَلاحَہٗ فِیہ وإن نَفَرَعَنْہُ طَبعُہٗ مثلاً لوأَمَرَہُ صَلَّی اللّٰہُ تَعَالٰی عَلَیْہِ وَسَلَّمَ بِقَتْلِ أَبَوَیْہِ وَأَوْلادِہٖ الکافِرینَ أوْ بِأَنْ یُّقَاتِلَ الکفارَ حَتَّی یکونَ شھیدًا ، لأَحَبَّ أن یختارَ ذلک لِعِلْمِہٖ أنَّ السّلامۃَ فِی امْتِثَال أمْرہٖ صَلَّی اللّٰہُ تَعَالٰی عَلَیْہِ وَسَلَّمَ أوالمراد الحُبُّ الإیْمَانِی النَّاشِیْ عن الإجلالِ والتوقیرِ والاحْسَانِ وَالرَّحمۃِ وَھُوَ إیثارُ جَمِیْعِ أَغْرَاض الْمَحْبُوْبِ عَلٰی جَمِیْعِ أَغْرَاضِ غَیْرِہٖ حَتَّی القَرِیَب وَالنَّفْس وَلَمَّا کَانَ صَلَّی اللّٰہُ تَعَالَی عَلَیْہِ وَسَلَّمَ جَامِعاً لِمُوْجِبَاتِ الْمَحَبَّۃِ مِنْ حُسْنِ الصُّوْرَۃِ وَالسِّیْرَۃِ وَکَمَالِ الْفَضْلِ وَالاحْسَانِ مَا لَمْ یَبْلُغْہٗ غَیْرُہٗ اسْتَحَقَّ أن یَّکُوْنَ أحبَّ إلَیَّ المؤمن مِنْ نَّفْسِہٖ فَضْلاً عَنْ غَیْرِہٖ سِیْمَا وَھُوَ الرَّسُوْلَ مِنْ عِنْدَ الْمَحْبُوْبِ الْحَقِیْقِیِّ الْھَادِیْ إِلَیْہِ وَالدَّالُّ عَلَیْہِ وَالْمُکَرَّم لَدَیْہِ ‘‘(2)\nیعنی اس حدیث میں حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے جو محبت رکھنے کا حکم ہے اس سے مراد محبت طبعی نہیں اس لیے کہ وہ اختیار سے باہر ہے (اور انسان ایسی چیز کا مکلف نہیں بنایاجاتا جو اس کے اختیار سے باہر ہو) ( کَمَا قَالَ اللّٰہُ تَعَالٰی ) { لایُکَلِّفُ اللّٰہنَفْساً الا وُسْعَھَا }بلکہ اس سے مراد محبتِ عقلی ہے جو اس امر کی تقدیم کو ضروری قرار دیتی ہے جس کی ترجیح کا عقل تقاضا کرے اور جس کے اختیار کرلینے کا عقل مطالبہ کرے اگرچہ وہ امر خواہشِ نفس کے خلاف ہی کیوں نہ ہو مثلاً بیمار آدمی کا (کڑوی) دواسے محبت رکھنا(یہ محبت عقلی ہے )چنانچہ وہ دواکو پسند کرکے اس کی طرف مائل ہوتا ہے اور اس کو بربنائے تقاضائے عقل پیتا ہے ؛اس لیے کہ وہ یقین رکھتا ہے یا اندازہ کرتا ہے کہ میری تندرستی اس(دوا کے پینے ) میں ہے اگرچہ اس دوا سے اس کی طبیعت متنفررہتی ہو۔ مثلاً اگر حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کسی کو حکم دیں کہ اپنے کافر والدین اور اولاد کو قتل کردے ۔ یا یہ حکم دے دیں کہ کفار سے لڑائی کرے اور لڑتے ہوئے شہید ہوجائے تو وہ اس کے کر گزرنے کا ضرور شیدائی رہے کیونکہ ازروئے عقل وہ اتنا بہرحال جانتا ہے کہ آپ کی اطاعت ہی میں عافیت ہے ۔ یا اس حدیث میں محبت سے مراد محبت ایمانی ہے جو آپ کی بزرگی قدرو عظمت اور آپ کے احسان و مہربانی کے سبب (قلبِ مومن میں) پیدا ہوتی ہے ، محبت ِایمانی کا تقاضا یہ ہے کہ محب اپنے محبوب کی تمام خواہشوں کو دوسرے لوگوں یہاں تک کہ اپنے عزیز اور خود اپنی ذات کی اغراض پر ترجیح دے ، اور چونکہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ محبت کیے جانے کے تمام اسباب یعنی خوب صورتی، خوش خلقی، کمال ِبزرگی اور کمالِ احسان کے جامع ہیں اور ایسے جامع ہیں کہ آپ کے سوا کوئی دوسرا اس جامعیت کو نہیں پہنچ سکتا ؛لہذا آپ ہر مومن کے نزدیک اس کے نفس سے بھی زیادہ محبوب ہونے کے مستحق ہیں تو مومن کے تئیں اس کے غیر سے بدر جہ اولیٰ آپ محبوب ہوں گے خاص کر اس صورت میں کہ آپ اس محبوبِ حقیقی یعنی خدائے تعالیٰ کی طرف سے رسول ہیں اور خدا تک پہنچانے والے اور اس تک رسائی کا راستہ بنانے والے اور ان کی بارگاہِ جبروت میں عزت و عظمت والے ہیں۔ (مرقاۃ شرح مشکوۃ، جلد اول، ص۶۴)\n¥انتباہ :\n(۱)… خدائے تعالیٰ زمان و مکان سے پاک ہے اس کے لیے زمان و مکان ثابت کرنا کفر ہے ۔\n(۲)… خدائے تعالیٰ کو اللّٰہ پاک یا اللّٰہ تعالیٰ کہنا چاہیے ۔ اللّٰہ میاں کہنا ممنوع و ناجائز ہے ۔\n(۳)… اگر کسی نے خدائے تعالیٰ کے بارے میں بڑھؤ ( بڈھے ) کا لفظ استعمال کیا تو وہ کافر ہوجائے گا۔\n(۴)… کوئی شخص بیمار نہیں ہوتا یا بہت بڈھا ہے مرتا نہیں اس کے لیے یہ نہ کہا جائے کہ اللّٰہ اسے بھول گئے ہیں۔\n(۵)… جو بطورِ تمسخر اور ٹھٹھے کے کفر کرے گا وہ بھی کافر و مرتد ہوجائے گا۔ اگرچہ کہتا ہو کہ میں ایسا اعتقاد نہیں رکھتا جیسا کہ در مختار ، باب المرتد میں ہے : ’’ مَن ھَزَلَ بِلَفْظِ کُفْرٍ اِرْتَدَّ وَ إِنْ لَمْ یَعْْتَقِدْہُ لِلْاِسْتِخْفَافِ ‘‘(3)\n اور شامی جلد سوم ص:۲۹۳پر بحرالرائق سے ہے :’’ والحَاصلُ أَنّ من تَکلّم بکلمۃِ الکُفرِ ھَازلاً أَوْلاعِباً کَفَرَعِنْد الکُلّ ولَا اعتبارَ بِاعْتقادِہ کما صرّح بہ فی الخانیۃ ‘‘(4)\n(۶)… کسی نبی کی شان میں گستاخی و بے ادبی کرنا یا ان کے لیے کوئی عیب ثابت کرنا کفر ہے ۔\n(۷)… قرآنِ مجید کی کسی آیت کو عیب لگانا یا اس کی توہین کرنا یا اس کے ساتھ تمسخر کرنا کفر ہے ۔ مثلاً اکثر داڑھی منڈے کہتے ہیں۔ ’’ کَلاَّ سَوْفَ تَعْلَمُوْنَ ‘‘ جس کا مطلب یہ بیان کرتے ہیں : کَلاَّصاف کرو ۔ یہ قرآنِ مجید کی کھلی ہوئی تحریف ہے اور اس کے ساتھ مذاق دل لگی بھی۔ اور یہ دونوں باتیں کفر ہیں۔ (5)(بہار شریعت، جلد نہم)\n(۸)… کسی سے نماز پڑھنے کو کہا اس نے جواب دیا تم نے نماز پڑھی کیا فائدہ ہوا، یا کہا بہت پڑھ لی اب دل گھبرا گیا ، یا کہا پڑھنا نہ پڑھنا دونوں برابر ہے ، غرض اس قسم کی بات کرنا کہ جس سے فرضیت کا انکار سمجھا جا تا ہو یا نماز کی تحقیر ہوتی ہو ۔ یہ سب کفر ہے ۔ (6) (بہار شریعت)\n(۹)… کسی سے روزہ رکھنے کو کہا اس نے جواب دیا کہ روزہ وہ رکھے جسے کھانا نہ ملے ، یا یہ کہا کہ جب خدا نے کھانے کو دیا ہے تو بھوکے کیوں مریں ، یا اسی قسم کی اور باتیں جن سے روزہ کی ہتک و تحقیر ہو کہنا کفر ہے ۔ (7) (بہار شریعت)\n(۱۰)… ماہ رمضان میں علانیہ دن میں کھانے سے منع کرنے پر یہ لفظ بولنا کہ ’’ جب اللّٰہ کا ڈر نہیں ہے تو لوگوں کا کیا ڈر‘‘ کفر ہے ۔\n(۱۱)… علمِ دین اور علماء کی توہین بے سبب یعنی محض اس وجہ سے کہ وہ عالمِ علمِ دین ہے کفر ہے ۔ (8) (بہار شریعت)\n(۱۲)… ہولی اور دیوالی پوجنا کفر ہے کہ یہ عباداتِ غیر اللّٰہ سے ہے ، کفار کے میلوں، تہواروں میں شریک ہو کر ان کے میلے اور مذہبی جلوس کی شان و شوکت بڑھانا کفر ہے ۔ جیسے رام لیلااور جنم اشٹمی اور رام نومی وغیرہ کے میلوں میں شریک ہونا، یونہی ان کے تہواروں کے دن محض اس وجہ سے چیزیں خریدنا کہ کفار کا تہوار ہے یہ بھی کفر ہے جیسے دیوالی میں کھلونے اور مٹھائیاں خریدی جاتی ہیں کہ آج خریدنا دیوالی منانے کے سوا کچھ نہیں۔ یونہی کوئی چیز خرید کر اس روز مشرکین کے پاس ہدیہ کرنا جب کہ مقصود اس دن کی تعظیم ہو تو کفر ہے ۔ (9) (بہار شریعت جلد نہم ص ۱۷۱، بحوالہ بحرالرائق)\n (۱۳)…’’ اَلْکُفرُفی الشّرعِ إِنکارُ مَا عُلِمَ بِالضّرورۃِ مَجیءُ الرَّسولِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بہ وإنّما عُدَّ لبس الغیارِ وشدّ الزنارِ وَنحوھما کفراً لأنَّھَا تَدُلُّ علی التکذیبِ ، فَإِنَّ مَن صَدَّقَ رَسُولَ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ لَا یَجْتَریء علیھا ظاھراً ‘‘(10)\nیعنی جن باتوں کا پیش کرنا رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم سے قطعی اور یقینی طور پر ثابت ہو، ان میں سے کسی ایک بات کا انکار کرنا اصطلاح شرع میں کفر ہے ۔ غیار (11) اور زنار یعنی جینو وغیرہ کے استعمال کو اس لیے کفر کہا گیا ہے کہ یہ امر(حضور علیہ الصلاۃ والسلام کی) تکذیب کا نشان ہے کیونکہ ظاہر یہی ہے کہ جو رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو مانے گا ، وہ ایسی چیزوں کے استعمال کی جرأت نہیں کرسکتا۔ (بیضاوی ، ص۲۳)\n (۱۴)… ’’ اَلْإِشرَاکُ ھُوَ إِثْباتُ الشَّریکِ فی الألوھیَّۃِ بمعنی وُجوبِ الوجودِ کمَا للمجُوسِ أو بمعنی استحقَاق العِبَادۃِکَمَا لِعَبَدَۃِ الْأَصْنَامِ ‘‘(12)\nیعنی اللّٰہ تعالیٰ کے ساتھ کسی دوسرے کو واجب الوجود ماننا جیسا کہ مجوسیوں کا عقیدہ ہے یا کسی غیر خدا کو لائق ِ عبادت سمجھنا جیسا کہ بت پرستوں کا اعتقاد ہے یہ شرک ہے ۔ (شرح عقائد نسفی ص۶۱)\n اور حضرت شیخ عبدالحق محدث دہلوی رحمۃ اللّٰہ تعالٰی علیہ فرماتے ہیں کہ:\n ’’ شر ک سہ قسم ست در وجود ودر خالقیت ودر عبادت ‘‘ اھ (13)\n اس عبارت کا خلاصہ یہ ہے کہ شرک تین طرح پر ہوتا ہے ایک تویہ کہ اللّٰہ تعالیٰ کے سوا کسی اور کو بھی واجب الوجود ٹھہرائے ، دوسرے یہ کہ خدائے تعالیٰ کے سوا کسی اور کو خالق جانے تیسرے یہ کہ خدائے تعالیٰ کے سوا کسی اور کی عبادت کرے یا اسے مستحق عبادت سمجھے ۔ (اشعۃ اللمعات جلد اول ص ۷۲)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الإیمان ، الفصل الأول ، ج۱، ص۵۰۔ ۵۱ .\n[2] مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الإیمان ، الفصل الأول ، الحدیث : ۷، ج ۱ ص ۱۴۵ .\n[3] ’’ الدر المختار ‘‘، کتاب الجہاد ، باب المرتد ، ج ۶، ص ۳۴۳ .\n[4] ’’ رد المحتار ‘‘، کتاب الجہاد ، مطلب ما یشک أنہ ردۃ لا یحکم بھا ، ج ۶، ص ۳۴۶ .\n[5] ’’ بہارِ شر یعت ‘‘، ج ۲، ص :۴۶۴۔ ’’ الفتاوی الھندیۃ ‘‘، کتاب السیر ، الباب التاسع فی أحکام المرتدین ، ج ۲، ص ۲۶۶ .\n[6] ’’ بہارِ شر یعت ‘‘، ج ۲، ص ۴۶۴۔ ’’ الفتاوی الھندیۃ ‘‘، کتاب السیر ، الباب التاسع فی أحکام المرتدین ، ج ۲، ص ۲۶۸ بتصرف.\n[7] ’’ بہار شر یعت ‘ ‘، ج ۲، ص :۴۶۵ .\n[8] ’’ بہارشریعت ‘ ‘، ج ۲، ص :۴۶۵۔ ’’ الفتاوی الھندیۃ ‘ ‘، کتاب السیر ، الباب التاسع ، ج ۲، ص ۲۷۰ .\n[9] ’’ بہارِ شر یعت ‘‘، ج ۲، ص :۴۶۶۔ ’’ البحر الرائق ‘‘، کتاب السیر ، باب أحکام المرتدین ، ج ۵، ص ۲۰۸\n[10] غیار: ایک کپڑے کا ٹکڑا جو ذمی کافر اپنے شانے پر لگاتے تھے ۔ ۱۲ منہ\n[11] تفسیر البیضاوی ‘‘ ، سورۃ البقرۃ ، آیۃ ۶، ص ۱۳۷ .\n[12] ’’ تفسیر البیضاوی ‘‘ ، سورۃ البقرۃ ، آیۃ ۶، ص ۱۳۷.\n[13] ’’ شرح العقائد النسفیۃ ‘‘، مبحث الأفعال کلھا بخلق اللّٰہ تعالی إلخ ، ص ۷۸."}, {"id": 7770, "bookId": 14, "volNo": "1", "hadithNo": 2, "chapter": "جنتی اور جہنمی فرقہ", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث : 1\nعَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ لَیَأتِیَنَّ عَلَی أُمَّتِیْ کَمَا أَتَی عَلَی بَنِیْ إِسْرَائیْلَ حَذْوَ النَّعْلِ بِالنَّعْلِ حَتَّی إِنْ کَانَ مِنْھُمْ مَنْ أَتَی أُمَّہُ عَلَانِیَۃً لَکَانَ فِیْ أُمَّتِیْ مَنْ یَصْنَعُ ذَلِکَ وَإِنَّ بَنِیْ إِسْرَاءِیْلَ تَفَرَّقَتْ عَلٰی ثِنْتَیْنِ وَ سَبْعِیْنَ مِلَّۃً وَتَفْتَرِقُ أُمَّتِیْ عَلٰی ثَلَثٍ وَّسَبْعِیْنَ مِلَّۃً کُلُّھُمْ فِی النَّارِ إِلَّا مِلَّۃً وَّاحِدَۃً قَالُوْا مَنْ ھِیَ یَارَسُوْلَ اللّٰہ قَالَ مَا أَنَا عَلَیْہِ وَأَصْحَابِی‘‘ (ترمذی، مشکوۃ)\nحدیث : 2\nعَنْ عَبْدِاللّٰہ بْنِ مَسْعُوْدٍ قَالَ خَطَّ لَنَا رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ خَطاً ثُمَّ قَالَ ھَذَا سَبِیْلُ اللّٰہ ثُمَّ خَطَّ خُطُوْطاً عَنْ یَمِیْنِہِ وَعَنْ شِمَالِہِ وَقَالَ ھٰذِہِ سُبُلٌ عَلَی کُلِّ سَبِیْلٍ مِنْھَا شَیْطَان یَدْعُوْ إِلَیْہِ وَقَرَأَ(وَأَنَّ ھَذَا صِرَاطِیْ مُسْتَقِیْماً فَاتَّبِعُوْہُ) الآیۃ۔ (احمد، نسائی، دارمی، مشکوۃ) \nحدیث : 3\nعَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ یَکُوْنُ فِیْ آخِرِالزَّمَانِ دَجَّالُوْنَ کَذَّابُوْنَ یَأْ تُوْنَکُمْ مِنَ الْأَحَادِیْث بِمَا لَمْ تَسْمَعُوْا أَنْتُمْ وَلَا آبَاءُ کُمْ فَإِیَّاکُمْ وَإِیَّاھُمْ لَایُضِلُّوْنَکُمْ وَلَا یَفْتِنُوْنَکُمْ۔ (مسلم، مشکوۃ)", "urdu": "¥ ترجمہِ حدیث 1: \n حضرتِ ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ رسول ِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ میری امت پر ایک زمانہ ضرور ایسا آئے گا جیسا کہ بنی اسرائیل پر آیا تھا۔ بالکل ہو بہو ایک دوسرے کے مطابق ۔ یہاں تک کہ بنی اسر ائیل میں سے اگر کسی نے اپنی ماں سے علانیہ بدفعلی کی ہوگی تو میری امت میں ضرور کوئی ہوگا جو ایسا کرے گا۔ اور بنی اسرائیل بہتّر مذہبوں میں بٹ گئے تھے اور میری امت تہتر مذہبوں میں بٹ جائے گی۔ ان میں ایک مذہب والوں کے سوا باقی تمام مذاہب والے ناری اور جہنمی ہوں گے ۔ صحابہ کرام رَضِیَ اللّٰہ عَنْہُم نے عرض کیا یارسول اللّٰہ ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) وہ ایک مذہب والے کون ہیں؟ ( یعنی ان کی پہچان کیا ہے ؟) حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا وہ لوگ اسی مذہب و ملت پر قائم رہیں گے جس پر میں ہوں اور میرے صحابہ ہیں۔ \n¥ ترجمہِ حدیث 2: \nحضرت عبد اللّٰہ بن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے ہمیں سمجھانے کے لیے ایک(سیدھی)لکیر کھینچی پھر فرمایایہ اللّٰہ کا راستہ ہے پھر اسی سیدھے خط کے دائیں بائیں اور چند لکیریں کھینچ کر فرمایا کہ یہ بھی راستے ہیں۔ ان میں سے ہر ایک راستہ پر شیطان بیٹھا ہوا ہے جو اپنی طرف بلاتا ہے ۔ پھر حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے یہ آیتِ کریمہ تلاوت فرمائی۔ ’’ وَأَنَّ ھَذَا صِرَاطِیْ مُسْتَقِیْماً فَاتَّبِعُوْہ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِکُمْ عَنْ سَبِیْلِہ ‘‘ یعنی یہ میرا سیدھا ر استہ ہے تو اسی پر چلو اور دوسری راہوں پر نہ چلو کہ وہ تمہیں اس سیدھی راہ سے جدا کردیں گی۔ \n¥ ترجمہِ حدیث 3: \nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ آخری زمانہ میں ( ایک گروہ) فریب دینے والوں اور جھوٹ بولنے والوں کا ہوگا وہ تمہارے سامنے ایسی باتیں لائیں گے جن کو نہ تم نے کبھی سنا ہوگا نہ تمہارے باپ دادا نے ۔ تو ایسے لوگوں سے بچو اور انہیں اپنے قریب نہ آنے دو تاکہ وہ تمہیں گمراہ نہ کریں اور نہ فتنہ میں ڈالیں۔", "roman": "Tarjuma-e-Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum se riwayat hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke meri ummat par ek zamana zaroor aisa aayega jaisa ke Bani Israel par aaya tha. Bilkul ho-ba-ho ek dusray ke mutabiq. Yahan tak ke Bani Israel mein se agar kisi ne apni maa se alaniya bad-fe'ali ki hogi to meri ummat mein zaroor koi hoga jo aisa karay ga. Aur Bani Israel bahattar (72) mazhabon mein bat gaye thay aur meri ummat tehattar (73) mazhabon mein bat jaye gi. Un mein ek mazhab walon ke siwa baqi tamam mazhab walay naari aur jahannami honge. Sahabah Radiyallahu Anhum ne arz kiya Ya Rasoolullah Sallallahu Alayhi wa Sallam woh ek mazhab walay kaun hain? (Ya'ni un ki pehchan kya hai?) Huzoor Sallallahu Alayhi wa Sallam ne farmaya woh log isi mazhab-o-millat par qaim rahen ge jis par main hoon aur meray Sahabah hain. Tarjuma-e-Hadees 2: Hazrat Abdullah Bin Mas'ood Radiyallahu Anhu ne farmaya ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne hamain samjhanay ke liye ek (seedhi) lakeer khenchi phir farmaya yeh Allah ka raasta hai, phir isi seedhay khat ke daayen baayen aur chand lakeerain khench kar farmaya ke yeh bhi raastay hain. In mein se har ek raasta par shaitan baitha hua hai jo apni taraf bulata hai. Phir Huzoor Sallallahu Alayhi wa Sallam ne yeh Ayat-e-Kareema tilawat farmai: 'Wa anna haaza siraati mustaqeeman fattabi'oohu wa la tattabi'us subula fatafarraqa bikum an sabeelihi' ya'ni yeh mera seedha raasta hai to isi par chalo aur dusri raahon par na chalo ke woh tumhain is seedhi raah se juda kar dengi. Tarjuma-e-Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke aakhri zamana mein (ek giroh) fareb denay walon aur jhoot bolnay walon ka hoga, woh tumharay samnay aisi baatein layen ge jin ko na tum ne kabhi suna hoga na tumharay baap dada ne. To aisay logon se bacho aur unhain apnay qareeb na aanay do taake woh tumhain gumraah na karain aur na fitna mein daalain.", "explanation": "¥شرح حدیث : 2\n حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت علمِ کلام کی مشہور کتاب ’’مواقف‘‘ کا یہ قول کہ ’’ فرقۂ ناجیہ اہلِ سنت و جماعت اند ‘‘ نقل کرکے فرماتے ہیں کہ:\n’’ اگر گویند چگونہ معلوم شود کہ فرقۂ ناجیہ اہل سنت و جماعت اند وایں راہِ راست ست وراہ خدا ست و دیگر ہمہ راہ ہائے نارست ، و ہر فرقہ دعویٰ مے کندکہ براہ راست ست ومذہب و ے حق ۔ جوابش آنست کہ ایں چیزے نیست کہ بمجرد دعوی تمام شود برہان باید ۔ و برہان حقانیت اہلسنت و جماعت آنست کہ ایں دین اسلام بنقل آمدہ است و مجرد عقل بآں وافی نیست ۔ و بہ تواتر اخبار معلوم شدہ وتتبع وتفحص احادیث و آثار متیقن گشتہ کہ سلف صالح از صحابہ و تابعین باحسان ومن بعد ہم ہمہ بریں اعتقاد وبریں طریقہ بودہ اند وایں بدع وہوا در مذاہب واقوال بعد از صدر اول حادث شدہ واز صحابہ و سلف متقدمین ہیچ کس برآں نہ بودہ وایشاں مبتری بودہ اند وبعد از حدوث ایں رابطۂ صحبت و محبت کہ بآن قوم داشتند قطع کردہ ورد نمودہ ۔ و محدثین اصحاب کتب ستہ وغیرہا از کتب مشہورۂ معتمدہ کہ مبنی ومدار احکام اسلام برآنہا افتادہ و آئمہ فقہائے ارباب مذاہب ار بعہ وغیرہم از آنہا کہ درطبقۂ ایشاں بودہ اند ہمہ بریں مذہب بودہ اند واشاعرہ و ماترید یہ کہ آئمہ اصول کلام اند تائید مذہب سلف نمودہ و بدلائل عقلیہ آنرا اثبات کردہ و آنچہ سنتِ رسول صلّی اللّٰہ تعالی علیہ واٰلہٖ وسلّم و اجماع سلف برآں رفتہ بودہ موکد ساختہ اند ولہذا نام ایشاں اہلسنت و جماعت افتادہ ۔ اگرچہ ایں نام حادث ست اما مذہب واعتقاد ایشان قدیم است وطریقہ ایشان اتباع احادیث نبوی صلّی اللّٰہ تعالی علیہ واٰلہٖ وسلّم واقتدا بآثار سلف و مشائخ صوفیہ از متقدمین و محققین ایشاں کہ استادانِ طریقت وزہاد وعباد و مرتاض و متورع و متقی و متوجہ بجناب حق و متبری از حول وقوت نفس بودہ اند ۔ ہمہ بریں مذہب بودہ اند چنا نکہ از کتب معتمدۂ ایشاں معلوم گردد ودر تعرّف کہ معتمد ترین کتابہائے ایں قوم ست وشیخ الشیوخ شہاب الدین سہروری درشانِ اوگفتہ است ’’ لو لا التعرف ما عرفنا التصوف ‘‘ عقائد صوفیہ کہ اجماع دارند برآں آوردہ کہ ہمہ عقائد اہلسنت و جماعت ست بے زیادت ونقصان ۔ و مصداق ایں سخن کہ گفتیم آنست کہ کتابہائے حدیث و تفسیر وکلام و فقہ و تصوف و سیر وتوا ریخ معتبرہ کہ د ر د یا ر مشرق ومغرب مشہور ومذکور اند جمع کنند وتفحص نمایند ومخالفان نیز کتا بہا را بیارند تا ظاہر شود کہ حقیقت حال چیست وبا لجملۃ سواد اعظم د ر د ین اسلام مذ ہب اہلسنت وجما عت ست ۔ (1)\nیعنی نجات پانے والا فرقہ اہلسنت وجماعت کا ہے ۔ اگر اعتراض کریں کہ کیسے معلوم ہوتا ہے کہ فرقہ ناجیہ اہلِ سنت و جماعت ہے اور یہی سیدھی راہ اور خدائے تعالیٰ تک پہنچانے والی راہ ہے اور دوسرے سارے راستے جہنم کے راستے ہیں اور ہر فرقہ دعویٰ کرتا ہے کہ وہ راہِ راست پر ہے اور اس کا مذہب حق ہے تو اس کا جواب یہ ہے کہ یہ ایسی بات نہیں ہے جو صرف دعویٰ سے ثابت ہوجائے ( اس کے لیے ) ٹھوس دلیل چاہیے ۔ اور اہلِ سنت وجماعت کی حقانیت کی دلیل یہ ہے کہ یہ دینِ اسلام (سرکارِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے ) منقول ہو کر ( ہم لوگوں تک ) پہنچا ہے ۔ عقائد ِاسلام معلوم کرنے کے لیے صرف عقل کا ذریعہ کافی نہیں ہے ۔ اخبارِ متواترہ سے معلوم ہوا اور آثار صحابہ واحادیث کریمہ کی تلاش و تتبع سے یقین حاصل ہوا کہ سلف صالحین یعنی صحابہ و تابعین رضوان اللّٰہ تعالیٰ علیہم اجمعین اور ان کے بعد کے تمام بزرگانِ دین اسی عقیدہ اور اسی طریقہ پر رہے ہیں۔ اقو ال و مذاہب میں بدعت و نفسانیت زمانہ اوّل کے بعد ( پیدا ) ہوئی ہے ۔ صحابۂ کر ام اور سلف متقدمین یعنی تابعین ، تبع تابعین ، مجتہدین میںکوئی اس مذہب پر نہیں تھا وہ لوگ اس نئے مذہب سے بیزار تھے بلکہ اس کے پیدا ہوجانے کے بعد محبت اور اٹھنے بیٹھنے کا جو لگاؤ اس قوم کے ساتھ تھا توڑ دیا اور ( زبان وقلم سے ) رد فرمایا ۔ صحاح ستہ اور ان کے علاوہ ( احادیث کریمہ کی) دوسری مشہور و معتمد کتابیں کہ جن پر احکامِ اسلام کا مدار و مبنی ہوا ان کے محدثین اور حنفی، شافعی ، مالکی اور حنبلی کے فقہاء و آئمہ اور ان کے علاوہ دو سرے علماء جو ان کے طبقہ میں تھے سب اسی مذہبِ اہلسنت و جماعت پر تھے ۔ اور اشاعرہ وماتریدیہ جو اصول ِکلام کے آئمہ ہیں انہوں نے سلف کے مذہب اہلسنت و جماعت کی تائید و حمایت فرمائی اور دلائل عقلیہ سے اس کا اثبات فرمایا۔ اور جن باتوں پر سنتِ رسول ِکریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم اور اجماع سلف صالحین جاری رہا ان کو ٹھوس قرار دیا ہے اسی لیے اشاعرہ اور ما ترید یہ کا نام اہلسنت و جماعت پڑا۔ اگرچہ یہ نام نیا ہے لیکن مذہب و اعتقاد ان کا پرانا ہے ۔ ان کا طریقہ احادیثِ نبوی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی اتباع اور سلف صالحین کے اقوال و اعمال کی اقتداء کرنا ہے اور گروہ صوفیہ کے مشائخ متقدمین اور (زمانہ موجود کے ) شیوخ محققین جو طریقت کے استاد، عابد و زاہد، ریاضت کرنے والے ، پرہیز گار ، خدا ترس، حق تعالیٰ کی جانب متوجہ ر ہنے والے اور نفس کی حکومت سے الگ رہنے والے سب اسی مذہب ِاہلسنت و جماعت پر تھے جیسا کہ ان مشائخ کی معتمد کتابوں سے واضح ہے ۔ اور صوفیائے کرام کی نہایت ہی قابلِ اعتماد کتاب’’ تعرف‘‘ ہے جس کے بارے میں سیدنا شیخ شہاب الدین سہروردی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا ہے کہ اگر’’ تعرف‘‘ کتاب نہ ہوتی تو ہم لوگ مسائل تصوف سے ناواقف رہ جاتے ۔ اس کتاب میں صوفیاء کرام کے جو اجماعی عقائد بیان کیے گئے ہیں وہ سب کے سب بلا کم و کاست اہلسنت ہی کے عقائدہیں۔ ہمارے اس بیان کی سچائی یہ ہے کہ حدیث ، تفسیر، کلام ، فقہ، تصوف، سِیَراور تواریخ معتبرہ کی کتابیں جو کہ مشرق و مغرب کے علاقہ میں مشہور و معروف ہیں جمع کی جائیں اور ان کی چھان بین کی جائے اور مخالفین بھی کتابوں کو لاویں تاکہ آشکارا ہوجائے کہ حقیقت ِحال کیا ہے خلاصہ یہ کہ دین ِ اسلام میں سواد ِاعظم مذہب ِاہل سنت و جماعت ہے ۔ (اشعۃ اللمعات ، باب الاعتصام ، ج ۱، ص۱۴۰)\n¬\n[1] ’’اشعۃ اللمعات‘‘ ، کتاب الإیمان ، باب الاعتصام بالکتاب والسنۃ ، ج ۱، ص۱۵۱۔ ۱۵۲.\n¥شرح حدیث : 3\n حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ عَلَیْہِ اس حدیث کے ترجمہ میں فرماتے ہیں کہ:\n’’ یعنی جماعہ باشند کہ خود را بہ مکر وتلبیس درصورت علماء و مشایخ و صلحا از اہل نصیحت و صلاح نمایند تادر وغہائے خود را ترویج دہند مردم را بہ مذہب یا ظلم و آرائے فاسدہ بخوانند ۔ (1)\nیعنی ایک ایسی جماعت پیدا ہوگی جو مکاری و فریب سے علماء مشائخ اور صلحا بن کر اپنے کو مسلمانوں کا خیر خواہ اور مُصلح ظاہر کرے گی تاکہ اپنی جھوٹی باتیں پھیلائے اور لوگوں کو اپنے باطل عقیدوں، فاسد خیالوں کی طرف راغب کرے ۔ (اشعۃ اللمعات ، جلد اول، ص ۱۳۳)\n------------------\n[1] اشعۃ اللمعات ‘‘، کتاب الإیمان ، باب الاعتصام بالکتاب والسنۃ ، ج ۱، ص ۱۴۳ .\n¥انتباہ :\n (۱)…مخبر صادق حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے جن دجّالوں اور کذّابوں کے آخری زمانہ میں پیدا ہونے کی خبر دی تھی زمانۂ موجودہ میں ان کے مختلف گروہ پائے جاتے ہیں جو مسلمانوں کے سامنے ایسی باتیں بیان کرتے ہیں کہ ان کے آباء و اجداد نے کبھی نہیں سنا ہے ۔\n ان میں کا ایک گروہ وہ ہے جو اپنے آپ کو اہلِ قرآن کہتا ہے ۔ وہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو صرف ایلچی سمجھتا ہے اور بس کھلم کھلا سب حدیثوں کا انکار کرتا ہے بلکہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی اطاعت کا بھی منکر ہے ۔ یہ وہ باتیں ہیں جن کو ہمارے باپ دادا نے کبھی نہیں سنا تھا بلکہ انہیں تو خدائے تعالیٰ نے یہ حکم دیا ہے :\n{ یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اَطِیْعُوا اللّٰهَ وَ اَطِیْعُوا الرَّسُوْلَ } ( پارہ ۵، رکوع ۵)\nیعنی اے ایمان والو ! خدائے تعالیٰ کی اطاعت کرو اور (اسکے )رسول( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) کی اطاعت کرو۔\n ان میں کا ایک گروہ مرزا غلام احمد قادیانی کا ہے ۔ یہ گروہ مرزا کو مہدی، مجدد، نبی اور رسول مانتا ہے ۔ حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے بعد دوسرے نبی کا پیدا ہونا جائز ٹھہراتا ہے ۔ یہ وہ باتیں ہیں جن کو ہمارے آبا ء و اجداد نے کبھی نہیں سنا تھا۔ بلکہ حضور علیہ الصلاۃ والسلام نے انہیں بتایا تھا کہ أَنَا خَاتِمُ النَّبِیِّیْنَ لاَ نَبِیَّ بَعْدِی (1)۔ (مشکوۃ ص۴۶۵) یعنی میں آخر الانبیاء ہوں میرے بعد کوئی (نیا) نبی نہیں ہوگا۔ اور قرآنِ کریم نے انہیں بتایا تھا کہ:\n{ مَا كَانَ مُحَمَّدٌ اَبَاۤ اَحَدٍ مِّنْ رِّجَالِكُمْ وَ لٰكِنْ رَّسُوْلَ اللّٰهِ وَ خَاتَمَ النَّبِیّٖنَؕ- } ( پارہ ۲۲، رکوع ۲)\nیعنی محمد صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ تم مردوں میں سے کسی کے باپ نہیں اور لیکن خدائے تعالیٰ کے رسول اور خاتم النبیین ہیں۔\n یعنی حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی ذات پر نبیوں کی پیدائش کا سلسلہ ختم ہے ۔ آپ نے بابِ نبوت پر مہر لگادی اب آپ کے بعد کوئی نبی ہر گز نہیں پیدا ہوگا۔\n اوران میں کا ایک گروہ وہ ہے جسے وہابی دیوبندی کہا جاتا ہے ۔ اس گروہ کا عقیدہ یہ ہے کہ جیسا علم حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو حاصل ہے ایسا علم تو بچوں، پاگلوں اور جانوروں کو بھی حاصل ہے ۔ جیسا کہ دیوبندیوں کے پیشوا مولوی اشرف علی تھانوی نے اپنی کتاب’’ حفظ الایمان ، ص ۸‘‘ پر حضور علیہ الصلاۃ والسلام کے لیے کل علمِ غیب کا انکار کرتے ہوئے صرف بعض علم غیب کو ثابت کیا بھر بعض علم غیب کے بارے میں یوں لکھا کہ ’’ اس میں حضور کی کیا تخصیص ہے ایسا علم تو زید و عمر و بلکہ ہر صبی و مجنون بلکہ جمیع حیوانات و بہائم کے لیے بھی حاصل ہے ‘‘۔ ( معاذ اللّٰہ رب العالمین )\n اس گروہ کا ایک عقیدہ یہ بھی ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ آخر الانبیاء نہیں ہیں۔ آپ کے بعد دوسرا نبی ہوسکتا ہے ۔ جیسا کہ مولوی قاسم نانوتوی بانی دار العلوم دیوبند نے اپنی کتاب ’’تحذیر الناس، ص: ۳‘‘ پر لکھا ہے کہ ’’عوام کے خیال میں تو رسول اللّٰہ کا خاتم ہونا بایں معنی ہے کہ آپ کا زمانہ انبیائے سابق کے زمانے کے بعد اور آپ سب میں آخری نبی ہیں۔ مگر اہلِ فہم پر روشن ہوگا کہ تقدم یا تاخر زمانہ میں بالذات کچھ فضیلت نہیں۔ ‘‘ اس عبارت کا خلاصہ یہ ہے کہ خاتم النبیین کا یہ مطلب سمجھنا کہ آپ سب میں آخری نبی ہیں۔ یہ ناسمجھ اور گنواروں کا خیال ہے ۔ پھر اسی کتاب کے صفحہ ۲۸ پر لکھا ہے کہ ’’ اگر بالفرض بعد زمانہ نبوی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کوئی نبی پیدا ہو تو پھر بھی خاتمیت محمدی میں کچھ فرق نہ آئے گا۔ ‘‘ اس عبارت کا خلاصہ یہ ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے بعد دوسرا نبی پیدا ہوسکتا ہے ۔ ( العیاذ باللّٰہ تعالیٰ )\n اس گروہ کا ایک عقیدہ یہ بھی ہے کہ شیطان و ملک الموت کے علم سے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کا علم کم ہے ۔ جو شخص شیطان و ملک الموت کے لیے وسیع علم مانے وہ مومن مسلمان ہے لیکن حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے علم کو وسیع اور زائد ماننے والا مشرک بے ایمان ہے ۔ جیسا کہ اس گروہ کے پیشؤا مولوی خلیل احمد انبیٹھی نے اپنی کتاب ’’براہین قاطعہ، ص: ۵۱‘‘ پر لکھا کہ’’ شیطان و ملک الموت کو یہ وسعت نص سے ثابت ہوئی فخرِ عالم کی وسعتِ علم کی کون سی نصِ قطعی ہے جس سے تمام نصوص کو رد کرکے ایک شرک ثابت کرتا ہے ۔ ‘‘( معاذ اللّٰہ رب العالمین )\n اس گروہ کا ایک عقیدہ یہ بھی ہے کہ ’’خدائے تعالیٰ جھوٹ بول سکتا ہے ۔ ‘‘(2) (رسالہ یکروزی ص۱۴۵ مصنف مولوی اسمعیل دہلوی)\n ایک عقیدہ یہ بھی ہے کہ ’’رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ مر کر مٹی میں مل گئے ۔ ‘‘(3) (تقویۃ الایمان ص۷۹)\n مذکورہ بالا عقیدوں کے علاوہ اور بھی اس گروہ کے بہت سے کفری عقیدے ہیں اس لیے مکہ معظمہ، مدینہ طیبہ ، ہند، سندھ ، بنگال ، پنجاب ، برما ، مدراس ، گجرات ، کاٹھیاواڑ ، بلوچستان، سر حد اور دکن وکوکن کے سینکڑوں علمائے کرام و مفتیانِ عظام نے ان لوگوں کے کافر و مرتد ہونے کا فتویٰ دیا ہے ۔ تفصیل کے لیے فتاویٰ’’ حسام الحرمین‘‘ اور’’ الصوارم الھندیہ‘‘ کا مطالعہ کریں۔\n (۲)… مسلمان کو مسلمان اور کافر کو کافر جاننا ضروریاتِ دین میں سے ہے ۔ اگرچہ کسی خاص شخص کے بارے میں یقین کے ساتھ نہیں کہاجاسکتا کہ اس کا خاتمہ ایمان پر ہوا یا معاذ اللّٰہ تعالیٰ کفر پر۔ تاوقتیکہ اس کے خاتمہ کا حال دلیلِ شرعی سے ثابت نہ ہو۔ مگر اس سے یہ نہیں ہوسکتا کہ جس نے قطعاً کفر کیا ہو اس کے کفر میں شک کیا جائے کہ قطعی کافر کے کفر میں شک کرنا بھی آدمی کو کافر بنا دیتا ہے ۔ (4) (بہار شریعت)\n (۳)… بعض ناواقف کہتے ہیں کہ اہلِ قبلہ کی تکفیر نہیں کرنا چاہیے خواہ وہ کیسا ہی عقیدہ رکھے اور کچھ بھی کرے ۔ یہ خیال غلط ہے ۔ صحیح یہ ہے کہ جب اہلِ قبلہ میں کفر کی کوئی علامت و نشانی پائے جائے یا اس سے کوئی بات موجب ِکفر صادر ہو تو اسے کافر کہا جائے گا۔\n حضرت مُلّا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی فرماتے ہیں:\n ’’ أَنَّ المرادَ بِعَدَمِ تکفیْرِ أَحدٍ مِّنْ أھْلِ الْقِبْلَۃِ عند أھْلِ السنَّۃِ أَنَّہ لا یُکفَّر مَا لم یُوْجَدْ شیئٌ من أَمارَاتِ الْکفرِ وَعَلامَاتِہِ وَلَمْ یَصْدَرْ عَنْہُ شَیْئٌ مِن مُوجِبَاتِہِ ‘‘(5)\nیعنی اہلِ سنت کے نزدیک اہلِ قبلہ میں سے کسی کو کافر نہ کہنے سے مراد یہ ہے کہ اسے کافر نہ کہیں گے جب تک کہ اس میں کفر کی کوئی علامت و نشانی نہ پائی جائے اور کوئی بات موجبِ کفر اس سے صادر نہ ہو ۔ (شرح فقہ اکبر ص۱۸۹)\n اور حضرت علامہ ابن عابد ین شامی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں :\n’’ لا خِلافَ فی کُفرِ الْمُخالِف فی ضَرورِیاتِ الْإِسلاَمِ وإِنْ کانَ منْ أَھلِ الْقبلَۃِ المُوَاظِبُ طُوْلَ عُمْرِہٖ عَلَی الطَّاعَاتِ کمَا فِی شرح التحریر ‘‘(6)\n یعنی ضروریات ِ اسلام میں سے کسی چیز کا انکار کرنے والا بالاجماع کافر ہے ۔ اگرچہ اہلِ قبلہ سے ہو اور عمر بھر طاعت میں بسر کرے ۔ جیسا کہ شرح تحریرامام ابن ہمام میں ہے ۔ (شامی جلد اول ص ۳۹۳)\n اور حضرت امام ابویوسف رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے کتاب الخراج میں فرمایا کہ :\n ’’ أیّمَا رَجل سَبَّ رَسولَ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ أََوْکَذبہ أَوْ عَابَہ أَوْ تنقصَہ فَقَدْ کَفَرَ بِاللّٰہ تَعَالَی وَبَانَتْ مِنہ اِمْرَأتہ ‘‘۔ (7)\n یعنی جو شخص مسلمان ( اہلِ قبلہ) ہو کر رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو دشنام دے یا حضور کی طرف جھوٹ نسبت کرے یا حضور کو کسی طرح کا عیب لگائے یا کسی وجہ سے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی شان گھٹائے وہ یقینا کافر، خدا کا منکر ہوگیا اس کی بیوی اس کے نکاح سے نکل گئی۔ (شامی، جلد سوم ، ص۳۰۰)\n¬\n[1] المعجم الأوسط ‘‘ للطبرانی ، من اسمہ بکر ، ج ۲، ص ۲۷۶ .\n ’’ مشکاۃ المصابیح ‘‘، کتاب الرقاق ، الفصل الثانی ، الحدیث : ۵۴۰۶، ج ۲، ص ۲۸۳ .\n[2] رسالہ یکروزی ‘‘، ص ۱۴۵، مصنفہ مولوی اسمعیل دہلوی.\n[3] تقویۃ الإیمان ‘‘ ، ص ۷۹ .\n[4] بہارِ شریعت ‘‘، باب ایمان وکفر کا بیان ، ج ۱، ص ۱۸۵ .\n[5] شرح الفقہ الأکبر ‘‘، باب عدم جواز تکفیر أھل القبلۃ ، ص ۱۵۵ .\n[6] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، مطلب البدعۃ خمسۃ أقسام ، ج ۲، ص ۳۵۷ .\n[7] ’’ رد المحتار ‘‘، کتاب الجہاد ، باب المرتد ، مطلب مھم : فی حکم ساب الأنبیاء ، ج ۶، ص ۳۶۰ ."}, {"id": 7771, "bookId": 14, "volNo": "1", "hadithNo": 3, "chapter": "بد مذہب", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’عَنْ اِبْرَاہِیْمَ بْن مَیْسَرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ مَنْ وَقَّرَصَاحِبَ بِدْعَۃٍ فَقَدْ أَعَانَ عَلَی ھَدَمِ الْإِسْلَامِ‘‘۔ \nحدیث2:\n’’عَنْ أَنَسٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ إِذَا رَأَیْتُمْ صَاحِبَ بِدْعَۃٍ فَاکْفَہِرُّوْا فِی وَجْھِہِ فَإِنَّ اللّٰہ یَبْغُضُ کُلَّ مُبْتَدِعٍ‘‘۔ (ابن عساکر)\nحدیث3:\n’’عَنْ أَبِیْ أُمَامَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ أَہْلُ الْبِدَع کِلَابُ أَھْلِ النَّارِ‘‘۔ \nحدیث4:\n’’عَنْ حُذِیْفَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ لَا یَقْبَلُ اللّٰہ لِصَاحِبِ بِدْعَۃٍ صَوْماً وَّلَا صَلَوۃً وَّلَا صَدَقَۃً وَّلَا حَجًّا وَّلَا عُمْرَۃً وَّلَا جِھَادًا وَّلَا صَرْفًا وَّلَا عَدْلًا یَّخْرُجُ مِنَ الْإِسْلَامِ کَمَا تَخْرُجُ الشَّعْرَۃُ مِنَ الْعَجِیْنِ‘‘۔ (ابن ماجہ)\nحدیث5:\nعَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ إِنْ مَرِضُوْا فَلَا تَعُوْدُوْھُمْ وَإِنْ مَاتُوْا فَلا تَشْھَدُوْھُمْ وَإِنْ لَقِیْتُمُوْھُمْ فَلا تُسَلِّمُوْا عَلَیْھِمْ وَلَا تُجَالِسُوْھُمْ وَلَا تُشَارِبُوْھُمْ وَلَا تُوَاکِلُوْھُمْ وَلَا تُنَاکِحُوْھُمْ وَلَا تُصَلُّوْا عَلَیْھِمْ وَلَا تُصَلُّوْا مَعَھُمْ‘‘۔ (مسلم شریف)", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابراہیم بن میسرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول ِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس نے کسی بدمذہب کی تعظیم و توقیر کی تو اس نے اسلام کے ڈھانے پر مدد دی۔ (مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے کہا کہ سر کار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جب تم کسی بدمذہب کو دیکھو تو اس کے سامنے ترشروئی سے پیش آؤ۔ اس لیے کہ خدا تعالیٰ ہر بدمذہب کو دشمن رکھتا ہے ۔ (ابن عساکر)\n¥ترجمہ حدیث 3:\nحضرت ابوامامہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ بدمذہب دوزخ والوں کے کتے ہیں۔ (دار قطنی)\n¥ترجمہ حدیث 4:\nحضرت حذیفہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے کہا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ خدائے تعالیٰ کسی بدمذہب کا نہ روزہ قبول کرتا ہے ، نہ نماز، نہ زکوۃ، نہ حج، نہ عمرہ، نہ جہاد، نہ نفل ، نہ فرض، بدمذہب دین اسلام سے ایسا نکل جاتا ہے جیسا کہ گوندھے ہوئے آٹے سے بال نکل جاتا ہے ۔ \n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سر کار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ بدمذہب اگر بیمار پڑیں تو ان کی عیادت نہ کرو، اگر مر جائیں تو ان کے جنازہ میں شریک نہ ہو، ان سے ملاقات ہو تو انہیں سلام نہ کرو، ان کے پاس نہ بیٹھو، ان کے ساتھ پانی نہ پیو۔ ان کے ساتھ کھانا نہ کھاؤ، ان کے ساتھ شادی بیاہ نہ کرو، ان کے جنازے کی نماز نہ پڑھو، اور نہ ان کے ساتھ نماز پڑھو۔ (مسلم شریف) اس حدیث کو ابوداؤد نے حضرت ابن عمر سے اور ابن ماجہ نے حضرت جابر سے اور عقیل و ابنِ حبان نے حضرت انس سے روایت کیا۔ رَضِیَ اللّٰہ عَنْہُم ۔", "roman": "Tarjuma Hadees 1: Hazrat Ibrahim Bin Maisarah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jis ne kisi bad-mazhab ki ta'zeem-o-tauqeer ki to us ne Islam ke dahanay par madad di. (Mishkaat) Tarjuma Hadees 2: Hazrat Anas Radiyallahu Anhu se riwayat hai unhon ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jab tum kisi bad-mazhab ko dekho to us ke samnay tursh-ru'i se pesh aao. Is liye ke Khuda Ta'ala har bad-mazhab ko dushman rakhta hai. (Ibn Asakir) Tarjuma Hadees 3: Hazrat Abu Umamah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke bad-mazhab dozakh walon ke kuttay hain. (Dar Qutni) Tarjuma Hadees 4: Hazrat Huzaifah Radiyallahu Anhu se riwayat hai unhon ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Khuda-e-Ta'ala kisi bad-mazhab ka na Roza qabool karta hai, na Namaz, na Zakat, na Hajj, na Umrah, na Jihad, na nafl, na Farz, bad-mazhab deen-e-Islam se aisa nikal jata hai jaisa ke goondhay huay aatay se baal nikal jata hai. Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke bad-mazhab agar beemar parain to un ki ayadat na karo, agar mar jayen to un ke Janazah mein shareek na ho, un se mulaqat ho to unhain Salam na karo, un ke paas na baitho, un ke saath paani na piyo, un ke saath khana na khao, un ke saath shaadi na karo, un ke Janazah ki Namaz na parho, aur na un ke saath Namaz parho. (Muslim Shareef) Is Hadees ko Abu Dawood ne Hazrat Ibn Umar se aur Ibn Majah ne Hazrat Jabir se aur Aqeel-o-Ibn-e-Habban ne Hazrat Anas se riwayat kiya. Radiyallahu Anhum.", "explanation": "¥شرح حدیث 1:\nحضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت فرماتے ہیں کہ:\n’’ در توقیر دے استخفاف و استہانت سنت ست وایں می کشد بویران کردن بنائے اسلام ‘‘(1)\n یعنی بدمذہب کی تعظیم وتوقیر میں سنت کی حقارت اور ذلت ہے ۔ اور سنت کی حقارت اسلام کی بنیاد ڈھانے تک پہنچا دیتی ہے ۔ (اشعۃ اللمعات جلد اول ص۱۴۷)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الإیمان ، باب الاعتصام بالکتاب والسنۃ ، ج۱، ص۱۵۹."}, {"id": 7772, "bookId": 14, "volNo": "1", "hadithNo": 4, "chapter": "سنت اور بدعت", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ مَنْ تَمَسَّکَ بِسُنَّتِیْ عِنْدَ فَسَادِ أُمّتِیْ فَلَہُ أَجْرُ مِءَۃِ شَھِیْدٍ۔ \nحدیث 2:\n’’عَنْ بِلالِ بْنِ حَارِ ثِ الْمُزَنِیِّ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ مَنْ أَحْیَی سُنَّۃً مِّنْ سُنَّتِیْ قَدْ اُمِیْتَتْ بَعْدِیْ فَإِنَّ لَہُ مِنَ الْأَجْرِمِثْلَ أُجُوْرِ مَنْ عَمِلَ بِھَا مِنْ غَیْرِ أَنْ یَنْقُصَ مِنْ أُجُوْرِھِمْ شَیْئاً وَمَنِ ابْتَدَعَ بِدْعَۃً ضَلَالَۃً لَایَرْضَاہُ اللّٰہ وَرَسُوْلُہُ کَانَ عَلَیْہِ مِنَ الْاِثْمِ مِثْلُ آثَامِ مَنْ عَمِلَ بِھَا لَا یَنْقُصُ ذَلِکَ مِنْ أَوْزَارِھِمْ شَیْئاً۔ (ترمذی، مشکوۃ)\nحدیث 3:\n’’عَنْ جَرِیْرٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ مَنْ سَنَّ فِی الْإِسْلَامِ سُنَّۃً حَسَنَۃً فَلَہُ أَجْرُھَا وَأَجْرُمَنْ عَمِلَ بِھَا مِنْ بَعْدِہِ مِنْ غَیْرِ أَنْ یَّنْقُصَ مِنْ أُجُوْرِھِمْ شَیْئٌ، وَمَنْ سَنَّ فِی الْإِسْلَامِ سَنَّۃً سَیِّءَۃً کَانَ عَلَیْہِ وِزْرُھَا وَوِزْرُمَنْ عَمِلَ بِھَا مِنْ بَعْدِہِ مِنْ غَیْرِ أَنْ یَّنْقُصَ مِنْ أَوْزَارِہِمْ شَیْئٌ۔ (مسلم، مشکوۃ) \nحدیث 4:\n’’عَنْ جَابِرٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ اَمَّا بَعْدُ فَاِنَّ خَیْرَ الْحَدِیْثِ کِتَابُ اللّٰہ وَخَیْرُالْھُدَی ھُدَی مُحَمَّدٍ وَشَرّالْاُمُوْرِ مُحْدَثَا تُھَا، وَکُلُّ بِدْعَۃٍ ضَلَالَۃٌ۔ (مسلم، مشکوۃ)", "urdu": "¥ترجمہ حدیث1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص میری امت میں (عملی یا اعتقادی) خرابی پیدا ہونے کے وقت میری سنت پر عمل کرے گا اس کو سو شہیدوں کا ثواب ملے گا۔ (مشکوۃ)\n¥ترجمہ حدیث2:\nحضرت بلال بن حارث مزنی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ نے فرمایا کہ جس نے میری کسی ایسی سنت کو ( لوگوں میں) رائج کیا جس کا چلن ختم ہوگیا ہو تو جتنے لوگ اس پر عمل کریں گے ان سب کے برابر رائج کرنے والے کو ثواب ملے گا اور عمل کرنے والوں کے ثواب میں کچھ کمی نہ ہوگی۔ اور جس نے کوئی ایسی نئی بات نکالی جو سیّئہ ہے جسے اللّٰہ و رسول ( جل جلالہ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) پسند نہیں فرماتے تو جتنے لوگ اس پر عمل کریں گے ان سب کے برابر نکالنے والے پر گناہ ہوگا اور عمل کرنے والوں کے گناہوں میں کچھ کمی نہ ہوگی۔ \n¥ترجمہ حدیث3:\nحضرت جریر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول ِکریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو اسلام میں کسی اچھے طریقہ کو رائج کرے گا تواس کو اپنے رائج کرنے کا بھی ثواب ملے گا اور ان لوگوں کے عمل کرنے کا بھی جو اس کے بعد ا س طریقہ پر عمل کرتے رہیں گے اور عمل کرنے والوں کے ثواب میں کوئی کمی بھی نہ ہوگی۔ اور جو مذہبِ اسلام میں کسی برے طریقہ کو رائج کرے گا تو اس شخص پر اس کے رائج کرنے کا بھی گناہ ہوگا ، اور ان لوگوں کے عمل کرنے کا بھی گناہ ہوگا جو اس کے بعد اس طریقہ پر عمل کرتے رہیں گے اور عمل کرنے والوں کے گناہ میں کوئی کمی نہ ہوگی۔ \n¥ترجمہ حدیث4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سر کار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے (غالباً ایک خطبہ میں) فرمایا۔ بعد حمد الہٰی کے معلوم ہونا چاہیے کہ سب سے بہتر کلام کتاب اللّٰہ ہے اور بہترین راستہ محمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) کا راستہ ہے اور بدترین چیزوں میں وہ ہے جسے نیانکالا گیا اور ہر بدعت گمراہی ہے ۔", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs meri ummat mein (amli ya e'tiqadi) kharabi paida honay ke waqt meri Sunnat par amal karay ga us ko sau shaheedon ka sawab milay ga. (Mishkaat) Tarjuma Hadees 2: Hazrat Bilal Bin Haris Muzni Radiyallahu Anhu se riwayat hai unhon ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jis ne meri kisi aisi Sunnat ko (logon mein) raaij kiya jis ka chalan khatam ho gaya ho to jitnay log us par amal karain ge un sab ke barabar raaij karnay walay ko sawab milay ga aur amal karnay walon ke sawab mein kuch kami na hogi. Aur jis ne koi aisi nayi baat nikali jo sayyi'ah hai jisay Allah-o-Rasool (Jalla Jalaaluhu wa Sallallahu Alayhi wa Sallam) pasand nahi farmatay to jitnay log us par amal karain ge un sab ke barabar nikalnay walay par gunah hoga aur amal karnay walon ke gunahon mein kuch kami na hogi. Tarjuma Hadees 3: Hazrat Jareer Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jo Islam mein kisi achay tareeqa ko raaij karay ga to us ko apnay raaij karnay ka bhi sawab milay ga aur un logon ke amal karnay ka bhi jo us ke baad us tareeqa par amal kartay rahen ge aur amal karnay walon ke sawab mein koi kami bhi na hogi. Aur jo mazhab-e-Islam mein kisi buray tareeqa ko raaij karay ga to us shakhs par us ke raaij karnay ka bhi gunah hoga, aur un logon ke amal karnay ka bhi gunah hoga jo us ke baad us tareeqa par amal kartay rahen ge aur amal karnay walon ke gunah mein koi kami na hogi. Tarjuma Hadees 4: Hazrat Jabir Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne (ghaliban ek Khutbah mein) farmaya: Ba'ad hamd-e-Ilahi ke maloom hona chahiye ke sab se behtar kalaam Kitaab-Allah hai aur behtareen raasta Muhammad Sallallahu Alayhi wa Sallam ka raasta hai aur badtareen cheezon mein woh hai jisay naya nikala gaya aur har bid'at gumraahi hai.", "explanation": "¥شرح حدیث:\nحضرت مُلّا علی قاری علیہ رحمۃ اللّٰہ الباری اس حدیث کی شرح میں فرماتے ہیں کہ :\n قَالَ النَّووی البِدعۃُ کلّ شی ئٍ عمل علی غیر مثال سبق ، وفی الشرع إحدَاثُ ما لم یَکنْ فی عھدِ رسولِ اللّٰہ صلَّی اللّٰہ تعالی علیہ وسلَّم وقولہ کُلُّ بِدْعَۃٍ ضَلَالَۃٌ عامٌ مخصوصٌ قال الشیخُ عزّالدین بن عبد السلام فِی آخرِ ’’ کتابِ القواعد ‘‘ اَلبدعَۃُ إِمّا وَاجبۃٌ کتعلّمِ النحوِ لِفَھم کلام اللّٰہ ورسولِہِ وکتدویْنِ أُصُولِ الْفقۃ والکَلام فِی الجَرح والتَّعدیلِ وَإِمّا مُحرَّمۃٌ کمذہب الجبریَّۃِ والقَدریَّۃ وَالمرجئیَّۃ والمجسِّمۃ والردُّ علی ھؤلاء من البِدَعِ الواجبۃ لأنَّ حفظَ الشَّریْعۃِ مِن ھذہ البِدَعِ فرضُ کفایۃٍ وَإِمَّا مَندُوبَۃٌ کَإِحْدَاث الربطِ والمدارسِ وکلّ احسان لَمْ یَعْھَد فِی الصَّدر الْأوَّل وَکالتَّرَاویح أَیْ بِالجَمَاعَۃِ الْعَامَّۃِ والکلامِ فِی دقائق الصوفیَّۃِ ۔ وَإِمَّا مَکْرُوْھَۃٌ کَزَخرَفۃ المَسَاجدِ وتزویق المصاحفِ یعنی عند الشافعیَّۃ وإما عِندَ الحنفیَّۃِ فمباحٌ وَإِمَّا مُبَاحَۃٌ کَالمُصَافَحَۃِ عَقیبَ الصُّبْح وَالْعصرِأَیْ عندَ الشَافعِیَّۃِ أَیضاً وَإِلَّا فَعِند الحَنفِیَّۃِ مکروہ وَالتَّوسعُ فِی لذَائذِ المآکلِ وَالمشارِبِ وَالمَسَاکِینِ وَتوسِیع الأَکمَامِ وَقَدْ اختلف فِی کراھَۃ بعض ذلک أَیْ کَمَا قَدَّمْنا قَالَ الشَّافعی رَحِمَہ اللّٰہ مَا أحدث ممَّا یخَالفُ الکتاب أَوِالسنَّۃ أَوِالأثر أَوِالاجْمَاع فھو ضَلالۃٌ وَمَا أحدَثَ من الخیر ممَّا لَایخالف شیئاً مِنْ ذَلِکَ فَلیس بمذمومٍ ۔ (1)\nیعنی امام نووی رحمۃ اللّٰہ علیہ نے فرمایا کہ ایسا کام جس کی مثال زمانہ سابق میں نہ ہو ( لغت میں) اس کو بدعت کہتے ہیں۔ اور شرع میں بدعت یہ ہے کہ کسی ایسی چیز کا ایجاد کرنا جو رسول اللّٰہ صلی اللّٰہ تعالٰی علیہ وسلم کے ظاہری زمانہ میں نہ تھی۔ اور حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کا قول’’ کُلُّ بِدْعَۃٍ ضَلَالَۃٌ ‘‘ عام مخصوص ہے ۔ ( یعنی بدعت سے مراد بدعت سیّئہ ہے ) حضرت شیخ عزالدین بن عبدالسلام نے ’’کتاب القواعد‘‘ کے آخر میں فرمایا کہ بدعت یا تو واجب ہے جیسے اللّٰہ اور اس کے رسول کے کلام کو سمجھنے کے لیے علمِ نحو سیکھنا اور جیسے اصولِ فقہ اور اسماء الرجال کے فن کو مرتب کرنا۔ اور بدعت یا تو حرام ہے جیسے جبریہ، قدریہ، مرجئہ اور مجسمہ کا مذہب، اور ان بدمذہبوں کا رد کرنا بدعتِ واجبہ سے ہے اس لیے کہ ان کے عقائدِ باطلہ سے شریعت کی حفاظت فرض کفایہ ہے اور بدعت یا تو مستحب ہے جیسے مسافر خانوں اور مدرسوں کی تعمیر اور ہر وہ نیک کام جس کا رواج ابتدائی زمانہ میں نہیں تھا اور جماعت کے ساتھ تراویح اور صوفیائے کرام کے دقیق اور باریک مسائل میں گفتگو ۔ اور بدعت یا تو مکروہ ہے جیسے شافعیہ کے نزدیک قرآن مجید کی تزئین اور مساجدکا نقش و نگار اور یہ حنفیہ کے نزدیک بلا کراہت جائز ہے ۔ اوربدعت یاتومباح ہے جیسے شافعیہ کے نزدیک صبح اور عصر کی نماز کے بعدمصافحہ کرنا ورنہ حنفیہ کے نزدیک مکروہ ہے ( تحقیق یہ ہے کہ بلا کراہت جائز ہے اسی کتاب میں مصافحہ کا بیان دیکھیے ) اور لذیذکھانے پینے اور رہنے کی جگہوں میں کشادگی اختیارکرنا اور کُرتے کی آستینوں کو لمبی رکھنا۔ اس میں سے بعض کی کراہت میں لوگوں نے اختلاف کیاہے جیسا کہ ہم نے پہلے بیان کیا امام شافعی رحمۃ اللّٰہ تعالیٰ علیہ نے فرمایا کہ ایسی چیز ایجاد کرنا جو قرآن مجید، حدیث شریف ، آثارِ صحابہ یا اجماع کے خلاف ہو تو وہ گمراہی ہے اور ایسی اچھی بات ایجاد کرنا جو ان میں سے کسی کے مخالف نہ ہو تو وہ بری نہیں ہے ۔ (مرقاۃ شرح مشکوۃ ، جلد اول، ص ۱۷۹)\n اور حضرت شیخ عبدالحق محدث دہلوی بخاری رحمۃ اللّٰہ تعالیٰ علیہ اسی حدیث کے تحت فرماتے ہیں:\n’’ بدانکہ ہر چہ پیدا شدہ بعد از پیغمبر صلی اللّٰہ تعالی علیہ وسلم بدعت ست ازانچہ موافق اصول وقواعد سنت اوست وقیاس کردہ شدہ برآں آں را بدعت حسنہ گویند ۔ وآنچہ مخالف آں باشد بدعتِ ضلالت گویند وکلیت ’’ کُلُّ بِدْعَۃٍ ضَلَالَۃٌ ‘‘ محمول بر این ست ۔ وبعض بدعتہا ست کہ واجب ست چنانچہ تعلم وتعلیم صرف ونحو کہ بداں معرفت آیات واحادیث حاصل گردد وحفظ غرائب کتاب وسنت و دیگر چیز ہائیکہ حفظِ دین وملت برآں موقوف بود ۔ وبعض مستحسن و مستحب مثل بنائے رباطہا و مدرسہا و بعض مکروہ مانند نقش ونگارکردن مساجد ومصاحف بقول بعض ۔ وبعض مباح مثل فراخی در طعامہائے لذیذہ ولباسہائے فاخرہ بشرطیکہ حلال باشند وباعث طغیان وتکبر ومفاخرت نہ شوند ومباحات دیگر کہ در زمان آں حضرت صلی اللّٰہ تعالی علیہ وآلہ وسلم نبودند چنانکہ بیری وغربال ومانند آں ۔ وبعض حرام چنانکہ مذہب اہل بدع واہوا برخلاف سنت و جماعت و آنچہ خلفائے راشدین کردہ باشند اگرچہ بآں معنی کہ در زمان آنحضرت صلی اللّٰہ تعالی علیہ وسلم نبودہ بدعت ست ولیکن قسم بدعت حسنہ خواہد بود بلکہ درحقیقت سنت ست ‘‘۔ (2)\nیعنی جاننا چاہیے کہ وہ چیز جو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے ظاہری زمانہ کے بعد ہوئی بدعت ہے ۔ لیکن ان میں سے جو کچھ حضور کی سنت کے اصول و قواعد کے مطابق ہے اور اسی پر قیاس کیا گیا ہے اس کو بدعت حسنہ کہتے ہیں اور ان میں جو چیز سنت کے مخالف ہو اسے بدعت ضلالت کہتے ہیں اور ’’ کُلُّ بِدْعَۃٍ ضَلالَۃٌ ‘‘( ہر بدعت گمراہی ہے ) کی کلیت بدعت کی اسی قسم پر محمول ہے یعنی ہر بدعت سے مراد صرف وہی بدعت ہے جو سنت نبوی کی مخالف ہو۔ اور بعض بدعتیں واجب ہیں جیسے کہ علم صرف و نحو کا سیکھنا سکھانا کہ اس سے آیا ت و احادیث کریمہ کے مفاہیم و مطالب کی معرفت حاصل ہوتی ہے اور قرآن و حدیث کے غرائب کا محفوظ کرنا اور دوسری چیزیں کہ دین و ملت کی حفاظت ان پر موقوف ہے ۔ اور بعض بدعتیں مستحسن و مستحب ہیں۔ جیسے سرائے اور مدرسوں کی تعمیر۔ اور بعض بدعتیں مکروہ ہیں جیسے کہ بعض کے قول پر قرآن مجید اور مسجدوں میں نقش و نگار کرنا۔ اور بعض بدعتیں مباح ہیں جیسے کہ عمدہ کپڑوں اور اچھے کھانوں کی زیادتی بشرطیکہ حلال ہوں اور غرور و نخوت کا باعث نہ ہوں اور دوسری مباح چیزیں جو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے ظاہری زمانہ میں نہ تھیں جیسے بیری اور چھلنی وغیرہ۔ اور بعض بدعتیں حرام ہیں جیسے کہ اہلِ سنت و جماعت کے خلاف نئے عقیدوں اور نفسانی خواہشات والوں کے مذاہب ۔ اور جو بات خلفائے راشدین رضوان اللّٰہ تعالیٰ علیہم اجمعین نے کی ہے اگرچہ اس معنی میں کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے زمانہ میں نہیں تھی بدعت ہے لیکن بدعتِ حسنہ کے اقسام میں سے ہے بلکہ حقیقت میں سنت ہے ۔ (اشعۃ اللمعات ، جلد اول ص ۱۲۸)\n اور شامی جلد اول ص:۳۹۳ میں ہے :\n’’ قَدْ تَکُونُ ( أَیْ اَلْبِدْعَۃُ ) وَاجِبَۃً ، کَنَصْبِ الْأَدِلَّۃِ لِلرَّدِّ عَلَی أَہْلِ الْفِرَقِ الضَّالَّۃِ ، وَتَعَلُّمِ النَّحْوِ الْمُفْہِمِ لِلْکِتَابِ وَالسُّنَّۃِ وَمَنْدُوبَۃً کَإِحْدَاثِ نَحْوِ رِبَاطٍ وَمَدْرَسَۃٍ وَکُلِّ إحْسَانٍ لَمْ یَکُنْ فِی الصَّدْرِ الْأَوَّلِ ، وَمَکْرُوہَۃ کَزَخْرَفَۃِ الْمَسَاجِدِ وَمُبَاحَۃ کَالتَّوَسُّعِ بِلَذِیذِ الْمَآکِلِ وَالْمَشَارِبِ وَالثِّیَابِ کَمَا فِی شَرْحِ الْجَامِعِ الصَّغِیرِ لِلْمُنَاوِیِّ عَنْ تَہْذِیبِ النَّوَوِیِّ ، وَبِمِثْلِہِ فِی الطَّرِیقَۃِ الْمُحَمَّدِیَّۃِ لِلْبِرْکِلِیِّ اہـ ‘‘۔ (3)\nیعنی بدعت کبھی واجب ہوتی ہے جیسے گمراہ فرقے والوں پر رد کے دلائل قائم کرنا اور علم نحو کا سیکھنا جو قرآن و حدیث سمجھنے میں معاون ہوتا ہے ۔ اور بدعت کبھی مستحب ہوتی ہے جیسے مدرسوں اور مسافر خانوں کو تعمیر کرنا اور ہر وہ نیک کام کرنا جو ابتدائی زمانہ میں نہیں تھا۔ اور بدعت کبھی مکروہ ہوتی ہے ۔ جیسے مسجدوں کو آراستہ و مزین کرنا۔ اور بدعت کبھی مباح ہوتی ہے جیسے لذیذ کھانے پینے اور کپڑے میں کشادگی اختیار کر نا جیسا کہ’’ مناوی‘‘ کی شرح جامع صغیر میں تہذیب النووی سے منقول ہے اور اسی کے مثل برکلی کی کتاب ’’طریقہ محمدیہ ‘‘میں ہے ۔\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الإیمان ، الحدیث : ۱۴۱، ج ۱، ص ۳۶۸.\n[2] ’’ اشعۃ اللمعات ‘‘ ، کتاب الإیمان ، باب الاعتصام با لکتاب والسنۃ ، ج ۱، ص ۱۳۵ .\n[3] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، ج ۲، ص ۳۵۶."}, {"id": 7773, "bookId": 14, "volNo": "1", "hadithNo": 5, "chapter": "علم و علماء کرام", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’عَنْ أَنَسٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ طَلَبُ الْعِلْمِ فَرِیْضَۃٌ عَلَی کُلِّ مُسْلِمٍ وَوَاضِعُ الْعِلْمِ عِنْدَغَیْرِ أَھْلِہِ کَمُقَلِّدِ الْخَنَازِیْرِ الْجَوْھَرَ وَاللُّؤْلُؤَ وَالذَّھَبَ‘‘۔ (ابن ماجہ، مشکوۃ)\nحدیث2:\n’’عَنِ ابْنِ سِیْرِیْنَ قَالَ إِنَّ ھَذَا الْعِلْمَ دِیْنٌ فَانْظُرُوْا عَمَّنْ تَأْخُذُوْنَ دِیْنَکُمْ‘‘۔ (مسلم، مشکوۃ)\nحدیث3:\n’’عَنْ أَبِیْ أُمَامَۃَ الْبَاھِلِیِّ قَالَ ذُکِرَ لِرَسُوْلِ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ رَجُلَانِِ أَحَدُھُمَا عَابِدٌ وَّالْآخَرُعَالِمٌ فَقَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ فَضْلُ الْعَالِمِ عَلَی الْعَابِدِ کَفَضْلِیْ عَلَی أَدْنَاکُمْ ثُمَّ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ وَمَلَءِکَتَہُ وَأَھْلَ السَّمَوَاتِ وَالْأَرْضِ حَتَّی النَّمْلَۃَ فِیْ جُحْرِھَا وَحَتَّی الْحُوْتَ لَیُصَلُّوْنَ عَلَی مُعَلِّمِ النَّاسِ الْخَیْرَ۔ (ترمذی، مشکوۃ)\nحدیث4:\n’’عَنْ کَثِیْرِ بْنِ قَیْسٍ قَالَ کُنْتُ جَالِساً مَعْ أَبِی الدَّرْدَاءِ فِیْ مَسْجِدِ دِمَشْقَ فَجَاءَ ہُ رَجُلٌ فَقَالَ یَا أَبَا الدَّرْدَاءِ إِنِّیْ جِئْتُکَ مِنْ مَدِیْنَۃِ الرَّسُوْلِ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ لِحَدِیْثٍ بَلَغَنِیْ أَنَّکَ تُحَدِّثُہُ عَنْ رَّسُوْلِ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ مَا جِئْتُ لِحَاجَۃٍ قَالَ فَإِنِّیْ سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ یَقُوْلُ مَنْ سَلَکَ طَرِیْقاً یَطْلُبُ فِیْہِ عِلْماً سَلَکَ اللّٰہ بِہِ طَرِیْقاً مِنْ طُرُقِ الْجَنَّۃِ وَإِنَّ الْمَلَءِکَۃَ لَتَضَعُ أَجْنِحَتَھَا رِضاً لِطَالِبِ الْعِلْمِ، وَإِنَّ الْعَالِمَ یَسْتَغْفِرُلَہُ مَنْ فِی السَّمَوَاتِ وَمَنْ فِی الْأَرْضِ وَالْحِیْتَانُ فِیْ جَوْفِ الْمَاءِ، وَإِنَّ فَضْلَ الْعَالِمِ عَلَی الْعَابِدِ کَفَضْلِ الْقَمَرِلَیْلَۃَ الْبَدْرِعَلَی سَاءِرِ الْکَوَاکِبِ، وَإِنَّ الْعُلَمَاء وَرَثَۃُ الأَنْبِیَاءِ وَإِنَّ الْأَنْبِیَاءَ لَمْ یُوَرِّثُوْا دِیْنَاراً وَلَا دِرْھَماً وَإِنَّمَا وَرَّثُوْا الْعِلْمَ فَمَنْ أَخَذَہُ أَخَذَ بِحَظٍّ وَافِرٍ‘‘۔ (ترمذی، أبو داود، مشکوۃ)\nحدیث5:\n’’عَنْ مُعَاوِیَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ مَنْ یُّرِدِ اللّٰہ بِہِ خَیْرًا یُفَقِّھْہُ فِی الدِّیْنِ وَإِنَّمَا أَنَا قَاسِمٌ وَاللّٰہ یُعْطِیْ۔ (بخاری، مسلم، مشکوۃ)\nحدیث6:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ تَدَارُسُ الْعِلْمِ سَاعَۃً مِّنَ اللَّیْلِ خَیْرٌ مِّنْ إِحْیَاءِھَا۔ (دارمی، مشکوۃ)\nحدیث7:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ فَقِیْہٌ وَاحِدٌ أَشَدُّ عَلَی الشَّیْطَانِ مِنْ أَلْفِ عَابِدٍ‘‘۔ (ترمذی، مشکوۃ)\nحدیث8:\n’’عَنْ أَبِی الدَّرْدَاءِ قَالَ سُءِلَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّم مَا حَدُّ الْعِلْمِ الَّذِیْ إِذَا بَلَغَہُ الرَّجُلُ کَانَ فَقِیْھاً فَقَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّم مَنْ حَفِظَ عَلَی أُمَّتِیْ أَرْبَعِیْنَ حَدِیْثاً فِیْ أَمْرِ دِیْنِھَا بَعَثَہُ اللّٰہ فَقِیْھاً وَکُنْتُ لَہُ یَوْمَ الْقِیَامَۃِ شَافِعاً وَّشَھِیْداً۔ (مشکوۃ)\nحدیث9:\n’’عَنْ أَبِیْ ھُرَیْرَۃَ قَالَ فِیْمَا أَعْلَمُ عَنْ رَّسُوْلِ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ اللّٰہ عَزَّوَجَلَّ یَبْعَثُ لِھَذِہِ الْأُمَّۃِ عَلَی رَأسِ کُلِّ مِءَۃِ سَنَۃٍ مَنْ یُّجَدِّدُ لَھَا دِیْنَھَا۔\nحدیث10:\n’’عَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّم مَنْ تَعَلَّمَ عِلْماً مِمَّا یُبْتَغَی بِہِ وَجْہُ اللّٰہ لَا یَتَعَلَّمُہُ إِلَّا لِیُصِیْبَ بِہِ عَرَضاً مِّنَ الدُّنْیَا لَمْ یَجِدْعَرْفَ الْجَنَّۃِ یَوْمَ الْقِیَامَۃِ یَعْنِیْ رِیْحَھَا۔ \nحدیث11:\n’’عَنْ سُفْیَانَ أَنَّ عُمَرَ بْنَ الْخَطَّابِ قَالَ لِکَعْبٍ مَنْ أَرْبَابُ الْعِلْمِ قَالَ الَّذِیْنَ یَعْمَلُوْنَ بِمَا یَعْلَمُوْنَ قَالَ فَمَا أَخْرَجَ الْعِلْمَ مِنْ قُلُوْبِ الْعُلَمَاءِ قَالَ الطَّمَعُ۔ \nحدیث12:\n’’عَنِ الْأَحْوَصِ بْنِ حَکِیْمٍ عَنْ أَبِیْہِ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ أَلاَ إِنَّ شَرَّ الشَّرِّ شِرَارُ الْعُلَمَاءِ وَإِنَّ خَیْرَ الْخَیْرِ خِیَارُ الْعُلَمَآء۔ \nحدیث13:\n’’عَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ مَنْ أُفْتِیَ بِغَیْرِ عِلْمٍ کَانَ اِثْمُہُ عَلَی مَنْ أَفْتَاہُ وَمَنْ أَشَارَ عَلَی أَخِیْہِ بِأَمْرٍ یَعْلَمُ أَنَّ الرُّشْدَ فِیْ غَیْرِہِ فَقَدْ خَانَہُ۔", "urdu": "¥ترجمہ حدیث1:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ علم کا حاصل کرنا ہر مسلمان مرد و ( عورت) پر فرض ہے اور نااہل کو علم سکھانے والا ایسا ہے جیسے خنزیر یعنی سور کے گلے میں جواہرات ، موتی اور سونے کا ہار پہنادیا ہو۔ \n¥ترجمہ حدیث2:\nحضرت محمد بن سیرین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے فرمایا کہ یہ علم(یعنی قرآن وحدیث کو جاننا)دین ہے لہذا تم دیکھ لو کہ اپنا دین کس سے حاصل کررہے ہو۔ \n¥ترجمہ حدیث3:\nحضرت ابوا مامہ باہلی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے فرمایا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کے سامنے د و آدمیوں کا ذکر کیا گیا۔ ایک ان میں سے عابد تھا دوسرا عالم۔ تو سر کارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ عابد پر عالم کی فضیلت ایسی ہے جیسے کہ میری فضیلت تمہارے ادنیٰ آدمی پر، پھر حضور نے فرمایا کہ لوگوں کو بھلائی سکھانے والے پر خدائے تعالیٰ رحمت نازل فرماتا ہے ۔ اوراس کے فرشتے نیز زمین و آسمان کے رہنے والے یہاںتک کہ چیونٹیاں اپنے سوراخوں میں اور مچھلیاں( پانی میں)اس کے لیے دعائے خیر کرتی ہیں۔ \n¥ترجمہ حدیث4:\nحضرت کثیر بن قیس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں حضرت ابوالدرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے ساتھ دمشق کی مسجد میں بیٹھا تھا تو ایک آدمی نے آکر کہا کہ اے ابوالدرداء بے شک میں رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے شہر مدینہ طیبہ سے یہ سن کر آیا ہوں کہ آپ کے پاس کوئی حدیث ہے جسے آپ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے روایت کرتے ہیں ا ور میں کسی دوسرے کام کے لیے نہیں آیا ہوں۔ حضرت ابوالدرداء نے کہا کہ میں نے رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کو فرماتے ہوئے سنا ہے کہ جو شخص علمِ ( دین) حاصل کرنے کے لیے سفر کرتا ہے تو خدا تعالیٰ اسے جنت کے راستوں میں سے ایک راستہ پر چلاتا ہے اور طالبِ علم کی رضا حاصل کرنے کے لیے فرشتے اپنے پروں کوبچھا دیتے ہیں اور ہر وہ چیز جو آسمان و زمین میں ہے یہاں تک کہ مچھلیاں پانی کے اندر عالم کے لیے دعائے استغفار کرتی ہیں۔ اور عالم کی فضیلت عابد پر ایسی ہے جیسی چودھویں رات کے چاند کی فضیلت ستاروں پر۔ اور علماء انبیائے کرام کے وارث و جانشین ہیں۔ انبیائے کرام کا ترکہ دینار و درہم نہیں ہیں۔ انہوں نے وراثت میں صرف علم چھوڑا ہے تو جس نے اسے حاصل کیا اس نے پورا حصہ پایا۔ \n¥ترجمہ حدیث5:\nحضرت معاویہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ خدائے تعالیٰ جس شخص کے ساتھ بھلائی چاہتا ہے تو اسے دین کی سمجھ عطا فرماتا ہے اور خدا دیتا ہے اور میں تقسیم کرتا ہوں۔ \n¥ترجمہ حدیث6:\nحضرتِ ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما سے روایت ہے انہوں نے فر مایا کہ رات میں ایک گھڑی علمِ دین کا پڑھنا پڑھانارات بھر کی عبادت سے بہتر ہے ۔ \n¥ترجمہ حدیث7:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ ایک فقیہ یعنی ایک عالمِ دین شیطان پر ہزار عابدوں سے زیادہ بھاری ہے ۔ \n¥ترجمہ حدیث8:\nحضرت ابوالدرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم سے دریافت کیا گیا کہ اس علم کی حد کیا ہے کہ جسے آدمی حاصل کرلے تو فقیہ یعنی عالمِ دین ہوجائے تو سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جو شخص میری امت تک پہنچانے کے لیے دینی اُ مور کی چالیس حدیثیں یاد کرلے گا تو خدائے تعالیٰ اسے قیامت کے دن عالمِ دین کی حیثیت سے اٹھائے گا اور قیامت کے دن میں اس کی شفاعت کروں گا اور اس کے حق میں گواہ رہوں گا۔ \n¥ترجمہ حدیث9:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے کہا کہ رسولِ کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے جو باتیں میں نے معلوم کی ہیں ان میں سے ایک یہ ہے کہ ہر صدی کے خاتمہ پر اس امت کے لیے اللّٰہ تعالیٰ ایک ایسے شخص کو بھیجے گا جو اس کے لیے اس کے دین کو نکھارتا رہے گا۔ (ابو داود، مشکوۃ)\n¥نوٹ :\n باتفاق علمائے عرب و عجم چودھویں صدی کے مجدد اعلی حضرت امام احمد رضا بریلوی رحمۃ اللّٰہ تعالٰی علیہ ہیں۔ \n¥ترجمہ حدیث10:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جس نے ایسے علم کو سیکھا جس کے ذریعے خدائے تعالیٰ کی خوشنودی طلب کی جاتی ہے ( مگر) اس نے صرف اس لیے سیکھا کہ اس علم سے متاعِ دنیا حاصل کرے تو قیامت کے دن اس کو جنت کی خوشبو تک میسر نہ ہوگی۔ (ابو داود ، مشکوۃ)\n¥ترجمہ حدیث11:\nحضرت سفیان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضرت عمر بن خطاب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے حضرت کعب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے دریافت فرمایا کہ اہلِ علم کون لوگ ہیں؟ انہوں نے جواب دیا کہ جو ا پنے علم کے موافق عمل کریں پھر آپ نے پوچھا کہ عالموں کے دلوں سے کون سی چیز علم ( کے انوار و برکات ) کو نکال لیتی ہے ؟ تو انہوں نے جواب دیا کہ لالچ۔ (دارمی ، مشکوۃ)\n¥ترجمہ حدیث12:\nحضرت احوص بن حکیم اپنے باپ سے روایت کرتے ہیں انہوں نے کہا کہ رسولِ کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ آگاہ ہوجاؤ کہ بُروں میں سب سے بدترین علمائے سُو ہیں۔ اور اچھو ں میں سب سے بہتر علمائے حق ہیں۔ (دارمی ، مشکوۃ)\n¥ترجمہ حدیث13:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جسے بغیر علم کے کوئی فتویٰ دیا گیا تو اس کا گناہ فتویٰ دینے والے پر ہوگا۔ اور جس نے جان بوجھ کر اپنے بھائی کو غلط مشورہ دیا تو اس نے اس کے ساتھ خیانت کی (ابوداود ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne farmaya ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Ilm ka hasil karna har musalman mard-o-(aurat) par Farz hai aur na-ahl ko Ilm sikhanay wala aisa hai jaise khanzeer ya'ni soor ke galay mein jawahiraat, moti aur sonay ka haar pehna diya ho. Tarjuma Hadees 2: Hazrat Muhammad Bin Sireen Radiyallahu Anhu se riwayat hai unhon ne farmaya ke yeh Ilm (ya'ni Quran-o-Hadees ko janna) deen hai lehaza tum dekh lo ke apna deen kis se hasil kar rahay ho. Tarjuma Hadees 3: Hazrat Abu Umamah Bahili Radiyallahu Anhu se riwayat hai unhon ne farmaya ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ke samnay do aadmiyon ka zikr kiya gaya. Ek un mein se aabid tha dusra aalim. To Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke aabid par aalim ki fazeelat aisi hai jaise ke meri fazeelat tumharay adna aadmi par, phir Huzoor ne farmaya ke logon ko bhalai sikhanay walay par Khuda-e-Ta'ala rehmat nazil farmata hai. Aur us ke farishtay neez zameen-o-aasman ke rehnay walay yahan tak ke chiyontiyan apnay surakhon mein aur machhliyan (paani mein) us ke liye Dua-e-Khair karti hain. Tarjuma Hadees 4: Hazrat Kaseer Bin Qais Radiyallahu Anhu ne farmaya ke main Hazrat Abu Darda Radiyallahu Anhu ke saath Damishq ki Masjid mein baitha tha to ek aadmi ne aa kar kaha ke ae Abu Darda beshak main Rasoolullah Sallallahu Alayhi wa Sallam ke shehar Madina Tayyaba se yeh sun kar aaya hoon ke aap ke paas koi Hadees hai jisay aap Rasoolullah Sallallahu Alayhi wa Sallam se riwayat kartay hain aur main kisi dusray kaam ke liye nahi aaya hoon. Hazrat Abu Darda ne kaha ke main ne Rasool-e-Kareem Sallallahu Alayhi wa Sallam ko farmatay huay suna hai ke jo shakhs Ilm-e-(Deen) hasil karnay ke liye safar karta hai to Khuda Ta'ala usay Jannat ke raaston mein se ek raasta par chalata hai aur talib-e-Ilm ki raza hasil karnay ke liye farishtay apnay paron ko bichha detay hain aur har woh cheez jo aasman-o-zameen mein hai yahan tak ke machhliyan paani ke andar aalim ke liye Istighfaar karti hain. Aur aalim ki fazeelat aabid par aisi hai jaisi chaudhween raat ke chand ki fazeelat sitaron par. Aur Ulama Anbiya-e-Kiram ke Waaris-o-janasheen hain. Anbiya-e-Kiram ka Tarkah deenar-o-dirham nahi hain. Unhon ne wirasat mein sirf Ilm chhora hai to jis ne usay hasil kiya us ne poora hissa paya. Tarjuma Hadees 5: Hazrat Mu'awiyah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Khuda-e-Ta'ala jis shakhs ke saath bhalai chahta hai to usay deen ki samajh ata farmata hai aur Khuda deta hai aur main taqseem karta hoon. Tarjuma Hadees 6: Hazrat Ibn Abbas Radiyallahu Anhu ma se riwayat hai unhon ne farmaya ke raat mein ek ghari Ilm-e-Deen ka parhna parhana raat bhar ki ibadat se behtar hai. Tarjuma Hadees 7: Hazrat Ibn Abbas Radiyallahu Anhu ma ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke ek faqeeh ya'ni ek aalim-e-deen shaitan par hazar aabidon se zyada bhaari hai. Tarjuma Hadees 8: Hazrat Abu Darda Radiyallahu Anhu se riwayat hai unhon ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam se daryaft kiya gaya ke is Ilm ki had kya hai ke jisay aadmi hasil kar lay to faqeeh ya'ni aalim-e-deen ho jaye to Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs meri ummat tak pohanchanay ke liye deeni umoor ki chalees Hadeesain yaad kar lay ga to Khuda-e-Ta'ala usay Qayamat ke din aalim-e-deen ki haisiyat se uthayay ga aur Qayamat ke din main us ki Shafa'at karoon ga aur us ke haq mein Gawah rahoon ga. Tarjuma Hadees 9: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai unhon ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam se jo baatein main ne maloom ki hain un mein se ek yeh hai ke har sadi ke khatma par is ummat ke liye Allah Ta'ala ek aisay shakhs ko bhejay ga jo us ke liye us ke deen ko nikhaarta rahay ga. (Abu Dawood, Mishkaat) Note: Battefaq Ulama-e-Arab-o-Ajam chaudhween sadi ke mujaddid Imam Ahmad Raza Barelvi Rahmatullah Ta'ala Alayh hain. Tarjuma Hadees 10: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jis ne aisay Ilm ko seekha jis ke zariye Khuda-e-Ta'ala ki khushnudi talab ki jati hai (magar) us ne sirf is liye seekha ke is Ilm se mata-e-dunya hasil karay to Qayamat ke din us ko Jannat ki khushboo tak mayassar na hogi. (Abu Dawood, Mishkaat) Tarjuma Hadees 11: Hazrat Sufyan Radiyallahu Anhu se riwayat hai ke Hazrat Umar Bin Khattab Radiyallahu Anhu ne Hazrat Ka'ab Radiyallahu Anhu se daryaft farmaya ke ahl-e-Ilm kaun log hain? Unhon ne Jawab diya ke jo apnay Ilm ke muwafiq amal karain phir aap ne poocha ke aalimon ke dilon se kaun si cheez Ilm (ke anwaar-o-barkaat) ko nikal leti hai? To unhon ne Jawab diya ke lalach. (Darimi, Mishkaat) Tarjuma Hadees 12: Hazrat Ahwas Bin Hakeem apnay baap se riwayat kartay hain unhon ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke aagah ho jao ke buron mein sab se badtareen Ulama-e-Soo hain. Aur achon mein sab se behtar Ulama-e-Haq hain. (Darimi, Mishkaat) Tarjuma Hadees 13: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jisay baghair Ilm ke koi Fatwa diya gaya to us ka gunah Fatwa denay walay par hoga. Aur jis ne jaan boojh kar apnay bhai ko ghalat mashwara diya to us ne us ke saath khayanat ki. (Abu Dawood, Mishkaat)", "explanation": "¥شرح حدیث:\n حضرت ملا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی اس حدیث کی شرح میں فرماتے ہیں:\n’’ قَالَ الشُّرَّاحُ اَلْمُرَادُ بِالعلْمِ مَا لَا مندوحۃ لِلْعَبدِ من تعلّمہِ کَمعْرِفۃِ الصَّانِع وَالْعِلمُ بِوحْدَانیَّتِہ ونبوَّۃِ رَسُولِہ وکَیْفِیَۃِ الصَّلاۃ ، فَإِنَّ تعلَّمہ فَرضُ عینٍ ، وَأَمَّا بلوغُ رتبۃِ الاجتھَادِ وَالْفُتیا فَفَرضُ کِفَایَۃٍ ‘‘ ۔ (1)\nیعنی شارحینِ حدیث نے فرمایا کہ علم سے مراد وہ مذہبی علم ہے جس کا حاصل کرنا بندہ کے لیے ضروری ہے جیسے خدائے تعالیٰ کو پہچاننا، اس کی وحدانیت، اس کے رسول کی نبوت کی شناخت اور ضروری مسائل کے ساتھ نماز پڑھنے کے طریقے کو جاننا۔\n اس لیے کہ ان چیزوں کا علم فرضِ عین ہے اور فتویٰ و اجتہاد کے رتبہ کو پہنچنا فرضِ کفایہ ہے ۔ (مرقاۃ شرح مشکوۃ، جلد اول ، ص۲۳۳)\n اور حضرت شیخ عبدالحق محدث دہلوی بخاری رحمۃ اللّٰہ تعالیٰ علیہ اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ مراد بعلم دریں جاعلمے ست کہ ضروری وقت مسلمان ست مثلاً چوں در اسلام در آمد واجب شد بروے معرفت صانع وصفات وے وعلم بہ نبوت رسول اللّٰہ صلی اللّٰہ تعالی علیہ وآلہ وسلم وجز آں از انچہ صحیح نیست ایمان بے آں ۔ وچوں وقت نماز در آمد واجب شد آموختن علم باحکام صلاۃ وچوں رمضان آمد واجب گردید تعلم احکام صوم ۔ وہرگاہ مالک نصاب گردید واجب شد تعلیم احکام زکوۃ واگر پیش ازاں مرد وتعلم نہ کرد عاصی نہ باشد ۔ وچوں زن خواست علم حیض و نفاس و جُز آں ازانچہ متعلق باحکام زن وشوے ست واجب گردد وعلی ہذا القیاس ‘‘۔ (2)\nیعنی علم سے مراد اس حدیث میں وہ علم ہے کہ جو مسلمانوں کو وقت پر ضروری ہے ۔ مثلاً جب اسلام میں داخل ہوا تو اس پر خدائے تعالیٰ کی ذات و صفات کو پہچاننا اور رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی نبوت کو جاننا واجب ہوگیا اور ہر اس چیز کا علم ضروری ہوگیا کہ جس کے بغیر ایمان صحیح نہیں ۔ اور جب نماز کا وقت آگیا تو اس پر نماز کے احکام کا جاننا واجب ہوگیا ۔ اور جب ماہ رمضان آگیا تو روزہ کے احکام کاسیکھنا ضروری ہو گیا۔ اور جب مالک ِنصاب ہوگیا تو زکوۃ کے مسائل کا جاننا واجب ہوگیا اور اگر مالک ِنصاب ہونے سے قبل مرگیا اور زکوۃ کے مسائل کو نہ سیکھا تو گنہگار نہ ہوا۔ اور جب عورت کو (عقد میں) لایا تو حیض و نفاس وغیرہ جتنے مسائل کا زن وشوہر سے تعلق ہے جاننا واجب ہوجاتا ہے ۔ وعلی ھذا القیاس ۔ (اشعۃ اللمعات، جلد اول ، ص ۱۶۱)\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘ ، کتاب العلم ، الفصل الثانی ، الحدیث : ۲۱۸، ج ۱، ص ۴۷۷.\n[2] ’’ اشعۃ اللمعات ‘‘ ، کتاب العلم ، الفصل الثانی ، ج ۱، ص ۱۷۳.\n¥ضروری انتباہ :\n(۱)… حضور سید ِعالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ اکثر رات بھر عبادت فرماتے ۔ یہاں تک پائے مبارک ورم کر جاتے اور صوم و صال یعنی پے درپے روزہ رکھتے ، رات میں افطار نہ فرماتے ، اور جو مال ملتا سب راہِ خدا عزوجل میں خرچ کر ڈالتے ۔ چٹائیوں پر آرام فرماتے ، جَو کی روٹی تناول فرماتے ، کبھی ایک دو مہینہ تک صرف کھجور اور پانی پر اکتفا فرماتے ، کبھی شکمِ اقدس پر پتھر باندھتے ، مگر ان باتوں کو اپنی کمزور و ناتوان امت پر کرم فرماتے ہوئے لازم نہیں فرمایا۔ یعنی حضور رحمتِ عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے ان باتوں کا کسی مسلمان سے مطالبہ نہیں فرمایا چاہے وہ جاہل ہو یا عالم۔ مگر آج کل بعض جاہل جنہیں مذہب سے دور کا بھی واسطہ نہیں ان باتوں کا علماء سے مطالبہ کرتے ہیں اور ایسا نہ کرنے والوں کو نافرمان سمجھتے ہیں اور شرم نہیں کرتے کہ جن باتوں کو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے لازم نہیں فرمایا تو ان بے عمل جاہلوں کو مطالبہ کرنے کا حق کہاں سے پہنچ گیا۔ خدائے تعالیٰ انہیں سمجھ عطا فرمائے ۔\n(۲)…چٹائیوں پر سونے اور پیٹ پر پتھر باندھنے کا مطالبہ کرنے والے اسلام اور مسلمان دونوں کو نقصان پہنچانا چاہتے ہیں۔ اسلام کو اس طرح کہ ایک ایسا غیر مسلم جو دائرہ اسلام میں آنا چاہتا ہے جب اس کو معلوم ہوگا کہ اسلام میں چٹائی پر سونا اور پیٹ پر پتھر باندھنا لازم ہے اور ایسا نہ کرنے والا گنہگار اور حضور پیغمبرِ اسلام صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کانافرمان ٹھہرایا جاتا ہے تو وہ اسلام کی طرف ہر گز نہیں آسکتا۔ اور علماء کو نافرمان و گنہ گار ٹھہرانے والا یہ گروہ مسلمانوں کو اس طرح نقصان پہنچانا چاہتا ہے کہ جب مسلمانوں کے دلوں میں یہ بات راسخ ہوجائے گی کہ علماء خود نافرمان ہیں تو پھروہ عالموں کی نصیحت ہر گز نہیں قبول کریں گے ۔ نماز و روزہ وغیرہ فرائض الٰہیہ کے قریب نہ آویں گے اور برائیوں میں مبتلا ہو کر مستحق عذابِ نار ہوں گے ۔"}, {"id": 7774, "bookId": 14, "volNo": "1", "hadithNo": 6, "chapter": "تقدیر کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَبْدِاللّٰہ بْنِ عَمَرٍو قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ کَتَبَ اللّٰہ مَقَادِیْرَ الْخَلَاءِقِ قَبْلَ أَنْ یَّخْلُقَ السَّمَوَتِ وَالْأَرْضَ بِخَمْسِیْنَ أَلْفَ سَنَۃٍ۔ \nحدیث 2:\n’’عَنْ عُبَادَۃَ بْنِ الصَّامِتِ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّمَ إِنَّ أَوَّلَ مَا خَلَقَ اللّٰہ الْقَلَمَ فَقَالَ لَہُ أُکْتُبْ قَالَ مَا أَکْتُبُ؟ قَالَ أُکْتُبِ الْقَدَرَ فَکَتَبَ مَا کَانَ وَمَا ھُوَ کَاءِنٌ إِلَی الْأَبَدِ۔ \nحدیث 3:\n’’عَنْ مَطْرِبْنِ عُکَامِسٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّم إِذَا قَضَی اللّٰہ لِعَبْدٍ أَنْ یَّمُوْتَ بِأَرْضٍ جَعَلَ لَہُ إِلَیْھَا حَاجَۃً۔ \nحدیث 4:\n’’عَنْ أَبِیْ خُزَامَۃَ عَنْ أَبِیْہِ قَالَ قُلْتُ یَارَسُوْلَ اللّٰہ أَرَأَیْتَ رُقًی نَسْتَرْقِیْھَا وَدَوَاءً نَتَدَاوَی بِہِ وَتُقَاۃً نَتَّقِیْھَا ھَلْ تَرُدَّ مِنْ قَدَرِ اللّٰہ شَیْئاً قَالَ ھِیَ مِنْ قَدَرِ اللّٰہ۔ \nحدیث 5:\n’’عَنْ أَبِیْ ھُرَیْرَۃَ رَضِیَ اللّٰہ تَعَالَی عَنْہُ قَالَ خَرَجَ عَلَیْنَا رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالَی عَلَیْہِ وَسَلَّم وَنَحْنُ نَتَنَازَعُ فِی الْقَدَرِ فَغَضِبَ حَتَّی اِحْمَرَّ وَجْھُہُ حَتَّی کَأَنَّمَا فُقِیءَ فِیْ وَجْنَتَیْہِ الرُّمَّانُ فَقَالَ أَبِھَذَا أُمِرْتُمْ أَمْ بِھَذَا أُرْسِلْتُ إِلَیْکُمْ إِنَّمَا ھَلَکَ مَنْ کَانَ قَبْلَکُمْ حِیْنَ تَنَازَعُوْا فِیْ ھَذَا الْأَمْرِ عَزَمْتُ عَلَیْکُمْ أَنْ لاَّ تَنَازَعُوْا فِیْہِ۔", "urdu": "¥ترجمہ حدیث1: \nحضرت عبد اللّٰہ بن عمر و رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ خدائے تعالیٰ نے آسمان و زمین کی پیدائش سے پچاس ہزار برس قبل مخلوقات کی تقدیروں کو لکھا ( لوحِ محفوظ میں ثبت فرمادیا)۔ (مسلم ، مشکوۃ)\n¥ترجمہ حدیث2: \nحضرت عبادہ بن صامت رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سر کارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ (حقیقت محمدیہ علی صاحبہاالصلوۃوالتحیۃکے بعد) سب سے پہلے جو چیز خدا نے پیدا کی وہ قلم ہے ۔ خدائے تعالیٰ نے اس سے فرمایا لکھ۔ قلم نے عر ض کیا، کیا لکھوں؟ فر مایا تقدیر ۔ تو قلم نے لکھا جو کچھ ہوچکا تھا اور جو اَبدتک ہونے والا تھا۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث3: \nحضرت مطربن عُکامس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جب خدائے تعالیٰ کسی شخص کی موت کسی زمین پر مقدر کردیتا ہے تو اس ز مین کی طرف اس کی حاجت پیدا کردیتا ہے ۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث4: \nحضرت ابو خزامہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے روایت کرتے ہیں انہوں نے کہا کہ میں نے عرض کیا یارسول اللّٰہ ! کیا فرماتے ہیں آپ منتر کے بارے میں جسے ہم پڑھتے ہیں ، اور دوا کے بارے میں جسے ہم استعمال کرتے ہیں، اور بچاؤ کے بارے میں جسے ہم ( جنگ وغیرہ میں) اختیار کرتے ہیں۔ کیا یہ چیزیں خدائے تعالیٰ کی قضا و قدر کو بدل دیتی ہیں؟ فرمایا کہ یہ چیزیں بھی خدائے تعالیٰ کی قضاء و قدر سے ہیں۔ ( ترمذی، ابن ماجہ، مشکوۃ)\n¥ترجمہ حدیث5: \nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم لوگ تقدیر کے مسئلہ میں بحث کررہے تھے کہ رسولِ خدا صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ تشریف لے آئے تو شدتِ غضب سے آپ کا چہرہ سرخ ہوگیا کہ گویا انار کے دانے آپ کے عارضِ اقدس پر نچوڑ دیئے گئے ہوں۔ پھر فرمایا کیا تم کو اسی کا حکم دیا گیا ہے ؟کیا میں تمہاری طرف اسی چیز کے ساتھ بھیجا گیا ہوں۔ تم سے پہلے قومیں ہلاک نہیں ہوئی مگر جب کہ قضا و قدر کے مسئلہ میں انہوں نے مباحثہ کیا۔ میں تمہیں قسم دیتا ہوں اور مکرر قسم دیتا ہوں کہ آئندہ اس مسئلہ میں بحث نہ کرنا۔ (ترمذی، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abdullah Bin Amr Radiyallahu Anhu ma ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Khuda-e-Ta'ala ne aasman-o-zameen ki paidaish se pachaas hazar baras qabl makhlooqat ki taqdeeron ko likha (Lauh-e-Mehfooz mein sabt farma diya). (Muslim, Mishkaat) Tarjuma Hadees 2: Hazrat Ubaadah Bin Saamit Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke (Haqeeqat-e-Muhammadiya Ali Sahibiha-as-Salatu-wat-Tahiyya ke ba'ad) sab se pehlay jo cheez Khuda ne paida ki woh qalam hai. Khuda-e-Ta'ala ne us se farmaya likh. Qalam ne arz kiya, kya likhoon? Farmaya taqdeer. To qalam ne likha jo kuch ho chuka tha aur jo abad tak honay wala tha. (Tirmidhi, Mishkaat) Tarjuma Hadees 3: Hazrat Matar Bin Ukaamis Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jab Khuda-e-Ta'ala kisi shakhs ki maut kisi zameen par muqaddar kar deta hai to us zameen ki taraf us ki haajat paida kar deta hai. (Tirmidhi, Mishkaat) Tarjuma Hadees 4: Hazrat Abu Khuzamah Radiyallahu Anhu apnay baap se riwayat kartay hain unhon ne kaha ke main ne arz kiya Ya Rasoolullah! Kya farmatay hain aap mantar ke baray mein jisay hum parhtay hain, aur Dawa ke baray mein jisay hum istemaal kartay hain, aur bachao ke baray mein jisay hum (jang waghera mein) ikhtiyar kartay hain. Kya yeh cheezain Khuda-e-Ta'ala ki Qaza-o-Qadar ko badal deti hain? Farmaya ke yeh cheezain bhi Khuda-e-Ta'ala ki Qaza-o-Qadar se hain. (Tirmidhi, Ibn Majah, Mishkaat) Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne farmaya ke hum log taqdeer ke mas'ala mein behas kar rahay thay ke Rasool-e-Khuda Sallallahu Alayhi wa Sallam tashreef lay aaye to shiddat-e-ghazab se aap ka chehra surkh ho gaya ke goya anaar ke daanay aap ke aariz-e-aqdas par nichor diye gaye hon. Phir farmaya kya tum ko isi ka Hukm diya gaya hai? Kya main tumhari taraf isi cheez ke saath bheja gaya hoon. Tum se pehlay qawmein halak nahi huin magar jab ke Qaza-o-Qadar ke mas'ala mein unhon ne mubahisa kiya. Main tumhain qasam deta hoon aur mukarrar qasam deta hoon ke aayinda is mas'ala mein behas na karna. (Tirmidhi, Mishkaat)", "explanation": "¥شرح حدیث: \nمُلّا علی قاری علیہ رحمۃ اللّٰہ البار ی اس حدیث کی شرح میں فرماتے ہیں کہ:\n’’ فَالأَوَّلِیَّۃُ إِضَافِیَّۃٌ وَالأَوّلُ الْحقِیْقیُّ ھُوَالنُّورُ الْمُحَمَّدِیّ ‘‘۔ (1)\n یعنی قلم کی اولیت اضافی ہے اور اوّلِ حقیقی نورِ محمدی ہے ۔ (مرقاۃ شرح مشکوۃ جلد اول ص۱۳۹)\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الإیمان ، الحدیث : ۹۴، ج ۱، ص ۲۸۹.\n¥انتباہ :\n (۱)… تقدیر حق ہے اس کا انکار کرنے والا گمراہ ، بدمذہب، اہلِ سنّت و جماعت سے خارج ہے ۔\n (۲)… خدائے تعالیٰ نے ہر بھلائی برائی اپنے علم ازلی کے موافق مقدر فرمادی ہے ۔ جیسا ہونے والا تھا اور جو جیسا کرنے والا تھا اپنے علم ازلی سے جان کر لکھ لیا۔ اس کا یہ مطلب نہیں کہ جیسا اس نے لکھ دیا ویسا ہم کو کرنا پڑتا ہے بلکہ جیسا ہم کرنے والے تھے ویسا اس نے لکھ دیا۔ زید کے ذمہ برائی لکھی اس لیے کہ زید برائی کرنے والا تھا۔ اگر زید بھلائی کرنے والا ہوتا تو خدائے تعالیٰ بھلائی لکھتا۔ خلاصہ یہ کہ خدائے تعالیٰ کے علم یا اس کے لکھ دینے نے کسی شخص کو کسی کام کے کرنے پر مجبور نہیں کردیا ۔ (1) (بہار شریعت)\n اور جیسا کہ حضرت مُلّا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی شرح فقہ اکبرص:۴۹میں فرماتے ہیں کہ :\n کَتَبَ اللّٰہ فِیْ حَقِّ کُلِّ شَیئٍ بِأَنَّہُ سَیَکُوْنُ کَذَا کَذَا وَلَمْ یَکْتُبْ بِأَنَّہُ لِیَکُنْ کَذَا کَذَا ۔ (2)\n (۳)… قضا کی تین قسمیں ۔ قضائے مبرم حقیقی ، قضائے معلق محض، قضائے معلق شبیہ بہ مبرم۔\n------------------\n[1] ’’ بہارِ شریعت‘‘، ج۱، ص۱۱.\n[2] ’’ شرح الفقہ الأکبر ‘‘، باب القضاء والقدر إلخ ، ص ۴۱.\n¥قضائے مبرم حقیقی:\n وہ قضاہے کہ علمِ الہٰی میں بھی کسی چیز پر معلق نہیں۔ اس قضا کی تبدیلی ناممکن ہے اولیاء کی اس قضا تک رسائی نہیں بلکہ انبیائے کرام ورُسل عظام بھی اگر اتفاقاًاس کے بارے میں کچھ عرض کرنا چاہیں تو انہیں اس خیال سے روک دیا جاتا ہے ۔ جیسا کہ حضرت ابراہیم خلیل اللّٰہ علٰی نبینا وعلیہ الصلوۃ والسلام نے حضرت لوط علیہ السلام کی قوم پر عذاب روکنے کے لیے بہت کوشش فرمائی یہاں تک کہ اپنے رب سے جھگڑنے لگے جیسا کہ خدائے تعالیٰ نے فرمایا:\n{ یُجَادِلُنَا فِیْ قَوْمِ لُوْطٍؕ(۷۴) } ( پارہ ۱۲ رکوع ۷)\n یعنی ابراہیم قوم لوط کے بارے میں ہم سے جھگڑنے لگے ۔\n لیکن چونکہ قوم لوط پر عذاب ہونا قضائے مبرم حقیقی تھا اس لیے حکم ہوا :\n { یٰۤاِبْرٰهِیْمُ اَعْرِضْ عَنْ هٰذَاۚ-اِنَّهٗ قَدْ جَآءَ اَمْرُ رَبِّكَۚ-وَ اِنَّهُمْ اٰتِیْهِمْ عَذَابٌ غَیْرُ مَرْدُوْدٍ(۷۶) } ( پارہ ۱۲ رکوع ۷)\n یعنی اے ابراہیم! اس خیال میں نہ پڑو بے شک تیرے رب کا حکم آچکا اور بے شک ان پر عذاب آئے گا۔ پھیرا نہ جائے گا۔\n¥قضائے معلّق محض:\n و ہ قضا ہے کہ فرشتوں کے صحیفوں میں کسی چیز مثلاً صدقہ یا دَوا وغیرہ پر معلق ہونا ظاہر کردیا گیا ہو۔ اس قضا تک اکثر اولیائے کرام کی رسائی ہوتی ہے ان کی دعا اور توجہ سے یہ قضا ٹل جاتی ہے ۔\n¥قضائے معلق شبیہ بہ مبرم:\n وہ قضا ہے کہ علم الہٰی میں وہ کسی چیز پر معلق ہے لیکن فرشتوں کے صحیفوں میں اس کا معلق ہونا مذکور نہیں۔ اس قضا تک خاص اکابر کی رسائی ہوتی ہے ۔ حضرت سیدنا غوث اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اسی کے بارے میں فرماتے ہیں کہ میں قضائے مبرم کررد کردیتا ہوں اور اسی قضا کے بارے میں حدیث شریف میں ارشاد ہوا کہ:\n’’ إِنَّ الدُّعَاء یَرُدُّ الْقضَاءبَعْدَ مَا أُبْرِ مَ ‘‘ یعنی بے شک دعا قضائے مبرم کو ٹال دیتی ہے ۔\n (۴)… قضا و قدر کے مسائل عام لوگ نہیں سمجھ سکتے اس میں زیادہ غور و فکر کرنا دین و ایمان کے تباہ ہونے کا سبب ہے ۔ حضرت ابوبکر صدیق و عمر فاروق رَضِیَ اللّٰہ تَعَالٰی عَنْہُما جیسے جلیل القدر صحابہ بھی اس مسئلہ میں بحث کرنے سے منع فرمائے گئے تو پھر ہم لوگ کس گنتی میں ہیں۔ اتنا سمجھ لینا چاہیے کہ اللّٰہ تعالیٰ نے آدمی کو پتھر اور دیگر جمادات کے مثل بے حس و حرکت نہیں پیدا کیا بلکہ اس کو ایک قسم کا اختیار دیا ہے کہ ایک کام چاہے کرے نہ کرے اور اس کے ساتھ عقل بھی دی ہے کہ بھلے بُرے نفع نقصان کو پہچان سکے اور ہر قسم کے سامان اور اسباب مہیا کردیئے کہ جب آدمی کوئی کام کرنا چاہتاہے تو اسی قسم کے سامان مہیا ہوجاتے ہیں اور اسی وجہ سے اس پر مواخذہ ہے اپنے کو بالکل مجبور یا بالکل مختار سمجھنا دونوں گمراہی ہیں۔ (1) (بہار شریعت)\n------------------\n[1] ’’ بہار شریعت ‘‘، ج۱، ص ۱۸."}, {"id": 7775, "bookId": 14, "volNo": "1", "hadithNo": 7, "chapter": "قبر کا عذاب حق ہے", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ الْبَرَاء بْنِ عَازِبٍ عَنَْ رَّسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ َیَأْتِیہِ مَلَکَانِ فَیُجْلِسَانِہِ فَیَقُولَانِ لَہُ مَنْ رَبُّکَ فَیَقُولُ رَبِّیَ اللّٰہ فَیَقُولَانِ لَہُ مَا دِینُکَ فَیَقُولُ دِینِیَ الْإِسْلَامُ فَیَقُولَانِ مَا ہَذَا الرَّجُلُ الَّذِی بُعِثَ فِیکُمْ قَالَ فَیَقُولُ ہُوَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَیَقُولَانِ لَہُ وَمَا یُدْرِیکَ فَیَقُولُ قَرَأْتُ کِتَابَ اللّٰہ فَآمَنْتُ بِہِ وَصَدَّقْتُ فَذَلِکَ قَوْلُہٗ:{یُثَبِّتُ اللّٰہ الَّذِینَ آمَنُوْا بِالْقَوْلِ الثَّابِتِ فِی الْحَیٰوۃِ الدُّنْیَا وَفِی الْاٰخِرَۃِ} الْآیَۃُ قَالَ فَیُنَادِی مُنَادٍ مِنْ السَّمَاءِ أَنْ صَدَقَ عَبْدِی فَأَفْرِشُوہُ مِنْ الْجَنَّۃِ وَأَلْبِسُوہُ مِنْ الْجَنَّۃِ وَافْتَحُوا لَہُ بَابًا إِلَی الْجَنَّۃِ فَیُفْتَحُ قَالَ فَیَأْتِیہِ مِنْ رَوْحِہَا وَطِیبِہَا قَالَ وَیُفْسَحُ لَہُ فِیہَا مَدَّ بَصَرِہِ وَأَمَّا الْکَافِرُ فَذَکَرَ مَوْتَہُ قَالَ وَیُعَادُ رُوحُہُ فِی جَسَدِہِ وَیَأْتِیہِ مَلَکَانِ فَیُجْلِسَانِہِ فَیَقُولَانِ مَنْ رَبُّکَ فَیَقُولُ ہَاہْ ہَاہْ لَا أَدْرِی فَیَقُولَانِ لَہُ مَا دِینُکَ فَیَقُولُ ہَاہْ ہَاہْ لَا أَدْرِی فَیَقُولَانِ مَا ہَذَا الرَّجُل الَّذِی بُعِثَ فِیکُمْ فَیَقُولُ ہَاہْ ہَاہْ لَا أَدْرِی فَیُنَادِی مُنَادٍ مِنْ السَّمَاء أَنْ کَذَبَ فَأَفْرِشُوہُ مِنْ النَّارِ وَأَلْبِسُوہُ مِنْ النَّارِ وَافْتَحُوا لَہُ بَابًا إِلَی النَّارِ قَالَ فَیَأْتِیہِ مِنْ حَرِّہَا وَسَمُومِہَا قَالَ وَیُضَیَّقُ عَلَیْہِ قَبْرُہُ حَتَّی تَخْتَلِفَ فِیہِ أَضْلَاعُہُ ثُمَّ یُقَیَّضُ لَہُ أَعْمَی وَاَصَمُّ مَعَہُ مِرْزَبَّۃٌ مِنْ حَدِیدٍ لَوْ ضُرِبَ بِہَا جَبَلٌ لَصَارَ تُرَابًا فَیَضْرِبُہُ بِہَا ضَرْبَۃً یَسْمَعُہَا مَا بَیْنَ الْمَشْرِقِ وَالْمَغْرِبِ إِلَّا الثَّقَلَیْنِ فَیَصِیرُ تُرَابًا ثُمَّ یُعَادُ فِیہِ الرُّوحُ۔\nحدیث2:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا اُقْبِرَ( ) الْمَیِّتُْ أَتَاہُ مَلَکَانِ أَسْوَدَانِ أَزْرَقَانِ یُقَالُ لِأَحَدِہِمَا الْمُنْکَرُ وَلِلْآخَرِ النَّکِیرُ فَیَقُولَانِ مَا کُنْتَ تَقُولُ فِی ہَذَا الرَّجُلِ فَیَقُولُ ہُوَ عَبْدُ اللّٰہ وَرَسُولُہُ أَشْہَدُ أَنْ لَا إِلَہَ إِلَّا اللّٰہ وَأَنَّ مُحَمَّدًا عَبْدُہُ وَرَسُولُہُ فَیَقُولَانِ قَدْ کُنَّا نَعْلَمُ أَنَّکَ تَقُولُ ہَذَا ثُمَّ یُفْتَحُ لَہُ فِی قَبْرِہِ سَبْعُونَ ذِرَاعًا فِی سَبْعِینَ ثُمَّ یُنَوَّرُ لَہُ فِیہِ ثُمَّ یُقَالُ لَہُ نَمْ فَیَقُولُ أَرْجِعُ إِلَی أَہْلِی فَأُخْبِرُہُمْ فَیَقُولَانِ نَمْ کَنَوْمَۃِ الْعَرُوسِ الَّذِی لَا یُوقِظُہُ إِلَّا أَحَبُّ أَہْلِہِ إِلَیْہِ حَتَّی یَبْعَثَہُ اللّٰہ مِنْ مَضْجَعِہِ ذَلِکَ وَإِنْ کَانَ مُنَافِقًا قَالَ سَمِعْتُ النَّاسَ یَقُولُونَ قَوْلًا فَقُلْتُ مِثْلَہُ لَا أَدْرِی فَیَقُولَانِ قَدْ کُنَّا نَعْلَمُ أَنَّکَ تَقُولُ ذَلِکَ فَیُقَالُ لِلْأَرْضِ الْتَءِمِی عَلَیْہِ فَتَلْتَءِمُ عَلَیْہِ فَتَخْتَلِفُ أَضْلَاعُہُ فَلَا یَزَالُ فِیہَا مُعَذَّبًا حَتَّی یَبْعَثَہُ اللّٰہ مِنْ مَضْجَعِہِ۔ \nحدیث3: \nعَنْ أَبِی سَعِیْدنِ الْخُدْرِی قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ لَیُسَلَّطُ عَلَی الْکَافِرِ فِی قَبْرِہِ تِسْعَۃٌ وَتِسْعُونَ تِنِّیناً تَنْہَسُہُ وَتَلْدَغُہُ حَتَّی تَقُومَ السَّاعَۃُ، وَلَوْ أَنَّ تِنِّیناً مِنْہَا نَفَخَ فِی الأَرْضِ مَا أَنْبَتَتْ خَضْرَاء۔", "urdu": "¥ترجمہ حدیث1:\nحضرت براء بن عازب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ مردے کے پاس دو فرشتے آتے ہیں تو اس کو بٹھا کر پوچھتے ہیں کہ تیرا رب کون ہے ؟ تو مردہ کہتا ہے کہ میرا رب اللّٰہ ہے ۔ تو فرشتے کہتے ہیں تیرا دین کیا ہے ؟وہ کہتا ہے میرا دین اسلام ہے پھر فرشتے پوچھتے ہیں کون ہیں یہ جو تم میں مبعوث فرمائے گئے تھے ؟ تو مردہ کہتا ہے کہ وہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم ہیں۔ پھر فرشتے دریافت کرتے ہیں کہ تمہیں کس نے بتایا ( کہ وہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم ہیں) تو مردہ کہتا ہے میں نے خدائے تعالیٰ کی کتاب کو پڑھا تو ان پر ایمان لایا اور ان کی تصدیق کی ( حضور علیہ الصلاۃ والسلام نے فرمایا) تو خدائے تعالیٰ کے اس قول{ یُثَبِّتُ اللّٰہ الَّذِینَ آمَنُوْابِالْقَوْلِ الثَّابِتِ فِی الْحَیوۃِ الدُّنْیَا وَفِی الْاٰخِرَۃِ }( ) کا یہی مطلب ہے (یعنی مومن خدائے تعالیٰ کے فضل سے فرشتوں کو جواب دینے میں ثابت رہتا ہے ) حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا پھر ایک پکار نے والا آسمان سے پکارکر کہتا ہے کہ میرے بندے نے سچ کہا تو اس کے لیے جنت کا بچھونا بچھاؤ اور اس کو جنت کا کپڑا پہناؤ او راس کے لیے جنت کی طرف ایک دروازہ کھول دو۔ تو دروازہ کھول دیا جاتا ہے حضور صلی اللّٰہ علیہ و سلم نے فرمایا تو اس کے پاس جنت کی ہوا اور خوشبو آتی ہے ۔ اور حدِّ نگاہ تک اس کی قبر کشادہ کردی جاتی ہے ۔ ( یہ حال تو مومن کا ہے ) اور اب رہ گیا کافر تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے اس کی موت کا ذکر کیا اور فرمایا کہ اس کی روح اس کے جسم میں واپس کی جاتی ہے اور اس کے پاس دو فرشتے آتے ہیں تو اسے بٹھا کر پوچھتے ہیں کہ تیرا رب کون ہے ؟توکافر مردہ کہتاہے ہاہ ہاہ میں نہیں جانتا۔ پھر فرشتے دریافت کرتے ہیں تیرا دین کیا ہے ؟ وہ کہتا ہے ہاہ ہاہ میں نہیں جانتا ، پھر فرشتے پوچھتے ہیں کون ہیں جو تم میں مبعوث کیے گئے تھے تو وہ کہتا ہے ہا ہ ہاہ میں نہیں جانتا۔ تو آسمان سے ایک ندا دینے والا پکار کر کہتا ہے کہ وہ جھوٹا ہے اس کے لیے آگ کا بچھونا بچھاؤ، اور آگ کا کپڑا پہناؤ اور اس کے لیے دوزخ کی طرف سے ایک دروازہ کھول دو۔ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا تو اس کے پاس جہنم کی گرمی اور لپٹ آتی ہے اور کافر کی قبر اس پر تنگ کی جاتی ہے یہاں تک کہ اس کی پسلیاں اِدھر کی اُدھر ہوجاتی ہیں پھر اس پر ایک اندھا اور بہرا فرشتہ مقرر کیا جاتا ہے جس کے پاس لوہے کا ایک گرز ہوتا ہے کہ اگر اس کو پہاڑ پر مار ا جائے تو وہ مٹی ہوجائے ۔ فرشتہ اس گرز سے کافر کو ایسا مارتا ہے کہ اس کی آواز مشرق سے مغرب تک تمام مخلوقات سنتی ہے مگر انسان اور جن نہیں سنتے ہیں تو وہ مٹی ہوجاتا ہے پھر اس کے اندر روح لوٹائی جاتی ہے ۔ (احمد، ابوداود، مشکوۃ)\n¥ترجمہ حدیث2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جب قبر میں مردہ کو رکھ دیا جاتا ہے تو اس کے پاس دو کالے فرشتے نیلی آنکھوں والے آتے ہیں جن میں سے ایک کا نام منکر ( )ہے اور دوسر ے کا نکیر، دونوں فرشتے اس مردہ سے پوچھتے ہیں کہ تو اس ذات ِ گرامی کے بارے میں کیا کہتا تھا تو مر دہ کہتا ہے کہ وہ خدائے تعالیٰ کے بندے اور اس کے رسول ہیں۔ میں گواہی دیتاہوں کہ اللّٰہ تعالیٰ کے سوا کوئی معبود نہیں۔ اور گواہی دیتا ہوں کہ محمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) خدائے تعالیٰ کے بندے اور اس کے رسول ہیں ( یہ سن کر ) وہ دونوں فرشتے کہتے ہیں کہ ہم پہلے سے جانتے تھے کہ تو یہی کہے گا۔ پھر اس کی قبر ستر(۷۰) گز لمبی اور ستر(۷۰) گز چوڑی کردی جاتی ہے اس کے بعد قبر میں روشنی کی جاتی ہے پھر اس سے کہا جاتا ہے کہ ’’سوجا‘‘ تو مردہ کہتا ہے کہ میں اپنے اہل و عیال میں جا کر اس حال سے ان کو آگاہ کردوں۔ تو فرشتے کہتے ہیں۔ ’’سو جیسے دولہا سوتا ہے ‘‘ جس کو صرف وہی شخص جگا سکتا ہے کہ جو اس کے اہل میں سب سے زیادہ محبوب ہو (تو وہ سو جاتا ہے ) یہاں تک کہ خدائے تعالیٰ اسے (قیامت کے دن) اس کی قبر سے اٹھائے گا۔ (یہ حال تو مومن کا ہے ) اور اگر مردہ منافق ہوتا ہے تو فرشتوں کے جواب میں کہتا ہے کہ میں نے لوگوںکو جو کہتے ہوئے سنا تھا اسی کے مثل میں بھی کہتا تھا۔ خود میں کچھ جانتا نہیں تھا تو فرشتے کہتے ہیں کہ ہم لوگ جانتے تھے کہ تو ایسا ہی کہے گا۔ پھر زمین کو حکم دیا جائے گاکہ اس کو دبا تو وہ دبائے گی یہاں تک کہ اس کی پسلیاں ادھر کی ادھر ہوجائیں گی تو اسی طرح وہ ہمیشہ عذاب میں مبتلا رہے گا۔ یہاں تک کہ خدائے تعالیٰ اس کو اس جگہ سے اٹھائے ۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث3:\nحضرت ابوسعید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ کافر پر اس کی قبر میں ننانوے (۹۹) اژدھے مقرر کیے جاتے ہیں جو اس کو قیامت تک کاٹتے اور ڈستے رہیں گے ان اژدھوں میں کا کوئی ایک اگر زمین پر پھنکار دے تو زمین سبزہ پیدا کرنے سے محروم ہوجائے ۔ (دارمی ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Baraa Bin Aazib Radiyallahu Anhu se riwayat hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke murday ke paas do farishtay aatay hain to us ko bitha kar poochtay hain ke tera Rabb kaun hai? To murda kehta hai ke mera Rabb Allah hai. To farishtay kehtay hain tera deen kya hai? Woh kehta hai mera deen Islam hai phir farishtay poochtay hain kaun hain yeh jo tum mein mab'oos farmaye gaye thay? To murda kehta hai ke woh Rasoolullah Sallallahu Alayhi wa Sallam hain. Phir farishtay daryaft kartay hain ke tumhain kis ne bataya (ke woh Rasoolullah Sallallahu Alayhi wa Sallam hain) to murda kehta hai main ne Khuda-e-Ta'ala ki Kitaab ko parha to un par Imaan laya aur un ki tasdeeq ki (Huzoor Sallallahu Alayhi wa Sallam ne farmaya) to Khuda-e-Ta'ala ke is qaul {Yusabbitullahu-llazeena aamanoo bil-qaul-is-saabiti fil-hayatid-dunya wa fil-aakhirah} ka yahi matlab hai (ya'ni momin Khuda-e-Ta'ala ke fazl se farishton ko Jawab denay mein saabit rehta hai). Huzoor Sallallahu Alayhi wa Sallam ne farmaya phir ek pukar nay wala aasman se pukar kar kehta hai ke meray banday ne sach kaha to us ke liye Jannat ka bichhona bichhao aur us ko Jannat ka kapra pehnao aur us ke liye Jannat ki taraf ek darwaza khol do. To darwaza khol diya jata hai. Huzoor Sallallahu Alayhi wa Sallam ne farmaya to us ke paas Jannat ki hawa aur khushboo aati hai. Aur hadd-e-nigah tak us ki Qabr kushada kar di jati hai. (Yeh haal to momin ka hai) aur ab reh gaya Kaafir to Huzoor Sallallahu Alayhi wa Sallam ne us ki maut ka zikr kiya aur farmaya ke us ki rooh us ke jism mein wapas ki jati hai aur us ke paas do farishtay aatay hain to usay bitha kar poochtay hain ke tera Rabb kaun hai? To Kaafir murda kehta hai haah haah main nahi janta. Phir farishtay daryaft kartay hain tera deen kya hai? Woh kehta hai haah haah main nahi janta, phir farishtay poochtay hain kaun hain jo tum mein mab'oos kiye gaye thay to woh kehta hai haah haah main nahi janta. To aasman se ek nida denay wala pukar kar kehta hai ke woh jhoota hai us ke liye aag ka bichhona bichhao, aur aag ka kapra pehnao aur us ke liye dozakh ki taraf se ek darwaza khol do. Huzoor Sallallahu Alayhi wa Sallam ne farmaya to us ke paas Jahannam ki garmi aur lipat aati hai aur Kaafir ki Qabr us par tang ki jati hai yahan tak ke us ki pasliyan idhar ki udhar ho jati hain phir us par ek andha aur behra farishta muqarrar kiya jata hai jis ke paas lohay ka ek gurz hota hai ke agar us ko pahar par mara jaye to woh mitti ho jaye. Farishta us gurz se Kaafir ko aisa marta hai ke us ki aawaz mashriq se Maghrib tak tamam makhlooqat sunti hai magar insaan aur jin nahi suntay hain to woh mitti ho jata hai phir us ke andar rooh lautayi jati hai. (Ahmad, Abu Dawood, Mishkaat) Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jab Qabr mein murda ko rakh diya jata hai to us ke paas do kaalay farishtay neeli aankhon walay aatay hain jin mein se ek ka naam Munkar hai aur dusray ka Nakeer, dono farishtay us murda se poochtay hain ke tu is zaat-e-girami ke baray mein kya kehta tha to murda kehta hai ke woh Khuda-e-Ta'ala ke banday aur us ke Rasool hain. Main gawah deta hoon ke Allah Ta'ala ke siwa koi mabood nahi. Aur gawah deta hoon ke Muhammad Sallallahu Alayhi wa Sallam Khuda-e-Ta'ala ke banday aur us ke Rasool hain (yeh sun kar) woh dono farishtay kehtay hain ke hum pehlay se jantay thay ke tu yahi kehay ga. Phir us ki Qabr sattar (70) gaz lambi aur sattar (70) gaz chauri kar di jati hai us ke ba'ad Qabr mein roshni ki jati hai phir us se kaha jata hai ke 'so ja' to murda kehta hai ke main apnay ahl-o-ayaal mein ja kar is haal se un ko aagah kar doon. To farishtay kehtay hain: 'So jaise dulha sota hai' jis ko sirf wahi shakhs jaga sakta hai ke jo us ke ahl mein sab se zyada mehboob ho (to woh so jata hai) yahan tak ke Khuda-e-Ta'ala usay (Qayamat ke din) us ki Qabr se uthayay ga. (Yeh haal to momin ka hai) aur agar murda munafiq hota hai to farishton ke Jawab mein kehta hai ke main ne logon ko jo kehtay huay suna tha isi ke misl main bhi kehta tha. Khud main kuch janta nahi tha to farishtay kehtay hain ke hum log jantay thay ke tu aisa hi kehay ga. Phir zameen ko Hukm diya jaye ga ke us ko daba to woh dabaye gi yahan tak ke us ki pasliyan idhar ki udhar ho jayen gi to isi tarah woh hamesha azaab mein mubtala rahay ga. Yahan tak ke Khuda-e-Ta'ala us ko us jagah se uthayay. (Tirmidhi, Mishkaat) Tarjuma Hadees 3: Hazrat Abu Sa'eed Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Kaafir par us ki Qabr mein ninnanway (99) azdhay muqarrar kiye jatay hain jo us ko Qayamat tak kaat-tay aur dastay rahen ge un azdhon mein ka koi ek agar zameen par phunkar day to zameen sabza paida karnay se mehroom ho jaye. (Darimi, Mishkaat)", "explanation": "¥شرح حدیث1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ:\n اشارت بہذا بآں حضرت صلی اللّٰہ تعالیعلیہ وسلم یا از جہت شہرت امر وحضور او ست در اذہان ما اگرچہ غائب ، ست یا باحضار ذات شریف وے در عیاں وبایں طریق کہ در قبر مثالے از حضرت وے صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ حاضر می ساختہ باشند تا بمشاہدہ جمال جاں افزائے او عقدہ اشکال کہ درکار افتادہ کشادہ شود و ظلمت فراق بنور لقائے دل کشائے او روشن گردد ۔ (1)\n یعنی ھذا ’’ یہ ‘‘ کے ساتھ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو اشارہ کرنا یا تو اس وجہ سے ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی ذات مقدس مشہور ہے اور حضور کا تصور ہمارے دلوں میں موجود ہے اگرچہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم ہمارے سامنے رونق افروز نہیں۔ اور یا توا س وجہ سے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی ذات گرامی کھلم کھلا پیش کی جاتی ہے اس طرح کہ قبر میں حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی شبیہ مبارک لائی جاتی ہے تاکہ ان کے جمالِ جان افزاء سے ا ن مشکلات کی گرہیں کہ جواب دینے میں پیش آئیں کھل جائیں اور فراق کی تاریکی ان کی دل کشا ملاقات کے نور سے روشن ہوجائے ۔ (اشعۃ اللمعات، جلد اول، ص ۱۱۵)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الإیمان ، باب إثبات عذاب القبر ، الفصل الأول ، ج ۱، ص :۱۲۴.\nحضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ ارشاد فرماتے ہیں کہ:\n’’ ملائکہ و ماروکژدم گزیدن ایشاں کہ درا حادیث واقع شدہ است ہمہ بحکم واقع موجود اند نہ محض مثال و خیال و آنکہ مانہ بنییم و نہ دریا بیم در وجودآن زیاں نہ داردزیر ا کہ عالم ملکوت رابچشم سر نہ تواں دید آنراچشم دیگر ست ۔ ‘‘(1)\n یعنی فرشتوں اور سانپوں اور بچھوؤں کا مردوں کو تکلیف پہنچانا جیسا کہ احادیث کریمہ میں بیان کیا گیا ہے سب حقیقت میں واقع اور موجود ہیں محض مثال و خیال نہیں۔ اور ہمارا نہ دیکھنا اور معلوم نہ کرپانا ان کے وجود کو مضر نہیں اس لیے کہ عالم ملکوت کو سر کی آنکھوں سے نہیں دیکھ سکتے اس کے لیے ایک دوسری آنکھ چاہیے ۔ (اشعۃ اللمعات جلد اول ص۱۱۴)\n اور حضرت مُلاّ علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی فرماتے ہیں:\n ’’ إِنْ قِیلَ نَحنُ نُشاھِدُ المیِّتَ عَلی حَالِہِ فَکَیفَ یُسئالُ وَیُقعَدُ وَیُضرَبُ وَلَا یَظْھَرُ أَثَرٌ ؟ فَالْجَوَابُ أَنَّہُ مُمْکنٌ وَلہ نَظیرٌ فِی الشَّاھدِ وَھُوَ النَّاءِم فَإِنَّہ یَجِدُ لَذَّۃً وَأَلمًا یحسّہٗ وَلَا نحسّہٗ وَکذَا یَجِدُ الیقظان لذّۃً وألمًا یَسْمعہُ وَیتفکَّر فِیہِ وَلَا یشَاھِد ذَلکَ جَلِیْسہ وَکَذَلک کَانَ جبریل یَأتِی النَّبِیَّ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ فَیوحِيْ بالقرآن المجید وَلَا یَرَاہُ أَصْحَابُہُ ‘‘(2)\nیعنی اگر اعتراض کیا جائے کہ ہم لوگ مردہ کو اس کے حال پر دیکھتے ہیں پھر کیونکر بٹھا کر اس سے پوچھا جاتا ہے اور مارا جاتا ہے حالانکہ کوئی بات نظر نہیں آتی۔ تو جواب یہ ہے کہ ایسا ممکن ہے ( کہ مردہ کے ساتھ سب کاروائیاں ہوں اور ہمیں نظر نہ آئیں) اور اس کی نظیر مشاہدہ کی دنیا میں موجود ہے چنانچہ سونے والا آدمی نیند میں راحت و رنج (کی چیزوں کو) دیکھ کر احساس کرتا ہے اور ہم ( اس کے پاس رہ کر) نہیں معلوم کر پاتے ( کہ سونے والے پر کیا واقعہ گزررہا ہے ) اور اسی طرح بیدار آدمی اچھی یا بری خبر سن کر اور سوچ کر لذت یا تکلیف محسوس کرتا ہے اور پاس بیٹھے ہوئے آدمی کو کچھ پتہ نہیں چلتا ، اور اسی طرح حضرت جبریل علیہ الصلاۃ والسلام قرآن مجید کی وحی لے کر حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے پاس حاضر ہوتے تھے ( خود حضور اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم تو حضرت جبریل علیہ الصلاۃ والسلام کو دیکھتے تھے ۔ )مگر صحابہ کرام ان کو نہیں دیکھ پاتے تھے ۔ (مرقاۃ شرح مشکوۃ، جلد اول، ص ۱۶۳)\n¥انتباہ :\n (۱)… مرنے کے بعد مسلمانوں کی روحیں حسب مراتب مختلف مقاموں میں رہتی ہیں۔ بعض کی قبر پر، بعض کی چاہ زمزم میں، بعض کی آسمان و زمین کے درمیان ، بعض کی پہلے دوسرے ساتویں آسمان تک اور بعض کی آسمانوں سے بھی اوپر اور بعض کی روحیں زیر عرش قندیلوں میں اور بعض کی اعلیٰ علیین میں ۔ اور کافروں کی خبیث روحیں بعض کی ان کے مرگھٹ یا قبر پر، بعض کی چاہ برہوت میں کہ یمن میں ایک نالا ہے ، بعض کی پہلی دوسری ساتویں زمین تک اور بعض کی اس کے بھی نیچے سجین میں مگر کہیں بھی ہوں اپنے جسم سے ان کا تعلق باقی رہتا ہے ۔ (3) (بہار شریعت)\n (۲)…قبر میں منکر نکیر کا سوال حق ہے ۔ اس کا انکار کرنے والا گمراہ بدمذہب ہے ۔ حضرت امام اعظم ابوحنیفہ رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فقہ اکبر مع شرح للملا علی قاری ص:۱۲۱ میں فرماتے ہیں ’’ سُوَالُ مُنْکَرٍوَ نَکِیرفِی القبرحقّ ‘‘ یعنی قبر میں منکر نکیر کا سوال حق ہے ۔ (4)\n (۳)…مردہ اگر قبر میں دفن نہ کیا جائے تو جہاں کہیں ہوگا وہیں سوالات ہوں گے اور وہیں ثواب یا عذاب پائے گا۔ یہاں تک کہ اگر کسی جانور نے کھالیا تو اس کے پیٹ میں سوال ہوں گے اور وہیں ثواب یا عذاب پائے گا۔\n حضرت ملّا علی قاری علیہ ر حمۃ اللّٰہ الباری فرماتے ہیں : ’’ السُّوَالُ یَشْمَلُ الأَموَاتِ جَمِیْعَھَا حَتَّی أَنَّ مَنْ مَاتَ وَأَکَلتْہُ السِّبَا عُ ‘‘ یعنی سوال سب مردوں سے کیا جائے گا۔ یہاں تک کہ مرنے کے بعد درندے جانور کھا لیں تو بھی سوال کیا جائے گا۔ (5) (مرقاۃ جلد اول ص۱۶۸)\n (۴)… عذابِ قبر اور تنعیم قبر حق ہے اس کا انکار کرنے والا گمراہ ہے ۔ اہلِ سنت و جماعت سے خارج ہے ۔ حضرت مّلا علی قاری علیہ ر حمۃ اللّٰہ الباری شرح فقہ اکبرص:۱۲۲ میں فرماتے ہیں ’’ عَذَابُہٗ ( أیِ الْقَبْرِ ) حَقٌّ کَاءِنٌ لِکُفَّارٍ کُلِّھِمْ أَجْمَعِیْنَ وَلِبَعْضِ الْمُسْلِمِیْنَ وَکَذَا تَنْعِیْمُ بَعضِ المُؤمِنِینَ حَقٌّ ‘‘([6])\n یعنی قبرکا عذاب حق ہے جو سب کافروں اور بعض (گنہگار) مسلمانوں پر ہوگا اور ایسے ہی تنعیم قبر بعض مومنین کے لیے حق ہے ۔ \n (۵)…جسم اگرچہ گل جائے جل جائے یا خاک ہوجائے مگر اس کے اجزائے اصلیہ قیامت تک باقی رہیں گے اور وہی مَوْرِدِ عذاب و ثواب ہوں گے ۔ وہ اجزاء ریڑھ کی ہڈی میں ہوتے ہیں اور اس قدر باریک ہوتے ہیں کہ نہ کسی خرد بین سے نظر آتے ہیں ، نہ آگ انہیں جلاتی ہے اور نہ زمین انہیں گلا سکتی ہے ۔ یہی جسم کے تخم ہیں خدائے تعالیٰ قیامت کے دن مردہ کے منتشر اجزاء کو پہلی ہیئت پر لا کر اِنہیں اجزائے اصلیہ پر کہ محفوظ ہیں ترکیب دے گا اور ہر روح کو اسی جسم سابق میں بھیجے گا۔ ([7]) (بہار شریعت)\n (۶)…انبیائے عِظَام علیہم الصلوۃ والسلام اولیائے کِرام علمائے اَعلام، شہدائے اسلام، حفاظ قر آن جو قرآن مجید پر عمل کرتے ہوں اور جو منصب محبت پر فائز ہیں اور وہ جسم جس نے کبھی اللّٰہ تعالیٰ کی معصیت نہ کی ہو۔ اور وہ لوگ کہ اپنے اوقات درود شر یف میں مستغرق رکھتے ہیں ان کے بدن کو مٹی نہیں کھاسکتی ، جو شخص انبیائے کرام علیہم الصلوۃ والسلام کی شان میں یہ خبیث کلمے کہے کہ ’’ مرکے مٹی میں مل گئے ‘‘ تو وہ گمراہ ، بددین خبیث اور مرتکب توہین ہے ۔ ([8]) (بہار شریعت ، جلد اول ص ۲۹)\n------------------\n[1] اشعۃ اللمعات ، کتاب الإیمان ، باب إثبات عذاب القبر ، ج ۱، ص ۱۲۳.\n[2] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الإیمان ، الحدیث : ۱۲۵، ج ۱، ص ۳۳۷.\n[3] ’’بہارِ شریعت‘‘، ج ۱، ص ۱۰۱.\n[4] ’’ شرح الفقہ الأکبر ‘‘، باب إعادۃ الروح إلی المیت فی قبرہ حق ، ص ۱۰۰.\n[5] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الإیمان ، الحدیث : ۱۳۰، ج ۱، ص ۳۴۷.\n[6] ’’ شرح الفقہ الأکبر ‘‘، باب إعادۃ الروح إلی المیت فی قبرہ حق ، ص ۱۰۱.\n[7] ’’بہارِ شریعت‘‘، ج۱، ص ۱۱۲.\n[8] ’’بہار شر یعت‘‘، ج۱، ص ۱۱۴."}, {"id": 7776, "bookId": 14, "volNo": "1", "hadithNo": 8, "chapter": "قیامت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\nعَنْ أَنَسٍ رَضِیَ اللّٰہ عَنْہُ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ إِنَّ مِنْ أَشْرَاطِ السَّاعَۃِ أَنْ یُرْفَعَ الْعِلْمُ وَیَکْثُرَ الْجَہْلُ وَیَکْثُرَ الزِّنَا وَیَکْثُرَ شُرْبُ الْخَمْرِ وَیَقِلَّ الرِّجَالُ وَیَکْثُرَ النِّسَاءُ حَتَّی یَکُونَ لِخَمْسِینَ امْرَأَۃَنِ الْقَیِّمُ الْوَاحِدُ۔\nحدیث2:\nعَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا اتّخِذَ الْفَیْءُ دُوَلًا، وَالْاَمَانَۃُ مَغْنَماً، وَالزَّکَاۃُ مَغْرَماً، وَتُعُلِّمَ لِغَیْرِ الدِّیْنِ، وَأَطَاعَ الرَّجُلُ اِمْرَاَتَہُ، وَعَقَّ أُمَّہُ، وَأَدْنَی صَدِیْقَہُ وَأَقْصَی أَبَاہُ، وَظَھَرَتِ الْأَصْوَاتُ فِی الْمَسَاجِدِ، وَسَادَ الْقَبِیْلَۃ فَاسِقُھُمْ، وَکَانَ زَعِیْمُ الْقَوْمِ أَرْذَلَھُمْ، وَأُکْرِمَ الرَّجُلُ مَخَافَۃَ شَرِّہِ، وَظَھَرَتِ الْقَیْنَاتُ وَالْمَعَازِفُ، وَشُرِبَتِ الْخُمُوْرُ، وَلَعَنَ آخِرُ ھَذِہِ الْأُمَّۃِ أَوَّلَھَا فَارتَقِبُوْا عَنْدَ ذَلِکَ رِیْحاً حَمْرَاءَ وَزَلْزَلَۃً وَخَسْفاً وَّمَسْخاً وَقَذْفاً، وَآیَاتٍ تَتَابَعُ کَنِظَامٍ بَالٍ قُطِعَ سِلْکُہُ فَتَتَابَعُ۔ \nحدیث3:\n عَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تَقُومُ السَّاعَۃُ حَتَّی یَتَقَارَبَ الزَّمَانُ فَتَکُونُ السَّنَۃُ کَالشَّہْرِ وَالشَّہْرُ کَالْجُمُعَۃِ وَتَکُونُ الْجُمُعَۃُ کَالْیَوْمِ وَیَکُونُ الْیَوْمُ کَالسَّاعَۃِ وَتَکُونُ السَّاعَۃُ کَالضَّرَمَۃِ بِالنَّارِ۔ \nحدیث4:\nعَنْ حُذَیْفَۃَ بْنِ أَسِیدٍ الْغِفَارِیِّ قَالَ اطَّلَعَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَلَیْنَا وَنَحْنُ نَتَذَاکَرُ فَقَالَ مَا تَذْکُرُونَ قَالُوا نَذْکُرُ السَّاعَۃَ قَالَ إِنَّہَا لَنْ تَقُومَ حَتَّی تَرَوْا قَبْلَہَا عَشْرَ آیَاتٍ فَذَکَرَ الدُّخَانَ وَالدَّجَّالَ وَالدَّابَّۃَ وَطُلُوعَ الشَّمْسِ مِنْ مَغْرِبِہَا وَنُزُولَ عِیسَی ابْنِ مَرْیَمَ وَیَأَجُوجَ وَمَأْجُوجَ وَثَلَاثَۃَ خُسُوفٍ خَسْفٌ بِالْمَشْرِقِ وَخَسْفٌ بِالْمَغْرِبِ وَخَسْفٌ بِجَزِیرَۃِ الْعَرَبِ وَآخِرُ ذَلِکَ نَارٌ تَخْرُجُ مِنْ الْیَمَنِ تَطْرُدُ النَّاسَ إِلَی مَحْشَرِہِمْ وَفِی رِوَایَۃٍ نَارٌ تَخْرُجُ مِنْ قَعْرِ عَدَنَ تَسُوقُ النَّاسَ إِلَی الْمَحْشَرِ وَفِی رِوَایَۃٍ فِی الْعَاشِرَۃِ وَرِیْحٌ تَلْقِی النَّاسَ فِی الْبَحْرِ۔\nحدیث5:\nعَنْ أَبِیْ ھُرَیْرَۃ( ) قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الدَّجَّالُ أَعْوَرُ الْعَیْنِ الْیُسْرَی جُفَالُ الشَّعَرِ مَعَہُ جَنَّتُہُ وَنَارُہُ فَنَارُہُ جَنَّۃٌ وجَنَّتُہُ نَارٌ۔ \nحدیث6:\nعَنْ أَبِی سَعِیدِنِ الْخُدْرِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اَلْمَھْدِیُّ مِنِّیْ أَجْلَی الْجَبْھَۃِ أَقْنَی الْاَنْفِ یَمْلَأُ الْأَرْضَ قِسْطاً وَعَدْلًا کَمَا مُلِءَتْ ظُلْمًا وَجَوْرًا یَمْلِکُ سَبْعَ سِنِیْنَ۔ \nحدیث7:\nعَنْ أَنَسٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَا تَقُومُ السَّاعَۃُ حَتَّی لَا یُقَالَ فِی الْأَرْضِ اللّٰہ اللّٰہ۔", "urdu": "¥ترجمہ حدیث1:\n حضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کو فرماتے ہوئے سنا ہے کہ قیامت کی نشانیاں یہ ہیں کہ علم اُٹھالیا جائے گا۔ جہالت زیادہ ہوگی، زنا کاری اور شراب خوری کی کثرت ہوگی۔ مردوں کی تعداد کم ہوگی۔ عورتوں کی تعداد بڑھ جائے گی۔ یہاں تک کہ ایک مرد کی سرپرستی میں پچاس عورتیں ہوں گی۔ \n¥ترجمہ حدیث2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جب غنیمت (صرف امرا کی) دولت ٹھہرائی جائے ، امانت کو مالِ غنیمت اور زکوۃ کو تاوان سمجھا جائے ۔ جب کہ علم کو دین کے لیے نہ حاصل کیا جائے ۔ مرد اپنی عورت کی اطاعت اور ماں کی نافرمانی کرے گا جب کہ آدمی اپنے دوست سے قریب ہوگا اور اپنے باپ کودور کرے گا۔ جب مسجدوں میں شور مچایا جائے گا ، قوم کا سردار ان کا فاسق ہوگا۔ اور جب قوم کا لیڈر ان میں کا کمینہ آدمی ہوگا اور آدمی کی عزت ان کی برائیوں سے بچنے کے لیے کی جائے گی۔ جب گانے والی عورتیں اور(قسم قسم)کے باجے ظاہر ہوں گے (علانیہ) شراب پی جائے گی اور جب امت کے پچھلے لوگ اگلوں کو برا کہیں گے تو اس وقت تم ان چیزوں کا انتظار کرنا۔ سرخ آندھی، زلزلہ ، زمین میں دھنسنا، صورتیں مسخ کرنا، پتھروںکا برسنا اور ( قیامت کی بڑی بڑی ) نشانیوں کا پے درپے ظاہر ہونا کہ گویا وہ موتیوں کی ٹوٹی ہوئی لڑی ہے جس سے لگاتا ر موتی گررہے ہیں۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ قیامت قائم نہ ہوگی جب تک کہ زمانہ ایک دوسرے کے قریب نہ ہوگا۔ (یعنی زمانہ کے حصہ جلد جلد گزر نے لگیں گے ) سال مہینہ کے برابر ہوجائے گا۔ مہینہ ہفتہ کے برابر۔ ہفتہ ایک دن کے برابر اور اس وقت ایک دن ایک ساعت کے برابر ہوگا اور ساعت آگ کا ایک شعلہ ( اٹھ کر ختم ہوجانے ) کے برابرہوگی۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث4:\nحضرت حذیفہ بن اسید غفار ی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم لوگوں کی گفتگو پر حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم مطلع ہوئے تو فرمایا تم لوگ کیا بات کررہے ہو؟ لوگوں نے کہا کہ ہم قیامت کا ذکر کررہے ہیں۔ حضور صلی اللّٰہ علیہ وآلہ وسلم نے فرمایا کہ اس وقت تک قیامت نہ آئے گی جب تک کہ تم ان نشانیوں کو نہ دیکھ لو گے ۔ پھر ان نشانیوں کا ذکر کیا اور فرمایا دھواں، دجال ، دابۃ الار ض ۔ پچھم سے سورج کا نکلنا، عیسی ابن مریم کا نازل ہونا۔ یاجوج و ماجوج، تین مقامات پر زمین کا دھنسنا ، ایک مشرق میں دوسرے مغرب میں اور تیسرے جزیرئہ عرب میں۔ اور ان کا دسواں وہ آگ ہے جو یمن سے نکلے گی اور لوگوں کو گھیر کر محشر یعنی ملک شام کی طرف لے جائے گی۔ اور ایک روایت میں ہے کہ وہ آگ عدن کے علاقے سے نکلے گی اور لوگوں کو گھیر کر محشر کی طرف لے جائے گی اور ایک روایت میں دسویں نشانی ایک ہوا بیان کی گئی ہے جو لوگوں کو دریا میں پھینک دے گی۔ (مسلم، مشکوۃ) \n¥ترجمہ حدیث5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ دجال بائیں آنکھ کا کانا ہوگا بہت کثرت سے بال ہوں گے ۔ اس کے ساتھ جنت اور دوزخ ہوگی۔ اس کی جہنم (حقیقت میں) \nجنت ہوگی اور جنت (حقیقت میں ) جہنم ہوگی۔ (مسلم ، مشکوۃ)\n¥ترجمہ حدیث6:\nحضرت ابوسعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ مہدی میری اولادمیں سے ہے ۔ روشن و کشادہ پیشانی، بلند ناک، وہ زمین کو اس طرح عدل و انصاف سے بھردے گا جس طرح پہلے ظلم و ستم سے بھری تھی۔ اور وہ سات برس تک زمین کا مالک رہے گا۔ (ابو داود، مشکوۃ)\n¥ترجمہ حدیث7:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ قیامت اس وقت آئے گی جب زمین پر کوئی اللّٰہ اللّٰہ کہنے والا نہیں رہ جائے گا۔ (ابو داود، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne kaha ke main ne Rasool-e-Kareem Sallallahu Alayhi wa Sallam ko farmatay huay suna hai ke Qayamat ki nishaniyan yeh hain ke Ilm utha liya jaye ga. Jahalat zyada hogi, zina kaari aur sharab khori ki kasrat hogi. Mardon ki tadaad kam hogi. Auraton ki tadaad barh jaye gi. Yahan tak ke ek mard ki sarparasti mein pachaas auratain hongi. Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jab ghanimat (sirf amra ki) daulat thehrayi jaye, amanat ko maal-e-ghanimat aur Zakat ko tawan samjha jaye. Jab ke Ilm ko deen ke liye na hasil kiya jaye. Mard apni aurat ki ita'at aur maa ki nafarmani karay ga jab ke aadmi apnay dost se qareeb hoga aur apnay baap ko door karay ga. Jab Masjidon mein shor machaya jaye ga, qaum ka sardar un ka faasiq hoga. Aur jab qaum ka leader un mein ka kameena aadmi hoga aur aadmi ki izzat un ki buraiyon se bachnay ke liye ki jaye gi. Jab ganay wali auratain aur (qisam qisam) ke bajay zahir hon ge (alaniya) sharab pi jaye gi aur jab ummat ke pichlay log aglon ko bura kehen ge to us waqt tum in cheezon ka intezar karna. Surkh aandhi, zalzala, zameen mein dhansna, sooratain maskh karna, pattharon ka barsna aur (Qayamat ki bari bari) nishaniyon ka pai dar pai zahir hona ke goya woh motiyon ki tooti hui lari hai jis se lagataar moti gir rahay hain. (Tirmidhi, Mishkaat) Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Qayamat qaim na hogi jab tak ke zamana ek dusray ke qareeb na hoga. (Ya'ni zamana ke hissa jald jald guzar nay lagain ge) saal mahina ke barabar ho jaye ga. Mahina hafta ke barabar. Hafta ek din ke barabar aur us waqt ek din ek sa'at ke barabar hoga aur sa'at aag ka ek shola (uth kar khatam ho janay) ke barabar hogi. (Tirmidhi, Mishkaat) Tarjuma Hadees 4: Hazrat Huzaifah Bin Aseed Ghifari Radiyallahu Anhu ne farmaya ke hum logon ki guftagu par Huzoor Sallallahu Alayhi wa Sallam muttala huay to farmaya tum log kya baat kar rahay ho? Logon ne kaha ke hum Qayamat ka zikr kar rahay hain. Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke us waqt tak Qayamat na aayegi jab tak ke tum in nishaniyon ko na dekh lo ge. Phir in nishaniyon ka zikr kiya aur farmaya dhuan, Dajjal, Daabbatul-Arz. Pachham se sooraj ka nikalna, Isa Ibn Maryam ka nazil hona. Ya'jooj-o-Ma'jooj, teen maqamat par zameen ka dhansna, ek mashriq mein dusray Maghrib mein aur teesray Jazeerat-ul-Arab mein. Aur un ka daswan woh aag hai jo Yaman se niklay gi aur logon ko gher kar mahshar ya'ni mulk-e-Shaam ki taraf lay jaye gi. Aur ek riwayat mein hai ke woh aag Adan ke ilaqay se niklay gi aur logon ko gher kar mahshar ki taraf lay jaye gi aur ek riwayat mein daswin nishani ek hawa bayan ki gayi hai jo logon ko darya mein phenk day gi. (Muslim, Mishkaat) Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Dajjal baayen aankh ka kana hoga bohat kasrat se baal hon ge. Us ke saath Jannat aur dozakh hogi. Us ki Jahannam (haqeeqat mein) Jannat hogi aur Jannat (haqeeqat mein) Jahannam hogi. (Muslim, Mishkaat) Tarjuma Hadees 6: Hazrat Abu Sa'eed Khudri Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke Mahdi meri aulaad mein se hai. Roshan-o-kushada peshani, buland naak, woh zameen ko is tarah adl-o-insaf se bhar day ga jis tarah pehlay zulm-o-sitam se bhari thi. Aur woh saat baras tak zameen ka maalik rahay ga. (Abu Dawood, Mishkaat) Tarjuma Hadees 7: Hazrat Anas Radiyallahu Anhu se riwayat hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Qayamat us waqt aayegi jab zameen par koi Allah Allah kehnay wala nahi reh jaye ga. (Abu Dawood, Mishkaat)", "explanation": "¥انتباہ:\n (۱)…قیامت کی چند نشانیاں جو احادیث مذکورہ میں بیان کی گئیں ہیں ان میں سے کچھ ظاہر ہوچکیں اور جو باقی ہیں وہ بھی یقیناً ظاہر ہوں گی۔ دجال کا فتنہ بہت سخت ہوگا ، وہ خدائی کا دعویٰ کرے گا جو اس پر ایمان لائے گا۔ اسے اپنی جنت میں( جو حقیقت میںدوزخ ہوگی) ڈالے گا اور جو انکار کرے گا اسے دوزخ میں ( جو در حقیقت جنت ہوگی) ڈالے گا۔ مردے جِلائے گا زمین سے سبزہ اُگائے گا اور آسمان سے پانی برسائے گا اسی قسم کے بہت شعبدے دکھائے گا جو حقیقت میں سب جادو کے کرشمے ہوں گے ۔ اس کی پیشانی پرک، ف، ر لکھا ہوگا (یعنی کافر) جس کو ہر مسلمان پڑھے گا مگر کافر کو نظر نہ آئے گا۔ (1) (بہار شریعت)\n (۲)…حضرت امام مہدی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے ظاہر ہونے کا مختصر واقعہ یہ ہے کہ رمضان شریف کا مہینہ ہوگا۔ ابدال کعبہ کے طواف میں مصروف ہوں گے اور حضرت امام مہدی بھی وہاں ہوں گے ۔ اولیائے کرام انہیں پہچانیں گے ان سے بیعت کی درخواست کریں گے وہ انکار فرمائیں گے تو غیب سے آواز آئے گی ’’ ھَذَا خَلِیْفَۃُ اللّٰہ الْمَھْدِیُّ فَاسْمَعُوْا لَہُ وَأَطِیْعُوہُ ‘‘ یعنی یہ اللّٰہ کا خلیفہ مہدی ہے اس کی بات سنو اور اس کا حکم مانو۔ سب لوگ ان کے ہاتھ پر بیعت کریں گے ، پھر وہاں سے سب کو اپنے ہمراہ لے کر آپ ملک شام چلے جائیں گے ۔ (2) (بہار شریعت)\n (۳)…حضرت عیسی علیہ السلام جامع مسجد دمشق کے شرقی منارہ پر آسمان سے اُتریں گے ، فجر کی نماز کا وقت ہوگا۔ حضرت امام مہدی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ وہاں موجود ہوںگے ۔ حضرت عیسی علیہ الصلاۃ والسلام انہیں امامت کا حکم دیں گے اور ان کے پیچھے نماز پڑھیں گے ۔ اس وقت دجال لعین ملک شام میں ہوگا۔ حضرت عیسی علیہ الصلاۃ والسلام کی سانس کی خوشبو سے پگھلنا شروع ہوگا۔ وہ بھاگے گا آپ اس کا پیچھا کریں گے اور اس کی پیٹھ میں نیزہ مار کر جہنم میں پہنچا دیں گے پھر بحکم الہٰی تمام مسلمانوں کو لے کر کوہِ طور پر چلے جائیں گے ۔ (3) (۲)(بہار شریعت)\n (۴)…جب حضرت عیسی علیہ الصلاۃ والسلام مسلمانوں کے ساتھ پہاڑ پرمحصور ہوں گے تو یاجوج و ماجوج کا خروج ہوگا۔ یہ دنیا بھر میں فساد اور قتل و غارت کریں گے پھر آسمان کی طرف تیر پھینکیں گے ۔ خدا تعالیٰ کی قدرت سے ان کے تیر اوپر سے خون آلود گریں گے وہ خوش ہوں گے ۔ وہ لوگ اپنی انہی حرکتوں میں مشغول ہوں گے کہ حضرت عیسی علیہ الصلاۃ والسلام ان کی ہلاکت کے لیے دعا کریں گے ۔ خدائے تعالیٰ ان کی گردنوں میں ایک قسم کے کیڑے پیدا کردے گا ایک دم میں وہ سب کے سب مرجائیں گے ۔ اب حضرت عیسی علیہ الصلاۃ والسلام تمام مسلمانوں کے ہمراہ پہاڑ سے اُتریں گے ۔ دنیا بھر میں اس وقت صرف ایک دین۔ دین اسلام اور ایک مذہب ، مذہب اہلِ سنت و جماعت ہوگا۔ چالیس برس تک آپ اقامت فرمائیں گے ۔ نکاح کریں گے اولاد ہوگی اور بعد وفات سرکار دوعالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے روضئہ انور میں دفن ہوں گے ۔ (4) (بہار شریعت)\n (۵)… دابۃ الارض ایک جانور ہوگا جس کے ہاتھ میں حضرت موسی علیہ الصلاۃ والسلام کا عصا اور حضرت سلیمان علیہ الصلاۃ والسلام کی انگوٹھی ہو گی۔ عصا سے ہر مسلمان کی پیشانی پر ایک نورانی نشان بنائے گا اور انگوٹھی سے ہر کافر کی پیشانی پر ایک سیاہ داغ لگائے گا جو کبھی نہ مٹے گا جو کافر ہے ہرگز ایمان نہ لائے گا اور جو مسلمان ہے زندگی بھر اپنے ایمان پر قائم رہے گا ۔ (5) (بہار شریعت)\n (۶)…حضرت عیسی علیہ الصلاۃ والسلام کی وفات کے ایک زمانہ کے بعد جب قیامت کو صرف چالیس برس رہ جائیں گے تو ایک خوشبودار ٹھنڈی ہوا چلے گی جو لوگوں کی بغلوں کے نیچے سے گزرے گی جس کا اثر یہ ہوگا کہ مسلمانوں کی روح قبض ہوجائے گی اللّٰہ کہنے والا کوئی نہ بچے گا۔ کافر ہی کافر دنیا میں رہ جائیں گے ۔ چالیس برس تک ان کے ہاں کوئی اولاد نہ ہوگی۔ یعنی چالیس برس سے کم عمر کا کوئی نہ ہوگا اب انہیں پر قیامت قائم ہوگی۔ حضرت اسرافیل علیہ الصلاۃ والسلام صور پھونکیں گے سب مرجائیں گے ۔ آسمان، پہاڑ ، زمین یہاں تک کہ صور و اسرافیل اور تمام فرشتے فنا ہوجائیں گے سوائے اس واحد حقیقی کے کوئی نہ ہوگا۔ وہ فرمائے گا۔ لِمَنِ الْمُلْکُ الْیَوْمَ یعنی آج کس کی بادشاہت ہے ۔ مگر ہے کون جو جواب دے پھر خود ہی فرمائے گا۔ لِلَّہِ الْوَاحِدِ الْقَہَّارِ یعنی صرف اللّٰہ واحد قہار کی سلطنت ہے ۔ پھر جب اللّٰہ تعالیٰ چاہے گا ، اسرافیل کو زندہ فرمائے گا۔ اور صور کو پیدا کرکے دوبارہ پھونکنے کا حکم دے گا۔ صور پھونکتے ہی تمام اولین و آخرین ملائکہ اور انس وجن وغیرہ سب موجود ہوجائیں گے ۔ سب سے پہلے حضور ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم قبرِ انور سے یوں باہر تشریف لائیں گے کہ ان کے داہنے دستِ مبارک میں حضرت صدیق اکبر کا ہاتھ ہوگا اور بائیں دستِ مبارک میں حضرت فاروقِ اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا کا ہا تھ ہوگا۔ پھر مکہ معظمہ اور مدینہ طیبہ کے مقابر میں جتنے مسلمان دفن ہیں سب کو اپنے ہمراہ لے کر میدانِ حشر میں تشریف لے جائیں گے ۔\n------------------\n[1] ’’بہار شریعت‘‘، ج۱، ص ۱۲۰.\n[2] ’’بہارِ شریعت‘‘، ج۱، ص ۱۲۴.\n[3] ’’بہار شریعت‘‘، ج۱، ص ۱۲۲.\n[4] ’’بہارِ شریعت‘‘، ج۱، ص ۱۲۴.\n[5] ’’بہارِ شریعت‘‘، ج۱، ص ۱۲۶."}, {"id": 7777, "bookId": 14, "volNo": "1", "hadithNo": 9, "chapter": "حوض کوثر اور شفاعت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\nعَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بَیْنَا أَنَا أَسِیرُ فِی الْجَنَّۃِ إِذَا أَنَا بِنَہَرٍ حَافَتَاہُ قِبَابُ الدُّرِّ الْمُجَوَّفِ قُلْتُ مَا ہَذَا یَا جِبْرِیلُ قَالَ ہَذَا الْکَوْثَرُ الَّذِی أَعْطَاکَ رَبُّکَ فَإِذَا طِینُہُ مِسْکٌ أَذْفَرُ۔ \nحدیث2:\nعَنْ عَبْدِ اللّٰہ بْنُ عَمْرٍوقَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَوْضِی مَسِیرَۃُ شَہْرٍ وَزَوَایَاہُ سَوَاء ٌ ومَاؤُہُ أَبْیَضُ مِنْ اللَّبَنِ وَرِیحُہُ أَطْیَبُ مِنْ الْمِسْکِ وَکِیزَانُہُ کَنُجُومِ السَّمَاء مَنْ یَشْرَبُ مِنْہَا فلَا یَظْمَأُ أَبَدًا۔ \nحدیث3:\nعَنْ أَنَسٍ قَالَ سَأَلْتُ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ یَشْفَعَ لِی یَوْمَ الْقِیَامَۃِ فَقَالَ أَنَا فَاعِلٌ قُلْتُ یَا رَسُولَ اللّٰہ فَأَیْنَ أَطْلُبُکَ قَالَ اُطْلُبْنِی أَوَّلَ مَا تَطْلُبُنِی عَلَی الصِّرَاطِ قُلْتُ فَإِنْ لَمْ أَلْقَکَ عَلَی الصِّرَاطِ قَالَ فَاطْلُبْنِی عِنْدَ الْمِیزَانِ قُلْتُ فَإِنْ لَمْ أَلْقَکَ عِنْدَ الْمِیزَانِ قَالَ فَاطْلُبْنِی عِنْدَ الْحَوْضِ فَإِنِّی لَا أُخْطِیُٔ ہَذِہِ الثَّلَاثَ الْمَوَاطِنَ۔ \nحدیث4:\nعَنْ أَنَسٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ شَفَاعَتِی لِأَہْلِ الْکَبَاءِرِ مِنْ أُمَّتِی۔ \nحدیث5:\nعَنْ عَوْفِ بْنِ مَالِکٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَتَانِی آتٍ مِنْ عِنْدِ رَبِّی فَخَیَّرَنِی بَیْنَ أَنْ یَدْخُلَ نِصْفُ أُمَّتِی الْجَنَّۃَ وَبَیْنَ الشَّفَاعَۃِ فَاخْتَرْتُ الشَّفَاعَۃَ وَہِیَ لِمَنْ مَاتَ لَا یُشْرِکُ بِاللّٰہ شَیْءًا۔ \nحدیث6:\nعَنْ عِمْرَانَ بْن حُصَیْنٍ رَضِیَ اللّٰہ عَنْہُم ا قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَخْرُجُ قَوْمٌ مِنْ أُمَّتِیْ مِنَ النَّارِ بِشَفَاعَتِیْ یُسَمَّوْنَ الْجَہَنَّمِیِّیْنَ۔ \nحدیث7:\nعَنْ عُثْمَانَ بْنِ عَفَّانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَشْفَعُ یَوْمَ الْقِیَامَۃِ ثَلَاثَۃٌ الْأَنْبِیَاءُ ثُمَّ الْعُلَمَاءُ ثُمَّ الشُّہَدَاءُ۔ \nحدیث8:\nعَنْ أَبِی سَعِیدٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ مِنْ أُمَّتِی مَنْ یَشْفَعُ لِلْفِءَامِ وَمِنْہُمْ مَنْ یَشْفَعُ لِلْقَبِیلَۃِ وَمِنْہُمْ مَنْ یَشْفَعُ لِلْعُصْبَۃِ وَمِنْہُمْ مَنْ یَشْفَعُ لِلرَّجُلِ حَتَّی یَدْخُلُوا الْجَنَّۃَ۔\nحدیث9:\n عَنِ ابْنِ مَسْعُوْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَرِدُ النَّاسُ النَّارَ ثُمَّ یَصْدُرُونَ مِنْہَا بِأَعْمَالِہِمْ فَأَوَّلُہُمْ کَلَمْحِ الْبَرْقِ ثُمَّ کَالرِّیحِ ثُمَّ کَحُضْرِ الْفَرَسِ ثُمَّ کَالرَّاکِبِ فِی رَحْلِہِ ثُمَّ کَشَدِّ الرَّجُلِ ثُمَّ کَمَشْیِہِ۔", "urdu": "¥ترجمہ حدیث1:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ ( معراج کی رات میں) جب میں جنت کی سیر کررہا تھا تو میرا گزر ایک نہر پر ہوا جس کے دونوں طرف مُجوّف یعنی خولدار موتی کے گنبد تھے ۔ میں نے پوچھا جبریل یہ کیا ہے ؟ ا نہوں نے کہا یہ وہ کوثر ہے جو آپ کے رب نے آپ کو عطا فرمایا ہے میں نے دیکھا کہ اس کی مٹی نہایت خوشبودار خالص مشک کی ہے ۔ (بخاری، مشکوۃ)\n¥ترجمہ حدیث2:\nحضرت عبد اللّٰہ بن عمر و رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ میرے حوض (کوثر)کی مسافت ایک مہینہ (کا راستہ) ہے وہ مربع ہے یعنی اس کے چاروں کونے برابر ہیں۔ اس کا پانی دودھ سے زیادہ سفید اور مشک سے زیادہ خوشبودار ہے ۔ اس کے کوزے چمک اور زیادتی میں آسمان کے ستاروں کے مثل ہیں جو شخص اس میں سے پئے گا پھر کبھی پیاسا نہ ہوگا۔ (بخاری، مسلم)\n¥ترجمہ حدیث3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضورِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم سے درخواست کی کہ حضور قیامت کے دن میری سفارش فرمائی جائے ۔ سرکار نے فرمایا میں کروں گا۔ میں نے عرض کیا یارسول اللّٰہ ! میں حضور کو کہاں تلاش کروں گا۔ سرکار نے فرمایا پہلے مجھ کو پل صراط پر تلاش کرنا میں نے عرض کیا اگر حضور پل صراط پر نہ ملیں فرمایا تو میزان پر ۔ میں نے عرض کیا اگر حضور میزان پر بھی نہ ملیں فرمایا تو پھر حوضِ کوثر پر، میں ان تین جگہوں کو نہیں چھوڑوں گا ( یعنی ان مقامات میں سے کسی ایک جگہ ضرور ملوں گا)۔ (ترمذی ، مشکوۃ\n¥ترجمہ حدیث4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ میری شفاعت ثابت ہے میری امت کے کبیرہ گناہ کرنے والوں کے لیے ۔ (ترمذی، ابو داود، مشکوۃ)\n¥ترجمہ حدیث5:\nحضرتِ عوف بن مالک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ میر ے پاس خدائے تعالیٰ کی طرف سے ایک فرشتہ آیا تو اس نے مجھے اختیار دیا کہ یا تو میری آدھی امت جنت میں داخل ہو یا میں شفاعت کو اختیار کروں تو میں نے شفاعت کو منظور کیا ، میری شفاعت ہر اس شخص کے لیے ہوگی جو اس حال میں مرے کہ اس نے کسی کو خدائے تعالیٰ کا شریک نہ مانا ہو۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث6:\nحضرت عمران بن حصین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سر کار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ میری امت کی ایک جماعت میری شفاعت کی بدولت نارِ دوزخ سے نکالی جائے گی جس کا نام جہنمی پڑا ہواتھا۔ (بخاری، مشکوۃ)\n¥ترجمہ حدیث7:\nحضرت عثمان بن عفان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ ا لصلوۃوالتسلیم نے فرمایا کہ قیامت کے دن تین قسم کے لوگ شفاعت کریں گے پہلے انبیائے کرام علیہم السلام پھر علمائے دین۔ پھر شہدائے اسلام۔ ( ترمذی، مشکوۃ)\n¥ترجمہ حدیث8:\nحضرت ابوسعید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ میری امت میں سے بعض لوگ کئی جماعت کی شفاعت کریں گے اور بعض لوگ ایک قبیلہ کی ، اور بعض لوگ دس سے چالیس کی شفاعت کریں گے اور بعض لوگ صرف ایک آدمی کی۔ یہاں تک کہ میری کل امت جنت میں داخل ہوجائے گی۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث9:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ لوگ جہنم کی آگ کو (پل صراط سے گزر کر) عبور کریں گے ۔ پھر اپنے اعمال صالحہ کے مطابق جہنم(کی لپیٹ وغیرہ) سے نجات پائیں گے تو ان میں سے جو سب سے بہتر ہوں گے وہ بجلی چمکنے کے مانند ( پل صراط سے ) گزر جائیں گے ۔ پھر ہوا کے مثل پھر دوڑنے والے گھوڑے کی طرح، پھر اونٹ سوار کے مانند پھر دوڑنے والے آدمی کی طرح پھر پیدل چلنے کے مثل ۔ (ترمذی، دارمی، ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke (Me'raj ki raat mein) jab main Jannat ki sa'ee kar raha tha to mera guzar ek nehar par hua jis ke dono taraf mujawwaf ya'ni khol-daar moti ke gumbad thay. Main ne poocha Jibreel yeh kya hai? Unhon ne kaha yeh woh Kausar hai jo aap ke Rabb ne aap ko ata farmaya hai. Main ne dekha ke us ki mitti nihayat khushboo-daar khalis mushk ki hai. (Bukhari, Mishkat). Tarjuma Hadees 2: Hazrat Abdullah Bin Amr Radiyallahu Anhum ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke mere Hauz (Kausar) ki musafat ek mahina (ka rasta) hai, woh murabba hai ya'ni us ke charon konay barabar hain. Us ka pani doodh se zyada safed aur mushk se zyada khushboo-daar hai. Us ke koozay chamak aur zyadati mein aasman ke sitaron ke misl hain, jo shakhs us mein se piye ga phir kabhi pyasa na hoga. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu ne farmaya ke main ne Huzoor-e-Aqdas Sallallahu Alaihi Wasallam se darkhwast ki ke Huzoor Qayamat ke din meri shafa'at farmaye jaye. Sarkar ne farmaya main karoon ga. Main ne arz kiya Ya Rasoolullah! Main Huzoor ko kahan talash karoon ga? Sarkar ne farmaya pehle mujh ko Pul-e-Sirat par talash karna. Main ne arz kiya agar Huzoor Pul-e-Sirat par na milein? Farmaya to Meezan par. Main ne arz kiya agar Huzoor Meezan par bhi na milein? Farmaya to phir Hauz-e-Kausar par, main in teen jaghon ko nahi chhoroon ga (ya'ni in maqamat mein se kisi ek jagah zaroor miloon ga). (Tirmidhi, Mishkat). Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu se riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke meri shafa'at sabit hai meri ummat ke kabeera gunah karne walon ke liye. (Tirmidhi, Abu Dawood, Mishkat). Tarjuma Hadees 5: Hazrat Auf Bin Malik Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke mere paas Khuda-e-Ta'ala ki taraf se ek farishta aaya to us ne mujhe ikhtiyar diya ke ya to meri aadhi ummat Jannat mein dakhil ho ya main shafa'at ko ikhtiyar karoon, to main ne shafa'at ko manzoor kiya, meri shafa'at har us shakhs ke liye hogi jo is haal mein mare ke us ne kisi ko Khuda-e-Ta'ala ka shareek na mana ho. (Tirmidhi, Mishkat). Tarjuma Hadees 6: Hazrat Imran Bin Hussain Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke meri ummat ki ek jama'at meri shafa'at ki badaulat naar-e-dozakh se nikali jaye gi jis ka naam jahannami para hua tha. (Bukhari, Mishkat). Tarjuma Hadees 7: Hazrat Usman Bin Affan Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Qayamat ke din teen qisam ke log shafa'at karenge, pehle Anbiya-e-Kiram Alaihimussalam, phir Ulama-e-Deen, phir Shuhada-e-Islam. (Tirmidhi, Mishkat). Tarjuma Hadees 8: Hazrat Abu Saeed Radiyallahu Anhu se riwayat hai ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke meri ummat mein se ba'az log kai jama'at ki shafa'at karenge aur ba'az log ek qabeela ki, aur ba'az log das se chalis ki shafa'at karenge aur ba'az log sarf ek aadmi ki. Yahan tak ke meri kul ummat Jannat mein dakhil ho jaye gi. (Tirmidhi, Mishkat). Tarjuma Hadees 9: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke log Jahannam ki aag ko (Pul-e-Sirat se guzar kar) aboor karenge. Phir apne a'maal-e-saliha ke mutabiq Jahannam (ki lapet waghera) se najaat payenge to un mein se jo sab se behtar honge woh bijli chamakne ke manind (Pul-e-Sirat se) guzar jayenge. Phir hawa ke misl, phir daurne wale ghore ki tarah, phir oont sawar ke manind, phir daurne wale aadmi ki tarah, phir paidal chalne ke misl. (Tirmidhi, Darimi, Abu Dawood).", "explanation": "¥شرح حدیث7:\nحضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ تخصیص شفاعت بہ ایں سہ گروہ بجہت زیادت فضل و کرامت ایشان ست والا ہمہ اہلِ خیراز مسلماناں را ثابت ست ‘‘۔ (1)\nیعنی ان تین گروہ کے ساتھ شفاعت کی تخصیص ان کے فضل و بزرگی کی زیادتی کے سبب ہے ورنہ ہر اہلِ خیر مسلماناں ( مثلاً سچا حاجی، باعمل حافظ) کے لیے ( بھی شفاعت کا حق) ثابت ہے (اشعۃ اللمعات، جلد چہارم، ص۴۰۸)\n------------------\n[1] اشعۃ اللمعات ، کتاب الفتن ، باب الحوض والشفاعۃ ، الفصل الثالث ، ج ۴، ص ۴۳۲.\n¥انتباہ:\n (۱)…قیامت قائم ہونا حق ہے اس کا انکار کرنے والا کافر ہے ۔ (1) (بہار شریعت) \n (۲)…قیامت کے دن لوگ اپنی اپنی قبروں سے ننگے بدن بغیر ختنہ شدہ اٹھیں گے ، کوئی پیدل ہوگا کوئی سوار اور کافر منہ کے بل چلتے ہوئے میدانِ حشر کو جائیں گے کسی کو فرشتے گھسیٹ کر لے جائیں گے ۔ میدانِ حشر ملک شام کی سرزمین پر قائم ہوگا ا س دن زمین تانبے کی ہوگی ۔ سورج صرف ایک میل کے فاصلے پر ہوگا۔ ابھی چار ہزار برس کی راہ کے فاصلہ پر ہے اور اس کی پیٹھ دنیا کی طرف ہے قیامت کے دن اس کا منہ ا س طرف ہوگا گرمی اور تپش سے بھیجے کھولتے ہوں گے ۔ پسینہ اس کثرت سے نکلے گا کہ اوپر چڑھے گا کسی کے ٹخنوں تک ہوگا۔ کسی کے گھٹنوں تک ، کسی کے کمر ، کسی کے سینہ، کسی کے گلے تک اور کافر کے تو منہ تک چڑھ کر مثل لگام کے جکڑ جائے گا جس میں وہ ڈبکیاں کھائے گا اور گرمی کی حالت میں پیاس کی جو کیفیت ہوگی وہ محتاج بیان نہیں ، زبانیں سوکھ کر کانٹا ہوجائیں گی اور بعضوں کی زبانیں منہ سے باہر نکل آئیں گی۔ ان مصیبتوں کے باوجود کوئی کسی کا پرسانِ حال نہ ہوگا۔ بھائی سے بھائی بھاگے گا ماں باپ اولاد سے پیچھا چھڑائیں گے ۔ ہر ایک اپنی اپنی مصیبت میں گرفتار ہوگا کوئی کسی کا مددگار نہ ہوگا۔ قیامت کا دن جو کہ پچاس ہزار برس کا ہوگا اس پریشانی کی حالت میں قریب آدھے کے گزر جائے گا اب اہلِ محشر مشورہ کریں گے کہ اپنا کوئی سفارشی ڈھونڈنا چاہیے جو ہم کو ان مصیبتوں سے رہائی دلائے لوگ گرتے پڑتے حضرت آدم علیہ السلام کے پاس حاضر ہوں گے اور عرض کریں گے کہ اے حضرت آدم !آپ ابوالبشر ہیں خدائے تعالیٰ نے آپ کو اپنے دستِ قدرت سے بنایا فرشتوں سے آپ کو سجدہ کرایا۔ ہم لوگ سخت پریشانی میں مبتلا ہیں آپ ہماری شفاعت کیجیے کہ خدائے تعالیٰ ہمیں اس سے نجات بخشے حضرت آدم علیہ الصلاۃ والسلام فرمائیں گے ۔ یہ میرا مر تبہ نہیں تم کسی اور کے پاس جاؤ۔ لوگ حضرتِ نوح علیہ الصلاۃ والسلام کی خدمت میں حاضر ہوں گے اور ان کے فضائل بیان کرکے عرض کریں گے کہ آپ اپنے رب کے حضور ہماری شفاعت کیجیے ۔ یہاں سے بھی وہی جواب ملے گا کہ میں اس لائق نہیں تم کسی اور کے پاس جاؤ ۔ مختصر یہ کہ لوگ حضرت ابراہیم، حضرت موسی وغیرہ جلیل القدر انبیاء کرام علیہم السلام کی بارگاہ میں حاضر ہو کر شفاعت کے لیے گریہ وزاری کریں گے مگر ہر جگہ سے یہی جواب ملے گا کہ یہ میرا رتبہ نہیں تم کسی اور کے پاس جاؤ۔ یہاں تک کہ لوگ حضرت عیسی علیہ السلام کے پاس حاضر ہوں گے وہ بھی یہی فرمائیں گے کہ میں اس لائق نہیں تم کسی اور کے پاس جاؤ ، لوگ عرض کریں گے آپ ہمیں کس کے پاس بھیجتے ہیں۔ فرمائیں گے تم ان کے حضور حاضر ہو جن کے ہاتھ پر فتح رکھی گئی جو آج بے خوف ہیں اور وہ تمام اولاد آدم کے سردار ہیں تم محمد صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی خدمت میں حاضر ہو وہ خاتم النبین ہیں۔ وہی آج تمہاری شفاعت فرمائیں گے اب لوگ پھرتے پھراتے ٹھوکریں کھاتے روتے چلاتے دہائی دیتے ہوئے شفیع المذنبین رحمۃ للعالمین جناب احمد مجتبی محمد مصطفی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی بارگاہِ بے کس پناہ میں حاضرہو کر شفاعت کے لیے عرض کریں گے ۔ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم ارشاد فرمائیں گے ۔ أَنَا لھَا یعنی شفاعت کے لیے میں ہوں۔ یہ فرما کر بارگاہِ الہٰی میں سجدہ کریں گے ۔ ارشاد ہوگا:\n یَا مُحَمَّدُ اِرْفَعْ رَأْسَکَ وَقُلْ تُسْمَعْ وَسَلْ تُعْطَہ وَاشْفَعْ تُشَفَّعْ ۔ (2)\nیعنی اے محمد!اپنا سر اٹھاؤ اور کہو تمہاری بات سنی جائے گی اور جو مانگو گے ملے گا اور شفاعت کرو تمہاری شفاعت مقبول ہوگی۔ اب شفاعت کا سلسلہ شروع ہوجائے گا یہاں تک کہ جس کے دل میں رائی کے دانہ سے بھی کم ایمان ہوگا سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ اس کی بھی شفاعت فرمائیں گے ۔\n أَللَّہُمَّ ارْزُقْنَا وَوَالِدَیْنَا وَأَسَاتِذَتَنَا وَمَشَایِخَنَا وَتَلاَمِذَتَنَا وَأَحْبَابَنَا وَجَمِیْعَ أَھْلِ السُّنَّۃِ شَفَاعَۃَ حَبِیْبِکَ الْمُصْطَفَے وَنَبِیِّکَ الْمُجْتَبیَ عَلَیْہِ التحیَّۃُ وَالثَّنَاء ۔\n (۳)…شفاعت حق ہے اس کا انکار کرنا بدمذہبی و گمراہی ہے جیسا کہ حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ’’ اِنکارِ شفاعت بدعت و ضلالت ست چنانکہ خوارج وبعض معتزلہ بداں رفتہ اند ۔ (3) (اشعۃ اللمعات ، جلد چہارم ، ص ۴۰۸)\n اور حضرت مّلا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی فرماتے ہیں کہ:\n ’’ فِی شَرحِ مسلم للنووی قَالَ الْقَاضِی عَیَاض رَحمہ اللّٰہ تَعَالَی مَذْہَبُ أَھلِ السُّنَّۃِ جَوَازُ الشَّفَاعۃِ عَقلاً وَوُجُوبُھَا سَمعًا لِصَریحِ قَولہ تَعَالی { یَوْمَىٕذٍ لَّا تَنْفَعُ الشَّفَاعَةُ اِلَّا مَنْ اَذِنَ لَهُ الرَّحْمٰنُ وَ رَضِیَ لَهٗ قَوْلًا } وَقَد جَاء تِ الْآ ثَار الَّتِی بَلَغتْ بِمَجمُوعِھَا التَّواترَ لِصحَّۃِ الشَّفَاعَۃِ فِی الآخِرَۃِ وَأَجْمَع السلفُ الصَّالِحُونَوَمَنْ بَعد ھُم مِنْ أَھلِ السنَّۃِ عَلَیْھَا ‘‘(4)\nیعنی امام نووی کی کتاب شرح مسلم میں ہے کہ امام قاضی عیاض رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ اہلِ سنت و جماعت کا مذہب یہ ہے کہ عقلاً شفاعت جائز ہے اور اس کا وجوب سماعی ہے اس لیے کہ خدائے تعالیٰ نے کھلم کھلا ارشاد فرمایا کہ { یَوْمَىٕذٍ لَّا تَنْفَعُ الشَّفَاعَةُ اِلَّا مَنْ اَذِنَ لَهُ الرَّحْمٰنُ وَ رَضِیَ لَهٗ قَوْلًا }(سورۃ طہ، آیۃ ۱۰۹) یعنی اس دن کسی کی شفاعت کام نہ دے گی مگر اس شخص کی جسے رحمن نے (شفاعت کرنے کا) اذن دے دیا ہو اوراس کی بات پسند فرمائی ہو۔\n اور ( اس آیت کریمہ کے علاوہ بہت سی) حدیثیں وارد ہیں۔ جن کا مجموعہ آخرت میں شفاعت کی صحت پر حد تواتر کو پہنچ چکا ہے ۔ شفاعت کے حق ہونے پر سلف صالحین اور ان کے بعد اہلِ سنت و جماعت کا اجماع ہے ۔\n(مرقاۃ، جلد پنجم، ص ۲۷۷)\n (۴)…شفاعت کی چند قسمیں(5)ہیں جیسا کہ حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ:\n’’ نوع اول شفاعت عظمٰی ست کہ عام ست مر تمامہ خلائق را و مخصوصست بہ پیغمبر ما صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کہ ہیچ کس را از انبیاء صلوات اللّٰہ تعالی وسلامہ علیہم مجال جرات وا قدام براں نباشد وآں برائے اراحت وتخلیص از طول وقوف در عرصات وتعجیل حساب و حکم کردگار تعالی وتقدس وبرآوردن ازاں شدت ومحنت دوم از برائے درآوردن قومے در بہشت بغیر حساب و ثبوت آں نیز وارد شدہ برائے پیغمبر ما ونزد بعضے مخصوص بحضرت او ست سوم در اقوامے کہ حسنات وسیئات ایشاں برابر باشد وبامدادِ شفاعت بہ بہشت درآیند چہارم قومے کہ مستحق و مستوجب دوزخ شدہ باشند پس شفاعت کند وایشاں را بہ بہشت در آرد پنجم برائے رفع درجات و زیادت کرامات ششم در گناہ گاراں کہ بدوزخ درآمدہ باشند بہ شفاعت بر آیند وایں شفاعت مشترک ست میاں سائر انبیاء وملائکہ وعلماء وشہداء ۔ ہفتم در استفتاح جنت ہشتم درتخفیف عذاب از انہا کہ مستحق عذاب مخلد شدہ باشند نہم برائے اہلِ مدینہ خاصہ دہم برائے زیارت کنندگان قبر شریف بروجہ امتیاز واختصاص ‘‘۔ (6)\n یعنی شفاعت کی پہلی قسم شفاعت عظمیٰ ہے جو کہ تمام مخلوقات کے لیے عام ہے اور ہمارے پیغمبر صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے ساتھ خاص ہے یعنی انبیائے کرام علیہم الصلوۃ والسلام میں سے کسی اور نبی کو اس پرجرأت اور پیش قدمی کی مجال نہ ہوگی اور یہ شفاعت لوگوں کو آر ام پہنچانے ، میدانِ حشر میں دیر تک ٹھہرنے سے چھٹکارا دلانے ، اللّٰہ تبارک و تعالیٰ کے فیصلہ اور حساب کے جلدی کرنے اور قیامت کے دن کی سختی و پریشانی سے نکالنے کے لیے ہوگی۔ دوسری قسم کی شفاعت ایک قوم کو بے حساب جنت میں داخل کرنے کے لیے ہوگی اور یہ شفاعت بھی ہمارے پیغمبر سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے لیے ثابت ہے ۔ اور بعض لوگوں کے نزدیک یہ شفاعت حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ہی کے ساتھ خاص ہے ۔ تیسری قسم کی شفاعت ان لوگوں کے بار ے میں ہوگی کہ جن کی نیکیاں اور برائیاں برابر ہوں گی۔ اور شفاعت کی امداد سے جنت میں داخل ہوں گے ۔ چوتھی قسم کی شفاعت ان لوگوں کے لیے ہوگی جو کہ دوزخ کے مستحق اور حق دار ہوچکے ہوں گے ۔ تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ شفاعت فرما کر ان کو جنت میں لاویں گے ۔ پانچویں قسم کی شفاعت مرتبے کی بلندی اور بزرگی کی زیادتی کے لیے ہوگی۔ چھٹی قسم کی شفاعت ان گنہگاروں کے بارے میں ہوگی جو کہ جہنم میں پہنچ چکے ہوں گے اور شفاعت کی وجہ سے نکل آئیں گے اور اس شفاعت میں دیگر انبیائے کرام علیہم السلام ، فرشتے ، علماء اور شہداء بھی شریک ہوں گے ۔ ساتویں قسم کی شفاعت جنت کھولنے کے بارے میں ہوگی۔ آٹھویں قسم کی شفاعت ان لوگوں کے عذاب کی تخفیف کے بارے میں ہوگی جو کہ دائمی عذاب کے مستحق ہوں گے ۔ نویں قسم کی شفاعت خاص کر مدینہ منورہ والوں اور سرکارِ اقدس کے روضئہ انور کی زیارت کرنے والوں کے لیے اختصاص و امتیاز کے طریقہ پر ہوگی۔ (اشعۃ اللمعات، جلد چہارم، ص۳۸۲)\n (۵)…حوض کوثر جو کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو مرحمت ہوا حق ہے ۔ (7)(بہار شریعت)\n (۶)…قیامت کے دن ہر شخص کو اس کی نیکیوں کا نامہ اعمال داہنے ہاتھ میں دیا جائے گا۔ اور برائیوں کا بائیں ہاتھ میں۔ اور کافر کا نامۂ اعمال سینہ توڑ کر اس کابایاں ہاتھ اس کے پس پشت نکال کرپیٹھ کے پیچھے دیا جائے گا۔ (8) (بہار شریعت)\n (۷)…حساب حق ہے اور اس کا منکر کافر ہے ۔ (9) (بہار شریعت)\n (۸)…میزان حق ہے اس پر لوگوں کے نیک و بداعمال تو لے جائیں گے نیکی یا بدی کا پلہ بھاری ہونے کا یہ مطلب ہے کہ اُوپر اٹھے یعنی دنیا کے جیسا معاملہ نہیں ہوگا کہ جو بھاری ہوتا ہے نیچے جھکتا ہے ۔ (10) (بہار شریعت)\n (۹)… حضورِا قدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو خدائے تعالیٰ مقامِ محمود عطا فرمائے گا کہ تمام اولین و آخرین آپ کی تعریف کریں گے ۔ (11)\n (۱۰)…سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو ایک جھنڈا مرحمت ہوگا جس کا نام لواء الحمد ہے ۔ حضرت آدم علیہ الصلاۃ والسلام سے لے کر قیامت تک کے سب مومنین اسی جھنڈے کے نیچے ہوں گے ۔ (12)\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۱۲۹.\n[2] ’’بہار شریعت‘‘، ج۱، ص۱۳۰۔ ۱۳۹.\n[3] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب الحوض والشفاعۃ ، الفصل الثالث ، ج ۴، ص ۴۳۲.\n[4] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب صفۃ القیامۃ والجنۃ والنار ، باب الحوض والشفاعۃ ، الحدیث : ۵۵۹۸، ج ۹، ص ۵۶۴.\n[5] حضرت ملا علی قاری علیہ رحمۃاللّٰہ الباری فرماتے ہیں ’’ اَلشَّفَاعَۃُ خَمْسَۃُ أَقْسامٍ ( أَوَّلھَا ) مُخْتَصَّۃٌ بِنَبیِّنَا صلی اللّٰہ علیہ وسلم وَھِیَ الارَاحَۃُ مِنْ ہَوْلِ الْمَوْقِفِ وَتَعجِیْلُ الْحِسَابِ ( الثَّانِیَۃ ) فِی إِدْخَال قَومِنِ الْجَنَّۃَ بِغَیْر حِسَابٍ وَھَذِہِ أَیضًا وَرَدَتْ فِی نَبِیِّنَا صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ ۔ ( الثالثۃ ) اَلشَّفَاعَۃُ لِقَومٍ اِسْتوْجَبُوْا النَّارَ فَیشْفَعُ فِیْھِمْ نَبِیُّنَا صلی اللّٰہ علیہ وسلم وَمَنْ شَاء اللّٰہ تَعَالی ( الرابعۃ ) فِیْمَن دَخَلَ النَّارَ مِن الْمُذْنِبِیْنَ فَقَدْ جَاءَ تِ الْآحَادِیْثُ بإخْرَاجِھِم مِنَ النَّارِ بِشَفَاعَۃِ نَبِیِّنَا وَالْمَلَاءِکَۃِ وَإِخْوَانِھِم مِنَ الْمُومِنِیْنَ ثُمَّ یُخْرِجُ اللّٰہ تَعَالی کُلَّ مَنْ قَالَ لَا إِلَہَ إِلاَّ اللّٰہ ( الخامسۃ ) اَلشَّفَاعَۃُ فِی زِیَادَۃ الدَّرَجَاتِ فِی الْجَنَّۃ لأَھْلِھَا وَھَذِہِ لَا تُنْکَرُھَا أَیضًا ۔ ( مرقاۃ ، جلد پنجم ، ص ۲۷۸) ( مرقاۃ المفاتیح شرح مشکاۃ المصابیح ، کتاب صفۃ القیامۃ إلخ ، الحدیث : ۵۵۹۸، ج ۹، ص ۵۶۴)\n[6] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب الحوض والشفاعۃ ، الفصل الأول ، ج۴، ص۴۰۴.\n[7] ’’بہار شریعت‘‘، ج۱، ص۱۴۵. \n[8] ’’بہار شریعت‘‘، ج۱، ص۱۴۴. \n[9] ’’بہارِ شریعت‘‘، ج۱، ص۱۴۱.\n[10] ’’بہارِ شریعت‘‘، ج۱، ص۱۴۶. \n[11] ’’بہارِ شریعت‘‘، ج۱، ص۱۴۶. \n[12] ’’بہارِ شریعت‘‘، ج۱، ص۱۴۷."}, {"id": 7778, "bookId": 14, "volNo": "1", "hadithNo": 10, "chapter": "جنت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ أَبِی ہُرَیْرَۃَ رَضِیَ اللّٰہ عَنْہُ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ اللّٰہ تَعَالَی أَعْدَدْتُ لِعِبَادِی الصَّالِحِینَ مَا لَا عَیْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَی قَلْبِ بَشَرٍ۔ \nحدیث 2:\nعَنْ بُرَیْدَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَہْلُ الْجَنَّۃِ عِشْرُونَ وَمِءَۃُ صَفٍّ ثَمَانُونَ مِنْہَا مِنْ ہَذِہِ الْأُمَّۃِ وَأَرْبَعُونَ مِنْ سَاءِرِ الْأُمَمِ۔ \nحدیث 3:\nعَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْ أَنَّ امْرَأَۃً مِنْ نِسَاء أَہْلِ الْجَنَّۃِ اطَّلَعَتْ إِلَی الْأَرْضِ لَأَضَاءتْ مَا بَیْنَہُمَا وَلَمَلَأَتْ مَا بَیْنَہُمَا رِیحًا وَلَنَصِیفُہَا عَلَی رَأْسِہَا خَیْرٌ مِنْ الدُّنْیَا وَمَا فِیہَا۔ \nحدیث 4:\n عَنْ سَعْدِ بْنِ أَبِی وَقَّاصٍ عَنْ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَوْ أَنَّ مَا یُقِلُّ ظُفُرٌ مِمَّا فِی الْجَنَّۃِ بَدَا لَتَزَخْرَفَتْ لَہُ مَا بَیْنَ خَوَافِقِ السَّمَوَاتِ وَالْأَرْضِ وَلَوْ أَنَّ رَجُلًا مِنْ أَہْلِ الْجَنَّۃِ اطَّلَعَ فَبَدَا أَسَاوِرُہُ لَطَمَسَ ضَوْءُ ہُ ضَوْءَ الشَّمْسِ کَمَا تَطْمِسُ الشَّمْسُ ضَوْءَ النُّجُومِ۔\nحدیث 5:\nعَنْ أَبِی سَعِیدٍ وَأَبِی ہُرَیْرَۃَ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ یُنَادِی مُنَادٍ إِنَّ لَکُمْ أَنْ تَصِحُّوا فَلَا تَسْقَمُوا أَبَدًا وَإِنَّ لَکُمْ أَنْ تَحْیَوْا فَلَا تَمُوتُوا أَبَدًا وَإِنَّ لَکُمْ أَنْ تَشِبُّوا فَلَا تَہْرَمُوا أَبَدًا وَإِنَّ لَکُمْ أَنْ تَنْعَمُوا فَلَا تَبْأَسُوا أَبَدًا۔\nحدیث 6:\n عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ أَہْلَ الْجَنَّۃِ یَأْکُلُونَ فِیہَا وَیَشْرَبُونَ وَلَا یَتْفُلُونَ وَلَا یَبُولُونَ وَلَا یَتَغَوَّطُونَ وَلَا یَمْتَخِطُونَ قَالُوا فَمَا بَالُ الطَّعَامِ قَالَ جُشَاء ٌ وَرَشْحٌ کَرَشْحِ الْمِسْکِ یُلْہَمُونَ التَّسْبِیحَ وَالتَّحْمِیدَ کَمَا تُلْہَمُونَ النَّفَسَ۔\nحدیث 7:\nعَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ أَدْنَی أَہْلِ الْجَنَّۃِ مَنْزِلَۃً لَمَنْ یَنْظُرُ إِلَی جِنَانِہِ وَأَزْوَاجِہِ وَنَعِیمِہِ وَخَدَمِہِ وَسُرُرِہِ مَسِیرَۃَ أَلْفِ سَنَۃٍ وَأَکْرَمَہُمْ عَلَی اللّٰہ مَنْ یَنْظُرُ إِلَی وَجْہِہِ غُدْوَۃً وَعَشِیَّۃً ثُمَّ قَرَأَ { وُجُوْهٌ یَّوْمَىٕذٍ نَّاضِرَةٌۙ(۲۲)اِلٰى رَبِّهَا نَاظِرَةٌۚ(۲۳)}", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا ہے کہ خدائے تعالیٰ نے فرمایا ہے کہ میں نے اپنے نیک بندوں کے لیے ایسی چیز تیار کررکھی ہے کہ جس کو نہ کسی آنکھ نے دیکھا نہ اس کی خوبیوں کو کسی کان نے سنا اور نہ کسی انسان کے دل پر اس کی ماہیت کا خیال گزرا ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت بُریدہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سر کارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جنتیوں کی ایک سو بیس صفیں ہوں گی۔ اور ان میں سے اسی(۸۰) صفیں اس امت کی ہوں گی اور چالیس صفیں دوسری امتوں کی۔ (ترمذی، دارمی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اگر جنتیوں کی عورتوں میں سے کوئی عورت زمین کی طرف جھانکے تو آسمان سے زمین تک منور ہوجائے اور ساری فضا زمین سے آسمان تک خوشبو سے معطر ہوجائے ۔ اور اس کے سرکی اوڑھنی دنیا و مافیہا سے بہتر ہے ۔ (بخاری، مشکوۃ)\n¥ترجمہ حدیث 4:\nحضرت سعد بن ابی وقاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃوالتسلیم نے فرمایا کہ اگر جنت کی چیزوں میں سے ناخن برابر کوئی چیز ظاہر ہوجائے تو آسمان و زمین کے اطراف وجوانب اس سے آراستہ ہوجائیں۔ اور اگر جنتیوں میں سے کوئی شخص ( دنیا کی طرف) جھانکے اور اس کے کنگن ظاہر ہوجائیں تو اس کی روشنی سورج کی روشنی کو مٹا دے ، جیسے کہ ستاروں کی روشنی کو سورج مٹا دیتا ہے ۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضر ت ابو سعید وا بوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ رسولِ کریم علیہ الصلاۃوالتسلیم نے فرمایا کہ پکارنے والا پکار کر کہے گا کہ (اے جنت والو) تم تندرست رہو گے کبھی بیمار نہ ہوگے ، تم زندہ رہو گے کبھی نہ مرو گے ۔ تم جوان رہو گے کبھی بوڑھے نہ ہو گے ۔ اور تم آرام سے رہو گے کبھی محنت ومشقت نہ اٹھاؤ گے ۔ (مسلم ، مشکوۃ)\n¥ترجمہ حدیث 6:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جنتّی جنت میں کھائیں گے اور پئیں گے لیکن نہ تھوکیں گے ، نہ پیشاب و پاخانہ کریں گے ۔ اور نہ رینٹھ سنکیں گے ۔ صحابہ نے عرض کیا کھانے کا فضلہ کیا ہوگا؟ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ (فرحت بخش) ڈکار آئے گی اور ایسا پسینہ آئے گا جو مشک کی خوشبو کے مثل ہوگا۔ اور سُبْحَانَ اللّٰہ وَالْحَمْدُ ﷲِ کہنا جنتیوں کے دل میں ڈال دیا جائے گا۔ ( جوان کی زبان پربے تکلف جاری ہوگا) جیسے کہ سانس جاری ہے ۔ (مسلم ، مشکوۃ)\n¥ترجمہ حدیث 7:\nحضرت ابنِ عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ مرتبہ کے لحاظ سے ادنیٰ جنتی وہ شخص ہوگا جو اپنے باغوں، اپنی بیویوں، اپنی نعمتوں، اپنے خدمت گاروں اور اپنی آرام گاہوں کو ایک ہزار برس کی مسافت کے اندر پھیلا ہوا دیکھے گا اور خدائے تعالیٰ کے نزدیک سب سے بڑے مرتبہ کا جنتی وہ شخص ہوگا جو صبح و شام دیدارِ الہٰی سے مشرف ہوگا۔ اس کے بعد حضور نے یہ آیت کریمہ تلاوت فرمائی:{ وُجُوْهٌ یَّوْمَىٕذٍ نَّاضِرَةٌۙ(۲۲)اِلٰى رَبِّهَا نَاظِرَةٌۚ(۲۳) }(پارہ ۲۹ سورۃ القیامۃ) یعنی اس روز بہت سے چہرے اپنے پروردگار کے دیدار سے ترو تازہ اور خوش و خرم ہوں گے ۔ ( احمد ، ترمذی، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya hai ke Khuda-e-Ta'ala ne farmaya hai ke main ne apne nek bandon ke liye aisi cheez tayyar kar rakhi hai ke jis ko na kisi aankh ne dekha, na us ki khoobiyon ko kisi kaan ne suna aur na kisi insaan ke dil par us ki mahiyat ka khayal guzra. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Buraidah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke Jannatiyon ki ek sau bees safein hongi. Aur un mein se assi (80) safein is ummat ki hongi aur chalis safein doosri ummaton ki. (Tirmidhi, Darimi, Mishkat). Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke agar Jannatiyon ki auraton mein se koi aurat Zameen ki taraf jhankay to aasman se Zameen tak munawwar ho jaye aur saari fiza Zameen se aasman tak khushboo se mo'attar ho jaye. Aur us ke sar ki orhni duniya-o-mafiha se behtar hai. (Bukhari, Mishkat). Tarjuma Hadees 4: Hazrat Saad Bin Abi Waqqas Radiyallahu Anhu se riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke agar Jannat ki cheezon mein se naakhun barabar koi cheez zahir ho jaye to aasman-o-Zameen ke atraf-o-jawanib us se aarasta ho jayen. Aur agar Jannatiyon mein se koi shakhs (duniya ki taraf) jhankay aur us ke kangan zahir ho jayen to us ki roshni sooraj ki roshni ko mita de, jaise ke sitaron ki roshni ko sooraj mita deta hai. (Tirmidhi, Mishkat). Tarjuma Hadees 5: Hazrat Abu Saeed aur Abu Hurairah Radiyallahu Anhum se riwayat hai ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke pukarne wala pukar kar kahe ga ke (Ae Jannat walo) tum tandurust rahoge kabhi bimar na hoge, tum zinda rahoge kabhi na maroge. Tum jawan rahoge kabhi boorhay na hoge. Aur tum aaram se rahoge kabhi mehnat-o-mashaqqat na uthaoge. (Muslim, Mishkat). Tarjuma Hadees 6: Hazrat Jabir Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke Jannati Jannat mein khayenge aur piyenge lekin na thookenge, na peshaab-o-paakhana karenge. Aur na renth sankenge. Sahabah ne arz kiya khane ka fazla kya hoga? Huzoor Sallallahu Alaihi Wasallam ne farmaya ke (farhat bakhsh) dakaar aaye gi aur aisa paseena aaye ga jo mushk ki khushboo ke misl hoga. Aur SubhanAllah walhamdulillah kehna Jannatiyon ke dil mein daal diya jaye ga. (Jo un ki zaban par be-takalluf jaari hoga) jaise ke saans jaari hai. (Muslim, Mishkat). Tarjuma Hadees 7: Hazrat Ibn-e-Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke martaba ke lihaz se adna Jannati woh shakhs hoga jo apne baghon, apni biwiyon, apni ne'maton, apne khidmat-garon aur apni aaram-gahon ko ek hazar baras ki musafat ke andar phaila hua dekhe ga aur Khuda-e-Ta'ala ke nazdeek sab se baray martaba ka Jannati woh shakhs hoga jo subah-o-shaam deedar-e-Ilahi se musharraf hoga. Us ke baad Huzoor ne yeh aayat-e-karima tilawat farmayi: { Wujoohun yawma'izin naadirah, ila Rabbiha naazirah } (Para 29, Surah Al-Qiyamah) ya'ni us roz bohat se chehray apne Parwardigar ke deedar se taro-taza aur khush-o-khurram honge. (Ahmad, Tirmidhi, Mishkat).", "explanation": "¥انتباہ :\n (۱)… جنتیوں کو جنت میں ہر قسم کے لذیذ میوے اور کھانے ملیں گے ، جو چاہیں گے فوراً ان کے سامنے موجود ہوگا۔ اگر کسی پرند کا گوشت کھانے کو جی چاہے گا تو اسی وقت بھنا ہوا ان کے سامنے آجائے گا۔ اگر کسی چیز کے پینے کی خواہش ہوگی تو اسی چیز سے بھر ا ہوا کوزہ فوراً ہاتھ میں آجائے گا۔ \n (۲)… ادنیٰ جنتی کے لیے اسّی(۸۰) ہزار خادم اور بہتر (۷۲) بیویاں ہوں گی اور ان کو ایسے تاج ملیں گے کہ اس میں کا ایک ادنیٰ موتی ساری دنیا کو روشن کردے گا۔ \n (۳)… جنتی آپس میں ملاقات کرنا چاہیں گے تو ایک تخت دوسر ے کے پاس خود بخود چلا جائے گا۔"}, {"id": 7779, "bookId": 14, "volNo": "1", "hadithNo": 11, "chapter": "دوزخ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ أَبِی ہُرَیْرَۃَ عَنْ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أُوقِدَ عَلَی النَّارِ أَلْفَ سَنَۃٍ حَتَّی احْمَرَّتْ ثُمَّ أُوقِدَ عَلَیْہَا أَلْفَ سَنَۃٍ حَتَّی ابْیَضَّتْ ثُمَّ أُوقِدَ عَلَیْہَا أَلْفَ سَنَۃٍ حَتَّی اسْوَدَّتْ فَہِیَ سَوْدَاءُ مُظْلِمَۃٌ۔ \nحدیث 2:\nعَنْ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَہْوَنُ أَہْلِ النَّارِ عَذَابًا أَبُو طَالِبٍ وَہُوَ مُنْتَعِلٌ بِنَعْلَیْنِ یَغْلِی مِنْہُمَا دِمَاغُہُ۔ \nحدیث 3:\nعَنْ سَمُرَۃَ بْنِ جُنْدَبٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مِنْہُمْ مَنْ تَأْخُذُہُ النَّارُ إِلَی کَعْبَیْہِ وَمِنْہُمْ مَنْ تَأْخُذُہُ النَّارُ إِلَی رُکْبَتَیْہِ وَمِنْہُمْ مَنْ تَأْخُذُہُ النَّارُ إِلَی حُجْزَتِہِ وَمِنْہُمْ مَنْ تَأْخُذُہُ النَّارُ إِلَی تَرْقُوَتِہِ۔\nحدیث 4:\n عَنْ أَبِی سَعِیْدِنِ الْخُدْرِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْ أَنَّ دَلْوًا مِنْ غَسَّاقٍ یُہَرَاقُ فِی الدُّنْیَا لَأَنْتَنَ أَہْلَ الدُّنْیَا۔ \nحدیث 5:\nعَنْ عَبْدِ اللّٰہ بْنِ الْحَارِثِ بْنِ جَزْئٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ فِی النَّارِ حَیَّاتٍ کَأَمْثَالِِ الْبُخْتِ تَلْسَعُ إِحْدَاہُنَّ اللَّسْعَۃَ فَیَجِدُ حَمْوَتَہَا أَرْبَعِینَ خَرِیفًا وَإِنَّ فِی النَّارِ عَقَارِبَ کَأَمْثَالِ الْبِغَالِ الْمُوکَفَۃِ تَلْسَعُ إِحْدَاہُنَّ اللَّسْعَۃَ فَیَجِدُ حَمْوَتَہَا أَرْبَعِینَ خَرِیفًا۔ \nحدیث 6:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَدْخُلُ النَّارَ إِلَّا شَقِیٌّ قِیلَ یَا رَسُولَ اللّٰہ وَمَنْ الشَّقِیُّ؟ قَالَ مَنْ لَمْ یَعْمَلْ لِلَّہِ بِطَاعَۃٍ وَلَمْ یَتْرُکْ لَہُ مَعْصِیَۃً۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃوالتسلیم نے فرمایا کہ جہنم کی آگ کو ایک ہزار برس جلایا گیا یہا ںتک کہ وہ سرخ ہوگئی ۔ پھر اس کو ایک ہزار برس تک جلایا گیا۔ یہاں تک کہ وہ سفید ہوگئی پھر اسے ایک ہزار برس اور جلایا گیا یہاں تک کہ وہ کالی سیاہ ہوگئی اب وہ سیاہ و تاریک ہے ۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ دوزخیوں میں سب سے ہلکا عذاب ابو طالب کو ہوگا۔ اس کو آگ کے جوتے پہنائے جائیں گے جن سے اس کا دماغ کھولنے لگے گا۔ ( بخاری، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت سمرہ بن جندب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ دوزخیوں میں بعض لوگ وہ ہوں گے جن کے ٹخنوں تک آگ ہوگی اور بعض لوگ وہ ہوں گے جن کے زانوں تک آگ کے شعلے پہنچیں گے اور بعض و ہ ہوں گے جن کے کمر تک ہوگی اور بعض لوگ وہ ہوں گے جن کے گلے تک آگ کے شعلے ہوں گے ۔ (مسلم ، مشکوۃ)\n¥ترجمہ حدیث 4:\nحضرت ابو سعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ اگر اس زرد پانی کا ایک ڈول جودوزخیوں کے زخموں سے جاری ہوگا دنیا میں ڈال دیا جائے تو دنیا والے بدبو دار ہوجائیں۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث 5:\n حضرت عبد اللّٰہ بن حارث بن جزء نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ دوزخ میں بختی اونٹ کے برابر سانپ ہیں۔ یہ سانپ ایک مرتبہ کسی کو کاٹے تو اس کا درد اور زہر چالیس برس تک رہے گا۔ اور دوزخ میں پالان باندھے ہوئے خچروں کے مثل بچھو ہیں تو ان کے ایک مر تبہ کاٹنے کا درد و زہر چالیس (۴۰) سال تک رہے گا۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 6:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ دوزخ میں صرف بدنصیب داخل ہوگا۔ پوچھا گیا یارسول اللّٰہ ! بدنصیب کون ہے ؟ فرمایا بدنصیب وہ شخص ہے کہ جس نے خدائے تعالیٰ کی خوشنودی حاصل کرنے کے لیے اس کی اطاعت نہیں کی اور اللّٰہ تعالیٰ کے لیے گناہ کو نہیں چھوڑا ۔ (ابن ماجہ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Jahannam ki aag ko ek hazar baras jalaya gaya yahan tak ke woh surkh ho gayi. Phir us ko ek hazar baras tak jalaya gaya. Yahan tak ke woh safed ho gayi phir usay ek hazar baras aur jalaya gaya yahan tak ke woh kaali siyah ho gayi ab woh siyah-o-tareek hai. (Tirmidhi, Mishkat). Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Dozakhiyon mein sab se halka azab Abu Talib ko hoga. Us ko aag ke jootay pehnaye jayenge jin se us ka dimagh kholne lage ga. (Bukhari, Mishkat). Tarjuma Hadees 3: Hazrat Samurah Bin Jundub Radiyallahu Anhu ne kaha ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Dozakhiyon mein ba'az log woh honge jin ke takhnon tak aag hogi aur ba'az log woh honge jin ke zanon tak aag ke sholay pahunchenge aur ba'az woh honge jin ke kamar tak hogi aur ba'az log woh honge jin ke galay tak aag ke sholay honge. (Muslim, Mishkat). Tarjuma Hadees 4: Hazrat Abu Saeed Khudri Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke agar is zard pani ka ek dowl jo Dozakhiyon ke zakhmon se jaari hoga duniya mein daal diya jaye to duniya wale badboo-daar ho jayen. (Tirmidhi, Mishkat). Tarjuma Hadees 5: Hazrat Abdullah Bin Harith Bin Juz ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Dozakh mein bakhti oont ke barabar saanp hain. Yeh saanp ek martaba kisi ko kaatay to us ka dard aur zehar chalis baras tak rahe ga. Aur Dozakh mein paalan bandhay hue khachron ke misl bichhoo hain to un ke ek martaba kaatne ka dard-o-zehar chalis (40) saal tak rahe ga. (Ahmad, Mishkat). Tarjuma Hadees 6: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Dozakh mein sarf badnaseeb dakhil hoga. Poocha gaya Ya Rasoolullah! Badnaseeb kaun hai? Farmaya badnaseeb woh shakhs hai ke jis ne Khuda-e-Ta'ala ki khushnoodi hasil karne ke liye us ki ita'at nahi ki aur Allah Ta'ala ke liye gunah ko nahi chhora. (Ibn Majah, Mishkat).", "explanation": "¥انتباہ:\n (۱)… جنت و دوزخ حق ہیں۔ ان کا انکار کرنے والا کافر ہے ۔ (1) (بہار شریعت)\n (۲)… دنیا کی آگ دوزخ کی آگ کے ستّر جزوں میں سے ایک جز ہے ۔ (2) (بہار شریعت)\n (۳)…حضرت جبریل علیہ السلام نے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے قسم کھا کر عرض کیا کہ اگر جہنم کو سوئی کی نوک برابر کھول دیا جائے تو اس کی گرمی سے سب زمین والے مرجائیں۔ اور قسم کھا کر کہا کہ اگر جہنم کا کوئی داروغہ دنیا والوں پر ظاہر ہوجائے تو زمین کے رہنے والے سب کے سب ان کی ہیبت سے مرجائیں اور قسم کے ساتھ بیان کیا کہ اگر جہنمیوں کی زنجیر کی ایک کڑی دنیا کے پہاڑوں پر رکھ دی جائے تو کانپنے لگیں اور انہیں قرار نہ ہو یہاں تک کہ نیچے کی زمین تک دھنس جائیں۔ (3)(بہار شریعت)\n (۴)… دوزخ کی گہرائی اتنی زیادہ ہے کہ اگر پتھر کی چٹان جہنم کے کنارے سے اس میں پھینکی جائے تو ستر برس میں بھی تہ تک نہ پہنچے گی۔ (4)(بہار شریعت)\n (۵)…جہنمیوں کو تیل کی جلی ہوئی تلچھٹ کی مثل سخت کھولتا ہوا پانی پینے کو دِیا جائے گا کہ مُنہ کے قریب ہوتے ہی اس کی تیزی سے چہرے کی کھال گرجائے گی۔ سر پر گرم پانی بہایا جائے گا ۔ جہنمیوں کے بدن سے جو پیپ بہے گی وہ پلائی جائے گی خار دار تھوہڑ کھانے کو دیا جائے گا۔ وہ گلے میں جا کر پھندا ڈالے گا۔ اس کے اتارنے کے لیے پانی مانگیں گے تو ان کو ایسا کھولتا ہوا پانی دیا جائے گا کہ منہ کے قریب آتے ہی منہ کی ساری کھال اس میں گر پڑے گی۔ اور پیٹ میں جاتے ہی آنتوں کو ٹکڑے ٹکڑے کردے گا تو وہ شوربے کی طرح بہہ کر قدموں کی طرف نکلیں گی۔ (5) (بہار شریعت)\n (۶)…جہنم والے گدھے کی آواز کی طرح چلّا کر روئیں گے پہلے آنسو نکلیں گے جب آنسو ختم ہوجائیں گے تو خون روئیں گے ، روتے روتے گالوں میں خندقوں کی مثل گڑھے پڑ جائیں گے ، رونے کا خون اور پیپ اس قدر ہوگا کہ اس میں کشتیاں ڈالی جائیں تو چلنے لگیں۔ العیاذ باللّٰہ ۔\n------------------\n[1] ’’بہارِ شریعت ، ج۱، ص ۱۵۰.\n[2] ’’بہار شریعت، ج۱، ص ۱۶۴.\n[3] ’’بہارِ شریعت، ج۱، ص ۱۶۵. \n[4] ’’بہارِ شر یعت ، ج۱، ص ۱۶۶.\n[5] ’’بہارِ شریعت‘‘، ج۱، ص ۱۶۷."}, {"id": 7780, "bookId": 14, "volNo": "1", "hadithNo": 12, "chapter": "وضو کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ أَبِی مَالِک الأَشْعَرِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الطُّہُورُ شَطْرُ الْإِیمَانِ۔ \nحدیث 2:\nعَنْ عُثْمَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَایَاہُ مِنْ جَسَدِہِ حَتَّی تَخْرُجَ مِنْ تَحْتِ أَظْفَارِہِ۔ \nحدیث 3:\n عَنْ سَعِیدِ بْنِ زَیْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا وُضُو ء لِمَنْ لَمْ یَذْکُرْ اسْمَ اللّٰہ عَلَیْہِ۔ \nحدیث 4:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا لَبِسْتُمْ وَإِذَا تَوَضَّأْتُمْ فَابْدَءُ وْا بِأَیَامِنِکُمْ۔\nحدیث 5:\nعَنْ عُثْمَانَ قَالَ إِنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَوَضَّأَ ثَلاَ ثًا ثَلاَ ثًا وَقَالَ ہَذَا وُضُوءِی وَوُضُوءُ الْأَنْبِیَاءِ قَبْلِی۔ \nحدیث 6:\nعَنْ عَاءِشَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ السِّوَاکُ مَطْہَرَۃٌ لِلْفَمِ مَرْضَاۃٌ لِلرَّبِّ۔\nحدیث 7:\nعَنْ أَبِی ہُرَیْرَۃَ رَضِیَ اللّٰہ عَنْہُ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْلَا أَنْ أَشُقَّ عَلَی أُمَّتِی لَأَمَرْتُہُمْ بِتَاخِیْرِ الْعِشَاءِ وَبِالسِّوَاکِ عَنْدَ کُلِّ صَلَاۃٍ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابو مالک اشعری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ پاکیزگی نصف ایمان ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت عثمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صلی اللّٰہ تعالیٰ علیہ و آلہ و سلم نے فرمایا کہ جو شخص وضو کرے اور اچھا وضو کرے تو اس کے گناہ اس کے جسم سے نکل جاتے ہیں۔ یہاں تک کہ اس کے ناخنوں کے نیچے سے بھی نکل جاتے ہیں۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت سعید بن زید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس نے وضو کے شروع میں بسم اللّٰہ نہ پڑھی اس کا وضو (کامل) نہیں۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب کپڑا پہنو یا وضو کرو تو اپنے داہنے سے شروع کرو۔ (احمد، ابوداود)\n¥ترجمہ حدیث 5:\n حضرت عثمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے تین تین مرتبہ وضو فرمایا اور فرمایا کہ یہ میرا اور مجھ سے پہلے جو انبیائے کرام علیہم السلام تھے ان کا وضو ہے ۔ (مشکوۃ)\n¥ترجمہ حدیث 6:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ مسواک منہ کو پاک کرنے والی اور پروردگار کو راضی کرنے والی چیز ہے ۔ (احمد ، دارمی)\n¥ترجمہ حدیث 7:\n حضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اگر میں اپنی امت کے لیے دشوار نہ سمجھتا تو انہیں حکم دیتا کہ وہ عشاء کی نماز دیر سے پڑھیں اور ہر نماز کے لیے مسواک کریں۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Abu Malik Ash'ari Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke paakeezgi nisf iman hai. (Muslim Shareef). Tarjuma Hadees 2: Hazrat Usman Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs Wazu kare aur achha Wazu kare to us ke gunah us ke jism se nikal jate hain. Yahan tak ke us ke naakhunon ke neeche se bhi nikal jate hain. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Saeed Bin Zaid Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jis ne Wazu ke shuru mein Bismillah na parhi us ka Wazu (kamil) nahi. (Tirmidhi, Ibn Majah). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke jab kapra pehno ya Wazu karo to apne dahne se shuru karo. (Ahmad, Abu Dawood). Tarjuma Hadees 5: Hazrat Usman Radiyallahu Anhu ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne teen teen martaba Wazu farmaya aur farmaya ke yeh mera aur mujh se pehle jo Anbiya-e-Kiram Alaihimussalam thay un ka Wazu hai. (Mishkat). Tarjuma Hadees 6: Hazrat Aishah Radiyallahu Anha ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke miswak munh ko paak karne wali aur Parwardigar ko raazi karne wali cheez hai. (Ahmad, Darimi). Tarjuma Hadees 7: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool Sallallahu Alaihi Wasallam ne farmaya ke agar main apni ummat ke liye dushwar na samajhta to unhein hukm deta ke woh Isha ki Namaz der se parhein aur har Namaz ke liye miswak karein. (Bukhari, Muslim).", "explanation": "¥وضو کرنے کا مسنون طریقہ\n پہلے نیت کرے اور پھر بِسم اللّٰہ الرحمن الرحیم پڑھنے کے بعد کم سے کم تین تین مرتبہ اوپر نیچے کے دانتوں کی چوڑائی میں مسواک کرے نہ کہ لمبائی میں اور اس طرح کہ پہلے دا ہنی جانب کے اوپر کے دانت مانجھے پھر بائیں جانب کے اوپر کے دانت پھر داہنی جانب کے نیچے کے دانت پھر بائیں جانب کے نیچے کے دانت مانجے ۔ اس کے بعد دونوں ہاتھ پر گٹوں سمیت پانی ملے اور انگلیوں میں خلال کرے پھر بائیں ہاتھ میں لوٹا وغیرہ لے کر دائیں ہاتھ پر انگلیوں کی طرف سے شروع کرکے گٹے تک تین بار پانی بہائے پھر لوٹے کو داہنے ہاتھ میں لے کر بائیں ہاتھ پر تین بار اسی طرح پانی بہائے اور اس کا خیال رہے کہ انگلیوں کی گھائیاں پانی بہنے سے نہ رہ جائیں اور اگر حوض سے وضو کرتا ہو تو گٹوں تک ہاتھوں کو ملنے کے بعد حوض میں پہلے داہنا ہاتھ ڈال کر تین بار ہلائے اور پھر بایاں ہاتھ ڈال کر تین بار ہلائے پھر تین بار کلی اس طرح کرے کہ منہ کی تمام جڑوں اور دانتوں کی سب کھڑکیوں میں پانی پہنچ جائے اور اگر روزہ دار نہ ہو تو ہر کلی غرغرہ کے ساتھ کرے پھر بائیں ہاتھ کی چھنگلیا ناک میں ڈال کر اسے صاف کرے اور سانس کی مدد سے تین بار داہنے ہاتھ سے نرم بانسوں تک پانی چڑھائے پھر چہرے پر اچھی طرح پانی مل کر اس کو تین بار اس طرح دھوئے کہ ایک کان کی لَو سے دوسرے کان کی لَو تک اور پیشانی کے اوپر کچھ سر کے حصہ سے لے کر ٹھوڑی کے نیچے تک ہر ہر حصے پر پانی بہہ جائے اور داڑھی کے بال وکھال کو دھوئے ہاں اگر داڑھی کے بال گھنے ہوں تو کھال کا دھونا فرض نہیں صرف مستحب ہے ۔ اور داڑھی کے جو بال منہ کے دائرے سے نیچے ہیں ان کو بھی دھوئے اور داڑھی کا خلال کرے اس طرح کہ انگلیوں کو گردن کی طرف سے داخل کرے اور سامنے نکالے ۔ پھر دونوں ہاتھوں پر کہنیوں سمیت پانی مل کر پہلے داہنے ہاتھ پر اور پھر بائیں ہاتھ پر سرِ ناخن سے شروع کرکے کہنیوں کے اوپر تک بال اور ہر حصہ کھال پر تین بار پانی بہائے ۔ پھر سرکا مسح اس طرح کرے کہ دونوں ہاتھوں کے انگوٹھے اور کلمہ کی انگلیاں چھوڑ کر باقی تین تین انگلیوں کے سرے ملا کر پیشانی کے بال اُگنے کی جگہ پر رکھے اور سر کے اوپری حصہ پر گدی تک انگلیوں کے پیٹ سے مسح کرتا ہوا لے جائے اور ہتھیلیاں سر سے جدا رہیں پھر وہاں سے ہتھیلیوں سے سر کی دونوں کروٹوں کا مسح کرتے ہوئے پیشانی تک واپس لائے ۔ یا تین تین انگلیاں سر کے اگلے حصے پر رکھے اور ہتھیلیاں سر کی کروٹوں پر جمائے ہوئے گدی تک کھینچتا لے جائے اور بس پھر اس کے بعد کلمہ کی انگلیوں کے پیٹ سے کان کے اندرونی حصہ کا مسح کرے اور انگوٹھے کے پیٹ سے کان کے باہری حصہ کا مسح کرے اور انگلیوں کی پیٹھ سے گردن کا مسح کرے پھر پاؤں پر ٹخنوں سمیت پانی ملے اور پہلے داہنے پاؤں پھر بائیں پاؤں پر انگلیوں کی طرف سے ٹخنوں کے اوپر تک ہر بال اور ہر حصہ کھال پرتین تین بار پانی بہائے اور انگلیوں میں خلال بائیں ہاتھ کی چھنگلیا سے اس طرح کرے کہ دہانے پاؤں کی چھنگلیا سے شروع کرکے انگوٹھے پر ختم کرے اور بائیں پاؤں میں انگوٹھے سے شروع کرکے چھنگلیا پر ختم کرے اور ہر عضو دھوتے وقت درود شریف پڑھتا ر ہے کہ افضل ہے ۔\n¥ضروری انتباہ: \n (۱)… کسی عضو کے دھونے کے یہ معنی ہیں کہ اس عضو کے ہر حصہ پر کم سے کم دو بوند پانی بہہ جائے ۔ ([1])\n (بہار شریعت، جلد دوم ص۹۳)\n اور درمختار مع ردالمحتار جلد اول ص:۶۷ میں ہے ’’ إسَالَۃُ الْمَاءِ مَعَ التَّقَاطُرِ وَلَوْ قَطْرَۃً وَفِی ’’ الْفَیْضِ ‘‘ أَقَلُّہُ قَطْرَتَانِ فِی الْأَصَحِّ ‘‘ اس عبارت کا حاصل معنی یہ ہے کہ تقاطر کے ساتھ پانی بہایا جائے اس طرح کہ عضو کے ہر حصہ پر کم سے کم دو بوند پانی بہہ جائے ۔ ([2])\n اور فتاویٰ عالمگیری جلد اول مصری ص:۴ میں ہے ’’ لَا یَجُوزُ الْوُضُو ء مَا لَمْ یَتَقَاطَرْ الْمَاء ‘‘ یعنی جب تک کہ اعضائے وضو کے ہر حصہ پر پانی کی بوندیکے بعد دیگرے نہ گزر جائے وضو نہ ہوگا۔ ([3])\n عنایہ شرح ہدایہ میں ہے ۔ ’’ اَلْبَلَلُ بِالْمَاء فِی الْمَغْسُولَاتِ لَا یُسْقِطُ الْفَرْضَ ‘‘ یعنی جن اعضاء کا دھونا فرض ہے انہیں صرف پانی سے بھگولینے پر فرض ادا نہ ہوگا۔ ([4]) \n لہذا جو لوگ وضو کرتے وقت اعضاء پر تیل کی طرح پانی صرف چپڑ لیتے ہیں یا بعض حصہ پر تو پانی بہاتے ہیں اور بعض حصے کو صرف بھگو کر چھوڑ دیتے ہیں۔ مثلاً پیشانی کے بالائی حصے ، کان کے کنارے ، ہاتھ کی کہنیوں اور پاؤں کے ٹخنوں پر تر ہاتھ صرف پھیر لیتے ہیں اور پانی نہیں بہاتے ہیں اِن کا وضونہیں ہوتا اس لیے کہ قرآن کریم نے اعضاء کے دھونے کا حکم دیا ہے لہذا صرف بھگونے سے وضو نہ ہوگا۔\n افسو س صد افسوس آج عوام تو عوام اکثر خواص بھی اس مسئلہ سے لاپرواہی برتتے ہیں اور آیت کریمہ { عَامِلَةٌ نَّاصِبَةٌۙ(۳)تَصْلٰى نَارًا حَامِیَةًۙ(۴) }کے مصداق بنتے ہیں۔ ( یعنی کام کریں، مشقت جھیلیں جائیں بھڑکتی آگ میں) العیاذ باللّٰہ تعالیٰ ۔\n (۲)… جب چھوٹے برتن مثلاً لوٹے یا بدھنے سے وضو کررہا ہو تو گٹوں تک ہاتھ دھونے کا مسنون طریقہ یہ ہے کہ پہلے دونوں گٹوں تک ہاتھ خوب بھگولے ۔ اس کے بعد بائیں ہاتھ میں برتن اُٹھا کر داہنے ہاتھ پر سرِ ناخن سے گٹے کے اوپر تک تین بار پانی بہائے پھر اسی طرح داہنے ہاتھ میں برتن اٹھا کر بائیں ہاتھ پر گٹے تک تین بار پانی بہائے ۔ جیسا کہ شرح وقایہ جلد اول مجیدی کان پورص:۵۹، طحطاوی مصری ص:۳۹، فتاویٰ عالمگیری جلد اول مصری ص:۶ ، اور عنایہ و کفایہ شروح ہدایہ میں ہے ’’ وَاللَّفْظُ لِلْفَتَاوٰی اَلْہِنْدِیَۃ کَیْفِیَّتُہُ إنْ کَانَ الْإِنَاءُ صَغِیرًا أَنْ یَأْخُذَہُ بِشِمَالِہِ وَیَصُبَّ الْمَاءَ عَلَی یَمِینِہِ ثَلَاثًا ثُمَّ یَأْخُذَہُ بِیَمِینِہِ وَیَصُبَّہُ عَلَی یَسَارِہِ کَذَلِکَ ‘‘([5])\n اور مراقی الفلاح مع طحطاوی مصری ص:۴۴ میں ہے ۔ ’’ وَیَسنّالبِدَا ۃُ ءبِالغَسْلِ مِنْ رُؤوْس الأَصَابِع ‘‘([6])\n (۳)… بہت سے لوگ یوں کر تے ہیں کہ ناک یا آنکھ یا بھوؤں پر چلّو ڈال کر سارے منہ پر ہاتھ پھیر لیتے ہیں اور یہ سمجھتے ہیں کہ منہ دُھل گیا حالانکہ پانی کا اوپر چڑھنا کوئی معنی نہیں رکھتا اس طرح منہ دھلنے میں منہ نہیں دُھلتا اور وضو نہیں ہوتا۔ ([7])\n (۴)… وضو کرنے میں مندرجہ ذیل باتوں کی احتیاط ضروری ہے ۔ پیشانی کے اوپر بال جمنے کی جگہ سے پانی کا بہنا فرض ہے ۔ داڑھی مونچھ اوربھوؤں کے بال اگر اتنے چھدرے ہوں کہ نیچے کی کھال جھلکتی ہو تو کھال پر پانی بہانا ضروری ہے صرف بالوں کا دھونا کافی نہیں۔ آنکھ اندر گھسی ہو تو آنکھ اور بھوؤں کے درمیانی حصہ پر پانی بہانے کا خاص خیال رکھے ۔ منہ دھوتے وقت آنکھیں اور ہونٹ سمیٹ کر زور سے بند نہ کر ے ورنہ کچھ حصہ رہ جانے کی صورت میں وضو نہ ہوگا۔ بعض وقت آنکھ میں کیچڑ وغیرہ سخت ہو کر جم جاتا ہے اسے چھڑ ا کر پانی بہانا ضروری ہے ۔ رخسار اور کان کے درمیانی حصہ یعنی کنپٹی پر کان کے کنارے تک پانی بہانا فرض ہے اس سے اکثر لوگ غفلت برتتے ہیں۔ ناک کے سوراخ میں کیل وغیرہ ہو یا نہ ہو بہرحال اس پر پانی ڈالنا ضروری ہے ۔ جتنی داڑھی چہرے کی حد میں ہو اس کا دھونا فرض ہے اور لٹکی ہوئی داڑ ھی کا مسح کرنا سنت اور دھونا مستحب ہے ۔ پانی بہانے میں انگلیوں کی گھائیوں اور کروٹوں کا لحاظ ضروری ہے خصوصاً پاؤں میں کہ اس کی انگلیاں قدرتی طور پر ملی رہتی ہیں۔ بڑھے ہوئے ناخنوں کے اندر جو جگہ خالی ہو اس کا دُھلنا ضروری ہے ۔ ناخنوں کے سرے سے کہنیوں کے اوپر تک ہاتھ کا ہر پہلو اور ایک ایک بال کا جڑ سے نوک تک دھل جانا ضر وری ہے چلو میں پانی لے کر کلائی پر الٹ دینا ہر گز کافی نہ ہوگا۔ کہنیوں پر پانی بہانے کا خاص خیال رکھے کہ اکثر بے احتیاطی میں دھلتی نہیں صرف تر ہو کر رہ جاتی ہیں بلکہ بعض لوگوں کی کہنیاں تر بھی نہیں ہوتیں۔ انگوٹھی ، چوڑی ، کلائی کے زیورات اور پاؤں کے ہر وہ زیور جو ٹخنے پر یا ٹخنے سے نیچے ہوں انہیں ہٹا کر ان کے نیچے پانی بہانا ضروری ہے ۔ پورے سر کا مسح سنت ہے ۔ اور چوتھائی سر کا مسح فرض ہے ۔ بعض لوگ صرف انگلیوں کے سرے سر پر گزار دیتے ہیں جو فرض کی مقدار کو بھی کافی نہیں ہوتا اور بعض لوگوں کا مسح یہ ہے کہ ٹوپی اٹھا کر پھر سر پر رکھ دیتے ہیں اور بس۔ ایسے لوگوں کا وضو نہیں ہوتا اور ان کی نمازیں بے کار ہوتی ہیں۔ پاؤں دھونے میں ٹخنوں ، تلوؤں ، ایڑیوں اور کونچوں کا خاص طور پر خیال رکھیں کہ اکثر بے احتیاطی میں یہ حصے دھلنے سے رہ جاتے ہیں اور وضو نہیں ہوتا۔\n (۵)… عضو کے ہر حصہ پر تین بار پانی بہانا سنت ہے خواہ تین بار پانی بہانے کے لیے کئی چلو پانی لینا پڑے اس لیے کہ تین چلو پانی لینا سنت نہیں بلکہ پورے عضو پر تین بار پانی بہا نا سنت ہے جیسا کہ درمختار مع شامی جلد اول ص:۸۳میں ہے ’’ وَتَثْلِیثُ الْغَسْلِ الْمُسْتَوْعِبِ وَلَا عِبْرَۃَ لِلْغَرَفَاتِ ‘‘([8]) لہذا تین چلو پانی لینے کو سنت سمجھنا غلطی ہے ۔\n (۶)… وضو کے پانی کے لیے شرعاً کوئی مقدار معین نہیں جیسا کہ مرقاۃ شرح مشکوۃ جلد اول ص:۳۲۶ میں ہے ۔ ’’ الإِجْمَاعُ عَلَی أَنَّہُ لَا یُشْتَرطُ قَدْرٌ مُعَیَّنٌ فِی مَاء الْوُضُوءِ وَالغُسْلِ ‘‘([9])\n لہذا اتنا زیادہ پانی خرچ نہ کرے کہ اسراف ہو اور نہ اس قدر کم خرچ کرے کہ سنت ادا نہ ہو۔ بعض لوگ صرف ایک چھوٹے سے پانی کے لوٹے سے وضو بنانے کی کوشش کرتے ہیں۔ خدائے تعالیٰ انہیں دھونے اور بھگونے کا فرق سمجھنے کی توفیق عطا فرمائے ۔ آمین۔\n (۷)… اگر اتنا پانی نہ ہو کہ وضو میں ہر عضو کو تین تین بار دھویا جاسکے تو دو دو بار دھوئے اور اگر دو دو بار دھونے کے کافی نہ ہو تو ایک ایک بار دھوئے اور اگر اتنا بھی نہ ہو کہ منہ اور دونوں ہاتھ کہنیوں سمیت اور دونوں پاؤں ٹخنوں سمیت ایک بار دھوسکے تو اب تیمم کرکے نماز پڑھے ۔\n (۸)… غیر کے نابالغ لڑکے سے بلا معاوضہ پانی بھروا کر وضو کرنا یا کسی دوسرے کام میں لانا جائز نہیں۔ ([10]) (بہار شریعت) درمختار مع شامی جلد چہارم ص:۵۳۱ میں ہے ’’ لَا تَصِحُّ ہِبَۃُ صَغِیرٍ ‘‘([11])\n (۹)… بعض مسجدوں میں چھوٹے حوض یا کسی بڑے برتن میں پانی ہوتا ہے اکثر لوگ جو بے وضو ہوتے ہیں ہاتھ دھوئے بغیر چھوٹے برتن سے پانی نکالتے ہوئے انگلی کا پور یا ناخن پانی میں داخل کردیتے ہیں اس طرح وہ پانی مستعمل ہوجاتا ہے ۔ اس سے وضو کرنا جائز نہیں۔\n (۱۰)… ڈول، بالٹی ، گھڑا ، لوٹا یا پاٹ کے پانی میں بے وضو آدمی کے بے دھُلے ہاتھ کا ناخن یا انگلی کا پور چلا گیا تو وہ پانی مستعمل ہوگیا۔ اس سے وضو کرنا جائز نہیں۔ اور اگر پہلے ہاتھ دُھولیا تو جو حصہ دُھلا ہو اسے پانی میں ڈال سکتے ہیں پانی مستعمل نہ ہوگا لیکن اگر ہاتھ دھولینے کے بعد کوئی سبب وضو ٹوٹنے کا پایا گیا مثلاً ریاح خارج ہوئی یا پیشاب کیا تو اب ہاتھ ڈالنے سے پانی مستعمل ہوجائے گا۔\n (۱۱)… مستعمل پانی کو وضو کے قابل بنانے کا طریقہ یہ ہے کہ جو پانی مستعمل نہ ہو اسے مستعمل میں اس قدر ملادیا جائے کہ مستعمل کم اور غیر مستعمل زیادہ ہوجائے ۔ یا مستعمل کے برتن میں غیر مستعمل پانی اتنا ڈالا جائے کہ وہ برتن بھر کر بہنے لگے تو سب پانی قابلِ وضو ہوجائے گا۔ ([12]) (درمختار مع رد المحتار)\n (۱۲)… ناخن پالش استعمال کیا جس سے ناخنوں پر ہلکی تہ جم گئی تو اگر ناخنوں سے پالش صاف کیے بغیر وضو کیا تو وضو نہ ہوا۔\n (۱۳)… استنجاء کے بچے ہوئے پانی سے وضو کرنا جائز ہے اسے پھینک دینا سخت ناجائز و گناہ ہے ۔\n (۱۴)… وضو کے بچے ہوئے پانی کو پھینک دینا حرام ہے اور کھڑے ہو کر پینا ثواب ہے ۔\n (۱۵)… جو وضو نمازِ جنازہ کے لیے کیا گیا اس سے ہر نماز پڑھ سکتے ہیں۔\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۲۸۸.\n[2] ’’ الدر المختار ورد المحتار ‘ ‘، کتاب الطھارۃ ، باب أرکان الوضوء أربعۃ ، مطلب فی الفرض القطعی والظنی ، ج ۱، ص۲۱۷.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الطھارۃ ، الفصل الأول فی فرائض الوضوء ، ج ۱، ص ۳.\n[4] ’’ العنایۃ شرح الہدایۃ ‘‘، کتاب الطھارۃ ، ج ۱، ص ۱۲.\n[5] ’’ الفتاوی الھندیۃ ‘‘ کتاب الطھارۃ ، الفصل الثانی فی سنن الوضوء ، ج ۱، ص ۶، ’’ شرح الوقایۃ ‘‘، باب سنن الوضوء إلخ ، ص ۶۲، ’’ العنایۃ شرح الھدایۃ ‘‘، کتاب الطہارۃ ، ج ۱، ص ۱۸، ’’ الکفایۃ شرح الھدایۃ ‘‘ ، کتاب الطہارۃ ، ج ۱، ص ۱۹، ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، فصل فی سنن الوضوء ، ص ۶۶.\n[6] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، کتاب الطہارۃ ، فصل فی سنن الوضوء ، ص ۷۴.\n[7] ’’بہارِ شریعت‘‘، ج۱، ص ۲۹۸.\n[8] ’’ الدر المختار ورد المحتار ‘‘، کتاب الطھارۃ ، مطلب فی منافع الصلاۃ ، ج ۱، ص ۲۵۷.\n[9] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الطھارۃ ، الحدیث : ۴۳۹، ج ۲، ص ۱۴۳.\n[10] ’’بہارِ شریعت‘‘، ج۱، ص ۳۳۴.\n[11] ’’ الدر المختار ورد المحتار ‘‘، کتا ب الہبۃ ، ج ۸، ص ۵۶۸.\n[12] ’’ الدر المختار ورد المحتار ‘‘، کتاب الطھارۃ ، باب المیاہ ، ج ۱، ص ۳۶۲."}, {"id": 7781, "bookId": 14, "volNo": "1", "hadithNo": 13, "chapter": "وضو توڑنے والی چیزیں", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ عَلِیِّ بْنِ طَلْقٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا فَسَا أَحَدُکُمْ فَلْیَتَوَضَّأْ۔\nحدیث 2:\n عَنْ عَلِیٍّ قَالَ سَءَلْتُ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنِ الْمَذْیِ فَقَالَ مِنَ الْمَذْیِ اَلْوَُضُوْء۔ \nحدیث 3:\nعَن ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الْوُضُوءَ عَلَی مَنْ نَامَ مُضْطَجِعًا فَإِنَّہُ إِذَا اضْطَجَعَ اسْتَرَخَتْ مَفَاصِلُہُ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت علی بن طلق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جب تم میں سے کسی کی ہوا خارج ہو تو وہ وضو کرے ۔ (ترمذی، ابوداود)\n¥ترجمہ حدیث 2:\nحضرت علی کرم اللّٰہ تعالیٰ وجہہ نے فرمایا کہ میں نے نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم سے مذی کے متعلق دریافت کیا توحضور صلی اللّٰہ علیہ وآلہ وسلم نے فرمایا کہ مذی نکلنے سے وضو واجب ہو جاتا ہے ۔ (یعنی وضو ٹوٹ جاتا ہے )۔ (ترمذی)\n¥ترجمہ حدیث 3:\n حضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص لیٹ کر نیند سے سو جائے اس پر وضو واجب ہے اس لیے کہ جب آدمی لیٹتا ہے تو اس کے جوڑ ڈھیلے پڑ جاتے ہیں۔ (ترمذی ، ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Ali Bin Talq Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab tum mein se kisi ki hawa kharij ho to woh Wazu kare. (Tirmidhi, Abu Dawood). Tarjuma Hadees 2: Hazrat Ali Karamallahu Wajhah ne farmaya ke main ne Nabi-e-Kareem Sallallahu Alaihi Wasallam se Mazi ke muta'alliq daryaft kiya to Huzoor Sallallahu Alaihi Wasallam ne farmaya ke Mazi nikalne se Wazu Wajib ho jata hai (ya'ni Wazu toot jata hai). (Tirmidhi). Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs lait kar neend se so jaye us par Wazu Wajib hai is liye ke jab aadmi laitta hai to us ke jor dheelay par jate hain. (Tirmidhi, Abu Dawood).", "explanation": "¥انتباہ:\n (۱)… انبیائے کرام علیہم الصلوۃ والسلام کا سونا ناقض وضو نہیں اس لیے کہ ان کی آنکھیں سوتی ہیں اور دل بیدار رہتا ہے ۔ (1) (بہار شریعت ، جلد دوم ص ۱۰۷)\n درمختار نیز ردالمحتار جلد اول ص:۱۰۱ ، اور بحرالرائق جلد اول ص:۳۹میں ہے ’’ وَاللَّفْظُ لِلبَحْرِ الرَّاءِقِ أَنَّ النَّوْمَ مُضْطَجِعًا نَاقِضٌ إلَّا فِی حَقِّ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَرَّحَ فِی الْقُنْیَۃِ ‘‘۔ (2)\n اور سعایہ جلد اوّل ص: ۲۳۶ میں ہے ’’ أَنَّ نَوْمَہُ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَیْسَ بِنَاقِضٍ لِقَوْلِہِ تَنَامُ عَیْنَای وَلَا یَنَامُ قَلْبِیْ کَمَا نَصَّ عَلَیْہِ جَمْعٌ مِمَّن صَنَّفُوْا عَلَیْہِ فِی الْخَصَائصِ اھـ ‘‘(3)\n اور بخاری شریف جلد اول ص:۵۰۴میں ہے ’’ الْأَنْبِیَاءُ تَنَامُ أَعْیُنُہُمْ وَلَا تَنَامُ قُلُوبُہُمْ ‘‘( الحدیث ) یعنی انبیائے کر ام علیہم السلام کی آنکھیں سوتی ہیں اور ان کے قلوب بیدار رہتے ہیں۔ (4)\n (۲)… عوام میں جومشہور ہے کہ گھٹنا یا ستر کھلنے اپنا یا پرایا ستر دیکھنے سے وضو جاتا رہتا ہے تو صحیح نہیں ہے ۔ (5) (بہار شریعت، جلد دوم)\n (۳)…مندرجہ ذیل چیزوں سے وضو ٹوٹ جاتا ہے ۔\n پا خانہ، پیشاب ، ودی ، مذی، منی، کیڑا، پتھری مرد یا عورت کے آگے یا پیچھے سے نکلنا۔ مرد یا عورت کے پیچھے سے ہوا خارج ہونا۔ خون یا پیپ یا زرد پانی کا کہیں سے نکل کر ایسی جگہ بہنا جس کا وضو یا غسل میں دھونا فرض ہے ۔ کھانا یا پانی یا صفرا کی منہ بھر قے آنا۔ اس طرح سوجانا کہ جسم کے جوڑ ڈھیلے پڑجائیں۔ بے ہوش ہونا، جنون ہونا، غشی ہونا، کسی چیز کا اتنا نشہ ہونا کہ چلنے میں پاؤں لڑکھڑائیں۔ بالغ آدمی کا رکوع و سجود والی نماز میں اتنی زور سے ہنسنا کہ آس پاس والے سنیں۔ دھکتی آنکھ سے آنسو بہنا، ( اور یہ آنسو ناپاک ہے ) مباشرت فاحشہ یعنی مرد اپنے آلہ کو تندی کی حالت میں عورت کی شرمگاہ یا کسی مرد کی شرمگاہ سے ملائے ۔ یا عورت عورت باہم ملائیں بشرطیکہ کوئی شے حائل نہ ہو نا قض وضو ہے ۔ (6) (بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۳۰۸.\n[2] ’’ الدر المختار وردالمحتار ‘‘، کتاب الطھارۃ ، مطلب نوم الأنبیاء غیر ناقض ، ج ۱، ص ۲۹۸، ’’ البحر الرائق ‘‘، کتاب الطھارۃ ، باب نواقض الوضوء ، ج ۱، ص ۷۵.\n[3] ’’ سعایہ ‘‘ ج ۱، ص ۲۳۶. \n[4] ’’ صحیح البخاری ‘‘، کتاب المناقب ، باب کان النبی صلی اللّٰہ علیہ وسلم تنام عیناہ ولا ینام قلبہ ، الحدیث : ۳۵۷۰، ۲، ص ۴۹۲.\n[5] ’’بہار ِ شریعت‘‘، ج۱، ص ۳۰۹.\n[6] ’’بہارِ شریعت‘‘، ج۱، ص ۳۰۳۔ ۳۰۷."}, {"id": 7782, "bookId": 14, "volNo": "1", "hadithNo": 14, "chapter": "استنجا کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ أَنَسٍ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاء نَزَعَ خَاتَمَہُ۔ \nحدیث 2:\nعَنْ أَنَسٍ قَالَ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاءَ یَقُولُ أَللَّہُمَّ إِنِّی أَعُوذُ بِکَ مِنْ الْخُبُثِ وَالْخَبَاءِثِ۔\nحدیث 3:\nعَنْ أَبِی أَیُّوبَ الْأَنْصَارِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَتَیْتُمْ الْغَاءِطَ فَلَا تَسْتَقْبِلُوا الْقِبْلَۃَ وَلَا تَسْتَدْبِرُوہَا۔\nحدیث 4:\nعَنْ أَنَسٍ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَرَادَ الْحَاجَۃَ لَمْ یَرْفَعْ ثَوْبَہُ حَتَّی یَدْنُوَ مِنْ الْأَرْضِ۔\nحدیث 5:\nعَنْ عَبْدِ اللّٰہ بْنِ سَرْجِسَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَبُولَنَّ أَحَدُکُمْ فِی جُحْرٍ۔\nحدیث 6:\nعَنْ عُمَرَ قَالَ رَآنِی النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَأَنَا أَبُولُ قَاءِمًا فَقَالَ یَا عُمَرُ لَا تَبُلْ قَاءِمًا فَمَا بُلْتُ قَاءِمًا بَعْدُ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرتِ انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم جب استنجاء خانہ میں جاتے تواپنی انگوٹھیاتار دیتے ( اس لیے کہ اس پر’’ مُحَمَّدٌ رَّسُوْلُ اللّٰہ ‘‘نقش تھا)۔ (ابوداود، ترمذی)\n¥ترجمہ حدیث 2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم جب استنجاء خانہ میں داخل ہوتے تو أَللَّھُمَّ إِنِّی أَعُوذ بِکَ مِنَ الخُبثِ والخبَائث ۔\n¥ترجمہ حدیث 3:\nحضرت ابو ایوب انصاری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جب تم پاخانہ ( یا پیشاب) کے لیے جاؤ تو قبلہ کی طرف منہ نہ کرو اور نہ اس کی جانب پیٹھ کرو۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم جب قضائے حاجت کا ارادہ فرماتے تو جب تک بیٹھتے ہوئے زمین کے قریب نہ پہنچ جاتے کپڑا نہ اٹھاتے ۔ (ترمذی، ابوداود)\n¥ترجمہ حدیث 5:\nحضرت عبد اللّٰہ بن سرجس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ تم میں سے کوئی شخص سوراخ کے اندر ہر گز پیشاب نہ کرے ۔ (ابوداود، نسائی)\n¥ترجمہ حدیث 6:\nحضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے مجھے اس حال میں دیکھا کہ میں کھڑے ہوکر پیشاب کرر ہا تھا تو حضور صلی اللّٰہ تعالی علیہ وسلم نے فرمایا کہ اے عمرکھڑے ہو کر پیشاب نہ کرو اس کے بعد میں نے کھڑے ہو کر کبھی پیشاب نہ کیا ۔ (ترمذی، ابن ماجہ)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne farmaya ke Nabi-e-Kareem Sallallahu Alaihi Wasallam jab Istinja khana mein jate to apni angoothi utaar dete (is liye ke us par 'Muhammadur Rasoolullah' naqsh tha). (Abu Dawood, Tirmidhi). Tarjuma Hadees 2: Hazrat Anas Radiyallahu Anhu ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam jab Istinja khana mein dakhil hote to Allahumma inni a'oodhu bika minal khubthi wal khaba'ith. Tarjuma Hadees 3: Hazrat Abu Ayyub Ansari Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab tum paakhana (ya peshaab) ke liye jao to Qiblah ki taraf munh na karo aur na us ki janib peeth karo. (Bukhari, Muslim). Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam jab Qaza-e-hajat ka irada farmate to jab tak baithte hue Zameen ke qareeb na pahunch jate kapra na uthate. (Tirmidhi, Abu Dawood). Tarjuma Hadees 5: Hazrat Abdullah Bin Sarjas Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke tum mein se koi shakhs soorakh ke andar hargiz peshaab na kare. (Abu Dawood, Nasai). Tarjuma Hadees 6: Hazrat Umar Radiyallahu Anhu ne farmaya ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne mujhe is haal mein dekha ke main kharay ho kar peshaab kar raha tha to Huzoor Sallallahu Alaihi Wasallam ne farmaya ke Ae Umar kharay ho kar peshaab na karo, us ke baad main ne kharay ho kar kabhi peshaab na kiya. (Tirmidhi, Ibn Majah).", "explanation": "¥شرح حدیث 1:\nحضرتِ شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت فرماتے ہیں کہ:\n’’ از یں جا معلوم شد کہ داخل متوضا رابایدکہ چیز ے را کہ دروے نامِ خدا ورسول خدا وقرآن ست باخود نبرد ودر بعض شروح گفتہ کہ ایں شامل ، ست اسمائے تمام انبیاء را صلوت اللّٰہ وتسلیماتہ علیہم اجمعین ‘‘(1)\nیعنی اس حدیث سے معلوم ہوا کہ بیت الخلاء میں داخل ہونے والے کو چاہیے کہ ایسی چیز کہ اس میں خدا اور رسول کا نام یا قرآن کا کوئی کلمہ ہو تو اسے اپنے ہمراہ نہ لے جائے اور بعض شروح میں کہا گیا ہے کہ یہ حکم انبیاء کرام علیہم الصلوۃ والسلام کے اسماء کو بھی شامل ہے ۔ (اشعۃ اللمعات، جلد اول ، ص ۲۰۱)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الطھارۃ ، باب آداب الخلاء ، الفصل الأول ، ج ۱، ص ۲۱۷.\n¥شرح حدیث 3:\n حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اسی باب الاستنجاء میں فرماتے ہیں کہ:\n’’ مذہب امام اعظم ابوحنیفہ آن ست کہ استقبال قبلہ واستدبار آں در بول و غائط حرام ست چہ در صحراء و چہ در خانہا ‘‘(1)\n یعنی حضرت امام اعظم ابوحنیفہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کا مذہب یہ ہے کہ پیشاب و پاخانہ کرنے میں قبلہ کی جانب منہ یا پیٹھ کرنا حرام ہے خواہ جنگل میں ہو یا گھروں میں۔ (اشعۃ اللمعات جلد اول ص۱۹۸)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الطھارۃ ، باب آداب الخلاء ، الفصل الأول ، ج ۱، ص ۲۱۳.\n¥انتباہ:\n (۱)… طہارت کے بچے ہوئے پانی سے وضو کرسکتے ہیں اسے پھینک دینا اسراف ہے ۔ (1)(بہارشریعت)\n (۲)… تہبند اور لنگی پہننے والے پیشاب کرنے کے لیے لوگوں کے سامنے ران اور گھٹنا کھول کر بیٹھ جاتے ہیں یہ ناجائز و حرام ہے ۔ اس لیے کہ لو گوں کے سامنے ستر بالا جماع فرض ہے ۔ (2)(بہار شریعت)\n اور جیسا کہ ردالمحتار جلد اول ص:۲۸۲میں ہے : ’’ إذَا کَانَ خَارِجَ الصَّلَاۃِ یَجِبُ السَّتْرُ بِحَضْرَۃِ النَّاسِ إجْمَاعًا ‘‘ (3)\n اور درمختار میں ہے : ’’ ہِیَ لِلرَّجُلِ مَا تَحْتَ سُرَّتِہِ إلَی مَا تَحْتَ رُکْبَتِہِ ‘‘(4)\n اور فتاویٰ عالمگیری جلد اول مصری ص:۵۴میں ہے ’’ رُکْبَتُہُ عَوْرَۃٌ عِنْدَ عُلَمَاءِنَا جَمِیعًا ہَکَذَا فِی الْمُحِیطِ ‘‘(5)\nٍ اور بہارِ شریعت جلد سوم ص:۲۵۰ میں ہے کہ بعض بے باک ایسے ہیں کہ لوگوں کے سامنے گھٹنے بلکہ ران تک کھولے رہتے ہیں یہ بھی حرام ہے اور اس کی عادت ہے تو فاسق ہے ۔ (6)\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص۴۱۳.\n[2] ’’بہار شریعت‘‘، ج۱، ص ۴۷۹.\n[3] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب شروط الصلاۃ ، مطلب فی سترالعورۃ ، ج ۲، ص ۹۳.\n[4] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، باب شروط الصلاۃ ، مطلب فی سترالعورۃ ، ج ۲، ص ۹۳.\n[5] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الأول فی الطھارۃ وستر العورۃ ، ج ۱، ص ۵۸.\n[6] ’’بہارِ شریعت‘‘، ج۱، ص۴۸۱."}, {"id": 7783, "bookId": 14, "volNo": "1", "hadithNo": 15, "chapter": "غسل کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ عَاءِشَۃَ قَالَتْ سُءِلَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنْ الرَّجُلِ یَجِدُ الْبَلَلَ وَلَا یَذْکُرُ احْتِلَامًا قَالَ یَغْتَسِلُ وَعَنْ الرَّجُلِ یَرَی أَنَّہُ قَدْ احْتَلَمَ وَلَا یَجِدُ بَلَلًا قَالَ لَا غُسْلَ عَلَیْہِ قَالَتْ أُمُّ سُلَیْمٍ ہَلْ عَلَی الْمَرْأَۃِ تَرَی ذَلِکَ غُسْلٌ قَالَ نَعَمْ إِنَّ النِّسَاءَ شَقَاءِقُ الرِّجَالِ۔\nحدیث 2:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا جَلَسَ أَحَدُکُمْ بَیْنَ شُعَبِہَا الْأَرْبَعِ ثُمَّ جَہَدَہَا فَقَدْ وَجَبَ الْغُسْلُ وَإِنْ لَمْ ینزِلْ۔\nحدیث 3:\nعَنْ عَائشَۃَ رَضِیَ اللّٰہ عَنْہَا قَالَتْ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَانَ جُنُبًا فَأَرَادَ أَنْ یَأْکُلَ أَوْ یَنَامَ تَوَضَّأَ وُضُو ء ہُ لِلصَّلَاۃِ۔ \nحدیث 4:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَحْتَ کُلِّ شَعْرَۃٍ جَنَابَۃٌ فَاغْسِلُوا الشَّعْرَ وَأَنْقُوا الْبَشَرَۃَ۔\nحدیث 5:\nعَنْ عَائشَۃَ رَضِیَ اللّٰہ عَنْہَا قَالَتْ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنْ الْجَنَابَۃِ بَدَأَ فَغَسَلَ یَدَیْہِ ثُمَّ یَتَوَضَّأُ کَمَا یَتَوَضَّأُ لِلصَّلَاۃِ ثُمَّ یُدْخِلُ أَصَابِعَہُ فِی الْمَاءِ فَیُخَلِّلُ بِہَا أُصُولَ شَعْرِہِ ثُمَّ یَصُبُّ عَلَی رَأْسِہِ ثَلاثَ غُرَفَاتٍ بِیَدَیْہِ ثُمَّ یُفِیضُ الْمَاء عَلَی جِلْدِہِ کُلِّہِ وَفِیْ رِوَایَۃِ الْمُسْلِمِ یَبْدَأُ فَیَغْسِلُ یَدَیْہِ قَبْلَ أَنْ یُدْخِلَھُمَا الْإِنَاء ثُمَّ یُفْرِغُ بِیَمِینِہِ عَلَی شِمَالِہِ فَیَغْسِلُ فَرْجَہُ ثُمَّ یَتَوَضَّأُ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے فرمایا کہ رسولِ کریم علیہ الصلاۃ والتسلیم سے اس مرد کے بارے میں دریافت کیا گیا کہ جو تری پائے اور احتلام یاد نہ ہو۔ فرمایا غسل کرے اور اس شخص کے بارے میںپوچھا گیا جسے خواب کا یقین ہے اور تری نہیں پاتا فرمایا اس پر غسل نہیں۔ حضرت اُمّ سلیم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے عرض کیا۔ کیا عورت اس کو دیکھے تو اس پر غسل ہے ؟فرمایا ہاں، عورتیں مردوں کی مثل ہیں۔ (ترمذی، ابوداود)\n¥ترجمہ حدیث 2:\n حضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب تمہیں کوئی عورت کی چاروں شاخوں یعنی ہاتھوں اور پاؤں کے درمیان بیٹھے پھر کوشش یعنی ہم بستری کرے تو غسل واجب ہوگیا اگرچہ منی نہ نکلے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ نبی کر یم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم جب جنب ہوتے پھر کچھ کھانے یا سونے کا ارادہ فرماتے تو وضو کرلیتے جس طرح کہ نماز کے لیے وضو کیا جاتا ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ ہر بال کے نیچے جنابت کا اثر ہے اس لیے ہر بال دھوؤ اور بدن کو صاف ستھرا کرو۔ (ابوداود، ترمذی)\n¥ترجمہ حدیث 5:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم جب جنابت کا غسل فرماتے تو ابتدا ء یوں کرتے کہ پہلے ہاتھ دھوتے پھر نماز کے جیسا وضو کرتے پھر انگلیاں پانی میں ڈال کر اِن سے بالوں کی جڑیں تر فرماتے پھر سر پر دونوں ہاتھ سے تین چلو پانی ڈالتے پھر تمام بدن پر پانی بہاتے اور امام مسلم کی روایت میں ہے کہ حضور (جب غسل) شر وع فرماتے تو ہاتھوں کو بر تن میں داخل کرنے سے پہلے دھولیتے پھر داہنے ہاتھ سے بائیں ہاتھ پر پانی ڈالتے بعد ہ اپنی شر مگاہ دھوتے پھر وضو فرماتے ۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Aishah Radiyallahu Anha ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam se us mard ke bare mein daryaft kiya gaya ke jo tari paye aur Ihtilaam yaad na ho. Farmaya Ghusl kare aur us shakhs ke bare mein poocha gaya jisay khwab ka yaqeen hai aur tari nahi pata farmaya us par Ghusl nahi. Hazrat Umm-e-Sulaim Radiyallahu Anha ne arz kiya, kya aurat is ko dekhe to us par Ghusl hai? Farmaya haan, auratein mardon ki misl hain. (Tirmidhi, Abu Dawood). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke jab tumhein koi aurat ki charon shakhon ya'ni hathon aur paon ke darmiyan baithay phir koshish ya'ni hum-bistari kare to Ghusl Wajib ho gaya agarche Mani na nikle. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Aishah Radiyallahu Anha ne farmaya ke Nabi-e-Kareem Sallallahu Alaihi Wasallam jab junubi hote phir kuch khane ya sone ka irada farmate to Wazu kar lete jis tarah ke Namaz ke liye Wazu kiya jata hai. (Bukhari, Muslim). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke har baal ke neeche Janabat ka asar hai is liye har baal dho'o aur badan ko saaf suthra karo. (Abu Dawood, Tirmidhi). Tarjuma Hadees 5: Hazrat Aishah Radiyallahu Anha ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam jab Janabat ka Ghusl farmate to ibtida yun karte ke pehle hath dho'te phir Namaz ke jaisa Wazu karte phir ungliyan pani mein daal kar un se baalon ki jarein tar farmate phir sar par dono hath se teen Chullu pani daalte phir tamam badan par pani bahate aur Imam Muslim ki riwayat mein hai ke Huzoor (jab Ghusl) shuru farmate to hathon ko bartan mein dakhil karne se pehle dho lete phir dahne hath se bayen hath par pani daalte ba'dah apni sharmgah dho'te phir Wazu farmate. (Bukhari, Muslim).", "explanation": "¥شرح حدیث 4:\nمُّلا علی قاری علیہ رحمۃ الباری اس حدیث کے تحت فرماتے ہیں کہ:\n’’ فَلَوْبَقِیَت شَعرۃٌ وَاحِدَۃٌ لَمْ یَصِل إِلَیْہَا الْمَاءُ بَقِیَتْ جَنَابَتُہُ ‘‘۔ (1)\nیعنی اگر ایک بال بھی پانی پہنچنے سے رہ گیا تو اس کی جنابت باقی رہے گی۔ (مرقاۃ، جلد اول ، ص۳۲۷)\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الطھارۃ ، الحدیث : ۴۴۳، ج ۲، ص ۱۴۶.\n¥انتباہ :\n (۱)… غسل کا طر یقہ یہ ہے کہ پہلے دونوں ہاتھ گٹوں تک تین مرتبہ دھوئے پھر استنجاء کی جگہ دھوئے اس کے بعد بدن پر اگر کہیں نجاست یعنی پیشاب یا پاخانہ یا منی وغیرہ ہو تو اسے دور کرے پھر نماز جیسا وضو کرے مگر پاؤں نہ دھوئے ۔ ہاں اگر چوکی یا پتھر وغیرہ اونچی چیز پر نہاتا ہو تو پاؤں بھی دھولے ۔ اس کے بعد بدن پر تیل کی طرح پانی چپڑے ۔ پھر تین مرتبہ داہنے مونڈھے پر پانی بہائے ۔ اور پھر تین مرتبہ بائیں مونڈھے پر ، پھر سر پر اور تمام بدن پر تین بار پانی بہائے ۔ تمام بدن پر ہاتھ پھیرے اور ملے ۔ پھر غسل کرنے کی جگہ سے الگ ہٹ جائے ۔ اگر وضو کرنے میں پاؤں نہیں دھویا تھا تو اب دھولے اور فوراً کپڑا پہن لے ۔\n (۲)…پردے کی جگہ میں ننگے بدن غسل کرنا جائز ہے ہاں عورتوں کو زیادہ احتیاط کی ضرورت ہے ۔ (1)(بہار شریعت)\n (۳)… لوگوں کے سامنے ران اور گھٹنا کھول کر نہانا یا اتنا باریک کپڑا پہن کر نہانا کہ بدن جھلکے سخت ناجائز وحرام ہے ۔ (عامہ کتب)\n (۴)… منی کا اپنی جگہ سے شہوت کے ساتھ جدا ہو کر عضو سے نکلنا، احتلام ہونا، حشفہ کا داخل ہونا، حیض سے فارغ ہونا ، نفاس کا ختم ہونا۔ ان تمام صورتوں میں غسل کرنا فرض ہے ۔ اور جمعہ، عید، بقرعید، عرفہ کے دن اور احرام باندھتے وقت نہانا سنت ہے ۔ (2)(بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص۳۲۰.\n[2] ’’بہار شر یعت‘‘، ج۱، ص ۳۲۱۔ ۳۲۴."}, {"id": 7784, "bookId": 14, "volNo": "1", "hadithNo": 16, "chapter": "اذان و اقامت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ مُعَاوِیَۃَ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا یَوْمَ الْقِیَامَۃِ۔\nحدیث 2:\nعَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَذَّنَ سَبْعَ سِنِینَ مُحْتَسِبًا کُتِبَتْ لَہُ بَرَاءَ ۃٌ مِنْ النَّارِ۔\nحدیث 3:\nعَنْ جَابِرٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لِبِلَالٍ: إِذَا أَذَّنْتَ فَتَرَسَّلْ و أَقَمْتَ فَاحْدُرْ وَاجْعَلْ بَیْنَ أَذَانِکَ وَإِقَامَتِکَ قَدْرَ مَا یَفْرُغُ الْآکِلُ مِنْ أَکْلِہِ وَالشَّارِبُ مِنْ شُرْبِہِ وَالْمُعْتَصِرُ إِذَا دَخَلَ لِقَضَاءِ حَاجَتِہِ وَلَا تَقُومُوا حَتَّی تَرَوْنِی۔\nحدیث 4:\nعَنْ عَلْقَمَۃَ بْنِ وَقَّاصٍ قَالَ إِنِّی لَعِنْدَ مُعَاوِیَۃَ إِذْ أَذَّنَ مُؤَذِّنُہُ فَقَالَ مُعَاوِیَۃُ کَمَا قَالَ مُؤَذِّنُہُ حَتَّی إِذَا قَالَ حَیَّ عَلَی الصَّلَاۃِ قَالَ لَا حَوْلَ وَلَا قُوَّۃَ إِلَّا بِاللّٰہ فَلَمَّا قَالَ حَیَّ عَلَی الْفَلَاحِ قَالَ لَا حَوْلَ وَلَا قُوَّۃَ إِلَّا بِاللّٰہ الْعَلِیِّ الْعَظِیْمِ وَقَالَ بَعْدَ ذَلِکَ مَا قَالَ الْمُؤَذِّنُ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ ذَلِکَ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت معاویہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے رسول علیہ الصلوۃ و التسلیم کو فرماتے ہوئے سنا ہے کہ مؤذنوں کی گردنیں قیامت کے دن سب سے زیادہ دراز ہوں گی۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابنِ عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جوشخص صرف ثواب کی غرض سے سات برس اذان کہے اس کے لیے دوزخ سے نجات لکھی جاتی ہے ۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 3:\nحضرت جابر رضی اللّٰہ عنہ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والسلام نے حضرت بلال رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے فرمایا کہ جب اذان کہو توٹھہر ٹھہر کر کہو اور جب تکبیرکہو توجلدی جلدی کہو اور اذان و تکبیر کے درمیان اتنا فاصلہ رکھو کہ فارغ ہوجائے کھانے والا اپنے کھانے سے اور پینے والا اپنے پینے سے اور قضائے حاجت کرنے والا اپنی حاجت کو رفع کرنے سے اور تاوقتیکہ مجھے دیکھ نہ لو نماز کے لیے کھڑے نہ ہو۔ (ترمذی\n¥ترجمہ حدیث 4:\n حضرت علقمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں حضرت معاویہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے پاس بیٹھا تھا کہ ان کے مؤذن نے اذان پڑھی۔ حضرت معاویہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے بھی وہی الفاظ کہے جو مؤذن نے کہے ۔ یہاں تک کہ جب مؤذن نے حَیَّ عَلَی الصَّلَاۃِ کہا تو حضرت معاویہ نے لَا حَوْلَ وَلَا قُوَّۃَ إِلَّا بِاللّٰہ کہا اور جب مؤذن نے حَیَّ عَلَی الْفَلَاحِ کہا تو حضرت معاویہ نے لَا حَوْلَ وَلَا قُوَّۃَإِلَّا بِاللّٰہ الْعَلِیِّ الْعَظِیْمِ کہا اور اس کے بعد حضرت معاویہ نے وہی کہا جو مؤذن نے کہا۔ پھر حضرت معاویہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام سے سنا کہ آپ اسی طرح فرماتے تھے ۔ (احمد ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Mu'awiyah Radiyallahu Anhu ne kaha ke main ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ko farmate hue suna hai ke mu'azzinon ki gardanein Qayamat ke din sab se zyada daraz hongi. (Muslim). Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs sarf sawab ki gharz se saat baras Azan kahe us ke liye Dozakh se najaat likhi jati hai. (Tirmidhi, Ibn Majah). Tarjuma Hadees 3: Hazrat Jabir Radiyallahu Anhu se riwayat hai ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne Hazrat Bilal Radiyallahu Anhu se farmaya ke jab Azan kaho to thehar thehar kar kaho aur jab Takbeer kaho to jaldi jaldi kaho aur Azan-o-Takbeer ke darmiyan itna fasla rakho ke farigh ho jaye khane wala apne khane se aur peene wala apne peene se aur Qaza-e-hajat karne wala apni hajat ko rafa karne se aur ta-waqt-e-ke mujhe dekh na lo Namaz ke liye kharay na ho. (Tirmidhi). Tarjuma Hadees 4: Hazrat Alqamah Radiyallahu Anhu ne farmaya ke main Hazrat Mu'awiyah Radiyallahu Anhu ke paas baitha tha ke un ke mu'azzin ne Azan parhi. Hazrat Mu'awiyah Radiyallahu Anhu ne bhi wahi alfaaz kahe jo mu'azzin ne kahe. Yahan tak ke jab mu'azzin ne 'Hayya 'alas-salah' kaha to Hazrat Mu'awiyah ne 'La hawla wala quwwata illa billah' kaha aur jab mu'azzin ne 'Hayya 'alal-falah' kaha to Hazrat Mu'awiyah ne 'La hawla wala quwwata illa billahil Aliyyil Azeem' kaha aur us ke baad Hazrat Mu'awiyah ne wahi kaha jo mu'azzin ne kaha. Phir Hazrat Mu'awiyah Radiyallahu Anhu ne farmaya ke main ne Huzoor Sallallahu Alaihi Wasallam se suna ke aap isi tarah farmate thay. (Ahmad, Mishkat).", "explanation": "¥شرح حدیث 1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ کنایت ست از بزرگی وگردن فرازی ایشاں دراں رُوز ‘‘(1)( اشعۃ اللمعات ، جلد اول ، ص ۳۱۲)\nیعنی اِس حدیث میں قیامت کے دن مؤذنوں کی بزرگی اور اعلیٰ منصبی سے کنایہ کیا گیا ہے ۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب فضل الأذان ، الفصل الأول ، ج ۱، ص ۳۳۴.\n¥انتباہ :\n (۱)… اذان مئذنہ پر یا خارج مسجد پڑھی جائے ۔ داخل مسجد اذان پڑھنا مکروہ ومنع ہے ۔ خواہ اذان پنچ وقتی نماز کے لیے ہو یا خطبہ جمعہ کے لیے دونوں کا حکم ایک ہے ۔ (1) (عالمگیری، فتح القدیر، بحرالرائق، طحطاوی، وغیرہ)\n (۲)…ناسمجھ بچے ، جُنب اور فاسق اگرچہ عالم ہی ہو ان کی اذان مکروہ ہے لہذا ان سب کی اذان کا اعادہ کیا جائے ۔ (2) (درمختار، بہارشریعت)\n (۳)…اذان میں حضور پُر نور شافع یوم النشور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کا نام مبارک سُن کر انگوٹھے چومنا اور آنکھوں سے لگانا مستحب ہے ۔\n طحطاوی علی مراقی الفلاح مصری ص ۱۲۲، اور ردالمحتار جلد اول مصری ص:۲۷۹میں ہے :\n یُسْتَحَبُّ أَنْ یُقَالَ عِنْدَ سَمَاعِ الْأُولَی مِنْ الشَّہَادَۃِ صَلَّی اللّٰہ عَلَیْک یَا رَسُولَ اللّٰہ ، وَعِنْدَ الثَّانِیَۃِ مِنْہَا قَرَّتْ عَیْنِی بِک یَا رَسُولَ اللّٰہ ، ثُمَّ یَقُولُ أَللَّہُمَّ مَتِّعْنِی بِالسَّمْعِ وَالْبَصَرِ بَعْدَ وَضْعِ ظُفْرَیْ الْإِبْہَامَیْنِ عَلَی الْعَیْنَیْنِ فَإِنَّہُ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَکُونُ قَاءِدًا لَہُ إلَی الْجَنَّۃِ ، کَذَا فِی ’’ کَنْزِ الْعِبَادِ ‘‘ ’’ قُھُسْتَانِی ‘‘ وَنَحوِہِ فِی ’’ الْفَتَاوَی الصُّوْفِیَّۃ ‘‘(3)\nیعنی مستحب ہے کہ جب اذان میں پہلی بار اَشْھَدُ أَنَّ مُحَمَّداً رَّسُوْل اللّٰہ سُنے تو صَلَّی اللّٰہ عَلَیْک یَا رَسُولَ اللّٰہ کہے اور جب دوسری بار سنے تو قَرَّتْ عَیْنِی بِک یَا رَسُولَ اللّٰہ اور پھر کہے اللّٰہمَّ مَتِّعْنِی بِالسَّمْعِ وَالْبَصَرِ اور یہ کہنا انگوٹھوں کے ناخن آنکھوں پر رکھنے کے بعد ہو۔ نبی اکرم صلی اللّٰہ تعالی علیہ وآلہ وسلم اپنی رکابِ ا قدس میں اسے جنت لے جائیں گے ایسا ہی کنزالعباد میں ہے ۔ یہ مضمون جامع الرموز علامہ قہستانی کا ہے اور اسی کے مثل فتاوی صوفیہ میں ہے ۔\n (۴)…اذان و اقامت کے درمیان صلوۃ پڑھنا یعنی بلند آواز سے الصَّلَوۃُ وَالسَّلَامُ عَلَیْکَ یَارَسُوْلَ اللّٰہ جائز ومستحب ہے ۔ اس صلاۃ کا نام اصطلاح شرح میں تثویب ہے اور تثویب کو فقہائے اسلام نے نماز مغرب کے علاوہ باقی نمازوں کے لیے مستحسن قر ار دیا ہے جیسا کہ فتاویٰ عالمگیری جلد اول مصری ص:۵۳میں ہے ’’ وَالتَّثْوِیبُ حَسَنٌ عِنْدَ الْمُتَأَخِّرِینَ فِی کُلِّ صَلَاۃٍ إلَّا فِی الْمَغْرِبِ ہَکَذَا فِی شَرْحِ النُّقَایَۃِ لِلشَّیْخِ أَبِی الْمَکَارِمِ وَہُوَ رُجُوعُ الْمُؤَذِّنِ إلَی الْإِعْلَامِ بِالصَّلَاۃِ بَیْنَ الْأَذَانِ وَالْإِقَامَۃِ . وَتَثْوِیبُ کُلِّ بَلْدَۃٍ عَلَی مَا تَعَارَفُوہُ إمَّا بِالتَّنَحْنُحِ أَوْ بِالصَّلَاۃَ الصَّلَاۃَ أَوْ قَامَتْ قَامَتْ؛ لِأَنَّہُ لِلْمُبَالَغَۃِ فِی الْإِعْلَامِ وَإِنَّمَا یَحْصُلُ ذَلِکَ بِمَا تَعَارَفُوہُ . کَذَا فِی الْکَافِی ‘‘.(4)\n مراقی الفلاح شرح نور الایضاح میں ہے ۔ وَیُثَوِّبُ بَعْدَ الْأَذَانِ فِی جَمِیْعِ الْأَوْقَاتِ لِظُھُوْرِ التَّوَانِی فِی الْأُمُوْرِ الدِّیْنِیِِّۃِ فِی الْأَصَحِّ وَتَثْوِیْبُ کلِّ بلَدٍ بِحَسَبِ مَاتَعَارَفَہُ أَھلُھَا ‘‘.(5)\n اور مرقاۃ شرح مشکوۃ لملا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی جلد اول ص:۴۱۸میں ہے وَاسْتَحْسَن الْمُتَأَخِّرَوْنَ التَّثْوِیْبَ فِی الصَّلَوَاتِ کُلِّھَا ۔ (6)\n اور درمختار مع ردالمحتار جلد اول ص:۲۷۳ میں اذان کے بعد خاص صلاۃ وسلام پڑھنے کے متعلق تصریح فرماتے ہوئے لکھتے ہیں کہ ’’ التَّسْلِیمُ بَعْدَ الْأَذَانِ حَدَثَ فِی رَبِیعٍ الْآخَرِ سَنَۃَ سَبْعِ مِءَۃٍ وَإِحْدَی وَثَمَانِینَ وَہُوَ بِدْعَۃٌ حَسَنَۃٌ اھ مُلخَّصاً ‘‘ یعنی اذان کے بعد أَلصَّلَوۃُ وَالسَّلَامُ عَلَیْکَ یَارَسُوْلَ اللّٰہ ‘‘ پڑھنا ماہِ ربیع الاخر ۷۸۱ھ میں جار ی ہوا اور یہ بہترین ایجاد ہے ۔ (7)\n (۵)… اقامت کے وقت کوئی شخص آیا تو اسے کھڑے ہو کر انتظار کرنا مکروہ ہے بلکہ بیٹھ جائے اور مکبّر جب حَیَّ عَلَی الصَّلَوۃ حَیَّ عَلَی الْفَلَاحِ پر پہنچے تو اس وقت کھڑا ہو۔\n فتاویٰ عالمگیری جلد اول مصری ص:۵۳میں ہے ۔ ’’ إذَا دَخَلَ الرَّجُلُ عِنْدَ الْإِقَامَۃِ یُکْرَہُ لَہُ الِانْتِظَارُ قَاءِمًا وَلَکِنْ یَقْعُدُ ثُمَّ یَقُومُ إذَا بَلَغَ الْمُؤَذِّنُ قَوْلَہُ حَیَّ عَلَی الْفَلَاحِ کَذَا فِی الْمُضْمَرَاتِ ‘‘۔ (8)\n اور ردالمحتار جلد اول ص:۳۸۰میں ہے : ’’ وَیُکْرَہُ لَہُ الانْتِظَارُ قَاءِمًا ، وَلَکِنْ یَقْعُدُ ثُمَّ یَقُومُ إذَا بَلَغَ الْمُؤَذِّنُ حَیَّ عَلَی الْفَلَاحِ ‘‘۔ (9)\n (۶)…جو لوگ تکبیر کے وقت مسجد میں موجود ہیں بیٹھے رہیں جب مکبّر حَیَّ عَلَی الصَّلَوۃِ حَیَّ عَلَی الْفَلاَحِ پر پہنچے تو اٹھیں اور یہی حکم امام کے لیے بھی ہے ۔\n فتاویٰ عالمگیری جلد اول مصری ص:۵۳میں ہے :\n’’ یَقُومُ الْإِمَامُ وَالْقَوْمُ إذَا قَالَ الْمُؤَذِّنُ حَیَّ عَلَی الْفَلاَحِ عِنْدَ عُلَمَاءِنَا الثَّلَاثَۃِ وَہُوَ الصَّحِیحُ ‘‘. (10)\nیعنی علمائے ثلاثہ حضرت امام اعظم ، امام ابو یوسف اور امام محمد رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ م کے نزدیک امام اور مقتدی اس وقت کھڑے ہوں جب کہ مکبر حَیَّ عَلَی الْفَلاَحِ کہے اور یہی صحیح ہے ۔\n اور شرح وقایہ جلد اول مجیدی ص:۱۳۶ میں ہے :\n یَقُومُ الْإِمَامُ وَالْقَوْمُ عَنْد حَیَّ عَلَی الصَّلَوۃِ . (11)\nیعنی امام اور مقتدی حَیَّ عَلَی الصَّلَوۃ کہنے کے وقت کھڑے ہوں۔\n اور مرقاۃ شرح مشکوۃ جلد اول ص:۴۱۹ میں ہے ۔ یَقُومُ الْإِمَامُ وَالْقَوْمُ عَنْد حَیَّ عَلَی الصَّلَوۃِ ۔ (12)\n اور شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اشعۃ اللمعات جلد اول ص:۳۲۱ میں فرماتے ہیںکہ:\n فقہا گفتہ اند مذہب آن ست کہ نزد حی علی الصلوۃ باید برخاست ۔ (13)\n یعنی فقہائے کرام نے فرمایا کہ مذہب یہ ہے حَیَّ عَلَی الصَّلَوۃِ کے وقت اُٹھنا چاہیے ۔\n------------------\n[1] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الثانی فی کلمات الأذان إلخ ، ج ۱، ص ۵۵، ’’ فتح القدیر ‘‘، کتاب الصلاۃ ، باب الأذان ، ج ۱، ص ۲۵۰، حاشیۃ الطحطاوی ، باب الأذان وغیرہ ، ص ۱۹۷.\n[2] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، باب الأذان ، مطلب فی المؤذن إذا کان غیر محتسب فی أذانہ ، ج ۲، ص ۷۵. ’’بہار شریعت‘‘، ج۱، ص۴۶۶.\n[3] ’’ حاشیۃ الطحطاویعلی مراقی الفلاح ‘‘، کتاب الصلاۃ ، باب الأذان ، ص ۲۰۵. ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الأذان ، مطلب فی کراھۃ تکرار الجماعۃ فی المسجد ، ج ۲، ص ۹۸۴.\n[4] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الثانی ، الفصل الثانی فی کلمات الأذان إلخ ، ج ۱، ص ۵۶.\n[5] ’’ مراقی الفلاح شرح نور الإیضاح ‘‘، ص ۱۱۹.\n[6] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، باب الأذان ، الحدیث : ۶۴۶، ج ۲، ص ۳۳۸.\n[7] ’’ الدر المختار ورد المحتار ‘‘، باب الأذان ، مطلب فی أول من بنی المنائر للأذان ، ج ۲، ص ۷۰.\n[8] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الثانی ، الفصل الثانی فی کلمات الأذان إلخ ، ج ۱، ص ۵۷.\n[9] ’’ ردالمحتار ‘‘، کتاب الصلاۃ ، باب الأذان ، مطلب فی کراھۃ تکرار الجماعۃ إلخ ، ج ۲، ص ۸۸. \n[10] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الثانی ، الفصل الثانی فی کلمات الأذان إلخ ، ج ۱، ص ۵۷.\n[11] ’’ شرح الوقایۃ ‘‘، کتاب الصلاۃ ، ص ۱۵۵.\n[12] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الصلاۃ ، باب الأذان ، ج ۲، ص ۳۳۹.\n[13] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، الفصل الأول ، ج ۱، ص ۳۴۴."}, {"id": 7785, "bookId": 14, "volNo": "1", "hadithNo": 17, "chapter": "نماز کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَرَأَیْتُمْ لَوْ أَنَّ نَہْرًا بِبَابِ أَحَدِکُمْ یَغْتَسِلُ فِیْہِ کُلَّ یَوْمٍ خَمْسًا ہَلْ یَبْقَی مِنْ دَرَنِہِ شَیْء ٌ قَالُوا لَا یَبْقَی مِنْ دَرَنِہِ شَیْء ٌ قَالَ فَذَلِکَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ یَمْحُو اللّٰہ بِہِنَّ الْخَطَایَا۔\nحدیث 2:\nعَنْ أَبِی ذَرٍّ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ خَرَجَ زَمَنَ الشِّتَاءِ وَالْوَرَقُ یَتَہَافَتُ فَأَخَذَ بِغُصْنَیْنِ مِنْ شَجَرَۃٍ قَالَ فَجَعَلَ ذَلِکَ الْوَرَقُ یَتَہَافَتُ قَالَ فَقَالَ یَا أَبَا ذَرٍّ قُلْتُ لَبَّیْکَ یَا رَسُولَ اللّٰہ قَالَ إِنَّ الْعَبْدَ الْمُسْلِمَ لَیُصَلِّ الصَّلَاۃَ یُرِیدُ بِہَا وَجْہَ اللّٰہ فَتَہَافَتُ عَنْہُ ذُنُوبُہُ کَمَا یَتَہَافَتُ ہَذَا الْوَرَقُ عَنْ ہَذِہِ الشَّجَرَۃِ۔\nحدیث 3:\nعَنْ سَلْمَانَ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَنْ غَدَا إِلَی صَلَاۃِ الصُّبْحِ غَدَا بِرَایَۃِ الْإِیمَانِ وَمَنْ غَدَا إِلَی السُّوقِ غَدَا بِرَایَۃِ إِبْلِیسَ۔\nحدیث 4:\nعَنْ عَبْدِ اللّٰہ بْنِ عَمَرِو بْنِ الْعَاصِ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَّہُ ذَکَرَ الصَّلاَۃَ یَوْماً فَقَالَ: مَنْ حَافَظَ عَلَیْہَا کَانَتْ لَہُ نُوراً وَبُرْہَاناً وَنَجَاۃً یَوْمَ الْقِیَامَۃِ، وَمَنْ لَمْ یُحَافِظْ عَلَیْہَا لَمْ تَکُنْ لَہُ نُوراً وَلَا بُرْہَاناً وَلَا نَجَاۃً، وَکَانَ یَوْمَ الْقِیَامَۃِ مَعَ قَارُونَ وَفِرْعَوْنَ وَہَامَانَ وَأُبَیِّ بْنِ خَلَفٍ۔\nحدیث5:\nعَنْ عَلِیِّ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ یَا عَلِیُّ ثَلَاثٌ لَا تُؤَخِّرْہَا الصَّلَاۃُ إِذَا أَتَتْ وَالْجَنَازَۃُ إِذَا حَضَرَتْ وَالْأَیِّمُ إِذَا وَجَدْتَ لَھَا کُفْؤًا۔ \nحدیث 6:\nعَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تِلْکَ صَلَاۃُ الْمُنَافِقِ یَجْلِسُ یَرْقُبُ الشَّمْسَ حَتَّی إِذَا اصْفَرَّتْ وَکَانَتْ بَیْنَ قَرْنِی الشَّیْطَانِ قَامَ فَنَقَرَ أَرْبَعًا لَا یَذْکُرُ اللّٰہ فِیہَا إِلَّا قَلِیلًا۔\nحدیث 7:\nعَنْ عَمْرِو بْنِ شُعَیْبٍ عَنْ أَبِیہِ عَنْ جَدِّہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مُرُوْا أَوْلَادَکُمْ بِالصَّلَاۃِ وَھُمْ أَبْنَاءُ سَبْعِ سِنِیْنَ وَاضْرِبُوہُمْ عَلَیْہَا وَھُمْ أَبْنَاءُ عَشَرِ سِنِیْنَ وَفَرِّقُوا بَیْنَہُمْ فِی الْمَضَاجِعِ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ بتاؤ اگر تم لوگوں میں کسی کے دروازے پر نہر ہو اور وہ ا س میں روزانہ پانچ مرتبہ غسل کرتا ہو تو کیا ان کے بدن پر کچھ میل باقی رہ جائے گا۔ صحابہ کرام نے عرض کیا ایسی حالت میں اس کے بدن پر کچھ بھی میل باقی نہ رہے گا ۔ \n حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا بس یہی کیفیت ہے پانچوں نمازوں کی، اللّٰہ تعالیٰ ان کے سب گناہوں کو مٹا دیتا ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابو ذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ایک روز سردی کے موسم میں جب کہ درختوں کے پتے گررہے تھے ۔ (یعنی پت جھڑ کا موسم تھا) حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم باہر تشریف لے گئے تو آپ نے ایک درخت کی دو ٹہنیاں پکڑیں ( اور انہیں ہلایا) تو ان شاخوں سے پتے گرنے لگے ۔ آپ نے فرمایا اے ابوذر! حضرت ابوذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے عرض کیا حاضر ہوں یارسول اللّٰہ !آپ نے فرمایاجب مسلمانبندہ خالص اللّٰہ تعالیٰ کے لیے نماز پڑھتا ہے تو اس کے گناہ اس طرح جھڑ جاتے ہیں جیسے کہ یہ پتے درخت سے جھڑ رہے ہیں۔ (احمد)\n¥ترجمہ حدیث 3:\n حضرت سلمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کو یہ فرماتے ہوئے سنا کہ جو شخص فجر کی نماز کو گیا وہ ایمان کا جھنڈا لے کر گیا۔ اور صبح سویرے بازار کی طرف گیا وہ شیطان کا جھنڈا لے کر گیا۔ (ابن ماجہ)\n¥ترجمہ حدیث 4:\nحضرت عبد اللّٰہ بن عمرو بن العاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے رو ایت ہے کہ نبی کریم صلی اللّٰہ تعالی علیہ وآلہ وسلم نے ایک روز نماز کا ذکر کیا تو فرمایا کہ جو شخص نماز کی پابندی کرے گا تو نماز اس کے لیے نور کا سبب ہوگی ۔ کمالِ ایمان کی دلیل ہوگی اور قیامت کے دن بخشش کا ذریعہ بنے گی۔ اور جو نماز کی پابندی نہیں کرے گا اِس کے لیے نہ تو نور کا سبب ہوگی نہ کمالِ ایمان کی دلیل ہوگی اور نہ بخشش کا ذریعہ اور وہ قیامت کے دن قارون فرعون ، ہامان اور اُبی بن خلف کے ہمراہ ہوگا۔ (احمد، دارمی، بیہقی)\n¥ترجمہ حدیث 5:\nحضرت علی کرم اللّٰہ تعالیٰ وجہہ نے کہا کہ حضور علیہ الصلاۃ والسلام نے مجھ سے فرمایا کہ اے علی تین کاموں میں دیر نہ کرنا۔ ایک تو نماز ادا کرنے میں جب وقت ہوجائے ، دوسرے جنازہ میں جب کہ وہ تیار ہو جائے ، تیسرے بیوہ کے نکاح میں جب کہ اس کا کفو مل جائے ۔ (ترمذی)\n¥ترجمہ حدیث 6:\nحضر ت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ یہ منافق کی نماز ہے کہ بیٹھے ہوئے سورج کا انتظار کرتا ہے یہاں تک کہ جب سورج پیلا پڑ جاتا ہے اور شیطان کی دونوں سینگوں کے بیچ میں آجاتا ہے تو کھڑا ہو کر چار چونچ مارلیتاہے ۔ نہیں ذکرکرتااس (تنگ وقت) میں اللّٰہ تعالیٰ کا مگر بہت تھوڑا۔ (مسلم)\n¥ترجمہ حدیث 7:\nحضرت عمرو بن شعیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا اپنے دادا سے روایت کر تے ہیں انہوں نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایاکہ جب تمہارے بچے سات سال کے ہوجائیں تو ان کو نماز پڑھنے کا حکم دو اور جب دس سال کے ہوجائیں تو ان کو مار کر نماز پڑھاؤ۔ اور ان کے سونے کی جگہیں علیحدہ کرو۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke batao agar tum logon mein kisi ke darwaze par nehar ho aur woh us mein rozana paanch martaba Ghusl karta ho to kya un ke badan par kuch mail baqi reh jaye ga. Sahabah ne arz kiya aisi halat mein us ke badan par kuch bhi mail baqi na rahe ga. Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya bas yahi kaifiyat hai paanchon Namazon ki, Allah Ta'ala un ke sab gunahon ko mita deta hai. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Zar Radiyallahu Anhu ne farmaya ke ek roz sardi ke mausam mein jab ke darakhton ke patte gir rahe thay (yani pat jhar ka mausam tha) Rasoolullah Sallallahu Alayhi wa Sallam bahar tashreef le gaye to aap ne ek darakht ki do tahniyan pakrein (aur unhein hilaya) to un shakhon se patte girne lage. Aap ne farmaya ae Abu Zar! Hazrat Abu Zar Radiyallahu Anhu ne arz kiya hazir hoon Ya Rasoolullah! Aap ne farmaya jab musalman banda khalis Allah Ta'ala ke liye Namaz parhta hai to us ke gunah is tarah jhar jate hain jaise ke ye patte darakht se jhar rahe hain. (Ahmad). Tarjuma Hadees 3: Hazrat Salman Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko ye farmate hue suna ke jo shakhs Fajr ki Namaz ko gaya woh imaan ka jhanda le kar gaya. Aur subah sawere bazaar ki taraf gaya woh shaitan ka jhanda le kar gaya. (Ibn Majah). Tarjuma Hadees 4: Hazrat Ibn Umar Radiyallahu Anhum se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne ek roz Namaz ka zikr kiya to farmaya ke jo shakhs Namaz ki pabandi kare ga to Namaz us ke liye noor ka sabab hogi. Kamal-e-imaan ki daleel hogi aur Qayamat ke din bakhshish ka zariya banay gi. Aur jo Namaz ki pabandi nahi kare ga is ke liye na to noor ka sabab hogi na kamal-e-imaan ki daleel hogi aur na bakhshish ka zariya aur woh Qayamat ke din Qaroon, Firaun, Haman aur Ubay bin Khalaf ke hamrah hoga. (Ahmad, Darimi, Baihaqi). Tarjuma Hadees 5: Hazrat Ali Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne mujh se farmaya ke ae Ali teen kamon mein der na karna. Ek to Namaz ada karne mein jab waqt ho jaye, dusre Janazah mein jab ke woh tayyar ho jaye, teesre bewa ke Nikah mein jab ke us ka Kufu mil jaye. (Tirmizi). Tarjuma Hadees 6: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke ye munafiq ki Namaz hai ke baithe hue suraj ka intezar karta hai yahan tak ke jab suraj peela par jata hai aur shaitan ki dono seengon ke beech mein aa jata hai to khara ho kar chaar chonch maar leta hai. Nahi zikr karta us (tang waqt) mein Allah Ta'ala ka magar bohat thora. (Muslim). Tarjuma Hadees 7: Hazrat Amr Bin Shuaib Radiyallahu Anhum apne dada se Riwayat karte hain unhon ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab tumhare bache saat saal ke ho jayen to un ko Namaz parhne ka Hukm do aur jab das saal ke ho jayen to un ko maar kar Namaz parhao. Aur un ke sone ki jaghein alaihda karo. (Abu Dawood).", "explanation": "¥ ضروری انتباہ :\n (۱)…آہستہ قرآن پڑھنے میں اِتنا ضروری ہے کہ خُود سُنے اگر حروف کی تصحیح کی مگر اِسقدر آہستہ پڑھا کہ خود نہ سُنا تو نماز نہ ہوئی۔ (1)اور فتاویٰ عالمگیری جلد اول مصری ص:۶۵میں ہے : ’’ إِنْ صَحَّحَ الْحُرُوف بِلِسَانِہِ وَلَمْ یُسْمِعْ نَفْسَہُ لَا یَجُوزُ وَبِہِ أَخَذَ عَامَّۃُ الْمَشَایِخِ ہَکَذَا فِی الْمُحِیطِ وَہُوَ الْمُخْتَارُ ہَکَذَا فِی السِّرَاجِیَّۃِ وَہُوَ الصَّحِیحُ ہَکَذَا فِی النُّقَایَۃِ ‘‘.(2)\n (۲)…سجدہ میں پاؤں کی ایک انگلی کا پیٹ زمین سے لگنا شرط ہے اور ہر پاؤں کی تین تین انگلیوں کا پیٹ لگنا واجب ، تو اگر کسی نے اِس طرح سجدہ کیا کہ دونوں پاؤں زمین سے اُٹھے رہے تو نماز نہ ہوئی۔ (3)\n (بہار شریعت، جلد سوم ص۲۷۹، فتاوی رضویہ ، جلد اول ، ص ۵۵۶)\n اور اشعۃ اللمعات جلد اول ص:۳۹۴میں ہے کہ ’’ اگر ہر دو پائے بردارد نماز فاسد ست واگر یکپائے بردارد مکروہ است ‘‘. (4)\n اور درمختار مع ردالمحتار جلد اول ص:۳۱۳ میں ہے ’’ وَوَضْعُ إصْبَعٍ وَاحِدَۃٍ مِنْہُمَا شَرْطٌ ‘‘۔ (5)\n اور اِسی کتاب میں ص:۳۵۱ پر ہے ’’ فِیہِ یُفْتَرَضُ وَضْعُ أَصَابِعِ الْقَدَمِ وَلَوْ وَاحِدَۃً نَحْوَ الْقِبْلَۃِ وَإِلَّا لَمْ تَجُزْ وَالنَّاسُ عَنْہُ غَافِلُونَ ‘‘ (6)\n اور کنزالدقائق میں ہے ’’ وَوَجُہُ أَصَابِعِ رِجْلَیْہِ نَحْوَ الْقِبْلَۃِ ‘‘ اسی کے تحت بحرالرائق جلد اول ص:۳۲۱میں ہے ’’ نَصَّ صَاحِبُ الْہِدَایَۃِ فِی التَّجْنِیسِ عَلَی أَنَّہُ إنْ لَمْ یُوَجِّہِ الْأَصَابِعَ نَحْوَہَا فَإِنَّہُ مَکْرُوہٌ ‘‘(7)\n (۳)…اکثر عورتیں اپنی نادانی سے فرض واجب سب نمازیں بغیر عذر بیٹھ کر پڑھتی ہیں۔ ان کی نماز نہیں ہوتی اِس لیے کہ مردوں کی طرح عورتوں پر بھی کھڑے ہوکر نماز پڑھنا فرض ہے ۔ اگر کسی بیماری یا بڑھاپے کی وجہ سے کمزور ہوگئی ہیں لیکن خادمہ یا لاٹھی یا دیوار پر ٹیک لگا کر کھڑی ہوسکتی ہیں تو فرض ہے کہ کھڑی ہو کر پڑھیں یہاں تک کہ اگر کچھ دیر ہی کے لیے کھڑی ہوسکتی ہیں۔ اگرچہ اتنا ہی کہ کھڑی ہو کر اللّٰہ اکبر کہہ لیں تو فرض ہے کہ کھڑی ہو کر اتنا کہہ لیں پھر بیٹھ جائیں۔ (8) (بہار شریعت، جلد سوم ، ص ۳۷۷، بحوالہ غنیۃ)\n اور فتاویٰ رضویہ جلدسوم، ص:۵۲ ، میں تنویر الابصار و درمختارسے ہے : ’’ إِنْ قَدَرَ عَلَی بَعْضِ الْقِیَامِ وَلَوْ مُتَّکِءًا عَلَی عَصًا أَوْ حَاءِطٍ قَامَ لُزُومًا بِقَدْرِ مَا یَقْدِرُ وَلَوْ قَدْرَ آیَۃٍ أَوْ تَکْبِیرَۃٍ عَلَی الْمَذْہَبِ ‘‘ ۔\n آج کل عموماً مرد بھی ذرا سی تکلیف پر بیٹھ کرنماز پڑھنا شروع کر دیتے ہیں۔ حالانکہ دیر تک کھڑے ہو کر ادھر ادھر کی باتیں کرلیا کرتے ہیں اِن کی نماز نہیں ہوتی اِس لیے کہ قیام کے بارے میں عورت مرد کا حکم ایک ہے ۔\n (۴)… عورت نے اِتنا باریک دوپٹہ اوڑھ کر نماز پڑھی کہ جس سے بال کی سیاہی چمکتی ہے تو نماز نہ ہوگی۔ جب تک کہ اس پر کوئی ایسی چیز نہ اوڑھے کہ جس سے بال کا رنگ چھپ جائے ۔ (9)\n (بہار شریعت، جلد سوم، ص۲۵۱)\n اور فتاویٰ عالمگیری جلد اول مصری ص:۵۴میں ہے : ’’ اَلثَّوْبُ الرَّقِیقُ الَّذِی یَصِفُ مَا تَحْتَہُ لَا تَجُوزُ الصَّلَاۃُ فِیہِ کَذَا فِی التَّبْیِینِ ‘‘ ۔ (10)\n------------------\n[1] ’’بہارِ شر یعت‘‘، ج۱، ص۵۱۱. ’’ الفتاوی الھندیۃ ‘‘، الباب الرابع فی صفۃ الصلاۃ ، ج ۱، ص ۶۹.\n[2] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الرابع ، ج ۱، ص ۶۹.\n[3] ’’بہارِ شریعت‘‘، ج۱، ص۵۱۳، ’’ الدر المختار ‘‘، ج ۲، ص ۱۶۷۔ ۲۴۹۔ ۲۵۱، ’’ الفتاوی الرضویۃ ‘‘، ج ۷، ص ۳۷۶.\n[4] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب السجود وفضلہ ، الفصل الأول ، ج ۱، ص ۴۲۲.\n[5] ’’ الدر المختار وردالمحتار ‘‘، کتاب الصلاۃ ، باب صفۃ الصلاۃ ، ج ۲، ص ۱۶۷.\n[6] ’’ الدر المختار وردالمحتار ‘‘، باب صفۃ الصلاۃ ، مطلب فی إطالۃ الرکوع للجائی ، ج ۲ ص ۲۴۹.\n[7] ’’ الدر ’’ کنز الدقائق ‘‘، کتاب الصلاۃ ، باب صفۃ الصلاۃ ، ص ۲۵، ’’ البحر الرائق ‘‘، کتاب الصلاۃ ، باب صفۃ الصلاۃ ، ج ۱، ص ۵۶۰. المختار وردالمحتار ‘‘، باب صفۃ الصلاۃ ، مطلب فی إطالۃ الرکوع للجائی ، ج ۲ ص ۲۴۹.\n[8] ’’بہارِ شریعت‘‘، ج۱، ص ۵۱۱، ’’ غنیۃ المتملی ‘‘، فرائض الصلاۃ ، ص ۲۶۱۔ ۲۶۷.\n[9] ’’بہارِ شریعت‘‘، ج۱، ص ۴۸۱. ’’ الفتاوی الھندیۃ ‘‘، الباب الثالث فی شروط الصلاۃ ، ج ۱، ص ۵۸، موضحا .\n[10] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الثالث ، الفصل الأول فی الطہارۃ وسترالعورۃ ، ج ۱، ص ۵۸."}, {"id": 7786, "bookId": 14, "volNo": "1", "hadithNo": 18, "chapter": "تراویح کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ قَامَ رَمَضَانَ إِیمَانًا وَاحْتِسَابًا غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ۔\nحدیث 2:\nعَنْ سَاءِبِ بْنِ یَزِیْدَ قَالَ کُنَّا نَقُوْمُ فِیْ زَمَان عُمَرَ بْنِ الْخَطَّابِ بِعِشْرِیْنَ رَکْعَۃً وَالْوِتْرِ۔\nحدیث3:\nعَنْ یَزِیْدَ بْنِ رُوْمَانَ أَنَّہُ قَالَ کَانَ النَّاسُ یَقُوْمُوْنَ فِی زَمَانِ عُمَرَ بْنِ الْخَطَّابِ فِی رَمَضَانَ بِثَلاثٍ وَعِشْرِینَ رَکْعَۃً۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جو شخص صدق دل اور اعتقاد ِ صحیح کے ساتھ رمضان میں قیام کرے یعنی تراویح پڑھے تو اس کے اگلے گناہ بخش دیئے جاتے ہیں۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت سائب بن یزید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم صحابہ کرام حضرت عمر فاروق اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے زمانہ میں بیس رکعت ( تراویح) اور وتر پڑھتے تھے ۔ (بیہقی)\n¥ترجمہ حدیث 3:\nحضرت یزید بن رومان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے زمانے میں لوگ تئیس رکعت پڑھتے تھے ( یعنی بیس رکعت تراویح اور تین رکعت وتر) (امام مالک)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs sadaq-e-dil aur aitqad-e-Saheeh ke sath Ramadan mein Qiyam kare yani Taraweeh parhe to us ke agle gunah bakhsh diye jate hain. (Muslim). Tarjuma Hadees 2: Hazrat Saaib Bin Yazeed Radiyallahu Anhu ne farmaya ke hum Sahabah Farooq-e-Azam Hazrat Umar Radiyallahu Anhu ke zamane mein bees rakat (Taraweeh) aur Witr parhte thay. (Baihaqi). Tarjuma Hadees 3: Hazrat Yazeed Bin Rumaan Radiyallahu Anhu ne farmaya ke Hazrat Umar Radiyallahu Anhu ke zamane mein log teees rakat parhte thay (yani bees rakat Taraweeh aur teen rakat Witr). (Imam Malik).", "explanation": "¥شرح حدیث 2:\nاس حدیث کے بارے میں مرقاۃ شرح مشکوۃ جلد دوم ص:۱۷۵ میں ہے ’’ قَالَ النَّووِی فِی الْخُلَاصَۃِ إِسْنَادُہُ صَحِیْحٌ ‘‘ یعنی امام نووی نے خلاصہ میں فرمایا کہ اِس روایت کی اسناد صحیح ہے ۔ (1)\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘ باب قیام شھر رمضان ، الحدیث : ۱۳۰۳، ج ۳، ص ۳۸۲.\n¥بیس رکعت پر صحابہ کا اجماع ہے\n ملک العلماء حضرت علامہ علاء الدین ابوبکربن مسعود کاسانی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ تحریر فرماتے ہیں کہ :\n’’ رُوِیَ أَنَّ عُمَرَ رَضِیَ اللّٰہ عَنْہُ جَمَعَ أَصْحَابَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی شَہْرِ رَمَضَانَ عَلَی أُبَیِّ بْنِ کَعْبٍ فَصَلَّی بِہِمْ فِی کُلِّ لَیْلَۃٍ عِشْرِینَ رَکْعَۃً ، وَلَمْ یُنْکِرْعَلَیْہِ أَحَدٌ فَیَکُونُ إجْمَاعًا مِنْہُمْ عَلَی ذَلِک ‘‘(1)\n یعنی مروی ہے کہ حضرت عمر فاروقِ اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے رمضان کے مہینہ میں صحابہ کرام کو حضرت اُبی بن کعب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ پر جمع فرمایا تو وہ روزانہ صحابہ کرام کو بیس رکعت پڑھاتے تھے اور ان میں سے کسی نے مخالفت نہیں کی تو بیس رکعت پر صحابہ کا اجماع ہوگیا۔ (بدائع الصنائع ، جلد اول ، ص۲۸۸)\n اور عمدۃ القاری شرح بخاری جلد پنجم ص:۳۵۵میں ہے :\n ’’ قَالَ ابْنُ عَبْدِالبرِ وَھُوَ قَوْلُ جُمْھورِ الْعُلَمَاء وَبِہِ قَالَ الْکُوْفِیُوْنَ وَالشَّافِعِیُّ وَأَکْثَر الفُقَھَاءِ وَھُوَالصَّحِیْحُ عَنْ أُبَیِّ بْنِ کَعْبٍ مِنْ غَیْرِ خِلَافٍ مِنَ الصَّحَابَۃِ ‘‘(2)\n یعنی علامہ ابن عبدالبر نے فرمایا کہ ( بیس رکعت تراویح) جمہور علماء کا قول ہے ۔ علمائے کوفہ ، امام شافعی اور اکثر فقہاء یہی فرماتے ہیں اور یہی صحیح ہے ۔ ابی بن کعب سے منقول ہے اس میں صحابہ کا اختلاف نہیں۔\n اور علامہ ابنِ حجر نے فرمایا ’’ إِجْمَاعُ الصَّحَابَۃِ عَلَی أَنَّ التَّرَاوِیْحَ عِشْرُوْنَ رَکْعَۃً ‘‘ یعنی صحابۂ کرام کا اس بات پر اجماع ہے کہ تراویح بیس رکعت ہے ۔ اور مراقی الفلاح شرح نور الایضاح میں ہے :\n وَہِیَ عِشْرُوْنَ رَکْعَۃً بِإِجْمَاعِ الصَّحَابَۃِ ۔ (3)\n یعنی تراویح بیس رکعت ہے اِس لیے کہ اس پر صحابہ کرام کا اجماع ہے ۔\n اور مولانا عبدالحی صاحب فرنگی محلی عمدۃ الرعایۃ حاشیہ شرح وقایہ جلد اول ص:۱۷۵ میں لکھتے ہیں:\n’’ ثَبَتَ اِھْتِمَامُ الصَّحَابَۃِ عَلَی عِشْرِیْنَ فِی عَھْدِ عُمَرَ وَعُثْمَانَ وَعَلِیٍّ فَمنْ بَعْدَھُمْ أَخْرَجَہُ مَالِکٌ وَابْنُ سَعْدٍ وَالْبَیْھَقِی وَغُیْرُھُمْ ‘‘۔ (4)\n یعنی حضرت عمر، حضرت عثمان اور حضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُم کے زمانے میں اور ان کے بعد بھی صحابہ کرام کا بیس رکعت تراویح پر اہتمام ثابت ہے اس مضمون کی حدیث کو امام مالک، ابن سعد، اور امام بیہقی وغیرہم نے تخریج کی ہے ۔\n اور مُلا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی تحریر فرماتے ہیں۔ أَجْمَعَ الصَّحَابَۃُ عَلَی أَنَّ التَّرَاوِیْحَ عِشْرُوْنَ رَکْعَۃً یعنی صحابہ کرام کا اس بات پر اجماع ہے کہ تراویح بیس رکعت ہے ۔ (5) (مرقاۃ، جلد دوم، ص۱۷۵)\n٭…٭…٭…٭\n¥بیس رکعت جمہور کا قول ہے اور اسی پرعمل ہے\n امام ترمذی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں:\n ’’ أَکْثَرُ أَہْلِ الْعِلْمِ عَلَی مَا رُوِیَ عَنْ عَلِیٍّ وَعُمَرَوَغَیْرِہِمَا مِنْ أَصْحَابِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عِشْرِینَ رَکْعَۃً وَہُوَ قَوْلُ سُفْیَانَ الثَّوْرِیِّ وَابْنِ الْمُبَارَکِ وَالشَّافِعِیِّ و قَالَ الشَّافِعِیُّ ہَکَذَا أَدْرَکْتُ بِبَلَدِنَا بِمَکَّۃَ یُصَلُّونَ عِشْرِینَ رَکْعَۃً ‘‘۔ (6)\n یعنی کثیر علماء کا اسی پر عمل ہے جو حضرت مولیٰ علی حضرت فاروق اعظم اور دیگر صحابہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم سے بیس رکعت تراویح منقول ہے ۔ اور سفیان ثوری ، ابن مبار ک اور امام شافعی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ م بھی یہی فرماتے ہیں کہ ( تراویح بیس رکعت ہے ) اور امام شافعی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ ہم نے اپنے شہر مکہ شریف میں لوگوں کو بیس رکعت تراویح پڑھتے ہوئے پایا ہے ۔ (ترمذی، باب قیام شھر رمضان، ص ۹۵)\n اور مُلّا علی قاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ شرح نقایہ میں تحریر فرماتے ہیں:\n فَصَارَ إِجْمَاعاً لِمَا رَوَی الْبَیْہَقِی بِإِسْنَادٍ صَحِیْحٍ کَانُوْا یُقِیْمُونَ عَلَی عَھْدِ عُمَرَ بِعِشْرِیْنَ رَکْعَۃً وَعَلَی عَھْدِ عُثْمَانَ وَعَلِیٍّ ۔ (7)\nیعنی بیس رکعت تراویح پر مسلمانوں کا اتفاق ہے ۔ اس لیے کہ امام بیہقی نے صحیح اسناد سے روایت کی ہے کہ حضرت عمر فاروق اعظم ، حضرت عثمانِ غنی اور حضرت مولیٰ علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُم کے مقدس زمانوں میں صحابہ کرام اور تابعین عظام بیس رکعت تراویح پڑھا کرتے تھے ۔ اور طحطاوی علی مراقی الفلاح ص:۲۲۴میں ہے :\n’’ ثَبَتَ الْعِشْرُوْنَ بِمُوَاظَبَۃِ الْخُلَفَاءِ الرَّاشِدِیْنَ مَاعَدَا الصدیق رضی اللّٰہ تعالَی عنہم ‘‘۔ (8)\nیعنی حضرت ابوبکر صدیق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے علاوہ دیگر خلفائے راشدین رضوان اللّٰہ تعالیٰ علیہم اجمعین کی مداومت سے بیس رکعت تراویح ثابت ہے ۔\n اور علامہ ابن عابدین شامی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ تحریر فرماتے ہیں:\n ’’ وَہِیَ عِشْرُونَ رَکْعَۃً ہُوَ قَوْلُ الْجُمْہُورِ وَعَلَیْہِ عَمَلُ النَّاسِ شَرْقًا وَغَرْبًا ‘‘۔ (9)\nیعنی تراویح بیس رکعت ہے یہی جمہور علماء کا قول ہے اور مشرق و مغرب ساری دنیا کے مسلمانوں کا اسی پر عمل ہے ۔ (شامی، جلد اول، مصری ص۱۹۵)\n اور شیخ زین الدین ابن نجیم رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ تحریر فرماتے ہیں:\n’’ ہُوَ قَوْلُ الْجُمْہُورِ لِمَا فِی الْمُوَطَّإِ عَنْ یَزِیدَ بْنِ رُومَانَ قَالَ کَانَ النَّاسُ یَقُومُونَ فِی زَمَنِ عُمَرَ بْنِ الْخَطَّابِ بِثَلَاثٍ وَعِشْرِینَ رَکْعَۃً وَعَلَیْہِ عَمل النَّاسُ شَرْقًا وَغَرْبًا ‘‘۔ (10)\nیعنی بیس رکعت تراویح جمہور علماء کا قول ہے اس لیے کہ مؤطا امام مالک میں حضرت یزید بن رومان رضی ا للہ تعالیٰ عنہ سے روایت ہے انہوں نے فرمایا کہ حضرت عمر فاروق اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے زمانہ میں صحابہ کرام تئیس رکعت پڑھتے تھے ۔ ( یعنی بیس رکعت تراویح اور تین رکعت وتر) اور اِسی پر ساری دنیاکے مسلمانوں کا عمل ہے ۔ (بحرالرائق، جلد دوم ، ص ۶۶) اور عنایہ شرح ہدایہ میں ہے :\n’’ کَانَ النَّاسُ یُصَلُّونَہَا فُرَادَی إلَی زَمَنِ عُمَرَ رَضِیَ اللّٰہ عَنْہُ ، فَقَالَ عُمَرُ إنِّی أَرَی أَنْ أَجْمَعَ النَّاسَ عَلَی إمَامٍ وَاحِدٍ ، فَجَمَعَہُمْ عَلَی أُبَیِّ بْنِ کَعْبٍ فَصَلَّی بِہِمْ خَمْسَ تَرْوِیحَاتٍ عِشْرِینَ رَکْعَۃً ‘‘۔ (11)\nیعنی حضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کے شروع زمانہ خلافت تک صحابہ کرام تراویح الگ الگ پڑھتے تھے بعد ہ حضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ایک امام پر صحابۂ کرام کو جمع کرنا بہتر سمجھتا ہوں۔ پھر انہوں نے حضرت اُبی بن کعب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ پر صحابہ کرام کو جمع فرمایا۔ حضرت اُبی نے لوگوں کو پانچ ترویحہ بیس رکعت پڑھائی۔ اور کفایہ میں ہے :\n’’ کَانَتْ جُمْلَتُھَا عِشْرِیْنَ رَکْعَۃً وَھَذَا عِنْدَنَا وَعِنْدَالشَّافِعی ‘‘.(12)\nیعنی تراویح کل بیس رکعت ہے ۔ اور یہ ہمارا مسلک ہے ۔ اور یہی مسلک امام شافعی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ کا بھی ہے ۔\n اور بدائع الصنائع جلد اول ص:۲۸۸ میں ہے :\n’’ أَمَّا قَدْرُہَا فَعِشْرُونَ رَکْعَۃً فِی عَشْرِ تَسْلِیمَاتٍ ، فِی خَمْسِ تَرْوِیحَاتٍ کُلُّ تَسْلِیمَتَیْنِ تَرْوِیحَۃٌ وَہَذَا قَوْلُ عَامَّۃِ الْعُلَمَاء ‘‘(13)\nیعنی تراویح کی تعداد بیس رکعت ہے ۔ پانچ ترویحہ دس سلام کے ساتھ ، ہر دو سلام ایک ترویحہ ہے ۔ اور یہی عام علماء کا قول ہے ۔\n اور امام غزالی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ تحریر فرماتے ہیں وَھِیَ عِشْرُونَ رَکْعَۃً یعنی تراویح بیس رکعت ہے ۔ (14) (احیاء العلوم، جلد اول ص ۲۰۱)\n اور شرح وقایہ جلد اول ص:۱۷۵میں ہے ’’ سُنَّ التَّرَاوِیْحُ عِشرُوْنَ رَکْعَۃً ‘‘ یعنی تراویح بیس رکعت مسنون ہے ۔ (15) اور فتاوی عالمگیری جلد اول مصری ص ۱۰۸ میں ہے ۔\n’’ وَہِیَ خَمْسُ تَرْوِیحَاتٍ کُلُّ تَرْوِیحَۃٍ أَرْبَعُ رَکَعَاتٍ بِتَسْلِیمَتَیْنِ کَذَا فِی السِّرَاجِیَّۃ ‘‘(16)\nیعنی تراویح پانچ ترویحہ ہے ، ہر ترویحہ چار رکعت کا دو سلام کے ساتھ، ایسا ہی سراجیہ میں ہے ۔\n اور حضرت شاہ ولی اللّٰہ صاحب محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں۔\n’’ عَدَدُہُ عِشْرُوْنَ رَکْعَۃً ‘‘(17)یعنی تراویح کی تعداد بیس رکعت ہے ۔ (حجۃ اللّٰہ البالغہ ، جلد دوم، ص ۱۸)\n٭…٭…٭…٭\n¥بیس رکعت تراویح کی حکمت\n بیس رکعت تراویح کی حکمت یہ ہے کہ رات اور دن میں کل بیس رکعت فرض وواجب ہیں، سترہ ر کعت فرض اور تین رکعت وتر اور رمضان میں بیس رکعت تراویح مقرر کی گئیں تاکہ فرض وواجب کے مدارج اور بڑھ جائیں اور ان کی خوب تکمیل ہوجائے ۔\n جیسا کہ بحرالرائق جلد دوم ص:۶۷ پر ہے :\n ’’ ذَکَرَ الْعَلَّامَۃُ الْحَلَبِیُّ أَنَّ الْحِکْمَۃَ فِی کَوْنِہَا عِشْرِینَ أَنَّ السُّنَنَ شُرِعَتْ مُکَمِّلَاتٍ لِلْوَاجِبَاتِ وَہِیَ عِشْرُونَ بِالْوِتْرِ فَکَانَتْ التَّرَاوِیحُ کَذَلِکَ لِتَقَعَ الْمُسَاوَاۃُ بَیْنَ الْمُکَمِّلِ وَالْمُکَمَّل ‘‘ ۔ (18)\n یعنی علامہ حلبی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے ذکر فرمایا کہ تراویح کے بیس رکعات ہونے میں حکمت یہ ہے کہ واجب اور فرض جو دن رات میں کل بیس رکعت ہیں انہیں کی تکمیل کے لیے سنتیں مشروع ہوئی ہیں تو تراویح بھی بیس رکعت ہوئی تاکہ مکمل کرنے والی تراویح اور جن کی تکمیل ہوگی یعنی فرض وواجب دونوں برابر ہوجائیں۔\n اور مراقی الفلاح کے قول وَھِیَ عِشْرُونَ رَکْعَۃً کے تحت علامہ طحطاوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ تحریر فرماتے ہیں:\n ’’ اَلْحکمَۃُ فِی تَقدِیرِھَا بِھذَا الْعدَدِ مُسَاوَاۃ المُکَمِّلِ وَھِیَ السنن للمکمَّل وَھِیَ الْفَراءِضُ الْاِعتقَادِیّۃ وَالْعَمَلِیَّۃ ‘‘ ۔ (19)\n یعنی بیس رکعت تراویح مقرر کرنے میں حکمت یہ ہے کہ مکمل کرنے والی سنتوں کی رکعات اور جن کی تکمیل ہوتی ہے یعنی فرض وواجب کی رکعات کی تعداد برابر ہوجائیں۔\n اور درمختار مع شامی جلد اول ص:۴۹۵میں ہے :\n ’’ وَہِیَ عِشْرُونَ رَکْعَۃً حِکْمَتُہُ مُسَاوَاۃُ الْمُکَمِّلِ لِلْمُکَمَّلِ ‘‘۔ (20)\nیعنی تراویح بیس رکعت ہے اور بیس رکعت تراویح میں حکمت یہ ہے کہ مکمِّل مکمَّل کے برابر ہو۔\n اور درمختار کی اسی عبارت کے تحت شامی میں نہر سے منقول ہے :\n’’ لَا یَخْفَی أَنَّ الرَّوَاتِبَ وَإِنْ کَمُلَتْ أَیْضًا إلَّا أَنَّ ہَذَا الشَّہْر لِمَزِیدِ کَمَالِہِ زِیدَ فِیہِ ہَذَا الْمُکَمِّلُ فَتَکْمُلُ ‘‘۔ (21)\n یعنی واضح ہو کہ فرائض اگرچہ پہلے سے بھی مکمل ہیں لیکن ماہِ رمضان میں اس کے کمال کی زیادتی کے سبب یہ مکمل یعنی بیس رکعت تراویح بڑھا دی گئی تو وہ خوب کامل ہوگئے ۔\n------------------\n[1] ’’ بدائع الصنائع ‘‘، کتاب الصلاۃ ، فصل فی مقدار التراویح ، ج ۱، ص ۶۴۴.\n[2] ’’ عمدۃ القاری شرح صحیح البخاری ‘‘، کتاب التراویح ، باب فضل من قام رمضان ، ج ۸، ص ۲۴۶.\n[3] ’’ مراقی الفلاح شرح نور الایضاح ‘‘، کتاب الصلاۃ ، فصل فی صلاۃ التراویح ، ص :۲۴۴.\n[4] ’’ عمدۃ الرعایۃ حاشیۃ شرح الوقایۃ ‘‘، باب بیان سنیۃ التراویح وتعداد رکعتھا ، ص ۲۰۷.\n[5] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الصلاۃ ، باب قیام شھر رمضان ، الحدیث : ۱۳۰۳، ج ۳، ص ۳۸۲.\n[6] ’’ سنن الترمذی ‘‘، کتاب الصوم ، باب ما جاء فی قیام شھر رمضان ، ج ۲، ص ۲۱۵.\n[7] ’’ فتح باب العنایۃ بشرح النقایۃ ‘‘، کتاب الصلاۃ ، ج ۱، ص ۳۴۲۔ \n[8] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، باب الوتر ، فصل فی صلاۃ التراویح ، ص ۴۱۱.\n[9] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الوتر والنوافل ، مبحث صلاۃ التراویح ، ج ۲، ص ۳۹۹.\n[10] ’’ البحر الرائق ‘‘، کتاب الصلاۃ ، باب الوتر والنوافل ، ج ۲، ص ۱۱۷.\n[11] ’’ العنایۃ شرح الہدایۃ ‘‘، کتاب الصلاۃ ، فصل فی قیام شھر رمضان ، ج ۱، ص ۴۰۸.\n[12] ’’ الکفایۃ ‘‘، کتاب الصلاۃ ، فصل فی قیام شھر رمضان ، ج ۱، ص ۴۰۷.\n[13] ’’ بدائع الصنائع ‘‘، کتاب الصلاۃ ، فصل فی مقدار التراویح ، ج ۱، ص ۶۴۴.\n[14] ’’ إحیاء علوم الدین ‘‘ کتاب إسرار الصلاۃ ومھماتھا ، القسم الثالث ، ج ۱، ص ۲۷۱.\n[15] ’’ شرح الوقایۃ ‘‘، کتاب الصلاۃ ، باب سنیۃ التراویح وتعداد رکعتھا ، ص ۲۰۷.\n[16] ’’ الفتاوی الھندیۃ ‘‘، الباب التاسع فی النوافل ، فصل فی التراویح ، ج ۱، ص ۱۱۵.\n[17] ’’ حجۃ اللّٰہ البالغۃ ‘‘، حصہ دوم ، ص ۱۸.\n[18] ’’ البحر الرائق ‘‘، کتاب الصلاۃ ، باب الوتر والنوافل ، ج ۲، ص ۱۱۷.\n[19] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، باب الوتر ، فصل فی صلاۃ التراویح ، ص ۴۱۴.\n[20] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصلاۃ ، باب الوتر إلخ ، مبحث صلاۃ التراویح ، ج ۲، ص ۵۹۹.\n[21] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الوتر والنوافل ، مبحث صلاۃ التراویح ، ج ۲، ص ۵۹۹."}, {"id": 7787, "bookId": 14, "volNo": "1", "hadithNo": 19, "chapter": "قراۃ خلف الامام", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث نمبر1:\n’’عَنْ عَطَاء بْنِ یَسَارٍ أَنَّہُ سَأَلَ زَیْدَ بْنَ ثَابِتٍ عَنْ الْقِرَاء ۃِ مَعَ الْإِمَامِ فَقَالَ لَا قِرَاء ۃَ مَعَ الْإِمَامِ فِی شَیْئٍ‘‘ . \nحدیث نمبر2:\n’’عَنْ أَبِی مُوسَی الْأَشْعَرِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا صَلَّیْتُمْ فَأَقِیْمُوْا صُفُوْفَکُمْ ثُمَّ لْیَؤُمَّکُمْ أَحَدُکُمْ فَإِذَا کَبَّرَ فَکَبِّرُوْا وَإِذَا قَرَأَ فَأَنْصِتُوا‘‘۔\nحدیث نمبر3:\n’’عَنْ جَابِرِ بْنِ عَبْدِ اللّٰہ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ صَلَّی خَلْفَ الإِمَامِ فَإِنَّ قِرَاءَ ۃَ الْإِمَامِ لَہُ قِرَاء ۃٌ ‘‘۔ \nحدیث نمبر4:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّمَا جُعِلَ الْإِمَامُ لِیُؤْتَمَّ بِہِ فَإِذَا قَرَأَ فَأَنْصِتُوا ‘‘۔", "urdu": "¥ترجمہ حدیث نمبر1:\nحضرت عطاء بن یسار رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ انہوں نے حضرت زید بن ثابت رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے امام کے ساتھ قراء ت کرنے کے بارے میں پوچھا تو انہوں نے فرمایا کہ امام کے ساتھ کسی بھی نماز میں قراء ت جائز نہیں خواہ سری ہو یا جہری ۔ (مسلم جلد اول ص۲۱۵)\n¥ترجمہ حدیث نمبر2:\nحضرت ابو موسیٰ اشعری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جب تم نماز پڑھو تو اپنی صفیں سیدھی کرو پھر تم میں کوئی امامت کرے تو جب وہ تکبیر کہے تم بھی تکبیر کہو اور جب وہ قراء ت کرے تم چپ رہو۔ (مسلم)\n¥ترجمہ حدیث نمبر3:\nحضرت جابر بن عبد اللّٰہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جو شخص امام کے پیچھے نمازپڑھے تو امام کی تلاوت مقتدی ہی کی تلاوت ہے ۔ (موطا امام محمد، ص ۹۹)\n¥ترجمہ حدیث نمبر4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ امام صرف اس لیے مقرر کیا گیا ہے کہ اس کی پیروی کی جائے تو جب وہ تلاوت کرے تو تم خاموش رہو۔ (طحاوی ص ۱۰۶)", "roman": "Tarjuma Hadees 1: Hazrat Ataa Bin Yasar Radiyallahu Anhu se Riwayat hai ke unhon ne Hazrat Zaid Bin Sabit Radiyallahu Anhu se Imam ke sath qirat karne ke bare mein pucha to unhon ne farmaya ke Imam ke sath kisi bhi Namaz mein qirat Jaiz nahi khwah sirri ho ya jahri. (Muslim Jild Awwal). Tarjuma Hadees 2: Hazrat Abu Moosa Ash'ari Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab tum Namaz parho to apni safein seedhi karo phir tum mein koi Imamat kare to jab woh Takbeer kahe tum bhi Takbeer kaho aur jab woh qirat kare tum chup raho. (Muslim). Tarjuma Hadees 3: Hazrat Jabir Bin Abdullah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs Imam ke peeche Namaz parhe to Imam ki tilawat Muqtadi hi ki tilawat hai. (Muwatta Imam Muhammad). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Imam sirf is liye muqarrar kiya gaya hai ke us ki pairwi ki jaye to jab woh tilawat kare to tum khamosh raho. (Tahawi).", "explanation": "¥شرح حدیث نمبر3:\n’’ قَالَ مُحَمَّدُ بْنُ مَنِیعٍ وَابْنُ الْھُمامِ ھَذَا الْإِسْنَادُ صَحِیْحٌ عَلَی شَرْطِ الشَّیْخَینِ ‘‘\nحضرت محمد بن منیع اور امام بن الہمام نے فرمایا کہ یہ اسناد مسلم اور بخاری کی شرط پر صحیح ہے ۔\n عَنِ ابْنِ عُمَرَ قَالَ مَنْ صَلَّی خَلْفَ الإِمَامِ کَفَتْہُ قِرَاء تُہ ۔ (1)\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے فرمایا کہ جو شخص امام کے پیچھے نماز پڑھے تو امام کی تلاوت اس کے لیے کافی ہے ۔ (موطاامام محمد، ص۹۷)\n------------------\n[1] ’’ مؤطا ‘‘ للإمام مالک بروایۃ إمام محمد ، کتاب الصلاۃ ، الحدیث : ۱۱۵، ج ۱، ص ۴۱۳.\n¥شرح حدیث نمبر4:\nمسلم شریف جلد اول ص۱۷۵ میں ہے :\n’’ فَقَالَ لَہُ أَبُو بَکْرٍ فَحَدِیثُ أَبِی ہُرَیْرَۃَ فَقَالَ ہُوَ صَحِیحٌ یَعْنِی وَإِذَا قَرَأَ فَأَنْصِتُوا ‘‘۔ (1)\nیعنی ابوبکر نے سلیمان سے پوچھا کہ ابوہریرہ کی حدیث کیسی ہے تو انہوں نے فرمایا کہ صحیح ہے یعنی یہ حدیث کہ جب امام تلاوت کرے تو تم خاموش رہو۔\n¥اِنتباہ :\n صاحبِ ہدایہ نے امام کے پیچھے قرات نہ کرنے پر صحابہ کا اجماع نقل کیا ہے جیسا کہ ہدایہ جلد اول ص۸۲ میں ہے :\n’ ’ لَا یَقْرَأُ الْمُؤْتَمُّ خَلْفَ الْإِمَام وَعَلَیْہِ إجْمَاعُ الصَّحَابَۃِ ‘‘۔ (2)\nیعنی مقتدی امام کے پیچھے قراء ت نہ کرے اور اسی پر صحابہ کا اجماع ہے ۔\n اور عنایہ میں اسی کے تحت ہے :\n’’ اَلْمُرَادَ بِہِ إجْمَاعُ أَکْثَرِ الصَّحَابَۃِ ، فَإِنَّہُ رُوِیَ عَنْ ثَمَانِینَ نَفَرًا مِنْ کِبَارِ الصَّحَابَۃِ مَنْعَ الْمُقْتَدِی عَنْ الْقِرَاءَ ۃِ خَلْفَ الْإِمَامِ . وَقَالَ الشَّعْبِیُّ أَدْرَکْتُ سَبْعِیْنَ بَدْرِیًّا کُلُّہُمْ یَمْنَعُونَ الْمُقْتَدِی عَنْ الْقِرَاءَ ۃِ خَلْفَ الْإِمَامِ ، وَقِیلَ الْمُرَادُ بِہِ إجْمَاعُ مُجْتَہِدِی الصَّحَابَۃِ وَکِبَارِہِمْ ، وَقَدْ رُوِیَ عَنْ عَبْدِ اللّٰہ بْنِ زَیْدِ بْنِ أَسْلَمَ عَنْ أَبِیہِ قَالَ کَانَ عَشَرَۃٌمِنْ أَصْحَابِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَنْہَوْنَ عَنْ الْقِرَاءَ ۃِ خَلْفَ الْإِمَامِ أَشَدَّ النَّہْیِ أَبُو بَکْرٍن الصِّدِّیق وَعُمَرُ بْنُ الْخَطَّابِ وَعُثْمَانُ بْنُ عَفَّانَ وَعَلِیُّ بْنُ أَبِی طَالِبٍ وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ وَسَعْدُ بْنُ أَبِی وَقَّاصٍ وَعَبْدُ اللّٰہ بْنُ مَسْعُودٍ وَزَیْدُ بْنُ ثَابِتٍ وَعَبْدُ اللّٰہ بْنُ عُمَرَ وَعَبْدُ اللّٰہ بْنُ عَبَّاسٍ رَضِیَ اللّٰہ عَنْہُم ‘‘۔ (3)\nیعنی ہدایہ کے قول إِجْمَاعُ الصَّحَابَۃِ کا مطلب یہ ہے کہ اکثر صحابہ کا اجماع ہے اس لیے کہ امام کے پیچھے قراء ت کر نے سے مقتدی کا منع کیا جانا بڑے بڑے اسی صحابہ کرام سے مروی ہے ۔ اور امام شعبی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ میں نے جنگ بدر میں شریک ہونے والے ستر صحابہ کرام سے ملاقات کی وہ سب کے سب امام کے پیچھے قراء ت کرنے سے مقتدی کو منع فرماتے تھے اور بعض لوگوں نے کہا کہ اجماع صحابہ کا مطلب مجتہدین صحابہ و کبار صحابہ کا اجماع ہے ۔ اوربے شک حضرت عبد اللّٰہ بیان کرتے ہیں کہ میرے والد حضر ت زید بن اسلم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کے صحابہ کرام میں سے دس حضرات یعنی حضرت ابوبکر صدیق ، حضرت عمر بن خطاب، حضرت عثمان بن عفان، حضرت علی بن ابو طالب ، حضرت عبدالرحمن بن عوف، حضرت سعد بن وقاص، حضرت عبد اللّٰہ بن مسعود، حضرت زید بن ثابت ، حضر ت عبد اللّٰہ بن عمر اور حضرت عبد اللّٰہ بن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم اجمعین یہ سب کے سب امام کے پیچھے قراء ت کرنے سے سختی کے ساتھ منع فرماتے تھے ۔ اورکفایہ میں ہے :\n ’’ مَنع الْمُقْتَدِی عَنِ القراءَ ۃِ مَاثورٌ عَنْ ثَمَانینَ نفراً مِن کِباَر الصَّحَابَۃِ مِنْھُمْ المُرْتَضی وَالْعَبَادِلَۃ رَضِیَ اللّٰہ عَنْہُم ‘‘۔ (4)\nیعنی بڑے بڑے اسی صحابہ کے بارے میں روایت آئی ہے کہ وہ مقتدی کو قر اء ت سے روکتے تھے ۔ ان میں حضرت علی مرتضٰی، حضرت عبد اللّٰہ بن عباس، حضرت عبد اللّٰہ بن عمر اورحضرت عبد اللّٰہ بن مسعودبھی ہیں۔\n اور درمختارمیں ہے :\n ’’ الْمُؤْتَمُّ لَا یَقْرَأُ مُطْلَقًا فَإِنْ قَرَأَ کُرِہَ تَحْرِیمًا ‘‘ ۔ (5)\nیعنی مقتدی سورۂ فاتحہ یا کسی دوسری سورت کی قراء ت نہیں کرے گا۔ اگر اس نے قراء ت کی تو مکروہ تحریمی کا مرتکب ہوگا۔\n------------------\n[1] ’’ صحیح مسلم ‘‘، کتاب الصلاۃ ، باب التشھد فی الصلاۃ ، الحدیث : ۶۳۔ (۴۰۴) ص ۲۱۵.\n[2] ’’ الہدایۃ ‘‘، کتاب الصلاۃ ، باب صفۃ الصلاۃ ، فصل فی القراء ۃ ، ج ۱، ص ۵۶.\n[3] ’’ العنایۃ شرح الہدایۃ ‘‘، کتاب الصلاۃ ، فصل فی القراء ۃ ، ج ۱، ص ۲۹۴.\n[4] ’’ الکفایۃ ‘‘، کتاب الصلاۃ ، فصل فی القراء ۃ ، ج ۱، ص ۲۹۷.\n[5] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، فصل فی القراء ۃ ، ج ۱، ص ۳۲۶."}, {"id": 7788, "bookId": 14, "volNo": "1", "hadithNo": 20, "chapter": "آمین بالسر", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَمَّنَ الْإِمَامُ فَأَمِّنُوا فَإِنَّہُ مَنْ وَافَقَ تَأْمِینُہُ تَأْمِینَ الْمَلَاءِکَۃِ غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ مُتَّفَقٌ عَلَیْہِ وَفِیْ رِوَایَۃٍ قَالَ إِذَا قَالَ الْإِمَامُ غَیْرِ الْمَغْضُوبِ عَلَیْہِمْ وَلَا الضَّالِّینَ فَقُولُوا آمِینَ فَإِنَّہُ مَنْ وَافَقَ قَوْلُہُ قَوْلَ الْمَلَاءِکَۃِ غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ ھَذَا لَفْظُ الْبُخَاري وَلِمُسْلمٍ نَحْوہ‘‘۔", "urdu": "¥ترجمہ حدیث1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جب امام آمین کہے تو تم بھی آمین کہو، اس لیے کہ جس کی آمین ملائکہ کی آمین کے موافق ہوگی تو اس کے پچھلے گناہ معاف کردیئے جائیں گے ۔ (بخاری، مسلم) اور ایک روایت میں یہ الفاظ ہیں کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا جب امام غَیْرِالْمَغضوبِ عَلَیھمِ ولا الضَّالِین کہے تو تم آمین کہو اس لیے کہ جس کا آمین کہنا فرشتوں کی آمین کہنے کے مطابق ہوگا تو اس کے گزشتہ گناہ بخش دیئے جائیں گے ۔ یہ الفاظ بخاری کے ہیں اور مسلم میں بھی اسی کے مثل ہے ۔ ( مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab Imam Aameen kahe to tum bhi Aameen kaho, is liye ke jis ki Aameen malaika ki Aameen ke muwafiq hogi to us ke pichle gunah maaf kar diye jayen ge. (Bukhari, Muslim). Aur ek Riwayat mein ye alfaaz hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya jab Imam 'Ghairil Maghdoobi Alaihim Walad-Daalleen' kahe to tum Aameen kaho is liye ke jis ka Aameen kehna farishton ki Aameen kehne ke mutabiq hoga to us ke guzashta gunah bakhsh diye jayen ge. Ye alfaaz Bukhari ke hain aur Muslim mein bhi isi ke misl hai. (Mishkat).", "explanation": "اس حدیث شریف سے دو باتیں واضح طور پر معلوم ہوئیں:\n ٭…اوّل یہ کہ مقتدی امام کے پیچھے سورۂ فاتحہ نہ پڑھے اس لیے کہ اگر مقتدی کو سورۂ فاتحہ پڑھنے کا حکم ہوتا تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ یوں فرماتے کہ جب تم وَلَا الضَّآلِین کہو تو آمین کہو۔ معلوم ہوا کہ مقتدی صرف آمین کہے گا۔ وَلَا الضَّآلِین کہنا امام کا کام ہے ۔\n ٭…دوسری بات یہ معلوم ہوئی کہ آمین آہستہ کہنا چاہیے کہ فرشتے بھی آہستہ آمین کہتے ہیں۔ اسی لیے ہم لوگ ان کے آمین کہنے کی آواز نہیں سُنتے ہیں۔ لہذا بلند آواز سے آمین کہنا فرشتوں کے آمین کہنے کی مخالفت کرنا ہے ۔\n کنزالدقائق اور بحرالرائق جلد اول، ص۳۱۳ میں ہے :\n أَمَّنَ الْإِمَامُ وَالْمَأْمُومُ سِرًّا ۔ (1)\nیعنی امام اور مقتدی دونوں آہستہ آمین کہیں ۔\nاور درمختار میں ہے :\n أَمَّنَ الْإِمَامُ سِرًّا کَمَأْمُومٍ وَمُنْفَرِدٍ ۔ (2)\nیعنی امام آہستہ آمین کہے جیسے کہ مقتدی اور منفرد۔\n------------------\n[1] ’’ البحر الرائق ‘‘، کتاب الصلاۃ ، باب صفۃ الصلاۃ ، ج ۱، ص ۵۴۷.’’ کنز الدقائق ‘‘، کتاب الصلوۃ ، ص ۲۵۔ \n[2] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، مطلب قراء ۃ البسلمۃ بین الفاتحۃ إلخ ، ج ۲، ص ۲۳۸۔ ۲۳۹ ."}, {"id": 7789, "bookId": 14, "volNo": "1", "hadithNo": 21, "chapter": "رفع یدین کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ عَلْقَمَۃَ قَالَ قَالَ عَبْدُ اللّٰہ بْنُ مَسْعُودٍ أَلا أُصَلِّی بِکُمْ صَلَاۃَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَصَلَّی فَلَمْ یَرْفَعْ یَدَیْہِ إِلَّا فِی أَوَّلِ مَرَّۃٍ قَالَ أَبُو عِیسَی حَدِیثُ ابْنِ مَسْعُودٍ حَدِیثٌ حَسَنٌ وَبِہِ یَقُولُ غَیْرُ وَاحِدٍ مِنْ أَہْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَالتَّابِعِینَ‘‘ ۔\nحدیث 2:\nعَنْ الْبَرَاءِ بْنِ عَازِبٍ رَضِیَ اللّٰہ عَنْہُ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إذَا کَبَّرَ لِافْتِتَاحِ الصَّلَاۃِ، رَفَعَ یَدَیْہِ حَتَّی یَکُونَ إبْہَامَاہُ قَرِیبًا مِنْ شَحْمَتَیْ أُذُنَیْہِ، ثُمَّ لَا یَعُودُ۔ \nحدیث 3:\n’’ عَنْ الْأَسْوَدِ قَالَ رَأَیْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِیَ اللّٰہ عَنْہُ یَرْفَعُ یَدَیْہِ فِی أَوَّلِ تَکْبِیرَۃٍ ثُمَّ لَا یَعُودُ‘‘۔ \nحدیث 4:\n’’ عَنْ مُجَاہِدٍ قَالَ صَلَّیْتُ خَلْفَ ابْنِ عُمَرَ رَضِیَ اللّٰہ عَنْہُم ا فَلَمْ یَکُنْ یَرْفَعُ یَدَیْہِ إلَّا فِی التَّکْبِیرَۃِ الْأُولَی مِنْ الصَّلَاۃِ‘‘ ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت علقمہ نے کہا کہ حضرت عبد اللّٰہ بن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں تمہارے سامنے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی نماز نہ پڑھوں پس آپ نے نماز پڑھی اور صرف شروع نماز میں اپنے ہاتھوں کو اٹھایا، امام ترمذی نے فرمایا کہ ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کی حدیث حسن ہے اور بہت سے علمائے صحابہ اور علمائے تابعین یہی فرماتے ہیں (کہ شروع نماز کے علاوہ رفع یدین نہ کیا جائے )۔ (ترمذی جلد اول ص۳۵)\n¥ترجمہ حدیث 2:\nحضرت براء بن عازب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم علیہ الصلاۃ والتسلیم جب نماز شروع فرمانے کے لیے تکبیر کہتے تو اپنے دست ِ مبارک کو اٹھاتے یہاں تک کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے انگوٹھے کانوں کی لو کے قریب ہوجاتے پھر حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم آخر نماز تک رفع یدین نہ فرماتے ۔ (طحاوی ص۱۱۰)\n¥ترجمہ حدیث 3:\nحضرت اسود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے فاروقِ اعظم حضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کو دیکھا کہ پہلیتکبیر میں ہاتھ اُٹھاتے تھے پھر آخر نماز تک ایسا نہیں کرتے تھے ۔ (طحاوی ۱۱۱)\n¥ترجمہ حدیث 4:\nحضرت مجاہد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا کی اقتداء میں نماز پڑھی تو وہ صرف تکبیراولیٰ میں رفع یدین کرتے تھے ۔ (طحاوی ۱۱۰)", "roman": "Tarjuma Hadees 1: Hazrat Alqama ne kaha ke Hazrat Ibn Mas'ood Radiyallahu Anhu ne farmaya ke main tumhare samne Rasoolullah Sallallahu Alayhi wa Sallam ki Namaz na parhoon? Pas aap ne Namaz parhi aur sirf shuru Namaz mein apne hathon ko uthaya, Imam Tirmizi ne farmaya ke Ibn Mas'ood Radiyallahu Anhu ki Hadees Hasan hai aur bohat se ulama-e-Sahabah aur ulama-e-Taabi'een yahi farmate hain (ke shuru Namaz ke ilawa rafa-e-yadain na kiya jaye). (Tirmizi Jild Awwal). Tarjuma Hadees 2: Hazrat Baraa Bin Aazib Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam jab Namaz shuru farmane ke liye Takbeer kehte to apne dast-e-mubarak ko uthate yahan tak ke Rasoolullah Sallallahu Alayhi wa Sallam ke angoothe kanon ki lau ke qareeb ho jate phir Rasoolullah Sallallahu Alayhi wa Sallam aakhir Namaz tak rafa-e-yadain na farmate. (Tahawi). Tarjuma Hadees 3: Hazrat Aswad Radiyallahu Anhu ne farmaya ke main ne Farooq-e-Azam Hazrat Umar Radiyallahu Anhu ko dekha ke pehli Takbeer mein hath uthate thay phir aakhir Namaz tak aisa nahi karte thay. (Tahawi). Tarjuma Hadees 4: Hazrat Mujahid Radiyallahu Anhu ne farmaya ke main ne Hazrat Ibn Umar Radiyallahu Anhum ki iqtida mein Namaz parhi to woh sirf Takbeer-e-Oola mein rafa-e-yadain karte thay. (Tahawi).", "explanation": "ان احادیثِ کریمہ سے واضح طور پرمعلوم ہوا کہ حضور سیدعالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ، حضرت فاروقِ اعظم، حضرت عبد اللّٰہ بن مسعود ، حضرت ابن عمر اور صحابہ و تابعین کے دیگر جلیل القدر علماء رضوان اللّٰہ علیہم اجمعین صرف تکبیر تحریمہ کے لیے رفع یدین کرتے تھے پھرآخر نماز تک ایسا نہیں کر تے تھے ۔ اور بعض روایتوں سے جو رکوع کے پہلے اور بعد میں رفع یدین ثابت ہے تو وہ حکم پہلے تھا۔ بعد میں منسوخ ہوگیا۔\n جیسا کہ عینی شار ح بخاری نے حضرت عبد اللّٰہ بن زبیر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت کی ہے :\n’’ أَنَّہُ رَای رَجُلًا یَرْفَعُ یَدَیْہِ فِی الصَّلَوۃِ عِنْدَ الرَّکُوعِ وَعِنْدَ رَفْعِ رَأْسِہِ مِنَ الرَّکُوعِ فَقَالَ لَہُ لَا تَفْعلْ فَاِنَّہُ شَیئٌ فَعَلَہُ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ثُمَّ تَرَکَہَ ‘‘ ۔ ([1])\n یعنی حضرت عبد اللّٰہ بن زبیر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے ایک شخص کو رکوع میں جاتے ہوئے اور رکوع سے اٹھتے وقت رفع یدین کرتے ہوئے دیکھا تو آپ نے اس سے فرمایا کہ ایسا نہ کرو اس لیے کہ یہ ایسی چیز ہے کہ جس کو حضور علیہ الصلاۃ والسلام نے پہلے کیا تھا پھر بعد میں چھوڑ دیا۔\n------------------\n[1] ’’ عمدۃ القاری شرح صحیح البخاری ‘‘، ج ۴، ص ۳۸۰."}, {"id": 7790, "bookId": 14, "volNo": "1", "hadithNo": 22, "chapter": "دُرود شریف", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ صَلَّی عَلَیَّ صَلَاۃً وَاحِدَۃً صَلَّی اللّٰہ عَلَیْہِ عَشْرَ صَلَوَاتٍ وَحُطَّتْ عَنْہُ عَشْرُ خَطِیءَاتٍ وَرُفِعَتْ لَہُ عَشْرُ دَرَجَاتٍ‘‘ ۔\nحدیث 2:\n’’ عَنِ ابْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَوْلَی النَّاسِ بِی یَوْمَ الْقِیَامَۃِ أَکْثَرُہُمْ عَلَیَّ صَلَاۃً ‘‘۔\nحدیث 3:\n’’عَنْ أُبَیِّ بْنِ کَعْبٍ قَالَ قُلْتُ یَا رَسُولَ اللّٰہ إِنِّی أُکْثِرُ الصَّلَاۃَ عَلَیْکَ فَکَمْ أَجْعَلُ لَکَ مِنْ صَلَاتِی فَقَالَ مَا شِئْتَ قَالَ قُلْتُ الرُّبُعَ قَالَ مَا شِئْتَ فَإِنْ زِدْتَ فَہُوَ خَیْرٌ لَّکَ قُلْتُ النِّصْفَ قَالَ مَا شِئْتَ فَإِنْ زِدْتَ فَہُوَ خَیْرٌ لَّکََ قُلْتُ فَالثُّلُثَیْنِ قَالَ مَا شِئْتَ فَإِنْ زِدْتَ فَہُوَ خَیْرٌ لَّکَ قُلْتُ أَجْعَلُ لَکَ صَلَاتِی کُلَّہَا قَالَ إِذًا یکْفِی ہَمَّکَ وَیُکَفَّرُلَکَ ذَنْبُکَ‘‘۔\nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ رَغِمَ أَنْفُ رَجُلٍ ذُکِرْتُ عِنْدَہُ فَلَمْ یُصَلِّ عَلَیَّ‘‘ ۔\nحدیث 5:\n’’ عَنْ عَلِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْبَخِیلُ الَّذِی مَنْ ذُکِرْتُ عِنْدَہُ فَلَمْ یُصَلِّ عَلَیَّ‘‘ ۔\nحدیث 6:\n’’ عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ إِنَّ الدُّعَاء مَوْقُوفٌ بَیْنَ السَّمَاءِ وَالْأَرْضِ لَا یَصْعَدُ مِنْہُ شَیْئٌ حَتَّی تُصَلِّیَ عَلَی نَبِیِّکَ‘‘ ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص مجھ پر ایک بار درود بھیجے گا خدائے تعالیٰ اس پر دس مرتبہ رحمت نازل فرمائے گا اورا س کے دس گناہوں کو معاف فرمائے گا۔ اور دس درجے بلند فرمائے گا۔ (نسائی)\n صَلَّی اللّٰہ عَلَی النَّبِیِّ الْاُمِّیِّ وَآلِہِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَلَوۃً وَّسَلَاماً عَلَیْکَ یَارَسُوْلَ اللّٰہ \n¥ترجمہ حدیث 2:\nحضرت ابنِ مسعود ر ضی اللّٰہ تعالیٰ عنہ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ قیامت کے دن لوگوں میں سب سے زیادہ میرے قریب وہ شخص ہوگا جس نے سب سے زیادہ مجھ پر درود بھیجا ہے ۔ (ترمذی)\n أَللَّہُمَّ صَلِّ عَلَی سَیِّدِنَا وَمَوْلَانَا مُحَمَّدٍ وَّعَلَی آلِ سَیِّدِنَا وَمَوْلَانَا مُحَمَّدٍ وَّبَارِکْ وَسَلِّم \n¥ترجمہ حدیث 3:\nحضرت ابی بن کعب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے عرض کیا یارسول اللّٰہ ! میں آپ پر کثرت سے درود پڑھنا چاہتا ہوں اب اس کے لیے اپنے اوراد و وظائف کے اوقات میں سے کتنا وقت مقرر کروں؟ فرمایا جتنا تم چاہو ؟ عرض کیا چوتھائی؟فرمایا جتناتم چاہو اور اگر زیادہ کرلو تو تمہارے لیے اور بہتر ہے ۔ میں نے عرض کیا نصف ؟ فرمایا جتنا تم چاہو اور اگر اس سے بھی زیادہ کرلو تو تمہارے لیے بہتر ہے ۔ میں نے عرض کیا دو تہائی؟ فرمایا جتنا تم چاہو اگر زیادہ کرلو تو تمہارے لیے اور بہتر ہے میں نے عرض کیا تو پھر سارا وقت درود ہی کے لیے مقرر کرلوں؟ فرمایا ایسا ہو تو وہ تمہارے سارے اُمور کے لیے کافی ہوگا اور تمہارا گناہ معاف کردیاجائے گا۔ (ترمذی)\n صَلَّی اللّٰہ عَلَی النَّبِیِّ الْاُمِّیِّ وَآلِہِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَلَوۃً وَّسَلَاماً عَلَیْکَ یَارَسُوْلَ اللّٰہ \n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اس شخص کی ناک خاک آلود ہو جس کے سامنے میرا ذکر کیا جائے اور وہ مجھ پر درود نہ پڑھے ۔ (ترمذی)\n أَللَّھُمَّ صَلِّ عَلَی سَیِّدِنَا و َمَوْلنَا مُحَمَّدٍ وَّعَلَی آلِ سَیِّدَنَا وَمَوْلنَا مُحَمَّدٍ مَعْدنِ الْجُوْدِ وَالْکَرَمِ وَأَصْحَابِہ وَبَارِکَ وَسَلّم \n¥ترجمہ حدیث 5:\nحضرت علی کرم اللّٰہ تعالیٰ وجہہ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اصل میں بخیل وہ شخص ہے جس کے سامنے میرا ذکر ہو اور وہ مجھ پر درود نہ پڑھے ۔ (ترمذی)\n صَلَّی اللّٰہ عَلَی النَّبِیِّ الْاُمِّیِّ وَآلِہِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَلَوۃً وَّسَلَاماً عَلَیْکَ یَارَسُوْلَ اللّٰہ \n¥ترجمہ حدیث 6:\nحضرت عمر بن الخطاب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ دعا آسمان و زمین کے درمیان معلق رہتی ہے اس میں سے کچھ اوپر نہیں چڑھتا جب تک کہ تو اپنے نبی پر درود نہ بھیجے ۔ (ترمذی)\n أَللَّہُمَّ صَلِّ وَسَلِّمِ وَبَارِکْ عَلَی سَیِّدِنَا مُحَمَّدٍ وآلِہِ وَصَحْبِہِ أَجْمَعِینَ", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs mujh par ek baar Durood bheje ga Allah Ta'ala us par das martaba rehmat nazil farmaye ga aur us ke das gunahon ko maaf farmaye ga. Aur das darje buland farmaye ga. (Nasa'i). Tarjuma Hadees 2: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Qayamat ke din logon mein sab se zyada mere qareeb woh shakhs hoga jis ne sab se zyada mujh par Durood bheja hai. (Tirmizi). Tarjuma Hadees 3: Hazrat Ubay Bin Ka'ab Radiyallahu Anhu ne farmaya ke main ne arz kiya Ya Rasoolullah! Main aap par kasrat se Durood parhna chahta hoon ab is ke liye apne aurad-o-wazaif ke auqat mein se kitna waqt muqarrar karoon? Farmaya jitna tum chaho? Arz kiya chauthai? Farmaya jitna tum chaho aur agar zyada kar lo to tumhare liye aur behtar hai. Main ne arz kiya nisf? Farmaya jitna tum chaho aur agar is se bhi zyada kar lo to tumhare liye behtar hai. Main ne arz kiya do tihai? Farmaya jitna tum chaho agar zyada kar lo to tumhare liye aur behtar hai. Main ne arz kiya to phir saari waqt Durood hi ke liye muqarrar kar loon? Farmaya aisa ho to woh tumhare saare umoor ke liye kafi hoga aur tumhara gunah maaf kar diya jaye ga. (Tirmizi). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke us shakhs ki naak khaak aalood ho jis ke samne mera zikr kiya jaye aur woh mujh par Durood na parhe. (Tirmizi). Tarjuma Hadees 5: Hazrat Ali Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke asal mein bakheel woh shakhs hai jis ke samne mera zikr ho aur woh mujh par Durood na parhe. (Tirmizi). Tarjuma Hadees 6: Hazrat Umar Bin Al-Khattab Radiyallahu Anhu ne farmaya ke Dua zameen-o-aasman ke darmiyan mu'allaq rehti hai is mein se kuch oopar nahi charhta jab tak ke tu apne Nabi par Durood na bheje. (Tirmizi).", "explanation": "¥انتباہ:\n (۱)… اکثر لوگ آج کل درود شریف کے بدلے صلعم ، عم ، ص ، ع لکھتے ہیں یہ ناجائز و حرام ہے ۔ اور اگر معاذ اللّٰہ استخفافِ شان کا قصد ہو تو قطعا کفر ہے ۔ اسی طرح صحابہ کرام اور اولیائے عظام ر ضی اللّٰہ تعالیٰ عنہم کے اسمائے مبارکہ کے ساتھ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کی جگہ رض لکھنا مکروہ و باعث محرومی ہے ۔ ([1]) (فتاوی افریقہ ، بہار شریعت)\n (۱)…جن کے نام محمد ، احمد، علی ، حسن، حسین وغیرہ ہوتے ہیں۔ بعض لوگ ان ناموں پر ص، ع بناتے ہیں یہ بھی ممنوع ہے ۔ اس لیے کہ اس جگہ تو یہ شخص مر اد ہے اس پر درود کا اشارہ کیا معنی؟\n٭…٭…٭…٭\n¥دُرود گنج عاشقاں\n صَلَّی اللّٰہ عَلَی النَّبِیِّ الْاُمِّیِّ وَآلِہِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَلَوۃً وَّسَلَاماً عَلَیْکَ یَارَسُوْلَ اللّٰہ \n جو شخص حضور اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم سے سچی محبت رکھے ، تمام جہان سے زیادہ حضور کی عظمت دل میں جمائے ، حضور کی شان گھٹانے والوں سے بیزار اور ان سے دوررہے ، وہ اگر اس درود شریف کو بعد نماز جمعہ مدینہ طیبہ کی طرف منہ کرکے دست بستہ کھڑے ہو کر سو بار پڑھے تو اس کے لیے بے شمار فائدے ہیں جن میں سے بعض یہاں درج کیے جاتے ہیں۔ اس درود شریف کے پڑھنے والے پر خدائے تعالیٰ تین ہزار رحمتیں نازل فرمائے گا۔ اس پر دو ہزار اپنا سلام بھیجے گا۔ پانچ ہزار نیکیاں اس کے نامہ اعمال میں لکھے گا۔ اس کے مال میں ترقی دے گا۔ اس کی اولاد اور اولاد کی اولاد میں برکت رکھے گا۔ دشمنوں پر غلبہ دے گا۔ کسی دن خواب میں سرکار اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی زیارت سے مشرف ہوگا۔ ایمان پر خاتمہ ہوگا قیامت میں حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی شفاعت واجب ہوگی اللّٰہ تعالیٰ اس سے ایسا راضی ہوگا کہ کبھی ناراض نہ ہوگا۔\n------------------\n[1] ’’فتاوی افریقہ‘‘، ص۵۰، ’’بہار ِ شریعت‘‘، ج۱، ص۵۳۴، ’’ حاشیۃ الطحطاوی علی الدر المختار ‘‘، خطبۃ الکتاب ، ج ۱، ص ۶ ."}, {"id": 7791, "bookId": 14, "volNo": "1", "hadithNo": 23, "chapter": "جماعت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَلاۃُ الْجَمَاعَۃِ تَفْضُلُ صَلاۃَ الْفَذِّ بِسَبْعٍ وَعِشْرِینَ دَرَجَۃً‘‘۔\nحدیث2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَیْسَ صَلاۃٌ أَثْقَل عَلَی الْمُنَافِقِینَ مِنَ الْفَجْرِ وَالْعِشَاءِ وَلَوْ یَعْلَمُونَ مَا فِیہِمَا لَأَتَوْہُمَا وَلَوْ حَبْوًا‘‘۔\nحدیث3:\n’’ عَنْ عُثْمَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ صَلَّی الْعِشَاءَ فِی جَمَاعَۃٍ فَکَأَنَّمَا قَامَ نِصْفَ اللَّیْلِ وَمَنْ صَلَّی الصُّبْحَ فِی جَمَاعَۃٍ فَکَأَنَّمَا صَلَّی اللَّیْلَ کُلَّہُ‘‘ ۔\nحدیث4:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَالَّذِی نَفْسِی بِیَدِہِ لَقَدْ ہَمَمْتُ أَنْ آمُرَ بِحَطَبٍ فَیُحْطَبَ ثُمَّ آمُرَ بِالصَّلَاۃِ فَیُؤَذَّنَ لَہَا ثُمَّ آمُرَ رَجُلًا فَیَؤُمَّ النَّاسَ ثُمَّ أُخَالِفَ إِلَی رِجَالٍ وَفِیْ رِوَایَۃٍ لَا یَشْہَدُونَ الصَّلاۃَ فَأُحَرِّقَ عَلَیْہِمْ بُیُوتَہُمْ‘‘۔\nحدیث5:\n’’ عَنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَوْلَا مَا فِی الْبُیُوتِ مِنَ النِّسَاءِ وَالذُّرِّیَّۃِ أَقَمْتُ صَلاۃَ الْعِشَاءِ وَأَمَرْتُ فِتْیَانِی یُحْرِقُونَ مَا فِی الْبُیُوتِ بِالنَّارِ‘‘ ۔\nحدیث6:\n ’’ عَنْ أَبِی الدَّرْدَاءِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا مِنْ ثَلاثَۃٍ فِی قَرْیَۃٍ وَلَا بَدْوٍ لَا تُقَامُ فِیہِمُ الصَّلَاۃُ إِلَّا قَدْ اسْتَحْوَذَ عَلَیْہِمُ الشَّیْطَانُ فَعَلَیْکَ بِالْجَمَاعَۃِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ نماز باجماعت کا ثواب تنہا پڑھنے کے مقابلے میں ستائیس درجہ زیادہ ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ منافقوں پر فجر اور عشاء کی نماز وں سے زیادہ کوئی نماز بھاری نہیں۔ اگر لوگ جانتے کہ ان دونوں نمازوں میں کیا اجر و ثواب ہے تو گھسٹتے ہوئے چل کر ان میں شریک ہوتے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت عثمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس نے عشاء کی نماز جماعت سے پڑھی تو گویا وہ آدھی رات تک عبادت میں کھڑا رہا اور جس نے فجر کی نماز جماعت سے ادا کی تو گویا اس نے ساری رات نماز پڑھی۔ (مسلم)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ قسم ہے اس ذات کی جس کے قبضۂ قدرت میں میری جان ہے کہ میرا جی چاہتا ہے کہ میں لکڑیاں جمع کرنے کا حکم دوں جب لکڑیاں جمع ہوجائیں تو نماز کا حکم دوں کہ اس کی اذان دی جائے پھر کسی کو حکم دوں کہ وہ لوگوں کو نماز پڑھائے ، پھر میں ان لوگوں کی طرف جاؤں جو نماز میں حاضر نہیں ہوتے یہاں تک کہ ان کے گھروں کو جلادوں۔ (بخاری، مسلم)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے رو ایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اگر گھروں میں عورتیں اور بچے نہ ہوتے تو میں عشاء کی نماز قائم کر تا اور اپنے جوانوں کو حکم دیتا کہ جو کچھ (بے نمازیوں کے ) گھروں میں ہے آگ سے جلادیں۔ (احمد)\n¥ترجمہ حدیث 6:\nحضرت ابوالدرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس آبادی یا جنگل میں تین آدمی ہوں اور ان میں نماز جماعت سے نہ قائم کی جائے تو شیطان ان پر غالب آجاتا ہے ۔ لہذا جماعت کو لازم جانو۔ (احمد، ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Namaz ba-Jama'at ka sawab tanha parhne ke muqable mein satais darja zyada hai. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke munafiqon par Fajr aur Isha ki Namazon se zyada koi Namaz bhari nahi. Agar log jante ke in dono Namazon mein kya ajr-o-sawab hai to ghasat-te hue chal kar in mein shareek hote. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Usman Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis ne Isha ki Namaz Jama'at se parhi to goya woh aadhi raat tak ibadat mein khara raha aur jis ne Fajr ki Namaz Jama'at se ada ki to goya us ne saari raat Namaz parhi. (Muslim). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke qasam hai us zaat ki jis ke qabza-e-qudrat mein meri jaan hai ke mera jee chahta hai ke main lakriyan jama karne ka Hukm doon jab lakriyan jama ho jayen to Namaz ka Hukm doon ke us ki Azan di jaye phir kisi ko Hukm doon ke woh logon ko Namaz parhaye, phir main un logon ki taraf jaoon jo Namaz mein hazir nahi hote yahan tak ke un ke gharon ko jala doon. (Bukhari, Muslim). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke agar gharon mein Aurat aur bache na hote to main Isha ki Namaz qaim karta aur apne jawanon ko Hukm deta ke jo kuch (be-namaziyon ke) gharon mein hai aag se jala dein. (Ahmad). Tarjuma Hadees 6: Hazrat Abu Darda Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis aabadi ya jangal mein teen aadmi hon aur un mein Namaz Jama'at se na qaim ki jaye to shaitan un par ghalib aa jata hai. Lehaza Jama'at ko lazim jano. (Ahmad, Abu Dawood).", "explanation": "¥انتباہ :\n عاقل، بالغ قادر پر جماعت واجب ہے ، بلا عذر ایک بار بھی چھوڑنے والا گنہ گار مستحق سزا ہے اور کئی بار ترک کرے توفاسق ، مردود الشہادۃ ہے ۔ اس کو سخت سزا دی جائے گی۔ اگر پڑوسیوں نے سکوت کیا(یعنی جماعت میں شریک ہونے کی تاکید نہیں کی اور خاموش رہے ) وہ بھی گنہ گار ہوں گے ۔ ([1]) (بہار شریعت، جلد سوم ص ۳۳۷)\n اور تنویر الابصار و درمختار میں ہے : قِیلَ وَاجِبَۃٌ وَعَلَیْہِ الْعَامَّۃُ أَيْ عَامَّۃُ مَشَایِخِنَا وَبِہِ جَزَمَ فِی التُّحْفَۃِ وَغَیْرِہَا قَالَ فِی الْبَحْرِ وَہُوَ الرَّاجِحُ عِنْدَ أَہْلِ الْمَذْہَبِ ۔ ([2])\n اور طحطاوی، ص:۱۷۱ میں ہے : ’’ فِی البدَائعِ عَامۃ المَشَایخ عَلَی الْوجُوبِ وَبِہِ جزمَ فِی التُّحْفَۃِ وَغَیرِھَا وَفِی جَامِع الْفقہِ أعدل الأَقْوَال وَأَقْوَاھَا الوُجُوب ‘‘۔ ([3])\n اورفتاویٰ عالمگیری جلد اول مصری ص:۷۷ میں ہے :’’ وَفِی الْغَایَۃِ قَالَ عَامَّۃُ مَشَایِخِنَا إنَّہَا وَاجِبَۃٌ وَفِی الْمُفِیدِ وَتَسْمِیَتُہَا سُنَّۃً لِوُجُوبِہَا بِالسُّنَّۃِ ‘‘۔ ([4])\n اور اشعۃ اللمعات جلد اول ص:۴۵۸میں ہے :\n شیخ ابن ہمام نقل کر دہ کہ اکثر مشائخ ما برین اندکہ جماعت واجب ست وتسمیۂ او بسنت بجہت آن ست کہ ثبوت وجوب آن بہ سنت است ۔ ([5])\nیعنی شیخ ابن ہمام رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے نقل فرمایا کہ ہمارے کثیر مشائخ کا مذہب یہ ہے کہ جماعت واجب ہے اور اس کا نام سنت اس وجہ سے ہے کہ اس کا وجوب سنت سے ثابت ہے ۔\n------------------\n[1] ’’بہار شریعت‘‘، ج۱، ص ۵۸۲، ’’ الدر المختار ورد المحتار ‘‘، کتاب الصلاۃ ، ج ۲، ص ۳۴۰.\n[2] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، ج ۲، ص ۳۴۵.\n[3] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، ص ۲۸۶.\n[4] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الخامس ، الفصل الأول فی الجماعۃ ، ج ۱، ص ۸۲.\n[5] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب الجماعۃ وفضلھا ، الفصل الأول ، ج ۱، ص ۴۹۲."}, {"id": 7792, "bookId": 14, "volNo": "1", "hadithNo": 24, "chapter": "مسجد کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عُثْمَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ بَنَی لِلَّہِ مَسْجِدًا بَنَی اللّٰہ لَہُ بَیْتًا فِی الْجَنَّۃِ ‘‘ ۔\nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَحَبُّ الْبِلَادِ إِلَی اللّٰہ مَسَاجِدُہَا وَأَبْغَضُ الْبِلَادِ إِلَی اللّٰہ أَسْوَاقُہَا‘‘۔\nحدیث 3:\n’’ عَنْ عُثْمَانَ بْنِ مَظْعُوْنٍ قَالَ یَارَسُوْلَ اللّٰہاِئْذَنْ لَنَا فِی التَّرَھُّبِ فَقَالَ اِنَّ تَرَھُّبَ اُمَّتِیْ الْجُلُوْسُ فِی الْمَسَاجِدِ اِنْتِظَارَ الصَّلَاۃِ‘‘ ۔\nحدیث 4:\n’’ عَنْ مُعَاوِیَۃَ بْنِ قُرَّۃَ عَنْ أَبِیہِ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ نَہَی عَنْ ہَاتَیْنِ الشَّجَرَتَیْنِ یَعْنِی الْبَصَلَ وَالثَّوْمَ وَقَالَ مَنْ أَکَلَہُمَا فَلا یَقْربَنَّ مَسْجِدَنَا وَقَالَ إِنْ کُنْتُمْ لَابُدَّ آکلیہِمَا فَأَمِیتُوہُمَا طَبْخًا‘‘۔\nحدیث 5:\n’’ عَنِ الْحَسَنِ مُرْسَلاً قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَاْتِیْ عَلَی النَّاسِ زَمَانٌ یَکُوْنُ حَدِ یْثُھُمْ فِیْ مَسَاجِدِ ھِمْ فِیْ أَمْرِ دُنْیَاھُمْ فَلاَ تُجَالِسُوْھُمْ فَلَیْسَ لِلَّہِ فِیْھِمْ حَاجَۃٌ‘‘ ۔", "urdu": "¥ترجمہ حدیث1:\nحضرت عثمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص خدائے تعالیٰ (کی خوشنودی) کے لیے مسجد بنائے گا تو خدائے تعالیٰ اس کے صلے میں جنت میں گھر بنائے گا۔ (بخاری، مسلم)\n¥ترجمہ حدیث2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالیٰ کے نزدیک تمام آبادیوں میں محبوب ترین جگہیں اس کی مسجد یں ہیں اور بدترین مقامات بازار ہیں۔ (مسلم)\n¥ترجمہ حدیث3:\nحضرت عثمان بن مظعون رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے عرض کیا یارسول اللّٰہ مجھے تارک الدنیا ہونے کی اجازت مرحمت فرمائیے ۔ حضور نے فرمایا کہ میری اُمت کے لیے ترکِ دنیا یہی ہے کہ وہ مسجدوں میں بیٹھ کر نماز کا انتظار کرے ۔ (شرح السنۃ، مشکوۃ)\n¥ترجمہ حدیث4:\nحضرت معاویہ بن قرّۃ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ااپنے باپ سے روایت کرتے ہیں کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے ان دو سبزیوں کے کھانے سے منع فرمایا یعنی پیاز اور لہسن سے اور فرمایا کہ اِنہیں کھا کر کوئی شخص ہماری مسجدوں کے قریب ہر گز نہ آئے ، اور فرمایا کہ اگر کھانا ہی چاہتے ہو تو پکا کر ان کی بُو دُور کرلیا کرو۔ (ابو داود)\n¥ترجمہ حدیث5:\nحضرت حسن بصری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے بطریق مرسل روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ایک زمانہ ایسا آئے گا کہ لوگ مسجدوں کے اندر دُنیا کی باتیں کریں گے تو اس وقت تم ان لوگوں کے پاس نہ بیٹھنا خدائے تعالیٰ کو ان لوگوں کی کچھ پروا نہیں۔ (بیہقی)", "roman": "Tarjuma Hadees 1: Hazrat Usman Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs Allah Ta'ala (ki khushnoodi) ke liye Masjid banaye ga to Allah Ta'ala us ke sile mein Jannat mein ghar banaye ga. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala ke nazdeek tamam aabadiyon mein mehboob tareen jaghein us ki Masajid hain aur badtareen maqamat bazaar hain. (Muslim). Tarjuma Hadees 3: Hazrat Usman Bin Maz'oon Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alayhi wa Sallam se arz kiya Ya Rasoolullah mujhe tarik-ud-dunya hone ki ijazat marhamat farmaye. Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke meri ummat ke liye tark-e-dunya yahi hai ke woh Masjidon mein baith kar Namaz ka intezar kare. (Sharh-us-Sunnah, Mishkat). Tarjuma Hadees 4: Hazrat Muawiyah Bin Qurrah Radiyallahu Anhum apne baap se Riwayat karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne in do sabziyon ke khane se mana farmaya yani pyaz aur lehsun se aur farmaya ke inhein kha kar koi shakhs hamari Masjidon ke qareeb har giz na aaye, aur farmaya ke agar khana hi chahte ho to paka kar in ki boo door kar liya karo. (Abu Dawood). Tarjuma Hadees 5: Hazrat Hasan Basri Radiyallahu Anhu se batareeq Mursal Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke ek zamana aisa aaye ga ke log Masjidon ke andar dunya ki batein karen ge to us waqt tum un logon ke paas na baithna Allah Ta'ala ko un logon ki kuch parwah nahi. (Baihaqi).", "explanation": "¥شرح حدیث4:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ:\n ’’ ہر چہ بوی ناخوش دارد از ماکولات وغیر ماکولات دریں حکم داخل ست ‘‘۔ ([1])( اشعۃ اللمعات ، جلد اول ص ۳۲۸)\nیعنی ہر وہ چیز کہ جس کی بُو ناپسند ہو اس حکم میں داخل ہے خواہ وہ کھانے والی چیزوں میں سے ہو یا نہ ہو۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب المساجد ومواضع الصلاۃ ، ج ۱، ص ۳۵۲.\n¥شرح حدیث5:\nحضرت شیخ محقق رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ کنایت است از بیزاری حق از ایشان ‘‘۔ ([1]) ( اشعۃ اللمعات ، جلد اول ص ۳۳۹)\n یعنی مطلب یہ ہے کہ خدائے تعالیٰ ان لوگوں سے بیزار ہے ۔\n¥انتباہ:\n (۱)…مسجد میں کچا لہسن اور پیاز کھانا یا کھا کر جانا جائز نہیں، جب تک کہ بُو باقی ہو اور یہی حکم ہر اس چیز کا ہے جس میں بُو ہو۔ جیسے بیڑی، سگریٹ پی کر یا مولی کھا کر جانا ، نیز جس کو گندہ د ہنی کی بیماری ہو یا کوئی بدبو دار دوا لگائی ہو تو جب تک بُو منقطع نہ ہو ان سب کو مسجد میں آنے کی ممانعت ہے ۔ اسی طرح مسجد میں ایسی ماچس اور دِیا سلائی جلانا کہ جس کے رگڑنے میں بُو اڑتی ہو منع ہے ۔ ([2])(درمختار، رد المحتار، بہار شریعت)\n (۲)…مسجد میں مٹی کا تیل جلانا حرام ہے مگر جب کہ اس کی بُو بالکل دُور کر دی جائے ۔ ([3]) (فتاوی رضویہ، جلد سوم ، ص ۵۹۸)\n (۳)…مسجد سے متصل کوئی مکان مسجد سے بلند ہو تو حرج نہیں اس لیے کہ مسجد ان ظاہری دیواروں کا نام نہیں بلکہ اس جگہ کے محاذ میں ساتوں آسمان تک سب مسجد ہے ۔\n درمختار میں ہے : ’’ أَنَّہُ مَسْجِدٌ إلَی عَنَانِ السَّمَاء ‘‘۔ ([4])ردالمحتارمیں ہے : ’’ وَکَذَا إلَی تَحْتِ الثَّرَی کَمَا فِی الْبِیرِیِّ عَنْ الْإِسْبِیجَابِیِّ ‘ ‘۔ ([5])\n (۴)…مسجد میں داخل ہوتے وقت پہلے داہنا قدم اندر رکھے اور یہ دعا پڑھے ۔\n ’’ أَللَّھُمَّ افتح لِی أَبْوابَ رَحْمَتِکَ ‘‘ یعنی اے اللّٰہ تو اپنی رحمت کے دروازے میرے لیے کھول دے ۔\n (۵)…مسجد سے نکلتے وقت پہلے بایاں قدم باہر رکھے اور یہ دُعا پڑ ھے ۔\n ’’ أَللَّھُمْ إِنِّی أَسْءَلُکَ مِنْ فَضْلِک ‘‘ یعنی اے اللّٰہ میں تجھ سے تیرے فضل کا سوال کرتا ہوں۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب المساجد ومواضع الصلاۃ ، الفصل الثالث ، ج ۱، ص ۳۶۴.\n[2] ’’بہار شریعت‘‘، ج۱، ص ۶۴۸، ’’ الدر المختار ورد المحتار ‘‘ ، کتاب الصلاۃ ، باب ما یفسد الصلاۃ وما یکرہ فیھا ، مطلب فی الغرس فی المسجد ، ج ۲، ص ۵۲۵.\n[3] ’’ الفتاوی الرضویۃ ‘‘، ج ۸، ص ۱۰۳.\n[4] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، باب ما یفسد الصلاۃ وما یکرہ فیھا ، ج ۲، ص ۵۱۶.\n[5] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب ما یفسد الصلاۃ وما یکرہ فیھا ، مطلب فی أحکام المسجد ، ج ۲، ص ۵۱۷."}, {"id": 7793, "bookId": 14, "volNo": "1", "hadithNo": 25, "chapter": "جمعہ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ سَلْمَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَغْتَسِلُ رَجُلٌ یَوْمَ الْجُمُعَۃِ وَیَتَطَہَّرُ مَا اسْتَطَاعَ مِنْ طُہْرٍ وَیَدَّہِنُ مِنْ دُہْنِہِ أَوْ یَمَسُّ مِنْ طِیبِ بَیْتِہِ ثُمَّ یَخْرُجُ فلَا یُفَرِّقُ بَیْنَ اثْنَیْنِ ثُمَّ یُصَلِّی مَا کُتِبَ لَہُ ثُمَّ یُنْصِتُ إِذَا تَکَلَّمَ الْإِمَامُ إِلَّا غُفِرَ لَہُ مَا بَیْنَہُ وَبَیْنَ الْجُمُعَۃِ الْأُخْرَی‘‘ ۔\nحدیث 2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَانَ یَوْمُ الْجُمُعَۃِ وَقَفَتِ الْمَلَا ءِکَۃُ عَلَی بَابِ الْمَسْجِدِ یَکْتُبُونَ الْأَوَّلَ فَالْأَوَّلَ وَمَثَلُ الْمُہَجِّرِ کَمَثَلِ الَّذِی یُہْدِی بَدَنَۃً ثُمَّ کَالَّذِی یُہْدِی بَقَرَۃً ثُمَّ کَبْشًا ثُمَّ دَجَاجَۃً ثُمَّ بَیْضَۃً فَإِذَا خَرَجَ الْإِمَامُ طَوَوْا صُحُفَہُمْ وَیَسْتَمِعُونَ الذِّکْرَ‘‘۔ (بخاری، مسلم)\nحدیث 3:\n’’ عَنْ سَمُرَۃَ بْنِ جُنْدُبٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ تَرَکَ الْجُمُعَۃَ مِنْ غَیْرِ عُذْرٍ فَلْیَتَصَدَّقْ بِدِینَارٍ فَإِنْ لَمْ یَجِدْ فَبِنِصْفِ دِینَارٍ ‘‘ ۔ (أحمد، ابوداود)\nحدیث 4:\n’’عَنْ سَمُرَۃَ بْنِ جُنْدُبٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ احْضُرُوا الذِّکْرَ وَادْنُوا مِنْ الْإِمَامِ فَإِنَّ الرَّجُلَ لَا یَزَالُ یَتَبَاعَدُ حَتَّی یُؤَخَّرَ فِی الْجَنَّۃِ وَإِنْ دَخَلَہَا‘‘ ۔\nحدیث 5:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا نَعَسَ أَحَدُکُمْ یَوْمَ الْجُمُعَۃِ فَلْیَتَحَوَّلْ مِنْ مَجْلِسِہِ ذَلِکَ‘‘ ۔\nحدیث 6:\n’’ عَنْ أَنَسٍ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا اشْتَدَّ الْبَرْدُ بَکَّرَ بِالصَّلَاۃِ وَإِذَا اشْتَدَّ الْحَرُّ أَبْرَدَ بِالصَّلَاۃِ یَعْنِی الْجُمُعَۃَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت سلمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جو شخص جمعہ کے دن نہائے اور جس قدر ممکن ہوسکے طہارت نظافت کرے اور تیل لگائے یا خوشبو ملے جو گھر میں میسر آئے ۔ پھر گھر سے نماز کے لیے نکلے اور دو آدمیوں کے درمیان ( اپنے بیٹھنے یا آگے گزرنے کے لیے ) شگاف نہ ڈالے ۔ پھر نماز پڑھے جو مقرر کردی گئی ہے ۔ پھر جب امام خطبہ پڑھے تو خاموش بیٹھا رہے تو اس کے وہ تمام گناہ جو ایک جمعہ سے دوسرے جمعہ تک اس نے کیے ہیں معاف کردیئے جائیں گے ۔ (بخاری)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جمعہ کے دن فرشتے مسجد کے دروازے پر کھڑے ہو کر مسجد میں آنے والوں کی حاضری لکھتے ہیں جو لوگ پہلے آتے ہیں ان کو پہلے اور جو بعد میں آتے ہیں ان کو بعد میں اور جو شخص جمعہ کی نماز کو پہلے گیا اس کی مثال اس شخص کی طر ح ہے جس نے مکہ شریف میں قربانی کے لیے اُونٹ بھیجا۔ پھر جو دوسرے نمبر پر آیا اس کی مثال اس شخص کی سی ہے جس نے گائے بھیجی پھر جو اس کے بعد آئے وہ اس شخص کے مانند ہے جس نے دُنبہ بھیجا پھر جو اس کے بعد آئے وہ اس شخص کے مانند ہے جس نے مرغی بھیجی اور جو اسکے بعد آئے وہ اس شخص کے مانند ہے جس نے انڈا۔ پھر جب امام خطبہ کے لیے اُٹھتا ہے تو فرشتے اپنے کاغذات لپیٹ لیتے ہیں۔ ا ور خطبہ سننے میں مشغول ہوجاتے ہیں۔ \n¥ترجمہ حدیث 3:\nحضرت سمرہ بن جندب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس شخص نے بغیر کسی عذر شرعی کے جمعہ کی نماز چھوڑ دی تو اسے چاہیے کہ ایک دینار (ا شرفی) صدقہ کرے اگر اتنا ممکن نہ ہو تو آدھا دینار۔ \n¥ترجمہ حدیث 4:\nحضرت سمرہ بن جندب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ حاضر رہو خطبہ کے وقت اور امام سے قریب رہو اس لیے کہ آدمی جس قدر دور رہے گااسی قدر جنت میں پیچھے رہے گا۔ اگرچہ وہ جنت میں داخل ضرور ہوگا۔ (ابوداود) \n¥ترجمہ حدیث 5:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایاکہ جس شخص کو مسجد میں جمعہ کے دن اونگھ آئے تو اس کو چاہیے کہ وہ اپنی جگہ تبدیل کردے ۔ (ترمذی)\n¥ترجمہ حدیث 6:\n حضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سخت سردی کے موسم میں جمعہ کی نماز سویرے پڑھتے اور سخت گرمی کے دنوں میں دیر سے پڑھتے ۔ (بخاری شریف)", "roman": "Tarjuma Hadees 1: Hazrat Salman Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs Jumu'ah ke din nahaye aur jis qadar mumkin ho sake Taharat nazafat kare aur tel lagaye ya khushboo male jo ghar mein mayassar aaye. Phir ghar se Namaz ke liye nikle aur do aadmiyon ke darmiyan (apne baithne ya aage guzarne ke liye) shagaaf na dale. Phir Namaz padhe jo muqarrar kardi gayi hai. Phir jab Imam Khutbah padhe to khamosh baitha rahe to us ke woh tamam gunah jo ek Jumu'ah se dusre Jumu'ah tak us ne kiye hain maaf kardiye jayenge. (Bukhari) Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Jumu'ah ke din farishtay Masjid ke darwaze par khade ho kar Masjid mein aane walon ki haziri likhte hain jo log pehle aate hain un ko pehle aur jo baad mein aate hain un ko baad mein aur jo shakhs Jumu'ah ki Namaz ko pehle gaya us ki misaal us shakhs ki tarah hai jis ne Makkah Shareef mein Qurbani ke liye oont bheja. Phir jo dusre number par aaya us ki misaal us shakhs ki si hai jis ne gaye bheji phir jo us ke baad aaye woh us shakhs ke manind hai jis ne dumba bheja phir jo us ke baad aaye woh us shakhs ke manind hai jis ne murghi bheji aur jo us ke baad aaye woh us shakhs ke manind hai jis ne anda. Phir jab Imam Khutbah ke liye uthta hai to farishtay apne kaghazat lapet lete hain aur Khutbah sunne mein mashghool ho jate hain. Tarjuma Hadees 3: Hazrat Samurah Bin Jundab Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jis shakhs ne baghair kisi uzr-e-shar'i ke Jumu'ah ki Namaz chhod di to use chahiye ke ek dinar (ashrafi) Sadaqah kare agar itna mumkin na ho to aadha dinar. Tarjuma Hadees 4: Hazrat Samurah Bin Jundab Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke hazir raho Khutbah ke waqt aur Imam se qareeb raho is liye ke aadmi jis qadar door rahega usi qadar Jannat mein peeche rahega. Agarcha woh Jannat mein dakhil zaroor hoga. (Abu Dawood) Tarjuma Hadees 5: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jis shakhs ko Masjid mein Jumu'ah ke din oongh aaye to us ko chahiye ke woh apni jagah tabdeel kar de. (Tirmidhi) Tarjuma Hadees 6: Hazrat Anas Radiyallahu Anhu ne farmaya ke Huzoor Sallallahu Alaihi Wasallam sakht sardi ke mausam mein Jumu'ah ki Namaz sawere padhte aur sakht garmi ke dinon mein der se padhte. (Bukhari Shareef)", "explanation": "¥انتباہ:\n(۱)…خطیب کے سامنے جو اذان ہوتی ہے مقتدیوں کو اس کا جواب ہر گز نہ دینا چاہیے یہی احوط ہے ۔ ([1]) (فتاوی رضویہ)\n اور درمختار مع ردالمختا ر جلد اول ص:۳۸۰میں ہے : ’’ یَنْبَغِی أَنْ لَا یُجِیبَ بِلِسَانِہِ اتِّفَاقًا فِی الْأَذَانِ بَیْنَ یَدَيْ الْخَطِیبِ ‘‘۔ ([2])\n اور ردالمحتار جلد اول ص:۵۷۵میں ہے : ’’ إِجَابَۃُ الْأَذَانِ حِینَءِذٍ مَکْرُوہَۃٌ ‘‘۔ ([3])\n (۲)…خطبہ میں حضورِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کا نام پاک سن کر انگوٹھا نہ چومے یہ حکم صرف خطبہ کے لیے ہے ورنہ عام حالات میں نام نامی سن کر انگوٹھا چومنا مستحب ہے اور درود شریف دل میں پڑھے … زبان کو جنبش نہ دے اس لیے کہ زبان سے سکوت فرض ہے ۔ ([4]) (فتاوی رضویہ)\n اور درمختار مع ردالمحتار جلد اول ص:۵۷۵ میں ہے : ’’ الصَّوَابُ أَنَّہُ یُصَلِّی عَلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عِنْدَ سَمَاعِ اسْمِہِ فِی نَفْسِہِ ‘‘۔ ([5])\n (۳)…غیر عربی میں خطبہ پڑھنا یا عربی کے ساتھ دوسری زبان کو بھی شامل کرلینا مکروہ اور سنت متوارثہ کے خلاف ہے ۔ ([6]) (فتاوی رضویہ، بہار شریعت)\n (۴)…دیہات میں جمعہ جائز نہیں( عامہ کتب) لیکن عوام اگر پڑھتے ہوں تو انہیں منع نہ کیا جائے ۔ ([7]) (فتاوی رضویہ، حصہ سوم)\n (۵)…چونکہ دیہات میں جمعہ جائز نہیں اس لیے دیہات میں جمعہ کی نماز پڑھنے سے اس دن کی نماز ظہر ساقط نہیں ہوتی لہذا دیہات میں جمعہ پڑھنے کے بعد چار رکعت ظہر فرض پڑھنا ضروری ہے ۔ (کتب عامہ)\n------------------\n[1] ’’ الفتاوی الرضویۃ ‘‘، ج ۵، ص ۳۶۸.\n[2] ’’ الدر المختار ورد المختا ر ‘‘، کتاب الصلاۃ ، باب الأذان ، ج ۲، ص ۸۷.\n[3] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الجمعۃ ، مطلب فی حکم المرقی بین یدی الخطیب ، ج ۳، ص ۴۱.\n[4] ’’ الفتاوی الرضویۃ ‘‘، ج ۸، ص ۴۶۸.\n[5] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصلاۃ ، باب الجمعۃ ، مطلب فی شروط إلخ ، ج ۳، ص ۴۰.\n[6] ’’ الفتاوی الرضویۃ ‘‘، ج ۸، ص ۳۸۹، ’’بہارِ شریعت‘‘، ج۱، ص۷۶۹.\n[7] ’’ الفتاوی الرضویۃ ‘‘، ج ۸، ص ۳۸۷."}, {"id": 7794, "bookId": 14, "volNo": "1", "hadithNo": 26, "chapter": "خطبہ کی اذان کہاں دی جائے", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "’’ عَنِ السَّاءِبِ بْنِ یَزِیدَ قَالَ کَانَ یُؤَذَّنُ بَیْنَ یَدَيْ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا جَلَسَ عَلَی الْمِنْبَرِ یَوْمَ الْجُمُعَۃِ عَلَی بَابِ الْمَسْجِدِ وَأَبِی بَکْرٍ وَعُمَرَ ‘‘ ۔", "urdu": "حضرت سائب بن یزید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے انہوں نے فرمایا کہ جب حضور علیہ الصلاۃ والسلام جمعہ کے دن منبر پر تشریف رکھتے تو حضور کے سامنے مسجد کے دروازہ پر اذان ہوتی۔ اور ایسا ہی حضرت ابوبکر و عمر ر ضی اللّٰہ تعالیٰ عنہم ا کے زمانہ میں بھی رائج تھا۔ (ابوداود، جلد اول ص ۱۶۲)", "roman": "Hazrat Sa'ib Bin Yazeed Radiyallahu Anhu se marwi hai unhon ne farmaya ke jab Huzoor Sallallahu Alaihi Wasallam Jumu'ah ke din Mimbar par tashreef rakhte to Huzoor ke samne Masjid ke darwaza par Azan hoti. Aur aisa hi Hazrat Abu Bakr o Umar Radiyallahu Anhum ke zamana mein bhi ra'ij tha. (Abu Dawood, Jild Awwal, Safa 162)", "explanation": "اس حدیث شریف سے معلوم ہوا کہ خطبہ کی اذان مسجد کے دروازہ پر پڑھنا سنت ہے ۔ حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم اور حضرات ابوبکر و عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا کے زمانہ مبارکہ میں خطبہ کی اذان مسجد کے دروازہ ہی پر ہوا کرتی تھی۔ ا سی لیے فقہائے کرام مسجد کے اندر اذان دینے کو منع فرماتے ہیں۔ جیسا کہ فتاویٰ قاضی خاں جلد اول مصری ص۷۸، اور فتاویٰ عالمگیری جلد اول مصری ص:۵۵، اور بحرالرائق جلد اول ص:۲۶۸میں ہے :’’ لَایُوذَّنُ فِی الْمَسْجِدِ ‘‘یعنی مسجد کے اندر اذان دینا منع ہے ۔ ([1])اور فتح القدیر جلد اول ص:۲۱۵ میں ہے :’’ قَالُوْا لَا یُؤذَّنُ فِی المسجدِ ‘‘ یعنی فقہائے کرام نے فرمایا کہ مسجد میں اذان نہ دی جائے ۔ ([2]) اور طحطاوی علی مراقی الفلاح ص:۱۷ میں ہے : ’’ یَکْرہُ أَن یُؤَذَّنَ فِی المسجِدِ کَمَا فِی القُھسْتَانِی عَن النظمِ ‘‘ یعنی مسجد میں اذان دینا مکروہ ہے اسی طرح قہستانی میں نظم سے ہے ۔ ([3]) لہذا یہ جو رواج ہوگیا ہے کہ اذان مسجد کے اندر دی جاتی ہے غلط ہے ۔ مسلمانوں کو چاہیے کہ اس غلط رواج کو ترک کرکے حدیث و فقہ پر عمل کریں۔\n------------------\n[1] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الثانی فی کلمات الأذان إلخ ، ج ۱، ص ۵۵، ’’ البحر الرائق ‘‘، کتا ب الصلاۃ ، باب الأذان ، ج ۱، ص ۴۴۴، فتاوی قاضیخاں ، باب الأذان ، ج ۱، ص ۳۸.\n[2] ’’ فتح القدیر ‘‘، کتاب الصلاۃ ، باب الأذان ، ج ۱، ص ۲۵۰.\n[3] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، کتاب الصلاۃ ، باب الأذان ، ص ۱۹۷."}, {"id": 7795, "bookId": 14, "volNo": "1", "hadithNo": 27, "chapter": "عید اور بقرہ عید کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\nعَنْ أَنَسٍ قَالَ قَدِمَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْمَدِینَۃَ وَلَہُمْ یَوْمَانِ یَلْعَبُونَ فِیہِمَا فَقَالَ مَا ہَذَانِ الْیَوْمَانِ قَالُوا کُنَّا نَلْعَبُ فِیہِمَا فِی الْجَاہِلِیَّۃِ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَدْ أَبْدَلَکُمُ اللّٰہ بِہِمَا خَیْرًا مِنْہُمَا یَوْمَ الْأَضْحَی وَیَوْمَ الْفِطْرِ‘‘ ۔\nحدیث 2:\n’’ عَنْ أَبِی الْحَوَیْرَثِ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَتَبَ إِلَی عَمْرِو بْنِ حَزْمٍ وَہُوَ بِنَجْرَانِ عَجِّلِ الْاَضْحَی وَأَخِّرِ الْفِطْر وَذَکِّرِ النَّاسَ ‘‘۔ \nحدیث 3:\n’’عَنْ جَابِرِ بْنِ سَمُرَۃَ قَالَ صَلَّیْتُ مَعَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْعِیدَیْنِ غَیْرَ مَرَّۃٍ وَلَا مَرَّتَیْنِ بِغَیْرِ أَذَانٍ وَلَا إِقَامَۃٍ ‘‘ ۔ \nحدیث 4:\n’’ عَنْ أَنَسٍ قَالَ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَغْدُو یَوْمَ الْفِطْرِ حَتَّی یَأْکُلَ تَمَرَاتٍ وَیَأْکُلُہُنَّ وِتْرًا‘‘۔ \nحدیث 5:\n’’ عَنْ بُرَیْدَۃَ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَخْرُجُ یَوْمَ الْفِطْرِ حَتَّی یَطْعَمَ وَلَا یَطْعَمُ یَوْمَ الْأَضْحَی حَتَّی یُصَلِّیَ‘‘ ۔\nحدیث 6:\n’’ عَنْ جَابِرٍ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَانَ یَوْمُ عِیدٍ خَالَفَ الطَّرِیقَ‘‘ ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم جب ہجرت فرما کر مدینہ منورہ تشریف لائے تو حضور کو معلوم ہوا کہ یہاں کے لوگ سال میں دو دن کھیل کود کرتے ہیں، خوشی مناتے ہیں اس پر حضور نے لوگوں سے پوچھا کہ یہ دو دن کیسے ہیں؟ لوگوں نے عرض کیا ان دنوں میں ہم لوگ زمانہ جاہلیت کے اندر خوشیاں مناتے اور کھیل کود کرتے تھے حضور علیہ الصلاۃ والسلام نے فرمایا کہ اللّٰہ تعالیٰ نے تمہارے لیے ان دو دنوں کو ان سے بہتر دنوں میں تبدیل کردیا ہے ان میں سے ایک دن عید الفطر اور دوسرا دن عیدالاضحٰی ہے ۔ (ابوداود، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت ابوالحویرث رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے عمرو بن حزم کو جب کہ وہ نجران میں تھے لکھا کہ بقر عید کی نماز جلد پڑھو اور عید الفطر کی نماز دیر سے پڑھو۔ اور لوگوں کو وعظ سناؤ۔ (مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت جابر بن سمرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کے ساتھ عیدین کی نماز بغیر اذان و اقامت کے پڑھی ہے ۔ ایک بار نہیں بلکہ کئی بار۔ (مسلم)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ عیدا لفطر کے دن جب تک حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم چند کھجوریں نہ کھا لیتے عیدگاہ کو تشریف نہ لے جاتے اور آپ طاق کھجوریں تناول فرماتے ۔ (بخاری)\n¥ترجمہ حدیث 5:\nحضرت بریدہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ عیدالفطر کے دن جب تک حضور علیہ الصلاۃ والسلام کچھ کھا نہ لیتے عیدگاہ کو تشریف نہ لے جاتے اور عید الاضحی کے دن اس وقت تک کچھ نہ کھاتے جب تک کہ نماز نہ پڑھ لیتے ۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 6:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم عید کے دن دو مختلف راستوں سے آتے جاتے تھے ۔ (بخاری)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne farmaya ke Nabi-e-Kareem Sallallahu Alaihi Wasallam jab hijrat farma kar Madinah Munawwarah tashreef laye to Huzoor ko maloom hua ke yahan ke log saal mein do din khel kood karte hain, khushi manate hain is par Huzoor ne logon se poocha ke ye do din kaise hain? Logon ne arz kiya in dinon mein hum log zamana-e-jahiliyat ke andar khushiyan manate aur khel kood karte the. Huzoor Sallallahu Alaihi Wasallam ne farmaya ke Allah Ta'ala ne tumhare liye in do dinon ko un se behtar dinon mein tabdeel kar diya hai in mein se ek din Eid-ul-Fitr aur dusra din Eid-ul-Adha hai. (Abu Dawood, Mishkat) Tarjuma Hadees 2: Hazrat Abul Huwairith Radiyallahu Anhu se Riwayat hai ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne Amr Bin Hazm ko jab ke woh Najran mein the likha ke Baqar Eid ki Namaz jald padho aur Eid-ul-Fitr ki Namaz der se padho. Aur logon ko wa'z sunao. (Mishkat) Tarjuma Hadees 3: Hazrat Jabir Bin Samurah Radiyallahu Anhu ne farmaya ke main ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ke sath Eidain ki Namaz baghair Azan o Iqamat ke padhi hai. Ek baar nahi balkay kayi baar. (Muslim) Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu ne farmaya ke Eid-ul-Fitr ke din jab tak Huzoor Sallallahu Alaihi Wasallam chand khajooren na kha lete Eidgah ko tashreef na le jate aur Aap taaq khajooren tanawul farmate. (Bukhari) Tarjuma Hadees 5: Hazrat Buraidah Radiyallahu Anhu ne farmaya ke Eid-ul-Fitr ke din jab tak Huzoor Sallallahu Alaihi Wasallam kuch kha na lete Eidgah ko tashreef na le jate aur Eid-ul-Adha ke din us waqt tak kuch na khate jab tak ke Namaz na padh lete. (Tirmidhi, Ibn Majah) Tarjuma Hadees 6: Hazrat Jabir Radiyallahu Anhu ne farmaya ke Huzoor Sallallahu Alaihi Wasallam Eid ke din do mukhtalif raston se aate jate the. (Bukhari)", "explanation": "¥انتباہ:\n (۱)…عیدین کی نماز کے بعد مصافحہ و معانقہ کرنا جیسا کہ عموما ً مسلمانوں میں رائج ہے بہتر ہے اس لیے کہ اس میں اظہارِ مسرت ہے ۔ ([1])(بہار شریعت)\n (۲)…عورتوں کے لیے عیدین کی نماز جائز نہیں اس لیے کہ عیدگاہ میں مردوں کے ساتھ اختلاط ہوگا اور اسی لیے اب عورتوں کو کسی نماز میں جماعت کی حاضری جائز نہیں دن کی نماز ہو یا رات کی ، جمعہ ہو یا عیدین ، خواہ وہ جوان ہوں یا بڑھیا جیسا کہ تنویر الابصار و درمختار میں ہے : ’’ یُکْرَہُ حُضُورُہُنَّ الْجَمَاعَۃَ وَلَوْ لِجُمُعَۃٍ وَعِیدٍ وَوَعْظٍ مُطْلَقًا وَلَوْ عَجُوزًا لَیْلًا عَلَی الْمَذْہَبِ الْمُفْتَی بِہِ لِفَسَادِ الزَّمَانِ ‘‘۔ ([2])\n اور اگر صرف عورتیں جماعت کریں تو یہ بھی ناجائز ہے ۔ اس لیے کہ صرف عورتوں کی جماعت ناجائز و مکروہ تحریمی ہے ۔ جیسا کہ فتاویٰ عالمگیری جلد اول مصری ص:۸۰ میں ہے : ’’ یُکْرَہُ إمَامَۃُ الْمَرْأَۃِ لِلنِّسَاءِ فِی الصَّلَوَاتِ کُلِّہَا مِنَ الْفَرَاءِضِ وَالنَّوَافِلِ إلَّا فِی صَلَاۃِ الْجَنَازَۃِ ہَکَذَا فِی النِّہَایَۃِ ‘‘۔ ([3])\n اور جیسا کہ درمختار میں ہے : ’’ وَیُکْرَہُ تَحْرِیمًا جَمَاعَۃُ النِّسَاء وَلَوْ فِی التَّرَاوِیح فِی غَیْرِ صَلاۃِ جِنَازَۃٍ ‘‘۔ ([4])\n اور اگر فرداً فرداً پڑھیں تو بھی نماز جائز نہ ہوگی اس لیے کہ عیدین کی نماز کے لیے جماعت شرط ہے ۔ ’’ وَاِذَا فَاتَ الشَّرْطُ فَاتَ الْمَشْرُوْطُ ‘‘۔ ہاں عورتیں اس دن اپنے اپنے گھروں میں فرداً فرداً نفل نمازیں پڑھیں تو باعثِ ثواب و برکت اور سبب ازدیادِ نعمت ہے ۔\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۷۸۴.\n[2] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، ج ۲، ص ۳۶۷.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الخامس ، الفصل الثالث فی بیان من یصلح إماما لغیرہ ، ج ۱، ص ۸۵.\n[4] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، ج ۲، ص ۳۶۵."}, {"id": 7796, "bookId": 14, "volNo": "1", "hadithNo": 28, "chapter": "بیماری کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی سَعِیدٍ الْخُدْرِیِّ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَا یُصِیبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا ہَمٍّ وَلَا حُزْنٍ وَلَا أَذًی وَلَا غَمٍّ حَتَّی الشَّوْکَۃِ یُشَاکُہَا إِلَّا کَفَّرَ اللّٰہ بِہَا مِنْ خَطَایَاہُ‘‘۔ (بخاری، مسلم)\nحدیث 2:\n’’ عَنْ عَبْدِ اللّٰہِ ابْنِ مَسْعُودٍ رَضِیَ اللّٰہ عَنْہُ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا مِنْ مُسْلِمٍ یُصِیبُہُ أَذًی مِنْ مَرَضٍ فَمَا سِوَاہُ إِلَّا حَطَّ اللّٰہ بِہِ سَیِّءَاتَہٗ کَمَا تَحُطُّ الشَّجَرَۃُ وَرَقَہَا‘‘۔ (بخاری، مسلم)\nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ ذُکِرَتِ الْحُمَّی عِنْدَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَسَبَّہَا رَجُلٌ فَقَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تَسُبَّہَا فَإِنَّہَا تَنْفِی الذُّنُوبَ کَمَا تَنْفِی النَّارُ خَبَثَ الْحَدِیدِ‘‘۔\nحدیث 4:\n’’ عَنْ مُحَمَّدِ بْنِ خَالِدِنِ السلَمِیّ عَنْ أَبِیہِ عَنْ جَدِّہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الْعَبْدَ إِذَا سَبَقَتْ لَہُ مِنَ اللّٰہ مَنْزِلَۃٌ لَمْ یَبْلُغْہَا بِعَمَلِہِ ابْتَلاہُ اللّٰہ فِی جَسَدِہِ أَوْ فِی مَالِہِ أَوْ فِی وَلَدِہِ ثُمَّ صَبَّرَہُ عَلَی ذَلِکَ حَتَّی یُبْلِغَہُ الْمَنْزِلَۃَ الَّتِی سَبَقَتْ لَہُ مِنَ اللّٰہ‘‘۔\nحدیث 5:\n’’ عَنْ عَائشَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَثُرَتْ ذُنُوبُ الْعَبْدِ وَلَمْ یَکُنْ لَہُ مَا یُکَفِّرُہَا مِنَ الْعَمَلِ ابْتَلاہُ اللّٰہ بِالْحُزْنِ لِیُکَفِّرَہَا عَنْہُ ‘‘۔ \nحدیث 6:\n’’عَنْ سَعْدٍ قَالَ سُءِلَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَيُّ النَّاسِ أَشَدُّ بَلاءً قَالَ الْأَنْبِیَاءُ ثُمَّ الْأَمْثَلُ فَالْأَمْثَلُ یُبْتَلَی الْعَبْدُ عَلَی حَسَبِ دِینِہِ فَإِنْ کَانَ فِی دِینِہِ صُلْبًا اشْتَدَّ بَلَاؤُہُ وَإِنْ کَانَ فِی دِینِہِ رِقَّۃ ہُوِّنَ عَلَیْہِ فَمَا زَالَ کَذَلِکَ حَتَّی یَمْشِی عَلَی الْأَرْضِ مَا لَہُ ذَنْبٌ‘‘۔\nحدیث 7:\n’’ عَنْ جَابِرِ بْنِ عَتِیکٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الشَّہَادَۃُ سَبْعٌ سِوَی الْقَتْلِ فِی سَبِیلِ اللّٰہ الْمَطْعُونُ شَہِیدٌ وَالْغَرِیْقُ شَہِیدٌ وَصَاحِبُ ذَاتِ الْجَنْبِ شَہِیدٌ وَالْمَبْطُونُ شَہِیدٌ وَصَاحِبُ الْحَرِیقِ شَہِیدٌ وَالَّذِی یَمُوتُ تَحْتَ الْہَدْمِ شَہِیدٌ وَالْمَرْأَۃُ تَمُوتُ بِجُمْعٍ شَہِیدٌ‘‘۔", "urdu": "¥ترجمہ حدیث1:\nحضرت ابو سعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ مسلمان کو کوئی رنج، کوئی دکھ، کوئی فکر، کوئی تکلیف، کوئی اذیت اور کوئی غم نہیں پہنچتا یہاں تک کہ کانٹا جو اسے چبھے مگر اللّٰہ تعالیٰ ان کے سبب اس کے گناہوں کو مٹا دیتا ہے ۔ \n¥ترجمہ حدیث2:\nحضرت عبد اللّٰہ بن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ نہیں پہنچتی مسلمان کو کوئی اذیت مرض یا اس کے سوا کچھ اور لیکن اللّٰہ تعالیٰ اس کے سبب اس کے (صغیرہ) گناہوں کوساقط کردیتا ہے ، جیسے درخت سے پتے جھڑتے ہیں۔ \n¥ترجمہ حدیث3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کے حضور میں بخارکا ذکر کیا گیاتو ایک شخص نے بخار کو بُرا کہا۔ حضور نے فرمایا بخار کو بُرا نہ کہو اس لیے کہ وہ ( مومن کو) گناہوں سے اس طرح پاک کردیتا ہے جیسے آگ لوہے کی میل کو صاف کردیتی ہے ۔ (ابن ماجہ ، مشکوۃ)\n¥ترجمہ حدیث4:\nحضرت محمد بن خالد سلمی اپنے باپ سے روایت کرتے ہیں کہ ان کے دادا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ بندہ کے لیے علمِ الہٰی میں جب کوئی مرتبہ کمال مقدر ہوتا ہے اور وہ اپنے عمل سے اس مرتبے کو نہیں پہنچا تو خدائے تعالیٰ اس کے جسم یا مال یا اولاد پر مصیبت ڈالتا ہے پھر اس پر صبر عطا فرماتا ہے یہاں تک کہ اسے اس مرتبہ تک پہنچا دیتا ہے جو اس کے لیے علمِ الہٰی میں مقدر ہوچکا ہے ۔ (احمد، ابوداود)\n¥ترجمہ حدیث5:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جب بندہ کے گناہ زیادہ ہوجاتے ہیں اور اس کے عمل میں کوئی ایسی چیز نہیں ہوتی جو گناہوں کا کفارہ بن سکے تو اللّٰہ تعالیٰ اس کو غم اور پریشانی میں مبتلا کردیتا ہے تاکہ اس کے گناہوں کا کفارہ بن جائے ۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث6:\nحضرت سعد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم سے دریافت کیا گیا کہ کون لوگ سخت بلاؤں میں مبتلا ہوتے ہیں؟ حضور نے فرمایا ( سب سے پہلے )انبیاء کرام پھر ان کے بعد جو افضل ہیں پھران کے بعد جو افضل ہیں یعنی حسب مر اتب آدمی میں دین کے ساتھ جیسا تعلق ہوتا ہے اسی اعتبار سے بلا میں مبتلا کیا جاتا ہے اگر دین میں سخت ہے تو بلا بھی اس پر سخت ہوگی۔ اور اگر دین میں کمزور ہے تو اس پر آسانی کی جاتی ہے ۔ یہی سلسلہ ہمیشہ رہتا ہے ۔ یہاں تک کہ زمین پر وہ یوں چلتا ہے کہ اس پر کوئی گناہ نہیں رہتا۔ (ترمذی، ابن ماجہ، دارمی)\n¥ترجمہ حدیث7:\nحضرت جابر بن عتیک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ خدائے تعالیٰ کی را ہ میں قتل کے علاوہ سات شہادتیںا ورہیں۔ جو طاعون میں مرے شہید ہے ۔ جو ڈوب کر مرے شہید ہے ۔ جو ذات الجنب(نمونیہ)میں مرے شہید ہے ۔ جو پیٹ کی بیماری میں مرے شہید ہے ۔ جو آگ میں جل جائے شہیدہے ۔ جو عمارت کے نیچے دب کر مرجائے شہیدہے ۔ اور جو عورت بچہ کی پیدائش کے وقت مرجائے شہید ہے ۔ (مالک، ابوداود، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Saeed Khudri Radiyallahu Anhu se Riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Musalman ko koi ranj, koi dukh, koi fikr, koi takleef, koi aziyat aur koi gham nahi pahunchta yahan tak ke kanta jo use chubhe magar Allah Ta'ala un ke sabab us ke gunahon ko mita deta hai. Tarjuma Hadees 2: Hazrat Abdullah Bin Mas'ood Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke nahi pahunchti Musalman ko koi aziyat, marz ya us ke siwa kuch aur lekin Allah Ta'ala us ke sabab us ke (sagheera) gunahon ko saaqit kar deta hai, jaise darakht se patte jhadte hain. Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ke huzoor mein bukhar ka zikr kiya gaya to ek shakhs ne bukhar ko bura kaha. Huzoor ne farmaya bukhar ko bura na kaho is liye ke woh (Momin ko) gunahon se is tarah Paak kar deta hai jaise aag lohay ki mail ko saaf kar deti hai. (Ibn Majah, Mishkat) Tarjuma Hadees 4: Hazrat Muhammad Bin Khalid Sulami apne baap se Riwayat karte hain ke un ke dada ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke bandah ke liye Ilm-e-Ilahi mein jab koi martaba-e-kamaal muqaddar hota hai aur woh apne amal se us martabe ko nahi pahunchta to Khudaye Ta'ala us ke jism ya Maal ya Aulaad par museebat dalta hai phir us par sabr ata farmata hai yahan tak ke use us martaba tak pahuncha deta hai jo us ke liye Ilm-e-Ilahi mein muqaddar ho chuka hai. (Ahmad, Abu Dawood) Tarjuma Hadees 5: Hazrat Aishah Radiyallahu Anha ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab bandah ke gunah zyada ho jate hain aur us ke amal mein koi aisi cheez nahi hoti jo gunahon ka Kaffarah ban sake to Allah Ta'ala us ko gham aur pareshani mein mubtala kar deta hai taake us ke gunahon ka Kaffarah ban jaye. (Ahmad, Mishkat) Tarjuma Hadees 6: Hazrat Sa'ad Radiyallahu Anhu ne farmaya ke Nabi-e-Kareem Sallallahu Alaihi Wasallam se daryaft kiya gaya ke kaun log sakht balaon mein mubtala hote hain? Huzoor ne farmaya (sab se pehle) Ambiya-e-Kiram phir un ke baad jo afzal hain phir un ke baad jo afzal hain yani hasb-e-maratib aadmi mein deen ke sath jaisa ta'alluq hota hai usi aitbaar se bala mein mubtala kiya jata hai agar deen mein sakht hai to bala bhi us par sakht hogi. Aur agar deen mein kamzor hai to us par aasani ki jati hai. Yehi silsila hamesha rehta hai. Yahan tak ke Zameen par woh yun chalta hai ke us par koi gunah nahi rehta. (Tirmidhi, Ibn Majah, Darimi) Tarjuma Hadees 7: Hazrat Jabir Bin Ateek Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Khudaye Ta'ala ki raah mein qatl ke ilawa saat Shahadatain aur hain. Jo ta'oon mein mare Shaheed hai. Jo doob kar mare Shaheed hai. Jo Zaat-ul-Janb (pneumonia) mein mare Shaheed hai. Jo pet ki bimari mein mare Shaheed hai. Jo aag mein jal jaye Shaheed hai. Jo imarat ke neeche dab kar mar jaye Shaheed hai. Aur jo Aurat Bachah ki paidaish ke waqt mar jaye Shaheed hai. (Malik, Abu Dawood, Mishkat)", "explanation": "¥الحاصل :\n بیماری سے بظاہر تکلیف پہنچتی ہے لیکن حقیقت میں وہ بہت بڑی نعمت ہے جس سے مومن کو ابدی راحت و آرام کا بہت بڑا ذخیرہ ہاتھ آتا ہے اس لیے کہ یہ ظاہری بیماری حقیقت میں رُوحانی بیماریوںکا ایک بڑا زبردست علاج ہے ۔ بشرطیکہ آدمی مومن ہو اور سخت سے سخت بیماری میں صبر و شکر سے کام لے اگر صبر نہ کرے بلکہ جزع فزع کرے تو بیماری سے کوئی معنوی فائدہ نہ پہنچے گا یعنی ثواب سے محروم رہے گا۔ بعض نادان بیماری میں نہایت بے جا کلمات بول اٹھتے ہیں اور بعض خدائے تعالیٰ کی جانب ظلم کی نسبت کرکے کفر تک پہنچ جاتے ہیں۔ یہ ان کی انتہائی شقاوت اوردنیا و آخرت کی ہلاکت کا سبب ہے ۔ العیاذ باللّٰہ تعالیٰ ۔"}, {"id": 7797, "bookId": 14, "volNo": "1", "hadithNo": 29, "chapter": "بیمار کی مزاج پُرسی کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’ عَنْ عَلِیٍّ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَا مِنْ مُسْلِمٍ یَعُودُ غُدْوَۃً إِلَّا صَلَّی عَلَیْہِ سَبْعُونَ أَلْفَ مَلَکٍ حَتَّی یُمْسِیَ وَإِنْ عَادَہُ عَشِیَّۃً إِلَّا صَلَّی عَلَیْہِ سَبْعُونَ أَلْفَ مَلَکٍ حَتَّی یُصْبِحَ وَکَانَ لَہُ خَرِیفٌ فِی الْجَنَّۃِ‘‘۔\nحدیث2:\nعَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ وأَعَادَ أَخَاہُ الْمُسْلِمَ مُحْتَسِبًا بُوعِدَ مِنْ جَہَنَّمَ مَسِیرَۃَ سِتِّیْنَ خَرِیفًا ‘‘۔ \nحدیث3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ عَادَ مَرِیضًا نَادَی مُنَادٍ مِنَ السَّمَاءِ طِبْتَ وَطَابَ مَمْشَاکَ وَتَبَوَّأْتَ مِنْ الْجَنَّۃِ مَنْزِلًا‘‘۔ \nحدیث4:\n’’ عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ عَادَ مَرِیضًا لَمْ یَزَلْ یَخُوضُ الرَّحْمَۃَ حَتَّی یَجْلِسَ فَإِذَا جَلَسَ اغْتَمَسَ فِیہَا ‘‘۔ \nحدیث5:\n’’ عَنْ أَبِی سَعِیدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا دَخَلْتُمْ عَلَی الْمَرِیضِ فَنَفِّسُوا لَہُ فِی أَجَلِہِ فَإِنَّ ذَلِکَ لَا یَرُدُّ شَیْءًا وَیُطَیِّبُ بِنَفْسِہِ ‘‘۔\nحدیث6:\n’’ عَنْ سَعِیدِ بْنِ الْمُسَیَّبِ مُرْ سَلاً قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَفْضَلُ الْعِیَادَۃِ سُرْعَۃُ الْقِیَامِ ‘‘۔ \nحدیث7:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا مِنْ مُسْلِمٍ یَعُودُ مُسْلِمًا فَیَقُولُ سَبْعَ مَرَّاتٍ أَسْأَلُ اللّٰہ الْعَظِیمَ رَبَّ الْعَرْشِ الْعَظِیمِ أَنْ یَشْفِیَکَ إِلَّا شُفِیَ إِلَّا أَنْ یَکُوْنَ قَدْ حَضَرَ أَجَلُہُ‘‘۔", "urdu": "¥ترجمہ حدیث1:\nحضرت علی کرم اللّٰہ تعالیٰ وجہہ نے فرمایا کہ میں نے نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کو فرماتے ہوئے سنا کہ جب کوئی مسلمان اپنے مسلمان بھائی کی صبح کے وقت عیادت کرتا ہے تو شام تک ستر ہزار فرشتے اس کے لیے رحمت و مغفرت کی دُعا کرتے ہیں اور جو شام کے وقت عیادت کرتا ہے اس کے لیے ستر ہزار فرشتے صبح تک دعائے مغفرت کرتے ہیں اور اس کے لیے جنت میں ایک باغ ہے ۔ (ترمذی، ابوداود)\n¥ترجمہ حدیث2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جس نے اچھا وضو کیا اورمحض ثواب حاصل کرنے کی غرض سے اپنے مسلمان بھائی کی عیادت کی تو اس کو ساٹھ برس کی مسافت کے فاصلے پر دوزخ سے دور کردیا جاتا ہے ۔ (احمد)\n¥ترجمہ حدیث3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص بیمار کی عیادت کو جاتا ہے تو آسمان سے ایک منادی ندا کرتا ہے کہ تو اچھا ہے اور تیرا چلنا اچھا ہے ۔ اور جنت کی ایک منزل کو تو نے (اپنا) ٹھکانا بنالیا۔ (ابن ماجہ)\n¥ترجمہ حدیث4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص مریض کی عیادت کو جاتا ہے توو ہ رحمت کے دریا میں غوطہ زن رہتا ہے جب تک کہ بیٹھ نہیں جاتا اور جب بیٹھ جاتا ہے تو غریق دریائے رحمت ہوجاتا ہے ۔ (احمد، مالک)\n¥ترجمہ حدیث5:\nحضرت ابوسعید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جب تم بیمار کی مزاج پُرسی کو جاؤ تو موت کے بارے میں اس کا رنج و غم دُور کرو اگرچہ اس سے اس کی موت کا وقت نہیں ٹل سکتا لیکن ا س کا دل خوش ہوجائے گا۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث6:\nحضرت سعید بن مسیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مرسلاً منقول ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ بہترین عیادت یہ ہے کہ مزاج پرسی کے بعد فوراً اُٹھ جائے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث7:\nحضرت ابنِ عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو مسلمان کسی مسلمان کی عیادت کوجائے توسات بار یہ دعا پڑھے ’’ أَسْأَلُ اللّٰہ الْعَظِیْمَ رَبَّ العرشِ العظیم أَنْ یَشفِیک ‘‘( ) اگر موت کا وقت نہیں آگیا ہے تو اسے ضرورشفا ہوگی۔ (ابوداود، ترمذی)", "roman": "Tarjuma Hadees 1: Hazrat Ali Karam Allah Ta'ala Wajhah ne farmaya ke main ne Nabi-e-Kareem Sallallahu Alaihi Wasallam ko farmate hue suna ke jab koi Musalman apne Musalman bhai ki subah ke waqt ayadat karta hai to shaam tak sattar hazar farishtay us ke liye rehmat o maghfirat ki Dua karte hain aur jo shaam ke waqt ayadat karta hai us ke liye sattar hazar farishtay subah tak Dua-e-maghfirat karte hain aur us ke liye Jannat mein ek baagh hai. (Tirmidhi, Abu Dawood) Tarjuma Hadees 2: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jis ne achha Wazu kiya aur mehaz sawab hasil karne ki gharz se apne Musalman bhai ki ayadat ki to us ko saath baras ki musafat ke faasle par dozakh se door kar diya jata hai. (Ahmad) Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs beemar ki ayadat ko jata hai to aasman se ek munadi nida karta hai ke tu achha hai aur tera chalna achha hai. Aur Jannat ki ek manzil ko tu ne (apna) thikana bana liya. (Ibn Majah) Tarjuma Hadees 4: Hazrat Jabir Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs mareez ki ayadat ko jata hai to woh rehmat ke dariya mein ghota zan rehta hai jab tak ke baith nahi jata aur jab baith jata hai to ghareeq-e-daryaye-rehmat ho jata hai. (Ahmad, Malik) Tarjuma Hadees 5: Hazrat Abu Saeed Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab tum beemar ki mizaj pursi ko jao to maut ke bare mein us ka ranj o gham door karo agarcha us se us ki maut ka waqt nahi tal sakta lekin us ka dil khush ho jayega. (Tirmidhi, Ibn Majah) Tarjuma Hadees 6: Hazrat Saeed Bin Musayyib Radiyallahu Anhu se Mursal-an manqool hai ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke behtareen ayadat ye hai ke mizaj pursi ke baad foran uth jaye. (Baihaqi, Mishkat) Tarjuma Hadees 7: Hazrat Ibn-e-Abbas Radiyallahu Anhum ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke jo Musalman kisi Musalman ki ayadat ko jaye to saat baar ye Dua padhe: ''As'alullahal Azeema Rabbil Arshil Azeemi An Yashfiyaka'' agar maut ka waqt nahi aa gaya hai to use zaroor shifa hogi. (Abu Dawood, Tirmidhi)", "explanation": "*****"}, {"id": 7798, "bookId": 14, "volNo": "1", "hadithNo": 30, "chapter": "دوا کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ رَضِیَ اللّٰہ عَنْہُ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا أَنْزَلَ اللّٰہ دَاءً إِلَّا أَنْزَلَ لَہُ شِفَاء ‘‘ ۔ \nحدیث2:\n’’ عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لِکُلِّ دَائٍ دَوَائٌ فَإِذَا أُصِیبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللّٰہ‘‘۔\nحدیث3:\n’’ عَنْ أَبِی الدَّرْدَاء قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ أَنْزَلَ الدَّاءَ وَالدَّوَاءَ وَجَعَلَ لِکُلِّ دَائٍ دَوَاءً فَتَدَاوَوْا وَلَا تَدَاوَوْا بِحَرَامٍ ‘‘۔\nحدیث4:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ نَہَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنِ الدَّوَاءِ الْخَبِیثِ‘‘", "urdu": "¥ترجمہ حدیث1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ خدائے تعالیٰ نے کوئی ایسی بیماری نہیں پیدا کی ہے جس کے لیے شفا یعنی دوا نہ اُتاری ہو۔ (بخاری شریف)\n¥ترجمہ حدیث2:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ہر بیماری کی دوا ہے جب بیمار ی کو ( اس کی صحیح) دوا پہنچادی جاتی ہے تو خدائے تعالیٰ کے حکم سے بیمار اچھا ہوجاتا ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث3:\nحضرت ابودرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ خدائے تعالیٰ نے بیماری پیدا کی ہے دوا بھی، اور ہر بیماری کی دوا مقرر فرمائی ہے ۔ لہذا دوا کرو لیکن حرام چیز سے دوا نہ کرو۔ (ابوداود)\n¥ترجمہ حدیث4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے نجس دوا(کے استعمال)سے منع فرمایا ہے ۔ (احمد، ابوداود، ترمذی، ابن ماجہ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Khudaye Ta'ala ne koi aisi bimari nahi paida ki hai jis ke liye shifa yani Dawa na utari ho. (Bukhari Shareef) Tarjuma Hadees 2: Hazrat Jabir Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke har bimari ki Dawa hai jab bimari ko (us ki Saheeh) Dawa pahuncha di jati hai to Khudaye Ta'ala ke Hukm se beemar achha ho jata hai. (Muslim Shareef) Tarjuma Hadees 3: Hazrat Abu Darda Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Khudaye Ta'ala ne bimari paida ki hai Dawa bhi, aur har bimari ki Dawa muqarrar farmayi hai. Lehaza Dawa karo lekin Haram cheez se Dawa na karo. (Abu Dawood) Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne najis Dawa (ke istemaal) se mana farmaya hai. (Ahmad, Abu Dawood, Tirmidhi, Ibn Majah)", "explanation": "¥اِنتباہ:\n انگریزی دوائیں بکثرت ایسی موجود ہیں جن میں اسپرٹ اور شراب کی آمیزش ہوتی ہے ایسی دوائیں ہر گز استعمال نہ کی جائیں۔ ( ) (بہار شریعت، جلد ۱۶، ص ۱۲۷)"}, {"id": 7799, "bookId": 14, "volNo": "1", "hadithNo": 31, "chapter": "دعا تعویز کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’عَنْ عَاءِشَۃَ قَالَتْ أَمَرَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ نَسْتَرْ قی مِنَ الْعَیْنِ‘ ‘۔ \nحدیث2:\n’’عَنْ أُمِّ سَلَمَۃَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ رَأَی فِی بَیْتِہَا جَارِیَۃً فِی وَجْہِہَا سَفْعَۃٌ یَعْنِیْ صُفْرَۃً فَقَالَ اسْتَرْقُوا لَہَا فَإِنَّ بِہَا النَّظْرَۃَ‘‘۔ \nحدیث3:\n’’عَنْ عَوْفِ بْنِ مَالِکِنِ الْأَشْجَعِیِّ قَالَ کُنَّا نَرْقی فِی الْجَاہِلِیَّۃِ فَقُلْنَا یَا رَسُولَ اللّٰہ کَیْفَ تَرَی فِی ذَلِکَ فَقَالَ اعْرِضُوا عَلَیَّ رُقَاکُمْ لَا بَأْسَ بِالرُّقَی مَا لَمْ یَکُنْ فِیہِ شِرْکٌ‘‘۔", "urdu": "¥ترجمہ حدیث1:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے کہا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے حکم فرمایا ہے کہ ہم نظربد کے لیے دُعا تعویذ کرائیں۔ (بخاری، مسلم)\n¥ترجمہ حدیث2:\nحضرت اُم سلمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا سے روایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے ان کے گھر میں ایک لڑکی کو دیکھا جس کا چہرہ زرد تھا حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا اسے دُعا تعویذ کراؤ اسے نظر بدلگی ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث3:\nحضرت عوف بن مالک اشجعی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم لوگ زمانہ جاہلیت میں جھاڑ پھونک کرتے تھے (اسلام لانے کے بعد) ہم نے عرض کیا یارسول اللّٰہ ! ان منتروں کی بابت آپ کیا فرماتے ہیں؟ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا اپنے منتر مجھے سُناؤ ، ان منتروں میں کوئی حرج نہیں جب تک کہ ان میں شرک نہ ہو۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Aishah Radiyallahu Anha ne kaha ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne Hukm farmaya hai ke hum nazar-e-bad ke liye Dua ta'weez karayen. (Bukhari, Muslim) Tarjuma Hadees 2: Hazrat Umm-e-Salamah Radiyallahu Anha se Riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne un ke ghar mein ek Ladki ko dekha jis ka chehra zard tha Huzoor Sallallahu Alaihi Wasallam ne farmaya ise Dua ta'weez karao ise nazar-e-bad lagi hai. (Bukhari, Muslim) Tarjuma Hadees 3: Hazrat Auf Bin Malik Ashja'i Radiyallahu Anhu ne farmaya ke hum log zamana-e-jahiliyat mein jhaad phoonk karte the (Islam lane ke baad) hum ne arz kiya Ya Rasoolallah! In mantron ki babat Aap kya farmate hain? Huzoor Sallallahu Alaihi Wasallam ne farmaya apne mantar mujhe sunao, in mantron mein koi harj nahi jab tak ke in mein Shirk na ho. (Muslim Shareef)", "explanation": "¥شرح حدیث3:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں:\n’’ یعنی اسمائے جن وشیاطین نباشد واز معانی آن کفر لازم نیاید ولہذا گفتہ اندکہ آنچہ معنی اومعلوم نہ باشد رُقیہ بآں نتواں کرد مگر آنکہ بہ نقل صحیح ازشارع آمدہ باشد ‘‘([1]) ( اشعۃ اللمعات ، جلد سوم ص ۶۰۴) \n یعنی منتر میں جن و شیاطین کے نام نہ ہوں۔ اور اس منتر کے معانی سے کفر لازم نہ آتا ہو۔ ( تو اس کے پڑھنے میں کوئی حرج نہیں)اوراسی لیے علمائے سلف نے فرمایا ہے کہ جس منتر کا معنی معلوم نہ ہو اسے نہیں پڑھ سکتے ۔ لیکن جو شارع علیہ السلام سے صحیح طور پر منقول ہو (اسے پڑھ سکتے ہیں اگرچہ اس کا معنی معلوم نہ ہو)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الطب والرقی ، الفصل الأول ، ج ۳، ص ۶۴۶."}, {"id": 7800, "bookId": 14, "volNo": "1", "hadithNo": 32, "chapter": "موت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَکْثِرُوا ذِکْرَ ہَاذِمِ اللَّذَّاتِ الْمَوْتِ‘‘۔ \nحدیث2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَتَمَنَّی أَحَدُکُمْ الْمَوْتَ إِمَّا مُحْسِنًا فَلَعَلَّہُ أَنْ یَّزْدَادَ خَیْرًا وَإِمَّا مُسِیءًا فَلَعَلَّہُ یَسْتَعْتِبُ‘‘ ۔ \nحدیث3:\n’’ عَنْ أَنَسٍ قَالَ دَخَلَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَلَی شَابٍّ وَہُوَ فِی الْمَوْتِ فَقَالَ کَیْفَ تَجِدُکَ قَالَ أَرْجُو اللّٰہ یَا رَسُولَ اللّٰہ وَاِنِّی أَخَافُ ذُنُوبِی فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَجْتَمِعَانِ فِی قَلْبِ عَبْدٍ فِی مِثْلِ ہَذَا الْمَوْطِنِ إِلَّا أَعْطَاہُ اللّٰہ مَا یَرْجُو وَآمَنَہُ مِمَّا یَخَافُ‘‘\nحدیث4:\n’’ عَنْ مَعْقِلِ بْنِ یَسَارٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اقْرَء ُوا سُوْرَۃَ یس عَلَی مَوْتَاکُمْ‘‘۔ \nحدیث5:\n’’عَنْ أَبِی سَعِیدٍ وَأَبِی ہُرَیْرَۃَ قَالَا قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَقِّنُوا مَوْتَاکُمْ لا إِلَہَ إِلَّا اللّٰہ‘‘۔", "urdu": "¥ترجمہ حدیث1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ لذتوں کو ختم کردینے والی چیز ( موت) کو اکثر و بیشتر یاد کرو۔ (ترمذی، نسائی)\n¥ترجمہ حدیث2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ تم میں کوئی موت کی آرزو نہ کرے ( اس لیے کہ) وہ یا تو نیکو کار ہوگا تو ممکن ہے اس کے نیک عمل میں زیادتی ہوجائے اور یا بدکار ہوگا تو ہوسکتا ہے کہ آئندہ تو بہ کرکے خدائے تعالیٰ کی خوشنودی حاصل کرلے ۔ (بخاری شریف) \n¥ترجمہ حدیث3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم ایک جوان کے پاس تشریف لے گئے جو قریب المرگ تھا۔ حضور نے اس سے فرمایا کہ تو اپنے آپ کو کس حال میں پاتا ہے ؟ اس نے عرض کیا یارسول اللّٰہ میں خدائے تعالیٰ کی رحمت کا امیدوار ہوں اور اپنے گناہوں سے ڈرتا ہوں حضور نے فرمایا یہ دونوں ( یعنی خوف ورجا) اس موقع پر جس بندہ کے دل میں ہوں گے ۔ خدائے تعالیٰ اسے وہ چیز دے گا جس کی وہ امید رکھتا ہے اور اس چیز سے محفوظ رکھے گا جس سے وہ ڈرتا ہے ۔ (ترمذی، ابن ماجہ، مشکوۃ)\n¥ترجمہ حدیث4:\nحضرت معقل بن یسار رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اپنے مرنے والوں کے قریب سورہ ٔ یس شریف پڑھو۔ (احمد، ابوداود)\n¥ترجمہ حدیث5:\nحضرت ابو سعید اور حضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلوۃ والسلام نے فرمایا کہ اپنے مرنے والوں کو کلمہ طیبہ کی تلقین کر و۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke lazzaton ko khatam kar dene wali cheez (maut) ko aksar o beshtar yaad karo. (Tirmidhi, Nasai) Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke tum mein koi maut ki aarzoo na kare (is liye ke) woh ya to nek-o-kaar hoga to mumkin hai us ke nek amal mein zyadati ho jaye aur ya bad-kaar hoga to ho sakta hai ke aayinda taubah kar ke Khudaye Ta'ala ki khushnudi hasil kar le. (Bukhari Shareef) Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu ne farmaya ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ek jawan ke paas tashreef le gaye jo qareeb-ul-marg tha. Huzoor ne us se farmaya ke tu apne aap ko kis haal mein pata hai? Us ne arz kiya Ya Rasoolallah main Khudaye Ta'ala ki rehmat ka umeedwar hoon aur apne gunahon se darta hoon. Huzoor ne farmaya ye dono (yani khauf o raja) is mauqe par jis bandah ke dil mein honge, Khudaye Ta'ala use woh cheez dega jis ki woh umeed rakhta hai aur us cheez se mehfooz rakhega jis se woh darta hai. (Tirmidhi, Ibn Majah, Mishkat) Tarjuma Hadees 4: Hazrat Ma'qal Bin Yasar Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke apne marne walon ke qareeb Surah Yaseen Shareef padho. (Ahmad, Abu Dawood) Tarjuma Hadees 5: Hazrat Abu Saeed aur Hazrat Abu Hurairah Radiyallahu Anhum ne kaha ke Huzoor Sallallahu Alaihi Wasallam ne farmaya ke apne marne walon ko Kalima-e-Tayyibah ki Talqeen karo. (Muslim)", "explanation": "¥شرح حدیث1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ ’’ باب تمنی الموت و ذکرہ ‘‘ میں فرماتے ہیں کہ:\n ذکر موت کنایت ست از خوف وخشیت حق وعمل بمقتضائے آں وتوبہ واستغفار وتقدیم وترجیح نفع درآخرت والا ذکر موت و یاد داشتن آں بے عمل چیزے نیست بلکہ تواند کہ سبب قساوت قلب گردد چنانکہ ذکر حق سبحانہ و تعالی بہ غفلت ۔ (1)( اشعۃ اللمعات ، جلد اول ، ص ۶۵۳)\n یعنی موت کو یاد کرنے کا مطلب یہ ہے کہ دل میں خدائے تعالیٰ کا خوف و خشیت ہو اور اسی کے حکم کے مطابق عمل ہو نیز توبہ و استغفار کرے ۔ اور آخرت کے نفع کو ( دنیا کے نفع پر) مقدم رکھے اور ترجیح دے ۔ ورنہ بغیر عمل کے صرف موت کا چرچا کرنا اور اس کو یاد رکھنا کوئی چیز نہیں ہے بلکہ (ایسا کرنا) دل کی قساوت اور سختی کا سبب ہو سکتا ہے ۔ جیسے کہ غفلت اور بے عملی کے ساتھ خدائے تعالیٰ کو( صرف زبانی طور پر) یاد کرنا ( قساوت قلبی کا سبب ہے )\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب تمنی الموت وذکرہ ، ج ۱، ص ۶۹۷.\n¥شرح حدیث2:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ:\n آر زوئے مرگ بجہت ضرر دنیا مانند مرض یا فقر یا مانندآں مکروہ است زیرا کہ آں علامت بے صبری وبستوہ آمدن از تقدیر الہی و ناراض بودن از آں است اما از جہت محبت وشوق بلقائے الہی تعالی وخلاص از تنگنائے ایں سرائے ومحنت آن ووصول بملک آخرت ونعیم آن نشان ایمان وکمال اوست و ہمچنیں مکروہ نیست از جہت خوف ضرر دینی ۔ (1)\n یعنی دنیوی نقصان جیسے بیماری یا غریبی وغیرہ کی وجہ سے موت کی تمنا کرنا مکروہ ہے اس لیے کہ یہ بے صبری او ر تقدیری الہٰی سے ملال وناراضگی کی نشانی ہے لیکن خدائے تعالیٰ کی محبت اور اس کی ملاقات کے شوق میں موت کی تمنا کرنا نیز اس دنیا کی تنگی اور پریشانی سے چھٹکارا حاصل کرنے اور ملک آخرت اور جنت میں پہنچنے کے لئے موت کی آرزو کرنا ایمان اور اس کے کمال کی نشانی ہے ۔ اسی طرح دینی ضرر کے خوف سے موت کی تمنا کرنا مکروہ نہیں ہے ۔ (اشعۃ اللمعات، جلد اول، ص ۶۵۳)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب تمنی الموت وذکرہ ، ج ۱، ص ۶۹۷.\n¥شرح حدیث4:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ :\n ظاہر آنست کہ مراد مختصر باشد وعمل نیز ہم بریں ست واحتمال دارد کہ مراد بعد از موت درخانہ یا برسرِ قبر ۔ (1)\nیعنی ظاہر مراد یہ ہے کہ موت کے وقت سورۂ یس پڑھی جائے اور اسی پر عمل بھی ہے ۔ اور ہوسکتا ہے یہ مراد ہو کہ موت کے بعد گھر میں پڑھی جائے یا قبر کے سرہانے ۔ (اشعۃ اللمعات، جلد اول، ص ۲۶۲)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب ما یقول عند من حضرہ الموت ، ج ۱، ص ۷۰۶.\n¥شرح حدیث5:\nتلقین کی صورت یہ ہے کہ موت کے وقت حاضرین بلند آواز سے کلمۂ طیبہ پڑھیں لیکن مرنے والے کو اس کے پڑھنے کا حکم نہ کریں۔"}, {"id": 7801, "bookId": 14, "volNo": "1", "hadithNo": 33, "chapter": "غسل و کفن کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أُمِّ عَطِیَّۃَ قَالَتْ دَخَلَ عَلَیْنَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَنَحْنُ نَغْسِلُ ابْنَتَہُ فَقَالَ اغْسِلْنَہَا وِتْرًا ثَلَاثًا أَوْ خَمْسًا أَوْ سَبْعًا وَابْدَأْنَ بِمَیَامِنِہَا وَمَوَاضِعِ الْوُضُوءِ مِنْہَا‘‘۔\nحدیث 2:\n’’عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَفَّنَ أَحَدُکُمْ أَخَاہُ فَلْیُحَسِّنْ کَفَنَہُ‘‘۔\nحدیث3:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْبَسُوا مِنْ ثِیَابِکُمُ الْبَیَاضَ فَإِنَّہَا مِنْ خَیْرِ ثِیَابِکُمْ وَکَفِّنُوا فِیہَا مَوْتَاکُمْ ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت اُم عطیہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا کہتی ہیں کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم ہمارے پاس تشریف لائے جب کہ ہم حضور کی صاحب زادی ( حضرت زینب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا) کو غسل دے رہے تھے ) تو حضور نے فرمایا اسے غسل دو طاق ، یعنی تین یا پانچ یا سات بار، اور غسل کا سلسلہ داہنی جانب سے اور وضو کے اعضاء سے شرو ع کریں۔ (بخاری)\n میت کو غسل دینے میں کلی نہ کرائے اور نہ ناک میں پانی ڈالا جائے ۔ (بہار شریعت)\n¥ترجمہ حدیث 2:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب کوئی اپنے بھائی کو کفن دے تو چاہیے کہ اچھا کفن دے ۔ (مسلم شریف)\n¥ترجمہ حدیث 3:\nحضرت ابنِ عباس ر ضی اللّٰہ تعالیٰ عنہم ا نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ تم لوگ سفید کپڑے پہنا کر واس لیے کہ وہ عمدہ قسم کے کپڑے ہیں اور سفید کپڑوں میں اپنے مُردوں کو کفنایا کرو۔ (ابو داود، ترمذی)", "roman": "Tarjumah Hadees 1: Hazrat Umm-e-Atiyyah Radiyallahu Anha kehti hain ke Rasoolullah Sallallahu Alaihi wa Sallam hamare paas tashreef laye jab ke hum Huzoor ki sahibzadi (Hazrat Zainab Radiyallahu Anha) ko Ghusl de rahe thay, toh Huzoor ne farmaya ise Ghusl do taaq, yani teen ya paanch ya saat baar, aur Ghusl ka silsila dahni janib se aur Wazu ke aaza se shuru karein. (Bukhari). Mayyit ko Ghusl dene mein kulli na karaye aur na naak mein paani dala jaye. (Bahar-e-Shariat). Tarjumah Hadees 2: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jab koi apne bhai ko Kafan de toh chahiye ke achha Kafan de. (Muslim Shareef). Tarjumah Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke tum log safed kapde pehna karo is liye ke woh umdah qisam ke kapde hain aur safed kapdon mein apne murdon ko kafnaya karo. (Abu Dawood, Tirmidhi).", "explanation": "¥شرح حدیث 2:\nحضرتِ شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ مراد بہ تحسین کفن آنست کہ تمام باشد ونظیف و سفید و بے اسراف و تبذیر ، ونوو شستہ دراں ، برابر ست اماآنچہ مُسرفان کنند بریا وتکبر حرام ومکروہ است اشد حرمت وکراہت ‘‘۔ ([1])\n یعنی اچھے کفن کا مطلب یہ ہے کہ کفن پورا ہو اور صاف ستھرا ہو و سفید ہو ا ور اس میں اسراف و بے جا خرچ نہ ہو۔ نیا کفن اور پرانا جو دھویا ہوا ہو دونوں کا حکم ایک ہے لیکن اسراف و فضول خرچی کرنے والے جو رِیا اور تکبّر سے کرتے ہیں وہ سخت مکروہ اور اشد حرام ہے ۔ (اشعۃ اللمعات، جلد اول، ص۶۷۲)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب غسل المیت وتکفینہ ، ج ۱، ص ۷۱۷.\n¥ضرور ی انتباہ:\n (۱)…عوام میں جو مشہور ہے کہ شوہر عورت کے جنازہ کو نہ کاندھا دے سکتا ہے نہ قبر میں اُتار سکتا ہے نہ منہ دیکھ سکتا ہے ۔ یہ محض غلط ہے صرف نہلانے اور اس کے بدن کو بلا حائل ہاتھ لگانے کی ممانعت ہے ۔ ([1]) (بہار شریعت، جلد چہارم، ص ۵۱۹)\n (۲)… میّت کے دونوں ہاتھ کروٹوں میں رکھیں سینہ پر نہ رکھیں کہ یہ کفّار کا طریقہ ہے ۔ درمختار مع ردالمحتار جلد اول ص:۶۰۰ میں ہے : ’’ یُوضَعُ یَدَاہُ فِی جَانِبَیْہِ لَا عَلَی صَدْرِہِ لِأَنَّہُ مِنْ عَمَلِ الْکُفَّارِ ‘‘۔ ([2])\n (۳)… بعض جگہ میت کے دونوں ہاتھ ناف کے نیچے اس طرح رکھتے ہیں کہ’’ جیسے نماز کے قیام میں‘‘یہ بھی منع ہے ۔\n (۴)… میت کا تہبند چوٹی سے قدم تک ہونا چاہیے یعنی لفافہ سے اتنا چھوٹا جو بندش کے لیے زیادہ تھا ۔ فتاویٰ عالمگیری جلد اول مصری ص:۱۵۰ ، ہدایہ جلد اول ص:۱۳۷، اور ردالمحتار جلد اول ص:۶۰۳ میں ہے : ’ ’ اَلْإِزَارُ مِنَ الْقَرْنِ إلَی الْقَدَمِ ‘ ‘یعنی تہبند کی مقدار چوٹی سے قدم تک ہے ۔ ([3])اسی طرح بہارِ شریعت میں ہے ۔ لہذا بعض لوگ جو ناف سے پنڈلی تک رکھتے ہیں یہ صحیح نہیں۔\n (۵)…عورت کی اوڑھنی نصف پشت سے سینہ تک ہونا چاہیے جس کا اندازہ تین ہاتھ یعنی ڈیڑھ گز ہے ۔ اور عرض ایک کان کی لَو سے دوسرے کان کی لَو تک ہونا چاہیے ۔ اور جو لوگ زندگی کی طرح اوڑھنی رکھتے ہیں یہ بے جا اور خلافِ سنّت ہے ۔ ([4])(بہار شریعت)\n (۶)… عورت کے لیے سینہ بند پستان سے ناف تک ہو اور بہتر یہ ہے کہ ران تک ہو۔ فتاویٰ عالمگیری میں ہے : ’ ’ وَالْأَوْلَی أَنْ تَکُونَ الْخِرْقَۃُ مِنْ الثَّدْیَیْنِ إلَی الْفَخِذِ کَذَا فِی الْجَوْہَرَۃِ النَّیِّرَۃِ ‘‘۔ ([5])\n (۷)…سینہ بند لفافہ کے اوپر ہونا چاہیے ۔ فتاوی عالمگیری جلد اول ص:۱۵۱میں ہے : ’ ’ ثُمَّ الْخِرْقَۃُ بَعْدَ ذَلِکَ تُرْبَطُ فَوْقَ الْأَکْفَانِ فَوْقَ الثَّدْیَیْنِ کَذَا فِی الْمُحِیطِ ‘‘۔ ([6])\n اور فتح القدیرمیں ہے : ’ ’ فِی شَرْحِ الْکَنْزِ فَوْقَ الْأَکْفَانِِ ‘‘ یعنی شرح کنزالدقائق میں سینہ بند کی جگہ سب کپڑوں کے اوپر مذکور ہے ۔ ([7])\n لہذا سینہ بند کو سب کپڑوں سے پہلے لپیٹنے کا جو عام رواج ہے وہ غلط ہے ۔\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۸۱۳.\n[2] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصلاۃ ، باب صلاۃ الجنائز ، مطلب فی القراء ۃ إلخ ، ج ۳، ص ۱۰۵.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الثالث ، ج ۱، ص ۱۶۰، ’’ الہدایۃ ‘‘، باب الجنائز ، فصل = \n فی التکفین ، ج ۱، ص ۸۹، ’’ رد المحتار ‘‘، باب صلاۃ الجنازۃ ، مطلب فی الکفن ، ج ۳، ص ۱۱۲.\n[4] ’’بہارِ شریعت‘‘، ج۱، ص ۸۲۱ ، ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الباب الحادی والعشرون فی الجنائز ، الفصل الثالث ، ج ۱، ص ۱۶۱.\n[5] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الثالث فی التکفین ، ج ۱، ص ۱۶۰.\n[6] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الثالث فی التکفین ، ج ۱، ص ۱۶۱.\n[7] ’’ فتح القدیر ‘‘، باب الجنائز ، فصل فی تکفینہ ، ج ۲، ص ۱۱۸."}, {"id": 7802, "bookId": 14, "volNo": "1", "hadithNo": 34, "chapter": "جنازہ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَسْرِعُوا بِالْجِنَازَۃِ فَإِنْ تَکُ صَالِحَۃً فَخَیْرٌ تُقَدِّمُونَہَاإِلَیْہِ وَإِنْ تَکُ سِوَی ذَلِکَ فَشَرٌّ تَضَعُونَہُ عَنْ رِقَابِکُمْ‘‘\nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنِ اتَّبَعَ جَنَازَۃَ مُسْلِمٍ إِیمَانًا وَاحْتِسَابًا وَکَانَ مَعَہُ حَتَّی یُصَلّی عَلَیْہَا وَیَفْرُغَ مِنْ دَفْنِہَا فَإِنَّہ یَرْجِعُ مِنْ الْأَجْرِ بِقِیرَاطَیْنِ کُلّ قِیرَاطٍ مِثْلُ أُحُدٍ وَمَنْ صَلَّی عَلَیْہَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّہُ یَرْجِعُ بِقِیرَاطٍ‘‘.\nحدیث 3:\n’’عَنْ أَنَسٍ قَالَ مَرُّوا بِجَنَازَۃٍ فَأَثْنَوْا عَلَیْہَا خَیْرًا فَقَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَجَبَتْ ثُمَّ مَرُّوا بِأُخْرَی فَأَثْنَوْا عَلَیْہَا شَرًّا فَقَالَ وَجَبَتْ فَقَالَ عُمَرُ مَا وَجَبَتْ فَقَالَ ہَذَا أَثْنَیْتُمْ عَلَیْہِ خَیْرًا فَوَجَبَتْ لَہُ الْجَنَّۃُ وَہَذَا أَثْنَیْتُمْ عَلَیْہِ شَرًّا فَوَجَبَتْ لَہُ النَّارُ أَنْتُمْ شُہَدَاءُ اللّٰہ فِی الْأَرْضِ‘‘۔\nحدیث 4:\n’’عَنْ عَائِشَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تَسُبُّوا الْأَمْوَاتَ‘‘۔\nحدیث 5:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اذْکُرُوا مَحَاسِنَ مَوْتَاکُمْ وَکُفُّوا عَنْ مَسَاوِیہِمْ‘‘۔\nحدیث 6:\n’’ عَنْ مُحَمَّدِ بْنِ سِیْرِیْنَ قَالَ إِنَّ جَنَازَۃً مَرَّتْ بِالْحَسَنِ بْنِ عَلِیٍّ وَابْنِ عَبَّاسٍ فَقَامَ الْحَسَنُ وَلَمْ یَقُمْ اِبْنُ عَبَّاسٍ فَقَالَ الْحَسَنُ أَلَیْسَ قَدْ قَامَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لِجَنَازَۃِ یَہُودِیٍّ قَالَ نَعَمْ ثُمَّ جَلَسَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جنازہ کے لے جانے میں جلدی کرو اس لیے کہ اگر وہ نیک آدمی کا جنازہ ہے تواسے خیرکی(منزل)کی طرف جلد پہنچانا چاہیے اور اگر بد کار کا جنازہ ہے تو بُرے کو اپنی گردنوں سے جلد اُتار دینا چاہیے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص ایمان کا تقاضا سمجھ کر اور حصولِ ثواب کی نیت سے کسی مسلمان کے جنازہ کے ساتھ ساتھ چلے یہاں تک کہ اس کی نماز پڑھے اور اس کے دفن سے فارغ ہو تو وہ دو قیراط ثواب لے کر واپس لوٹتا ہے ۔ جس میں سے ہرقیراط اُحد (پہاڑ) کے برابر ہے اور جو شخص صرف جنازہ کی نماز پڑھ کر واپس آجائے اور دفن میں شریک نہ ہو تو وہ ایک قیراط کا ثواب لے کر واپس ہوتا ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ چند صحابہ کرام ایک جنازہ کے قریب سے گزرے تو خیر کے ساتھ اس کا ذکر کیا اس پر حضور علیہ الصلاۃ والسلام نے ارشاد فرمایا کہ واجب ہوگئی پھر لوگوں کا دوسرے جنازہ پر گزر ہوا تو برائی کے ساتھ اس کا ذکر کیا اس پر حضور نے ارشاد فرمایا واجب ہوگئی۔ حضرت فاروقِ اعظم رضی ا للہ تعالیٰ عنہ نے عرض کیا ( یارسول اللّٰہ ) کیا چیز واجب ہوگئی ، فرمایا جس میت کا تم لوگوں نے بھلائی کے ساتھ ذکر کیا اس کے لیے جنت واجب ہوگئی اور جس کی تم لوگوں نے برائی کی اس کے لیے دوزخ واجب ہوگئی تم لوگ زمین پر خدائے تعالیٰ کے گواہ ہو۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ مُردوں کو گالی نہ دو۔ (بخاری)\n¥ترجمہ حدیث 5:\nحضرتِ ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اپنے مُردوں کی نیکیوں کا چرچا کرو اور ان کی برائیوں سے چشم پوشی کرو۔ (ابوداود، ترمذی)\n¥ترجمہ حدیث 6:\nحضرت محمد بن سیرین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ ایک جنازہ حضرت امام حسن بن علی و ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم کے قریب سے گزرا تو حضرت امام حسن کھڑے ہو گئے اور حضرت ابن عباس نہیں کھڑے ہوئے ۔ حضرت امام حسن نے حضرت ابن عباس سے فرمایا کیا حضور علیہ الصلاۃ والسلام ایک یہودی کاجنازہ دیکھ کر کھڑے نہیں ہوئے تھے ؟ حضرت ابن عباس نے کہا ہاں لیکن پھر اس کے بعد بیٹھے رہتے تھے ( اور کھڑے نہ ہوتے تھے )۔ (نسائی)", "roman": "Tarjumah Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke Janazah ke le jaane mein jaldi karo is liye ke agar woh nek aadmi ka Janazah hai toh use khair ki manzil ki taraf jald pahunchana chahiye aur agar badkar ka Janazah hai toh bure ko apni gardanon se jald utaar dena chahiye. (Bukhari, Muslim). Tarjumah Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo shakhs imaan ka taqaza samajh kar aur husool-e-sawab ki niyat se kisi Musalman ke Janazah ke saath saath chale yahan tak ke us ki Namaz padhe aur us ke dafan se farigh ho toh woh do qeeraat sawab le kar wapas laut-ta hai. Jis mein se har qeeraat Uhad (pahar) ke barabar hai aur jo shakhs sirf Janazah ki Namaz padh kar wapas aa jaye aur dafan mein shirkat na ho toh woh ek qeeraat ka sawab le kar wapas hota hai. (Bukhari, Muslim). Tarjumah Hadees 3: Hazrat Anas Radiyallahu Anhu ne farmaya ke chand Sahabah qareeb se guzre toh khair ke saath us ka zikr kiya, is par Rasoolullah Sallallahu Alaihi wa Sallam ne irshad farmaya ke Wajib ho gayi. Phir logon ka dusre Janazah par guzar hua toh burai ke saath us ka zikr kiya, is par Huzoor ne irshad farmaya Wajib ho gayi. Hazrat Farooq-e-Azam Radiyallahu Anhu ne arz kiya (Ya Rasoolullah) kya cheez Wajib ho gayi? Farmaya jis Mayyit ka tum logon ne bhalai ke saath zikr kiya us ke liye Jannat Wajib ho gayi aur jis ki tum logon ne burai ki us ke liye Dozakh Wajib ho gayi, tum log Zameen par Allah Ta'ala ke Gawah ho. (Bukhari, Muslim). Tarjumah Hadees 4: Hazrat Aishah Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke murdon ko gaali na do. (Bukhari). Tarjumah Hadees 5: Hazrat Ibn Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke apne murdon ki nekiyon ka charcha karo aur un ki buraiyon se chashm-poshi karo. (Abu Dawood, Tirmidhi). Tarjumah Hadees 6: Hazrat Muhammad Bin Sireen Radiyallahu Anhu se riwayat hai ke ek Janazah Hazrat Imam Hasan Bin Ali aur Ibn Abbas Radiyallahu Anhu ke qareeb se guzra toh Hazrat Imam Hasan khade ho gaye aur Hazrat Ibn Abbas nahi khade hue. Hazrat Imam Hasan ne Hazrat Ibn Abbas se farmaya kya Rasoolullah Sallallahu Alaihi wa Sallam ek Yahudi ka Janazah dekh kar khade nahi hue thay? Hazrat Ibn Abbas ne kaha haan lekin phir us ke baad baithe rehte thay (aur khade na hote thay). (Nasa'i).", "explanation": "¥شرح حدیث 3:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت فرماتے ہیں کہ:\n’’ مراد ثنائے اہلِ خیر وصلاح وصدق وتقوی بے مدخلیت غرض نفسانی ست کہ آن علامت بودن مردست از اہل جنت والا اگر بعضے از فساقِ وفجار بغرضے از اغراض یکے از اہل فسق بستایند یا یکے صالحے رانکوہش کنند قطع بداں نتواں کرد ۔ ([1])\n یعنی اہلِ خیر و صلاح اور صدق وتقویٰ والوں کی ایسی تعریف مراد ہے جس میں نفسانی غرض شامل نہ ہو اس لیے کہ ایسی ہی تعریف آدمی کے جنتی ہونے کی نشانی ہے ورنہ اگر بعض فاسق وفاجر کسی غرض سے کسی فاسق کی تعریف کریں یا کسی نیک صالح آدمی کی برائی کریں تو اس کی وجہ سے ( جنتی یا جہنمی ہونے کا) یقین نہیں کرسکتے ۔ (اشعۃ اللمعات، جلد اول، ص۶۸۲)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب المشی بالجنازۃ والصلاۃ علیھا ، الفصل الأول ، ج ۱، ص ۷۲۷.\n¥شرح حدیث 5:\nحضرت عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت فرماتے ہیں کہ:\n ایں مخصوص ست بمسلماناں وصالحان وآنکہ آشکارا فسق نکنند وظلم نہ کنند ۔ ([1]) ( اشعۃ اللمعات جلد ، اول )\n یعنی یہ حکم ان نیک مسلمانوں کے ساتھ مخصوص ہے جو علانیہ فسق و ظلم نہیں کر تے ہیں۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب المشی بالجنازۃ والصلاۃ علیھا ، الفصل الثانی ، ج ۱، ص ۷۳۲.\n¥شرح حدیث 6:\nاشعۃ اللمعات ترجمۂ مشکوۃ میں اس حدیث کے تحت ہے کہ:\n ’’ پس حکم سابق منسوخ شد وایں نسخ درجنازہ یہود باشد یا مطلق واللّٰہ اعلم وظاہر ثانی ست ‘‘۔ ([1])\n یعنی تو پہلا حکم منسوخ ہوگیا اور یہ منسوخ ہونا صرف یہودی جنازہ کے بارے میں ہے یا ہر ایک کے لیے ، خدائے تعالیٰ بہتر جانتا ہے لیکن ظاہر یہ ہے کہ سب کے لیے ہے ۔\n فتاویٰ عالمگیری جلد اول مصری ص:۱۵۲ میں ہے :\n’’ لَا یَقُومُ لِلْجَنَازَۃِ إلَّا أَنْ یُـرِیـدَ أَنْ یَشْہَدَہَا ‘‘۔ ([2])\n یعنی جنازہ کے لیے نہ کھڑا ہو لیکن اس میں شرکت کا ارادہ ہو تو کھڑا ہوسکتا ہے ۔\n اور طحطاوی ص:۳۶۷میں ہے :\n’’ فَھُوَمَکْرُوْہٌ کَمَا فِی القُھُستَانِی ‘‘([3])\nیعنی جنازہ دیکھ کر کھڑا ہونا مکروہ ہے جیسا کہ قہستانی میں ہے ۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘ ، کتاب الجنائز ، باب المشی بالجنازۃ والصلاۃ علیھا ، ج ۱، ص ۷۳۴.\n[2] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل الرابع فی حمل الجنازۃ ، ج ۱، ص ۱۶۲.\n[3] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، باب احکام الجنائز ، فصل فی حملھا ودفنھا ، ص ۶۰۷."}, {"id": 7803, "bookId": 14, "volNo": "1", "hadithNo": 35, "chapter": "دفن میت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عُرْوَۃَ بْنِ الزُّبَیْرِ قَالَ کَانَ بِالْمَدِینَۃِ رَجُلَانِ أَحَدُہُمَا یَلْحَدُ وَالْآخَرُ لَا یَلْحَدُ فَقَالُوا أَیُّہُمَا جَاءَ أَوَّلًا عَمِلَ عَملَہُ فَجَاءَ الَّذِی یَلْحَدُ فَلَحَدَ لِرَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ‘‘۔ \nحدیث 2:\n’’عَنْ عَلِیٍّ أَنَّہُ قَالَ شَہِدَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ جِنَازَۃَ رَجُلٍ فَقَالَ یَا عَلِیُّ اسْتَقْبِلْ بِہِ اسْتِقْبَالًا وَقُولُوا جَمِیعًا بِاسْمِ اللّٰہ وَعَلَی مِلَّۃِ رَسُولِ اللّٰہ وَضَعُوہُ لِجَنْبِہِ وَلَا تَکُبُّوہُ لِوَجْہِہِ وَلَا تُلْقُوہُ لِظَہْرِہِ‘‘۔ \nحدیث 3:\n’’عَنْ سُفْیَانَ التَّمَّار أَنَّہُ رَأَی قَبْرَ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مُسَنَّمًا‘‘۔\nحدیث 4:\n ’’ عَنْ جَابِرٍ قَالَ رُشَّ قَبْرُ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَکَانَ الَّذِیْ رَشَّ الْمَاءَ عَلَی قَبْرِہِ بِلالُ بْنُ ربَاحٍ بِقِرْبَۃٍ بَدَأَ مِنْ قِبَلِ رَأَسِہِ حَتَّی اِنْتَھَی إِلَی رِجْلَیْہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عروہ بن زبیر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایاکہ مدینہ شریف میں دو آدمی قبر کھودا کرتے تھے ۔ ایک ان میں سے (حضرت ابوطلحہ انصاری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ تھے جو) لحد یعنی بغلی کھودتے تھے ۔ اور دوسرے (حضرت ابوعبیدہ بن الجراح رَضِیَ اللّٰہ تَعَالٰی عَنْہُ تھے جو) بغلی نہیں کھودتے تھے ۔ ( بلکہ شق یعنی صندوقی قبر بناتے تھے ) حضور علیہ الصلاۃ والسلام کے وصال پر ) صحابہ نے آپس میں طے کیا کہ جو ان دونوں میں سے پہلے آئے گا وہ اپنا کام کرے گا۔ تو پہلے وہ صحابی آئے جو لحد کھودا کرتے تھے تو انہوں نے حضور علیہ الصلاۃ والسلام کے لیے بغلی قبر تیار کی۔ (شرح السنۃ، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم علیہ الصلاۃ والسلام نے ایک آدمی کے جنازہ میں شرکت کی تو فرمایا اے علی مردہ کو قبلہ کی جانب متوجہ کرو اور سب لوگ بِاسْمِ اللّٰہ وَعَلَی مِلَّۃِ رَسُوْلِ اللّٰہ ( )پڑھو۔ اور اس کو کروٹ پر رکھو۔ منہ کے بل اوندھا نہ کرو اور نہ پیٹھ کے بل چت لٹاؤ۔ (بدائع الصنائع)\n¥ترجمہ حدیث 3:\nحضرت سفیان تمّار رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ انہوں نے حضور علیہ الصلاۃ والسلام کی قبر شریف کو دیکھا جو اُونٹ کے کوہان کی طرح (اُٹھی ہوئی) تھی۔ (بخاری)\n¥ترجمہ حدیث 4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کی قبر شریف پرپانی چھڑکا گیا۔ اور پانی چھڑکنے والے حضرت بلال بن رُباح تھے ۔ انہوں نے مشک سے پانی چھڑکا اور سرہانے سے چھڑکنا شروع کیا اور قدموں تک چھڑکا۔ (بیہقی، مشکوۃ)", "roman": "Tarjumah Hadees 1: Hazrat Urwah Bin Zubair Radiyallahu Anhu ne farmaya ke Madina Shareef mein do aadmi Qabr khoda karte thay. Ek un mein se (Hazrat Abu Talha Ansari Radiyallahu Anhu thay jo) Lahad yani baghli khodte thay. Aur dusre (Hazrat Abu Ubaidah Bin Al-Jarrah Radiyallahu Anhu thay jo) baghli nahi khodte thay (balki Shiq yani sandooki Qabr banate thay). Rasoolullah Sallallahu Alaihi wa Sallam ke wisal par Sahabah ne aapas mein tay kiya ke jo in dono mein se pehle aayega woh apna kaam karega. Toh pehle woh Sahabi aaye jo Lahad khoda karte thay toh unhon ne Rasoolullah Sallallahu Alaihi wa Sallam ke liye baghli Qabr tayyar ki. (Sharh-us-Sunnah, Mishkat). Tarjumah Hadees 2: Hazrat Ali Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alaihi wa Sallam ne ek aadmi ke Janazah mein shirkat ki toh farmaya ae Ali! Mayyit ko Qiblah ki janib mutawajjah karo aur sab log Bismillahi wa ala millati Rasoolillah parho. Aur us ko karwat par rakho. Munh ke bal oondha na karo aur na peeth ke bal chit litao. (Badai-us-Sanai). Tarjumah Hadees 3: Hazrat Sufyan Tammar Radiyallahu Anhu se riwayat hai ke unhon ne Rasoolullah Sallallahu Alaihi wa Sallam ki Qabr shareef ko dekha jo oont ke kohan ki tarah (uthi hui) thi. (Bukhari). Tarjumah Hadees 4: Hazrat Jabir Radiyallahu Anhu ne farmaya ke Nabi Kareem Sallallahu Alaihi wa Sallam ki Qabr shareef par paani chhirka gaya. Aur paani chhirakne wale Hazrat Bilal Bin Rabah thay. Unhon ne mashk se paani chhirka aur sarhane se chhirakna shuru kiya aur qadmon tak chhirka. (Baihaqi, Mishkat).", "explanation": "¥شرح حدیث 2:\nاس حدیث شریف سے واضح طور پر معلوم ہوا کہ میت کو داہنی کروٹ پر لِٹایا جائے ۔ اور یہی صحیح ہے جیسا کہ بہارِ شریعت جلد چہارم ص:۵۴۵ میں ہے :’’ میت کو داہنی کروٹ پر لِٹائیں۔ ‘‘([1])\n اور فتاویٰ عالمگیری جلد اول مصری ص:۱۵۵میں ہے : ’’ وَیُوضَعُ فِی الْقَبْرِ عَلَی جَنْبِہِ الْأَیْمَنِ مُسْتَقْبِلَ الْقِبْلَۃِ کَذَا فِی الْخُلَاصَۃِ ‘‘۔ ([2])\n اور درمختار مع ردالمحتار جلد اول ، ص:۶۲۶میں ہے : ’’ وَ یَنْبَغِی کَوْنُہُ عَلَی شِقِّہِ الْأَیْمَنِ ‘‘۔ ([3])\n اور بحرالرائق جلد ثانی ص :۱۹۴ میں ہے : ’’ یَکُونُ عَلَی شِقِّہِ الْأَیْمَن ِ‘‘۔ ([4])\n اور بدائع الصنائع جلد اول ، ص:۳۱۹ میں ہے : ’’ وَیُوضَعُ عَلَی شِقِّہِ الْأَیْمَنِ مُتَوَجِّہًا إِلَی الْقِبْلَۃِ ‘‘۔ ([5])\n اور مراقی الفلاح میں ہے : ’ ’ یُوَجَّہُ اِلَی الْقِبْلَۃِ ‘ ‘۔ ([6])\nان عبارتوں کا خلاصہ یہ ہے کہ میت کو قبر میں داہنے پہلو پر لِٹانا بہتر ہے ۔\n فتح القدیر جلد ثالث ص:۹۵پر ہے :\n ’’ إِنَّہُ عَلَیْہِ السَّلَامُ فِی الْقَبْرِ الشَّرِیفِ الْمُکَرَّمِ عَلَی شِقِّہِ الْأَیْمَنِ مُسْتَقْبِلَ الْقِبْلَۃِ ‘‘۔ ([7])\nیعنی حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم عظمت والی قبر شریف میں قبلہ رُو اپنے داہنے پہلو پر (رونق افروز) ہیں۔\n اور طحطاوی ص: ۲۶۹میں ہے :\n’’ وَیُسْنَدُ الْمَیِّتُ مِنْ وَرَاءِہِ بِنَحْوِ تُرَابٍ لِءَلاَّ یَنْقَلِبَ ‘‘۔ ([8])\nیعنی میت کو کروٹ پر لِٹانے میں اس کی پیٹھ کی جانب مٹی وغیرہ کی ٹیک لگادی جائے تاکہ وہ پلٹ نہ جائے ۔\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۸۴۴، ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، ج ۱، ص ۱۶۶.\n[2] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، الفصل السادس فی القبر والدفن إلخ ، ج ۱، ص ۱۶۶.\n[3] ’’ الدر المختار ورد المحتار ‘‘، باب صلاۃ الجنازۃ ، مطلب فی دفن المیت ، ج ۳، ص ۱۶۷.\n[4] ’’ البحرالرائق ‘‘ ، کتاب الجنائز ، فصل السلطان أحق بصلاتہ ، ج ۲، ص ۳۳۹.\n[5] ’’ بدائع الصنائع ‘‘، کتاب الصلاۃ ، فصل فی سنۃ الدفن ، ج ۲، ص ۶۳.\n[6] ’’ مراقی الفلاح ‘‘، باب أحکام الجنائز ، فصل فی سنۃ الدفن ، ص ۳۴۳.\n[7] ’’ فتح القدیر ‘‘، کتاب الحج ، باب مسا ئل منثورہ ، ج ۳، ص ۱۶۹.\n[8] ’’ حاشیۃ الطحطاوی ‘‘، کتاب الصلاۃ ، باب أحکام الجنائز ، فصل فی حملھا ودفنھا ، ص ۶۰۹.\n¥انتباہ :\n (۱) …مستحب یہ ہے کہ سرہانے کی طرف دونوں ہاتھ سے تین بار مٹی ڈالیں۔ پہلی بار مِنْہَا خَلَقْنَاکُمْ دوسری بار وَفِیہَا نُعِیدُکُمْ اور تیسری بار وَمِنْہَا نُخْرِجُکُمْ تَارَۃً أُخْرَی پڑھیں۔ ([1])(طحطاوی، بہارشریعت)\n (۲) … شجرہ یا عہد نامہ قبر میں رکھنا جائز ہے اور بہتر یہ ہے کہ میت کے منہ کے سامنے قبلہ کی جانب طاق کھود کر اس میں رکھیں۔ ([2]) (بہارشریعت)\n (۳) …میت کی پیشانی یا کفن پر عہد نامہ لکھنا بہتر ہے ۔ درمختار مع ردالمحتار جلد اول ص:۶۳۳میں ہے ۔ ’’ کُتِبَ عَلَی جَبْہَۃِ الْمَیِّتِ أَوْ عِمَامَتِہِ أَوْ کَفَنِہِ عَہْدُ نَامَہْ یُرْجَی أَنْ یَغْفِرَ اللّٰہ لِلْمَیِّتِ ‘‘۔ ([3])\n (۴) …پیشانی پر بِسْمِ اللّٰہ شریف یا سینہ پر کلمہ طیبہ لکھنا بھی جائز ہے ۔ مگر نہلانے کے بعد کفن پہنانے سے پہلے کلمہ کی انگلی سے لکھیں روشنائی سے نہ لکھیں۔ ([4]) (رد المحتار، جلد اول، ۶۳۴)\n (۵) … دفن کے بعد قبر کے سرہانے اذان پڑھنا جائز بلکہ مستحسن ہے ۔\n (۶) …علماء سادات اور مشائخ کرام کی قبروں پر قبہ یا عمارت بنانا جائز ہے ۔ ردالمحتار جلداول ص:۶۲۷ میں ہے : ’’ قِیلَ لَا یکْرَہُ الْبِنَاءُ إذَا کَانَ الْمَیِّتُ مِنَ الْمَشَایِخِ وَالْعُلَمَاءِ وَالسَّادَاتِ ‘‘۔ ([5])\n نیز درمختار ، باب الدفن اور طحطاوی ص: ۳۷۰ میں ہے : ’’ لَا یُرْفَعُ عَلَیْہِ بِنَائٌ وَقِیلَ لَا بَأْسَ بِہِ وَہُوَ الْمُخْتَارُ ‘‘۔ ([6])\n (۷) …اولیائے کرام کی اظہارِ عظمت کے لیے ان کے مزارات پر چادر ڈالنا ، پھول رکھنا اور ان کے مزارات کے قریب چراغ روشن کرناجائز ہے ۔ ([7]) (رد المحتار، عالمگیری، حدیقہ ندیہ)\n------------------\n[1] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، کتاب الصلاۃ ، باب أحکام الجنائز ، فصل فی حملھا ودفنھا ، ص ۶۱۱، ’’بہارشریعت‘‘، ج۱، ص ۸۴۵، ’’ الجوھرۃ النیرۃ ‘‘، کتاب الصلاۃ ، باب الجنائز ، ص ۱۴۱.\n[2] ’’بہارشریعت‘‘، ج۱، ص۸۴۸، الدر المختار ، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، ج ۳، ص ۱۸۵.\n[3] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، ج ۳، ص ۱۸۵.\n[4] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، ج ۳، ص ۱۸۶.\n[5] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، مطلب فی دفن المیت ، ج ۳، ص ۱۷۰.\n[6] ’’ الدر المختار ‘‘، باب الد فن ، ج ۳، ص ۱۶۹۔ ۱۷۰، ’’ حاشیۃ الطحطاوی ‘‘، کتاب الصلاۃ ، ص ۶۱۱.\n[7] ’’ رد المحتار ‘‘، کتاب الحظر والاباحۃ ، فصل فی اللبس ، ج ۹، ص ۵۹۹، ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، الباب السادس عشر فی زیارۃ إلخ ، ج ۵، ص ۳۵۱، ’’ الحدیقۃ الندیۃ ‘‘، ج ۲، ص ۶۳۰."}, {"id": 7804, "bookId": 14, "volNo": "1", "hadithNo": 36, "chapter": "میت پر رونا", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَلَا تَسْمَعُونَ إِنَّ اللّٰہ لَا یُعَذِّبُ بِدَمْعِ الْعَیْنِ وَلَا بِحُزْنِ الْقَلْبِ وَلَکِنْ یُعَذِّبُ بِہَذَا وَأَشَارَ إِلَی لِسَانِہِ أَوْ یَرْحَمُ وَإِنَّ الْمَیِّتَ لَیُعَذَّبُ بِبُکَاء أَہْلِہِ عَلَیْہِ‘‘\nحدیث 2:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّہُ مَہْمَا کَانَ مِنْ الْعَیْنِ وَ مِنَ الْقَلْبِ فَمِنَ اللّٰہ عَزَّ وَجَلَّ وَمِنَ الرَّحْمَۃِ وَمَا کَانَ مِنَ الْیَدِ وَ مِنَ اللِّسَانِ فَمِنَ الشَّیْطَانِ ‘‘۔\nحدیث 3:\n’’عَنْ أَبِیْ مُوسَی الْأَشْعَرِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا مَاتَ وَلَدُ الْعَبْدِ قَالَ اللّٰہ تَعَالَی لِمَلَاءِکَتِہِ قَبَضْتُمْ وَلَدَ عَبْدِی فَیَقُولُونَ نَعَمْ فَیَقُولُ قَبَضْتُمْ ثَمَرَۃَ فُؤَادِہِ فَیَقُولُونَ نَعَمْ فَیَقُولُ مَاذَا قَالَ عَبْدِی فَیَقُولُونَ حَمِدَکَ وَاسْتَرْجَعَ فَیَقُولُ اللّٰہ ابْنُوا لِعَبْدِی بَیْتًا فِی الْجَنَّۃِ وَسَمُّوہُ بَیْتَ الْحَمْدِ‘‘۔\nحدیث 4:\n’’عَنْ مُعَاذِ بْنِ جَبَلٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا مِنْ مُسْلِمَیْنِ یُتَوَفَّی لَہُمَا ثَلَاثَۃٌ إِلَّا أَدْخَلَہُمَا اللّٰہ الْجَنَّۃَ بِفَضْلِ رَحْمَتِہِ إِیَّاہُمَا فَقَالُوا یَا رَسُولَ اللّٰہ أَوْ اثْنَانِ قَالَ أَوْ اثْنَانِ قَالُوا أَوْ وَاحِدٌ قَالَ أَوْ وَاحِدٌ ثُمَّ قَالَ وَالَّذِی نَفْسِی بِیَدِہِ إِنَّ السِّقْطَ لَیَجُرُّ أُمَّہُ بِسَرَرِہِ إِلَی الْجَنَّۃِ إِذَا احْتَسَبَتْہُ‘‘۔\nحدیث 5:\n’’ عَنْ عَبْدِ اللّٰہ بْنِ جَعْفَرٍ قَالَ لَمَّا جَاء نَعْیُ جَعْفَرٍ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اِصْنَعُوا لِآلِ جَعْفَرٍ طَعَامًا فَقَدْ أَتَاہُمْ مَا یَشْغَلُہُمْ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عبد اللّٰہ بن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسول ِ کریم علیہ الصلاۃ والسلام نے فر مایا کہ خبردار ہو کر سن لو کہ آنکھ کے آنسو اور دل کے غم کے سبب خدائے تعالیٰ عذاب نہیں فرماتا۔ (اور زبان کی طرف اشارہ کرکے فرمایا) لیکن اس کے سبب عذاب یا رحم فرماتا ہے ۔ ا ور گھر والوں کے رونے کی وجہ سے میت پر عذاب ہوتا ہے ۔ ( جب کہ اس نے رونے کی وصیت کی ہو یا وہاں رونے کا رواج ہو اور اس نے منع نہ کیا ہو یا یہ مطلب ہے کہ ان کے رونے سے میت کو تکلیف ہوتی ہے )۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو آنسو آنکھ سے ہو اور جو غم سے ہو تو وہ اللّٰہ تعالیٰ کی جانب سے ہے اور اس کی رحمت کا حصہ ہے اور غم کا جو اظہار ہاتھ اور زبان سے ہو وہ شیطان کی طرف سے ہے ۔ (مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابو موسی اشعری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جب کسی مومن بندہ کا بیٹا مرجاتا ہے تو خدائے تعالیٰ ملائکہ سے فرما تا ہے کہ تم نے میرے بندہ کے بیٹے کی روح قبض کرلی تو وہ عرض کر تے ہیں ہاں، پھر خدائے تعالیٰ فرماتا ہے کہ تم نے اس کے دل کے میوہ کو توڑ لیا۔ تو وہ عرض کرتے ہیں ہاں۔ پھر خدائے تعالیٰ فرماتا ہے (اس مصیبت پر)میرے بندہ نے کیا کہا ؟ تو فرشتے عرض کرتے ہیں کہ تیری تعریف کی اور إِنَّا ﷲِ وإِنَّا إِلَیْہِ رَاجِعُونَ پڑھا تو خدائے تعالیٰ فرماتا ہے کہ میرے اس بندہ کے لیے جنت میں ایک گھر بناؤ اور اس کا نام بیت الحمد رکھو۔ (احمد، ترمذی)\n¥ترجمہ حدیث 4:\nحضرت معاذ بن جبل رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جن دو مسلمان یعنی میاں بیوی کے تین بچے مرجائیں تو خدائے تعالیٰ ان دونوں کو اپنے فضل و رحمت سے جنت میں داخل فرمائے گا۔ صحابہ نے عرض کیا یارسول اللّٰہ !اگر دو بچے انتقال کرجائیں تو حضور نے فرمایا دو کا بھی یہی اجر ہے ۔ پھر صحابہ نے عرض کیا یارسول اللّٰہ ! اور اگر ایک فوت ہوجائے تو حضور نے فرمایا ایک کا بھی یہی اجر ہے ۔ پھر فرمایا قسم ہے اس ذات کی جس کے دست قدرت میں میری جان ہے کہ خام حمل جو ساقط ہوجاتا ہے اپنی ماں کو’’ آنول‘‘کے ذریعہ جنت کی طرف کھینچے گا۔ جب کہ ماں ( اس تکلیف پر ) صبر اور ثواب کی طالب ہوئی ہو۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت عبد اللّٰہ بن جعفر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے فرمایا کہ جب حضرت جعفر کی شہادت کی خبر آئی تو نبی کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جعفر کے گھر والوں کے لیے کھانا تیار کرو اس لیے کہ ان کو وہ مصیبت پہنچی ہے جو انہیں کھانا پکانے سے باز رکھے گی۔ (ترمذی، ابوداود، ابن ماجہ)", "roman": "Tarjumah Hadees 1: Hazrat Abdullah Bin Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke khabardar ho kar sun lo ke aankh ke aansu aur dil ke gham ke sabab Allah Ta'ala azab nahi farmata (aur zaban ki taraf ishara karke farmaya) lekin is ke sabab azab ya raham farmata hai. Aur ghar walon ke rone ki wajah se Mayyit par azab hota hai (jab ke us ne rone ki Wasiyat ki ho ya wahan rone ka riwaj ho aur us ne mana na kiya ho ya yeh matlab hai ke un ke rone se Mayyit ko takleef hoti hai). (Bukhari, Muslim). Tarjumah Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo aansu aankh se ho aur jo gham se ho toh woh Allah Ta'ala ki janib se hai aur us ki rahmat ka hissa hai aur gham ka jo izhar haath aur zaban se ho woh Shaitan ki taraf se hai. (Mishkat). Tarjumah Hadees 3: Hazrat Abu Musa Ash'ari Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jab kisi Momin bandah ka beta mar jata hai toh Allah Ta'ala malaika se farmata hai ke tum ne mere bandah ke bete ki rooh qabz kar li? Toh woh arz karte hain haan, phir Allah Ta'ala farmata hai ke tum ne us ke dil ke mewa ko tod liya? Toh woh arz karte hain haan. Phir Allah Ta'ala farmata hai (is museebat par) mere bandah ne kya kaha? Toh farishte arz karte hain ke teri tareef ki aur Inna lillahi wa inna ilaihi raji'oon parha. Toh Allah Ta'ala farmata hai ke mere is bandah ke liye Jannat mein ek ghar banao aur us ka naam Bait-ul-Hamd rakho. (Ahmad, Tirmidhi). Tarjumah Hadees 4: Hazrat Mu'adh Bin Jabal Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jin do Musalman yani miyan biwi ke teen bachche mar jayen toh Allah Ta'ala un dono ko apne fazl-o-rahmat se Jannat mein dakhil farmayega. Sahabah ne arz kiya Ya Rasoolullah! Agar do bachche inteqal kar jayen? Toh Huzoor ne farmaya do ka bhi yahi ajar hai. Phir Sahabah ne arz kiya Ya Rasoolullah! Aur agar ek faut ho jaye? Toh Huzoor ne farmaya ek ka bhi yahi ajar hai. Phir farmaya qasam hai us zaat ki jis ke dast-e-qudrat mein meri jaan hai ke kham hamal jo saaqit ho jata hai apni maa ko 'aanwal' ke zariye Jannat ki taraf khenchega. Jab ke maa (is takleef par) sabr aur sawab ki talib hui ho. (Ahmad, Mishkat). Tarjumah Hadees 5: Hazrat Abdullah Bin Ja'far Radiyallahu Anhu ne farmaya ke jab Hazrat Ja'far ki Shahadat ki khabar aayi toh Nabi Kareem Sallallahu Alaihi wa Sallam ne farmaya ke Ja'far ke ghar walon ke liye khana tayyar karo is liye ke un ko woh museebat pahunchi hai jo unhein khana pakane se baaz rakhegi. (Tirmidhi, Abu Dawood, Ibn Majah).", "explanation": "¥شرح حدیث 5:\nاس حدیث کے تحت حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ:\n’’ دریں حدیث دلیل است بر آنکہ مستحب ست خویشاں وہمسائیگان ودوستان راتہیئہ طعام مراہل میت را ‘‘۔ ([1])\n یعنی اس حدیث شریف سے ثابت ہوا کہ رشتہ داروں ، پڑوسیوں اور دوستوں کو میت کے گھر پکا ہوا کھانا لانا مستحب ہے ۔ (اشعۃ اللمعات، جلد اول)\n¥انتباہ:\n (۱) …نوحہ یعنی میت کے اوصاف مبالغہ کے ساتھ بیان کرکے آواز سے رونا جس کو بَین کہتے ہیں۔ بالاجماع حرام ہے ۔ ([2]) (بہار شریعت بحوالہ جوھرہ)\n (۲) …گریبان پھاڑنا، منہ نوچنا ، بال کھولنا، سر پر مٹی ڈالنا ، ران پرہاتھ مارنا اور سینہ کوٹنا سب جاہلیت کے کام ہیں۔ ناجائز اور گناہ ہیں۔ ([3])(فتاوی عالمگیری، جلد اول مصری، ص ۱۵۷)\n (۳) …آواز سے رونا منع ہے اور آواز بلند نہ ہو تو اس کی ممانعت نہیں۔ ([4])( (بہارشریعت)\n (۴) … تعزیت مسنون ہے اور اس کاوقت موت سے تین دن تک ہے اس کے بعد مکروہ ہے ، اور اگر کوئی موجود نہ تھا یا علم نہ تھا تو بعد میں حرج نہیں ۔ ([5]) (بہار شریعت، بحوالہ ردالمحتار وغیرہ)\n (۵) … تعزیت میں یہ کہے کہ خدائے تعالیٰ میت کی مغفرت فرمائے اور اس کو اپنی رحمت میں ڈھانکے اور تم کو صبر کی توفیق دے اور مصیبت پر ثواب عطا فرمائے ، یا اسی کے مثل دوسرے جملے کہے ۔\n (۶) …میت کے گھر صرف پہلے دن کھانا بھیجنا سنت ہے اس کے بعد مکروہ ہے ۔ ([6]) (بہار شریعت بحوالہ عالمگیری)\n (۷) … میت کے گھر والے تیجہ کے دن یا اس کے بعد میت کے ایصالِ ثواب کے لیے فقراء اور مساکین کو کھانا کھلائیں تو بہتر ہے لیکن دوست احباب اور عام مسلمانوں کی دعوت کریں تو ناجائز و بدعت قبیحہ ہے کہ دعوت توخوشی کے وقت مشروع ہے نہ کہ غم کے وقت۔ فتاویٰ عالمگیری جلد اول مصری ص:۱۵۷میں ہے : ’’ لَا یُبَاحُ اتِّخَاذُ الضِّیَافَۃِ عِنْدَ ثَلاثَۃِ أَیَّامٍ کَذَا فِی التَّتَارْخَانِیَّۃ ‘‘۔ ([7])\n اور ردالمحتار جلد اول ص: ۶۲۹اور فتح القدیر جلد دوم ص:۱۰۲میں ہے : ’’ وَیُکْرَہُ اتِّخَاذُ الضِّیَافَۃِ مِنَ الطَّعَامِ مِنْ أَہْلِ الْمَیِّتِ لِأَنَّہُ شُرِعَ فِی السُّرُورِ لَا فِی الشُّرُورِ وَہِیَ بِدْعَۃٌ مُسْتَقْبَحَۃٌ ‘‘۔ ([8]) \n (۸) … تیجہ وغیرہ کا کھانا اکثر میت کے ترکہ سے کیا جاتا ہے اس میں یہ لحاظ ضروری ہے کہ ورثہ میں نابالغ نہ ہو ور نہ سخت حرام ہے لیکن بالغ اگر اپنے حصہ سے کرے تو حرج نہیں۔ ([9]) (بہار شریعت بحوالہ خانیہ)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب البکاء علی المیت ، الفصل الثانی ، ج ۱، ص ۷۵۳.\n[2] ’’بہارِ شریعت‘‘، ج۱، ص ۸۵۴، ’’ الجوہرۃ النیرۃ ‘‘، کتاب الصلاۃ ، باب الجنائز ، ص ۱۳۹.\n[3] الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، مسائل فی التعزیۃ ، ج ۱، ص ۱۶۷.\n[4] ’’بہار شر یعت‘‘، ج۱، ص ۸۵۵، ’’ الجوہرۃ النیرۃ ‘‘، کتاب الصلاۃ ، باب الجنائز ، ص ۱۳۹.\n[5] ’’بہارِ شریعت‘‘، ج۱، ص ۸۵۲، ’’ رد المحتار ‘‘، کتاب الصلاۃ ، مطلب فی کراھۃ إلخ ، ج ۳، ص ۱۷۷.\n[6] ’’بہارِ شریعت‘‘، ج۱، ص ۸۵۴، ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، ج ۵، ص ۳۴۴.\n[7] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصلاۃ ، مسائل فی التعزیۃ ، ج ۱، ص ۱۶۷.\n[8] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، ج ۳، ص ۱۷۵، ’’ فتح القدیر ‘‘، کتاب الصلاۃ ، باب الجنائز ، فصل فی الدفن ، ج ۲، ص ۱۵۱.\n[9] ’’بہارِ شریعت‘‘، ج۱، ص ۸۵۳، ’’ الفتاوی الخانیۃ ‘‘، کتاب الحظر والاباحۃ ، ج ۴، ص ۳۶۶."}, {"id": 7805, "bookId": 14, "volNo": "1", "hadithNo": 37, "chapter": "شہید کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ الْمِقْدَامِ بْنِ مَعْدِیکَرِبَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لِلشَّہِیدِ عِنْدَ اللّٰہ سِتُّ خِصَالٍ یُغْفَرُ لَہُ فِی أَوَّلِ دَفْعَۃٍ وَیُرَی مَقْعَدَہُ مِنَ الْجَنَّۃِ وَیُجَارُ مِنْ عَذَابِ الْقَبْرِ وَیَأْمَنُ مِنَ الْفَزَعِ الْأَکْبَرِ وَیُوضَعُ عَلَی رَأْسِہِ تَاجُ الْوَقَارِ الْیَاقُوتَۃ مِنْہَا خَیْرٌ مِنَ الدُّنْیَا وَمَا فِیہَا وَیُزَوَّجُ ثِنْتَیْنِ وَسَبْعِینَ زَوْجَۃً مِنَ الْحُورِ الْعِینِ وَیُشَفَّعُ فِی سَبْعِینَ مِنْ أَقْرِبَاءِہِ‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرِو بْنِ الْعَاصِ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ الْقَتْلُ فِی سَبِیلِ اللّٰہ یُکَفِّرُ کُلَّ شَیْئٍ إِلَّا الدَّیْنَ‘‘۔\nحدیث 3:\n’’عَنْ سَہْلِ بْنِ حُنَیْفٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ سَأَلَ اللّٰہ الشَّہَادَۃَبِصِدْقٍ بَلَّغَہُ اللّٰہ مَنَازِلَ الشُّہَدَاءِ وَإِنْ مَاتَ عَلَی فِرَاشِہِ‘‘۔\nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ مَاتَ وَلَمْ یَغْزُ وَلَمْ یُحَدِّثْ بِہِ نَفْسَہُ مَاتَ عَلَی شُعْبَۃٍ مِنْ نِفَاقٍ‘‘\nحدیث 5:\n’’عَنْ أَنَسٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ جَاہِدُوا الْمُشْرِکِینَ بِأَمْوَالِکُمْ وَأَنْفُسِکُمْ وَأَلْسِنَتِکُمْ‘‘۔ \nحدیث 6:\n’’ عَنْ أَبِی مُوسَی قَالَ جَاءَ رَجُلٌ إِلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ الرَّجُلُ یُقَاتِلُ لِلْمَغْنَمِ وَالرَّجُلُ یُقَاتِلُ لِلذِّکْرِ وَالرَّجُلُ یُقَاتِلُ لِیُرَی مَکَانُہُ فَمَنْ فِی سَبِیلِ اللّٰہ؟ قَالَ مَنْ قَاتَلَ لِتَکُونَ کَلِمَۃُ اللّٰہ ہِیَ الْعُلْیَا فَہُوَ فِی سَبِیلِ اللّٰہ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت مقداد بن معدیکرب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ خدائے تعالیٰ کے تئیں شہید کے لیے چھ باتیں ہیں۔ پہلی ہی مرتبہ یعنی خون کا پہلا قطرہ گرتے ہی اسے بخشا جائے گا۔ اوراس کاٹھکانہ جنت میں دکھایا جائے گا۔ عذابِ قبر سے محفوظ رکھا جائے گا۔ بڑی گھبراہٹ سے امن میں رہے گا۔ اس کے سر پر وقار کا ایسا تاج رکھا جائے گا کہ جس کا یاقوت دنیا اور دنیا کی تمام چیزوں سے بہتر ہوگا۔ اس کے نکاح میں بڑی بڑی آنکھوں والی بہتر(۷۲) حوریں دی جائیں گی۔ اور اس کے عزیزوں میں سے ستر(۷۰) آدمیوں کے لیے اس کی شفاعت قبول کی جائے گی۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن عمرو بن العاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ نبی کر یم علیہ الصلوۃو السلام نے فرمایا کہ خدائے تعالیٰ کی راہ میں قتل کیا جانا قرض کے علاوہ ہر گناہ کو مٹا دیتا ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 3:\nحضرت سہل بن حنیف رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جو شخص خدائے تعالیٰ سے سچے دل سے شہادت طلب کرے تو اللّٰہ تعالیٰ اسے شہید کا مرتبہ عطا فرمادیتا ہے ۔ اگرچہ وہ اپنے بستر پر مرے ۔ (مسلم شریف)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص مر گیا اور جہاد نہ کیا نہ جہاد کا خیال دل میں لایا تو اس کی موت نفاق کی ایک قسم پر ہوئی۔ (مسلم شریف)\n¥ترجمہ حدیث 5:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اپنی جان و مال اور زبانوں کے ذریعہ مشرکین سے جہاد کرو۔ (ابوداود، نسائی)\n¥ترجمہ حدیث 6:\nحضرت ابوموسی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ ایک شخص نے حضور کی بارگاہ میں حاضر ہو کر کہا کہ کوئی مالِ غنیمت کے لیے لڑتا ہے ، کوئی شہرت و ناموری کے لیے لڑتا ہے اور کوئی اپنی بہادری و شجاعت دکھانے کے لیے لڑتا ہے تو ان میں سے راہِ حق میں لڑنے والا کون ہے ؟ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا جو اس لیے لڑتا ہے کہ اللّٰہ تعالیٰ کے دین کا بول بالا ہو تو وہ مجاہد فی سبیل اللّٰہ ہے ۔ (بخاری، مسلم)", "roman": "Tarjumah Hadees 1: Hazrat Miqdad Bin Ma'dikarib Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke Allah Ta'ala ke tayin Shaheed ke liye chhe baatein hain. Pehli hi martaba yani khoon ka pehla qatra girte hi use bakhsha jayega. Aur us ka thikana Jannat mein dikhaya jayega. Azab-e-Qabr se mehfooz rakha jayega. Badi ghabrahat se amn mein rahega. Us ke sar par waqar ka aisa taaj rakha jayega ke jis ka yaqoot duniya aur duniya ki tamam cheezon se behtar hoga. Us ke Nikah mein badi badi aankhon wali behtar (72) hoorein di jayengi. Aur us ke azizon mein se sattar (70) aadmiyon ke liye us ki Shafa'at Qubool ki jayegi. (Tirmidhi, Ibn Majah). Tarjumah Hadees 2: Hazrat Abdullah Bin Amr Bin Al-Aas Radiyallahu Anhu se riwayat hai ke Nabi Kareem Sallallahu Alaihi wa Sallam ne farmaya ke Allah Ta'ala ki raah mein qatl kiya jana Qarz ke alawa har gunah ko mita deta hai. (Muslim Shareef). Tarjumah Hadees 3: Hazrat Sahl Bin Haneef Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo shakhs Allah Ta'ala se sachche dil se Shahadat talab kare toh Allah Ta'ala use Shaheed ka martaba ata farma deta hai. Agarcheh woh apne bistar par mare. (Muslim Shareef). Tarjumah Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo shakhs mar gaya aur Jihad na kiya na Jihad ka khayal dil mein laya toh us ki maut nifaq ki ek qisam par hui. (Muslim Shareef). Tarjumah Hadees 5: Hazrat Anas Radiyallahu Anhu se riwayat hai ke Nabi Kareem Sallallahu Alaihi wa Sallam ne farmaya ke apni jaan-o-Maal aur zabanon ke zariye mushrikeen se Jihad karo. (Abu Dawood, Nasa'i). Tarjumah Hadees 6: Hazrat Abu Musa Radiyallahu Anhu ne kaha ke ek shakhs ne Huzoor ki bargah mein hazir ho kar kaha ke koi Maal-e-Ghanimat ke liye ladta hai, koi shohrat-o-naamwari ke liye ladta hai aur koi apni bahaduri-o-shuja'at dikhane ke liye ladta hai toh in mein se raah-e-haq mein ladne wala kaun hai? Huzoor Sallallahu Alaihi wa Sallam ne farmaya jo is liye ladta hai ke Allah Ta'ala ke Deen ka bol bala ho toh woh Mujahid fi Sabeelillah hai. (Bukhari, Muslim).", "explanation": "*****"}, {"id": 7806, "bookId": 14, "volNo": "1", "hadithNo": 38, "chapter": "قبروں کی زیارت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ بُرَیْدَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ نَہَیْتُکُمْ عَنْ زِیَارَۃِ الْقُبُورِ فَزُورُوہَا‘‘۔ \nحدیث 2:\n’’عَنِ ابْنِ مَسْعُودٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ کُنْتُ نَہَیْتُکُمْ عَنْ زِیَارَۃِ الْقُبُورِ فَزُورُوہَا فَإِنَّہَا تُزَہِّدُ فِی الدُّنْیَا وَتُذَکِّرُ الْآخِرَۃَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت بریدہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ میں نے تم لوگوں کو قبروں کی زیارت سے منع کیا تھا ( اب میں تمہیں اجازت دیتا ہوں کہ) ان کی زیارت کرو۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ میں نے تم لوگوں کو قبروں کی زیارت سے روکا تھا تو اب میں تمہیں اجازت دیتا ہوں کہ انکی زیارت کرو اس لیے کہقبروں کی زیارت کرنا دنیا سے بیزار کرتا ہے ۔ اور آخرت کی یاد دلاتا ہے ۔ (ابن ماجہ)", "roman": "Tarjumah Hadees 1: Hazrat Buraidah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke main ne tum logon ko Qabron ki Ziyarat se mana kiya tha (ab main tumhein ijazat deta hoon ke) un ki Ziyarat karo. (Muslim). Tarjumah Hadees 2: Hazrat Ibn Mas'ood Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke main ne tum logon ko Qabron ki Ziyarat se roka tha toh ab main tumhein ijazat deta hoon ke un ki Ziyarat karo is liye ke Qabron ki Ziyarat karna duniya se bezar karta hai. Aur Aakhirat ki yaad dilata hai. (Ibn Majah).", "explanation": "¥اِنتباہ :\n (۱)…قبروں کی زیارت کا بہتر طر یقہ یہ ہے کہ پائنتی کی جانب سے جا کرمیت کے منہ کے سامنے کھڑا ہو اور یہ کہے : ’’ السَّلَامُ عَلَیْکُمْ أَہْلَ دَارِ قَوْمٍ مُؤْمِنِینَ أَنْتُمْ لَنَا سَلَفٌ وَإِنَّا إنْ شَاءَ اللّٰہ بِکُمْ لَاحِقُونَ نَسْأَلُ اللّٰہ لَنَا وَلَکُمْ الْعَفْوَ وَالْعَافِیَۃَ ‘‘ پھر تین یا پانچ یا سات یا گیارہ بار درود شریف پڑھے بعدہٗ جس قدر ہوسکے قرآن شریف کی سورتیں اور آیتیں تلاوت کرے مثلاً سورۂ یس، سورۂ ملک ، چاروں قُل ، سورۂ فاتحہ، الٓم سے مُفْلِحُوْنَ تک، آیۃ الکرسی اور اٰمَنَ الرَّسُوْلُ وغیرہ پھر آخر میں درود شریف پڑھ کر ایصالِ ثواب کرے اور افضل یہ ہے کہ ایصالِ ثواب میں سب مؤمنین و مؤمنات کو شامل کرے کہ ہر ایک کو پورا پورا ثواب ملے گا اورکسی کے اجر میں کچھ کمی نہ ہوگی۔ ([1]) (رد المحتار)\n (۲)… اولیائے کرام کے مزارات مقدسہ کی زیارت کے لیے سفر کرنا جائز ہے ۔ ([2]) (بہارشریعت بحوالہ رد المحتار)\n (۳)… اولیائے کرام کی زیارت کرنا خدائے تعالیٰ سے محبت کی دلیل ہے اور زائرین کو کافر و بدعتی کہنا کھلی ہوئی گمراہی اور بدعقیدگی ہے ۔ تفسیر صاوی جلد اول ص :۲۴۵ ، آیت ِکریمہ:{ ابْتَغُوا إِلَیْہِ الْوَسِیلَۃَ } کے تحت ہے کہ:\n ’’ مِنَ الضَّلَالِ الْبَیِّنِ وَالْخُسْرَانِ الظَّاھِرِ تَکْفِیْرُ الْمُسْلِمِیْنَ بِزِیَارَۃِ أَوْلِیَاءاللّٰہ زَاعِمِیْنَ أَنَّ زِیَارَتَھُمْ مِنْ عِبَادَۃِ غَیْرِ اللّٰہ کَلَّا بَلْ ھِیَ مِنْ جمْلَۃِ الْمَحَبَّۃِ فِیْ اللّٰہ ‘‘۔ ([3])\n یعنی اولیاء اللّٰہ کی زیارت کے سبب مسلمانوں کو اس خیال سے کافر کہنا کہ ان کی زیارت عبادتِ غیر اللّٰہ ہے کھلی ہوئی گمراہی اور خسارے کا سبب ہے ۔ (اولیاء کی زیارت عبادت غیر اللّٰہ ) ہر گز نہیں ہے ۔ بلکہ یہ الحبُّ فِی اللّٰہ میں سے ہے ۔\n (۴)… منکرات ِشرعیہ اگر ایامِ عرس میں پائے جائیں تو ان کی وجہ سے زیارت ترک نہ کرے اس لیے کہ ایسی باتوں سے نیک کام ترک نہیں کیا جاتا بلکہ اسے بُرا جانے اور اصلاح کی جدوجہد کرے ۔ جیسا کہ ردالمحتار جلد اول ص:۶۳۱ میں ہے : ’’ قَالَ ابْنُ حَجَرٍ فِی فَتَاوِیہِ وَلَا تُتْرَکُ لِمَا یَحْصُلُ عِنْدَہَا مِنْ مُنْکَرَاتٍ وَمَفَاسِد کَاخْتِلَاطِ الرِّجَالِ بِالنِّسَاء وَغَیْرِ ذَلِکَ لِأَنَّ الْقُرُبَاتِ لَا تُتْرَکُ لِمِثْلِ ذَلِکَ بَلْ عَلَی الْإِنْسَانِ فِعْلُہَا وَإِنْکَارُ الْبِدَع بَلْ وَإِزَالَتُہَا إنْ أَمْکَنَ ا ہـ ۔ قُلْت وَیُؤَیِّدُ مَا مَرَّ مِنْ عَدَمِ تَرْکِ اتِّبَاعِ الْجِنَازَۃِ وَإِنْ کَانَ مَعَہَا نِسَاء وَنَاءِحَاتٌ تَأَمَّلْ ‘‘۔ ([4])\n (۵)…عورتوں کو عزیزوں کی قبروں پر جانا ممنوع ہے اس لیے کہ وہ جزع فزع کر یں گی۔\n (۶)…اولیائے کرام کے مزاراتِ مقدسہ پر برکت کے لیے حاضر ہونے میں بوڑھی عورتوں کے لیے حرج نہیں اور جوانوں کے لیے ناجائز ہے ۔ جیسا کہ ردالمحتار جلد اول ص:۶۳۱ میں ہے : ’’ وَالتَّبَرُّک بِزِیَارَۃِ قُبُورِ الصَّالِحِینَ فَلَا بَأْسَ إِذَا کُنَّ عَجَاءِزَ وَیُکْرَہُ إِذَا کُنَّ شَوَابَّ کَحُضُورِ الْجَمَاعَۃِ فِی الْمَسَاجِدِ ‘‘۔ ([5])\n اور علامہ طحطاوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اسی کے مثل لکھنے کے بعد فرماتے ہیں کہ :\n ’ ’ حَاصِلُہ أَنَّ مَحَلَّ الرُّخْصَۃِ لَھُنَّ إِذَا کَانَتِ الزِّیَارَۃُ عَلَی وَجْہٍ لَیْسَ فِیْہِ فِتْنَۃٌ ‘‘ ۔ ([6])\nیعنی حاصل یہ ہے کہ عورتوں کے لیے اجازت صرف اس صورت میں ہے جب کہ زیارت ایسے طریقے پرہو کہ اس میں کوئی فتنہ نہ ہو۔ (طحطاوی، ص ۳۷۶)\n اور حضرت صدر الشریعہ رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے تحریر فرمایا ہے کہ اسلم یہ ہے کہ عورتیں مطلقاً ( یعنی جوان ہوں یا بوڑھی سب) منع کی جائیں۔ ([7]) (بہار شریعت ، جلد چہارم ص ۵۴۹)\n (۷)…مزاراتِ مقدسہ پر ہاتھ پھیرنا ، بوسہ دینا، ان کے سامنے جھکنا اور زمین پر چہرہ ملنا منع ہے اس لیے کہ یہ چیزیں عاداتِ نصاریٰ میں سے ہیں۔ جیسا کہ اشعۃ اللمعات، جلد او ل، باب زیارت القبور، ص:۷۱۶ میں ہے : ’’ مسح نہ کند قبر را وبوسہ ندہد آنرا ومنخی نہ شود وروئے بہ خاک نہ مالدکہ ایں عادت نصاریٰ ست ‘‘۔ ([8])\n اور فتاویٰ عالمگیری جلد پنجم مصری ص:۳۰۴میں ہے :\n ’’ وَلَا یَمْسَحُ الْقَبْرَ وَلَا یُقَبِّلُہُ فَإِنَّ ذَلِکَ مِنْ عَادَۃِ النَّصَارَی ‘‘ ۔ ([9])\n یعنی قبر پر ہاتھ نہ پھیرے اور نہ اسے بوسہ دے اس لیے کہ وہ عاداتِ نصاریٰ میں سے ہے ۔\n اور فتاویٰ رضویہ جلد چہارم ، ص: ۸ میں ہے ۔ مزارات کو بوسہ نہ دینا چاہیے ([10])۔\n (۸)… قبر کو سجدہ ([11]) کرنا حرام ہے اور عبادت کی نیت سے ہو تو کفر ہے ۔\n------------------\n[1] ’’ رد المحتار ‘‘، کتا الصلاۃ ، باب صلاۃ الجنائز ، مطلب فی زیارۃ القبور ، ج ۳، ص ۱۷۸۔ ۱۷۹.\n[2] ’’بہارِ شریعت‘‘، ج۱، ص ۸۴۸، ’’ رد المحتار ‘‘، کتاب الصلاۃ ، مطلب فی زیارۃ القبور ، ج ۳، ص ۱۷۷.\n[3] ’’ تفسیر الصاوی ‘‘، سورۃ المائدۃ ، ج ۱، ص ۴۹۷.\n[4] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، مطلب فی زیارۃ القبور ، ج ۳، ص ۱۷۸.\n[5] ’’ رد المحتار ‘‘ ، کتاب الصلاۃ ، باب صلاۃ الجنازۃ ، مطلب فی زیارۃ القبور ، ج ۳، ص ۱۷۸.\n[6] ’’ حاشیۃ الطحطاوی ‘‘، کتاب الصلاۃ ، باب أحکام الجنائز ، فصل فی زیارۃ القبور ، ص ۶۲۰.\n[7] ’’بہارِ شریعت‘‘، ج۱، ص ۸۴۹.\n[8] ’’ اشعۃ اللمعات ‘‘، کتاب الجنائز ، باب زیارۃ القبور ، الفصل الأول ، ج ۱، ص ۷۶۳. \n[9] ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراہیۃ ، الباب السادس عشر فی زیارۃ القبور إلخ ، ج ۵، ص ۳۵۱.\n[10] ’’ الفتاوی الرضویۃ ‘‘، ج ۹، ص ۵۲۸.\n[11] شرح فقہ اکبر صفحہ نمبر ۲۳۰ میں ہے :’’ اَلسَّجْدَۃُ حَرَامٌ لِغَیْرِہِ سُبْحَانَہ ‘‘ یعنی غیر اللّٰہ کے لیے سجدہ حرام ہے ۔ (’’ شرح الفقہ الأکبر ‘‘، ص ۱۸۷)اور فتاویٰ عالمگیری جلد پنجم مصری صفحہ نمبر ۲۳۱میں جواہر الاخلاطی سے ہے ۔ ’’ قَالَ الْفَقِیہُ أَبُو جَعْفَرٍ رَحِمَہُ اللّٰہ تَعَالَی وَإِنْ سَجَدَ لِلسُّلْطَانِ بِنِیَّۃِ الْعِبَادَۃِ أَوْ لَمْ تَحْضُرْہُ النِّیَّۃُ فَقَدْ کَفَرَ ‘‘ یعنی فقیہ ابو جعفر رحمۃ اللّٰہ تعالیٰ علیہ نے فرمایا کہ اگر عبادت کی نیت سے بادشاہ کو سجدہ کیا یا کوئی نیت اس وقت نہ تھی تو کافر ہوگیا۔ (’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، ج ۵، ص ۳۶۸)"}, {"id": 7807, "bookId": 14, "volNo": "1", "hadithNo": 39, "chapter": "ایصال ثواب کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ سَعْدِ بْنِ عُبَادَۃَ قَالَ یَا رَسُولَ اللّٰہ إِنَّ أُمَّ سَعْدٍ مَاتَتْ فَأَیُّ الصَّدَقَۃِ أَفْضَلُ قَالَ الْمَاءُ فَحَفَرَ بِئْرًا وَقَالَ ہَذِہِ لِأُمِّ سَعْدٍ رَوَاہُ أَبُوداؤد وَالنِّسَائی‘‘۔ (مشکوۃ، ص۱۹۹)\nحدیث 2:\n’’ عَنْ عَائِشَۃَ أَنَّ رَجُلًا أَتَی النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ یَا رَسُولَ اللّٰہ إِنَّ أُمِّیَ افْتُلِتَتْ نَفْسُہَا وَلَمْ تُوصِ وَأَظُنُّہَا لَوْ تَکَلَّمَتْ تَصَدَّقَتْ أَفَلَہَا أَجْرٌ إِنْ تَصَدَّقْتُ عَنْہَا قَالَ نَعَمْ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت سعد بن عبادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے کہ انہوں نے حضور علیہ الصلوۃ والسلام سے عرض کیا کہ ام سعد یعنی میری ماں کا انتقال ہوگیا ہے ان کے لیے کون سا صدقہ افضل ہے ۔ سرکار ِ اقدس نے فرمایا پانی (بہترین صدقہ ہے تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے ارشاد کے مطابق) حضرت سعد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کنواں کھدوایا ( اور اسے اپنی ماں کی طرف منسوب کرتے ہوئے ) کہا یہ کنواں سعد کی ماں کے لیے ہے ۔ (یعنی اس کا ثواب ان کی روح کو ملے )۔ (ابوداود، نسائی)\n¥ترجمہ حدیث 2:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا سے روایت ہے کہ ایک شخص آئے اور انہوں نے عرض کیا یارسول اللّٰہ ! میری ماں کا اچانک انتقال ہوگیا اور وہ کسی بات کی وصیت نہ کرسکی۔ میر ا گمان ہے کہ انتقال کے وقت اگر اسے کچھ کہنے سننے کا موقع ملتا تو وہ صدقہ ضرور دیتی تو اگر میں اس کی طرف سے صدقہ کروں تو کیا اس کی رُوح کو ثواب پہنچے گا ؟ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ ہاں پہنچے گا۔ (مسلم ، جلد اول ، ص ۳۲۴)", "roman": "Tarjumah Hadees 1: Hazrat Sa'd Bin Ubadah Radiyallahu Anhu se marwi hai ke unhon ne Rasoolullah Sallallahu Alaihi wa Sallam se arz kiya ke Umm-e-Sa'd yani meri maa ka inteqal ho gaya hai un ke liye kaun sa Sadaqah afzal hai? Sarkar-e-Aqdas ne farmaya paani (behtareen Sadaqah hai toh Rasoolullah Sallallahu Alaihi wa Sallam ke irshad ke mutabiq) Hazrat Sa'd Radiyallahu Anhu ne Kunwan khodwaya (aur use apni maa ki taraf mansoob karte hue) kaha yeh Kunwan Sa'd ki maa ke liye hai. (Yani is ka sawab un ki rooh ko mile). (Abu Dawood, Nasa'i). Tarjumah Hadees 2: Hazrat Aishah Radiyallahu Anha se riwayat hai ke ek shakhs aaye aur unhon ne arz kiya Ya Rasoolullah! Meri maa ka achanak inteqal ho gaya aur woh kisi baat ki Wasiyat na kar saki. Mera guman hai ke inteqal ke waqt agar use kuch kehne sunne ka mauqa milta toh woh Sadaqah zaroor deti toh agar main us ki taraf se Sadaqah karoon toh kya us ki rooh ko sawab pahunchega? Sarkar-e-Aqdas Sallallahu Alaihi wa Sallam ne farmaya ke haan pahunchega. (Muslim, Jild Awwal, S 324).", "explanation": "علامہ نووی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت فرماتے ہیں کہ :\n ’’ فِی ھَذَا الْحَدِیْثِ أَنَّ الصَّدْقَۃَ عَنِ الْمَیِّتِ تَنْفَعُ الْمَیِّتَ وَیَصِلُ ثَوَابُھَا وَھُوَ کَذَلِکَ بِإِجْمَاعِ الْعُلَمَاء ‘‘۔ ([1])( نووی شرح مسلم ، جلد اول ، ص ۳۲۴)\n یعنی اس حدیث شریف سے ثابت ہوا کہ اگر میت کی طرف سے صدقہ کیا جائے تو میت کو اس کا فائدہ و ثواب پہنچتا ہے ۔ اسی پر علماء کا اتفاق ہے ۔\n( ان احادیث کریمہ سے مندرجہ ذیل باتیں واضح طور پرمعلوم ہوئیں۔ )\n (۱)… میت کے ایصالِ ثواب کے لیے پانی بہترین صدقہ ہے کہ کنواں وغیرہ کھدوا کر اس کا ثواب میت کو بخش دیا جائے ۔\n (۲)…میت کو کسی کارِ خیر کا ثواب بخشنا بہتر ہے ۔ تفسیر عزیزی پارہ عم ص: ۱۱۳ میں ہے : ’’ مردہ در آن حالت مانند غریقی ست کہ انتظار فریاد رسی می برد وصدقات وادعیہ وفاتحہ دریں وقت بسیار بکارمی آید وازیں جاست کہ طوائف بنی آدم تایکسال وعلی الخصوص تایک چلّہ بعد موت دریں نوع امداد کوشش تمام می نمایند ‘‘۔ ([2])\n (۳)…ثواب بخشنے کے الفاظ زبان سے ادا کرنا صحابی کی سنت ہے ۔\n (۴)…کھانا یا شیرینی وغیرہ کو سامنے رکھ کر ایصالِ ثواب کرنا جائز ہے اس لیے کہ حضرت سعد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے اشارئہ قریب کا لفظ استعمال کرتے ہوئے فرمایا’ ’ ھٰذِہ لِاُمِّ سَعْدٍ ‘‘ یہ کنواں سعد کی ماں کے لیے ہے ۔ یعنی اے اللّٰہ تعالیٰ اس کنو ئیں کے پانی کا ثواب میری ماں کو عطا فرما۔ اس سے معلوم ہوا کہ کنواں ان کے سامنے تھا۔\n (۵)…غریب و مسکین کو کھانا وغیرہ دینے سے پہلے بھی ایصالِ ثواب کرنا جائز ہے ۔ جیسا کہ صحابی رسول نے کیا کہ کنواں تیار ہونے کے ساتھ ہی انہوں نے ایصالِ ثواب کیا حالانکہ لوگوں کے پانی استعمال کرنے کے بعد ثواب ملے گا۔ اسی طرح اگرچہ غریب و مسکین کو کھانا دینے پر ثواب مرتب ہوگا۔ لیکن اس ثواب کو پہلے ہی سے بخش دینا بھی جائز ہے ۔\n (۶)…کسی چیز پر میت کا نام آنے سے وہ چیز حرام نہ ہوگی مثلاً غوث پاک کا بکرا، اور غازی میاں کا مرغا وغیرہ اس لیے کہ ایک جلیل القدر صحابی نے اس کنوئیں کو اپنی مرحومہ ماں کے نام سے منسوب کیا تھا جو آج تک ’’ بیرأُمّ سعد ‘‘ ہی کے نام سے مشہور ہے ۔\n------------------\n[1] ’’ نووی شرح مسلم ‘‘، کتاب الزکاۃ ، باب وصول ثواب الصدقۃ عن المیت إلیہ ، ج ۴، ص ۹۰.\n[2] ’’ تفسیر عزیزی ‘‘ ، پارہ عم ، ص ۱۱۳."}, {"id": 7808, "bookId": 14, "volNo": "1", "hadithNo": 40, "chapter": "زکوٰۃ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنِ اسْتَفَادَ مَالًا فَلَا زَکَاۃَ فِیْہِ حَتَّی یَحُولَ عَلَیْہِ الْحَوْلُ‘‘۔\nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا مِنْ صَاحِبِ ذَہَبٍ وَلَا فِضَّۃٍ لَا یُؤَدِّی مِنْہَا حَقَّہَا إِلَّا إِذَا کَانَ یَوْم الْقِیَامَۃِ صُفِّحَتْ لَہُ صَفَاءِحُ مِنْ نَارٍ فَأُحْمِیَ عَلَیْہَا فِی نَارِ جَہَنَّمَ فَیُکْوَی بِہَا جَنْبُہُ وَجَبِینُہُ وَظَہْرُہُ کُلَّمَا بَرَدَتْ أُعِیدَتْ لَہُ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ آتَاہُ اللّٰہ مَالًا فَلَمْ یُؤَدِّ زَکَاتَہُ مُثِّلَ لَہُ مَالُہُ یَوْمَ الْقِیَامَۃِ شُجَاعًاأَقْرَع لَہُ زَبِیبَتَانِ یُطَوَّقُہُ یَوْمَ الْقِیَامَۃِ ثُمَّ یَأْخُذُ بِلِہْزِمَتَیْہِ یَعْنِی بِشِدْقَیْہِ ثُمَّ یَقُولُ أَنَا مَالُکَ أَنَا کَنْزُکَ ثُمَّ تَلَا {وَلَا یَحْسَبَنَّ الَّذِینَ یَبْخَلُونَ بِمَا اَتَاہُمُ اللّٰہ مِنْ فَضْلِہِ ہُوَ خَیْرًا لَہُمْ بَلْ ہُوَ شَرٌّ لَہُمْ سَیُطَوَّقُونَ مَا بَخِلُوا بِہِ یَوْمَ الْقِیَامَۃِ}‘‘۔ \nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَکُونُ کَنْزُ أَحَدِکُمْ یَوْمَ الْقِیَامَۃِ شُجَاعًا أَقْرَع یَفِرُّ مِنْہُ صَاحِبُہُ وَہُوَ یَطْلُبُہُ حَتَّی یُلْقِمَہُ أَصَابِعَہُ‘‘۔ \nحدیث 5:\n’’ عَنْ عَمْرِو بْنِ شُعَیْبٍ عَنْ أَبِیہِ عَنْ جَدِّہِ أَنَّ اِمْرَأَتَیْنِ أَتَتَا رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَفِی أَیْدِیَہُمَا سُوَارَانِ مِنْ ذَہَبٍ فَقَالَ لَہُمَا أَتُؤَدِّیَانِ زَکَاتَہُ قَالَتَا لَا فَقَالَ لَہُمَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَتُحِبَّانِ أَنْ یُسَوِّرَکُمَا اللّٰہ بِسُوَارَیْنِ مِنْ نَارٍ قَالَتَا لَا قَالَ فَأَدِّیَا زَکَاتَہُ‘‘۔ (\nحدیث 6:\n’’ عَنْ سَمُرَۃَ بْنِ جُنْدُبٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ یَأْمُرُنَا أَنْ نُخْرِجَ الصَّدَقَۃَ مِنَ الَّذِی نُعِدُّ لِلْبَیْعِ‘‘۔ \nحدیث 7:\n’’عَنْ مُوسَی بْنِ طَلْحَۃَ قَالَ عِنْدَنَا کِتَابُ مُعَاذِ بْنِ جَبَلٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّمَا أَمَرَہُ أَنْ یَأْخُذَ الصَّدَقَۃَ مِنَ الْحِنْطَۃِ وَالشَّعِیرِ وَالزَّبِیبِ وَالتَّمْرِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص مال حاصل کرے تو اس پر اس وقت تک زکوۃ نہیں جب تک کہ اس پر ایک سال نہ گزر جائے ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص سونے یا چاندی کے شرعی نصاب کا مالک ہو اور وہ اس کا حق یعنی زکاۃ نہ ادا کرے تو قیامت کے دن اس کے لیے اس سونے اور چاندی کی سلیں بنائی جائیں گی اور انہیں آگ میں تپایا جائے گا۔ پھر ان آتشیں سلوں سے اس کے پہلو ، پیشانی اور پیٹھ کو داغا جائے گا اور جب وہ ٹھنڈی ہو جائے گی تو پھر دوزخ کی آگ میں تپا کر داغا جائے گا اور ہمیشہ اسی طرح ہوتا رہے گا۔ (مسلم)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جس شخص کو خدائے تعالیٰ نے مال عطا کیا تو اس نے اس کی زکوۃ نہیں ادا کی تو اس کے مال کو قیامت کے دن گنجے سانپ کی شکل میں تبدیل کردیا جائے گا جس کے سر پر دو چتیاں ہوں گی وہ سانپ اس کے گلے میں طوق بنا کر ڈال دیا جائے گا پھر وہ سانپ اس کی باچھیں پکڑے گا اور کہے گا کہ میں تیرا مال ہوں، میں تیرا خزانہ ہوں اس کے بعد حضور نے (پارہ ۴ رکوع ۹ کی) آیت کریمہ تلاوت کی وَلَا یَحْسَبَنَّ الَّذِینَ إلخ یعنی اور جو لوگ بخل کرتے ہیں اس چیز میں جسے خدائے تعالیٰ نے انہیں اپنے فضل سے عطا کی ( تو انجام کار) ہر گز اسے اپنے لیے اچھا نہ سمجھیں بلکہ وہ ان کے لیے برا ہے ، عنقریب وہ مال کہ جس میں بخل کیا تھا قیامت کے دن ان کے گلے کا طوق ہوگا۔ (بخاری)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول ِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ تمہارا خزانہ قیامت کے دن ایک گنجا سانپ بنے گا۔ اس کا مالک اس سے بھاگے گا اور وہ سانپ اس کو ڈھونڈتا پھرے گا۔ یہاں تک کہ اس کو پالے گا اور اس کی انگلیوں کو لقمہ بنائے گا۔ (احمد)\n¥ترجمہ حدیث 5:\nحضرت عمرو بن شعیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ااپنے والد سے اور وہ اپنے دادا سے روایت کرتے ہیں کہ دو عورتیں حضور علیہ الصلاۃ والسلام کی خدمت میں حاضر ہوئیں اور ان کے ہاتھوں میں سونے کے دوکنگن تھے آپ نے ان سے پوچھا کیا تم ان کی زکوۃ دیتی ہو؟ انہوں نے عرض کیا نہیں آپ نے ان سے فرمایا کیا تم اس بات کو پسند کرتی ہو کہ خدائے تعالیٰ تم کو آگ کے دوکنگن پہنائے ؟ انہوں نے عرض کیا نہیں۔ آپ نے فرمایا تو پھر ان کی زکوۃ ادا کیا کرو۔ (ترمذی)\n¥ترجمہ حدیث 6:\nحضرت سمرہ بن جندب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام ہم کو حکم فرمایا کر تے تھے کہ ہم تجارت کے لیے تیار کی جانے والی چیزوں کی زکوۃ نکالا کریں۔ (ابو داود)\n¥ترجمہ حدیث 7:\nحضرت موسیٰ بن طلحہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہمارے پاس حضرت معاذ بن جبل رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کا وہ خط موجود ہے جسے حضور نے انہیں بھیجا تھا۔ روای نے کہا کہ حضور نے معاذ بن جبل کو حکم فرمایا تھا کہ وہ گیہوں، جو، انگور اور کھجور کی پیدوار میں(مسلمانوں سے ) زکوۃ وصول کریں۔ (شرح السنۃ، مشکوۃ)", "roman": "Tarjumah Hadees 1: Hazrat Ibn Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo shakhs Maal hasil kare toh us par us waqt tak Zakaat nahi jab tak ke us par ek saal na guzar jaye. (Tirmidhi). Tarjumah Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo shakhs sone ya chandi ke shar'i Nisaab ka Maalik ho aur woh us ka haq yani Zakaat na ada kare toh Qayamat ke din us ke liye us sone aur chandi ki salein banayi jayengi aur unhein aag mein tapaya jayega. Phir un aatishin salon se us ke pehlu, peshani aur peeth ko daga jayega aur jab woh thandi ho jayegi toh phir Dozakh ki aag mein tapa kar daga jayega aur hamesha isi tarah hota rahega. (Muslim). Tarjumah Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alaihi wa Sallam ne farmaya ke jis shakhs ko Allah Ta'ala ne Maal ata kiya toh us ne us ki Zakaat nahi ada ki toh us ke Maal ko Qayamat ke din ganje saanp ki shakal mein tabdeel kar diya jayega jis ke sar par do chattiyan hongi, woh saanp us ke gale mein tauq bana kar daal diya jayega phir woh saanp us ki baachhein pakdega aur kahega ke main tera Maal hoon, main tera khazana hoon. Is ke baad Huzoor ne (Parah 4 Ruku 9 ki) Aayat-e-Kareema tilawat ki 'Wala yahsabannallazina' ilakh yani aur jo log bukhal karte hain us cheez mein jise Allah Ta'ala ne unhein apne fazl se ata ki (toh anjam-e-kaar) hargiz use apne liye achha na samjhein balki woh un ke liye bura hai, anqareeb woh Maal ke jis mein bukhal kiya tha Qayamat ke din un ke gale ka tauq hoga. (Bukhari). Tarjumah Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke tumhara khazana Qayamat ke din ek ganja saanp banega. Us ka Maalik us se bhagega aur woh saanp us ko dhoondta phirega. Yahan tak ke us ko pale ga aur us ki ungliyon ko luqma banayega. (Ahmad). Tarjumah Hadees 5: Hazrat Amr Bin Shu'aib Radiyallahu Anhu apne walid se aur woh apne dada se riwayat karte hain ke do Auratain Rasoolullah Sallallahu Alaihi wa Sallam ki khidmat mein hazir huin aur un ke hathon mein sone ke do kangan thay. Aap ne un se poochha kya tum in ki Zakaat deti ho? Unhon ne arz kiya nahi. Aap ne un se farmaya kya tum is baat ko pasand karti ho ke Allah Ta'ala tum ko aag ke do kangan pehnaye? Unhon ne arz kiya nahi. Aap ne farmaya toh phir in ki Zakaat ada kiya karo. (Tirmidhi). Tarjumah Hadees 6: Hazrat Samurah Bin Jundab Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam hum ko Hukm farmaya karte thay ke hum Tijarat ke liye tayyar ki jaane wali cheezon ki Zakaat nikala karein. (Abu Dawood). Tarjumah Hadees 7: Hazrat Musa Bin Talhah Radiyallahu Anhu ne farmaya ke hamare paas Hazrat Mu'adh Bin Jabal Radiyallahu Anhu ka woh khat maujood hai jise Huzoor ne unhein bheja tha. Rawi ne kaha ke Huzoor ne Mu'adh Bin Jabal ko Hukm farmaya tha ke woh gehoon, jau, angoor aur khajoor ki paidawar mein (Musalmanon se) Zakaat wasool karein. (Sharh-us-Sunnah, Mishkat).", "explanation": "¥انتباہ:\n (۱)… زکوۃ کے سلسلہ میں مالک ِ نصاب وہ شخص ہے جو ساڑھے باون تولے چاندی یا ساڑھے سات تولہ سونے کا مالک ہو یا ان میں سے کسی ایک کی قیمت کے سامانِ تجارت کا مالک ہو اور مملوکہ چیزیں حاجت ِ اصلیہ سے زائد اور دین سے فارغ ہوں۔ ([1])\n (۲)…زکوۃ کی ادائیگی میں تاخیر کرنے والا گنہگا ر مردود الشہادۃ ہے ۔ ([2])\n اور فتاویٰ عالمگیری جلد اول مصری ص:۱۶۰ میں ہے : ’’ تَجِبُ عَلَی الْفَوْرِ عِنْدَ تَمَامِ الْحَوْلِ حَتَّی یَأْثَمَ بِتَأْخِیرِہِ مِنْ غَیْرِ عُذْرٍ ‘‘۔ ([3])\n (۳)…زکوۃ کا روپیہ مردہ کی تجہیز و تکفین یا مسجد و مدرسہ کی تعمیر میں نہیں لگایا جاسکتا۔ جیسا کہ فتاویٰ عالمگیری جلد اول مصری ص:۱۷۶میں ہے :’’ لَا یَجُوزُ أَنْ یَبْنِیَ بِالزَّکَاۃِ الْمَسْجِدَ وَکَذَا الحجِّ وَکُلُّ مَا لَا تَمْلِیکَ فِیہِ وَلَا یَجُوزُ أَنْ یُکَفَّنَ بِہَا مَیِّتٌ وَلَا یُقْضَی بِہَا دَیْنُ الْمَیِّتِ کَذَا فِی التَّبْیِینِ ملخصاً ‘‘۔ ([4])\n (۴)…مالِ زکوۃ اگر مسجد اور مدرسہ وغیرہ کی تعمیر میں صَرف کرنا چاہیں تو اس کا طریقہ یہ ہے کہ کسی غریب آدمی کو دے دیں پھر وہ صرف کرے تو ثواب دونوں کو ملے گا۔ ([5]) (رد المحتار، بہار شریعت)\n (۵)…وہابیہ زمانہ کہ توہین خداو تنقیص شانِ رسالت کرتے ہیں جن کو اَکابر علمائے حرمین طیبین نے بالاتفاق کافر و مرتد فرمایا ہے اگرچہ وہ اپنے آپ کو مسلمان کہیں انہیں زکوۃ دینا حرام اور سخت حرام ہے اور اگر دی تو ہر گز ادا نہ ہوگی۔ ([6])(بہار شریعت)\n (۶)…گیہوں ، جَو ، جوار ، باجرہ ، دھان اور ہرقسم کے غلّے ، السی، کسم ، اخروٹ ، بادام اور ہر قسم کے میوے ، روئی، پھول ، گنا ، خربز، تربز، کھیرا ، ککڑی ، بینگن اور ہر قسم کی ترکاریاں سب میں عشر واجب ہے ۔ تھوڑا پیدا ہو یا زیادہ ۔ ([7])(عالمگیر ی، بہار شریعت)\n (۷)…جو کھیت بارش یا نہر نالے کے پانی سے سیراب کیا جائے ، اس میں عشر یعنی دسواں حصہ واجب ہے ۔ اور جس کی آب پاشی چرسے یا ڈول سے ہو اس میں نصف عشر یعنی پیدوار کا بیسواں حصہ واجب ہے ۔ اور اگر پانی خرید کر آب پاشی کی جب بھی بیسواں حصہ واجب ہے ([8])۔ (درمختار، ردالمحتار)\n (۸)…جس چیز میں عُشر یا نصف عشر واجب ہوا اس میں کل پیداوار کا عشر یا نصف عشر دیا جائے گا۔ کھیتی کے اخراجات یعنی ہل، بیل حفاظت کرنے والے اور کام کرنے والوں کی اُجرت یا بیج وغیرہ کی قیمت ان میں سے کوئی خرچ بھی عشر میں منہا نہیں کیا جائے گا۔ ([9]) (درمختار، بہارشریعت)\n------------------\n[1] مالک نصاب کی یہ تعریف صرف اموال باطنہ کے لحاظ سے ہے ۔ ۱۲منہ\n[2] ’’بہارِ شریعت‘‘، ج۱، ص ۸۷۴، ’’ الفتاوی الھندیۃ ‘‘، کتاب الزکاۃ ، ج ۱، ص ۱۷۰.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الزکاۃ ، الباب الأول فی تفسیر الزکاۃ إلخ ، ج ۱، ص ۱۷۰.\n[4] ’’ الفتاوی الھندیۃ ‘‘، کتاب الزکاۃ ، الباب السابع فی المصارف ، ج ۱، ص ۱۸۸.\n[5] ’’بہارشریعت‘‘، ج۱، ص ۸۹۰، ’’ رد المحتار ‘‘ ، کتاب الزکاۃ ، مطلب فی زکاۃ ثمن إلخ ، ج ۳، ص ۲۲۷.\n[6] ’’بہارشریعت‘‘، ج۱، ص ۹۳۳.\n[7] ’’بہارشریعت‘‘، ج۱، ص ۹۱۸، ’’ الفتاوی الھندیۃ ‘‘، کتاب الزکاۃ ، الباب السادس فی زکاۃ الزرع والثمار ، ج ۱، ص ۱۸۶.\n[8] کنویں اور ٹیوب ویل سے سیراب کرنے کا بھی یہی حکم ہے ۔ (تابش)۔ ’’ الدر المختار ورد المحتار ‘‘، کتاب الزکاۃ ، باب العشر ، ج ۳، ص ۳۱۶.\n[9] ’’بہارشریعت‘‘، ج۱، ص۹۱۸، ’’ الدر المختار ‘‘، کتاب الزکاۃ ، باب العشر ، ج ۳، ص ۳۱۷، ."}, {"id": 7809, "bookId": 14, "volNo": "1", "hadithNo": 41, "chapter": "صدقۂ فطر کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ عُمَرَ قَالَ فَرَضَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ زَکَاۃَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ شَعِیرٍ عَلَی الْعَبْدِ وَالْحُرِّ وَالذَّکَرِ وَالْأُنْثَی وَالصَّغِیرِ وَالْکَبِیرِ مِنَ الْمُسْلِمِینَ وَأَمَرَ بِہَا أَنْ تُؤَدَّی قَبْلَ خُرُوجِ النَّاسِ إِلَی الصَّلَاۃِ‘‘۔ \nحدیث 2:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ فِی آخِرِ رَمَضَانَ أَخْرِجُوا صَدَقَۃَ صَوْمِکُمْ فَرَضَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ہَذِہِ الصَّدَقَۃَ صَاعًا مِنْ تَمْرٍ أَوْ شَعِیرٍ أَوْ نِصْفَ صَاعٍ مِنْ قَمْحٍ عَلَی کُلِّ حُرٍّ أَوْ مَمْلُوکٍ ذَکَرٍ أَوْ أُنْثَی صَغِیرٍ أَوْ کَبِیرٍ‘‘۔ \nحدیث 3:\n’’عَنْ عَبْدِ اللّٰہ بْنِ ثَعْلَبَۃَ أَوْ ثَعْلَبَۃَ بْنِ عَبْدِ اللّٰہ بْنِ أَبِی صُغَیْرٍ عَنْ أَبِیہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صَاعٌمِنْ بُرٍّ أَوْ قَمْحٍ عَلَی کُلِّ اثْنَیْنِ صَغِیرٍ أَوْ کَبِیرٍ حُرٍّ أَوْ عَبْدٍ ذَکَرٍ أَوْ أُنْثَی أَمَّا غَنِیُّکُمْ فَیُزَکِّیہِ اللّٰہ وَأَمَّا فَقِیرُکُمْ فَیَرُدُّ عَلَیْہِ أَکْثَرَ مِمَّا أَعْطَاہُ‘‘۔ \nحدیث 4:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ فَرَضَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ زَکَاۃَ الْفِطْرِ طُہْرَ الصّیَامِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَۃً لِلْمَسَاکِینِ‘‘۔ \nحدیث 5:\n’’عَنْ عَمْرِو بْنِ شُعَیْبٍ عَنْ أَبِیہِ عَنْ جَدِّہِ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بَعَثَ مُنَادِیًا فِی فِجَاجِ مَکَّۃَ أَلَا إِنَّ صَدَقَۃَ الْفِطْرِ وَاجِبَۃٌ عَلَی کُلِّ مُسْلِمٍ ذَکَرٍ أَوْ أُنْثَی حُرٍّ أَوْ عَبْدٍ صَغِیرٍ أَوْ کَبِیرٍ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضر ت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے واجب ٹھہرا یا صدقۂ فطرکو غلام ، آزاد ، مرد ، عورت، بچے ، او ر بوڑھے ہر مسلمان پر ، ایک صاع جو یا کھجور ، اور حکم فرمایا کہ نماز (عید)کے لیے نکلنے سے پہلے اس کو ادا کیا جائے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابنِ عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے رمضان کے آخر میں لوگوں سے فرمایا کہ تم لوگ اپنے روزوں کا صدقہ ادا کرو۔ کیونکہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے اس صدقہ کو ہر مسلمان پر مقرر فرمایا ہے ۔ خواہ وہ آزاد ہو یا غلام، مرد ہو یا عورت ، چھوٹا ہو یا بڑا، ہر ایک کی طرف سے ایک صاع کھجور یا جَو یا نصف صاع گیہوں۔ (ابوداود، نسائی)\n¥ترجمہ حدیث 3:\nحضرت عبد اللّٰہ بن ثعلبہ یا ثعلبہ بن عبد اللّٰہ بن ابوصغیر اپنے والد سے روایت کرتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ایک صاع گیہوں دو آدمی کیطرف سے کافی ہے خواہ وہ بالغ ہو یا نابالغ ، آزاد ہوں یا غلام، مرد ہوں یا عورت۔ خدائے تعالیٰ اس کی بدولت تمہارے غنی کو پاک کرتا ہے اور فقیر کو اس سے زیادہ دیتا ہے جتنا کہ اس نے دیا۔ (ابوداود)\n¥ترجمہ حدیث 4:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے صدقۂ فطر اس لیے مقرر فرمایا تاکہ لغو اور بے ہودہ کلام سے روزہ کی طہارت ہوجائے اور دوسری طرف مساکین کے لیے خوراک ہوجائے ۔ (ابوداود)\n¥ترجمہ حدیث 5:\nحضرت عمر و بن شعیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا پنے باپ سے اور و ہ اپنے دادا سے روایت کرتے ہیں کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے ایک شخص کو بھیجا کہ مکہ شریف کی گلیوں میں اعلان کردے کہ صدقۂ فطر ہر مسلمان پر واجب ہے خواہ وہ مرد ہو یا عورت، آزاد ہو یا غلام ، نابالغ ہو یا بالغ۔ (ترمذی)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne Wajib thehraya Sadaqah-e-Fitr ko ghulam, azaad, mard, aurat, bachay, aur burhay har Musalman par, ek sa'a jau ya khajoor, aur hukm farmaya ke Namaz (Eid) ke liye nikalne se pehle is ko ada kiya jaye. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhum ne Ramazan ke aakhir mein logon se farmaya ke tum log apne rozon ka Sadaqah ada karo. Kyunke Rasoolullah Sallallahu Alaihi Wasallam ne is Sadaqah ko har Musalman par muqarrar farmaya hai. Khwah woh azaad ho ya ghulam, mard ho ya aurat, chota ho ya bara, har ek ki taraf se ek sa'a khajoor ya jau ya nisf sa'a gehun. (Abu Dawood, Nasai). Tarjuma Hadees 3: Hazrat Abdullah Bin Sa'labah ya Sa'labah Bin Abdullah Bin Abu Sagheer apne walid se riwayat karte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke ek sa'a gehun do shakhs ki taraf se kaafi hai khwah woh Baaligh ho ya Nabaaligh, azaad hon ya ghulam, mard hon ya aurat. Khuda-e-Ta'ala is ki badaulat tumhare ghani ko Paak karta hai aur Faqeer ko is se zyada deta hai jitna ke us ne diya. (Abu Dawood). Tarjuma Hadees 4: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne Sadaqah-e-Fitr is liye muqarrar farmaya taake laghw aur behuda kalam se roza ki Taharat hojaye aur dusri taraf Miskeen ke liye khoraak hojaye. (Abu Dawood). Tarjuma Hadees 5: Hazrat Amr Bin Shuaib Radiyallahu Anhu apne baap se aur woh apne dada se riwayat karte hain ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne ek shakhs ko bheja ke Makkah Shareef ki galiyon mein elaan karde ke Sadaqah-e-Fitr har Musalman par Wajib hai khwah woh mard ho ya aurat, azaad ho ya ghulam, Nabaaligh ho ya Baaligh. (Tirmidhi).", "explanation": "¥انتباہ:\n (۱)… صدقۂ فطر مالکِ نصاب پر واجب ہے کہ اپنی طرف سے اور اپنے چھوٹے بچوں کی طرف سے نکالے جب کہ بچہ مالکِ نصاب نہ ہو اور اگر ہو تو بچہ کا صدقہ اسی کے مال سے ادا کیا جائے ۔ ([1]) (درمختار، بہارشریعت)\n (۲)… صدقۂ فطر کے مسئلے میں مالکِ نصاب وہ شخص ہے جو ساڑھے باون تولہ چاندی یا ساڑھے سات تولہ سونا کا مالک ہو۔ یا ان میں سے کسی ایک کی قیمت کا سامانِ تجارت یا سامان غیر تجارت کا مالک ہو اور مملوکہ چیزیں حاجت اصلیہ سے زائد ہوں۔\n (۳)…صدقۂ فطر واجب ہونے کے لیے روزہ رکھنا شرط نہیں، اگر کسی عذر مثلاً سفر ، مرض ، بڑھاپے کی وجہ سے یا معاذ اللّٰہ بلا عذر روزہ نہ رکھا جب بھی واجب ہے ۔ ([2]) (بہارشریعت)\n اور جیسا کہ ردالمحتار جلد دوم ص:۷۶میں ہے : ’’ تَجِبُ الْفِطْرَۃُ وَإِنْ أَفْطَرَ عَامِدًا ‘‘۔ پھر دو سطر کے بعد ہے : ’’ مَنْ أَفْطَرَ لِکِبَرٍ أَوْ مَرَضٍ أَوْ سَفَرٍ یَلْزَمُہُ صَدَقَۃُ الْفِطْرِ ‘‘۔ ([3])\n (۴)…اگر باپ غریب ہو یا مرگیا ہو تو دادا پر اپنے غریب یتیم پوتے ، پوتی کی طرف سے صدقۂ فطر دینا واجب ہے ۔ درمختار باب صدقۃالفطر میں ہے : ’’ وَالْجَدُّ کَالْأَبِ عِنْدَ فَقْدِہِ أَوْ فَقْرِہِ ‘‘۔ ([4])\n (۵)…گیہوں، جو ، کھجور اور منقّٰی کے علاوہ اگر کسی دوسری چیز سے فطرہ ادا کرنا چاہیں مثلاً چاول، باجرہ اور کوئی غلہ تو آدھے صاع گیہوں یا ایک صاع جو کی قیمت کا لحاظ کرنا ہوگا۔ ([5]) (بہارشریعت)\n (۶)…عید کے دن طلوعِ فجر کے بعد عیدگاہ جانے سے پہلے صدقہ فطر نکالنا مستحب ہے ۔ فتاویٰ عالمگیری جلد اول ص:۱۸۰میں ہے :’’ وَالْمُسْتَحَبُّ لِلنَّاسِ أَنْ یُخْرِجُوا الْفِطْرَۃَ بَعْدَ طُلُوعِ الْفَجْرِ یَوْمَ الْفِطْرِ قَبْلَ الْخُرُوجِ إلَی الْمُصَلَّی کَذَا فِی الْجَوْہَرَۃِ النَّیِّرَۃِ ‘‘۔ ([6])\n (۷)…ماہِ رمضان اور رمضان سے پیشتر صدقۂ فطر ادا کرنا جائز ہے ۔ فتاوی عالمگیری جلد اول مصری ص:۱۷۹میں ہے : ’’ وَإِنْ قَدَّمُوہَا عَلَی یَوْمِ الْفِطْرِ جَازَ وَلَا تَفْضِیلَ بَیْنَ مُدَّۃٍ وَمُدَّۃٍ وَہُوَ الصَّحِیحُ ‘‘۔ ([7]) اور درمختار میں ہے : ’’ صَحَّ أَدَاؤُہَا إذَا قَدَّمَہُ عَلَی یَوْمِ الْفِطْرِ أَوْ أَخَّرَہُ ‘‘۔ ([8])\n (۸)…صاع کا وزن تین سو اکیاون ۳۵۱ روپیہ بھر ہے یعنی انگریزی سیر سے چار سیر چھ چھٹا نک ایک روپیہ بھر۔ اور نصف صاع ایک سو ساڑھے پچھتر روپیہ بھر ہے یعنی دو سیر تین چھٹانک آٹھ آنہ بھر۔ اس لیے کہ صاع وہ پیمانہ ہے جس میں آٹھ رطل اناج آئے ۔\n شرح وقایہ جلد اول ص:۲۳۹میں ہے : ’’ اَلصَّاعُ کَیْلٌ یَسَعُ فِیہِ ثَمَانِیَۃ أَرْطَالٍ ‘‘۔ ([9])\n اور ایک رطل نصف مَن ہے ۔ شامی جلد دوم ص:۷۹میں ہے : ’’ وَالرِّطْلُ نِصْفُ مَنٍّ ‘‘۔ ([10])\n توصاع وہ پیمانہ ہوا کہ جس میں چار من اناج آئے ۔ ’’ مَن‘‘ کو ’’مُد‘‘ بھی کہتے ہیں۔ جیسا کہ ردالمحتار جلد دوم ص:۷۹پر ہے ۔ ’’ الْمُدُّ وَالْمَنُّ سَوَاء کُلٌّ مِنْہُمَا رُبْعُ صَاعٍ ‘‘۔ ([11])\n اور مَن جس کو مُد بھی کہتے ہیں چالیس استار کا ہوتا ہے اور ہر استارساڑھے چار مثقال ، تو ہر مَن ایک سو اسی مثقال ہوا۔ شرح وقا یہ جلد اول ص:۲۴۰میں ہے : ’’ إِنَّ الْمَنَّ أَرْبَعُوْنَ أَسْتَاراً وَالْاَسْتَارُ أَرْبَعَۃُ مَثَاقِیْلَ وَنِصْفُ مِثْقَالٍ فَالْمَنُّ مِءَۃٌ وَّثَمَانُوْنَ مِثْقَالًا ‘‘۔ ([12])\n تو صاع وہ پیمانہ ہوا کہ جس میں ( ۴ مَن x۱۸۰ مثقال= ۷۲۰ مثقال) سات سو بیس مثقال اناج آئے ۔ پھر اناج ہلکے بھاری ہر طرح کے ہوتے ہیں۔ صاع کی تقدیر میں کس اناج کا اعتبار ہے ؟ تو بعض آئمہ نے ماش وعدس یعنی مسور اور اُرد کا اعتبا رکیا ہے ۔ اور صدر الشریعہ صاحبِ شرح وقایہ نے فرمایا کہ ماش وعدس گیہوں سے بھاری ہوتے ہیں لہذا وہ پیمانہ کہ جس میں آٹھ رطل یعنی ۷۲۰ سات سو بیس مثقال ماش وعدس آئے گا چھوٹا ہوگا اور وہ پیمانہ کہ جس میں ۷۲۰ سات سو بیس مثقال گیہوںآئے بڑا ہوگا۔ لہذا زیادہ احتیاط اس میں ہے کہ گیہوں کا اعتبار کیا جائے ۔ صدرالشریعہ رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ کی عبارت یہ ہے :\n ’’ اَلْمَاشُ أَثْقلُ مِن الحِنطَۃِ وَالحنطَۃُ مِنَ الشَّعِیْرِفَالْمِکْیَالُ الَّذِی یَمْلأ بِثَمَانِیَۃ أَرْطَالٍ مِن المج یَمْلأ بِأَقَلَّ مِنْ ثَمَانِیَۃِ أَرْطَالٍ مِنَ الْحِنْطَۃِ الجیدۃِ الْمُکْتَنِزَۃِ فَالأَحوطُ فِیہِ أَن یَقدرَ الصَّاع بِثَمَانیۃ أَرْطَالٍ مِنَ الْحِنْطۃ الجیدۃِ ‘‘([13]) ( شرح وقایہ ، جلد اول ، ص ۲۳۹)\n اورچونکہ گیہوں جَو سے بھاری ہوتا ہے لہذا وہ پیمانہ کہ جس میں آٹھ رطل یعنی سات سو بیس مثقال جَو آئے بڑا ہوگا۔ اسی لیے علامہ ابن عابدین شامی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے صاحبِ شرح وقایہ کی اس احتیاط کو ذکر کرکے فرمایا کہ سب سے زیادہ احتیاط یہ ہے کہ جَو کا اعتبار کیا جائے بلکہ یہ بھی تحریر فرمایا کہ بعض علماء نے حاشیہ زیلعی سے نقل کیا ہے کہ حرم شریف مکہ معظمہ کے مشائخ موجودین و سابقین کا عمل اور فتوی اسی پر ہے کہ صاع کی تقدیر میں جَو کا اعتبار کیا جائے ۔\n جیسا کہ ردالمحتار جلد دوم ص:۸۰پر ہے : ’’ وَلَکِنْ عَلَی ہَذَا الْأَحْوَطِ تَقْدِیرُہُ بِالشَّعِیرِ وَلِہَذَا نَقَلَ بَعْضُ الْمُحَشِّینَ عَنْ حَاشِیَۃِ الزَّیْلَعِیِّ لِلسَّیِّدِ مُحَمَّد أَمِینٍ مِیرْغَنِیٍّ أَنَّ الَّذِی عَلَیْہِ مَشَایِخُنَا بِالْحَرَمِ الشَّرِیفِ الْمَکِّیِّ وَمَنْ قَبْلَہُمْ مِنْ مَشَایِخِہِمْ وَبِہِ کَانُوا یُفْتُونَ تَقْدِیرُہُ بِثَمَانِیَۃِ أَرْطَالٍ مِنْ الشَّعِیرِ وَلَعَلَّ ذَلِکَ لِیَحْتَاطُوا فِی الْخُرُوجِ عَنِ الْوَاجِبِ بِیَقِینٍ لِمَا فِی مَبْسُوطِ السَّرَخْسِیِّ مِنْ أَنَّ الْأَخْذَ بِالِاحْتِیَاطِ فِی بَابِ الْعِبَادَاتِ وَاجِبٌ ا ہـ فَإِذَا قُدِّرَ بِذَلِکَ فَہُوَ یَسَعُ ثَمَانِیَۃَ أَرْطَالٍ مِنَ الْعَدَسِ وَمِنَ الْحِنْطَۃِ وَیَزِیدُ عَلَیْہَا أَلْبَتَّۃَ بِخِلَافِ الْعَکْسِ فَلِذَا کَانَ تَقْدِیرُ الصَّاعِ بِالشَّعِیرِ أَحْوَطَ ‘‘۔ ([14])\n خلاصہ کلام یہ ہے صاع وہ پیمانہ ہے کہ جس میں ۷۲۰ سات سو بیس مثقال جَو آئیں اسی میں سب سے زیادہ احتیاط ہے اور یہی حرم شریف مکہ معظمہ کے مشائخ کا معمول و مفتی بہ ہے اور مثقال کا وزن ساڑھے چار ماشہ ہے تو صاع و ہ پیمانہ ہوا کہ جس میں ( ۷۲۰ مثقال x ــــ ۱ ۲ ۴ =۳۲۴۰) سات سو بیس مثقال یعنی تین ہزار دو سو چالیس ماشے جَو آئیں۔ پھر چونکہ بارہ ماشے کا تولہ ہوا ہے تو صاع وہ پیمانہ ہوا کہ جس میں (۳۲۴۰ ماشے ÷ ۱۲=۲۷۰ تولے ) تین ہزار دو سو چالیس ماشے یعنی ۲۷۰ تولے جَو آئیں۔ اور چونکہ ایک روپیہ کا وزن سوا گیارہ ماشے ہوتا ہے اس لیے صاع وہ پیمانہ ہوا کہ جس میں (۳۲۴۰ ماشے ÷ ــــ ۱ ۴ ۱۱ماشے = ۲۸۸ روپیہ بھر) بتیس سو چالیس ماشے یعنی دو سو اٹھاسی روپیہ بھر جَو آئیں۔ اور نصف صاع وہ پیمانہ ہو ا کہ جس میں ایک سو چوالیس روپیہ بھر سے زیادہ آئے گا۔ پھر چونکہ گیہوں جَو سے بھاری ہوتا ہے تو جس پیمانہ میں ایک سو چوالیس روپیہ بھر جَو آئے گا اسی پیمانہ میں گیہوں ایک سو چوالیس روپیہ بھر سے زیادہ آئے گا۔\n اعلی حضرت امام احمد ر ضا فاضل بریلوی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے اس کا تجربہ کیا تو وہ پیمانہ کہ جس میں ایک سو چوالیس روپیہ بھر جَو آئے اسی پیمانہ میں ــــ ۲۱ ۱۷۵ ایک سو پچھتر روپیہ اٹھنی بھر گیہوں آئے ۔ فتاویٰ رضویہ جلد اول لاہوری ص: ۱۴۵ میں ہے کہ فقیر نے ۲۷ رمضان المبارک ۱۳۲۷ھ کو نیم صاع شعیری کا تجربہ کیا جو ٹھیک چار رطل جَو کا پیمانہ تھا اس میں گیہوں برابر ہموار مسطح بھر کر تولے تو ایک سو چوالیس روپیہ بھر جَو کی جگہ ایک سو پچھتر روپیہ آٹھ آنہ بھر گیہوںآئے ۔ ([15]) تو نصف صاع گیہوں صدقہ فطر کا وزن ایک سو پچھتر روپیہ آٹھ آنہ بھر ہوا جو انگریزی سیر سے دو سیر تین چھٹانک اور آٹھ آنے بھر ہے اس لیے کہ انگریزی سیر اسی روپیہ بھر ہے یعنی پورے پچھتر تولے کا ہے (منظر الفتاویٰ) اور نئے پیمانے سے نصف صاع گیہوں کا وزن ۲ کلو گرام ـــــــ ۴۶۱۶۰۱۲۳ گرام یعنی دو کلو اور تقریبا ۴۷ گرام ہوگا کیونکہ اسی روپیہ بھر کا سیر نو سو تینتیس گرام کا ہوتا ہے ۔ یہیں سے یہ بات متحقق ہوگئی اعلٰحضرت فاضل بریلوی رضی اللّٰہ المولیٰ تعالیٰ عنہ کا مسلک غایت احتیاط اور اعلیٰ درجہ تحقیق پرمبنی ہے ۔\n------------------\n[1] ’’ الدر المختار ورد المحتار ‘‘، باب صدقۃ الفطر ، ج ۳، ص ۳۶۷.’’بہارِ شریعت‘‘ ، ج۱، ص ۹۳۶۔ \n[2] ’’بہار شریعت‘‘، ج۱، ص ۹۳۶، ’’ رد المحتار ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر ، ج ۳، ص ۳۶۷.\n[3] ’’ رد المحتار ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر ، ج ۳، ص ۳۶۷.\n[4] ’’ الدر المختار ‘‘، کتاب الزکاۃ ، باب صدقۃالفطر ، ج ۳، ص ۳۶۸.\n[5] ’’بہار شریعت‘‘، ج۱، ص ۹۳۹، ’’ الدر المختار ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر ، ج ۳، ص ۳۷۳.\n[6] ’’ الفتاوی الھندیۃ ‘‘، کتاب الزکاۃ ، الباب الثامن فی صدقۃ الفطر ، ج ۱، ص ۱۹۲.\n[7] ’’ الفتاوی الھندیۃ ‘‘، کتاب الزکاۃ ، الباب الثامن فی صدقۃ الفطر ، ج ۱، ص ۱۹۲.\n[8] ’’ الدر المختار ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر ، ج ۳، ص ۳۷۶.\n[9] ’’ شرح الوقایۃ ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر فی البر وغیرہ ، ص ۳۰۰.\n[10] ’’ رد المحتار ‘‘، کتاب الزکاۃ ، مطلب فی تحریرالصاع والمد والمن والرطل ، ج ۳، ص ۳۷۳.\n[11] ’’ رد المحتار ‘‘ ، کتاب الزکاۃ ، مطلب فی تحریر الصاع والمد والمن والرطل ، ج ۳، ص ۳۷۳.\n[12] ’’ شرح الوقا یۃ ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر فی البر وغیرہ ، ص ۳۰۱.\n[13] ’’ شرح الوقایۃ ‘‘، کتاب الزکاۃ ، باب صدقۃ الفطر فی البر وغیرہ ، ص ۳۰۰.\n[14] ’’ رد المحتار ‘‘، کتاب الزکاۃ ، مطلب فی مقدار الفطرۃ بالمد الشامی ، ج ۳، ص ۳۷۶.\n[15] ’’ سنن أبی داود ‘‘، کتاب الوصایا ، باب ما جاء فی کراھیۃ إلخ ، الحدیث : ۲۸۶۶، ج ۳، ص ۱۵۵."}, {"id": 7810, "bookId": 14, "volNo": "1", "hadithNo": 42, "chapter": "سخی اور بخیل کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی سَعِیدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَأَنْ یَتَصَدَّقَ الْمَرْءُ فِی حَیَاتِہِ بِدِرْہَمٍ خَیْرٌ لَہُ مِنْ أَنْ یَتَصَدَّقَ بِمِءَۃٍ عِنْدَ مَوْتِہِ‘‘۔ \nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ السَّخِیُّ قَرِیبٌ مِنْ اللّٰہ قَرِیبٌ مِنَ الْجَنَّۃِ قَرِیبٌ مِنْ النَّاسِ بَعِیدٌ مِنَ النَّارِ وَالْبَخِیلُ بَعِیدٌ مِنَ اللّٰہ بَعِیدٌ مِنَ الْجَنَّۃِ بَعِیدٌ مِنَ النَّاسِ قَرِیبٌ مِنَ النَّارِ وَلَجَاہِلٌ سَخِیٌّ أَحَبُّ إِلَی اللّٰہ مِنْ عَابِدٍ بَخِیلٍ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی بَکْرِنِ الصِّدِّیقِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَدْخُلُ الْجَنَّۃَ خِبٌّ وَلَا بَخِیلٌ وَلَا مَنَّانٌ‘‘۔ \nحدیث 4:\n’’عَنْ أَبِی سَعِیدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ خَصْلَتَانِ لَا تَجْتَمِعَانِ فِی مُؤْمِنٍ اَلْبُخْلُ وَسُوءُ الْخُلُقِ‘‘۔ \nحدیث 5:\n’’عَنْ أَبِی ہُرَیْرَۃَ أَنَّہُ سَمِعَ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ إِنَّ ثَلاثَۃً فِی بَنِی إِسْرَاءِیلَ أَبْرَصَ وَأَقْرَعَ وَأَعْمَی فَأَرَادَ اللّٰہ أَنْ یَبْتَلِیَہُمْ فَبَعَثَ إِلَیْہِمْ مَلَکًا فَأَتَی الْأَبْرَصَ فَقَالَ أَیُّ شَیْئٍ أَحَبُّ إِلَیْکَ قَالَ لَوْنٌ حَسَنٌ وَجِلْدٌ حَسَنٌ وَیَذْہَبُ عَنِّی الَّذِی قَدْ قَذِرَنِی النَّاسُ قَالَ فَمَسَحَہُ فَذَہَبَ عَنْہُ قَذَرُہُ وَأُعْطِیَ لَوْنًا حَسَنًا وَجِلْدًا حَسَنًا قَالَ فَأَیُّ الْمَالِ أَحَبُّ إِلَیْکَ قَالَ الْإِبِلُ أَوْ قَالَ الْبَقَرُ شَکَّ إِسْحَقُ إِلَّا أَنَّ الْأَبْرَصَ أَوِ الْأَقْرَعَ قَالَ أَحَدُہُمَا الْإِبِلُ وَقَالَ الْآخَرُ الْبَقَرُ قَالَ فَأُعْطِیَ نَاقَۃً عُشَرَاءَ فَقَالَ بَارَکَ اللّٰہ لَکَ فِیہَا قَالَ فَأَتَی الْأَقْرَعَ فَقَالَ أَیُّ شَیْئٍ أَحَبُّ إِلَیْکَ قَالَ شَعَرٌ حَسَنٌ و َیَذْہَبُ عَنِّی ہَذَا الَّذِی قَدْ قَذِرَنِی النَّاسُ قَالَ فَمَسَحَہُ فَذَہَبَ عَنْہُ قَالَ وَأُعْطِیَ شَعرًا حَسَنًا قَالَ فَأَیُّ الْمَالِ أَحَبُّ إِلَیْکَ قَالَ الْبَقَرُ فَأُعْطِیَ بَقَرَۃً حَامِلًا قَالَ بَارَکَ اللّٰہ لَکَ فِیہَا قَالَ فَأَتَی الْأَعْمَی فَقَالَ أَیُّ شَیْئٍ أَحَبُّ إِلَیْکَ قَالَ أَنْ یَرُدَّ اللّٰہ إِلَیَّ بَصَرِی فَأُبْصرَ بِہِ النَّاسَ قَالَ فَمَسَحَہُ فَرَدَّ اللّٰہ إِلَیْہِ بَصَرَہُ قَالَ فَأَیُّ الْمَالِ أَحَبُّ إِلَیْکَ قَالَ الْغَنَمُ فَأُعْطِیَ شَاۃً وَالِدًا فَأُنْتِجَ ہَذَانِ وَوَلَّدَ ہَذَا قَالَ فَکَانَ لِہَذَا وَادٍ مِنَ الْإِبِلِ وَلِہَذَا وَادٍ مِنَ الْبَقَرِ وَلِہَذَا وَادٍ مِنَ الْغَنَمِ قَالَ ثُمَّ إِنَّہُ أَتَی الْأَبْرَصَ فِی صُورَتِہِ وَہَیْءَتِہِ فَقَالَ رَجُلٌ مِسْکِینٌ قَدْ انْقَطَعَتْ بِیَ الْحِبَالُ فِی سَفَرِی فَلَا بَلَاغَ لِی الْیَوْمَ إِلَّا بِاللّٰہ ثُمَّ بِکَ أَسْأَلُکَ بِالَّذِی أَعْطَاکَ اللَّوْنَ الْحَسَنَ وَالْجِلْدَ الْحَسَنَ وَالْمَالَ بَعِیرًا أَتَبَلَّغُ عَلَیْہِ فِی سَفَرِی فَقَالَ الْحُقُوقُ کَثِیرَۃٌ فَقَالَ لَہُ کَأَنِّی أَعْرِفُکَ أَلَمْ تَکُنْ أَبْرَصَ یَقْذَرُکَ النَّاسُ فَقِیرًا فَأَعْطَاکَ اللّٰہ فَقَالَ إِنَّمَا وَرِثْتُ ہَذَا الْمَالَ کَابِرًا عَنْ کَابِرٍ فَقَالَ إِنْ کُنْتَ کَاذِبًا فَصَیَّرَکَ اللّٰہ إِلَی مَا کُنْتَ قَالَ وَأَتَی الْأَقْرَعَ فِی صُورَتِہِ فَقَالَ لَہُ مِثْلَ مَا قَالَ لِہَذَا وَرَدَّ عَلَیْہِ مِثْلَ مَا رَدَّ عَلَی ہَذَا فَقَالَ إِنْ کُنْتَ کَاذِبًا فَصَیَّرَکَ اللّٰہ إِلَی مَا کُنْتَ قَالَ وَأَتَی الْأَعْمَی فِی صُورَتِہِ وَہَیْءَتِہِ فَقَالَ رَجُلٌ مِسْکِینٌ وَابْنُ سَبِیلٍ انْقَطَعَتْ بِیَ الْحِبَالُ فِی سَفَرِی فَلَا بَلَاغَ لِی الْیَوْمَ إِلَّا بِاللّٰہ ثُمَّ بِکَ أَسْأَلُکَ بِالَّذِی رَدَّ عَلَیْکَ بَصَرَکَ شَاۃً أَتَبَلَّغُ بِہَا فِی سَفَرِی فَقَالَ قَدْ کُنْتُ أَعْمَی فَرَدّ اللّٰہ إِلَیَّ بَصَرِی فَخُذْ مَا شِئْتَ وَدَعْ مَا شِئْتَ فَوَاللّٰہ لَا أَجْہَدُکَ الْیَوْمَ شَیْءًا أَخَذْتَہُ لِلَّہِ فَقَالَ أَمْسِکْ مَالَکَ فَإِنَّمَا ابْتُلِیتُمْ فَقَدْ رضِیَ عَنْکَ وَسخِطَ عَلَی صَاحِبَیْکَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوسعید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ انسان کا اپنی زندگی کے ایام میں ایک درہم صدقہ کرنا مرنے کے وقت سو درہم صدقہ کرنے سے بہتر ہے ۔ (ابوداود)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ سخی اللّٰہ تعالیٰ سے قریب ہے جنت سے قریب ہے لوگوں سے قریب ہے اور دوزخ سے دور ہے اور بخیل اللّٰہ تعالیٰ سے دور ہے جنت سے دور ہے لوگوں سے دور ہے اور جہنم سے قریب ہے اور جاہل سخی خدا کے نزدیک عبادت گزار بخیل سے کہیں بہتر ہے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت ابوبکر صدیق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ مکار اور بخیل جنت میں داخل نہ ہوں گے اور نہ وہ شخص جو خیرات دے کر احسان جتائے ۔ (ترمذی)\n¥ترجمہ حدیث 4:\nحضرت ابو سعید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ مومن میں دو باتیں یعنی بخل اور بدخلقی جمع نہیں ہوتی۔ (ترمذی)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ انہوں نے حضور علیہ الصلاۃ والسلام کو یہ فرماتے ہوئے سُنا ہے کہ بنی اسرائیل میں تین شخص تھے ایک کوڑھی دوسرا گنجا اور تیسرا اندھا ، اللّٰہ تعالیٰ نے ان کا امتحان لینا چاہا اور ان کی طرف ایک فرشتہ کو بھیجا۔ فرشتہ سب سے پہلے کوڑھی کے پاس آیا۔ اور پوچھا تجھے سب سے زیادہ کون سی چیز پسند ہے اس نے کہا اچھا رنگ اور خوبصورت جلد اور اس عیب کا دور ہوجانا جس کے سبب لوگ مجھ سے نفرت کرتے ہیں۔ حضور نے فرمایا کہ یہ سن کر فرشتے نے اس کے جسم پر ہاتھ پھیرا اور اس کا کوڑھ زائل ہوگیا اور اس کے جسم کا ر نگ نکھر گیا اور جلد خوش رنگ ہوگئی اس کے بعد فرشتہ نے کہا تجھ کو کس قسم کا مال پسند ہے ؟ اس نے اونٹ کہا یا گائے ( حدیث کے راوی حضرت اسحاق کو شک ہے کہ اس نے اونٹ کہا یا گائے ) بہرحال کوڑھی اور گنجے میں سے ایک نے اونٹ بتلائے اور دوسرے نے گائیں۔ حضور نے فرمایا کہ اس کی خواہش کے مطابق اس کو حاملہ اونٹنیاں دی گئیں اور فرشتہ نے اس کو یہ دعا دی کہ خدا تیرے لیے ان میں برکت عطا فرمائے ۔ حضور نے فرمایا کہ اس کے بعد فرشتہ گنجے کے پاس آیا اور پوچھا تجھ کو کون سی چیز زیادہ پسند ہے اس نے کہا خوبصورت بال اور اس عیب کا دور ہوجانا جس کے سبب سے لوگ مجھ سے نفرت کرتے ہیں یعنی گنجا پن۔ حضور نے فرمایا کہ فرشتہ نے اس کے سر پر ہاتھ پھیر ا اس کا گنجا پن زائل ہوگیا اور خوبصورت بال اسے عطا کیے گئے ۔ پھر فرشتہ نے اس سے پوچھاتجھ کو کون سا مال پسند ہے اس نے کہا گائیں ، چنانچہ اس کو حاملہ گائیں عطا کردی گئیں اور فرشتہ نے اس کو دعا د ی کہ خدا تیرے اس مال میں برکت دے ۔ حضور فرماتے ہیں کہ اس کے بعد فرشتہ اندھے کے پاس گیا اور پوچھاتجھ کو کون سی چیز بہت پسند ہے ؟ اس نے کہا کہ اللّٰہ تعالیٰ میری بینائی مجھ کو واپس کردے تاکہ میں اپنی آنکھوں سے لوگوں کو دیکھوں ۔ حضور فرماتے ہیں کہ فرشتہ نے اس کی آنکھوں پر ہاتھ پھیرا اور خدا نے اس کی بینائی اس کو مرحمت فرمادی پھر فرشتہ نے اس سے پوچھاکس قسم کا مال تجھ کو پسند ہے ؟ اس نے کہا بکریاں چنانچہ اس کو زیادہ بچے دینے والی بکریاں دے دی گئیں۔ پس ان تینوں کے مال میں خدا نے برکت دی ا ور کوڑھی اور گنجے کے اونٹوں اور گائیوں سے جنگل بھر گئے ۔ اور اندھے کی بکریوں کے ریوڑ وادیوںمیں نظر آنے لگے ۔ حضور فرماتے ہیں کہ اس کے بعد فرشتہ کوڑھی کی صورت میں اس کوڑھی کے پا س پہنچا؟۔ اور کہا کہ میں ایک مسکین آدمی ہوں، میرا وسیلہ سفر مفقود ہے اب منزل مقصود تک پہنچنا خدا کی مہربانی اور تیری مدد سے ہوسکتا ہے ۔ پس میں تجھ سے اس کی ذات کا وسیلہ دے کر جس نے تجھ کو اچھا ر نگ اچھی جلد اور مال دیا ہے ایک اونٹ مانگتا ہوں کہ اس کے ذریعہ منزل مقصود تک پہنچ جاؤں۔ کوڑھی نے اس کے جواب میں کہا میرے اوپر بہت سے حقوق ہیں ( اتنی گنجائش نہیں ہے کہ میں تیری کچھ مدد کرسکوں) فرشتے نے اس کے جواب میں کہا میں گویا تجھ کو پہچانتا ہوں تو وہی کوڑھی ہے جس سے لوگ نفرت کرتے تھے اور تو فقیر تھا۔ خدا نے تجھے مال دیا ۔ کوڑھی نے کہا یہ مال مجھ کونسلاً بعد نسل ٍ اپنے خاندان سے (وراثت) میں ملا ہے ۔ فرشتہ نے کہا اگر تو جھوٹا ہے تو خدا تجھ کو پھر ویسا ہی کردے جیسا کہ تو پہلے تھا اس کے بعد حضور نے فرمایا کہ پھر فرشتہ گنجے کی صورت میں اُسی گنجے کے پاس آیا اور اس سے بھی وہی کہا جو کوڑھی سے کہا تھا اور اس نے بھی وہی جواب دیا جو کوڑھی نے جواب دیا تھا تو فرشتے نے کہا اگر تو جھوٹا ہے تو خدا تجھ کو ویسا ہی کردے جیسا کہ تو پہلے تھا۔ پھر حضور نے فرمایا کہ اس کے بعد فرشتہ اندھے کے پاس آیا اور کہا کہ میں ایک مرد مسکین اور مسافر ہوں میرا سامانِ سفر جاتا رہا، بس اب منزل مقصود تک پہنچنا خدا کی عنایت سے پھر تیرے ذریعہ ممکن ہے تو میں تجھ سے اس ذات کا واسطہ دے کر جس نے تجھ کو دوبارہ بینائی بخشی ہے ایک بکری مانگتا ہوں کہ اس کے ذریعہ اپنا سفر پورا کرلوں۔ اندھے نے یہ سن کر کہا بے شک میں اندھا تھا خدا نے میری بینائی مجھ کو واپس بخشی پس تجھ کو جس قدر چاہیے لے جا اور جس قدر تیرا جی چاہے چھوڑ جا۔ قسم ہے خدا کی آج میں تجھ کو تکلیف نہیں دوں گا اس چیز کو واپس کرنے کی جو تو لے گا۔ فرشتے نے یہ سن کر کہا تو اپنا مال اپنے پاس رکھ تم لوگوں کا امتحان لیا گیا تھا۔ خدا تجھ سے راضی اور خوش ہوا۔ اور تیرے ساتھیوں سے خدائے تعالیٰ نار اض ہوا۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Abu Saeed Khudri Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke insaan ka apni zindagi ke ayyam mein ek dirham Sadaqah karna marne ke waqt sau dirham Sadaqah karne se behtar hai. (Abu Dawood). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke sakhi Allah Ta'ala se qareeb hai, Jannat se qareeb hai, logon se qareeb hai aur dozakh se door hai aur bakheel Allah Ta'ala se door hai, Jannat se door hai, logon se door hai aur Jahannam se qareeb hai aur jaahil sakhi Khuda ke nazdeek ibadat guzar bakheel se kahin behtar hai. (Tirmidhi). Tarjuma Hadees 3: Hazrat Abu Bakr Siddiq Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke makkar aur bakheel Jannat mein dakhil na honge aur na woh shakhs jo khairaat de kar ehsaan jataye. (Tirmidhi). Tarjuma Hadees 4: Hazrat Abu Saeed Khudri Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke Momin mein do baatein yani bukhal aur badkhulqi jama nahi hotin. (Tirmidhi). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu kehte hain ke unhon ne Rasoolullah Sallallahu Alaihi Wasallam ko ye farmate hue suna hai ke Bani Israel mein teen shakhs thay, ek korhi, dusra ganja aur teesra andha. Allah Ta'ala ne un ka imtehan lena chaha aur un ki taraf ek farishta ko bheja. Farishta sab se pehle korhi ke paas aaya aur pucha tujhe sab se zyada kaun si cheez pasand hai? Us ne kaha achha rang aur khubsurat jild aur is aib ka door hojana jis ke sabab log mujh se nafrat karte hain. Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke ye sun kar farishtay ne us ke jism par haath phera aur us ka korh zail hogaya aur us ke jism ka rang nikhar gaya aur jild khush rang hogayi. Is ke baad farishtay ne kaha tujh ko kis qisam ka Maal pasand hai? Us ne unt kaha ya gaye (Hadees ke Raawi Hazrat Ishaq ko shak hai ke us ne unt kaha ya gaye). Baharhal korhi aur ganjay mein se ek ne unt batlaye aur dusre ne gayen. Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke us ki khwahish ke mutabiq us ko hamila untniyan di gayin aur farishtay ne us ko ye Dua di ke Khuda tere liye in mein barkat ata farmaye. Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke is ke baad farishta ganjay ke paas aaya aur pucha tujh ko kaun si cheez zyada pasand hai? Us ne kaha khubsurat Baal aur is aib ka door hojana jis ke sabab se log mujh se nafrat karte hain yani ganja pan. Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke farishtay ne us ke sar par haath phera, us ka ganja pan zail hogaya aur khubsurat Baal usay ata kiye gaye. Phir farishtay ne us se pucha tujh ko kaun sa Maal pasand hai? Us ne kaha gayen, chunancha us ko hamila gayen ata kardi gayin aur farishtay ne us ko Dua di ke Khuda tere is Maal mein barkat de. Rasoolullah Sallallahu Alaihi Wasallam farmate hain ke is ke baad farishta andhay ke paas gaya aur pucha tujh ko kaun si cheez bahut pasand hai? Us ne kaha ke Allah Ta'ala meri beenai mujh ko wapas karde taake main apni aankhon se logon ko dekhun. Rasoolullah Sallallahu Alaihi Wasallam farmate hain ke farishtay ne us ki aankhon par haath phera aur Khuda ne us ki beenai us ko marhamat farma di. Phir farishtay ne us se pucha kis qisam ka Maal tujh ko pasand hai? Us ne kaha bakriyan, chunancha us ko zyada bachay dene wali bakriyan de di gayin. Pas in teenon ke Maal mein Khuda ne barkat di aur korhi aur ganjay ke unton aur gayion se jangal bhar gaye aur andhay ki bakriyon ke rewar wadiyon mein nazar aane lage. Rasoolullah Sallallahu Alaihi Wasallam farmate hain ke is ke baad farishta korhi ki surat mein us korhi ke paas pahuncha aur kaha ke main ek Miskeen aadmi hun, mera waseela-e-safar mafqood hai, ab manzil-e-maqsood tak pahunchna Khuda ki meherbani aur teri madad se hosakta hai. Pas main tujh se is ki zaat ka waseela de kar jis ne tujh ko achha rang, achhi jild aur Maal diya hai ek unt mangta hun ke is ke zariye manzil-e-maqsood tak pahunch jaun. Korhi ne us ke jawab mein kaha mere upar bahut se huqooq hain (itni gunjaish nahi hai ke main teri kuch madad karsakun). Farishtay ne us ke jawab mein kaha main goya tujh ko pehchanta hun, tu wahi korhi hai jis se log nafrat karte thay aur tu Faqeer tha, Khuda ne tujhe Maal diya. Korhi ne kaha ye Maal mujh ko naslan ba'ad naslin apne khandan se (wirasat) mein mila hai. Farishtay ne kaha agar tu jhoota hai to Khuda tujh ko phir waisa hi karde jaisa ke tu pehle tha. Is ke baad Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke phir farishta ganjay ki surat mein usi ganjay ke paas aaya aur us se bhi wahi kaha jo korhi se kaha tha aur us ne bhi wahi jawab diya jo korhi ne jawab diya tha to farishtay ne kaha agar tu jhoota hai to Khuda tujh ko waisa hi karde jaisa ke tu pehle tha. Phir Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke is ke baad farishta andhay ke paas aaya aur kaha ke main ek mard Miskeen aur musafir hun, mera saman-e-safar jata raha, bas ab manzil-e-maqsood tak pahunchna Khuda ki inayat se phir tere zariye mumkin hai to main tujh se is zaat ka wasta de kar jis ne tujh ko dobara beenai bakhshi hai ek bakri mangta hun ke is ke zariye apna safar pura karlun. Andhay ne ye sun kar kaha beshak main andha tha, Khuda ne meri beenai mujh ko wapas bakhshi, pas tujh ko jis qadar chahiye le ja aur jis qadar tera jee chahe chor ja. Qasam hai Khuda ki aaj main tujh ko takleef nahi dunga is cheez ko wapas karne ki jo tu le ga. Farishtay ne ye sun kar kaha tu apna Maal apne paas rakh, tum logon ka imtehan liya gaya tha. Khuda tujh se raazi aur khush hua aur tere sathiyon se Khuda-e-Ta'ala naaraz hua. (Bukhari, Muslim).", "explanation": "*****"}, {"id": 7811, "bookId": 14, "volNo": "1", "hadithNo": 43, "chapter": "بھیک مانگنا کیسا", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا یَزَالُ الرَّجُلُ یَسْأَلُ النَّاسَ حَتَّی یَأْتِیَ یَوْمَ الْقِیَامَۃِ لَیْسَ فِی وَجْہِہِ مُضْغَۃُ لَحْمٍ۔\nحدیث 2:\n’’ عَنِ الزُّبَیْرِ بْنِ الْعَوَّامِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَأَنْ یَأْخُذَ أَحَدُکُمْ حَبْلَہُ فَیَأْتِیَ بِحُزْمَۃِ الْحَطَبِ عَلَی ظَہْرِہِ فَیَبِیعَہَا فَیَکُفَّ اللّٰہ بِہَا وَجْہَہُ خَیْرٌ لَہُ مِنْ أَنْ یَسْأَلَ النَّاسَ أَعْطَوْہُ أَوْ مَنَعُوہُ‘‘۔ \nحدیث 3:\n’’ عَنِ ابْنِ عُمَرَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ وَہُوَ یَذْکُرُ الصَّدَقَۃَ وَالتَّعَفُّفَ عَنِ الْمَسْأَلَۃِ۔ اَلْیَدُ الْعُلْیَا خَیْرٌ مِنَ الْیَدِ السُّفْلَی وَالْیَدُ الْعُلْیَا ہِیَ الْمُنْفِقَۃُ وَالسُّفْلَی ہِیَ السَّاءِلَۃُ ‘‘۔ \nحدیث 4:\n’’ عَنْ سَمُرَۃَ بْنِ جُنْدُبٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْمَسَاءِلُ کُدُوحٌ یَکْدَحُ بِہَا الرَّجُلُ وَجْہَہُ فَمَنْ شَاءَ أَبْقَی عَلَی وَجْہِہِ وَمَنْ شَاء تَرَکَہُ إِلَّا أَنْ یَسْأَلَ الرَّجُلُ ذَا سُلْطَانٍ أَوْ فِی أَمْرٍ لَا یَجِدُ مِنْہُ بُدًّا‘‘۔ (ابوداود، ترمذی)\nحدیث 5:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ سَأَلَ النَّاسَ أَمْوَالَہُمْ تَکَثُّرًا فَإِنَّمَا یَسْأَلُ جَمْرًا فَلْیَسْتَقِلَّ أَوْ لِیَسْتَکْثِرْ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عبد اللّٰہ بن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ آدمی ہمیشہ لوگوں سے بھیک مانگتا رہے گا یہاں تک کہ قیامت کے دن وہ اس حالت میں آئے گا کہ اس کے منہ پر گوشت کی بوٹی نہ ہوگی۔ یعنی نہایت بے آبرو ہو کر آئے گا۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت زبیر بن عوام رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلوۃو السلام نے فرمایا کہ تم میں سے جو شخص اپنی رسی لے اور لکڑیوں کا ایک گٹھا پیٹھ پر لاد کر لائے اوران کو بیچے اور اللّٰہ تعالیٰ بھیک مانگنے کی لذت سے اس کے چہرے کو بچائے تو یہ بہتر ہے اس بات سے کہ لوگوں سے بھیک مانگے ۔ اور وہ ا س کو دیں یا نہ دیں۔ (بخاری)\n¥ترجمہ حدیث 3:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم منبر پر تشریف فرما تھے ۔ صدقہ کا اور بھیک مانگنے سے بچنے کا ذکر کرتے ہوئے فرمایا کہ اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے ۔ اوپر والا ہاتھ خرچ کرنے والا ہے اور نیچے والا ہاتھ مانگنے والا ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\n حضرت سمرہ بن جندب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ بھیک مانگنا ایک قسم کی خراش ہے کہ آدمی بھیک مانگ کر اپنے منہ کو نوچتا ہے تو جو چاہے اپنے منہ پر اس خراش کو نمایاں کرے اور جو چاہے اس سے اپنا چہرہ محفوظ رکھے ۔ ہاں اگر آدمی صاحبِ سلطنت سے اپنا حق مانگے یا ایسے امر میں سوال کرے کہ اس سے چارہ کا ر نہ ہو تو جائز ہے ۔ (ابوداود، ترمذی)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص مال بڑھانے کے لیے لوگوں سے بھیک مانگتا ہے وہ گویا انگارہ مانگتا ہے توا س کو اختیار ہے کہ بہت مانگے یا کم مانگے ۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke aadmi hamesha logon se bheek mangta rahega yahan tak ke Qayamat ke din woh is halat mein aayega ke us ke munh par gosht ki Booti na hogi. Yani nihayat be-aabroo ho kar aayega. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Zubair Bin Awwam Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke tum mein se jo shakhs apni rassi le aur lakriyon ka ek gatha peeth par laad kar laye aur un ko beche aur Allah Ta'ala bheek mangne ki lazzat se us ke chehre ko bachaye to ye behtar hai is baat se ke logon se bheek mange. Aur woh us ko dein ya na dein. (Bukhari). Tarjuma Hadees 3: Hazrat Ibn Umar Radiyallahu Anhum se Riwayat hai ke Rasool-e-Kareem Sallallahu Alaihi Wasallam Mimbar par tashreef farma thay. Sadaqah ka aur bheek mangne se bachne ka zikr karte hue farmaya ke upar wala haath neeche wale haath se behtar hai. Upar wala haath kharch karne wala hai aur neeche wala haath mangne wala. (Bukhari, Muslim). Tarjuma Hadees 4: Hazrat Samurah Bin Jundab Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke bheek mangna ek qisam ki kharash hai ke aadmi bheek mang kar apne munh ko nochta hai to jo chahe apne munh par is kharash ko numayan kare aur jo chahe is se apna chehra mehfooz rakhe. Haan agar aadmi sahib-e-saltanat se apna haq mange ya aise amr mein Sawaal kare ke is se chara-e-kaar na ho to Jaiz hai. (Abu Dawood, Tirmidhi). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs Maal barhane ke liye logon se bheek mangta hai woh goya angara mangta hai to us ko ikhtiyar hai ke bahut mange ya kam mange. (Muslim).", "explanation": "¥انتباہ :\n (۱)… آج کل بہت سے لوگوں نے بھیک مانگنا اپنا پیشہ بنالیا ہے ۔ گھر میں ہزاروں روپے ہیں۔ ہل بیل والے ہیں کھیتی کرتے ہیں مگر بھیک مانگنا نہیں چھوڑتے ۔ حالانکہ ایسے لوگوں کو بھیک مانگنا حرام ہے ۔ اور ان کو بھیک دینے والے گنہ گار ہوتے ہیں: ’’ لِأَنَّ اللّٰہتَعَالَی قَالَ فِی الْقُرْآنِ الْمَجِیْدِ { لا تَعَاوَنُوا عَلَی الْإِثْمِ وَالْعُدْوَانِِِ }‘‘( پارہ ۶، رکوع ۵)۔\n (۲)…ڈھول، ہارمونیم، سارنگی بجانے والوں اور گانے والوں کو بھیک دینا منع ہے ۔\n اشعۃ اللمعات جلد دوم ص:۳۰ میں ہے : ’’ بناید داد سائلے را کہ طبل زدہ برور ہامی گردد ومطرب راکہ از ہمہ افحش ست ‘‘۔ ([1])\n (۳)…آج کل اکثر لوگ اندھے ، لولے ، لنگڑے ، اپاہج کو بھیک نہیں دیتے اور گانے والی، جوان نامحرم عورتوں سے گانا سنتے اور انہیں بھیک دیتے ہیں یہ سخت ناجائز اور حرام ہے ۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الزکاۃ ، باب من لا تحل لہ المسئلۃ ومن تحل لہ ، ج ۲، ص ۳۱."}, {"id": 7812, "bookId": 14, "volNo": "1", "hadithNo": 44, "chapter": "روزہ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا دَخَلَ رَمَضَانُ فُتِحَتْ أَبْوَابُ السَّمَآء وَفِيْ رِوَایَۃٍ فُتِحَتْ أَبْوَابُ الْجَنَّۃِ وَغُلِّقَتْ أَبْوَابُ جَہَنَّمَ وَسُلْسِلَتِ الشَّیَاطِینُ وَفِی رِوَایَۃٍ فُتحَتْ أَبْوَابُ الرَّحْمَۃِ ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ صَامَ رَمَضَانَ إِیمَانًا وَاحْتِسَابًا غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ وَمَنْ قَامَ رَمَضَان إِیمَانًا وَاحْتِسَابًا غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ وَمَنْ قَامَ لَیْلَۃَ الْقَدْرِ إِیْمَانًا وَّاِحْتِسَابًا غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَانَ أَوَّلُ لَیْلَۃٍ مِنْ شَہْرِ رَمَضَانَ صُفِّدَتِ الشَّیَاطِینُ وَمَرَدَۃُ الْجِنِّ وَغُلِّقَتْ أَبْوَابُ النَّارِ فَلَمْ یُفْتَحْ مِنْہَا بَابٌ وَفُتِّحَتْ أَبْوَابُ الْجَنَّۃِ فَلَمْ یُغْلَقْ مِنْہَا بَابٌ وَیُنَادِی مُنَادٍ یَا بَاغِیَ الْخَیْرِ أَقْبِلْ وَیَابَاغِیَ الشَّرِّ أَقْصِرْ وَلِلَّہِ عُتَقَاءُ مِنْ النَّارِ وَذَلکَ کُلّ لَیْلَۃٍ‘‘۔ \nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَتَاکُمْ رَمَضَانُ شَہْرٌ مُبَارَکٌ فَرَضَ اللّٰہ عَلَیْکُمْ صِیَامَہُ تُفْتَحُ فِیہِ أَبْوَابُ السَّمَاء وَتُغْلَقُ فِیہِ أَبْوَابُ الْجَحِیمِ وَتُغَلُّ فِیہِ مَرَدَۃُ الشَّیَاطِینِ لِلَّہِ فِیہِ لَیْلَۃٌ خَیْرٌ مِنْ أَلْفِ شَہْرٍ مَنْ حُرِمَ خَیْرَہَا فَقَدْ حُرِمَ‘‘۔ \nحدیث 5:\n’’عَنْ سلْمَانَ الْفَارِسِیِّ قَالَ خَطَبَنَا رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِیْ آخِرِ یَوْمٍ مِنْ شَعْبَانَ فَقَالَ یَا أَیُّہَا النَّاسُ قَدْ أَظَلَّکُمْ شَہْرٌ عَظِیْمٌ شَہْرٌ مُبَارَکٌ شَہْرٌ فِیْہِ لَیْلَۃٌ خَیْرٌ مِّنْ أَلْفِ شَہْرٍ جَعَلَ اللّٰہ صِیَامَہُ فَرِیْضَۃً وَقِیَامَ لَیْلہِ تَطَوُّعًا مَنْ تَقَرَّبَ فِیْہِ بِخَصْلَۃٍ مِّنَ الْخَیْرِ کَانَ کَمَنْ أَدَّی فَرِیْضَۃً فِیْمَا سِوَاہُ وَمَنْ أَدَّی فَرِیْضَۃً فِیْہِ کَانَ کَمَنْ أَدَّی سَبْعِیْنَ فَرِیْضَۃً فِیْمَا سِوَاہُ وَہُوَ شَہْر الصَّبْرِ وَالصَّبْرُ ثَوَابُہُ الْجَنَّۃ وَشَہْرُ الْمَوَاسَاۃِ وَشَہْرٌ یُزَادُ فِیْہِ رِزْقُ الْمُؤْمِنِ مَنْ فَطَّرَ فِیْہِ صَاءِمًا کَانَ لَہُ مَغْفِرَۃً لِذُنُوبِہِ وَعِتْقَ رَقْبَتِہِ مِنَ النَّارِ وَکَانَ لَہُ مِثْلُ أَجْرِہِ مِنْ غَیْرِ أَنْ یَنْقُصَ مِنْ أِجْرِہِ شَیْئٌ قُلْنَا یَا رَسُوْلَ اللّٰہ لَیْسَ کُلّنَا یَجِدُ مَا یُفَطِّرُ بِہِ الصَّاءِمَ فَقَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یُعْطِی اللّٰہ ہَذَا الثَّوَابَ مَنْ فَطَّرَ صَاءِمًا عَلَی مُذْقَۃِ لَبَنٍ أَوْ تَمْرَۃٍ أَوْ شَرْبَۃٍ مِنْ مَائٍ وَمَنْ أَشْبَعَ صَاءِمًا سَقَاہُ اللّٰہ مِنْ حَوْضِی شَرْبَۃً لَا یَظْمَأُ حَتَّی یَدْخُلَ الْجَنَّۃَ وَہُوَ شَہْرٌ أَوَّلُہُ رَحْمَۃٌ وَأَوْسَطُہُ مَغْفِرَۃٌ وَآخِرُہُ عِتْقٌ مِن النَّارِ وَمَنْ خَفَّفَ عَنْ مَمْلُوْکِہِ فِیْہِ غَفَرَ اللّٰہ لَہُ وَأَعْتَقَہُ مِنَ النَّارِ‘‘۔ \nحدیث 6:\n’’عَنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یُغْفَرلأُمَّتِہِ فِی آخِرِ لَیْلَۃٍ فِی رَمَضَانَ قِیلَ یَا رَسُولَ اللّٰہ أَہِیَ لَیْلَۃُ الْقَدْرِ قَالَ لَا وَلَکِنَّ الْعَامِلَ إِنَّمَا یُوَفَّی أَجْرہُ إِذَا قَضَی عَمَلَہُ‘‘۔ \nحدیث 7:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ ذَرَعَہُ الْقَیْءُ وَہُوَ صَاءِمٌ فَلَیْسَ عَلَیْہِ قَضَائٌ وَمَنْ اسْتَقَاء عَمْدًا فَلْیَقْضِ‘‘۔ \nحدیث 8:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ لَمْ یَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِہِ فَلَیْسَ لِلَّہِ حَاجَۃٌ فِی أَنْ یَدَعَ طَعَامَہُ وَشَرَابَہُ‘‘۔ \nحدیث 9:\n’’عَنْ سَلَمَۃَ بْنِ الْمُحَبِّقِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ کَانَ لَہُ حَمُولَۃٌ تَأْوِی إِلَی شِبَعٍ فَلْیَصُمْ رَمَضَانَ حَیْثُ أَدْرَکَہُ‘‘۔ \nحدیث 10:\n’’ عَنْ أَنَسِ بْنِ مَالِکٍ الکَعْبِی قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ وَضَعَ عَنْ الْمُسَافِرِ شَطْرَ الصَّلَاۃِ وَالصَّوْمَ عَنِ الْمُسَافِرِ وَعَنِ الْمُرْضِعِ وَالْحُبْلَی‘‘۔ \nحدیث 11:\n’’عَنْ أَبِی أَیُّوبَ الْأَنْصَارِیِّ أَنَّہُ حَدَّثَہُ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَہُ سِتًّا مِنْ شَوَّالٍ کَانَ کَصِیَامِ الدَّہْرِ‘‘۔ \nحدیث 12:\n’’عَنْ أَبِی قَتَادَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صِیَامُ یَوْمِ عَرَفَۃَ أَحْتَسِبُ عَلَی اللّٰہ أَنْ یُکَفِّرَ السَّنَۃَ الَّتِی قَبْلَہُ وَالسَّنَۃَ الَّتِی بَعْدَہُ‘‘۔ \nحدیث 13:\n’’ عَنْ حَفْصَۃَ قَالَتْ أَرْبَعٌ لَمْ یَکُنْ یَدَعُہُنَّ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صِیَامَ عَاشُورَاءَ وَالْعَشْرَ وَثَلاثَۃ أَیَّامٍ مِنْ کُلِّ شَہْرٍ وَرَکْعَتَانِ قَبْلَ الْفَجْرِ‘‘۔ \nحدیث 14:\n’’عَنْ أَبِی ذَرٍّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَا أَبَا ذَرٍّ إِذَا صُمْتَ مِنَ الشَّہْرِ ثَلَاثَۃَ أَیَّامٍ فَصُمْ ثَلاث عَشرَۃَ وَأَرْبَعَ عَشرَۃَ وَخَمْسَ عَشرَۃَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جب ماہِ رمضان شروع ہوتا ہے تو آسمان کے دروازے کھول دیئے جاتے ہیں اور ایک روایت میں ہے کہ جنت کے دروازے کھول دیئے جاتے ہیں اور دوز خ کے دروازے بند کردیئے جاتے ہیں اور شیاطین زنجیروں میں جکڑ دیئے جاتے ہیں اور ایک روایت میں ہے کہ رحمت کے دروازے کھول دیئے جاتے ہیں۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ جو شخص ایمان کے ساتھ ثواب کی امید سے روزہ رکھے گا توا س کے اگلے گناہ بخش دیئے جائیں گے اور جو ایمان کے ساتھ ثواب کی نیت سے رمضان کی راتوں میں قیام یعنی عبادت کرے گا توا س کے اگلے گناہ بخش دیئے جائیں گے اور جو ایمان کے ساتھ ثواب حاصل کرنے کی غرض سے شب قدر میں قیام کرے گا اس کے اگلے گناہ بخش دیئے جائیں گے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب ماہِ رمضان کی پہلی رات ہوتی ہے تو شیاطین اور سرکش جن قید کرلیے جاتے ہیں اور جہنم کے دروازے بند کردیئے جاتے ہیں۔ ( پھر رمضان بھر) ان میں سے کوئی دروازہ کھولا نہیں جاتا اور جنت کے دروازے کھول دیئے جاتے ہیں تو ان میں سے کوئی دروازہ بند نہیں کیا جاتا اور منادی پکارتا ہے کہ اے خیر کے طلب کرنے والے متوجہ ہو اور اے برائی کا ارادہ رکھنے والے برائی سے باز رہ، اور اللّٰہ بہت سے لوگوں کود وزخ سے آزاد کرتا ہے ۔ اور ہر رات ایسا ہوتا ہے ۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ رمضان آیا یہ برکت کا مہینہ ہے اللّٰہ تعالیٰ نے اس کے روزے تم پر فرض کیے ہیں۔ اس میں آسمان کے دروازے کھول دیئے جاتے ہیں اور دوزخ کے دروازے بند کردیئے جاتے ہیں اور سرکش شیاطین کو طوق پہنائے جاتے ہیں اور اس میں ایک رات ایسی ہے جو ہزار مہینوں سے افضل ہے ۔ جو اس کی برکتوں سے محروم رہا وہ بے شک محروم ہے ۔ (احمد، نسائی ، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت سلمان فارسی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے شعبان کے آخر میں وعظ فرمایا۔ اے لوگو تمہارے پاس عظمت والا، برکت والا مہینہ آیا۔ وہ مہینہ جس میں ایک رات ہزار مہینوں سے بہتر ہے اور اس کے روزے اللّٰہ تعالیٰ نے فرض کیے اور اس کی رات میں قیام کرنا(نماز پڑھنا) تطوع یعنی نفل قرار دیا ہے جو اس میں نیکی کا کوئی کام یعنی نفل عبادت کرے تو ایسا ہے جیسے اور مہینہ میں فرض ادا کیا۔ ا ور جس نے ایک فرض ادا کیا تو ایسا ہے جیسے اور دنوں میں ستر فرض ادا کیے ۔ یہ صبر کامہینہ ہے اور صبر کا ثواب جنت ہے اور یہ غم خواری کا مہینہ ہے اور اس مہینہ میں مومن کا رزق بڑھایا جاتا ہے جو اس میں روزہ دار کو افطار کرائے اس کے گناہوں کے لیے مغفرت ہے اور اس کی گردن دوزخ سے آزاد کردی جائے گی اور اس میں افطار کرانے والے کو ویسا ہی ثواب ملے گا جیسا روزہ رکھنے والے کو ملے گا بغیر اس کے کہ اس کے ثواب میں کچھ کمی واقع ہو۔ ہم نے عرض کیا یارسول اللّٰہ ! ہم میں کا ہر شخص وہ چیز نہیں پاتا جس سے روزہ افطار کرائے ۔ حضور نے فرمایا اللّٰہ تعالیٰ یہ ثواب اس شخص کو بھی دے گا جو ایک گھونٹ دودھ یا ایک کھجور یا ایک گھونٹ پانی سے افطار کرائے اور جس نے روزہ دار کو پیٹ بھر کر کھانا کھلایا اس کو اللّٰہ تعالیٰ میرے حوض سے سیراب کرے گا۔ کبھی پیاسا نہ ہوگا۔ یہاں تک کہ جنت میں داخل ہوجائے ۔ یہ وہ مہینہ ہے کہ ا س کا ابتدائی حصہ رحمت ہے اور اس کا درمیانی حصہ مغفرت ہے اور اس کا آخری حصہ جہنم سے آزادی ہے ۔ اور جو اپنے غلام پر اس مہینہ میں تخفیف کرے یعنی کام لینے میں کمی کردے تو اللّٰہ تعالیٰ اسے بخش دے گا اور جہنم سے آزاد فرمائے گا۔ (بیہقی)\n¥ترجمہ حدیث 6:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ رمضان کی اخیر رات میں اس امت کی مغفرت ہوتی ہے عرض کیا گیا وہ شبِ قدر ہے ؟ فرمایا نہیں۔ لیکن کام کرنے والوں کو اس وقت مزدوری پوری دی جاتی ہے جب وہ کام پورا کرلے ۔ (احمد)\n¥ترجمہ حدیث 7:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس شخص کو روزہ کی حالت میں خود بخود قے آجائے اس پر قضا واجب نہیں۔ ا ور جو قصداً قے کرے اس پر قضا واجب ہے ۔ (ترمذی، ابوداود)\n¥ترجمہ حدیث 8:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص( روزہ رکھ کر) بری بات کہنا اور اس پر عمل کرنا ترک نہ کرے تو خدائے تعالیٰ کو اس کی پر واہ نہیں کہ اس نے کھانا پینا چھوڑ دیا ہے ۔ (بخاری)\n¥ترجمہ حدیث 9:\nحضرت سلمہ بن محبق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس شخص کے پاس ایسی سواری ہو جو آرام سے منزل تک پہنچادے تو اس کو چاہیے کہ روزہ رکھے جہاں بھی رمضان آجائے ۔ (ابوداود)\n¥ترجمہ حدیث 10:\nحضرت انس بن مالک کعبی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اللّٰہ تعالیٰ نے (شرعی) مسافر سے آدھی نماز معاف فرمادی ( یعنی مسافر چار رکعت والی فرض نماز دو پڑھے ) اور مسافر، \nدودھ پلانے والی اور حاملہ عورت سے روزہ معاف کردیا ( یعنی ان لوگوں کو اجازت ہے کہ اس وقت روزہ نہ رکھیں بعد میں قضا کرلیں)۔ (ابوداود، ترمذی)\n¥ترجمہ حدیث 11:\nحضرت ابو ایوب انصاری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس نے رمضان کا روزہ رکھا پھر اس کے بعد چھ روزے شوال کے رکھے توا س نے گویا ہمیشہ روزہ رکھا۔ (مسلم)\n¥ترجمہ حدیث 12:\nحضرت ابو قتادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ مجھے خدائے تعالیٰ کی رحمت سے امید ہے کہ عرفہ کے دن کا روزہ ایک سال اگلے اور ایک سال پچھلے کا گناہ دور کردے گا۔ (مسلم)\n¥ترجمہ حدیث 13:\nحضرت حفصہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ چار چیزیں ہیںجنہیںحضور علیہ الصلاۃ والسلام نہیں چھوڑتے تھے ۔ عاشورہ کاروزہ۔ ذی الحجہ کے روزے (ایک سے نو تک) ہر مہینہ کے تین روزے دو رکعتیں فجر کی فرض سے پہلے ۔ (نسائی)\n¥ترجمہ حدیث 14:\nحضرت ابوذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ اے ابوذر! جب (کسی ) مہینہ میں تین دن روزہ رکھنا ہو تو تیرہ چودہ اور پندرہ تاریخ کو ( روزہ) رکھو۔ (ترمذی، نسائی)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab mah-e-Ramazan shuru hota hai to aasman ke darwaze khol diye jate hain aur ek Riwayat mein hai ke Jannat ke darwaze khol diye jate hain aur dozakh ke darwaze band kardiye jate hain aur shayateen zanjeeron mein jakar diye jate hain aur ek Riwayat mein hai ke rehmat ke darwaze khol diye jate hain. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs imaan ke sath sawab ki umeed se Roza rakhega to us ke agle gunah bakhsh diye jayenge aur jo imaan ke sath sawab ki niyat se Ramazan ki raton mein Qiyam yani ibadat karega to us ke agle gunah bakhsh diye jayenge aur jo imaan ke sath sawab hasil karne ki gharz se Shab-e-Qadr mein Qiyam karega us ke agle gunah bakhsh diye jayenge. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jab mah-e-Ramazan ki pehli raat hoti hai to shayateen aur sarkash jin qaid karliye jate hain aur Jahannam ke darwaze band kardiye jate hain. (Phir Ramazan bhar) in mein se koi darwaza khola nahi jata aur Jannat ke darwaze khol diye jate hain to in mein se koi darwaza band nahi kiya jata aur munadi pukarta hai ke ae khair ke talab karne wale mutawajjah ho aur ae burai ka irada rakhne wale burai se baaz reh, aur Allah bahut se logon ko dozakh se azaad karta hai. Aur har raat aisa hota hai. (Tirmidhi, Ibn Majah). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke Ramazan aaya ye barkat ka mahina hai, Allah Ta'ala ne is ke Roze tum par Farz kiye hain. Is mein aasman ke darwaze khol diye jate hain aur dozakh ke darwaze band kardiye jate hain aur sarkash shayateen ko tauq pehnaye jate hain aur is mein ek raat aisi hai jo hazar mahinon se afzal hai. Jo is ki barkaton se mehroom raha woh beshak mehroom hai. (Ahmad, Nasai, Mishkat). Tarjuma Hadees 5: Hazrat Salman Farsi Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne Sha'ban ke aakhir mein wa'az farmaya. Ae logo tumhare paas azmat wala, barkat wala mahina aaya. Woh mahina jis mein ek raat hazar mahinon se behtar hai aur is ke Roze Allah Ta'ala ne Farz kiye aur is ki raat mein Qiyam karna (Namaz parhna) tatau' yani nafl qarar diya hai, jo is mein neki ka koi kaam yani nafl ibadat kare to aisa hai jaise aur mahina mein Farz ada kiya. Aur jis ne ek Farz ada kiya to aisa hai jaise aur dinon mein sattar Farz ada kiye. Ye sabr ka mahina hai aur sabr ka sawab Jannat hai aur ye gham khwari ka mahina hai aur is mahina mein Momin ka rizq barhaya jata hai, jo is mein Roza dar ko Iftaar karaye us ke gunahon ke liye maghfirat hai aur us ki gardan dozakh se azaad kardi jayegi aur is mein Iftaar karane wale ko waisa hi sawab milega jaisa Roza rakhne wale ko milega baghair is ke ke us ke sawab mein kuch kami waqay ho. Hum ne arz kiya Ya Rasoolullah! Hum mein ka har shakhs woh cheez nahi pata jis se Roza Iftaar karaye. Rasoolullah Sallallahu Alaihi Wasallam ne farmaya Allah Ta'ala ye sawab us shakhs ko bhi dega jo ek ghunt Doodh ya ek khajoor ya ek ghunt pani se Iftaar karaye aur jis ne Roza dar ko pet bhar kar khana khilaya us ko Allah Ta'ala mere Hauz se sairab karega. Kabhi pyasa na hoga. Yahan tak ke Jannat mein dakhil hojaye. Ye woh mahina hai ke is ka ibtidai hissa rehmat hai aur is ka darmiyani hissa maghfirat hai aur is ka aakhri hissa Jahannam se azaadi hai. Aur jo apne ghulam par is mahina mein takhfeef kare yani kaam lene mein kami karde to Allah Ta'ala usay bakhsh dega aur Jahannam se azaad farmayega. (Baihaqi). Tarjuma Hadees 6: Hazrat Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Ramazan ki akhir raat mein is ummat ki maghfirat hoti hai, arz kiya gaya woh Shab-e-Qadr hai? Farmaya nahi. Lekin kaam karne walon ko us waqt mazdoori puri di jati hai jab woh kaam pura karle. (Ahmad). Tarjuma Hadees 7: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jis shakhs ko Roza ki halat mein khud ba khud qay aajaye us par Qaza Wajib nahi. Aur jo qasdan qay kare us par Qaza Wajib hai. (Tirmidhi, Abu Dawood). Tarjuma Hadees 8: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs (Roza rakh kar) buri baat kehna aur us par amal karna tark na kare to Khuda-e-Ta'ala ko is ki parwah nahi ke us ne khana peena chor diya hai. (Bukhari). Tarjuma Hadees 9: Hazrat Salamah Bin Muhabbaq Radiyallahu Anhu ne kaha Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jis shakhs ke paas aisi sawari ho jo aaram se manzil tak pahunchade to us ko chahiye ke Roza rakhe jahan bhi Ramazan aajaye. (Abu Dawood). Tarjuma Hadees 10: Hazrat Anas Bin Malik Ka'bi Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Allah Ta'ala ne (shar'i) musafir se aadhi Namaz maaf farma di (yani musafir char rakat wali Farz Namaz do parhe) aur musafir, Doodh pilane wali aur hamila aurat se Roza maaf kardiya (yani in logon ko ijazat hai ke us waqt Roza na rakhein ba'ad mein Qaza karlein). (Abu Dawood, Tirmidhi). Tarjuma Hadees 11: Hazrat Abu Ayyub Ansari Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jis ne Ramazan ka Roza rakha phir is ke ba'ad chhay Roze Shawwal ke rakhe to us ne goya hamesha Roza rakha. (Muslim). Tarjuma Hadees 12: Hazrat Abu Qatadah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke mujhe Khuda-e-Ta'ala ki rehmat se umeed hai ke Arafah ke din ka Roza ek saal agle aur ek saal pichle ka gunah door kardega. (Muslim). Tarjuma Hadees 13: Hazrat Hafsah Radiyallahu Anha ne farmaya ke char cheezein hain jinhein Rasoolullah Sallallahu Alaihi Wasallam nahi chorte thay. Aashurah ka Roza. Zil-Hajj ke Roze (ek se nau tak) har mahina ke teen Roze, do rakatein Fajr ki Farz se pehle. (Nasai). Tarjuma Hadees 14: Hazrat Abu Zar Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke ae Abu Zar! Jab (kisi) mahina mein teen din Roza rakhna ho to terah, chaudah aur pandrah tareekh ko (Roza) rakho. (Tirmidhi, Nasai).", "explanation": "¥شرح حدیث 1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ کشادہ شدن درہائے آسمان کنایت ست از پیاپے فرستادن رحمت وصعود اعمال بے مائع واجابت دعا ۔ وکشادہ شدن درہائے بہشت از بذل توفیق وحسن قبول وبستہ شدن درہائے دوزخ از تنزیہ نفوس روزہ داران از آلودگی فواحش و تخلص از بواعث معاصی وقمع شہوات ودر زنجیر کردن شیاطین از بستہ شدن طرف معاصی ووساوس ‘‘۔ ([1])\nیعنی آسمان کے دروازے کھول دیئے جانے کا مطلب ہے پے درپے رحمت کا بھیجا جانا ، اور بغیر کسی رکاوٹ کے بارگاہِ الٰہی میں اعمال کا پہنچنا اور دعا کا قبول ہونا اور جنت کے دروازے کھول دیئے جانے کا معنی ہے نیک اعمال کی توفیق اور حسنِ قبول عطا فرمانا۔ اور دوزخ کے دروازے بند کیے جانے کا مطلب ہے روزہ داروں کے نفوس کو ممنوعات شرعیہ کی آلودگی سے پاک کرنا اور گناہوں پر اُبھارنے والی چیزوں سے نجات پانا اور دل سے لذتوں کے حصول کی خواہش کا توڑنا اور شیاطین کو زنجیروں میں جکڑ دیئے جانے کا معنی ہے بُرے خیالات کے راستوں کا بند ہوجانا۔ (اشعۃ اللمعات، جلد دوم، ص ۷۲)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، الفصل الأول ، ج ۲، ص ۷۷.\n¥شرح حدیث 8:\nاس حدیث شریف کے تحت حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ:\n’’ ایںکنایت ست ازعدم قبول یعنی مقصود از ایجاب صوم وشرعیت آں ہمیں گرسنگی وتشنگی نیست بلکہ کسر شہوت واطفائے نائرہ نفسانیت است تانفس از امارگی برآید ومطمئنہ گردد ۔ ([1]) ( اشعۃ اللمعات ، جلد دوم ، ص ۸۵)\nیعنی مطلب یہ ہے کہ روزہ قبول نہ ہوگا اس لیے کہ روزہ کے مشروع اور واجب کرنے کا مقصد یہی بھوک اور پیاس نہیں ہے بلکہ لذتوں کی خواہشات کا توڑنا اور خودغرضی کی آگ کو بجھانا مقصود ہے تاکہ نفس خواہشات کی جانب راغب ہونے کی بجائے حکمِ الہی پر چلنے والا ہوجائے ۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، باب تنزیہ الصوم ، الفصل الأول ، ج ۲، ص ۹۰.\n¥شرح حدیث 10:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ افطار مرمرضع وحبلی را بر تقدیرے است کہ اگر زیاں کند بچہ را یا نفس ایشاں را ‘‘۔ ([1])\n( اشعۃ المعات جلد دوم ص ۹۴)\nیعنی دودھ پلانے والی اور حاملہ عورت کو روزہ نہ رکھنے کی رخصت صرف اس صورت میں ہے کہ بچہ کو یا خود اس کو روزہ سے نقصان پہنچے ۔ ( ورنہ رخصت نہیں ہے )\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، باب صوم المسافر ، الفصل الثانی ، ج ۲، ص ۱۰۰.\n¥شرح حدیث 12:\nواضح ہو کہ عرفہ کا روزہ میدانِ عرفات میں منع ہے ۔ ([1]) (بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص ۱۰۱۰.\n¥انتباہ :\n (۱)… یکم شوال اور ۱۰، ۱۱، ۱۲ ذی الحجہ کو روزہ رکھنا مکروہ تحریمی اور ناجائز ہے ۔ ([1])\n (طحطاوی، ص ۳۸۷، درمختار، ردالمحتار، ج ۲، ص۸۶)\n (۲)…احتلام ہوجانے یا ہمبستری کرنے کے بعد غسل نہ کیا اور اسی حالت میں پورا دن گزار دیا تو وہ نمازوں کے چھوڑ دینے کے سبب سخت گنہ گار ہوگا مگر روزہ ادا ہوجائے گا۔\n بحرالرائق جلد دوم ص:۲۷۳ میں ہے : ’’ لَوْ أَصْبَحَ جُنُبًا لَا یَضُرُّہُ کَذَا فِی الْمُحِیطِ ‘‘۔ ([2])\n اور فتاویٰ عالمگیری جلد اول مصری ص:۱۸۷میں ہے : ’’ وَمَنْ أَصْبَحَ جُنُبًا أَوِ احْتَلَمَ فِی النَّہَارِ لَمْ یَضُرَّہُ کَذَا فِی مُحِیطِ السَّرَخْسِیِّ ‘‘۔ ([3])\n (۳)… مریض کو مرض بڑھ جانے یا دیر میں اچھا ہونے یا تندرست کو بیمار ہوجانے کا گمان غالب ہو تو روزہ توڑنے کی اجازت ہے ۔ غالب گمان کی تین صورتیں ہیں۔ اس کی ظاہر نشانی پائی جاتی ہے ۔ یا اس شخص کا ذاتی تجربہ ہے یا کسی سُنی مسلمان طبیب حاذق مستور الحال یعنی غیر فاسق نے اس کی خبر دی ہو۔ اور اگر نہ کوئی علامت ہو نہ تجربہ، نہ اس قسم کے طبیب نے اسے بتایا بلکہ کسی کافر یا فاسق یا بدمذہب ڈاکٹر یا طبیب کے کہنے سے روزہ توڑ دیا تو کفارہ لازم آئے گا۔ ([4]) (رد المحتار ، جلد دوم ص ۱۲۰، بہار شریعت)\n (۴)…جو شخص رمضان میں بلا عذر علانیہ قصداً کھائے تو سلطان اسلام اسے قتل کردے ۔ ([5]) (شامی، بہار شریعت)\n (۵)…معتکف کے سوا دوسروں کو مسجدوں میں روزہ افطار کرنا کھانا پینا جائز نہیں۔ ([6]) (درمختار، فتاوی رضویہ)\n لہذا دوسرے لوگ اگر مسجدمیں افطار کرنا چاہتے ہیں تو اعتکاف کی نیت کرکے مسجد میں جائیں کچھ ذکر یا درود شریف پڑھنے کے بعد اب کھاپی سکتے ہیں مگر اس صورت میں بھی مسجد کا احترام ضروری ہے ۔ آج کل بمبئی وغیرہ کی اکثر مساجد میں بلکہ بعض دیہاتوں میں بھی افطار کے وقت مسجدوں کی بڑی بے حرمتی کرتے ہیں جو ناجائز اور حرام ہے ۔ امام اور متولیانِ مسجد کو اس امر پر توجہ کرنا ضروری ہے ورنہ قیامت کے دن ان سے سخت باز پرس ہوگی۔\n------------------\n[1] ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، کتاب الصوم ، فصل فی صفۃ الصوم وتقسیمہ ، ص ۶۴۰، ’’ الدر المختار ورد المحتار ‘‘، کتاب الصوم ، ج ۳، ص ۳۹۱.\n[2] ’’ البحر الرائق ‘‘، کتاب الصوم ، باب ما یفسد وما لا یفسدہ ، ج ۲، ص ۴۷۶.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصوم ، الباب الثالث فیما یکرہ للصائم وما لا یکرہ ، ج ۱، ص ۲۰۰.\n[4] ’’بہارِ شریعت‘‘، ج۱، ص۱۰۰۳، ’’ رد المحتار ‘‘، کتاب الصوم ، فصل فی العوارض ، ج ۳، ص ۴۶۳۔ ۴۶۴.\n[5] ’’بہارِ شریعت‘‘، ج۱، ص۹۸۸، ’’ رد المحتار ‘‘، کتاب الصوم ، باب ما یفسد الصوم وما لا یفسدہ ، مطلب فی الکفارۃ ، ج ۳، ص ۴۴۹.\n[6] ’’ الدر المختار ‘‘ ، کتاب الصوم ، باب الاعتکاف ، ج ۳، ص ۵۰۶، ’’ الفتاوی الرضویۃ ‘‘، ج ۸، ص ۹۲."}, {"id": 7813, "bookId": 14, "volNo": "1", "hadithNo": 45, "chapter": "رویت ہلال کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تَصُومُوا حَتَّی تَرَوْا الْہِلَالَ وَلَا تُفْطِرُوا حَتَّی تَرَوْہُ فَإِنْ غُمَّ عَلَیْکُمْ فَاقْدِرُوا لَہُ وَفِی رِوَایَۃٍ قَالَ الشَّہْرُ تِسْعٌ وَعِشْرُونَ لَیْلَۃً فَلَا تَصُومُوا حَتَّی تَرَوْہُ فَإِنْ غُمَّ عَلَیْکُمْ فَأَکْمِلُوا الْعِدَّۃَ ثَلَاثِینَ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ صُومُوا لِرُؤْیَتِہِ وَأَفْطِرُوا لِرُؤْیَتِہِ فَإِنْ غُمَّ عَلَیْکُمْ فَأَکْمِلُوا عِدَّۃَ شَعْبَانَ ثَلَاثِینَ‘‘۔\nحدیث 3:\n’’عَنْ ابْنِ عَبَّاسٍ قَالَ جَاءَ أَعْرَابِیٌّ إِلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ إِنِّی رَأَیْتُ الْہِلَالَ یَعْنِی ہِلَالَ رَمَضَانَ فَقَالَ أَتَشْہَدُ أَنْ لَا إِلَہَ إِلَّا اللّٰہ قَالَ نَعَمْ قَالَ أَتَشْہَدُ أَنَّ مُحَمَّدًا رَسُولُ اللّٰہ ( صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ) قَالَ نَعَمْ قَالَ یَا بِلَالُ أَذِّنْ فِی النَّاسِ أَنْ یَصُومُوا غَدًا ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جب تک چاند نہ دیکھ لو روزہ نہ رکھو۔ اور جب تک چاند نہ دیکھ لو افطار نہ کرو۔ اور اگر ابریا غبار ہونے کی وجہ سے چاند نظر نہ آئے تو ( تیس دن کی ) مقدار پوری کرلو۔ اور ایک روایت میں ہے کہ مہینہ کبھی انتیس دن کا ہوتا ہے پس تم جب تک چاند نہ دیکھ لو روزہ نہ رکھو اور اگر تمہارے سامنے ابر یا غبار ہوجائے تو تیس دن کی گنتی پوری کرلو۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ چاند دیکھ کر روزہ رکھنا شروع کر و اور چاند دیکھ کر افطار کرو۔ ا ور اگر ابر ہو تو شعبان کی گنتی تیس پوری کرلو۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ ایک اعرابی نے حضور کی خدمت میں حاضر ہو کر عرض کیا کہ میں نے رمضان کا چاند دیکھا ہے حضور نے فرمایا کیا تو گواہی دیتا ہے کہ اللّٰہ تعالیٰ کے سوا کوئی معبود نہیں، عرض کیا ہاں، فرمایا کیا تو گواہی دیتا ہے کہ محمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) اللّٰہ تعالیٰ کے رسول ہیں۔ اس نے کہا ہاں حضور نے ار شاد فرمایا اے بلال لوگوں میں اعلان کردو کہ کل روزہ رکھیں۔ (ابو داود، ترمذی، نسائی)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab tak chand na dekh lo Roza na rakho. Aur jab tak chand na dekh lo Iftaar na karo. Aur agar abr ya ghubar hone ki wajah se chand nazar na aaye to (tees din ki) miqdar puri karlo. Aur ek Riwayat mein hai ke mahina kabhi untees din ka hota hai pas tum jab tak chand na dekh lo Roza na rakho aur agar tumhare samne abr ya ghubar hojaye to tees din ki ginti puri karlo. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke chand dekh kar Roza rakhna shuru karo aur chand dekh kar Iftaar karo. Aur agar abr ho to Sha'ban ki ginti tees puri karlo. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke ek a'arabi ne Rasoolullah Sallallahu Alaihi Wasallam ki khidmat mein hazir ho kar arz kiya ke main ne Ramazan ka chand dekha hai, Rasoolullah Sallallahu Alaihi Wasallam ne farmaya kya tu Gawah deta hai ke Allah Ta'ala ke siwa koi Ma'bood nahi, arz kiya haan, farmaya kya tu Gawah deta hai ke Muhammad (Sallallahu Alaihi Wasallam) Allah Ta'ala ke Rasool hain. Us ne kaha haan, Rasoolullah Sallallahu Alaihi Wasallam ne irshad farmaya ae Bilal logon mein elaan kardo ke kal Roza rakhein. (Abu Dawood, Tirmidhi, Nasai).", "explanation": "¥شرح حدیث 1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ قول منجمین نامقبول ونامعتبر ست در شرع واعتماد برآں نہ تو ان کرد وآنحضرت صلی اللّٰہ علیہ وسلم واصحاب واتباع رضی اللّٰہ تعالی عنہم وسلف وخلف رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِم بداں عمل ننمودہ اند واعتبار نہ کردہ اند ‘‘۔ ([1])\n یعنی شرع میں نجومیوں کا قول نامقبول وغیر معتبر ہے ۔ اس پر بھروسہ نہیں کرسکتے ۔ اور حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ، صحابہ کرام و تابعین رضوان اللّٰہ تعالیٰ علیہم اجمعین، نیز سلف و خلف رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِم نے اس پر عمل نہیں کیا۔ اور نہ اعتبار فرمایا۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، باب رؤیۃ الھلال ، الفصل الأول ، ج ۲، ص ۸۲.\n¥شرح حدیث 3:\nحضرت شیخ عبدالحق محدث دہلوی رحمۃا للہ تعالیٰ علیہ فرماتے ہیں کہ:\n’’ دریں حدیث دلیل ست برآنکہ یک مرد مستور الحال یعنی آنکہ فسق او معلوم نہ باشد مقبول ست خبروے در ماہ رمضان وشرط نیست لفظ شہادت ‘‘۔ ([1])\nیعنی اس حدیث شریف سے ثابت ہوا کہ ایک مرد مستور الحال یعنی جس کا فاسق ہونا ظاہر نہ ہو اس کی خبر ماہ رمضان میں مقبول ہے لفظ شہادت کی شرط نہیں۔ (اشعۃ اللمعات، جلد دوم ، ص ۷۹)\n¥انتباہ:\n(۱) …چاند کے ثبوت کی چند صورتیں ہیں۔\n¥اوّل چاند کی خبر:\n ۲۹ شعبان کو مطلع صاف نہ ہو تو ایک مسلمان مرد یا عورت عادل یا مستور الحال کی خبر سے رمضان المبارک کا چاند ثابت ہو جائے گا اور مطلع صاف ہونے کی صورت میں باوصاف مذکورہ ایک شخص کاآبادی سے باہر کھلے میدان میں یا بلند مکان پر سے دیکھنا کافی ہے ورنہ ایک کثیر جماعت چاہیے جو اپنی آنکھ سے چاند کا دیکھنا بیان کرے باقی گیارہ مہینوں کے چاند کے لیے مطلع صاف نہ ہونے کی صورت میں دوعادلوں کی گواہی ضروری ہے اور مطلع صاف ہونے کی صورت میں اتنی بڑی جماعت درکار ہے جن کا جھوٹ پر متفق ہونا عقلاً مشکل ہو۔\n درمختار مع ردالمحتار جلد دوم، ص:۹۳ میں ہے : ’’ قُبِلَ بِلَا دَعْوَی وَبِلَا لَفْظِ أَشْہَدُ وَبِلَا حُکْمٍ وَمَجْلِسِ قَضَائٍ لِلصَّوْمِ مَعَ عِلَّۃٍ کَغَیْمٍ وَغُبَارٍ خَبَرُ عَدْلٍ أَوْ مَسْتُورٍ لَا فَاسِق اتِّفَاقًا ۔ ملخصاً ‘‘۔ ([2])\n پھر اسی کتاب کے ص :۹۵ پر ہے : ’’ قُبِلَ بِلَا عِلَّۃٍ جَمْعٌ عَظِیمٌ یَقَعُ الْعِلْمُ الشَّرْعِیُّ وَہُوَ غَلَبَۃُ الظَّنِّ بِخَبَرِہِمْ وَصَحَّحَ فِي الْأَقْضِیَۃِ الِاکْتِفَاءَ بِوَاحِدٍ إنْ جَاءَ مِنْ خَارِجِ الْبَلَدِ أَوْ کَانَ عَلَی مَکَان مُرْتَفِعٍ وَاخْتَارَہُ ظَہِیرُ الدِّینِ ‘‘۔ ([3])\n اور بحرالرائق جلد دوم ص:۲۶۹میں ہے : ’’ أَمَّا فِی ہِلَالِ الْفِطْرِ وَالْأَضْحَی وَغَیْرِہِمَا مِنْ الْأَہِلَّۃِ فَإِنَّہُ لَا یُقْبَلُ فِیہِ إلَّا شَہَادَۃُ رَجُلَیْنِ أَوْ رَجُلٍ وَامْرَأَتَیْنِ عُدُولٍ أَحْرَارٍ غَیْرِ مَحْدُودِینَ کَمَا فِی سَاءِرِ الْأَحْکَامِ ‘‘۔ ([4])\n¥دوم شہادۃ علی الشہادۃ :\n یعنی گواہوں نے چاند خود نہ دیکھا بلکہ دیکھنے والوں نے ان کے سامنے گواہی دی اور اپنی گواہی پر انہیں گواہ کیا تو اس طرح بھی چاند کا ثبوت ہوجاتا ہے ۔ جب کہ گواہان اصل حاضری سے معذور ہوں۔ اس کا طریقہ یہ ہے کہ گواہان اصل میں سے ہر ایک دو آدمیوں میں سے کہیں کہ میری اس گواہی پر گواہ ہوجاؤ کہ میں نے فلاں سنہ کے فلاں مہینہ کا چاند فلاں دن کی شام کو دیکھا۔ پھر ان گواہان فرع میں سے ہر ایک آکر یوں شہادت دیں کہ میں گواہی دیتا ہوں کہ فلاں بن فلاں اور فلاں بن فلاں نے مجھے اپنی اس گواہی پرگواہ کیا کہ انہوں نے فلاں سنہ کے فلاں مہینہ کا چاند فلاں دن کی شام کو دیکھا اور انہوں نے مجھ سے کہا کہ میری اس گواہی پر گواہ ہوجاؤ۔\n درمختار مع ردالمحتار جلد چہارم ص:۴۰۹ میں ہے : ’’ الشَّہَادَۃُ عَلَی الشَّہَادَۃِ مَقْبُولَۃٌ وَإِنْ کَثُرَتْ اسْتِحْسَانًا ‘‘۔ ([5])\n اورفتاویٰ عالمگیری جلد سوم مصری ص:۴۱۰میں ہے : ’’ وَیَنْبَغِی أَنْ یَذْکُرَ الْفَرْعُ اسْمَ الشَّاہِدِ الْأَصْلِ وَاسْمَ أَبِیہِ وَجَدِّہِ حَتَّی لَوْ تُرِکَ ذَلِکَ فَالْقَاضِی لَا یَقْبَلُ شَہَادَتَہُمَا ‘‘۔ ([6])\n¥سوم شہادۃ علی القضا:\n یعنی کسی دوسرے شہر میں قاضی شر ع یا مفتی کے سامنے چاند ہونے پر شہادتیں گزریں اور اس نے ثبوت ہلال کا حکم دیا۔ اس گواہی اور حکم کے وقت دو شاہد عادل دارالقضا میں موجود تھے ۔ انہوں نے یہاں آکر مفتی کے سامنے کہا کہ’’ ہم گواہی دیتے ہیں کہ ہمارے سامنے فلاں شہر کے فلاں مفتی کے پاس گواہیاں گزریں کہ فلاں ہلال کی رؤیت فلاں دن کی شام کوہوئی ہے اورمفتی نے ان گواہیوں پر ثبوت ِ ہلال فلاں روز کا حکم دیا تو اس طرح بھی چاند کا ثبوت ہوجاتا ہے ۔\n جیسا کہ فتاویٰ الامام الغزی ص :۶ اور فتح القدیر جلد دوم ص:۲۴۳ میں ہے : ’’ لَوْ شَہِدُوا أَنَّ قَاضِیَ بَلْدَۃِ کَذَا شَہِدَ عِنْدَہُ اثْنَانِ بِرُؤْیَۃِ الْہِلَالِ فِی لَیْلَۃِ کَذَا وَقَضَی بِشَہَادَتِہِمَا جَازَ لِہَذَا الْقَاضِی أَنْ یَحْکُمَ بِشَہَادَتِہِمَا لِأَنَّ قَضَاءَ الْقَاضِی حُجَّۃٌ وَقَدْ شَہِدُوا بِہِ کَذَا فِی شَرْحِ الْکَنْزِ ‘‘۔ ([7])\n¥چہارم استفاضہ : \n یعنی جس اسلامی شہر میں مفتی اسلام مرجع عوام و متبع الاحکام ہو کہ روزہ اور عیدین کے احکام اسی کے فتویٰ سے نافذ ہوتے ہوں۔ عوام خود عید و رمضان نہ ٹھہرالیتے ہوں وہاں سے متعدد جماعتیں آئیں اور سب بیک زبان خبردیں کہ وہاں فلاں دن چاند دیکھ کر روزہ ہوا یا عید کی گئی تو اس طرح بھی چاند کا ثبوت ہوجاتا ہے ۔ لیکن صرف بازاری افواہ اڑ جائے اور کہنے والے کا پتہ نہ ہو۔ پوچھنے پر جواب ملے کہ سنا ہے یا لوگ کہتے ہیں تو ایسی خبر ہر گز استفاضہ نہیں، نیز ایسا شہر کہ جہاں کوئی مفتی اسلام نہ ہو یا ہو مگر نااہل ہو یا محقق اور معتمد ہو۔ مگر وہاں کے عوام جب چاہتے ہیں عید و رمضان خود مقرر کرلیتے ہیں۔ جیسا کہ آج کل عام طور پر ہورہا ہے ۔ تو ایسے شہروں کی شہرت بلکہ تواتر بھی قابلِ قبول نہیں ہے ۔ ([8]) (فتاوی رضویہ، جلد چہارم ، ص ۵۵۳)\n اور جیسا کہ درمختار بحث رویت ہلال میں ہے : ’’ لَوْ اسْتَفَاضَ الْخَبَرُ فِی الْبَلْدَۃِ الْأُخْرَی لَزِمَہُمْ عَلَی الصَّحِیحِ مِنَ الْمَذْہَبِ ، مُجْتَبَی وَغَیْرُہُ ‘‘۔ ([9])\n اور شامی جلد دوم ص:۹۷پر ہے : ’’ قَالَ الرَّحْمَتِیُّ مَعْنَی الاسْتِفَاضَۃِ أَنْ تَأْتِیَ مِنْ تِلْکَ الْبَلْدَۃِ جَمَاعَاتٌ مُتَعَدِّدُونَ کُلٌّ مِنْہُمْ یُخْبِرُ عَنْ أَہْلِ تِلْکَ الْبَلْدَۃِ أَنَّہُمْ صَامُوا عَنْ رُؤْیَۃٍ لَا مُجَرَّدِ الشُّیُوعِ مِنْ غَیْرِ عِلْمٍ بِمَنْ أَشَاعَہُ کَمَا قَدْ تَشِیعُ أَخْبَارٌ یَتَحَدَّثُ سَاءِرُ أَہْلِ الْبَلْدَۃِ وَلَا یُعْلَمُ مَنْ أَشَاعَہَا کَمَا وَرَدَ أَنَّ فِی آخِرِ الزَّمَانِ یَجْلِسُ الشَّیْطَانُ بَیْنَ الْجَمَاعَۃِ فَیَتَکَلَّمُ بِالْکَلِمَۃِ فَیَتَحَدَّثُونَ بِہَا وَیَقُولُونَ لَا نَدْرِی مَنْ قَالَہَا فَمِثْلُ ہَذَا لَا یَنْبَغِی أَنْ یُسْمَعَ فَضْلًا عَنْ أَنْ یَثْبُتَ بِہِ حُکْمٌ ا ہـ قُلْت وَہُوَ کَلَامٌ حَسَنٌ ‘‘۔ ([10])\n¥پنجم اکمالِ عدت :\n یعنی جب ایک مہینہ کا تیس دن پورا ہوجائے تو دوسرے مہینہ کا چاند ثابت ہوجائے گا لیکن اگر ایک گواہ کی شہادت پر رمضان کا چاند مان لیا گیا اور اس حساب سے تیس دن پورے ہوگئے مگر مطلع صاف ہونے کے باوجود چاند نظر نہیں آیا تو یہ اکمالِ عدت کافی نہیں بلکہ ایک روزہ اور رکھنا پڑے گا۔\n درمختار مع ردالمحتار جلد دو م ص:۹۷ میں ہے : ’’ بَعْدَ صَوْمِ ثَلاثِینَ بِقَوْلِ عَدْلَیْنِ حَلَّ الْفِطْرُ وبِقَوْلِ عَدْلٍ لَا ، لَکِنْ نَقَلَ ابْنُ الْکَمَالِ عَنِ الذَّخِیرَۃِ إنْ غُمَّ ہِلَالُ الْفِطْرِ حَلَّ اتِّفَاقًا ۔ ملخصاً ‘‘۔ ([11])\n(۲) …اگر چاند شرعی طریقہ سے ثابت ہوجائے تو اہلِ مغرب کا دیکھنا اہلِ مشرق کے لیے لازم ہوگا ۔\n جیسا کہ فتاویٰ الامام الغزی ص :۵ میں ہے : ’’ یَلْزَمُ أَہْل الْمَشْرِقِ بِرُؤْیَۃِ أَہْلِ الْمَغْرِبِ عَلَی مَا ھُوَ ظَاھِرُ الرِّوَایَۃِ عَلَیْہِ الْفَتْوَی کَمَا فِی فَتْح الْقَدِیْرِ وَالْخُلَاصَۃِ ‘‘۔ ([12])\n(۳) …¥جنتری:\n جنتری سے چاند کا ثبوت ہر گز نہ ہوگا۔ درمختار میں ہے : ’’ لَا عِبْرَۃَ بِقَوْلِ الْمُؤَقِّتِینَ وَلَوْ عُدُولًا عَلَی الْمَذْہَبِ ‘‘۔ ([13])\n اور شامی جلد دوم ص:۹۴پر ہے : ’’ لَا یُعْتَبَرُ قَوْلُہُمْ بِالْإِجْمَاعِ وَلَا یَجُوزُ لِلْمُنَجِّمِ أَنْ یَعْمَلَ بِحِسَابِ نَفْسِہِ ‘‘۔ ([14])\n(۴) …¥اخبار :\n اخبار سے بھی چاند کا ثبوت ہرگز نہ ہوگا اس لیے کہ اخباری خبریں بسا اوقات گپ نکلتی ہیں اور اگر خبر صحیح ہو تو بھی بغیر ثبوت شرعی کے ہر گز قابلِ قبول نہیں۔ ’’ فَإِنَّہُمْ لَم یَشْہَدُوا بِالرُّؤْیَۃِ وَلَا عَلَی شَہَادَۃِ غَیْرِہِمْ وَإِنَّمَا حَکَوْا رُؤْیَۃَ غَیْرِہِمْ کَذَا فِی فَتْحِ الْقَدِیرِ ‘‘۔ ([15]) (رد المحتار، جلد دوم ، ص ۹۷)\n(۵) …¥خط :\n خط سے بھی چاند کا ثبوت نہ ہوگا اس لیے کہ ایک تحریر دوسری تحریر سے مل جاتی ہے ۔ لہذا اس سے علمِ یقینی حاصل نہ ہوگا۔ درمختار میں ہے : ’’ لَا یَعْمَلُ بِالْخَطِّ ‘‘۔ ([16]) ہدایہ میں ہے :’’ اَلْخَطُّ یُشْبِہُ الْخَطَّ فَلَا یُعْتَبَرُ ‘‘۔ ([17])\n(۶) …¥تار اور ٹیلی فون:\n تار اور ٹیلیفون بے اعتباری میں خط سے بڑھ کر ہیں اس لیے کہ خط میں کم از کم کاتب کے ہاتھ کی علامت ہوتی ہے ، تار و ٹیلیفون میں وہ بھی مفقود ، نیز جب گواہ پر دے کے پیچھے ہوتا ہے تو گواہی معتبر نہیں ہوتی اس لیے کہ ایک آواز سے دوسری آواز مل جاتی ہے ۔ تو تار اورٹیلی فون کے ذریعہ گواہی کیسے معتبر ہوسکتی ہے ۔\n فتاویٰ عالمگیری جلد سوم مصری ص:۳۵۷ میں ہے : ’’ لَوْ سَمِعَ مِنْ وَرَاءِ الْحِجَابِ لَا یَسَعُہُ أَنْ یَشْہَدَ لِاحْتِمَالِ أَنْ یَکُونَ غَیْرَہُ إذْ النَّغْمَۃُ تُشْبِہُ النَّغْمَۃَ ‘‘۔ ([18])\n(۷) … ¥ریڈیو اور ٹیلیویژن :\n ریڈیواور ٹیلیویژن میں تار و ٹیلیفون سے زیادہ دشواریاں ہیں اس لیے کہ تار و ٹیلیفون پر سوال و جواب بھی کرسکتے ہیں مگر ریڈیو اور ٹیلی ویژن پر کچھ بھی نہیں کرسکتے ۔\n غرضیکہ یہ نئے آلات خبر پہنچانے میں تو کام آسکتے ہیں لیکن شہادتوں میں معتبر نہیں ہوسکتے ۔ یہی وجہ ہے کہ خط، تار ، ٹیلیفون ، ریڈیو اور ٹیلی ویژن کی خبروں پر کچہریوں کے مقدموںکا فیصلہ نہیں ہوتا۔ بلکہ گواہوں کو حاضر ہو کر گواہی دینی پڑتی ہے پھر فیصلہ ہوتا ہے ۔\n تعجب ہے کہ جب دنیوی جھگڑوں میں موجودہ کچہری کا قانون ریڈیو اور ٹیلی ویژن کے ذریعہ گواہی ماننے کو تیار نہیں تو پھر دینی اُمور میں شریعت کا قانون ان کے ذریعہ گواہی کیوں کرمان سکتا ہے ۔\n حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کا ارشادِ گرامی اوپر گزر چکا ہے کہ:\n ’’ فَإِنْ غُمَّ عَلَیْکُمْ فَأَکْمِلُوا الْعِدَّۃَ ثَلَاثِینَ ‘‘ ۔ ([19])\nیعنی اگر چاند مشتبہ ہوجائے تو تیس دن کی گنتی پوری کرو۔ (بخاری، مسلم)\n مگر افسوس کہ موجودہ زمانہ کے بہت سے مسلمان کہ ان میں اکثر بے نمازی و بے روزہ دار ہوتے ہیں، ٹیلیفون اور ریڈیو وغیرہ کی خبر پر ایک ہنگامہ کھڑا کرکے قیامت برپا کردیتے ہیں۔\n خدائے تعالیٰ ان ناسمجھ مسلمانوں کو اپنے نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کے ارشاد گرامی پر عمل کی توفیق عطا فرمائے ۔ آمِین بِجَاہِ حَبِیْبِہِ سَیِّدِ الْمُرْسَلِیْنَ صَلَوَاتُ اللّٰہتَعَالَی وَسَلَامُہُ عَلَیْہِ وَعَلَیْھِمِ أَجْمَعِیْنَ ۔ \n (۸) …جہاں سلطانِ اسلام اور قاضی شرع کوئی نہ ہو تو شہر کا سب سے بڑا سُنّی صحیح العقیدہ مفتی اس کا قائم مقام ہے اور جہاں کوئی مفتی نہ ہو تو عامہ مومنین کے سامنے چاند کی گواہی دی جائے ۔ ([20])\n (فتاوی رضویہ، جلد چہارم، ص۵۴۷ )\n اور حدیقہ ندیہ میں ہے :\n ’’ إِذَا خَلا الزَّمَانُ مِنْ سُلْطَانٍ ذِی کِفَایَۃٍ فَالأُمُوْرُ مُؤکلَۃٌ إِلَی الْعُلَمَاءِ وَیَلْزَمُ الأُمَّۃَ الْمَرْجُوْعُ إِلَیْھِمْ وَیَصِیْرُوْنَ ولاۃً فَإِذَا عَسَرَ جَمْعُھُمْ عَلَی وَاحِدٍ اِستَقلّ کلّ قطر بِاتّبَاعِ عُلمَاءِہِ فَإنْ کَثَرُوْا فَالمُتَّبَع أَعْلَمُھُمْ فَإِنْ اسْتَوَوا أقرع بَیْنَھُمْ ‘‘۔ ([21])\n یعنی جب زمانہ ایسے سلطان سے خالی ہو جو معاملاتِ شرعیہ میں کفایت کرسکے تو سب شرعی کام علماء کے سپرد ہوں گے اور تمام معاملاتِ شرعیہ میں ان کی طرف رجوع کرنا مسلمانوں پر لازم ہوگا۔ وہی علماء قاضی و حاکم سمجھے جائیں گے پھر اگر سب مسلمانوں کا ایک عالم پر اتفاق مشکل ہو تو ہر ضلع کے لوگ اپنے علماء کی اتباع کریں۔ پھر اگر ضلع میں عالم بہت زیادہ ہوں تو جوان میں سب سے زیادہ احکام شرع جانتا ہو اس کی پیروی ہوگی اور اگر علم میں برابر ہوں تو ان میں قرعہ ڈالا جائے گا۔\n(۹) …بے نمازی، یا نماز پڑھتا ہو مگر ترک جماعت کا عادی ہو، داڑھی منڈھے داڑھی کتروا کر ایک مشت سے کم رکھانے والے یہ سب فاسق معلن ہیں ان کی گواہی شرعاً معتبر نہیں۔ یونہی کافر، بدمذہب، مجنون ، نابالغ کی گواہی بھی شرع کے نزدیک قابلِ اعتبار نہیں۔ ( عامہ کتب)\n(۱۰) …چاند دیکھ کر اس کی طرف انگلی سے اشارہ کرنا مکروہ ہے اگرچہ دوسرے کو بتانے کے لیے ہو۔ ([22])\n (بہار شریعت، پنجم ص ۶۸۵)\n اور جیسا کہ درمختار میں ہے :\n ’’ إِذَا رَأَوْا الْہِلَالَ یُکْرَہُ أَنْ یُشِیرُوا إلَیْہِ ‘‘۔ ([23])\n یعنی چاند دیکھ کر اس کی جانب اشارہ کرنا مکروہ ہے ۔\n اور فتاویٰ عالمگیری جلد اول مصری ص:۱۸۴میں ہے :\n’’ تُکْرَہُ الْإِشَارَۃُ عِنْدَ رُؤْیَۃِ الْہِلَالِ کَذَا فِی الظَّہِیرِیَّۃِ ‘‘۔ ([24])\nیعنی چاند دیکھ کر اشار ہ کرنا مکروہ ہے ایسا ہی ظہیر یہ میں ہے ۔\n(۱۱) … مسلمانوں کو اپنے معاملات میں عربی اسلامی تاریخ وسنہ کا اعتبار کرنا واجب ہے ۔ دوسری تاریخ و سنہ کا اعتبار کرنا جائز نہیں۔\n جیسا کہ تفسیر کبیرجلد چہارم ص:۴۴۵ میں ہے : ’’ قاَلَ أَہْلُ الْعِلْمِ اَلْوَاجِبُ عَلَی الْمُسْلِمِیْنَ بِحُکْمِ ہِذِہِ الْآیَۃِ ([25]) أَنْ یَعْتَبِرُوْا فِی بُیُوْعِہِمْ وَمَدد دُیُوْنِہِمْ وَأَحْوَالِ زَکَواتِہِمْ وَسَاءِرِ أَحْکَامِہِمْ السَّنَۃَ الْعَرَبِیَّۃَ بِالأَہِلَّۃِ وَلَا یَجُوْزُ لَہُمْ اِعْتِبَارُ السَّنَۃِ الْعَجمِیَّۃِ وَالرُّوْمِیَّۃِ ‘‘۔ ([26])\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، باب رؤیۃ الھلال ، الفصل الثانی ، ج ۲، ص ۸۴.\n[2] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصوم ، مبحث فی صوم یوم الشک ، ج ۳، ص ۴۰۶.\n[3] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصوم ، مبحث فی صوم یوم الشک ، ج ۳، ص ۴۰۹.\n[4] ’’ البحر الرائق ‘‘، کتاب الصوم ، ج ۲، ص ۴۷۰.\n[5] ’’ الدر المختار ورد المحتار ‘‘، کتاب الشھادات ، باب الشھادۃ علی الشھادۃ ، ج ۱۱، ص ۲۸۵.\n[6] ’’ الفتاوی الھندیۃ ‘‘، کتاب الشھادات ، الباب الحادی عشر فی الشھادۃ علی الشھادۃ ، ج ۳، ص ۵۲۴.\n[7] ’’ الفتاوی الإمام الغزی ‘‘، ص ۶، ’’ فتح القدیر ‘‘، کتاب الصوم ، فصل فی رؤیۃ الھلال ، ج ۲، ص ۳۱۹.\n[8] ’’ الفتاوی الرضویۃ ‘‘، ج ۴، ص ۴۱۴۔ ۴۱۵.\n[9] ’’ الدر المختار ‘‘ ، کتاب الصوم ، مطلب ما قالہ السبکی من الاعتماد إلخ ، ج ۳، ص ۴۱۳.\n[10] ’’ رد المحتار ‘‘، کتاب الصوم ، مطلب ما قالہ السبکی من الاعتماد إلخ ، ج ۳، ص ۴۱۳.\n[11] ’’ الدر المختار ورد المحتار ‘‘ ، کتاب الصوم ، ج ۳، ص ۴۱۳۔ ۴۱۴.\n[12] ’’ الفتاوی الإمام الغزی ‘‘، ص ۵ .\n[13] ’’ الدر المختار ‘‘، کتاب الصوم ، مطلب لا عبرۃ بقول الموقتین فی الصوم ، ج ۳، ص ۴۰۸.\n[14] ’’ رد المحتار ‘‘، کتاب الصوم ، مطلب لا عبرۃ بقول الموقتین فی الصوم ، ج ۳، ص ۴۰۸.\n[15] ’’ رد المحتار ‘‘، کتاب الصوم ، ج ۳، ص ۴۱۳.\n[16] ’’ الدر المختار ‘‘، کتاب القضاء ، مطلب لا یعمل بالخط ، ج ۸، ص ۱۵۲.\n[17] ’’ الہدایۃ ‘‘، کتاب الزکاۃ ، باب فیمن یمر علی العاشر ، ج ۱، ص ۱۰۴.\n[18] ’’ الفتاوی الھندیۃ ‘‘، کتاب الشھادات ، الباب الثانی فی بیان تحمل الشھادۃ إلخ ، ج ۳، ص ۴۵۲.\n[19] ’’ صحیح البخاری ‘‘، کتاب الصوم ، باب قول النبی صلی اللّٰہ علیہ وسلم إذا رأیتم إلخ ، الحدیث : ۱۹۰۷، ج ۱، ص ۶۲۹، ’’ صحیح مسلم ‘‘، کتاب الصیام ، الحدیث : ۱۸۔ (۱۰۸۱) ص ۵۴۶.\n[20] ’’ الفتاوی الرضویۃ ‘‘، ج ۱۰، ص ۴۰۶.\n[21] ’’ الحدیقۃ الندیۃ ‘‘، النوع الثالث فی أنواع العلوم الثلاثۃ إلخ ، ج ۱، ص ۳۵۱.\n[22] ’’بہارِ شریعت‘‘ ، ج۱، ص ۹۸۰، ’’ رد المحتار ‘‘، کتاب الصوم ، ج ۳، ص ۴۱۹.\n[23] ’’ الدر المختار ‘‘، کتاب الصوم ، مطلب فی اختلاف المطالع ، ج ۳، ص ۴۱۹.\n[24] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصوم ، الباب الثانی فی رؤیۃ الھلال ، ج ۱، ص ۱۹۷.\n[25] أَی : { اِنَّ عِدَّةَ الشُّهُوْرِ عِنْدَ اللّٰهِ اثْنَا عَشَرَ شَهْرًا } ( پارہ ۱۰، رکوع ۱۱).\n[26] ’’ التفسیر الکبیر ‘‘، سورۃ التوبۃ ، ج ۶، ص ۴۳."}, {"id": 7814, "bookId": 14, "volNo": "1", "hadithNo": 46, "chapter": "شب قدر کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَنَسِ بْنِ مَالِکٍ قَالَ دَخَلَ رَمَضَانُ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ ہَذَا الشَّہْرَ قَدْ حَضَرَکُمْ وَفِیہِ لَیْلَۃٌ خَیْرٌ مِنْ أَلْفِ شَہْرٍ مَنْ حَرُمَہَا فَقَدْ حُرِمَ الْخَیْرَ کُلَّہُ وَلَا یُحْرَمُ خَیْرَہَا إِلَّا مَحْرُوم‘‘۔ \nحدیث 2:\n’’ عَنْ عَائِشَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَحَرَّوْا لَیْلَۃَ الْقَدْرِ فِی الْوِتْرِ مِنَ الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ‘‘۔ \nحدیث 3:\n’’ عَنْ عَائِشَۃَ قُلْتُ یَا رَسُولَ اللّٰہ أَرَأَیْتَ إِنْ عَلِمْتُ أَیُّ لَیْلَۃٍ لَیْلَۃُ الْقَدْرِ مَا أَقُولُ فِیہَا قَالَ قُولِی اللّٰہمَّ إِنَّکَ عُفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّی‘‘۔ \nحدیث 4:\n’’ عَنْ عَائِشَۃَ قَالَتْ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَجْتَہِدُ فِی الْعَشْرِ الْأَوَاخِرِ مَا لَا یَجْتَہِدُ فِی غَیْرِہِ‘‘۔ \nحدیث 5:\n’’ عَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَانَ لَیْلَۃُ الْقَدْرِ نَزَلَ جِبْرِیْلُ عَلَیْہِ السَّلَامُ فِی کُبْکُبَۃٍ مِنَ الْمَلَاءِکَۃِ یُصَلُّوْنَ عَلَی کُلِّ عَبْدٍ قَاءِمٍ أَوْ قَاعِدٍ یَذْکُرُ اللّٰہ عَزَّ وَجَلَّ فَإِذَا کَانَ یَوْمُ عِیْدِہِمْ یَعْنِیْ یَوْمَ فِطْرِہِمْ بَاہَی بِہِمْ مَلَاءِکَتَہُ فَقَالَ یَا مَلَاءِکَتِیْ مَا جَزَاءُ أَجِیْرٍ وَفَّی عَمَلَہُ ؟ قَالُوْا رَبَّنَا جَزَاؤُہُ أَنْ یُوَفَّی أَجْرُہُ قَالَ مَلَاءِکَتِی عَبِیْدِیْ وَإِمَاءِی قَضَوْا فَرِیْضَتِیْ عَلَیْہِمْ ثُمَّ خَرَجُوْا یَعِجُّوْنَ إِلَی الدُّعَاءِ وَعِزَّتِیْ وَجَلَالِی وَکَرَمِیْ وَعُلُوِّیْ وَارْتِفَاعِ مَکَانِی لَأُجِیْبَنَّہُمْ فَیَقُوْلُ اِرْجِعُوْا فَقَدْ غَفَرْتُ لَکُمْ وَبَدَّلْتُ سَیِّءَاتِکُمْ حَسَنَاتٍ قَالَ فَیَرْجِعُوْنَ مَغْفُوْرًا لَّہُمْ ‘‘۔ \nحدیث 6:\n’’ عَنْ عَائِشَۃَ قَالَتْ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا دَخَلَ الْعَشْرُ شَدَّ مِئْزَرَہُ وَأَحْیَا لَیْلَہُ وَأَیْقَظَ أَہْلَہُ ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس بن مالک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ جب رمضان کا مہینہ شروع ہوا تو حضور علیہ الصلاۃ والسلام نے فرمایا کہ یہ مہینہ تم میں آیا ہے ۔ اور اس میں ایک رات ایسی ہے جو ہزار مہینوں سے بہتر ہے ۔ تو جو شخص اس کی برکتوں سے محروم رہا وہ تمام بھلائیوں سے محروم رہا اور نہیں محروم رکھا جاتا اس کی بھلائیوں سے مگر وہ جو بالکل بے نصیب ہو۔ (ابن ماجہ)\n¥ترجمہ حدیث 2:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ رمضان کے آخری عشرہ کی طاق راتوں میں شب قدر کو تلا ش کرو۔ (بخاری)\n¥ترجمہ حدیث 3:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام سے پوچھا کہ یارسول اللّٰہ ! اگر مجھ کو شبِ قدر معلوم ہوجائے تو میں اس میں کیا کروں؟ آپ نے فرمایا کہ یہ دعا پڑھو۔ ’’ أَللَّھُمَّ إِنَّکَ عَفُو تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّی ‘‘۔ (ترمذی)\n¥ترجمہ حدیث 4:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ حضور علیہ الصلاۃ والسلام جس قدر رمضان کے آخری عشرہ میں (طاعت و عبادت کے لیے ) کوشش فرماتے تھے ، اتنی کسی دوسرے عشرہ میں نہ فرماتے تھے ۔ (مسلم)\n¥ترجمہ حدیث 5:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والتسلیم نے فرمایا کہ جب شبِ قدر آتی ہے تو جبرئیل علیہ السلام فرشتوں کی جماعت کے ساتھ آتے ہیں اور ہر اس بندہ کے لیے دعائے مغفرت کرتے ہیں جو کھڑے ہوکر یا بیٹھ کر خدائے تعالیٰ کے ذکر میں مشغول رہتا ہے پھر جب انہیں عید الفطر کا دن نصیب ہوتا ہے تو خدائے تعالیٰ اپنے ان بندوں پر اپنے فرشتوں کے سامنے اپنی خوشنودی کا اظہار کر تا ہے اور فرماتا ہے کہ اے میرے فرشتو! اس مزدور کی اجرت کیا ہے جو اپنا کام پورا کردے ، فرشتے عرض کرتے ہیں کہ اے میرے پروردگار اس کی اجرت یہ ہے کہ ا سکو پورا معاوضہ دیا جائے ۔ خدائے تعالیٰ فرماتا ہے کہ اے میرے فرشتو! میرے بندوں اور میری لونڈیوں نے ( میرے مقرر کیے ہوئے ) فرض کو ادا کردیا اب وہ گھر وں سے دعا کے لیے عیدگاہ کی طرف نکلے ہیں۔ قسم ہے اپنی عزت، اپنے جلال، اپنی بخشش و رحمت اپنی عظمت شان اور اپنی رفعت مکان کی کہ میں ان کی دعاؤں کو قبول کروں گا۔ پھر خدائے تعالیٰ فرماتا ہے اے میرے بندو ! اپنے گھروں کو لوٹ جاؤ میں نے تم کو بخش دیا اور تمہاری برائیوں کو نیکیوں میں تبدیل کردیا۔ فرمایا حضور علیہ الصلاۃ والسلام نے کہ پس مسلمان واپس ہوتے ہیں۔ عیدگاہ سے اس حال میں کہ ان کے گناہ بخش دیئے جاتے ہیں۔ (بیہقی)\n¥ترجمہ حدیث 6:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ جب رمضان کا آخری عشرہ آتا تو حضور علیہ الصلاۃ والسلام اپنے تہبند کو مضبوط باندھ لیتے ( یعنی عبادت میں بہت کوشش فرماتے ) راتوں کو جاگتے اور اپنے گھر والوں کو جگاتے ۔", "roman": "Tarjuma Hadees 1: Hazrat Anas Bin Malik Radiyallahu Anhu ne farmaya ke jab Ramazan ka mahina shuru hua to Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke ye mahina tum mein aaya hai. Aur is mein ek raat aisi hai jo hazar mahinon se behtar hai. To jo shakhs is ki barkaton se mehroom raha woh tamam bhalaiyon se mehroom raha aur nahi mehroom rakha jata is ki bhalaiyon se magar woh jo bilkul be-naseeb ho. (Ibn Majah). Tarjuma Hadees 2: Hazrat Aishah Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke Ramazan ke aakhri Ashrah ki taaq raton mein Shab-e-Qadr ko talash karo. (Bukhari). Tarjuma Hadees 3: Hazrat Aishah Radiyallahu Anha ne farmaya ke main ne Rasoolullah Sallallahu Alaihi Wasallam se pucha ke Ya Rasoolullah! Agar mujh ko Shab-e-Qadr maloom hojaye to main is mein kya karun? Aap ne farmaya ke ye Dua parho. ’’Allahumma innaka Afuwwun tuhibbul Afwa fa'fu anni’’. (Tirmidhi). Tarjuma Hadees 4: Hazrat Aishah Radiyallahu Anha ne farmaya ke Rasoolullah Sallallahu Alaihi Wasallam jis qadar Ramazan ke aakhri Ashrah mein (ta'at-o-ibadat ke liye) koshish farmate thay, itni kisi dusre Ashrah mein na farmate thay. (Muslim). Tarjuma Hadees 5: Hazrat Anas Radiyallahu Anhu ne farmaya ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jab Shab-e-Qadr aati hai to Jibraeel Alayhis Salam farishton ki Jama'at ke sath aate hain aur har us banday ke liye Dua-e-maghfirat karte hain jo kharay ho kar ya baith kar Khuda-e-Ta'ala ke zikr mein mashghool rehta hai phir jab unhein Eid-ul-Fitr ka din naseeb hota hai to Khuda-e-Ta'ala apne in bandon par apne farishton ke samne apni khushnudi ka izhar karta hai aur farmata hai ke ae mere farishto! Is mazdoor ki Ujrat kya hai jo apna kaam pura karday, farishtay arz karte hain ke ae mere Parwardigar is ki Ujrat ye hai ke us ko pura muawza diya jaye. Khuda-e-Ta'ala farmata hai ke ae mere farishto! Mere bandon aur meri londiyon ne (mere muqarrar kiye hue) Farz ko ada kardiya ab woh gharon se Dua ke liye Eid-gah ki taraf nikle hain. Qasam hai apni izzat, apne jalal, apni bakhshish-o-rehmat, apni azmat-e-shaan aur apni rif'at-e-Makaan ki ke main in ki Duaon ko Qubool karunga. Phir Khuda-e-Ta'ala farmata hai ae mere bando! Apne gharon ko laut jao main ne tum ko bakhsh diya aur tumhari buraiyon ko nekiyon mein tabdeel kardiya. Farmaya Rasool-e-Kareem Sallallahu Alaihi Wasallam ne ke pas Musalman wapas hote hain Eid-gah se is hal mein ke un ke gunah bakhsh diye jate hain. (Baihaqi). Tarjuma Hadees 6: Hazrat Aishah Radiyallahu Anha ne farmaya ke jab Ramazan ka aakhri Ashrah aata to Rasoolullah Sallallahu Alaihi Wasallam apne tehband ko mazboot bandh lete (yani ibadat mein bahut koshish farmate) raton ko jagte aur apne ghar walon ko jagate.", "explanation": "¥شرح حدیث 6:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ شَدَّ مِئْزَرَہُ کے تحت فرماتے ہیں: ’’ کنایت ست از اجتہاد در عبادات زیادہ بر عادت یاکنایت از گوشہ گرفتن از زناں ‘‘۔ ([1])( اشعۃ اللمعات ، جلد دوم ، ص ۱۱۵)\n¥انتباہ :\n بعض جگہ شب قدر میں عشاء کی نماز کے لیے سات باراذان کہتے ہیں یہ بے اصل ہے جس کا کوئی ثبوت نہیں۔\nوہ معزز تھے زمانے میں مسلمان ہو کر\nاور ہم خوار ہوئے تارک قرآن ہو کر\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، باب لیلۃ القدر ، الفصل الأول ، ج ۲، ص ۱۲۳."}, {"id": 7815, "bookId": 14, "volNo": "1", "hadithNo": 47, "chapter": "اعتکاف کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَائِشَۃَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ یَعْتَکِفُ الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ حَتَّی تَوَفَّاہُ اللّٰہ ‘‘۔ \nحدیث 2:\n’’ عَنْ أَنَسِ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَعْتَکِفُ فِی الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ فَلَمْ یَعْتَکِفْ عَامًا فَلَمَّا کَانَ الْعَامُ الْمُقْبِلُ اعْتَکَفَ عِشْرِینَ ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا سے روایت ہے کہ نبی کر یم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم رمضان کے آخری عشرہ میں اعتکاف کیا کرتے تھے یہاں تک کہ ( اسی طریقے پر) وصال فرمایا۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام رمضان کے آخری عشرہ میں اعتکاف فرمایا کرتے تھے اور ایک سال اعتکاف نہیں فرمایا تو دوسرے سال بیس دن اعتکاف فرمایا۔ (ترمذی، ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Aishah Radiyallahu Anha se Riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam Ramazan ke aakhri Ashrah mein I'tikaf kiya karte thay yahan tak ke (isi tareeqay par) wisal farmaya. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Anas Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alaihi Wasallam Ramazan ke aakhri Ashrah mein I'tikaf farmaya karte thay aur ek saal I'tikaf nahi farmaya to dusre saal bees din I'tikaf farmaya. (Tirmidhi, Abu Dawood).", "explanation": "¥شرح حدیث 2:\nرمضان کے آخری عشرہ میں اعتکاف کرنا سنت مؤکدہ ہے ۔ جیسا کہ حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں:\n’’ اعتکاف در ظاہر مذہب حنفیہ سنت مؤکدہ است از جہت مواظبت رسولِ خدا صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ برآں تا انکہ گذشت ازیں عالم ‘‘ ۔ ([1])\nیعنی ظاہر مذہب حنفیہ میں اعتکاف سنت موکدہ ہے اس لیے کہ حضور علیہ الصلاۃ والسلام ہمیشہ اعتکاف فرمایا کرتے تھے ۔ یہاں تک کہ اس دنیا سے تشریف لے گئے ۔ (اشعۃ اللمعات، جلد دوم، ص ۱۱۸)\n¥انتباہ:\n (۱) …اعتکاف کی تین قسمیں ہیں:\n ’’¥واجب ‘‘ کہ اعتکاف کی منّت مانی مثلاً یوں کہا کہ میرا بچہ تندرست ہوگیا تو میں تین دن اعتکاف کروں گا۔ تو بچہ کے تندرست ہونے پر روزہ کے ساتھ تین دن کا اعتکاف واجب ہوگا۔\n ’’¥سنت مؤکدہ‘‘ کہ بیسویں رمضان کو سورج ڈوبتے وقت اعتکاف کی نیت سے مسجد میں ہو اور تیسویں رمضان کو غروب کے بعد یا انتیس کو چاند ہونے کے بعد نکلے ۔ یہ اعتکاف سنت کفایہ ہے یعنی اگر سب لوگ ترک کریں تو سب سے مطالبہ ہوگا۔ اور ایک نے کرلیا تو سب بری الذمہ ہوگئے ۔\n ان دونوں کے علاوہ جو اعتکاف کیا جائے وہ’’ ¥مستحب‘‘ ہے ۔\n جیسا کہ فتاویٰ عالمگیری جلد اول ص:۱۹۷ میں ہے : ’’ یَنْقَسِمُ إلَی وَاجِبٍ وَہُوَ الْمَنْذُورُ تَنْجِیزًا أَوْ تَعْلِیقًا وَإِلَی سُنَّۃٍ مُؤَکَّدَۃٍ وَہُوَ فِی الْعَشْرِ الْأَخِیرِ مِنْ رَمَضَانَ ، وَإِلَی مُسْتَحَبٍّ وَہُوَ مَا سِوَاہُمَا ہَکَذَا فِی فَتْحِ الْقَدِیرِ ‘‘۔ ([2])\n (۲) …اعتکاف کرنے والا دنیوی بات نہ کرے ، قرآن مجید کی تلاوت کرے ۔ حدیث شریف پڑھے اور درود شریف کی کثرت کرے ۔ علم دین پڑھنے پڑھانے میں مشغول ہو۔ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ اور دیگر انبیائے کرام علیہم الصلوۃ والسلام اور اولیائے عظام کی سیرت کی کتابیں پڑھے ۔\n جیسا کہ فتاویٰ عالمگیری جلد اول مصری ص:۱۹۸میں ہے : ’’ لَا یَتَکَلَّمَ إلَّا بِخَیْرٍ وَیُلَازِم التِّلاوَۃَ وَالْحَدِیثَ وَالْعِلْمَ وَتَدْرِیسَہُ وَسِیَرَ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَالْأَنْبِیَاءِ عَلَیْہِمْ السَّلَامُ ، وَأَخْبَارَ الصَّالِحِینَ کَذَا فِی فَتْحِ الْقَدِیرِ ‘‘ ملخصاً ۔ ([3])\n (۳) …مستحب اعتکاف کی آسان صورت یہ ہے کہ جب بھی مسجد میں داخل ہوں تو دروازہ پر دخولِ مسجد کی نیت کے ساتھ اعتکاف کی بھی نیت کرلیں جب تک مسجد میں رہیں گے اعتکاف کا بھی ثواب ملے گا۔ نیت کے الفاط یہ ہیں:\n ’’ بِسْمِ اللّٰہدَخَلْتُ وَعَلَیْہِ تَوَکَّلْتُ وَنَوَیْتُ سُنَّۃَ الْاِعْتِکَافِ اَللَّھُمَّ افْتَحْ لِی أَبْوَابَ رَحْمَتِکَ ‘‘ ۔\nیعنی اللّٰہ تعالیٰ کے مقدس نام کی برکت کے ساتھ میں داخل ہوا اور اسی پر میں نے بھروسہ کیا اور میں نے سنت اعتکاف کی نیت کی۔ بارِ الہٰا! میرے لیے اپنی رحمت کے دروازے کھول دے ۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصوم ، باب الاعتکاف ، ج ۲، ص ۱۲۵.\n[2] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصوم ، الباب السابع فی الاعتکاف ، ج ۱، ص ۲۱۱.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الصوم ، الباب السابع فی الاعتکاف ، ج ۱، ص ۲۱۲."}, {"id": 7816, "bookId": 14, "volNo": "1", "hadithNo": 48, "chapter": "تلاوت قرآن مجید کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ عُثْمَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ خَیْرُکُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَہُ‘‘۔ \nحدیث 2:\n’’عَنْ مُعَاذن الْجُہَنِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ قَرَأَ الْقُرْآنَ وَعَمِلَ بِمَا فِیہِ أُلْبِسَ وَالِدَاہُ تَاجًا یَوْمَ الْقِیَامَۃِ ضَوْءُ ہُ أَحْسَنُ مِنْ ضَوْءِ الشَّمْسِ فِی بُیُوتِ الدُّنْیَا لَوْ کَانَتْ فِیکُمْ فَمَا ظَنُّکُمْ بِالَّذِی عَمِلَ بِہَذَا‘‘۔\nحدیث 3:\n’’ عَنْ ابْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ قَرَأَ حَرْفًا مِنْ کِتَابِ اللّٰہ فَلَہُ بِہِ حَسَنَۃٌ وَالْحَسَنَۃُ بِعَشْرِ أَمْثَالِہَا لَا أَقُولُ الم حَرْفٌ أَلِفٌ حَرْفٌ وَلَامٌ حَرْفٌ وَمِیمٌ حَرْفٌ‘‘ ۔ \nحدیث 4:\n’’ عَنْ الْبَرَاءِ قَالَ کَانَ رَجُلٌ یَقْرَأُ سُورَۃَ الْکَہْفِ وَإِلَی جَانِبِہِ حِصَانٌ مَرْبُوطٌ بِشَطَنَیْنِ فَتَغَشَّتْہُ سَحَابَۃٌ فَجَعَلَتْ تَدْنُو وَتَدْنُو وَجَعَلَ فَرَسُہُ یَنْفِرُ فَلَمَّا أَصْبَحَ أَتَی النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَذَکَرَ ذَلِکَ لَہُ فَقَالَ تِلْکَ السَّکِینَۃُ تَنَزَّلَتْ بِالْقُرْآنِ‘‘۔\nحدیث 5:\n’’ عَنْ أَبِی سَعِیدٍ الْخُدْرِیِّ أَنَّ أُسَیْدَ بْنَ حُضَیْرٍ قَالَ بَیْنَمَا ہُوَ یَقْرَأُ مِنْ اللَّیْلِ سُورَۃَ الْبَقَرَۃِ وَفَرَسُہُ مَرْبُوطَۃٌ عِنْدَہُ إِذْ جَالَتِ الْفَرَسُ فَسَکَتَ فَسَکَتَتْ فَقَرَأَ فَجَالَتِ الْفَرَسُ فَسَکَتَ فَسَکَتَتْ الْفَرَسُ ثُمَّ قَرَأَ فَجَالَتِ الْفَرَسُ فَانْصَرَفَ وَکَانَ ابْنُہُ یَحْیَی قَرِیبًا مِنْہَا فَأَشْفَقَ أَنْ تُصِیبَہُ فَلَمَّا اَخَّرَہُ رَفَعَ رَأْسَہُ إِلَی السَّمَاءِ فَإِذَا مِثْلُ الظُّلَّۃِ فِیہَا أَمْثَالُ الْمَصَابِیح فَلَمَّا أَصْبَحَ حَدَّثَ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ فَقَالَ اقْرَأْ یَا ابْنَ حُضَیْرٍ اقْرَأْ یَا ابْنَ حُضَیْرٍ قَالَ فَأَشْفَقْتُ یَا رَسُولَ اللّٰہ أَنْ تَطَأَ یَحْیَی وَکَانَ مِنْہَا قَرِیبًا فَرَفَعْتُ رَأْسِی فَانْصَرَفْتُ إِلَیْہِ وَرَفَعْتُ رَأْسِی إِلَی السَّمَاءِ فَإِذَا مِثْلُ الظُّلَّۃِ فِیہَا أَمْثَالُ الْمَصَابِیحِ فَخَرَجَت حَتَّی لَا أَرَاہَا قَالَ وَتَدْرِی مَا ذَاکَ قَالَ لَا قَالَ تِلْکَ الْمَلَاءِکَۃُ دَنَتْ لِصَوْتِکَ وَلَوْ قَرَأْتَ لَأَصْبَحَت یَنْظُرُ النَّاسُ إِلَیْہَا لَا تَتَوَارَی مِنْہُمْ‘‘۔\nحدیث 6:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لِأُبَیِّ بْنِ کَعْبٍ کَیْفَ تَقْرَأُ فِی الصَّلَاۃِ فَقَرَأَ أُمَّ الْقُرْآنِ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَالَّذِی نَفْسِی بِیَدِہِ مَا أُنْزِلَتْ فِی التَّوْرَاۃِ وَلَا فِی الْإِنْجِیلِ وَلَا فِی الزَّبُورِ وَلَا فِی الْقُرْآنِ مِثْلُہَا‘‘۔ \nحدیث 7:\n’’عَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ إِنَّ لِکُلِّ شَیْئٍ قَلْبًا وَقَلْبُ الْقُرْآنِ یس وَمَنْ قَرَأَ یس کَتَبَ اللّٰہ لَہُ بِقِرَاءَ تِہَا قِرَاءَ ۃَ الْقُرْآنِ عَشْرَ مَرَّاتٍ‘‘۔\nحدیث 8:\n’’ عَنْ عَطَاءِ بْنِ أَبِی رَبَاحٍ قَالَ بَلَغَنِی أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ قَرَأَ یس فِی صَدْرِ النَّہَارِ قُضِیَتْ حَوَاءِجُہُ‘‘۔ \nحدیث 9:\n’’عَنْ مَعْقِلِ بْنِ یَسَارٍ الْمُزَنِیِّ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ قَرَأَ یس اِبْتِغَاءَ وَجْہِ اللّٰہ تَعَالَی غُفِرَ لَہُ مَا تَقَدَّمَ مِنْ ذَنْبِہِ فَاقْرَءُ وْہَا عَنْدَ مَوْتَاکُمْ‘‘۔ \nحدیث 10:\n’’ عَنْ عَلِیٍّ قَالَ سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ لِکُلِّ شَیْئٍ عَرُوْسٌ وَعَرُوْسُ الْقُرْآنِ الرَّحْمٰنُ‘‘۔ \nحدیث 11:\n’’عَنْ أَبِی الدَّرْدَاءقَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَیَعْجِزُ أَحَدُکُمْ أَنْ یَقْرَأَ فِی لَیْلَۃٍ ثُلُثَ الْقُرْآنِ قَالُوا وَکَیْفَ یَقْرَأْ ثُلُثَ الْقُرْآنِ قَالَ قُلْ ہُوَ اللّٰہ أَحَدٌ یَعْدِلُ ثُلُثَ الْقُرْآنِ‘‘۔\nحدیث 12:\n’’ عَنْ أَبِی مُوسَی الْأَشْعَرِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَعَاہَدُوا الْقُرْآنَ فَوَالَّذِی نَفْسِی بِیَدِہِ لَہُوَ أَشَدُّ تَفَصِّیًا مِنَ الْإِبِلِ فِی عُقُلِہَا‘‘۔ (بخاری، مسلم)\nحدیث 13:\n’’ عَنْ سَعْدِ بْنِ عُبَادَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا مِنْ اِمْرَئٍ یَقْرَأُ الْقُرْآنَ ثُمَّ یَنْسَاہُ إِلَّا لَقِیَ اللّٰہ یَوْمَ الْقِیَامَۃِ أَجْذَمَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عثمان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ تم میں بہترین شخص وہ ہے جس نے قرآن کو سیکھا اور دوسروں کو سکھایا۔ (بخاری)\n¥ترجمہ حدیث 2:\nحضر ت معا ذ جہنی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص قرآن کو پڑھے اور اس پر عمل کرے تو قیامت کے دن اس کے ماں اور باپ کو ایسا تاج پہنایا جائے گا کہ اس کی روشنی دُنیا کے سورج کی روشنی سے بڑھ کرہوگی جب کہ سورج کو اتنا قریب فرض کر لیا جائے کہ گویا تمہارے گھروں میں اتر آیا ہے پھر تم سمجھ سکتے ہو کہ جب ماں باپ کا یہ مر تبہ ہوگا تو اس شخص کا کیا درجہ ہوگا جس نے قرآن کریم پر عمل کیا۔ (احمد)\n¥ترجمہ حدیث 3:\nحضرت ابنِ مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص کتاب اللّٰہ میں سے ایک حرف پڑھے تو اس کو ہر حرف کے بدلے ایک نیکی ملے گی ا ور ہر نیکی دس نیکیوں کے برابر ہوگی۔ میں آلم ّکو ایک حرف نہیں کہتا بلکہ الف ایک حرف ہے ، لام ایک حرف ہے اور میم ایک حرف ہے ۔ (ترمذی، دارمی)\n قرآن میں کل ۳۲۱۲۶۷۰ حروف ہیں تو پورے قرآن کی تلاوت سے ۳۲۱۲۶۷۰ نیکیاں ملیں گی۔ \n¥ترجمہ حدیث 4:\nحضرت براء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ایک شخص سورۂ کہف پڑھ رہا تھا اورا س کے قریب ایک جانب دو رسیوں سے گھوڑا بندھا ہوا تھا اس گھوڑے پر ایک ابر چھا گیا اور گھوڑے سے قریب ہوا پھراور قریب ہوا۔ اور گھوڑے نے اس کو دیکھ کر اچھلناکودنا شروع کیا جب صبح ہوئی تو اس نے حضور علیہ الصلوۃ والسلام کی خدمت میں حاضر ہو کر واقعہ بیان کیا آپ نے فرمایا یہ سکینہ یعنی رحمت تھی جو قرآن پڑھنے کے سبب نازل ہوئی۔ (بخاری، مسلم)\n¥ترجمہ حدیث 5:\nحضرت ابو سعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ اسید بن حضیر نے بیان کیا ہے کہ میں رات کو سورۂ بقرہ پڑھ رہا تھا اور میرا گھوڑا پاس بندھا ہوا تھا یکایک گھوڑا کودنے اُچھلنے لگا میں پڑھتے پڑھتے خاموش ہوگیا تو گھوڑا بھی ٹھہر گیا میں نے پھر پڑھنا شروع کیا گھوڑا پھر اسی طرح اچھلنے کودنے لگا آخر میں نے پڑھنا بند کردیا اور میرا بیٹا یحییٰ گھوڑے کے قریب سورہا تھا مجھ کو اندیشہ ہوا کہ کہیں گھوڑا اس کو تکلیف نہ پہنچادے اس خیال سے یحیی کو ہٹا کرجب آسمان کی طرف سر اٹھایا تو اچانک دیکھا کہ کوئی چیز سائبان کی طرح ہے جس میں چراغوں جیسی چمکتی ہوئی چیزیں ہیں۔ جب صبح ہوئی تو اس واقعہ کو میں نے حضور علیہ الصلو ۃ والسلام سے بیان کیاآپ نے فرمایا اے ابن حضیر تلاوت کرتے رہو۔ میں نے عرض کی یارسول اﷲ! میرا بیٹا یحییٰ قریب تھا مجھ کو اندیشہ ہوا کہ کہیں گھوڑا اس کو کچل نہ دے ۔ اس لیے میں یحییٰ کی طرف چلا گیا اور آسمان کی طرف سر اٹھایا تو کوئی چیز سائبان کی طرح نظر آئی جس میں چراغوں کی طرح چیزیں تھیں۔ پھر میں نے باہر نکل کر دیکھا توکچھ بھی نہ تھا۔ حضور علیہ الصلاۃ والسلام نے فرمایا تم جانتے ہو وہ کیا تھا؟ میں نے عرض کیا نہیں آپ نے فرمایا وہ فرشتے تھے جو تیری قرات کو سننے آئے تھے ۔ اگر تو برابر پڑھتا رہتا تو صبح کو لوگ فرشتوں کو دیکھتے اور فرشتے ان کی نظروں سے نہ چھپتے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 6:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے حضرت اُبی بن کعب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے دریافت فرمایا کہ تم نماز میں کیا پڑھتے ہو تو انہوں نے سورۂ فاتحہ کی تلاوت کی۔ تو حضور علیہ الصلاۃ والسلام نے فرمایا قسم ہے اس ذات کی جس کے قبضۂ قدرت میں میری جان ہے کہ توراۃ، انجیل اور زبور ( یہاں تک کہ) قرآن میں اس کے مثل ( کوئی دوسری سورۃ) نہیں نازل ہوئی۔ (ترمذی)\n¥ترجمہ حدیث 7:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ہر چیز کا دل ہے اور قرآن کا دل سورۂ یس ہے ۔ پس جو شخص سورۂ یس کو پڑھے اس کے لیے دس قرآن پڑھنے کا ثواب لکھا جاتا ہے ۔ (ترمذی، دارمی)\n¥ترجمہ حدیث 8:\nحضرت عطاء بن رباح رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ مجھ کو معلوم ہوا کہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا دن کے شروع حصہ میں جو شخص سورۂ یس کو پڑھے تو اس کی حاجتیں پوری کردی جاتی ہیں۔ (دارمی)\n¥ترجمہ حدیث 9:\nحضرت معقل بن یسار مزنی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جس شخص نے محض خدا کی خوشنودی حاصل کرنے کے لیے سورۂ یس کو پڑھا تو اس کے اگلے گناہ معاف کیے جاتے ہیں توا س سورۃکو تم لوگ اپنے مُردوں کے پاس پڑھا کرو۔ (بیہقی)\n¥ترجمہ حدیث 10:\nحضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور علیہ الصلاۃ والسلام کو یہ فرماتے ہوئے سنا کہ ہر چیز کی ایک زینت ہے اور قرآن پاک کی زینت سورۂ رحمن ہے ۔ (بیہقی)\n¥ترجمہ حدیث 11:\nحضرت ابودرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ تم میں سے کوئی شخص رات کے وقت تہائی قرآن نہیں پڑ سکتا۔ صحابہ نے عرض کیا یارسول اللّٰہ ! تہائی قرآن کیسے پڑھا جائے ؟ آپ نے فرمایا ( پوری سورۂ ) قُل ھُوَ اللّٰہأَحَد تہائی قرآن کے برابر ہے ۔ (مسلم، بخاری عن ابی سعد رضی اللّٰہ عنہ ) \n¥ترجمہ حدیث 12:\nحضرت ابو موسی اشعر ی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ قرآن کے ساتھ اعتناکرو۔ قسم ہے اس ذات کی جس کے قبضۂ قدرت میں میری جان ہے اپنی رسی سے اونٹ نکل جانے کی بہ نسبت قرآن سینہ سے جلد نکل جاتا ہے ۔ \n¥ترجمہ حدیث 13:\nحضرت سعد بن عبادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص قرآن مجید پڑھے اور پھر اس کو بھول جائے وہ قیامت کے دن خدا سے اس حال میں ملے گا کہ اس کے اعضاء جذام( ) کے سبب گل گئے ہوں گے ۔ (ابوداود، دارمی)", "roman": "Tarjuma Hadees 1: Hazrat Usman Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke tum mein behtareen shakhs woh hai jis ne Quran ko seekha aur dusron ko sikhaya. (Bukhari). Tarjuma Hadees 2: Hazrat Mu'az Juhani Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs Quran ko parhe aur is par amal kare to Qayamat ke din us ke maa aur baap ko aisa taj pehnaya jayega ke us ki roshni dunya ke suraj ki roshni se barh kar hogi jab ke suraj ko itna qareeb Farz kar liya jaye ke goya tumhare gharon mein utar aaya hai phir tum samajh sakte ho ke jab maa baap ka ye martaba hoga to us shakhs ka kya darja hoga jis ne Quran-e-Kareem par amal kiya. (Ahmad). Tarjuma Hadees 3: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs Kitaab-ullah mein se ek harf parhe to us ko har harf ke badle ek neki milegi aur har neki das nekiyon ke barabar hogi. Main Alif-Laam-Meem ko ek harf nahi kehta balkay Alif ek harf hai, Laam ek harf hai aur Meem ek harf hai. (Tirmidhi, Darimi). Quran mein kul 3212670 huroof hain to pure Quran ki tilawat se 3212670 nekiyan milengi. Tarjuma Hadees 4: Hazrat Bara Radiyallahu Anhu ne farmaya ke ek shakhs Surah-e-Kahf parh raha tha aur us ke qareeb ek janib do rassiyon se ghora bandha hua tha, us ghoray par ek abr chha gaya aur ghoray se qareeb hua phir aur qareeb hua. Aur ghoray ne us ko dekh kar uchhalna kudna shuru kiya jab subah hui to us ne Rasoolullah Sallallahu Alaihi Wasallam ki khidmat mein hazir ho kar waqia bayan kiya, Aap ne farmaya ye Sakeena yani rehmat thi jo Quran parhne ke sabab nazil hui. (Bukhari, Muslim). Tarjuma Hadees 5: Hazrat Abu Saeed Khudri Radiyallahu Anhu se Riwayat hai ke Usaid Bin Hudair ne bayan kiya hai ke main raat ko Surah-e-Baqarah parh raha tha aur mera ghora paas bandha hua tha, yakayak ghora kudne uchhalne laga, main parhte parhte khamosh hogaya to ghora bhi thehar gaya, main ne phir parhna shuru kiya ghora phir isi tarah uchhalne kudne laga, aakhir main ne parhna band kardiya aur mera beta Yahya ghoray ke qareeb so raha tha, mujh ko andesha hua ke kahin ghora us ko takleef na pahunchade, is khayal se Yahya ko hata kar jab aasman ki taraf sar uthaya to achanak dekha ke koi cheez saiban ki tarah hai jis mein charaghon jaisi chamakti hui cheezein hain. Jab subah hui to is waqia ko main ne Rasoolullah Sallallahu Alaihi Wasallam se bayan kiya, Aap ne farmaya ae Ibn Hudair tilawat karte raho. Main ne arz ki Ya Rasoolullah! Mera beta Yahya qareeb tha mujh ko andesha hua ke kahin ghora us ko kuchal na de. Is liye main Yahya ki taraf chala gaya aur aasman ki taraf sar uthaya to koi cheez saiban ki tarah nazar aayi jis mein charaghon ki tarah cheezein thin. Phir main ne bahar nikal kar dekha to kuch bhi na tha. Rasoolullah Sallallahu Alaihi Wasallam ne farmaya tum jante ho woh kya tha? Main ne arz ki nahi, Aap ne farmaya woh farishtay thay jo teri qirat ko sunne aaye thay. Agar tu barabar parhta rehta to subah ko log farishton ko dekhte aur farishtay un ki nazron se na chupte. (Bukhari, Muslim). Tarjuma Hadees 6: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne Hazrat Ubay Bin Ka'b Radiyallahu Anhu se daryaft farmaya ke tum Namaz mein kya parhte ho to unhon ne Surah-e-Fatihah ki tilawat ki. To Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya qasam hai us zaat ki jis ke qabza-e-qudrat mein meri jaan hai ke Taurat, Injeel aur Zaboor (yahan tak ke) Quran mein is ke misl (koi dusri Surah) nahi nazil hui. (Tirmidhi). Tarjuma Hadees 7: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke har cheez ka dil hai aur Quran ka dil Surah-e-Yaseen hai. Pas jo shakhs Surah-e-Yaseen ko parhe us ke liye das Quran parhne ka sawab likha jata hai. (Tirmidhi, Darimi). Tarjuma Hadees 8: Hazrat Ata Bin Rabah Radiyallahu Anhu ne kaha ke mujh ko maloom hua ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya din ke shuru hissa mein jo shakhs Surah-e-Yaseen ko parhe to us ki hajatein puri kardi jati hain. (Darimi). Tarjuma Hadees 9: Hazrat Ma'qal Bin Yasar Muzni Radiyallahu Anhu se Riwayat hai ke Nabi-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jis shakhs ne mehez Khuda ki khushnudi hasil karne ke liye Surah-e-Yaseen ko parha to us ke agle gunah maaf kiye jate hain to is Surah ko tum log apne murdon ke paas parha karo. (Baihaqi). Tarjuma Hadees 10: Hazrat Ali Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alaihi Wasallam ko ye farmate hue suna ke har cheez ki ek zeenat hai aur Quran-e-Paak ki zeenat Surah-e-Rahman hai. (Baihaqi). Tarjuma Hadees 11: Hazrat Abu Darda Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke tum mein se koi shakhs raat ke waqt tihai Quran nahi parh sakta. Sahabah ne arz kiya Ya Rasoolullah! Tihai Quran kaise parha jaye? Aap ne farmaya (puri Surah) Qul Huwallahu Ahad tihai Quran ke barabar hai. (Muslim, Bukhari an Abi Sa'ad Radiyallahu Anhu). Tarjuma Hadees 12: Hazrat Abu Musa Ash'ari Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Quran ke sath e'tina karo. Qasam hai us zaat ki jis ke qabza-e-qudrat mein meri jaan hai apni rassi se unt nikal jane ki ba-nisbat Quran seena se jald nikal jata hai. Tarjuma Hadees 13: Hazrat Sa'ad Bin Ubadah Radiyallahu Anhuma ne kaha ke Rasoolullah Sallallahu Alaihi Wasallam ne farmaya ke jo shakhs Quran Majeed parhe aur phir us ko bhool jaye woh Qayamat ke din Khuda se is hal mein milega ke us ke a'aza juzam ke sabab gal gaye honge. (Abu Dawood, Darimi).", "explanation": "¥اِنتباہ :\n (۱)…بیرونِ نماز کسی سورت کے شروع سے تلاوت کی ابتداء کرتے وقت أَعُوْذُ بِاللّٰہمِنَ الشَّیطَانِ الرَّجِیْم پڑھنا مستحب اور بسم اللّٰہ پڑھنا سنت ہے اور درمیان سورت سے تلاوت کی ابتداء کرتے وقت أَعُوْذُ بِاللّٰہ اور بِسْمِ اللّٰہ پڑھنا مستحب ہے ۔ ([1]) (بہار شریعت)\n (۲)…سورۂ توبہ کی ابتداء میں أَعُوْذُ بِاﷲ پڑھنے کا نیا طریقہ جو آج کل کے حافظوں نے نکالا ہے بے اصل ہے ۔ اور یہ جو مشہور ہے کہ سورۂ توبہ کے کسی حصہ سے تلاوت کی ابتداء کرتے وقت بِسْمِ اللّٰہ نہ پڑھے یہ محض غلط ہے ۔ ([2]) (بہار شریعت، جلد سوم ، ص ۳۰۹)\n (۳)…بعض جگہ ’’ لَقَدْ جَاء کُمْ رَسُولٌ مِنْ أَنْفُسِکُمْ ‘‘ سے خارج نماز تلاوت کی ابتداء کرتے ہیں مگر اس کے شروع میں بِسْمِ اللّٰہ نہیں پڑھتے ۔ حالانکہ اس آیت کے شروع میں بھی اَعُوْذُ اور بِسْمِ اللّٰہ پڑھنا مستحب ہے اسی طرح قُل میں پنج آیت پڑھتے وقت ’’ وَإِلٰھُکُمْ إِلٰہُ وَّاحِدٌ ‘‘یا ’’ إِنَّ رَحْمَۃَ اللّٰہقَرِیْبٌ ‘‘ یا ’’ مَاکَانَ مُحَمَّدٌ ‘‘ سے تلاوت کی ابتداء کرتے ہیں تو تعوذ و تسمیہ نہیں پڑھتے ایسا ہرگز نہ چاہیے ۔\n (۴)…مجمع میں سب لوگ بلند آواز سے قرآن پڑھیں یہ حرام ہے اکثر تیجوں میں سب بلند آواز سے پڑھتے ہیں۔ یہ حرام ہے اگر چند شخص پڑھنے والے ہوں تو حکم ہے کہ آہستہ پڑھیں۔ ([3]) (بہار شریعت جلد سوم ص۳۱۰)\n اور درمختار مع ردالمحتار جلد اول ص:۳۸۳ میں ہے :’’ یَجِبُ الاسْتِمَاعُ لِلْقِرَاءَ ۃِ مُطْلَقًا لِأَنَّ الْعِبْرَۃَ لِعُمُومِ اللَّفْظِ ‘‘۔ ([4])\n (۵)…پورے قرآن مجید کا حفظ کرنا فرض کفایہ ہے اور سورۂ فاتحہ اور ایک دوسری چھوٹی سورت یا اس کی مثل مثلاً تین چھوٹی آیتیں یا ایک بڑی آیت کا حفظ کرنا واجب عین ہے ۔ ([5]) (بہار شریعت ، جلد سوم ، ص ۳۰۵)\n اور درمختار میں ہے : ’’ حِفْظُ جَمِیعِ الْقُرْآنِ فَرْضُ کِفَایَۃٍ وَحِفْظُ فَاتِحَۃِ الْکِتَابِ وَسُورَۃٍ وَاجِبٌ عَلَی کُلِّ مُسْلِمٍ ‘‘ ملخصاً ۔ ([6])\n (۶)… ث س ش ص ، ت ط ، ذ ز ض ظ ، ا ء ع ، ح ہ ، ق ک ، د ض ، ج ز ، ان حرفوں میں صحیح امتیاز رکھیں ورنہ معنی فاسد ہونے کی صورت میں نماز نہ ہوگی۔ ([7]) (بہار شریعت)\n (۷)…جو لوگ ح ، ط ، ع ، ص وغیرہ کے صحیح تلفظ پر قدرت نہ رکھتے ہوں انہیں لازم ہے کہ تصحیح حرو ف کے لیے حتی الامکان کوشش جاری رکھیں ورنہ نماز نہ ہوگی۔\n جیسا کہ فتاویٰ رضویہ، جلد سوم، ص: ۹۵، اور شامی جلد اول ص:۴۰۹ میں ہے : ’’ مَنْ لَا یَقْدِرُ عَلَی التَّلَفُّظِ بِحَرْفٍ مِنَ الْحُرُوفِ کَالرَّہْمَنِ الرَّہِیمِ وَالشَّیْتَانِ الرَّجِیمِ ، نَأْبُدُ وَإِیَّاکَ نَسْتَءِینُ ، السِّرَاتَ ، أَنْأَمْتَ ، فَکُلُّ ذَلِکَ حُکْمُہُ مَا مَرَّ مِنْ بَذْلِ الْجہْدِ دَاءِمًا وَإِلَّا فَلا تَصِحُّ الصَّلَاۃُ بِہِ ‘‘ ملخصاً ۔ ([8])\n (۸)…دیہاتوں میں مکتب کے اکثر مدرسین کو دیکھا گیا ہے کہ وہ پورے قرآن میں ذ ز ظ کو ج ، ق کو ک ، ش کو س اور غ کو گ پڑھاتے ہیں یہ سخت گناہ ہے ۔ اور بعض تو بلا وضو قرآن مجید کو ہاتھ لگاتے ہیں جو سخت ناجائز و حرام ہے ۔ کَمَا قَالَ اللّٰہ تَعَالَی :{ لَّا یَمَسُّهٗۤ اِلَّا الْمُطَهَّرُوْنَ } ( پارہ ۲۷، سورہ واقعہ )۔\n (۹)…آج کل اکثر حافظ اس طرح قرآن مجید پڑھتے ہیں کہ یَعْلَمُوْنَ تَعْلَمُوْنَ کے سوا کسی لفظ کا پتہ نہیں چلتا۔ نہ تصحیح حروف ہوتی ہے ۔ بلکہ جلدی میں لفظ کے لفظ کھا جاتے ہیں۔ اور اس پر فخر ہوتا ہے کہ فلاں اس قدر جلد پڑھتا ہے حالانکہ اس طرح قرآن مجید پڑھنا سخت حرام ہے ۔ ([9]) (بہار شریعت ، جلد سوم ، ص ۳۰۶)\n (۱۰)…اوقات مکروہ یعنی طلوع و غروب کے وقت اور دوپہر میں تلاوت قرآن مجید بلا کراہت جائز ہے لیکن نہ کرے تو بہتر ہے ۔ بہار شر یعت جلد سوم ص:۲۳۰ میں ہے :’’ ان اوقات میں تلاوتِ قرآن مجید بہتر نہیں۔ بہتر یہی ہے کہ ذکر و درود شریف میں مشغول رہے ۔ ‘‘ ([10])\n اور بحرالرائق جلد اول ص:۲۵۱ میں ’’ البغیہ ‘‘ کا یہ قول: ’’ الصَّلاۃُ عَـلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی الْأَوْقَاتِ الَّتِی تُکْرَہُ فِیہَا الصَّلَاۃُ وَالدُّعَاءُ وَالتَّسْبِیحُ أَفْضَلُ مِنْ قِرَاء ۃِ الْقُرْآنِ ‘‘نقل کرکے لکھتے ہیں: ’’ وَلَعَلَّہُ لِأَنَّ الْقِرَاءَ ۃَ رُکْنُ الصَّلَاۃِ وَہِیَ مَکْرُوہَۃٌ فَالْأَوْلَی تَرْکُ مَا کَانَ رُکْنًا لَہَا ‘‘۔ ([11])\n اور ردالمحتارجلد اول ص:۲۶۲ میں صاحب بحر کے قول ’’ فَالْأَوْلَی ‘‘ کے تحت ہے : ’’ فَالْأَوْلَی أَيْ فَالْأَفْضَلُ لِیُوَافِقَ کَلامَ الْبُغْیَۃِ فَإِنَّ مفَادَہُ أَنَّہُ لَا کَرَاہَۃَ أَصْلًا لِأَنَّ تَرْکَ الْفَاضِلِ لَا کَرَاہَۃَ فِیہِ ‘‘۔ ([12])\n مغز قرآن ، جان ایمان ، روح دیں ہست حب رحمۃ للعلمین\n------------------\n[1] ’’بہار شریعت‘‘، ج۱، ص ۵۵۰.\n[2] ’’بہار شریعت‘‘، ج۱، ص ۵۵۱.\n[3] ’’بہار شریعت‘‘، ج۱، ص ۵۵۲.\n[4] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصلاۃ ، فروع فی القراء ۃ خارج الصلاۃ ، ج ۲، ص ۳۲۸.\n[5] ’’بہار شریعت‘‘، ج۱، ص ۵۴۵۔ ۵۴۶، ’’ الدر المختار ‘‘، کتاب الصلاۃ ، فصل فی القراء ۃ ، ج ۲، ص ۳۱۵ .\n[6] ’’ الدر المختار ‘‘، کتاب الصلاۃ ، مطلب فی الفرق بین فرض العین وفرض الکفایۃ ، ج ۲، ص ۳۱۵.\n[7] ’’بہار شریعت‘‘، ج۱، ص ۵۵۷.\n[8] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب الإمامۃ ، ج ۲، ص ۳۹۶، ’’ الفتاوی الرضویۃ ‘‘، ج ۶، ص ۲۵۵.\n[9] ’’بہار شریعت‘‘، ج۱، ص ۵۴۷.\n[10] ’’بہار شریعت‘‘، ج۱، ص ۴۵۵، ’’ الدر المختار ‘‘، کتاب الصلاۃ ، ج ۲، ص ۴۴.\n[11] ’’ البحر الرائق ‘‘، کتاب الصلاۃ ، ج ۱، ص ۴۳۷.\n[12] ’’ رد المحتار ‘‘، کتاب الصلاۃ ، مطلب یشترط العلم بدخول الوقت ، ج ۲، ص ۴۴."}, {"id": 7817, "bookId": 14, "volNo": "1", "hadithNo": 49, "chapter": "حج کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَا أَیُّہَا النَّاسُ اِنَّ اللّٰہ کَتَبَ عَلَیْکُمُ الْحَجَّ فَقَامَ الْأَقْرَعُ بْنُ حَابِسٍ أَفِی کُلِّ عَامٍ یَا رَسُولَ اللّٰہ قَالَ لَوْ قُلْتُہَا نَعَمْ لَوَجَبَتْ وَلَوْ وَجَبَتْ لَمْ تَعْمَلُوا بِہَا وَلَمْ تَسْتَطِیعُوا وَالْحَجُّ مَرَّۃٌ فَمَنْ زَادَ فَتَطَوُّعٌ‘‘۔ \nحدیث 2:\n’’عَنْ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَرَادَ الْحَجَّ فَلْیَتَعَجَّلْ‘‘۔ \nحدیث 3:\n’’عَنِ ابْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَابِعُوا بَیْنَ الْحَجِّ وَالْعُمْرَۃِ فَإِنَّہُمَا یَنْفِیَانِ الْفَقْرَ وَالذُّنُوبَ کَمَا یَنْفِی الْکِیرُ خَبَثَ الْحَدِیدِ وَالذَّہَبِ وَالْفِضَّۃِ وَلَیْسَ لِلْحَجَّۃِ الْمَبْرُورَۃِ ثَوَابٌ إِلَّا الْجَنَّۃُ‘‘۔\nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ خَرَجَ حَاجًّا أَوْ غَازِیًا ثُمَّ مَاتَ فِی طَرِیْقِہِ کَتَبَ اللّٰہ لَہُ أَجْرَ الْغَازِیِّ وَالْحَاجِّ وَالْمُعْتَمِرِ‘‘۔\nحدیث 5:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اِنَّ عُمْرَۃ فِی رَمَضَانَ تَعْدِلُ حَجَّۃً‘‘۔ \nحدیث 6:\n’’عَنْ أَبِی رَزِینٍ الْعُقَیْلِیِّ أَنَّہُ أَتَی النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ یَا رَسُولَ اللّٰہ إِنَّ أَبِی شَیْخٌ کَبِیرٌ لَا یَسْتَطِیعُ الْحَجَّ وَلَا الْعُمْرَۃَوَلَا الظَّعْنَ قَالَ حُجَّ عَنْ أَبِیکَ وَاعْتَمِرْ‘‘۔ (ترمذی، ابوداود)\nحدیث 7:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ أَتَی رَجُلٌ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ إِنَّ أُخْتِی نَذَرَتْ أَنْ تَحُجَّ وَإِنَّہَا مَاتَتْ فَقَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْ کَانَ عَلَیْہَا دَیْنٌ أَکُنْتَ قَاضِیَہُ قَالَ نَعَمْ قَالَ فَاقْضِ دَیْنَ اللّٰہ فَہُوَ أَحَقُّ بِالْقَضَاء‘‘۔\nحدیث 8:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تُسَافِرَنَّ امْرَأَۃٌ إِلَّا وَمَعَہَا مَحْرَمٌ ‘‘۔ (بخاری، مسلم)\nحدیث 9:\n’’ عَنْ عَلِیٍّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ مَلَکَ زَادًا وَرَاحِلَۃً تُبَلِّغُہُ إِلَی بَیْتِ اللّٰہ وَلَمْ یَحُجَّ فَلاعَلَیْہِ أَنْ یَمُوتَ یَہُودِیًّا أَوْ نَصْرَانِیًّا وَذَلِکَ أَنَّ اللّٰہ تَعَالَی یَقُولُ: { وَ لِلّٰهِ عَلَى النَّاسِ حِجُّ الْبَیْتِ مَنِ اسْتَطَاعَ اِلَیْهِ سَبِیْلًاؕ-}(پارہ ۴، رکوع۱)۔ (ترمذی)", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ اے لوگو! خدا نے تم پر حج فرض کیا ہے ۔ اقرع بن حابس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کھڑے ہو کر عرض کیا یارسول اللّٰہ ! کیا ہر سال حج فرض ہے ؟ فرمایا اگر میں ہاں کردوں تو ہر سال حج فرض ہوجائے اور اگر ہر سال فرض ہوجائے تو تم اسے ادا کرنے کی طاقت نہیں رکھتے ۔ اس لیے حج پوری زندگی میں صرف ایک مرتبہ فرض ہے اور جو شخص اس سے زیادہ کرے وہ نفل ہے ۔ (احمد ، نسائی، دارمی، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت ابنِ عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص حج کا ارادہ کرے تو پھر جلد اس کو پورا کرے ۔ (ابوداود، دارمی)\n¥ترجمہ حدیث 3:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ حج اور عمرہ کو یکے بعد دیگرے ادا کرو( یعنی قِران کا احرام باندھو یا بالفعل دونوں کو متصلاًکرو) اس لیے کہ یہ دونوں افلاس ا ور گناہوں کو اس طرح دور کردیتے ہیں جس طرح بھٹی لوہے چاندی اور سونے کی میل کو دور کردیتی ہے ۔ اور حج مقبول کا بدلہ صرف جنت ہے ۔ (ترمذی، نسائی)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص حج یا عمرہ یا جہاد کے ارادہ سے نکلا اور پھر راستہ ہی میں مرگیا تو اللّٰہ تعالیٰ اس کے حق میں ہمیشہ کے لیے مجاہد، حاجی اور عمرہ کرنے والے کا ثواب لکھ دیتا ہے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ رمضان میں عمرہ کرنا حج کے برابر ہے ۔ \n¥ترجمہ حدیث 6:\nحضرت ابو رزین عقیلی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ وہ نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی خدمت میں حاضرہوئے اور عرض کیا یارسول اللّٰہ ! میرا بوڑھا باپ اتنا کمزور ہے کہ حج و عمرہ کی طاقت نہیں رکھتا اور نہ سواری پر سفر کرنے کی اس میں قوت ہے آپ نے فرمایا تو اپنے باپ کی طرف سے حج و عمرہ کرلے ۔ \n¥ترجمہ حدیث 7:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے فرمایا کہ حضور علیہ الصلاۃ والسلام کی خدمت میں ایک شخص نے حاضر ہو کر عرض کیا کہ میری بہن نے حج کی نذر مانی تھی(اورنذرپوری کرنے سے پہلے )وہ مرگئی۔ آپ نے فرمایا اگر اس پر قرض ہوتا تو کیا اس کو ادا کرتا؟ اس نے عرض کیا ہاں، آپ نے فرمایا تو پھر خدائے تعالیٰ کا قرض بھی ادا کرکہ اس کا ادا کرنا زیادہ ضروری ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 8:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ عورت بغیر محرم کے ہر گز سفر نہ کرے ( چاہے وہ حج ہی کا سفر کیوں نہ ہو)۔ \n¥ترجمہ حدیث 9:\nحضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جو شخص زادِ راہ اور بیت اللّٰہ شریف تک پہنچادینے والی سواری کے مصارف کا مالک ہو اور پھر اس نے حج نہیں کیا تو اس کے یہودی یا نصرانی ہو کر مرنے میں کوئی فرق نہیں اور یہ اس لیے کہ اللّٰہ تعالیٰ نے فرمایا ہے ۔ { وَ لِلّٰهِ عَلَى النَّاسِ حِجُّ الْبَیْتِ مَنِ اسْتَطَاعَ اِلَیْهِ سَبِیْلًاؕ- } یعنی خدائے تعالیٰ کے لیے بیت اللّٰہ کا حج کرنا لوگوں پر فرض ہے جب کہ حج کے تمام ضروری مصارف کا مالک ہو۔", "roman": "Tarjuma Hadees 1: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke ae logo! Allah ne tum par Hajj Farz kiya hai. Aqra bin Habis Radiyallahu Anhu ne khade ho kar arz kiya Ya Rasoolullah! Kya har saal Hajj Farz hai? Farmaya agar main haan kar doon to har saal Hajj Farz ho jaye aur agar har saal Farz ho jaye to tum ise ada karne ki taqat nahi rakhte. Is liye Hajj poori zindagi mein sirf ek martaba Farz hai aur jo shakhs is se zyada kare woh nafl hai. (Ahmad, Nasai, Darimi, Mishkat)\nTarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs Hajj ka irada kare to phir jald us ko poora kare. (Abu Dawood, Darimi)\nTarjuma Hadees 3: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Nabi-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Hajj aur Umrah ko yake baad deegre ada karo (yani Qiran ka Ihraam bandho ya bilfa'l dono ko muttasil karo) is liye ke ye dono iflaas aur gunahon ko is tarah door kar dete hain jis tarah bhatti lohay, chandi aur sonay ki mail ko door kar deti hai. Aur Hajj Qubool ka badla sirf Jannat hai. (Tirmidhi, Nasai)\nTarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs Hajj ya Umrah ya Jihad ke iraday se nikla aur phir rastay hi mein mar gaya to Allah Ta'ala us ke haq mein hamesha ke liye mujahid, haaji aur Umrah karne walay ka sawab likh deta hai. (Baihaqi, Mishkat)\nTarjuma Hadees 5: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Ramzan mein Umrah karna Hajj ke barabar hai.\nTarjuma Hadees 6: Hazrat Abu Razin Uqaili Radiyallahu Anhu se riwayat hai ke woh Nabi-e-Kareem Sallallahu Alayhi wa Sallam ki khidmat mein hazir huay aur arz kiya Ya Rasoolullah! Mera boodha baap itna kamzor hai ke Hajj o Umrah ki taqat nahi rakhta aur na sawari par safar karne ki us mein quwwat hai. Aap ne farmaya to apne baap ki taraf se Hajj o Umrah kar le.\nTarjuma Hadees 7: Hazrat Ibn Abbas Radiyallahu Anhum ne farmaya ke Huzoor Sallallahu Alayhi wa Sallam ki khidmat mein ek shakhs ne hazir ho kar arz kiya ke meri behan ne Hajj ki nazr maani thi (aur nazr poori karne se pehle) woh mar gayi. Aap ne farmaya agar us par Qarz hota to kya us ko ada karta? Us ne arz kiya haan, Aap ne farmaya to phir Khudaye Ta'ala ka Qarz bhi ada kar ke us ka ada karna zyada zaroori hai. (Bukhari, Muslim)\nTarjuma Hadees 8: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke Aurat baghair mehram ke hargiz safar na kare (chahay woh Hajj hi ka safar kyun na ho).\nTarjuma Hadees 9: Hazrat Ali Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs zaad-e-rah aur Baitullah Shareef tak pahuncha dene wali sawari ke masarif ka maalik ho aur phir us ne Hajj nahi kiya to us ke Yahoodi ya Nasrani ho kar marnay mein koi farq nahi aur ye is liye ke Allah Ta'ala ne farmaya hai: {Wa lillahi alan-nasi hijjul baiti manistata'a ilaihi sabeela} yani Khudaye Ta'ala ke liye Baitullah ka Hajj karna logon par Farz hai jab ke Hajj ke tamam zaroori masarif ka maalik ho.", "explanation": "¥شرح حدیث 1:\n معلوم ہوا کہ حضور اکرم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم ا حکام شرعیہ پر اختیار کلی رکھتے ہیں کہ اگر چاہتے تو ہر سال حج کرنا فرض فرمادیتے ۔ \n¥انتباہ :\n (۱)… دکھاوے کے لیے حج کرنا اور مال حرام سے حج کو جانا حرام ہے ۔ ([1]) (درمختار، رد المحتار، بہار شریعت، ج۶، ص ۷۱۹)\n (۲)…حج کرنے کے لیے بھی تصویر اور فوٹو کھنچاناجائز نہیں خواہ حج فرض ہو یا نفل۔ اس لیے کہ گناہ سے بچنا کسی نیکی کے اکتساب سے اہم و اعظم ہے ۔\n جیسا کہ فتاویٰ رضویہ جلد سوم ص: ۷۲۹ پر اشباہ سے ہے : ’’ اِعْتِنَاءُ الشَّرْعِ بِالْمَنْہِیَّاتِ أَشَدُّ مِنْ اِعْتِنَاءِہِ بِالْمَأْمُورَاتِ ‘‘۔ ([2])\n (۳)…عورت کو مکہ شریف تک جانے میں تین روز یا زیادہ کا راستہ ہو تو اس کے ہمراہ شوہر یا محرم ہونا ضروری ہے خواہ وہ جوان عورت ہو یا بوڑھی۔ محرم سے مراد وہ مرد ہے کہ جس سے ہمیشہ کے لیے اس عورت کا نکاح حرام ہے ۔ خواہ نسبت کی وجہ سے نکاح حرام ہو جیسے باپ، بیٹا ، اور بھائی وغیرہ یا دودھ کے رشتہ سے نکاح کی حرمت ہو جیسے رضاعی بھائی باپ بیٹا وغیرہ یا سسرالی رشتہ سے حرمت آئی ہو جیسے خسر، شوہر کا بیٹا وغیرہ۔ ([3]) (بہار شریعت)\n (۴)…شوہر یا محرم جس کے ساتھ عورت سفر کرسکتی ہے اس کا عاقل بالغ غیر فاسق ہونا شرط ہے ۔ مجنون یا نابالغ یا فاسق کے ساتھ نہیں جاسکتی۔ ([4]) (عالمگیری، درمختار، بہار شریعت)\n (۵)…عورت کو بغیر محرم یا شوہر کے حج کے لیے جانا حرام ہے اگر حج کرے گی تو ہوجائے گا مگر ہر قدم پرگناہ لکھا جائے گا۔ ([5]) (فتاوی رضویہ، جلد چہارم، ص ۶۹۱)\n بعض عورتیں بغیر محرم اپنے پیر یا کسی بوڑھے آدمی کے سا تھ حج کو جاتی ہیں یہ بھی ناجائز و حرام ہے ۔\n (۶)…عورت کے ساتھ شوہر اور محرم نہ ہو تو اس پر واجب نہیں کہ حج کے جانے کے لیے نکاح کرے ۔ ([6])\n (بہار شریعت)\n (۷)… اگر حج کے مصارف کا مالک ہو اور احباب کے لیے تحفہ و تحائف لانے کی استطاعت نہ رکھتا ہو تب بھی حج کو جانا فرض ہے ۔ اس کی وجہ سے حج نہ کرنا حرام ہے ۔ ([7]) (بہار شریعت)\n (۸)…سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے روضۂ انور کی حاضری اور بیت اللّٰہ شریف نیز دیگر مقاماتِ مقدسہ کی زیارت کے بعد حاجیوں کو چاہیے تو یہ تھا کہ اپنے عزیز و اقارب میں مذہبی رنگ پیدا کرتے مگر افسوس کہ ایسا کرنے کے بجائے وہاں سے ریڈیو لا کر اپنے عزیز واقارب کو دیتے ہیں جس سے وہ اکثر اوقات گانا بجانا سن کر گناہ کماتے رہتے ہیں۔ اور ساتھ ہی ریڈیو لانے والے حاجی کا نامۂ اعمال بھی سیاہ ہوتا رہتا ہے ۔ اَلْعِیَاذُ بِاللّٰہتَعَالَی قَالَ اللّٰہ تَعَالَی : { تَعَاوَنُوْا عَلَى الْبِرِّ وَ التَّقْوٰى ۪-وَ لَا تَعَاوَنُوْا عَلَى الْاِثْمِ وَ الْعُدْوَانِ۪- } ( پارہ ۶، رکوع ۵)\n (۸)…جس نے پاک مال، پاک کمائی، پاک نیت سے حج کیا اور اس میں لڑائی جھگڑا نیز ہر قسم کے گناہ ونافرمانی سے بچا پھر حج کے بعدفوراً مر گیا اتنی مہلت نہ ملی کہ جو حقوق اللّٰہ یا حقوق العباد اس کے ذمے تھے انہیں ادا کرتا یا ادا کرنے کی فکر کرتا۔ تو حج قبول ہونے کی صورت میں امید قوی ہے کہ اللّٰہ تعالیٰ اپنے تمام حقوق کو معاف فرمادے اور حقوق العباد کو اپنے ذمۂ کرم پر لے کر حق والوں کو قیامت کے دن راضی کرے اور خصومت سے نجات بخشے ۔ ([8])( اعجب الامداد للامام احمدرضا ) \n اور اگر حج کے بعد زندہ رہا اور حتی الامکان حقوق کا تدارک کرلیا یعنی سالہا ئے گزشتہ کی مابقی زکوۃ ادا کردی چھوٹی ہوئی نماز اور روزہ کی قضا کی، جس کا حق مار لیا تھا اس کو یا مرنے کے بعد اس کے وارثین کو دے دیا، جسے تکلیف پہنچائی تھی معاف کرالیا جو صاحب حق نہ رہا اس کی طرف سے صدقہ کردیا۔ اگر حقوق اللّٰہ اور حقوق العباد میں سے ادا کرتے کرتے کچھ رہ گیا تو موت کے وقت اپنے مال میں سے ان کی ادائیگی کی وصیت کرگیا۔ خلاصہ یہ کہ حقوق اللّٰہ اور حقوق العباد میں سے چھٹکارے کی ہر ممکن کوشش کی تو اس کے لیے بخشش کی اور زیادہ امید ہے ۔ ([9]) ( اعجب الامداد)\n ہاں اگر حج کے بعد قدرت ہونے کے باوجود ان امور سے غفلت برتی انہیں ادا نہ کیا تو یہ سب گناہ ازسرِ نو اس کے ذمہ ہوں گے اس لیے کہ حقوق اللّٰہ و حقوق العباد تو باقی ہی تھے ان کی ادائیگی میں تاخیر کرنا پھر تازہ گناہ ہوا جس کے ازالہ کے لیے وہ حج کافی نہ ہوگا۔ اس لیے کہ حج گزرے گناہوں یعنی وقت پر نماز و روزہ وغیرہ ادا نہ کرنے کی تقصیر کو دھوتا ہے ۔ حج سے قضا شدہ نماز اور روزہ ہر گز نہیں معاف([10]) ہوتے اور نہ آئندہ کے لیے پروانۂ آزادی ملتا ہے بلکہ مقبول([11]) حج کی نشانی ہی یہ ہے کہ حاجی پہلے سے اچھا ہو کر واپس ہو۔ ([12]) (اعجب الامداد)\n آج کل بہت سے حضرات برسہا برس حقوق اللّٰہ یعنی نماز و روزہ اور زکاۃ وغیرہ نہیں ادا کر تے نیز حقوق العباد کی کچھ پروا نہیں کرتے ، کسی کا قتل کرتے ہیں، کسی کی زمین غصب کرلیتے ہیں۔ کسی کا مال چراتے ہیں کسی کا روپیہ لے لیتے ہیں اور کسی کو ستاتے ہیں ۔ پھر حج کر آتے ہیں اور یہ سمجھتے ہیں کہ ہمارا سب گناہ معاف ہوگیا نہ اب چھوٹی ہوئی قضا نمازیں پڑھنی ہیں نہ بندوں کے حقوق معاف کرانا ہے یہ ان کی سخت غلط فہمی ہے ۔\n مولیٰ تعالیٰ مسلمانوں کو توفیق عطا فرمائے کہ وہ حقوق اللّٰہ اور حقوق العباد کما حقہ ادا کریں ۔\n ’’ آمِیْن بِجَاہِ حَبِیْبِہِ سَیِّدِ الْمُرْسَلِیْنَ صَلَوَاتُ اللّٰہتَعَالَی وَسَلَامُہُ عَلَیْہِ وَعَلَیْھِمْ أَجْمَعِیْنَ ‘‘\nحاجیوں آؤ شہنشاہ کا روضہ دیکھو\nکعبہ تو دیکھ چکے ، کعبہ کا کعبہ دیکھو\n------------------\n[1] ’’بہار شریعت‘‘، ج ۱، ص۱۰۳۶، ’’ الدر المختار ورد المحتار ‘‘، مطلب فیمن حج بمال إلخ ، ج ۳، ص ۵۱۹.\n[2] ’’ الفتاوی الرضویۃ ‘‘، ج ۸، ص ۴۰۶.\n[3] ’’بہارِ شریعت‘‘ ، ج۱، ص۱۰۴۴.\n[4] ’’بہارِ شریعت‘‘ ، ج۱، ص۱۰۴۴، ’’ الدر المختار ‘‘، کتاب الحج ، ج ۳، ص ۵۳۱۔ ۵۳۲ .\n[5] ’’ الفتاوی الرضویۃ ‘‘ ، ج ۱۰، ص ۷۰۶۔ ۷۰۷.\n[6] ’’بہارِ شریعت‘‘، ج۱، ص۱۰۴۵، ’’ الجوھرۃ النیرۃ ‘‘، کتاب الحج ، ص ۱۹۳.\n[7] ’’بہارِ شریعت‘‘، ج۱، ص۱۰۴۰، ’’ رد المحتار ‘‘، کتاب الحج ، مطلب فیمن حج بمال إلخ ، ج ۳، ص ۵۲۸.\n[8] ’’ أعجب الإمداد فی مکفرات حقوق العباد ‘‘، ص ۲۷.\n[9] ’’ أعجب الإمداد فی مکفرات حقوق العباد ‘‘، ص ۲۸.\n[10] ردالمحتار جلد دوم ص:۲۶۱ میں اس مسئلہ پر بحث کے بعد فرمایا کہ: ’’ وَالْحَاصِلُ أَنَّ تَأْخِیرَ الدَّیْنِ وَغَیْرِہِ وَتَأْخِیر نَحْوِ الصَّلَاۃِ وَالزَّکَاۃِ مِنْ حُقُوقِہِ تَعَالَی فَیَسْقُطُ إثْمُ التَّأْخِیرِ فَقَطْ عَمَّا مَضَی دُونَ الْأَصْلِ وَدُونَ التَّأْخِیرِ الْمُسْتَقْبِلِ قَالَ فِی الْبَحْرِ فَلَیْسَ مَعْنَی التَّکْفِیرِ کَمَا یَتَوَہَّمُہُ کَثِیرٌ مِنَ النَّاسِ أَنَّ الدَّیْنَ یَسْقُطُ عَنْہُ وَکَذَا قَضَاءُ الصَّلاۃِ وَالصَّوْمِ وَالزَّکَاۃِ إذْ لَمْ یَقُلْ أَحَدٌ بِذَلِکَ ‘‘پھر ص:۲۶۲ پر فرمایا ’’ وَالْحَاصِلُ کَمَا فِی الْبَحْرِ أَنَّ الْمَسْأَلَۃَ ظَنِّیَّۃٌ فَلا یُقْطَعُ بِتَکْفِیرِ الْحَجِّ لِلْکَبَاءِرِ مِنْ حُقُوقِہِ تَعَالَی فَضْلًا عَنْ حُقُوقِ الْعِبَادِ ‘‘۔ (’’ رد المحتار ‘‘ ، کتاب الحج ، مطلب فی تکفیر الحج الکبائر ، ج ۴، ص ۵۸۔ ۵۹)\n[11] اشعۃ اللمعات جلد دوم ص :۳۰۲میں ہے : ’’ گفتہ اند نشان حج مبرور آن ست کہ بہتر از انکہ رفتہ است برگردد بیاید راغب در آخرت وزاہد در دینا وبمعاصی عود نہ کند ‘‘ ۱۲منہ (’’ اشعۃ اللمعات ‘‘، کتاب المناسک ، الفصل الأول ، ج ۲، ص ۳۲۰)\n[12] ’’ أعجب الإمداد فی مکفرات حقوق العباد ‘‘، ص ۲۹."}, {"id": 7818, "bookId": 14, "volNo": "1", "hadithNo": 50, "chapter": "مدینہ طیبہ کی حاضری کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ زَارَ قَبْرِی وَجَبَتْ لَہُ شَفَاعَتِی ‘‘۔ (دار قطنی، بیہقی)\nحدیث 2:\n’’ عَنِ ابْنِ عُمَرَقَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ جَاءَ نِی زَاءِرًا لَا تَعْمَلہُ حَاجَۃ إِلا زِیَارَتِی کَانَ حَقًّا عَلَیَّ أَنْ أَکُونَ لَہُ شَفِیعًا یَوْمَ الْقِیَامَۃِ.‘‘۔ \nحدیث 3:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ حَجَّ فَزَارَ قَبْرِی بَعْدَ وَفَاتِی کَانَ کَمَنْ زَارَنِی فِی حَیَاتِی‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابنِ عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص میری قبر کی زیارت کرے اس کے لیے میری شفاعت واجب ہے ۔ \n¥ترجمہ حدیث 2:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو میری زیارت کے لیے آیا ، سوائے میری زیارت کے اور کسی حاجت کے لیے نہ آیا تو مجھ پر حق ہے کہ قیامت کے دن اس کا شفیع بنوں۔ (دار قطنی، طبرانی)\n¥ترجمہ حدیث 3:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جس نے حج کیا اور میری وفات کے بعد میری قبر کی زیارت کی تو ایسا ہے جیسے میر ی حیات ( دنیوی ) میں زیارت سے مشرف ہوا۔ (دار قطنی، طبرانی)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs meri Qabr ki Ziyarat kare us ke liye meri Shafa'at Wajib hai.\nTarjuma Hadees 2: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke jo meri Ziyarat ke liye aaya, siwaye meri Ziyarat ke aur kisi haajat ke liye na aaya to mujh par haq hai ke Qayamat ke din us ka shafee banoon. (Dar Qutni, Tabarani)\nTarjuma Hadees 3: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke jis ne Hajj kiya aur meri wafat ke baad meri Qabr ki Ziyarat ki to aisa hai jaise meri hayat (duniyawi) mein Ziyarat se musharraf hua. (Dar Qutni, Tabarani)", "explanation": "¥انتباہ:\n (۱) …زیارت ِ اقدس قریب بواجب ہے ۔ ([1]) (فتاوی رضویہ، بہار شریعت)\n (۲) …حج کے لیے جانا اور سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے روضۂ انور کی زیارت نہ کرنا بدبختی کی علامت ہے ۔\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۱، ص۱۲۲۱، ’’ الفتاوی الرضویۃ ‘‘، ج ۱۰، ص ۷۶۳."}, {"id": 7819, "bookId": 14, "volNo": "1", "hadithNo": 51, "chapter": "انبیائے کرام زندہ ہیں", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی الدَّرْدَاءِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ حَرَّمَ عَلَی الْأَرْضِ أَنْ تَأْکُلَ أَجْسَادَ الْأَنْبِیَاءِ فَنَبِیُّ اللّٰہ حَیٌّ یُرْزَقُ‘‘۔\nحدیث 2:\n’’عَنْ أَوْسِ بْنِ أَوْسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ حَرَّمَ عَلَی الْأَرْضِ أَجْسَادَ الْأَنْبِیَاءِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابودرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ خدائے تعالیٰ نے زمین پر انبیائے کرام علیہم السلام کے جسموں کو کھانا حرام فرمادیا ہے لہذا اللّٰہ کے نبی زندہ ہیں۔ رزق دیئے جاتے ہیں۔ (رواہ ابن ماجہ، مشکوۃ ص۱۲۱)\n¥ترجمہ حدیث 2:\nحضرت اوس بن اوس رضی ا للہ تعالیٰ عنہ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ خدائے تعالیٰنے انبیائے کرام علیہم السلام کے جسموں کو زمین پر (کھانا) حرام فرمادیا ہے ۔", "roman": "Tarjuma Hadees 1: Hazrat Abu Darda Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Khudaye Ta'ala ne Zameen par Anbiya-e-Kiram Alaihimussalam ke jismon ko khana Haram farma diya hai lehaza Allah ke Nabi zinda hain. Rizq diye jatay hain. (Rawah Ibn Majah, Mishkat s-121)\nTarjuma Hadees 2: Hazrat Aus bin Aus Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke Khudaye Ta'ala ne Anbiya-e-Kiram Alaihimussalam ke jismon ko Zameen par (khana) Haram farma diya hai.", "explanation": "¥شرح حدیث 1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ پیغمبر خدا زندہ است بہ حقیقت حیات دنیاوی ‘‘۔ ([1])\nیعنی خدائے تعالیٰ کے نبی دنیوی زندگی کی حقیقت کے ساتھ زندہ ہیں۔ (اشعۃ اللمعات، جلد اول ص۶۷۵)\n اورحضرت مُلا علی قاری عَلَیْہِ رَحْمَۃُ اللّٰہ البَارِی اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ لَا فَرقَ لَھُمْ فِی الْحَالَیْنِ وَلِذَاقِیْلَ أَوْلِیَاءُ اللّٰہلَایَمُوْتُوْنَ وَلٰکِنْ یَنْتَقِلُوْنَ مِنْ دَارٍ إِلَی دَارٍ ‘‘۔ ([2])\nیعنی انبیائے کرام کی دنیوی اور بعد وصال کی زندگی میں کوئی فرق نہیں۔ اسی لیے کہا جاتا ہے کہ اولیائے کرام مرتے نہیں بلکہ ایک دار سے دوسرے دار کی طرف منتقل ہوجاتے ہیں۔ (مرقاۃ جلد دوم مطبوعہ بمبئی ص۲۱۲)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب الجمعۃ ، الفصل الثالث ، ج ۱، ص ۶۱۵.\n[2] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الصلاۃ ، الحدیث : ۱۳۶۶، ج ۳، ص ۴۵۹.\n¥شرح حدیث 2:\nحضرت مُلَّا علی قاری رضی عنہ ربّہ الباری اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ إِنَّ الْأَنْبِیَاء فِی قُبُوْرِھِمْ أَحْیَاء ‘‘۔ ([1])\nیعنی انبیائے کرام علیہم السلام اپنی قبروں میں زندہ ہیں۔ (مرقاۃ، جلد دوم ص ۲۰۹)\n اور حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اسی حدیث کی شرح میں فرماتے ہیں کہ:\n ’’ حیات انبیاء متفق علیہ است ہیچ کس را دروے خلافے نیست حیات جسمانی دنیاوی حقیقی نہ حیات معنوی روحانی چنانکہ شہدا راست ‘‘۔ ([2])\n یعنی انبیائے کر ام علیہم السلام زندہ ہیں اور ان کی زندگی سب مانتے آئے ہیں۔ کسی کو اس میں اختلاف نہیں ہے ۔ ان کی زندگی جسمانی حقیقی دنیاوی ہے ۔ شہیدوں کی طرح صرف معنوی اور روحانی نہیں ہے ۔ (اشعۃ اللمعات، جلد اول ص ۵۷۴)\n¥انتباہ :\n (۱)… انبیائے کرام علیہم السلام بعد وفات دنیوی زندگی کی حقیقت کے ساتھ زندہ رہتے ہیں اسی لیے شبِ معراج جب سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم بیت المقدس پہنچے تو انبیائے\n کرام علیہم السلام کو وہاں نماز پڑھائی۔ اگر انبیائے کرام علیہم السلام بعد وفات زندہ نہ ہوتے تو بیت المقدس میں نماز پڑھنے کے لیے کیسے آتے ۔\n (۲)…انبیائے کرام علیہم السلام کی زندگی جسمانی حقیقی دنیوی ہے ۔ شہیدوں کی طرح صرف معنوی اور رُوحانی نہیں ہے اسی لیے انبیائے کرام علیہم السلام کا ترکہ نہیں تقسیم کیا جاتا اور نہ ان کی بیویاں دوسرے سے نکاح کرسکتی ہیں۔ اور شہیدوں کا ترکہ تقسیم ہوتا ہے اور ان کی بیویاں عدت گزارنے کے بعد دوسرے سے نکاح کر سکتی ہیں۔\n (۳)…انبیائے کرام علیہم السلام کی زندگی برزخی نہیں بلکہ دنیوی ہے بس فرق صرف یہ ہے کہ ہم جیسے لوگوں کی نگاہوں سے اوجھل ہیں۔\n جیسا کہ حضرت شیخ حسن بن عمار شرنبلالی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اپنی مشہور کتاب ’’نورالایضاح ‘‘کی شرح ’’مراقی الفلاح ‘‘میں فرماتے ہیں:\n’’ وَمِمَّا ھُوَ مُقَرَّرٌ عِنْدَ الْمُحَقِّقِیْنَ أَنَّہُ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَیٌّ یُرْزَقُ مُمَتّعٌ بِجَمِیْعِ الملاذِّ وَالْعِبَادَاتِ غَیْرَ أَنَّہُ حجبَ عَنْ أَبْصَارِ الْقَاصِرِیْنَ عَنْ شَرِیْف المقَامَاتِ ‘‘۔ ([3])\nیعنی یہ بات اربابِ تحقیق علماء کے نزدیک ثابت ہے کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ (حقیقی دنیوی زندگی کے ساتھ) زندہ ہیں۔ ان پر روزی پیش کی جاتی ہے تمام لذت والی چیزوں کا مزا اور عبادتوں کا سرور پاتے ہیں۔ لیکن جو لوگ کہ بلند درجوں تک پہنچنے سے قاصر ہیں ان کی نگاہوں سے اوجھل ہیں۔ (مع طحطاوی مصری ص۴۴۷)\n اور نسیم الریاض شرح شفا قاضی عیاض جلد اول، ص:۱۹۶میں ہے :\n ’’ اَلأَنْبِیَاءُ عَلَیْھِمُ السَّلَامُ أَحْیَائٌ فِی قُبُوْرِھِمْ حَیَاۃً حَقِیْقَۃً ‘‘۔ ([4])\nیعنی انبیائے کرام علیہم السلام حقیقی زندگی کے ساتھ اپنی قبروں میں زندہ ہیں۔\n اور مرقاۃ شرح مشکوۃ جلد اول ص: ۲۸۴میں ہے :\n ’’ إِنَّہُ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَیٌّ یُرْزَقُ وَیُسْتَمَدُّ مِنْہُ الْمَدَدُ الْمُطْلَقُ ‘‘۔ ([5])\nیعنی بے شک حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم باحیات ہیں انہیں روزی پیش کی جاتی ہے اور ان سے ہرقسم کی مدد طلب کی جاتی ہے ۔\n اور حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے اپنے مکتوب سلوک أقرب السبل بالتوجہ إلی سید الرسل مع أخبار الأخیار مطبوعہ رحیمیہ دیوبند ص ۱۶۱ میں فرمایا کہ:\n ’’ باچندیں اختلاف و کثرت مذاہب کہ در علمائے امت ست یک کس رادریں مسئلہ خلافے نیست کہ آں حضرت صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم بحقیقتِ حیات بے شائبہ مجاز و توہم تاویل دائم و باقی ست وبراعمال اُمت حاضرو ناظر و مرطالبان حقیقت راو متوجہان آں حضرت رامضیض و مربی ‘‘۔\nیعنی علمائے امت میں اتنے اختلافات و کثرت مذاہب کے باوجود کسی شخص کو اس مسئلہ میں کوئی اختلاف نہیں ہے کہ آنحضرت صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم حیاتِ ( دنیوی) کی حقیقت کے ساتھ قائم اور باقی ہیں۔ اس حیات نبوی میں مجاز کی آمیزش اور تاویل کا وہم نہیں ہے اور امت کے اعمال پر حاضر و ناظر ہیں۔ نیز طالبانِ حقیقت کے لیے اور ان لوگوں کے لیے کہ آنحضرت کی جانب توجہ رکھتے ہیں حضور ان کو فیض بخشنے والے اور ان کے مربی ہیں۔\n (۴)…پارہ ۲۳ آخری رکوع کی آیت کریمہ ’’ إِنَّکَ مَیِّتٌ ‘‘میں جو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے لیے موت آنا ذکر فرمایا تو اس سے مراد اس عالم دنیا سے منتقل ہونا ہے اور ان احادیث کریمہ میں حیات سے بعد وصال کی حقیقی زندگی مراد ہے ۔\nتو زندہ ہے و اللّٰہ تو زندہ ہے و اللّٰہ \nمیری چشم عالم سے چھپ جانے والے\n(اعلی حضرت بریلوی)\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب الصلاۃ ، الحدیث : ۱۳۶۱، ج ۳، ص ۴۵۲۔ ۴۵۴.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب الصلاۃ ، باب الجمعۃ ، الفصل الثانی ، ج ۱، ص ۶۱۳.\n[3] ’’ مراقی الفلاح شرح نور الإیضاح ‘‘، کتاب الحج ، باب زیارۃ النبی صلی اللّٰہ علیہ وسلم ، ص ۴۳۰.\n[4] ’’ نسیم الریاض شرح شفا القاضی عیاض ‘‘، ج ۱، ص ۱۷۴.\n[5] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب المناسک ، الحدیث : ۲۷۵۶، ج ۵، ص ۶۳۲."}, {"id": 7820, "bookId": 14, "volNo": "1", "hadithNo": 52, "chapter": "حلال روزی کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَبْدِ اللّٰہ بْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ طَلَبُ کَسَبِ الْحَلالِ فَرِیْضَۃٌ بَعْدَ الْفَرِیْضَۃِ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی بَکْرٍ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَا یَدْخُلُ الْجَنَّۃَ جَسَدٌ غُذِّیَ بِالْحَرَامِ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَأْتِی عَلَی النَّاسِ زَمَانٌ لَا یُبَالِی الْمَرْءُ مَا أَخَذَ مِنْہُ أَ مِنَ الْحَلالِ أَمْ مِنَ الْحَرَامِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عبد اللّٰہ بن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ( شریعت کے دیگر) فرائض کے بعد حلال روزی حاصل کرنا فرض ہے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت ابوبکر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جس بدن کو حرام غذا دی گئی وہ جنت میں داخل نہ ہوگا۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ لوگوں پر ایک زمانہ ایسا بھی آئے گا جب کہ کوئی اس بات کی پروا نہ کرے گا کہ اس نے جو مال حاصل کیا وہ حلال ہے یا حرام۔ (بخاری شریف)", "roman": "Tarjuma Hadees 1: Hazrat Abdullah bin Mas'ood Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke (Shariat ke deegar) faraiz ke baad Halal rozi hasil karna Farz hai. (Baihaqi, Mishkat)\nTarjuma Hadees 2: Hazrat Abu Bakr Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jis badan ko Haram ghiza di gayi woh Jannat mein dakhil na hoga. (Baihaqi, Mishkat)\nTarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke logon par ek zamana aisa bhi aayega jab ke koi is baat ki parwah na karega ke us ne jo Maal hasil kiya woh Halal hai ya Haram. (Bukhari Shareef)", "explanation": "¥انتباہ :\n (۱)…چکی والے گیہوں وغیرہ پیسنے کے بعد فی کلو تیس چالیس گرام آٹا ’’جرتی‘‘ کہہ کر نکال لیتے ہیں یہ ناجائز و حرام ہے اس لیے کہ اتنی مقدار میں آٹا نہیں جلتا۔ ثبوت یہ ہے کہ چکی والے کے پاس دس پانچ کلو آٹا روزانہ فاضل بچ جاتا ہے ۔\n اور اگر چکی والے کچھ پیسا اور اپنے پیسے ہوئے میں سے کچھ آٹا اجرت ٹھہرادیں تویہ بھی ناجائز اس لیے کہ قفیز طحان ہے ۔ بہارِ شریعت جلدچہار دہم ص:۱۴۱ میں ہے ۔ اجارہ پر کام کرایا اور یہ قرار پایا کہ اسی میں سے اتنا تم اجرت لے لینا یہ اجارہ فاسد ہے مثلاً کپڑا بننے کے لیے سوت دیا اور کہہ دیا کہ آدھا کپڑا اجرت میں لے لینا یا غلہ اٹھا کر لاؤ اس میں سے دوسیر مزدوری لے لینا ، یا چکی چلانے کے لیے بیل لیے اور جو آٹا پیسا جائے گا اس میں سے اتنا اجرت میں دیا جائے گا ( یا کھیت کٹوایا اور اسی میں سے اجرت دینا طے کیا) یہ سب صورتیں ناجائز([1])ہیں۔ ملخصاً۔ ([2])\n ہاں پیسہ اور کچھ گیہوں یا باجرہ وغیرہ اجرت مقرر کریں تو جائز ہے ۔ بہار ِ شریعت میں ہے کہ جائز ہونے کی صورت یہ ہے کہ جو کچھ اجرت میں دینا ہے اس کو پہلے ہی سے علیحدہ کردے کہ یہ تمہاری اجرت ہے ۔ مثلاً سوت کو دو حصہ کرکے ایک حصہ کی نسبت کہا کہ اس کا کپڑا بُن دو اور دوسرا دیا کہ یہ تمہاری مزدوری ہے یا غلّہ اٹھانے والے کو اسی غلہ میں سے نکال کر دے دیا کہ یہ تیری مزدوری ہے اور یہ غلہ فلاں جگہ پہنچادے ( جیسا کہ) بھاڑ والے پہلے ہی اپنی بھنائی نکال کر باقی کو بھونتے ہیں۔ ([3])\n (۲)…بعض لوگ اس طرح کھیت کٹواتے ہیں کہ ہم فی بیگھہ یا ہر روز چار سیر دھان مزدوری دیں گے\nمگر یہ نہیں ٹھہراتے کہ ہم تمہارے کام کیے ہوئے میں سے دیں گے ۔ اب خواہ اسی کام کیے ہوئے میں سے دیں کوئی حرج([4])نہیں۔\n (۳)…کپڑا سلنے کے لیے دیا تو درزی نے اس میں سے کاٹ لیا۔ روئی کاتنے کے لیے دی تو کاتنے والے نے روئی نکال لی، کپڑا بننے کے لیے دیا تو بننے والے نے سوت نکال لیا اور بھرنے کے لیے دیاتو بھرنے والوں نے سوت نکال لیا یہ سب ناجائز و حرام ہے ۔\n افسوس کہ یہ باتیں علانیہ کھلے طور پر مسلمانوں میں اس طرح رائج ہوگئی ہیں کہ اب لوگوں کو احساس ہی نہیں ہوتا کہ ہم حرام روزی سے اپنا پیٹ بھر کر اپنی عاقبت برباد کررہے ہیں بلکہ عوام تو عوام بعض خواص بھی اس طرح حر ام روزی حاصل کرنے میں بے باک نظر آتے ہیں۔ اَلْعِیَاذُ بِاللّٰہ تَعَالَی ۔\nکرو مہر بانی تم اہل زمین پر\nخدا مہربان ہوگا عرش بریں پر\n-----------------\n[1] درمختار میں ہے : ’’ لَوْ دَفَعَ غَزْلًا لِآخَرَ لِیَنْسِجَہُ لَہُ بِنِصْفِہِ أَوْ اسْتَأْجَرَ بَغْلًا لِیَحْمِلَ طَعَامَہُ بِبَعْضِہِ أَوْ ثَوْرًا لِیَطْحَنَ بُرَّہُ بِبَعْضِ دَقِیقِہِ فَسَدَتْ فِی الْکُلِّ لِأَنَّہُ اسْتَأْجَرَہُ بِجُزْئٍ مِنْ عَمَلِہِ وَالْأَصْلُ فِی ذَلِکَ نَہْیُہُ صلی اللّٰہ علیہ وسلم عَنْ قَفِیزِ الطَّحَّانِ ‘‘۔ (’’ الدر المختار ‘‘، کتاب الاجارۃ ، ج ۹، ص ۹۷) اور فتاوی عالمگیری جلد چہارم مصری ص:۴۲۹ میں ہے :’’ لَا تَصِحُّ إجَارَۃُ الرَّحَی لِیَطْحَنَ بُرَّہُ بِبَعْضِ دَقِیقِہِ کَذَا فِی شَرْحِ أَبِی الْمَکَارِمِ ‘‘ ۱۲منہ۔ (’’ الفتاوی الھندیۃ ‘‘، کتاب الاجارۃ ، الباب الرابع عشر ، ج ۴، ص ۴۴۵)\n[2] ’’بہارِ شریعت‘‘، ج۳، ص۱۴۹.\n[3] ’’بہارِ شریعت‘‘، ج۳، ص۱۴۹.\n[4] درمختار کتاب الاجارہ میں ہے : ’’ وَالْحِیلَۃُ أَنْ یَفْرِزَ الْأَجْرَ أَوَّلًا أَوْ یُسَمِّیَ قَفِیزًا بِلَا تَعْیِینٍ ثُمَّ یُعْطِیَہُ قَفِیزًا مِنْہُ فَیَجُوزُ ‘‘۔ ۱۲ منہ ۔ (’’ الدر المختار ‘‘، کتاب الاجارۃ ، ج ۹، ص ۹۷)"}, {"id": 7821, "bookId": 14, "volNo": "1", "hadithNo": 53, "chapter": "اچھا تاجر کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی سَعِیدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ التَّاجِرُ الصَّدُوقُ الْأَمِینُ مَعَ النَّبِیِّینَ وَالصِّدِّیقِینَ وَالشُّہَدَاء‘‘۔ (ترمذی)\nحدیث 2:\n’’ عَنْ عُبَیْدِ بْنِ رِفَاعَۃَ عَنْ أَبِیہِ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ التُّجَّارُ یُحْشَرُوْنَ یَوْمَ الْقِیَامَۃِ فُجَّارًا إِلَّا مَنِ اتَّقَی وَبَرَّ وَصَدَقَ‘‘۔ \nحدیث 3:\n’’عَنْ وَاثِلَۃَ بْنِ الْأَسْقَعِ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَنْ بَاعَ عَیْبًا لَمْ یُبَیِّنْہُ لَمْ یَزَلْ فِی مَقْتِ اللّٰہ وَلَمْ تَزَلَ الْمَلاءِکَۃُ تَلْعَنُہُ‘‘۔", "urdu": "¥ترجمہ ضدیث 1:\nحضرت ابو سعید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ بہت سچے اور دیانت دار تاجر ( کا حشر) نبیوں، صدیقوں اور شہیدوں کے ساتھ ہوگا۔ ( علیہم السلام و رَضِیَ اللّٰہ تَعَالٰی عَنْہُم )\n¥ترجمہ ضدیث 2:\nحضرت عبید بن رفاعہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے روایت کرتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ قیامت کے دن (بددیانت) تاجروں کا حشر نافرمانوں کے ساتھ ہوگا مگر جو تاجر خدائے تعالی سے ڈرتے ہوئے حرام سے بچے ، جھوٹی قسم نہ کھائے اور سچ بولے ( تو اس کا حشر فاجروں کے ساتھ نہیں ہوگا) (ترمذی، ابن ماجہ)\n¥ترجمہ ضدیث 3:\nحضرت واثلہ بن اسقع رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ جو شخص عیب دار چیز بیچے اور اس کے عیب کو ظاہر نہ کرے وہ ہمیشہ اللّٰہ تعالیٰ کے غضب میں رہے گا۔ اور فرشتے اس پر لعنت کرتے رہیں گے ۔ (ابن ماجہ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Saeed Radiyallahu Anhu ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke bohat sachay aur diyanatdar tajir (ka hashr) Nabiyon, Siddiqon aur Shaheedon ke sath hoga. (Alaihimussalam wa Radiyallahu Anhum)\nTarjuma Hadees 2: Hazrat Ubaid bin Rifa'ah Radiyallahu Anhu apne baap se riwayat karte hain ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke Qayamat ke din (baddiyanat) tajiron ka hashr nafarmanon ke sath hoga magar jo tajir Khudaye Ta'ala se dartay huay Haram se bachay, jhooti qasam na khaye aur sach bolay (to us ka hashr faajiron ke sath nahi hoga). (Tirmidhi, Ibn Majah)\nTarjuma Hadees 3: Hazrat Wasilah bin Asqa Radiyallahu Anhu ne farmaya ke main ne Huzoor Sallallahu Alayhi wa Sallam ko farmatay huay suna ke jo shakhs aib-dar cheez bechay aur us ke aib ko zahir na kare woh hamesha Allah Ta'ala ke ghazab mein rahay ga. Aur farishtay us par la'nat karte rahen ge. (Ibn Majah)", "explanation": "¥انتباہ:\n (۱)… مردار کی چربی کو بیچنا یا اس سے کسی قسم کا نفع اٹھانا جائز نہیں۔ نہ اسے چراغ میں جلاسکتے ہیں۔ نہ چمڑا پکانے کے کام میں لاسکتے ہیں۔ ([1]) (شامی جلد۴، ص ۱۲۰، بہار شریعت، جلد ۱۱، ص ۵۷۸)\n (۲)…مردار کے چمڑے کو بھی بیچنا باطل ہے ۔ جو پکایا ہوا نہ ہو اور دباغت کرلی ہو تو بیچنا جائز ہے اور اس کو کام میں لانا بھی جائز ہے ۔ ([2]) (درمختار، بہار شریعت)\n دباغت کی تین صورتیں ہیں ، کھارے نمک وغیرہ کسی دوا سے پکایا جائے یا فقط دھوپ یا ہوا میں سکھا لیا جائے کہ تمام رطوبت خشک ہو کر بدبو جاتی رہے ۔ ([3]) (بہار شریعت)\n (۳)…کافر حربی کے ہاتھ مردار کی چربی اور چمڑا بیچنا جائز ہے ۔ ([4]) (بہار شریعت بحوالہ رد المحتار)\n (۴)…بعض لوگ گائے بکری بٹائی پر دیتے ہیں کہ جتنے بچے پیدا ہوں گے دونوں نصف نصف لیں گے یہ اجارہ فاسد اور ناجائز ہے ۔ بچے اسی کے ہیں جس کی گائے اور بکری ہے دوسرے کو صرف اس کے کام کی واجبی اجرت ملے گی۔ ([5]) (بہار شریعت، ج ۱۴، ص ۲۲۱۹)\n اور جیسا کہ شامی جلد سوم ص:۳۶۱میں ہے : ’’ إذَا دَفَعَ الْبَقَرَۃَ بِالْعَلَفِ لِیَکُونَ الْحَادِثُ بَیْنَہُمَا نِصْفَیْنِ فَمَا حَدَثَ فَہُوَ لِصَاحِبِ الْبَقَرَۃِ وَلِلْآخَرِ مِثْلُ عَلَفِہِ وَأَجْرُ مِثْلِہِ تَتَارْخَانِیَّۃٌ ‘‘۔ ([6])\n اسی طرح فتاویٰ عالمگیری جلد چہارم مصری ص:۴۳۰ میں بھی ہے ۔ ([7])\n (۵)…کسی کو مرغی دی کہ جتنے انڈے دے گی دونوں نصف نصف تقسیم کرلیں گے یہ اجارہ بھی فاسد اور ناجائز ہے ۔ انڈے اسی کے ہیں جس کی مرغی ہے ۔ ([8]) (فتاوی عالمگیری مصری، جلد ۴، ص ۴۳۰، بہار شریعت، جلد ۱۴، ص ۱۴۳)\n (۶)…کسی چیز کی قیمت زیادہ مانگنا پھر اس سے کم مانگنا پھر اس سے کم پر دے دینا جائز ہے ۔ یہ جھوٹ میں داخل نہیں ہے ۔\n (۷)…تالابوں، جھیلوں کا مچھلیوں کے شکار کے لیے ٹھیکہ دینا جیسا کہ ہندوستان میں رائج ہے ناجائز ہے ۔ ([9]) (بہار شریعت، جلد ۱۱ ص۸۷)\n اور جیسا کہ درمختار باب البیع الفاسدمیں ہے ۔ ’’ وَلَمْ تَجُزْ إجَارَۃُ بِرْکَۃٍ لِیُصَادُ مِنْہَا السَّمَکُ ‘‘۔ ([10])\n------------------\n[1] ’ ’’بہارِ شریعت‘‘، ج۲، ص ۷۰۸، ’’ رد المحتار ‘‘، کتاب البیوع ، باب البیع الفاسد ، ج ۷، ص ۲۶۷.\n[2] ’’بہارِ شریعت‘‘، ج۲، ص ۷۰۷، ’’ الدر المختار ‘‘، کتاب البیوع ، باب البیع الفاسد ، ج ۷، ص ۲۶۵.\n[3] ’’بہارِ شریعت‘‘، ج۱، ص۴۰۲، ’’ الدر المختار ورد المحتار ‘‘، کتاب الطہارۃ ، ج ۱، ص ۳۹۳۔ ۳۹۵.\n[4] ’’بہارِ شریعت‘‘، ج۲، ص۷۷۵، ’’ رد المحتار ‘‘، کتاب البیوع ، باب الربا ، ج ۷، ص ۴۴۲.\n[5] ’’بہارِ شریعت‘‘، ج۳، ص۱۵۱، ’’ الفتاوی الھندیۃ ‘‘، کتاب الشرکۃ ، الباب الخامس فی الشرکۃ الفاسدۃ ، ج ۲، ص ۳۳۵.\n[6] ’’ رد المحتار ‘‘، کتاب الشرکۃ ، مطلب یرجح القیاس ، ج ۶، ص ۴۹۹.\n[7] ’’ الفتاوی الھندیۃ ‘‘، کتاب الشرکۃ ، الباب الخامس فی الشرکۃ الفاسدۃ ، ج ۲، ص ۳۳۵.\n[8] ’’بہارِ شریعت‘‘، ج۳، ص۱۵۱، ’’ الفتاوی الھندیۃ ‘‘، کتاب الشرکۃ ، الباب الخامس فی الشرکۃ الفاسدۃ ، ج ۲، ص ۳۳۵.\n[9] ’’بہارِ شریعت‘‘، ج۲، ص۱۵۱، ’’ الدر المختار ‘‘، کتاب البیوع ، باب البیع الفاسد ، ج ۷، ص ۲۴۸.\n[10] ’’ الدر المختار ‘‘، کتاب البیوع ، مطلب فی حکم إیجار البرک للاصطیاد ، ج ۷، ص ۲۴۹."}, {"id": 7822, "bookId": 14, "volNo": "1", "hadithNo": 54, "chapter": "سود کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ جَابِرٍ قَالَ لَعَنَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ آکِلَ الرِّبَا وَمُؤْکِلَہُ وَکَاتِبَہُ وَشَاہِدَیْہِ وَقَالَ ہُمْ سَوَاء ٌ‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ اللّٰہ بْنِ حَنْظَلَۃَ غَسِیلِ الْمَلَاءِکَۃِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ دِرْہَم رِبًا یَأْکُلُہُ الرَّجُلُ وَہُوَ یَعْلَمُ أَشَدُّ مِنْ سِتَّۃٍ وَثَلاثِینَ زنْیَۃً‘‘۔\nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الرِّبَا سَبْعُونَ جُزْءً أَیْسَرُہَا أَنْ یَنْکِحَ الرَّجُلُ أُمَّہُ‘‘۔ \nحدیث 4:\n’’ عَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَقْرَضَ أَحَدُکُمْ قَرْضًا فَأَہْدَی إِلَیْہِ أَوْ حَمَلَہُ عَلَی الدَّابَّۃِ فَلا یَرْکَبہُ وَلَا یَقْبَلْہَا إِلَّا أَنْ یَکُونَ جَرَی بَیْنَہُ وَبَیْنَہُ قَبْلَ ذَلِکَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے سود لینے والوں، سود دینے والوں، سودی دستاویز لکھنے والوں اور اس کے گواہوں پر لعنت فرمائی ہے ۔ اور فرمایا کہ وہ سب ( گناہ میں) برابر کے شریک ہیں۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن حنظلہ غسیل الملائکہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلوۃو السلام نے فرمایا کہ سود کا ایک درہم جسے آدمی جان بوجھ کر کھائے اس کا گناہ چھتیس بار زنا کرنے سے زیادہ ہے ۔ (احمد، دار قطنی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ سود (کا گناہ) ایسے ستّر گناہوں کے برابر ہے جن میں سب سے کم درجہ کا گناہ یہ ہے کہ مرد اپنی ماں سے زنا کرے ۔ (ابن ماجہ ، بیہقی)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص کسی کو قرض دے اور پھر قرض لینے والا اس کے پاس کوئی ہدیہ اور تحفہ بھیجے یا سواری کے لیے کوئی جانور پیش کرے تو اس سواری پر سوار نہ ہو اور اس کا ہدیہ اور تحفہ قبول نہ کرے البتہ قرض دینے سے پہلے آپس میں اس قسم کا معاملہ ہوتا رہا ہو تو کوئی حرج نہیں۔ (ابن ماجہ، بیہقی)", "roman": "Tarjuma Hadees 1: Hazrat Jabir Radiyallahu Anhu ne farmaya ke Huzoor Sallallahu Alayhi wa Sallam ne Sood lene walon, Sood dene walon, Soodi dastaveez likhne walon aur us ke Gawahon par la'nat farmayi hai. Aur farmaya ke woh sab (gunah mein) barabar ke shareek hain. (Muslim Shareef)\nTarjuma Hadees 2: Hazrat Abdullah bin Hanzala Ghaseel-ul-Malaika Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke Sood ka ek Dirham jisay aadmi jaan boojh kar khaye us ka gunah chhatees baar zina karne se zyada hai. (Ahmad, Dar Qutni, Mishkat)\nTarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Sood (ka gunah) aisay sattar gunahon ke barabar hai jin mein sab se kam darja ka gunah ye hai ke Mard apni maa se zina kare. (Ibn Majah, Baihaqi)\nTarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs kisi ko Qarz de aur phir Qarz lene wala us ke paas koi hadiya aur tohfa bhejay ya sawari ke liye koi janwar pesh kare to us sawari par sawar na ho aur us ka hadiya aur tohfa Qubool na kare albatta Qarz dene se pehle aapas mein is qisam ka muamla hota raha ho to koi haraj nahi. (Ibn Majah, Baihaqi)", "explanation": "¥شرح حدیث 4:\nحضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کی شرح میں فرماتے ہیں کہ:\n’’ ہر قرضے کہ بکشد سودے را پس آں ربوا است ‘‘۔ ([1])\n یعنی ہر وہ قرض کہ جس سے نفع حاصل ہو سود ہے ۔ (اشعۃ اللمعات، جلد سوم ص ۲۵)\n¥انتباہ:\n (۱)… سود حرام قطعی ہے اس کی حرمت کا منکر کافر ہے حرام سمجھ کر سود لینے والا فاسق مردود الشہادت ہے ۔ ([2])(بہار شریعت)\n (۲)…عقد فاسد کے ذریعہ کافر حربی کا مال حاصل کرنا ممنوع نہیں یعنی جو عقد مابین دو مسلمان ممنوع ہے اگر کافر حربی کے ساتھ کیا جائے تو منع نہیں مگر شرط یہ ہے کہ وہ عقد مسلم کے لیے مفید ہو۔ مثلاً ایک روپیہ کے بدلے میں دو روپیہ خریدے یا اس کے ہاتھ مردار کو بیچ ڈالا کہ اس طریقہ پر مسلمان سے روپیہ حاصل کرنا شرع کے خلاف اور حرام ہے اور کافر سے حاصل کرنا جائز ہے ۔ ([3])(شامی، بہار شریعت، ج ۱۱ ، ص۱۵۳)\n (۳)… ہندوستان اگرچہ دار الاسلام ہے اس کو دارالحرب کہنا صحیح نہیں مگر یہاں کے کفار یقیناً نہ تو ذمی ہیں نہ مستامن کیونکہ ذمی یا مستامن کے لیے بادشاہ اسلام کا ذمہ اور امن دینا ضروری ہے لہذا یہاں کے کفار کے اموال عقودِ فاسدہ کے ذریعہ حاصل کیے جاسکتے ہیں جب کہ بدعہدی نہ ہو۔ ([4]) (بہار شریعت، جلد ۱۱ ص۱۵۳)\n (۴)…ہندوستانی کفار کا مال چوری ، ڈاکہ ، مکاری اور فریب سے حاصل کرنا جائز نہیں۔\n (۵)…انڈیا گورنمنٹ کی طرف سے جگہ جگہ جو بلاک قائم ہیں وہاں سے روپیہ وغیرہ زائد رقم دینے کی شرط پر بلا ضرورت لانا اور انہیں نفع دینا منع ہے ۔\n (۶)…بینک خواہ انڈیا ( غیر مسلم حکومت) کا ہو یا کسی کافر حربی کا اس کا نفع شرعاً سود نہیں اسی طرح انڈیا گورنمنٹ یا کافری حربی کے مسلم ملازمین کو فنڈ کا جو نفع ملتا ہے وہ بھی سود نہیں۔ البتہ مسلم بینک کا نفع سود ہے ۔\nفتاویٰ عزیزیہ جلد اول ص :۳۹ پر ہے :’’ گرفتن سود از حربیاں بایں وجہ حلال است کہ مال حربی مباح ست اگر در ضمن آں نقص عہد نہ باشد وحربی چوں خود بخود بدہد بلاشبہ حلال خواہد بود ‘‘۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب البیوع ، باب الربوا ، الفصل الثالث ، ج ۳، ص ۲۵.\n[2] ’’بہارِ شریعت‘‘، ج۲، ص ۷۶۸.\n[3] ’’بہارِ شریعت‘‘، ج۲، ص ۷۷۵، ’’ رد المحتار ‘‘، کتاب البیوع ، مطلب فی استقراض الدراھم عددا ، ج ۷، ص ۴۴۲.\n[4] ’’بہارِ شریعت‘‘، ج۲، ص ۷۷۶."}, {"id": 7823, "bookId": 14, "volNo": "1", "hadithNo": 55, "chapter": "رہن اور بیع سلم کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَدِمَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْمَدِینَۃَ وَہُمْ یُسْلِفُونَ فِی الثِّمَارِ السَّنَۃَ وَالسَّنَتَیْنِ وَالثَّلاثَ فَقَالَ مَنْ أَسْلَفَ فِی شَیْئٍ فَلْیُسْلِفْ فِی کَیْلٍ مَعْلُومٍ وَوَزْنٍ مَعْلُومٍ إِلَی أَجَلٍ مَعْلُومٍ‘‘۔ \nحدیث 2:\n’’ عَنْ سَعِیدِ بْنِ الْمُسَیِّبِ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَا یَغْلَقُ الرَّہْنُ الرَّھْنَ مِنْ صَاحِبِہِ الَّذِیْ رَھَنَہُ لَہُ غُنْمُہُ وَعَلَیْہِ غُرْمُہُ ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم مدینہ طیبہ میں تشریف لائے مدینہ کے لوگ پھلوں میں سال دو سال اور تین سال کی ( پیشگی) بیع کیا کرتے تھے ۔ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جو شخص اس طرح کی بیع کرے اسے چاہیے کہ معین پیما نہ معین وزن اور معین مدت کے ساتھ کرے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت سعید بن المسیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ سرکارِ دوعالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ کسی چیز کو رہن کردینے سے رہن کرنے والے کی ملکیت ختم نہیں ہوجاتی اس کے منافع کا حق دار راہن([1])ہے اور ( چیز ضائع ہوجائے تو) مرتہن ([2]) تاوان کا ذمہ دار ہے ۔ (مشکوۃ)\n------------------\n[1] راہن جو دوسرے کے پاس کوئی چیز رکھے ۔ ۱۲\n[2] مرتہن جس کے پاس کوئی چیز رہن رکھی جائے ۔ ۱۲", "roman": "Tarjuma Hadees 1: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam Madina Tayyaba mein tashreef laye Madina ke log phalon mein saal do saal aur teen saal ki (peshgi) Bai kiya karte thay. Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs is tarah ki Bai kare usay chahiye ke mu'ayyan paimana, mu'ayyan wazan aur mu'ayyan muddat ke sath kare. (Bukhari, Muslim)\nTarjuma Hadees 2: Hazrat Saeed bin Al-Musayyab Radiyallahu Anhu se riwayat hai ke Sarkar-e-Do-Aalam Sallallahu Alayhi wa Sallam ne farmaya ke kisi cheez ko Rahn kar dene se Rahn karne walay ki malkiyat khatam nahi ho jati us ke manafa ka haqdar Rahin hai aur (cheez zaya ho jaye to) Murtahin tawan ka zimmedar hai. (Mishkat)", "explanation": "¥انتباہ :\n (۱)… بیع سلم یعنی ایسی خرید و فروخت کہ جس میں قیمت نقد اورمال ادھار ہو جائز ہے ۔ مثلاً زید نے فصل تیار ہونے سے پہلے بکر سے کہا کہ آپ سو روپیہ ہمیں دے دیجئے ہم فی روپیہ چار کلو گیہوں آپ کو فلاں تاریخ میں دے دیں گے ۔ تو خواہ اس وقت یا ادائیگی کے وقت بازار کا بھاؤ فی روپیہ تین کلو ہو زید پر فی روپیہ چار کلو گیہوں دینا واجب ہوگا اس لیے کہ یہ بیع شرعاً جائز ہے بہ شرطیکہ مسلم فیہ([1]) کی جنس بیان کردی جائے کہ گیہوں دے گا یا جَو۔ اور اس کی نوع بیان کردی جائے کہ فلاں نام کا گیہوں دے گا اور یہ بھی بیان کرنا ضروری ہے کہ وہ گیہوں اعلیٰ ہوگا یا اوسط یا ادنیٰ ۔ نیز یہ بھی بتانا ضروری ہے کہ گیہوں کتنا دے گا؟ کس تاریخ میں دے گا اور کس جگہ دے گا اور بھی کچھ شرطیں ہیں جن کی تفصیلات بہارِ شریعت وغیرہ سے معلوم کریں۔\n (۲)…کھیت رہن رکھنے کا جو عام رواج ہے کہ کسی شخص کو کچھ روپیہ دے کر اس کا کھیت اس شرط پر رہن رکھتے ہیں کہ ہم کھیت سے نفع حاصل کرتے رہیں گے اور گورنمنٹی لگان دیتے رہیں گے ۔ پھر جب تم روپیہ ادا کرو گے تو ہم کھیت واپس کردیں گے یہ ناجائز ہے ۔ اس لیے کہ قرض دے کر نفع حاصل کرنا سود ہے حرام ہے ۔\n حدیث شریف میں ہے :\n’’ کُلُّ قَرْضٍ جَرّ نَفْعًا فَھُوَ رِبًا ‘‘۔\nیعنی قرض سے جو نفع حاصل ہو وہ سود ہے ۔\nالبتہ کافر حربی کا کھیت اس طرح لے سکتا ہے اس لیے کہ عقود فاسد ہ کے ذریعہ ان کا مال لینا جائز ہے ۔\n (۳)…بعض لوگ کھیت اس طرح رہن رکھتے ہیں کہ مرتہن کھیت کو جوتے بوئے فائدہ حاصل کرے ۔ اور کھیت کا دس پانچ روپیہ سال کرایہ مقرر کردیتے ہیں اور طے یہ پاتا ہے کہ وہ رقم زرِ قرض سے مجرا ہوتی رہے گی جب کل رقم ادا ہوجائے گی تو کھیت واپس ہوجائے گا۔ اس صورت میں بظاہر کوئی قباحت نہیں معلوم ہوتی اگرچہ کرایہ واجبی اجرت سے کم طے پایا ہو اس لیے کہ یہ صورت اجارہ میں داخل ہے یعنی اتنے زمانہ کے لیے کھیت کرایہ پر دیا اور کرایہ پیشگی لے لیا۔ ([2]) (بہار شریعت، جلد ہفدہم ص ۳۹)\n------------------\n[1] مسلم فیہ۔ جس چیز کو فروخت کیا گیا ۱۲۔ \n[2] ’’بہارِ شریعت‘‘، حصہ ہفدہم ، باب رہن کا بیان ، ص۳۹."}, {"id": 7824, "bookId": 14, "volNo": "1", "hadithNo": 56, "chapter": "قرضدارکو مہلت دینا کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِیْ قَتَادَۃَ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ مَنْ أَنْظَرَمُعْسِرًا أَوْ وَضَعَ عَنْہُ أَنْجَاہُ اللّٰہ مِنْ کُرَبِ یَوْمِ الْقِیَامَۃِ‘‘۔ \nحدیث 2:\n’’عَنْ عِمْرَانَ بْنِ حُصَیْنٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ کَانَ لَہُ عَلَی رَجُلٍ حَقٌّ فَمَنْ أَخَّرَہُ کَانَ لَہُ بِکُلِّ یَوْمٍ صَدَقَۃٌ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ نَفْسُ الْمُؤْمِنِ مُعَلَّقَۃٌ بِدَیْنِہِ حَتَّی یُقْضَی عَنْہُ‘‘۔ \nحدیث 4:\n’’ عَنْ عَبْدِ اللّٰہ بْنِ عَمْرِو أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ یُغْفَرُ لِلشَّہِیدِ کُلُّ ذَنْبٍ إِلَّا الدَّیْنَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوقتادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم کو فرماتے ہوئے سنا کہ جو شخص قرضدار کو مہلت دے یا قرض معاف کردے تو اللّٰہ تعالیٰ اس کو قیامت کے دن کی سختیوں سے محفوظ رکھے گا۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت عمران بن حصین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس کا کسی شخص پر کوئی حق ہو وہ اسے مہلت دے تو اسے ہر دن کے عوض صدقہ کا ثواب ملے گا۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ مومن کی جان اپنے قرض کے سبب معلق رہتی ہے جب تک کہ اس کا قرض ادا نہ کردیا جائے ۔ \n¥ترجمہ حدیث 4:\nحضرت عبد اللّٰہ بن عمرو رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ شہید کے سب گناہ بخش دیئے جاتے ہیں سوائے قرض کے ۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Abu Qatada Radiyallahu Anhu ne kaha ke main ne Rasool-e-Kareem Sallallahu Alayhi wa Sallam ko farmatay huay suna ke jo shakhs Qarzdar ko mohlat de ya Qarz maaf kar de to Allah Ta'ala us ko Qayamat ke din ki sakhtiyon se mehfooz rakhay ga. (Muslim Shareef)\nTarjuma Hadees 2: Hazrat Imran bin Haseen Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke jis ka kisi shakhs par koi haq ho woh usay mohlat de to usay har din ke ewaz Sadaqah ka sawab milay ga. (Ahmad, Mishkat)\nTarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke Momin ki jaan apne Qarz ke sabab mu'allaq rehti hai jab tak ke us ka Qarz ada na kar diya jaye.\nTarjuma Hadees 4: Hazrat Abdullah bin Amr Radiyallahu Anhu se marwi hai ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke Shaheed ke sab gunah bakhsh diye jatay hain siwaye Qarz ke. (Muslim Shareef)", "explanation": "*****"}, {"id": 7825, "bookId": 14, "volNo": "1", "hadithNo": 57, "chapter": "زمین پر ناجائز قبضہ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ سَالِمٍ عَنْ أَبِیہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَخَذَ مِنَ الْأَرْضِ شَیْءًا بِغَیْرِ حَقِّہِ خُسِفَ بِہِ یَوْمَ الْقِیَامَۃِ إِلَی سَبْعِ أَرْضِیْنَ‘‘۔ \nحدیث 2:\n’’ عَنْ سَعِیدِ بْنِ زَیْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَخَذَ شِبْرًا مِنَ الْأَرْضِ ظُلْمًا فَإِنَّہُ یُطَوَّقُہُ یَوْمَ الْقِیَامَۃِ مِنْ سَبْعِ أَرْضِیْنَ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِیْ حُرَّۃَ الرَّقَاشِیّ عَنْ عمِّہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اَلا لَا تَظْلِمُوْا اَلا لَا یَحِلُّ مَالُ اِمْرَیئٍ اِلَّا بِطِیْبِ نَفْسٍ مِنْہُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت سالم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے روایت کرتے ہیں کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ جو شخص دوسرے کی زمین کا کچھ حصہ ناحق دبالے تو اسے قیامت کے دن سات زمینوں کی (تہ) تک دھنسایا جائے گا۔ (بخاری شریف)\n¥ترجمہ حدیث 2:\nحضرت سعید بن زید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص کسی کی بالشت بھر زمین ظلم سے حاصل کرے گا اسے قیامت کے دن سات زمینوں کا طوق پہنایا جائے گا۔ (مسلم، بخاری)\n¥ترجمہ حدیث 3:\nحضرت ابوحرہ رقاشی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے چچا سے روایت کرتے ہیں کہ انہوں نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایاکہ خبردار!(کسی پر)ظلم نہ کرنا (اور) کان کھول کر سن لو کہ کسی شخص کا مال(تمہارے لیے ) حلال نہیں ہوسکتا مگر وہ خوشی دل سے راضی ہوجائے ۔ (بیہقی)", "roman": "Tarjuma Hadees 1: Hazrat Salim Radiyallahu Anhu apne baap se riwayat karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs dusre ki Zameen ka kuch hissa na-haq daba le to use Qiyam ke din saat Zameenon ki (teh) tak dhansaya jayega. (Bukhari Sharif). Tarjuma Hadees 2: Hazrat Saeed Bin Zaid Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs kisi ki baalisht bhar Zameen zulm se hasil karega use Qiyam ke din saat Zameenon ka tauq pehnaya jayega. (Muslim, Bukhari). Tarjuma Hadees 3: Hazrat Abu Hurrah Raqashi Radiyallahu Anhu apne chacha se riwayat karte hain ke unhon ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke khabardar! (kisi par) zulm na karna (aur) kaan khol kar sun lo ke kisi shakhs ka Maal (tumhare liye) Halal nahi ho sakta magar woh khushi dil se raazi ho jaye. (Baihaqi)", "explanation": "*****"}, {"id": 7826, "bookId": 14, "volNo": "1", "hadithNo": 58, "chapter": "نکاح کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَبْدِ اللّٰہ بْنِ مَسْعُوْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَا مَعْشَرَ الشَّبَابِ مَنِ اسْتَطَاعَ مِنْکُمُ الْبَاءَ ۃَ فَلْیَتَزَوَّجْ فَإِنَّہُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ وَمَنْ لَمْ یَسْتَطِعْ فَعَلَیْہِ بِالصَّوْمِ فَإِنَّہُ لَہُ وِجَاء ٌ‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الدُّنْیَا کُلُّہَا مَتَاعٌ وَخَیْرُ مَتَاعِ الدُّنْیَا الْمَرْأَۃُ الصَّالِحَۃُ‘‘۔ \nحدیث 3:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَمْ تَرَ لِلْمُتَحَابَّیْنِ مِثْلَ النِّکَاحِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عبد اللّٰہ بن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اے نوجوانو! تم میں سے جو شخص نکاح کی استطاعت رکھتا ہے وہ نکاح کرے کہ یہ ( اجنبی عور ت کی طرف سے )نگاہ کو روکنے والا، شرمگاہ کی حفاظت کرنے والا ہے اور جس میں نکاح کی استطاعت نہ ہو وہ روزے رکھے اس لیے کہ روزہ شہوت کو توڑ تا ہے ۔ (بخاری ، مسلم)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن عمرو رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ ساری دنیا ایک متاع زندگی ہے اور دنیا کی بہترین متا ع نیک عورت ہے ۔ (مسلم)\n¥ترجمہ حدیث 3:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ رشتہ نکاح کے سوا (اور کوئی رشتہ)دیکھنے میں نہیں آیا جو دو اجنبی آدمیوں کے درمیان اتنی گہری محبت پیدا کردے ۔ (ابن ماجہ)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke ae naujawano! tum mein se jo shakhs Nikah ki istita'at rakhta hai woh Nikah kare ke yeh (ajnabi Aurat ki taraf se) nigah ko rokne wala, Sharmgah ki hifazat karne wala hai aur jis mein Nikah ki istita'at na ho woh Roza rakhe is liye ke Roza shahwat ko todta hai. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abdullah Bin Amr Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Saari duniya ek mata-e-Zindagi hai aur duniya ki behtareen mata-e-neik Aurat hai. (Muslim). Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke rishta Nikah ke siwa (aur koi rishta) dekhne mein nahi aaya jo do ajnabi admiyon ke darmiyan itni gehri Mohabbat paida kar de. (Ibn Majah)", "explanation": "¥انتباہ:\n (۱)…جو شخص مہرو نفقہ کی قدرت رکھتا ہو اس کے نکاح کرنے کی تفصیل یہ ہے کہ اگر اسے یقین ہو کہ بحالتِ تجرد وہ زنا کی معصیت میںمبتلا ہوجائے گا تو نکاح کرنا فرض ہے اور اگر اس کا یقین نہیں بلکہ صرف اندیشہ ہے تو نکاح کرنا واجب ہے اور شہوت کا بہت زیادہ غلبہ نہ ہو تو نکاح کرنا سنت مؤکدہ ہے اور اگر اس بات کا اندیشہ ہے کہ نکاح کرے گا تو نان و نفقہ نہ دے سکے گا یا نکاح کے بعد جو فرائض متعلقہ ہیں انہیں پورا نہ کرسکے گا تو نکاح کرنا مکروہ ہے اور اگر ان باتوں کا اندیشہ ہی نہیں بلکہ یقین ہو تو نکاح کر نا حرام ہے ۔ ([1]) (درمختار، رد المحتار، بہار شریعت)\n (۲)…بعض لوگ بیوہ عورتوں کا نکاح کرنا خاندان کے لیے عار سمجھتے ہیں یہ سخت ناجائز و گناہ ہے ۔\n (۳)…مرتد و مرتدہ کا نکاح کسی سے صحیح نہیں ہوسکتا نہ مسلمان سے نہ کافر سے نہ مرتدہ و مرتد سے ۔ ([2])\n (بہار شریعت بحوالہ درمختار)\n اور جیسا کہ فتاویٰ عالمگیری جلد اول مصری ص: ۲۶۳میں ہے :\n ’’ لَا یَجُوزُ لِلْمُرْتَدِّ أَنْ یَتَزَوَّجَ مُرْتَدَّۃً وَلَا مُسْلِمَۃً وَلَا کَافِرَۃً أَصْلِیَّۃً وَکَذَلِکَ لَا یَجُوزُ نِکَاحُ الْمُرْتَدَّۃِ مَعَ أَحَدٍ ، کَذَا فِی الْمَبْسُوطِ ‘‘ ۔ ([3])\nیعنی مرتدہ مسلمہ اور کافرہ اصلیہ سے مرتد کا نکاح کرنا جائز نہیں۔ اور ایسا ہی مر تدہ کا نکاح کسی سے جائز نہیں ہے ۔ ایسا ہی مبسوط میں ہے ۔\n (۴)…وہابیوں، دیوبندیوں ، رافضیوں ، نیچریوں، وغیرہ بددینوں کے ساتھ رشتہ نکاح قائم کرنا اہل سنت کے لیے ہر گز جائز نہیں۔\n (۵)…پورے ہندوستان میں عام طور پر جو رائج ہے کہ عورت یا ولی سے ایک شخص اذن لے کرآتا ہے جسے وکیل کہتے ہیں وہ نکاح پڑھانے والے سے کہہ دیتا ہے کہ میں فلاں کا وکیل ہوں آپ کو اجازت دیتا ہوں کہ نکاح پڑھا دیجئے ۔ یہ طریقہ محض غلط ہے ۔ وکیل کو یہ اختیار نہیں کہ اس کام کے لیے دوسرے کو وکیل بنادے اگر ایسا کیا گیا تو نکاح فضولی ہوا ( عورت کی) اجازت پر موقوف رہے گا اجازت سے پہلے مرد و عورت ہر ایک کو توڑ دینے کا اختیار حاصل ہے ۔ لہذا یوں چاہیے کہ جو نکاح پڑھائے وہ خود عورت یا اس کے ولی کا وکیل بنے ۔ ([4]) (بہار شریعت)\n یا پھر عورت کا وکیل اس بات کی بھی اجازت حاصل کرے کہ وہ نکاح پڑھانے کے لیے دوسرے کو وکیل بناسکتا ہے ۔\n (۶)…بعض لوگ ایجاب و قبول کے الفاظ بہت آہستہ بولتے ہیں اگر اس قدر آہستہ بولے کہ حاضرین میں سے دوآدمیوں نے بھی ایجاب و قبول کے الفاظ نہ سنے تو نکاح نہ ہوا۔\n (۷)…نکاح سے پہلے لڑکی اور لڑکا کو کلمۂ طیبہ اور ایمان مجمل و مفصل پڑھانا جیسا کہ رائج ہے بہتر ہے ۔\n (۸)…خطبۂ نکاح ایجاب و قبول سے پہلے پڑھنا مستحب ہے ۔\n٭…٭…٭…٭\n¥خطبۂ نکاح\n اَلْحَمْدُ لِلَّہِ نَحْمَدُہُ وَنَسْتَعِینُہُ وَنَسْتَغْفِرُہُ وَنُؤْمِنُ بِہِ وَنَتَوَکَّلُ عَلَیْہِ وَنَعُوذُ بِاللّٰہ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَیِّءَاتِ أَعْمَالِنَا مَنْ یَہْدِہِ اللّٰہ فَلَا مُضِلَّ لَہُ وَمَنْ یُضْلِلْہُ فَلَا ہَادِیَ لَہُ ، وَأَشْہَدُ أَنْ لَا إلَہَ إلَّا اللّٰہ وَحْدَہُ لَا شَرِیکَ لَہُ ، وَأَشْہَدُ أَنَّ مُحَمَّدًا عَبْدُہُ وَرَسُولُہُ ۔ أَعُوذُ بِاللّٰہ مِنَ الشَّیْطَانِ الرَّجِیمِ بِسْمِ اللّٰہ الرَّحْمَنِ الرَّحِیمِ ۔ یَا أَیُّہَا النَّاسُ اتَّقُوا رَبَّکُمُ الَّذِی خَلَقَکُمْ مِنْ نَفْسٍ وَاحِدَۃٍ وَخَلَقَ مِنْہَا زَوْجَہَا وَبَثَّ مِنْہُمَا رِجَالًا کَثِیرًا وَنِسَاءً وَاتَّقُوا اللّٰہ الَّذِی تَسَاءَ لُونَ بِہِ وَالْأَرْحَامَ إِنَّ اللّٰہ کَانَ عَلَیْکُمْ رَقِیبًا ۔ یَأَیُّہَا الَّذِینَ آمَنُوا اتَّقُوا اللّٰہ حَقَّ تُقَاتِہِ وَلَا تَمُوتُنَّ إلَّا وَأَنْتُمْ مُسْلِمُونَ ۔ یَأَ یُّہَا الَّذِینَ آمَنُوا اتَّقُوا اللّٰہ وَقُولُوا قَوْلًا سَدِیدًا ۔ یُصْلِحْ لَکُمْ أَعْمَالَکُمْ وَیَغْفِرْ لَکُمْ ذُنُوبَکُمْ وَمَنْ یُطِعِ اللّٰہ وَرَسُولَہُ فَقَدْ فَازَ فَوْزًا عَظِیمًا ۔ صَدَقَ اللّٰہ الْعَلِیُّ الْعَظِیْمُ ۔ وَصَدَقَ رَسُوْلُہُ النَّبِیُّ الْکَرِیْمُ ۔ وَنَحْنُ عَلَی ذَلِکَ مِنَ الشَّاھِدِیْنَ وَالْحَمْدُ لِلَّہِ رَبِّ الْعَلَمِیْنَ ۔\n٭…٭…٭…٭\n¥دعا بعد نکاح\n أَللَّہُمَّ اَلِّفْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا آدَمَ وَحَوَّآء عَلَی نَبِیِّنَا وَعَلَیْہِمَا الصَّلَاۃُ وَالسَّلَامُ ۔ أَللَّہُمَّ اَلِّفْْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا اِبْرَاھِیْمَ وَسَارَۃَ عَلَی نَبِیِّنَا وَعَلَیْہِمَا الصَّلَاۃُ وَالسَّلَامُ ۔ أَللَّہُمَّ اَلِّفْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا یُوْسُفَ وَزُلَیْخَآ عَلَی نَبِیِّنَا وَعَلَیْہِمَا الصَّلَاۃُ وَالسَّلَامُ ۔ أَللَّہُمَّ اَلِّفْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا سُلَیْمَانَ وَبِلْقِیْسَ عَلَی نَبِیِّنَا وَعَلَیْہِمَا الصَّلَاۃُ وَالسَّلَامُ ۔ أَللَّہُمَّ اَلِّفْْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا مُوْسَی وَصَفُوْرَاءَ عَلَی نَبِیِّنَا وَعَلَیْہِمَا الصَّلَاۃُ وَالسَّلَامُ ۔ أَللَّہُمَّ اَلِّفْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا مُحَمَّدٍ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ وَخَدِیْجَۃِ الْکُبْرَی رَضِیَ اللّٰہ تَعَالَی عَنْہَا ۔ أَللَّہُمَّ اَلِّفْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا مُحَمَّدٍ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ وَعَاءِشَۃَ الصِّدِّیْقَۃِ وَسَاءِر أُمَّھَاتِ الْمُؤْمِنِیْنَ رَضِیَ اللّٰہ تَعَالَی عَنْہُنَّ ۔ أَللَّہُمَّ اَلِّفْ بَیْنَہُمَا کَمَا اَلَّفْتَ بَیْنَ سَیِّدِنَا عَلِيِّ الْمُرْتَضَی وَفَاطِمَۃَ الزَّھْرَاءَ رَضِیَ اللّٰہ تَعَالَی عَنْہُمَا ۔ آمِیْنَ ۔ آمِیْنَ ۔ آمِیْنَ ۔ بِرَحْمَتِکَ یَا أَرْحَمَ الرَّاحِمِیْنَ ۔\n------------------\n[1] ’’بہارِ شریعت‘‘، ج۲، ص ۴۔ ۵، ’’ الدر المختار ورد المحتار ‘‘، کتاب النکاح ، ج ۴، ص ۷۲۔ ۷۳ .\n[2] ’’بہارِ شریعت‘‘، ج۲، ص ۳۱.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب النکاح ، القسم السا بع المحرمات بالشرک ، ج ۱، ص ۲۸۲.\n[4] ’’بہارِ شریعت‘‘، ج۲، ص ۱۵."}, {"id": 7827, "bookId": 14, "volNo": "1", "hadithNo": 59, "chapter": "مہر کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عُقْبَۃَ بْنِ عَامِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَحَقُّ الشُّرُوطِ أَنْ تُوَفُّوْا بِہِ مَا اسْتَحْلَلْتُمْ بِہِ الْفُرُوجَ‘‘َ۔ \nحدیث 2:\n’’عَنْ أَبِی سَلَمَۃَ قَالَ سَأَلْتُ عَائِشَۃَ کَمْ کَانَ صَدَاقُ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ؟ قَالَتْ کَانَ صَدَاقُہُ لِأَزْوَاجِہِ ثِنْتَیْ عَشْرَۃَ أُوقِیَّۃً وَنَشَّ قَالَتْ أَتَدْرِی مَا النَّشُّ؟ قُلْتُ لَا قَالَتْ نِصْفُ أُوقِیَّۃٍ فَتِلْکَ خَمْسُ مِءَۃِ دِرْہَمٍ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عقبہ بن عامر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ ( نکاح کی) شرطوں میں سے جس شرط کا پورا کرنا تمہارے لیے سب سے زیادہ اہم ہے وہ وہی شرط ہے جس کے ذریعہ تم نے عورتوں کی شرمگاہوں کو اپنے لیے حلال کیا ہے ۔ (یعنی دین مہر)۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابو سلمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا سے دریافت کیا کہ نبی کریم علیہ الصلاۃ والتسلیم کا مہر کتنا تھا؟ انہوں نے فرمایا کہ حضور کا مہر آپ کی (ا کثر) بیویوں کے لیے بارہ اوقیہ اور ایک نش تھا۔ پھر حضرت عائشہ نے فرمایا جانتے ہو نش کیا ہے ؟ میں نے کہا نہیں۔ انہوں نے فرمایا کہ نصف اوقیہ۔ تو سب مل کر پانچ سو درہم ہوئے ۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Uqbah Bin Amir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke (Nikah ki) sharton mein se jis shart ka pura karna tumhare liye sab se zyada ahem hai woh wahi shart hai jis ke zariye tum ne Auraton ki Sharmgahon ko apne liye Halal kiya hai. (yani deen-e-Mahr). (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Salamah Radiyallahu Anhu ne kaha ke main ne Hazrat Aishah Radiyallahu Anha se daryaft kiya ke Nabi Kareem Sallallahu Alayhi wa Sallam ka Mahr kitna tha? Unhon ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ka Mahr aap ki (aksar) Biwi ke liye barah auqiyah aur ek nash tha. Phir Hazrat Aishah ne farmaya jante ho nash kya hai? Main ne kaha nahi. Unhon ne farmaya ke nisf auqiyah. To sab mil kar paanch sau dirham huye. (Muslim)", "explanation": "¥شرح حدیث 2:\nایک اوقیہ چالیس درہم کا اور ایک نش بیس درہم کا ہوتا ہے ، لہذا بارہ اوقیہ اور ایک نش کا ۵۰۰ درہم ہوا۔ تفصیل یہ ہے ۱۲ اوقیہ ×۴۰ درہم = ۴۸۰ درہم + ۲۰ درہم = ۵۰۰ درہم پھر ایک درہم ساڑھے تین ماشہ کا ہوتا ہے تو پانچ سو درہم کا ساڑھے سترہ سو ماشہ ( ۵۰۰ درہم × ـــ ۱ ۲ ۳ماشہ =۰ ۱۷۵ ماشہ) اوربارہ ماشہ کا تولہ ہوتا ہے تو ساڑھے سترہ سو ماشہ کا ایک سو پینتالیس تولہ دس ماشہ ہوا (۱۷۵۰ ماشہ ÷۱۲ ماشہ = ۱۴۵ تولہ ۱۰ ماشہ) جس کی قیمت فی تولہ پانچ روپیہ کے حساب سے تقریباً سوا سات سو روپیہ ہوا۔ خلاصہ یہ ہے کہ چاندی کے مذکورہ بھاؤ اور سکۂ رائج الوقت کے حساب سے حضور علیہ الصلاۃ والسلام کی ( اکثر) بیویوں کا مہر تقریباً سوا سات سو روپیہ تھا۔\n٭…٭…٭…٭\n¥مہر فاطمہ رضی اللّٰہ تعالی عنہا\n حضرت سیدہ فاطمہ زہراء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا کا مہر چار سو درہم([1]) یعنی ایک سو ساڑھے سولہ تولہ چاندی تھی جس کی قیمت فی تولہ پانچ روپیہ کے حساب سے پانچ سو ساڑھے بیاسی روپیہ ہوئی۔\n مرقاۃ شرح مشکوۃ جلد سوم ص: ۴۴۷ میں ہے :\n ’’ نَقَلَ ابْنُ الْہُمَام أَنَّ صَدَاقَ فَاطِمَۃَ کَانَ أَرْبَعَ مِءَۃ دِرْہَمٍ ‘‘ ۔ ([2])\nیعنی امام ابن الہمام صاحبِ فتح القدیر نے نقل فرمایا کہ حضرت فاطمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا کا مہر چار سو درہم تھا ۔\n اور حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ: ’’ مہر فاطمہ زہراء رضی اللّٰہ تعالی عنہا چہار صد درہم بود ‘‘ ملخصاً ۔ ([3]) ( اشعۃ اللمعات ، جلد ثالث ، ص ۱۳۷)\n¥اِنتباہ :\n (۱)…مہر کم سے کم یعنی ابتدائی مہر دس درہم ہے ۔ در مختار باب المہر میں ہے : ’’ أَقَلُّہُ عَشَرَۃُ دَرَاھِم ‘‘ یعنی مہر کی مقدار کم از کم دس درہم ( ۲ تولہ _۷۲۱ ماشہ چاندی) ہے ۔ ([4])\n جس کی قیمت پانچ روپیہ فی تولہ کے حساب سے چودہ روپیہ اٹھاون پیسہ ہوئی۔ اور اگر چاندی کا بھاؤ چھ روپیہ ہوجائے تو دس درہم کا ساڑھے سترہ روپیہ ہوجائے گا ، خلاصہ یہ کہ چاندی کے نرخ کی کمی بیشی پر روپیہ سے ابتدائی مہر کی مقدار کی کمی بیشی ہوتی رہے گی۔ لہذا اس گرانی کے زمانہ میں مہر کی کم سے کم مقدار تین روپیہ ساڑھے دس آنہ سمجھنا غلطی ہے ۔\n (۲)…زیادتی کی جانب مہر کی کوئی مقدار معین نہیں ہزار دس ہزار بلکہ چالیس پچاس ہزار اور اس سے زیادہ مہر مقرر کرسکتے ہیں لیکن بہت زیادہ مہر باندھنا بہتر نہیں۔\n (۳)…مہر کی تین قسمیں ہیں ۔ (۱) معجل (۲) مؤجل (۳) مطلق ۔ مہر معجل وہ مہر ہے کہ خلوت سے پہلے دینا قرار پایا ہو ۔ اور مؤجّل و ہ مہر ہے کہ جس کی ادائیگی کے لیے کوئی میعاد مقرر ہو۔ او رمطلق وہ مہر ہے کہ نہ خلوت سے پہلے دینا قرار پایا ہواور نہ کوئی میعاد مقرر ہو اور یہی ہمارے ہندوستان میں عام طور سے رائج ہے ۔\n (۴)…مہر معجل وصول کرنے کے لیے عورت اپنے کو شوہر سے روک سکتی ہے اور مؤجل میں میعاد پوری ہونے کے بعد روک سکتی ہے پہلے نہیں روک سکتی۔ اور مہر مطلق وصول کرنے کے لیے کبھی نہیں روک سکتی۔\n (۵)…ہندوستان میں عام دستور ہے کہ عورت جب مرنے لگتی ہے تو اس سے مہر معاف کراتے ہیں حالانکہ مرض الموت میں معافی دیگر ورثہ کی اجازت کے بغیر معتبر نہیں([5])یعنی بیوی نے معاف بھی کردیا تو ایسی حالت میں ورثہ کی اجازت کے بغیر معاف نہیں ہوگا۔\n------------------\n[1] یہ مسئلہ ائمۂ محققین کے نزدیک مختلف فیہ ہے ، انوار الحدیث کے چھٹے ایڈیشن سے ہم نے بھی حضرت فاطمہ زہراء رضی اللّٰہ تعالی عنہا کا مہر اعلی حضرت امام احمد رضا بریلوی علیہ الرحمۃ والرضوان کی تحقیق کے مطابق کر دیا ہے ۔ و اللّٰہ اعلم بحقیقۃ الحال (فتاوی فیض الرسول۱/۷۱۶)\n نوٹ: اعلی حضرت علیہ رحمۃ رب العزۃ فرماتے ہیں: چار سو مثقال چاندی مہرِ خاتونِ جنت رضی اللّٰہ تعالی عنہاتھا، یہاںکے سکّے سے ایک سو ساٹھ روپے بھر چاندی۔ (فتاوی رضویہ مخرجہ ۱۲/۱۷۲)\n[2] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب النکاح ، الحدیث : ۳۳۰۴، ج ۶، ص ۳۵۹۔ ۳۶۰.\n[3] ’’ اشعۃ اللمعات ‘‘، ج ۳، ص ۱۳۷.\n[4] ’’ الدر المختار ‘‘، کتاب النکاح ، باب المھر ، ج ۴، ص ۲۲۰.\n[5] درمختار باب المہرکی عبارت ’’ صَحَّ حَطُّہَا ‘‘کے تحت ردالمحتار میں ہے ۔ وَلَا بُدَّ مِنْ رِضَاہَا وَأَنْ لَا تَکُونَ مَرِیضَۃً مَرَضَ الْمَوْتِ . ملخصاً۔\n(’’ الدر المختار ورد المحتار ‘‘، کتاب النکاح ، مطلب فی حط المھر إلخ ، ج ۴، ص ۲۳۹۔ ۲۴۰)\n اور فتاوی عالمگیری جلد اول مصری ص۲۹۳ میں ہے ۔ لَا بُدَّ فِی صِحَّۃِ حَطِّہَا مِنَ الرِّضَا حَتَّی لَوْ کَانَتْ مُکْرَہَۃً لَمْ یَصِحَّ وَمِنْ أَنْ لَا تَکُونَ مَرِیضَۃً مَرَضَ الْمَوْتِ ہَکَذَا فِی الْبَحْرِ الرَّاءِقِ ۔ ۱۲ منہ ۔ (’’ الفتاوی الھندیۃ ‘‘، کتاب النکاح ، الفصل السابع فی الزیادۃ إلخ ، ج ۱، ص ۳۱۳)"}, {"id": 7828, "bookId": 14, "volNo": "1", "hadithNo": 60, "chapter": "دعوتِ ولیمہ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَنَسٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَوْلِمْ وَلَوْ بِشَاۃٍ‘‘۔ \nحدیث 2:\n’’عَـنْ أَبِی ہُـرَیْـرَۃَ قَـالَ قَـالَ رَسُـوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ شَرُّ الطَّعَامِ طَعَامُ الْوَلِیْمَۃِ یُدْعَی لَہَا الْأَغْنِیَاءُ وَیُتْرَکُ الْفُقَرَاء‘‘۔ \nحدیث 3:\n’’ عَنْ عَبْدِ اللّٰہ بْنِ عُمَرَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ دُعِیَ فَلَمْ یُجِبْ فَقَدْ عَصَی اللّٰہ وَرَسُولَہُ وَمَنْ دَخَلَ عَلَی غَیْرِ دَعْوَۃٍ دَخَلَ سَارِقًا وَخَرَجَ مُغِیْرًا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ولیمہ کرو اگرچہ ایک ہی بکری کا ہو۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ سب سے برا کھانا ولیمہ کا وہ کھانا ہے جس کے لیے صرف مالدار لوگ بلائے جائیں اور غریب محتاج لوگوں کو نہ پوچھا جائے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت عبد اللّٰہ بن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس شخص کو کھانے کی دعوت دی جائے اور وہ (بے وجہ شرعی) دعوت قبول نہ کرے توا س نے اللّٰہ اور اس کے رسول کی نافرمانی کی۔ اور جو بغیر دعوت کے پہنچ جائے تو وہ چور کی طرح گیا اور ڈاکو بن کر نکلا۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Waleemah karo agarche ek hi bakri ka ho. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke sab se bura khana Waleemah ka woh khana hai jis ke liye Sarf Maal-daar log bulaye jayen aur ghareeb mohtaj logon ko na pucha jaye. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Abdullah Bin Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis shakhs ko khane ki dawat di jaye aur woh (be-wajah shar'i) dawat Qubool na kare to us ne Allah aur us ke Rasool ki Ita'at na ki. Aur jo baghair dawat ke pahunch jaye to woh chor ki tarah gaya aur daku ban kar nikla. (Abu Dawood)", "explanation": "*****"}, {"id": 7829, "bookId": 14, "volNo": "1", "hadithNo": 61, "chapter": "میاں بیوی کا باہمی برتاؤ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْ کُنْتُ آمرُ أَحَدًا أَنْ یَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَۃَ أَنْ تَسْجُدَ لِزَوْجِہَا‘‘۔ \nحدیث 2:\n’’ عَنْ أُمِّ سَلَمَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَیُّمَا امْرَأَۃٍ مَاتَتْ وَزَوْجُہَا عَنْہَا رَاضٍ دَخَلَتِ الْجَنَّۃَ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَکْمَلُ الْمُؤْمِنِینَ إِیمَانًا أَحْسَنُہُمْ خُلُقًا وَخِیَارُکُمْ خِیَارُکُمْ لِنِسَاءِہِمْ‘‘۔\nحدیث 4:\n’’عَنْ حَکِیمِ بْنِ مُعَاوِیَۃَ الْقُشَیْرِیِّ عَنْ أَبِیہِ قَالَ قُلْتُ یَا رَسُولَ اللّٰہ مَا حَقُّ زَوْجَۃِ أَحَدِنَا عَلَیْہِ قَالَ أَنْ تُطْعِمَہَا إِذَا طَعِمْتَ وَتَکْسُوَہَا إِذَا اکْتَسَیْتَ وَلَا تَضْرِبْ الْوَجْہَ وَلَا تُقَبِّحْ وَلَا تَہْجُرْ إِلَّا فِی الْبَیْتِ‘‘۔ \nحدیث 5:\n’’عَنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِذَا کَانَتْ عِنْدَ الرَّجُلِ امْرَأَتَانِ فَلَمْ یَعْدِلْ بَیْنَہُمَا جَاء یَوْمَ الْقِیَامَۃِ وَشِقّہُ سَاقِطٌ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اگر میں کسی کو حکم دیتا کہ وہ اللّٰہ کے سوا کسی (د وسرے ) کو سجدہ کرے تو عورت کو ضرور حکم دیتا کہ وہ اپنے شوہر کو سجدہ کرے (لیکن چونکہ غیر خدا کو سجدہ حرام ہے اس لیے ایک عورت اپنے شوہر کو سجدہ تو نہیں کرسکتی البتہ اس کے لیے شوہر کی اطاعت کا حکم ضرور ہے )۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ام سلمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو عورت اس حال میں انتقال کرے کہ اس کا شوہر اس سے راضی اور خوش ہو تو وہ عورت جنتی ہے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا مسلمانوں میں کامل الایمان وہ شخص ہے جو اپنے اخلاق میں سب سے اچھا ہو اور تم میں سب سے زیادہ بہتر وہ لوگ ہیں جو اپنی بیویوں کے لیے سب سے بہتر ہوں۔ (ترمذی)\n¥ترجمہ حدیث 4:\nحضرت حکیم بن معاویہ قشیری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے روایت کرتے ہیں انہوں نے کہا کہ میں نے عرض کیا یارسول اللّٰہ ! ہم میں سے کسی کی بیوی کا اس پر کیا حق ہے ؟ فرمایا کہ جب تم کھاؤ تواسے کھلاؤ اور جب تم پہنو تو اسے پہناؤ اور( اگر کسی خلافِ شرع بات پر سزا دینی ہو تو) اس کے منہ پر نہ مارو، اور اسے برا نہ کہو اور اسے نہ چھوڑو مگر گھر میں۔ (ابوداود، مشکوۃ) \n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس شخص کی دو بیویاں ہوں اور وہ ان کے درمیان عدل و انصاف نہ کرے تو قیامت کے دن اس حال میں اُٹھے گا کہ اس کے جسم کا ایک دھڑ الگ ہوگیا ہوگا۔ (مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke agar main kisi ko Hukm deta ke woh Allah ke siwa kisi (dusre) ko Sajdah kare to Aurat ko zaroor Hukm deta ke woh apne Shauhar ko Sajdah kare (lekin chunke ghair-e-Khuda ko Sajdah Haram hai is liye ek Aurat apne Shauhar ko Sajdah to nahi kar sakti albata us ke liye Shauhar ki Ita'at ka Hukm zaroor hai). (Tirmidhi). Tarjuma Hadees 2: Hazrat Umm-e-Salamah Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo Aurat is haal mein inteqal kare ke us ka Shauhar us se raazi aur khush ho to woh Aurat jannati hai. (Tirmidhi). Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya Musalmanon mein kamil-ul-imaan woh shakhs hai jo apne akhlaq mein sab se achha ho aur tum mein sab se zyada behtar woh log hain jo apni Biwi ke liye sab se behtar hon. (Tirmidhi). Tarjuma Hadees 4: Hazrat Hakeem Bin Mu'awiyah Qushairi Radiyallahu Anhu apne baap se riwayat karte hain unhon ne kaha ke main ne arz kiya Ya Rasoolullah! Hum mein se kisi ki Biwi ka us par kya haq hai? Farmaya ke jab tum khao to use khilao aur jab tum pehno to use pehnao aur (agar kisi khilaf-e-shar'a baat par saza deni ho to) us ke munh par na maaro, aur use bura na kaho aur use na chodo magar ghar mein. (Abu Dawood, Mishkat). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis shakhs ki do Biwi hon aur woh un ke darmiyan adl-o-insaf na kare to Qiyam ke din is haal mein uthega ke us ke jism ka ek dhad alag ho gaya hoga. (Mishkat)", "explanation": "*****"}, {"id": 7830, "bookId": 14, "volNo": "1", "hadithNo": 62, "chapter": "پردے کی باتیں کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْ أَنَّ أَحَدَکُمْ إِذَا أَرَادَ أَنْ یَأْتِیَ أَہْلَہُ قَالَ بِسْمِ اللّٰہ اللّٰہمَّ جَنِّبْنَا الشَّیْطَانَ وَجَنِّبْ الشَّیْطَانَ مَا رَزَقْتَنَا ثُمَّ قُدِّرَ أَنْ یَکُونَ بَیْنَہُمَا وَلَدٌ فِی ذَلِکَ لَمْ یَضُرّہُ شَیْطَانٌ أَبَدًا‘‘۔ \nحدیث 2:\n’’ عَنْ اِبْنِ عَبَّاس قَالَ اُوْحِیَ إِلَی رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ نِسَاؤُکُمْ حَرْثٌ لَکُمْ فَأْتُوا حَرْثَکُم الآیۃ أَقْبِلْ وَأَدْبِرْ وَاتَّقِ الدُّبُرَ وَالْحَیْضَۃ‘‘۔ \nحدیث 3:\n’’ عَنْ خُزَیْمَۃَ بِنْ ثَابِتٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ اللّٰہ لَا یَسْتَحْیِیْ مِنْ الْحَقِّ لَا تَأْتُوا النِّسَاء فِی أَدْبَارِہِنَّ‘‘۔ \nحدیث 4:\n’’عَنْ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَنْظُرُ اللّٰہ إِلَی رَجُلٍ أَتَی رَجُلًا أَوْ امْرَأَۃً فِی الدُّبُرِ‘‘۔ \nحدیث 5:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَلْعُونٌ مَنْ أَتَی امْرَأَتَہُ فِی دُبُرِہَا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ مانے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا تم میں سے کوئی شخص جب اپنی بیوی کے ساتھ ہمبستری کرنا چاہے تو یہ دعا پڑھے ’’ بِسْمِ اللّٰہ الرَّحْمَنِ الرَّحِیمِ أَللَّہُمَّ جَنِّبْنَا الشَّیْطَانَ وَجَنِّبْ الشَّیْطَانَ مَا رَزَقْتَنَا ‘‘ یعنی اے اللّٰہ تو ہم کو شیطان سے بچا اور جواولاد ہمیں عطا ہو اسے بھی شیطان سے بچا۔ پھر اگر عورت مرد کے درمیان اسی صحبت میں لڑکا پیدا ہونا مقدر ہوگیا ( یعنی حمل قرار پا گیا) تو شیطان اس لڑکے کو کبھی ضرر نہیں پہنچائے گا۔ (ابوداود، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے فرمایا کہ حضور علیہ الصلاۃ والسلام پر یہ آیتِ کریمہ جو نازل کی گئی۔ نِسَاؤُکُمْ حَرْثٌ لَکُمْ إلخ یعنی تمہاری عورتیں تمہاری کھیتی ہیں تم اپنی کھیتی میں جس طرح چاہو آؤ تو اس کا مطلب یہ ہے کہ آگے سے آؤ اور پیچھے سے آؤ لیکن پیچھے کے مقام میں صحبت کرنے سے بچو اور حالتِ حیض (میں ہمبستری) سے پرہیز کرو۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت خزیمہ بن ثابت رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اللّٰہ تعالی حق بات (کے اظہار) سے شرم نہیں فرماتا تم لوگ عورتوں کے پیچھے کے مقام میں صحبت نہ کرو۔ (احمد، ترمذی)\n¥ترجمہ حدیث 4:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اللّٰہ تعالی اس شخص کو رحمت کی نظر سے نہیں دیکھے گا جو مرد یا عورت کے ساتھ اس کے پیچھے کے مقام میں صحبت کرے ۔ (ترمذی، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص اپنی بیوی سے اس کے پیچھے کے مقام میں صحبت کرے وہ ملعون ہے ۔ (احمد)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya tum mein se koi shakhs jab apni Biwi ke sath suhbat karna chahe to yeh Dua padhe: Bismillahir Rahmanir Rahim, Allahumma jannibnash shaitana wa jannibish shaitana ma razaqtana, yani ae Allah tu hum ko shaitan se bacha aur jo Aulaad humein ata ho use bhi shaitan se bacha. Phir agar Aurat Mard ke darmiyan isi Suhbat mein ladka paida hona muqaddar ho gaya (yani Hamal qarar pa gaya) to shaitan us ladke ko kabhi zarar nahi pahunchayega. (Abu Dawood, Mishkat). Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam par yeh Ayat-e-Kareema jo nazil ki gayi: Nisa'ukum harsul lakum, yani tumhari Aurat tumhari kheti hain tum apni kheti mein jis tarah chaho aao to is ka matlab yeh hai ke aage se aao aur peeche se aao lekin peeche ke maqam mein Suhbat karne se bacho aur halat-e-Haiz (mein suhbat) se parhez karo. (Tirmidhi). Tarjuma Hadees 3: Hazrat Khuzaimah Bin Sabit Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala haq baat (ke izhar) se sharm nahi farmata tum log Auraton ke peeche ke maqam mein Suhbat na karo. (Ahmad, Tirmidhi). Tarjuma Hadees 4: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala us shakhs ko rehmat ki nazar se nahi dekhega jo Mard ya Aurat ke sath us ke peeche ke maqam mein Suhbat kare. (Tirmidhi, Mishkat). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs apni Biwi se us ke peeche ke maqam mein Suhbat kare woh mal'oon hai. (Ahmad)", "explanation": "*****"}, {"id": 7831, "bookId": 14, "volNo": "1", "hadithNo": 63, "chapter": "دیکھنا جائز نہیں کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنِ ا بْنِ مَسْعُوْدٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ الْمَرْأَۃُ عَوْرَۃٌ فَإِذَا خَرَجَتْ اسْتَشْرَفَہَا الشَّیْطَانُ ‘‘۔ \nحدیث 2:\n’’ عَنْ أُمِّ سَلَمَۃَ أَنَّہَا کَانَتْ عِنْدَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَمَیْمُونَۃَ اِذْ أَقْبَلَ ابْنُ أُمِّ مَکْتُومٍ فَدَخَلَ عَلَیْہِ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ احْتَجِبَا مِنْہُ فَقُلْتُ یَا رَسُولَ اللّٰہ! أَلَیْسَ ہُوَ أَعْمَی لَا یُبْصِرُنَا؟ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَفَعَمْیَا وَانِ أَنْتُمَا أَلَسْتُمَا تُبْصِرَانِہِ؟‘‘۔ \nحدیث 3:\n’’عَنْ جَرِیرِ بْنِ عَبْدِ اللّٰہ قَالَ سَأَلْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنْ نَظَرِ الْفُجَاءَ ۃِ فَأَمَرَنِی أَنْ أَصْرِفَ بَصَرِی‘‘۔ \nحدیث 4:\n’’ عَنْ بُرَیْدَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لِعَلِیّ یَا عَلِیُّ لَا تُتْبِعِ النَّظْرَۃَ النَّظْرَۃَ فَإِنَّ لَکَ الْأُولَی وَلَیْسَتْ لَکَ الْآخِرَۃُ‘‘۔\nحدیث 5:\n’’ عَنْ جَابِرٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اِنَّ الْمَرْأَۃَ تُقْبِلُ فِیْ صُوْرَۃِ شَیْطَانٍ وَتُدْبِرُ فِیْ صُوْرَۃِ شَیْطَانٍِ إِذَا أَحَدُکُمْ أَعْجَبَتْہُ الْمَرْأَۃُ فَوَقَعَتْ فِی قَلْبِہِ فَلْیَعْمِدْ إِلَی امْرَأَتِہِ فَلْیُوَاقِعْہَا فَإِنَّ ذَلِکَ یَرُدُّ مَا فِی نَفْسِہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ عور ت عورت ہے یعنی پردہ میں رکھنے کی چیز ہے جب وہ باہر نکلتی ہے تو شیطان اس عورت کو گھورتا ہے یعنی کسی اجنبی عورت کو دیکھنا شیطانی کام ہے ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ام سلمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا سے روایت ہے کہ میں اور حضرت میمونہ حضور کی خدمت میں حاضر تھیں کہ ( ایک نابینا صحابی) حضرت ابنِ ام مکتوم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سامنے سے حضور کی خدمت میں آرہے تھے تو سرکار نے ( ہم دونوں سے ) فرمایا کہ پردہ کرلو (حضرت ام سلمہ فرماتی ہیں کہ) میں نے عرض کیا یارسول اﷲ! کیا وہ نابینانہیں ہیں؟وہ ہمیں نہیں دیکھ سکیں گے ۔ حضور نے فرمایا کیا تم دونوں بھی نابینا ہو کیا تم انہیں نہیں دیکھو گی۔ (احمد، ترمذی، ابوداود)\n¥ترجمہ حدیث 3:\nحضرت جریر بن عبد اللّٰہ نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام سے (کسی عورت پر) اچانک نظر پڑ جانے کے متعلق پوچھا تو حضور علیہ الصلاۃ والسلام نے مجھے نظر پھیرلینے کا حکم فرمایا ۔ (مسلم)\n¥ترجمہ حدیث 4:\nحضرت بریدہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے حضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے فرمایا کہ اے علی ! ( اجنبی عورت پر) ایک نگاہ کے بعد دوسری نگاہ مت ڈالو کہ اچانک پڑجانے والی پہلی نگاہ تمہارے لیے معاف ہے دوبارہ دیکھنا جائز نہیں۔ (ترمذی) \n¥ترجمہ حدیث 5:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ عورت شیطان کی صورت میں آگے آتی ہے اور شیطان کی شکل میں پیچھے جاتی ہے جب تم میں سے کسی کو غیر عورت اچھی معلوم ہو پھر اس کا خیال د ل میں جم جائے تو وہ اپنی بیوی کے پاس چلا جائے اور اس سے ہمبستری کرلے اس لیے کہ ایسا کرنا اس کے دل کے شہوانی خیال کو دور کر دے گا۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Mas'ood Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Aurat Aurat hai yani Pardah mein rakhne ki cheez hai jab woh bahar nikalti hai to shaitan us Aurat ko ghoorta hai yani kisi ajnabi Aurat ko dekhna shaitani kaam hai. (Tirmidhi). Tarjuma Hadees 2: Hazrat Umm-e-Salamah Radiyallahu Anha se riwayat hai ke main aur Hazrat Maimoonah Rasoolullah Sallallahu Alayhi wa Sallam ki khidmat mein hazir thin ke (ek nabina Sahabi) Hazrat Ibn-e-Umm-e-Maktum Radiyallahu Anhu samne se Rasoolullah Sallallahu Alayhi wa Sallam ki khidmat mein aa rahe the to Sarkar ne (hum dono se) farmaya ke Pardah kar lo. (Hazrat Umm-e-Salamah farmati hain ke) main ne arz kiya Ya Rasoolullah! Kya woh nabina nahi hain? Woh humein nahi dekh sakenge. Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya kya tum dono bhi nabina ho kya tum unhein nahi dekhogi. (Ahmad, Tirmidhi, Abu Dawood). Tarjuma Hadees 3: Hazrat Jareer Bin Abdullah ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam se (kisi Aurat par) achanak nazar pad jane ke mutaliq pucha to Rasoolullah Sallallahu Alayhi wa Sallam ne mujhe nazar pher lene ka Hukm farmaya. (Muslim). Tarjuma Hadees 4: Hazrat Buraidah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne Hazrat Ali Radiyallahu Anhu se farmaya ke ae Ali! (ajnabi Aurat par) ek nigah ke baad dusri nigah mat daalo ke achanak pad jane wali pehli nigah tumhare liye maaf hai dobara dekhna Jaiz nahi. (Tirmidhi). Tarjuma Hadees 5: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Aurat shaitan ki surat mein aage aati hai aur shaitan ki shakal mein peeche jaati hai jab tum mein se kisi ko ghair Aurat achi maloom ho phir us ka khayal dil mein jam jaye to woh apni Biwi ke paas chala jaye aur us se Suhbat kar le is liye ke aisa karna us ke dil ke shahwani khayal ko door kar dega. (Muslim Sharif)", "explanation": "*****"}, {"id": 7832, "bookId": 14, "volNo": "1", "hadithNo": 64, "chapter": "اجنبی عورت کے ساتھ تنہائی کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَ لَا لَا یَبِیتَنَّ رَجُلٌ عِنْدَ امْرَأَۃٍ ثَیِّبٍ إِلَّا أَنْ یَکُونَ نَاکِحًا أَوْ ذَا مَحْرَمٍ‘‘۔ \nحدیث 2:\n’’ عَنْ عُمَرَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لاَ یَخْلُوَنَّ رَجُلٌ بِاِمْرَأَۃٍ إِلَّا کَانَ ثَالِثَہُمَا الشَّیْطَانُ ‘‘۔ \nحدیث 3:\n’’ عَنْ عُقْبَۃَ بْنِ عَامِرٍأَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِیَّاکُمْ وَالدُّخُولَ عَلَی النِّسَاء فَقَالَ رَجُلٌ مِنْ الْأَنْصَارِ یَا رَسُولَ اللّٰہ أَفَرَأَیْتَ الْحَمْوَ قَالَ الْحَمْوُ الْمَوْتُ‘‘۔\nحدیث 4:\n’’ عَنْ أَنَسٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ مَعَ إِحْدَی نِسَاءِہِ فَمَرَّ بِہِ رَجُلٌ فَدَعَاہُ فَجَاءَ فَقَالَ یَا فُلَانُ ہَذِہِ زَوْجَتِی فُلانَۃُ فَقَالَ یَا رَسُولَ اللّٰہ مَنْ کُنْتُ أَظُنُّ بِہِ فَلَمْ أَکُنْ أَظُنُّ بِکَ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الشَّیْطَانَ یَجْرِی مِنْ الْإِنْسَانِ مَجْرَی الدَّمِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ خبردار! کوئی مرد کسی ثیّبہ یعنی شادی شدہ عورت کے پاس رات نہ گزارے مگر صرف اس حالت میں کہ وہ مرد یا تو اس عورت کا شوہر ہو یا اس کا محرم۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کوئی مرد کسی اجنبی عورت کے ساتھ تنہائی میں نہیں جمع ہوتا لیکن اس حال میں کہ وہاں دو کے علاوہ تیسرا شیطان بھی ہوتا ہے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت عقبہ بن عامر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایاکہ تم( غیر ) عورتوں کے پاس جانے سے بچو، ایک انصاری نے عرض کیا یارسول اللّٰہ ! اگر وہ عورت کا دیور ہو تو فرمایا دیور تو موت ہے یعنی وہ اور بھی خطرناک ہے ۔ (مسلم)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام اپنی ایک بیوی کے ہمراہ تھے اتنے میں ایک شخص سامنے سے گزرا حضور نے اس کو بلا کر فرمایا اے فلاں !سن لے کہ یہ عورت میری فلاں بیوی ہے ۔ وہ شخص بولا یارسول اللّٰہ ! جب میں کسی اور کے ساتھ بدگمانی نہیں کرتا تو معاذ اللّٰہ آپ کے ساتھ بدگمانی کروں گا۔ سرکارِ اقدس نے فرمایا بات دراصل یہ ہے کہ شیطان انسان کے بدن کے اندر خون کی نالیوں میں دوڑتا پھرتا ہے ۔ اس لیے یہ اندیشہ کچھ بعید نہیں کہ وہ تیرے دل میں وسوسہ ڈال دے کہ رسولِ خدا ایک اجنبی عورت کے ساتھ ہیں۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke khabardar! koi Mard kisi sayyibah yani shadi shuda Aurat ke paas raat na guzare magar sirf is halat mein ke woh Mard ya to us Aurat ka Shauhar ho ya us ka mehram. (Muslim Sharif). Tarjuma Hadees 2: Hazrat Umar Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke koi Mard kisi ajnabi Aurat ke sath tanhai mein nahi jama hota lekin is haal mein ke wahan do ke alawa teesra shaitan bhi hota hai. (Tirmidhi). Tarjuma Hadees 3: Hazrat Uqbah Bin Amir Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke tum (ghair) Auraton ke paas jaane se bacho, ek Ansari ne arz kiya Ya Rasoolullah! Agar woh Aurat ka dewar ho to farmaya dewar to maut hai yani woh aur bhi khatarnak hai. (Muslim). Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam apni ek Biwi ke hamrah the itne mein ek shakhs samne se guzra Rasoolullah Sallallahu Alayhi wa Sallam ne us ko bula kar farmaya ae falaan! sun le ke yeh Aurat meri falaan Biwi hai. Woh shakhs bola Ya Rasoolullah! Jab main kisi aur ke sath badgumani nahi karta to ma'az Allah aap ke sath badgumani karunga. Sarkar-e-Aqdas ne farmaya baat darasal yeh hai ke shaitan insaan ke badan ke andar khoon ki naliyon mein daudta phirta hai. Is liye yeh andesha kuch ba'eed nahi ke woh tere dil mein waswasa daal de ke Rasool-e-Khuda ek ajnabi Aurat ke sath hain. (Muslim)", "explanation": "*****"}, {"id": 7833, "bookId": 14, "volNo": "1", "hadithNo": 65, "chapter": "زنا لواطت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَزْنِی الزَّانِی حِینَ یَزْنِی وَہُوَ مُؤْمِنٌ‘‘۔ \nحدیث 2:\n’’عَنْ عَمْرِو بْنِ الْعَاصِ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَا مِنْ قَوْمٍ یَظْہَرُ فِیہِمْ الزِّنَا إِلَّا أُخِذُوْا بِالسَّنَۃِ وَمَا مِنْ قَوْمٍ یَظْہَرُ فِیہِمْ الرّشَا إِلَّا أُخِذُوا بِالرُّعْبِ‘‘۔ \nحدیث 3:\n’’ عَنْ جَابِرٍأَنَّ رَجُلًا زَنَی بِامْرَأَۃٍ فَأَمَرَ بِہِ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَجُلِدَ الْحَدُّ ثُمَّ أُخْبِرَ أَنَّہُ مُحْصنٌ فَأَمَرَ بِہِ فَرُجِمَ‘‘۔\nحدیث 4:\n’’عَنْ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ وَجَدْتُمُوہُ یَعْمَلُ عَمَلَ قَوْمِ لُوطٍ فَاقْتُلُوا الْفَاعِلَ وَالْمَفْعُولَ بِہِ‘‘۔\nحدیث 5:\n’’ عَنْ اِبْنِِ عَبّاسٍ وَأَبِیْ ھُرَیْرَۃَ اَنَّ رَسُول اللّٰہصَلَّی اللّٰہعَلیْہِ وَسَلَّمَ قَالَ مَلْعُوْنٌ مَنْ عَمِلَ عَمَلَ قَوْمِ لُوْطٍ رَوَاہُ رَزِیْن وَفِیْ رِوَایَۃٍ لَہُ عَنْ ابْنِ عَبَّاسٍ أَنَّ عَلِیًا اَحْرَ قَھُمَا وَاَبَابَکْرٍ ھََدَمَ عَلَیْھِمَا حَاءِطاً‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ زنا کرنے والا جس وقت زنا کرتا ہے ( اس وقت) مومن نہیں رہتا یعنی مومن کی صفات سے محروم ہوجاتا ہے ۔ (بخاری شریف)\n¥ترجمہ حدیث 2:\nحضرت عمرو بن العاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ جس قوم میں زنا پھیل جاتا ہے وہ قوم قحط سالی میں ضرور مبتلا کی جاتی ہے اور جس قوم میں رشوت عام ہوتی ہے وہ (اپنے دشمن کے ) خوف و ہراس میں مبتلا رہتی ہے ۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ ایک مرد نے ایک عورت سے زنا کیا تو حضور علیہ الصلاۃ والسلام نے اسے کوڑے لگوائے پھر خبر دی گئی وہ محصن(یعنی شادی شدہ) ہے تو حضور نے اسے سنگسار کرادیا یعنی لوگوں نے پتھروں سے مار مار کر اسے ہلاک کردیا۔ (ابوداود)\n¥ترجمہ حدیث 4:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس شخص کو تم(حضرت) لوط علیہ السلام کی قوم کا عمل کرتے ہوئے پاؤ تو فاعل اور مفعول دونوں کو قتل کردو۔ (ترمذی)\n¥ترجمہ حدیث 5:\nحضرت ابن عباس و ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص قومِ لوط کا عمل کرے وہ ملعون ہے ۔ (رزین) اور انہیں کی ایک روایت میں حضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما سے ہے کہ حضرت علی رضی اللّٰہ عنہ نے فعلِ بد کرنے والے اور کرانے والے دونوںکو جلا دیا اور حضرت ابوبکر صدیق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے ان دونوں پر دیوار گرادی۔", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke zina karne wala jis waqt zina karta hai (us waqt) momin nahi rehta yani momin ki sifat se mehroom ho jata hai. (Bukhari Shareef). Tarjuma Hadees 2: Hazrat Amr Bin Al-Aas Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alaihi wa Sallam ko farmate hue suna ke jis qaum mein zina phail jata hai woh qaum qahat saali mein zaroor mubtala ki jati hai aur jis qaum mein rishwat aam hoti hai woh (apne dushman ke) khauf-o-haras mein mubtala rehti hai. (Ahmad, Mishkat). Tarjuma Hadees 3: Hazrat Jabir Radiyallahu Anhu se riwayat hai ke ek mard ne ek Aurat se zina kiya to Rasoolullah Sallallahu Alaihi wa Sallam ne use koday lagwaye phir khabar di gayi woh muhsan (yani shadi shuda) hai to Rasoolullah Sallallahu Alaihi wa Sallam ne use sangsar karadiya yani logon ne pathron se maar maar kar use halak kardiya. (Abu Dawood). Tarjuma Hadees 4: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jis Shakhs ko tum (Hazrat) Loot Alayhis Salam ki qaum ka amal karte hue pao to fa'il aur maf'ool dono ko qatl kardo. (Tirmidhi). Tarjuma Hadees 5: Hazrat Ibn Abbas aur Abu Hurairah Radiyallahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo Shakhs qaum-e-Loot ka amal kare woh mal'oon hai. (Razeem) aur unhi ki ek riwayat mein Hazrat Ibn Abbas Radiyallahu Anhum se hai ke Hazrat Ali Radiyallahu Anhu ne fe'l-e-bad karne wale aur karane wale dono ko jala diya aur Hazrat Abu Bakr Siddiq Radiyallahu Anhu ne un dono par deewar gira di.", "explanation": "¥اِنتباہ:\n (۱)… یہاں اگر حکومت اسلامیہ ہوتی تو زانی کو سو کوڑے مارے جاتے یا سنگ سار کیا جاتا یعنی اس قدر پتھر مارا جاتا کہ وہ مرجاتا مگر اس حال میں زانی اور زانیہ کے لیے یہ حکم ہے کہ مسلمان ان کا پورے طور پر بائیکاٹ کریں ان کے ساتھ کھانا پینا ، اُٹھنا، بیٹھنا، سلام و کلام اور ہر قسم کے اسلامی تعلقات ختم کردیں تاوقتیکہ توبہ کرکے وہ اپنے گناہ سے باز نہ آجائیں۔ اگر مسلمان ایسانہیں کریں گے تو وہ بھی گنہ گار ہوں گے ۔ \n (۲)…لواطت کرنے والے جسمانی طور پر بھی سخت سزا کے مستحق ہیں کہ حضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے انہیں جلادیا۔ حضرت ابوبکر صدیق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے ان پر دیوار گرادی اور ایک روایت کے مطابق حضور علیہ الصلاۃ والسلام نے حکم دیا کہ انہیں قتل کردو۔ اس سے پتہ چلتا ہے کہ یہ فعل نہایت خبیث ہے بلکہ زنا سے بھی بدتر ہے ۔ \n زمانۂ موجودہ میں لواطت کرنے والے اور کرانے والے کے متعلق یہ حکم ہے کہ مسلمان ان سے پورے طور پر قطع تعلق کریں اور اس خبیث فعل سے باز آجانے کے لیے ان پر اپنی طاقت بھر اتنی سختی کریں کہ وہ اپنے اس گندے خلافِ فطرت فعل سے باز آجائیں اگر مسلمان اپنی غفلت سے کام لے کر خاموشی اختیار کریں گے تو گنہ گار ہوں گے ۔"}, {"id": 7834, "bookId": 14, "volNo": "1", "hadithNo": 66, "chapter": "طلاق کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ ابْنِ عُمَرَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَبْغَضُ الْحَلَالِ إِلَی اللّٰہ الطَّلَاقُ‘‘۔ \nحدیث 2:\n’’عَنْ ثَوْبَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَیُّمَا امْرَأَۃٍ سَأَلَتْ زَوْجَہَا طَلَاقًا فِی غَیْرِ مَا بَأْس فَحَرَامٌ عَلَیْہَا رَاءِحَۃُ الْجَنَّۃِ‘‘۔ \nحدیث 3:\n’’ عَنْ مَحْمُودِ بْنِ لَبِیدٍ قَالَ أُخْبِرَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَہُ ثَلَاثَ تَطْلِیقَاتٍ جَمِیعًا فَقَامَ غَضْبَانَ ثُمَّ قَالَ أَیُلْعَبُ بِکِتَابِ اللّٰہ عَزَّ وَجَلَّ وَأَنَا بَیْنَ أَظْہُرِکُمْ ‘‘۔ \nحدیث 4:\n’’ عَنْ عَائِشَۃَ قَالَتْ جَاءَ تْ امْرَأَۃُ رِفَاعَۃَ الْقُرَظِیِّ إِلَی رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَتْ إِنِّی کُنْتُ عندَ رِفَاعَۃَ فَطَلَّقَنِی فَبَتَّ طَلَاقِی فَتَزَوَّجْتُ بَعْدَہُ عَبْدَ الرَّحْمَنِ بْن الزُّبَیْر ومَا مَعَہ إِلَّا مِثْلُ ہُدْبَۃ الثَّوْبِ فَقَال أَ تُرِیدِینَ أَنْ تَرْجِعِی إِلَی رِفَاعَۃَ؟ فَقَالَتْ نَعَمْ قَالَ لَا حَتَّی تَذُوقِیَ عُسَیْلَتَہُ و یَذُوقَ عُسَیْلَتَکِ‘‘۔ (بخاری، مسلم)", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ تمام حلال چیزوں میں خدائے تعالی کے نزدیک سب سے ناپسندیدہ چیز طلاق ہے ۔ (ابوداود)\n¥ترجمہ حدیث 2:\nحضرت ثوبان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو عورت بغیر کسی عذرِ مقبول کے شوہر سے طلاق مانگے اس پر جنت کی خوشبو حرام ہے ۔ (ترمذی، ابوداود)\n¥ترجمہ حدیث 3:\nحضرت محمود بن لبید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام کو خبر دی گئی کہ ایک شخص نے اپنی بیوی کو تین طلاقیں اکٹھی دی ہیں یہ سنتے ہی حضور غضب ناک ہو کر کھڑے ہوگئے پھر فرمایا کیا اللّٰہ تعالی کی کتاب کے ساتھ کھیل کیا جاتا ہے حالانکہ میں تمہارے اندر موجو د ہوں۔ (نسائی)\n¥ترجمہ حدیث 4:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے فرمایا کہ رفاعہ قرظی کی بیوی نے حضور علیہ الصلاۃ والسلام کی خدمت میں حاضر ہو کر عرض کیا کہ میں رفاعہ کے پاس تھی تو انہوں نے مجھے طلاق دی پھر میری طلاق قطعی کردی یعنی مجھے تین طلاقیں دے دیں۔ ا س کے بعد میں نے عبدالرحمن بن زبیر سے نکاح کرلیا اور نہیں ہے ان کا (عضو) مگر کپڑے کے دامن کی طرح نرم (یعنی وہ ہمبستری کی قدرت نہیں رکھتے ) تو حضور نے فرمایا کہ تم لوٹ کر رفاعہ کے پاس جانا چاہتی ہو؟انہوں نے عرض کیا ہاں، حضو ر نے ارشاد فرمایا کہ تم اس وقت تک ان کی طرف لوٹ کر نہیں جاسکتی ہو جب تک کہ عبدالرحمن سے تم اور تم سے وہ جنسی حظ نہ حاصل کرلیں۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke tamam Halal cheezon mein Allah Ta'ala ke nazdeek sab se napasandeeda cheez Talaq hai. (Abu Dawood). Tarjuma Hadees 2: Hazrat Thauban Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo Aurat baghair kisi uzr-e-Qubool ke Shauhar se Talaq mange us par jannat ki Khushboo Haram hai. (Tirmidhi, Abu Dawood). Tarjuma Hadees 3: Hazrat Mahmood Bin Labeed Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alaihi wa Sallam ko khabar di gayi ke ek Shakhs ne apni Biwi ko teen Talaqein ikatthi di hain ye sunte hi Rasoolullah Sallallahu Alaihi wa Sallam ghazab naak ho kar khade ho gaye phir farmaya kya Allah Ta'ala ki Kitaab ke sath khel kiya jata hai halankeh main tumhare andar maujood hoon. (Nasa'i). Tarjuma Hadees 4: Hazrat Aishah Radiyallahu Anha ne farmaya ke Rifa'ah Qurzi ki Biwi ne Rasoolullah Sallallahu Alaihi wa Sallam ki khidmat mein hazir ho kar arz kiya ke main Rifa'ah ke paas thi to unhon ne mujhe Talaq di phir meri Talaq qat'i kardi yani mujhe teen Talaqein de dein. Us ke baad main ne Abdur Rahman Bin Zubair se Nikah karliya aur nahi hai un ka (uzw) magar kapde ke daaman ki tarah narm (yani woh hambistari ki qudrat nahi rakhte) to Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke tum laut kar Rifa'ah ke paas jana chahti ho? Unhon ne arz kiya haan, Rasoolullah Sallallahu Alaihi wa Sallam ne irshad farmaya ke tum us waqt tak un ki taraf laut kar nahi ja sakti ho jab tak ke Abdur Rahman se tum aur tum se woh jinsi hazz na hasil kar lein. (Bukhari, Muslim).", "explanation": "¥شرح حدیث 3:\nمعلوم ہوا کہ یکبارگی تین طلاقیں دینی حرام ہیں۔ مرقاۃ میں اسی حدیث کے تحت ہے : ’’ اَلْحَدِیْثُ یَدُلُّ عَلَی أَنَّ التَّطْلِیْقَ بِالثَّلاثِ حَرَامٌ لِأَنَّہُ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَصِیْرُ غَضْبَان إِلَّابِمَعْصِیَۃٍ اھـ ‘‘۔ ([1])\n------------------\n[1] ’’ مرقاۃ المفاتیح شرح مشکاۃ المصابیح ‘‘، کتاب النکاح ، الحدیث : ۳۲۹۲، ج ۶، ص ۴۳۵۔ ۴۳۶.\n¥انتباہ :\n (۱)…طلاق کی تین قسمیں ہیں۔ رجعی ، بائن اور مغلّظہ۔ طلاق رجعی کا مطلب یہ ہے کہ شوہر عدت کے اندر رجعت کرسکتا ہے خواہ عورت راضی ہو یا نہ ہو۔ اور بعد عدت عورت کی مرضی سے نکاح کرسکتا ہے ۔ حلالہ کی ضرورت نہیں۔ اور طلاق بائن کا مطلب یہ ہے کہ عورت کی مرضی سے شوہر عدت کے اندر نکاح کرسکتا ہے ۔ اور عدت کے بعد بھی حلالہ کی ضرورت نہیں۔ ا ور طلاق مغلّظہ کا مطلب یہ ہے عورت بغیر حلالہ شوہر اول کے لیے جائز([1])نہ ہوگی۔\n (۲)…حلالہ کی صورت یہ ہے کہ اگر عورت مدخولہ ہے تو عدت پوری ہونے کے بعد دوسرے سے نکاح کرے اور یہ دوسرا شوہر اس سے وطی بھی کرے اب دوسرے شوہر کی موت یا طلاق کے بعد عدت پوری ہونے پر پہلے شوہر سے نکاح کرسکتی ہے ۔ اور اگر عورت مدخولہ نہیں ہے تو پہلے شوہر کے طلاق دینے کے فوراً بعد دوسرے سے نکاح کرسکتی ہے اس لیے کہ غیر مدخولہ کے لیے عدت نہیں۔ ([2]) (عالمگیری، بہار شریعت وغیرہ)\n حدیث شریف میں حلالہ کرنے والے اور حلالہ کرانے والے پر جو لعنت آئی ہے اس کا مطلب یہ ہے کہ ایجاب و قبول میں حلالہ کی شرط لگائی جائے ۔ اور اگر ایجاب وقبول میں حلالہ کی شرط نہ لگائی جائے تو کوئی قباحت نہیں بلکہ اگر بھلائی کی نیت ہو تو مستحق اجر ہے ۔\n درمختار مع ردالمحتارجلد ۲، ص:۵۵۹ میں ہے :\n’’ لُعِنَ الْمُحَلِّلُ وَالْمُحَلَّلُ لَہُ بِشَرْطِ التَّحْلِیل کَتَزَوَّجْتُکِ عَلَی أَنْ أُحَلِّلَکِ أَمَّا إذَا أَضْمَرَ ذَلِکَ لَا یکْرَہُ وَکَانَ الرَّجُلُ مَأْجُورًا لِقَصْدِ الْإِصْلَاحِ ‘‘۔ ([3])\nیعنی حلالہ کرنے والے اور حلالہ کرانے والے پر اس صورت میں لعنت کی گئی ہے جب کہ ایجاب و قبول میں حلالہ کی شرط لگائی جائے ۔ مثلاً مرد عورت سے یوں کہے کہ میں نے تجھ سے نکاح کیا اس بات پر کہ تو شوہر اوّل کے لیے حلال ہوجائے لیکن اگر حلالہ کی نیت دل میں ہو ( اور ایجاب و قبول میں حلالہ کی شرط کا ذکر نہ ٔآئے ) تو اس میں کوئی قباحت وکراہت نہیں بلکہ اگر اصلاح کی نیت سے ہو تو موجب اجر ہے ۔\n (۳)… طلاق دینا جائز ہے لیکن بغیر وجہ شرعی ممنوع ہے ۔\n (۴)…وجہ شرعی ہو تو طلاق دینا مباح ہے بلکہ اگر عورت شوہر کو یا دوسروں کو تکلیف دیتی ہو یا نماز نہ پڑھتی ہو تو طلاق دینا مستحب ہے ۔ ([4]) (بہار شریعت)\n (۵)…اگر شوہر نامرد ہے یا اس پر کسی نے جادو کردیا ہو کہ ہمبستری نہیں کر پاتا اور اس کے ازالہ کی بھی کوئی صورت نظر نہیں آتی تو ان صورتوں میں طلاق دینا واجب ہے ۔ اگر طلاق نہیں دے گا تو گنہ گار ہوگا۔ ([5]) (بہار شریعت بحوالہ درمختار وغیرہ)\n------------------\n[1] رجعی، بائن اور طلاق مغلّظہ کی صورتیں بہار ِشریعت(حصہ ۸) سے معلوم کریں۔ ۱۲ منہ\n[2] ’’ بہار شریعت‘‘، ج۲، ص۱۷۷، ’’ الفتاوی الھندیۃ ‘‘، کتاب الطلاق ، فصل فیما تحل بہ المطلقۃ وما یتصل بہ ، ج ۱، ص ۴۷۳.\n[3] ’’ الدر المختار ورد المحتار ‘‘، کتاب الطلاق ، مطلب فی حیلۃ إسقاط عدۃ المحلل ، ج ۵، ص ۵۱.\n[4] ’’ بہار شریعت‘‘، ج۲، ص۱۱۰.\n[5] ’’ بہار شریعت‘‘، ج۲، ص۱۱۰، ’’ الدر المختار ‘‘، کتاب الطلاق ، ج ۴، ص ۴۱۴۔ ۴۱۷ وغیرہ ."}, {"id": 7835, "bookId": 14, "volNo": "1", "hadithNo": 67, "chapter": "عدت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "’’عَنِ الْمِسْوَرِ بْنِ مَخْرَمَۃَ أَنَّ سُبَیْعَۃَ الْأَسْلَمِیَّۃَ نُفِسَتْ بَعْدَ وَفَاۃِ زَوْجِہَا بِلَیَالٍ فَجَاءَ تِ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَاسْتَأْذَنَتْہُ أَنْ تَنْکِحَ فَأَذنَ لَہَا فَنَکَحَتْ‘‘۔", "urdu": "حضرت مسور بن مخرمہ سے روایت ہے کہ سُبیعہ اسلمیہ کو شوہر کے انتقال کے کچھ عرصہ بعد بچہ تولد ہوا تو حضور علیہ الصلاۃ والسلام کی خدمت میں حاضر ہوئیں اور نکاح کی اجازت طلب کی ۔ حضور نے ان کو اجازت دے دی تو انہوں نے نکاح کرلیا۔ (بخاری شریف)", "roman": "Hazrat Miswar Bin Makhramah se riwayat hai ke Subai'ah Aslamiyah ko Shauhar ke inteqal ke kuch arsa baad Bachah tawallud hua to Rasoolullah Sallallahu Alaihi wa Sallam ki khidmat mein hazir huin aur Nikah ki ijazat talab ki. Rasoolullah Sallallahu Alaihi wa Sallam ne un ko ijazat de di to unhon ne Nikah karliya. (Bukhari Shareef).", "explanation": "معلوم ہوا کہ بیوہ حاملہ کی عدت وضع حمل ہے ۔ جیسا کہ شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ عَلَیْہِ اسی حدیث کے تحت فرماتے ہیں کہ ’’ عدت حاملِ وضع حمل ست ‘‘۔ ([1]) ( اشعۃ اللمعات ، جلد سوم ص ۱۸۴)\n اور بیوہ اگر حاملہ نہ ہو تو اس کی عدت چار مہینہ دس دن ہے ۔ جیسا کہ پارہ ۲۔ رکوع ۱۴ میں ہے :{ وَ الَّذِیْنَ یُتَوَفَّوْنَ مِنْكُمْ وَ یَذَرُوْنَ اَزْوَاجًا یَّتَرَبَّصْنَ بِاَنْفُسِهِنَّ اَرْبَعَةَ اَشْهُرٍ وَّ عَشْرًاۚ- }۔\n اور طلاق والی عورت اگر حاملہ ہو تو اس کی عدت بھی وضع حمل ہے ۔ جیسا کہ پارہ ۲۸۔ رکوع ۱۷میں ہے : { وَ اُولَاتُ الْاَحْمَالِ اَجَلُهُنَّ اَنْ یَّضَعْنَ حَمْلَهُنَّؕ- }۔\n اور طلاق والی مدخولہ عورت اگر آئسہ یعنی پچپن سالہ یا نابالغہ ہو تو اس کی عدت تین ماہ ہے ۔ جیسا کہ پارہ ۲۸ سورۃ طلاق میں ہے : { وَ اﻼ یَىٕسْنَ مِنَ الْمَحِیْضِ مِنْ نِّسَآىٕكُمْ اِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلٰثَةُ اَشْهُرٍۙ- وَّ اﻼ لَمْ یَحِضْنَؕ - }۔\n اور طلاق والی مدخولہ عورت اگر حاملہ نابالغہ یا پچپن سالہ نہ ہو یعنی حیض والی ہو تو اس کی عدت تین حیض ہے ۔ خواہ یہ تین حیض تین ماہ یا تین سال یا اس سے زیادہ میں آئیں کَماقَالَ اللّٰہ تَعَالَی : { وَ الْمُطَلَّقٰتُ یَتَرَبَّصْنَ بِاَنْفُسِهِنَّ ثَلٰثَةَ قُرُوْٓءٍؕ- }۔ ( پارہ ۲، رکوع ۱۲) \n اورطلاق والی غیر مدخولہ عورت کے لیے کوئی عدت نہیں جیسا کہ پارہ ۲۲ رکوع ۳میں ہے :{ اِذَا نَكَحْتُمُ الْمُؤْمِنٰتِ ثُمَّ طَلَّقْتُمُوْهُنَّ مِنْ قَبْلِ اَنْ تَمَسُّوْهُنَّ فَمَا لَكُمْ عَلَیْهِنَّ مِنْ عِدَّةٍ }۔\n¥انتباہ:\n عوام میں جو مشہور ہے کہ طلاق والی عورت کی عدت تین مہینہ تیرہ دن ہے تو یہ بالکل غلط اور بے بنیاد ہے جس کی شریعت میں کوئی اصل نہیں۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب النکاح ، باب العدۃ ، الفصل الأول ، ج ۳، ص ۱۸۴."}, {"id": 7836, "bookId": 14, "volNo": "1", "hadithNo": 68, "chapter": "حلال اور حرام جانور کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ جَابِرٍ قَالَ حَرَّمَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَعْنِیْ یَوْمَ خَیْبَرَ الْحُمُرَ الْإِنْسِیَّۃَ وَلُحُومَ الْبِغَالِ وَکُلَّ ذِی نَابٍ مِنْ السِّبَاعِ وَکُلَّ ذِی مِخْلَبٍ مِنْ الطَّیْر‘‘۔ \nحدیث 2:\n’’ عَنْ سَفِیْنَۃَ قَالَ أَکَلْتُ مَعَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَحْمَ حُبَارَی‘‘۔\nحدیث 3:\n’’عَنْ أَبِی مُوسَی قَالَ رَأَیْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَأْکُلُ لَحْمَ الدَّجَاجِ‘‘۔ \nحدیث 4:\n’’ عَنْ أَبِیْ قَتَادَۃَ أَنَّہُ رَأَی حِمَارًا وَحْشِیًّا فَعَقَرَہُ فقَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ہَلْ مَعَکُمْ مِنْ لَحْمِہِ شَیْئٌ قَالَ مَعَنَا رِجْلُہُ فَأَخَذَہَا فَأَکَلَہَا‘‘۔\nحدیث 5:\n’’ عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أُحِلَّتْ لَنَا مَیْتَتَانِ وَدَمَانِ الْمَیْتَتَانِ الْحُوتُ وَالْجرَادُ وَالدَّمَانِ الْکَبِدُ وَالطِّحَالُ‘‘۔ \nحدیث 6:\n’’ عَنْ جَابِرِقَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا أَلْقَاہُ الْبَحْرُ وَجَزَرَ عَنْہُ الْمَاءُ فَکُلُوہُ وَمَا مَاتَ فِیہِ وَطَفَا فَلاَ تَأْکُلُوہ‘‘۔\nحدیث 7:\n’’ عَنْ عِکْرَمَۃَ عَنِ ابْنِ عَبَّاسٍ قَالَ لَا أَعْلَمُہُ اِلَّا رَفَعَ الْحَدِیْثَ إِنَّہُ کَانَ یَامُرُ بِقَتْلِ الْحَیَّاتِ وََقالَ مَنْ تَرَکَھُنَّ خَشْیَۃَ ثَائرٍ فَلَیْسَ مِنَّا‘‘۔ \nحدیث 8:\n’’عَنْ أَبِی ہُرَیْرَۃَ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ قَتَلَ وَزَغًا فِی أَوَّلِ ضَرْبَۃٍ کُتِبَتْ لَہُ مِءَۃُ حَسَنَۃٍ وَفِی الثَّانِیَۃِ دُونَ ذَلِکَ وَفِی الثَّالِثَۃِ دُونَ ذَلِک‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃو التسلیم نے گھریلو گدھوں ، خچروں، درندوں اور پنجہ سے شکار کرنے والے پرندوں کے گوشت کو خیبر کے دن حرام قرار دیا۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت سفینہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے سرکارِ دوعالم صلی اللّٰہ تعالی علیہ وسلم کے ساتھ سرخاب کا گوشت کھایا ہے ۔ (ابو داود)\n¥ترجمہ حدیث 3:\nحضرت ابوموسی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے رسولِ کریم علیہ الصلاۃ والتسلیم کو مرغ کا گوشت تناول فرماتے ہوئے دیکھا ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\nحضرت ابوقتادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ انھوں نے نیل گائے دیکھا تو شکار کیا حضور اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کیا تمہارے پاس اس کے گوشت کا کچھ حصہ ہے ؟ عرض کیا ہاں، اس کی ران ہے ، حضور نے اس کو قبول فرمایا اور کھایا۔ (بخاری، مسلم)\n¥ترجمہ حدیث 5:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ ہمارے لیے دو مردار جانور اور دو خون حلال کیے گئے ہیں۔ مردار جانور تو مچھلی اور ٹڈی ہیں اور دو خون کلیجی اور تلی ہیں۔ (احمد، ابن ماجہ، مشکوۃ)\n¥ترجمہ حدیث 6:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ دریا نے جس مچھلی کوباہر پھینک دیا اسے کھاؤ اور جو پانی میں مر کر تیرنے لگے اسے نہ کھاؤ۔ (ابوداود، ابن ماجہ)\n¥ترجمہ حدیث 7:\nحضرت عکرمہ حضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہم سے روایت کرتے ہیں کہ سرکار اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سانپوں کو مار ڈالنے کا حکم فرمایا کرتے تھے اور فرماتے تھے کہ جو شخص اس ڈر سے نہ مارے کہ دوسرے سانپ اس سے بدلہ لیں گے تو ہمارے طریقے پر نہیں ہے ۔ (شرح السنۃ، مشکوۃ)\n¥ترجمہ حدیث 8:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص گرگٹ یا چھپکلی کو پہلی ضرب میں مارے اس کے نامۂ اعمال میں سو نیکیاں لکھی جاتی ہیں اور دوسری میں اس سے کم اور تیسری میں اس سے بھی کم ۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne gharelu gadhon, khachron, darindon aur panja se shikar karne wale parindon ke gosht ko Khaibar ke din Haram qarar diya. (Tirmidhi). Tarjuma Hadees 2: Hazrat Safeenah Radiyallahu Anhu ne farmaya ke main ne Sarkaar-e-Do'alam Sallallahu Alaihi wa Sallam ke sath sarkhab ka gosht khaya hai. (Abu Dawood). Tarjuma Hadees 3: Hazrat Abu Musa Radiyallahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alaihi wa Sallam ko murgh ka gosht tanawul farmate hue dekha hai. (Bukhari, Muslim). Tarjuma Hadees 4: Hazrat Abu Qatadah Radiyallahu Anhu se riwayat hai ke unhon ne neel gaye dekha to shikar kiya, Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya kya tumhare paas is ke gosht ka kuch hissa hai? Arz kiya haan, is ki Raan hai, Rasoolullah Sallallahu Alaihi wa Sallam ne us ko Qubool farmaya aur khaya. (Bukhari, Muslim). Tarjuma Hadees 5: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Sarkaar-e-Aqdas Sallallahu Alaihi wa Sallam ne farmaya ke hamare liye do murdar janwar aur do khoon Halal kiye gaye hain. Murdar janwar to machli aur tiddi hain aur do khoon kaleji aur tilli hain. (Ahmad, Ibn Majah, Mishkat). Tarjuma Hadees 6: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke darya ne jis machli ko bahar phenk diya use khao aur jo pani mein mar kar tairne lage use na khao. (Abu Dawood, Ibn Majah). Tarjuma Hadees 7: Hazrat Ikrimah Hazrat Ibn Abbas Radiyallahu Anhum se riwayat karte hain ke Sarkaar-e-Aqdas Sallallahu Alaihi wa Sallam saanpon ko maar dalne ka Hukm farmaya karte the aur farmate the ke jo Shakhs is dar se na mare ke dusre saanp us se badla lenge to hamare tareeqe par nahi hai. (Sharh-us-Sunnah, Mishkat). Tarjuma Hadees 8: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo Shakhs girgit ya chhipkali ko pehli zarb mein mare us ke namah-e-a'maal mein sau nekiyan likhi jati hain aur dusri mein us se kam aur teesri mein us se bhi kam. (Muslim Shareef).", "explanation": "¥انتباہ :\n (۱)… غُرَابُ الْأَبْقَع یعنی وہ کوّا جو مردار کھاتا ہے حرام ہے درمختار میں ہے : لَا یَحِلُّ الْغُرَابُ الْأَبْقَعُ الَّذِی یَأْکُلُ الْجِیَفَ لِأَنَّہُ مُلْحَقٌ بِالْخَبَاءِثِ ۔\n اور مہو کا کہ یہ کوّے کی طرح ایک جانور ہوتا ہے حلال ہے ۔ ([1])(رد المحتار)\n (۲)…مچھلی کے علاوہ پانی کے سب جانور حرام ہیں۔ جیسے کچھوا، مگر مچھ ، وغیرہ ۔\n (۳)…جھینگا کے مچھلی ہونے میں اختلاف ہے لہذا اس سے بچنا بہتر ہے ۔ ([2])(بہار شریعت)\n (۴)…پانی میں کوئی ایسی چیز ڈال دی کہ جس سے مچھلی مر گئی اور یہ معلوم ہے کہ اس چیز کے ڈالنے سے مری ہے تو وہ مچھلی حلال ہے ۔ ([3])(درمختار)\n (۵)…خرگوش جو بلی کی طرح ایک تیز رفتار جانور ہوتا ہے حلال ہے ، ہدایہ صفحہ ۴۲۵ میں ہے : ’’ لَا بَأْسَ بِأَکْلِ الْأَرْنَبِ لِأَنَّ النَّبِیَّ عَلَیْہِ السَّلَامُ أَکَلَ مِنْہُ حِینَ أُہْدِیَ إلَیْہِ مَشْوِیًّا وَأَمَرَ أَصْحَابَہُ رَضِیَ اللّٰہ عَنْہُم بِالْأَکْلِ مِنْہُ ‘‘۔ ([4])\n------------------\n[1] ’’ الدر المختار ورد المحتار ‘‘، کتاب الذبائح ، ج ۹، ص ۵۰۹.\n[2] ’’بہارِ شریعت‘‘، حصہ پانزدہم، ص۱۲۶.\n[3] ’’ الدر المختار ‘‘، کتاب الذبائح ، ج ۹، ص ۵۱۲.\n[4] ’’ الہدایۃ ‘‘، کتاب الذبائح ، فصل فیمایحل أکلہ وما لایحل ، ج ۲، ص ۳۵۲."}, {"id": 7837, "bookId": 14, "volNo": "1", "hadithNo": 69, "chapter": "شکار اور ذبح کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَدِیِّ بْنِ حَاتِمٍ قَالَ قُلْتُ یَا رَسُولَ اللّٰہ أَرَأَیْتَ أَحَدُنَا أَصَابَ صَیْدًا وَلَیْسَ مَعَہُ سِکِّیْنٌ أَیَذْبَحُ بِالْمَرْوَۃِ وَشِقَّۃِ الْعَصَا؟ فَقَالَ أَمْرِرِ الدَّمَ بِمَا شِئْتَ وَاذْکُرِ اسْمَ اللّٰہ ‘‘۔ \nحدیث 2:\n’’عَنْ عَدِیِّ بْنِ حَاتِمٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَا عَلَّمْتَ مِنْ کَلْبٍ أَوْ بَازٍ ثُمَّ أَرْسَلْتَہُ وَذَکَرْتَ اسْمَ اللّٰہ فَکُلْ مِمَّا أَمْسَکَ عَلَیْکَ قُلْتُ وَإِنْ قَتَلَ قَالَ إِذَا قَتَلَہُ وَلَمْ یَأْکُلْ مِنْہُ شَیْءًا فَإِنَّمَا أَمْسَکَہُ عَلَیْکَ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنِ اتَّخَذَ کَلْبًا إِلَّا کَلْبَ مَاشِیَۃٍ أَوْ صَیْدٍ أَوْ زَرْعٍ انْتَقَصَ مِنْ أَجْرِہِ کُلَّ یَوْمٍ قِیْرَاطٌ‘‘۔ \nحدیث 4:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو بْنِ العَاصِ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ قَتَلَ عُصْفُورًا فَمَا فَوْقَہَا بِغَیْرِ حَقِّہَا سَأَلَہُ اللّٰہ عَنْ قَتْلِہِ قِیلَ یَا رَسُولَ اللّٰہ مَا حَقُّہَا؟ قَالَ اَنْ یَذْبَحَہَا فَیَأْکُلُہَا وَلَا یَقْطَعُ رَأْسَہَا فیَرْمِی بِہَا‘‘۔ \nحدیث 5:\n’’عَنْ عَائِشَۃَ قَالَتْ قَالُوْا یَا رَسُولَ اللّٰہ إِنَّ ہُنَا أَقْوَامًا حَدِیثٌ عَہْدُہُمْ بِشِرْکٍ یَأْتُونَنَا بِلحْمَانٍ لَا نَدْرِی أَیَذْکُرُونَ اسْمَ اللّٰہ عَلَیْہَا أَمْ لَا قَالَ اذْکُرُوا أَنْتُمْ اسْمَ اللّٰہ وَکُلُوا‘‘۔ \nحدیث 6:\n’’ عَنْ شَدَّادِ بْنِ أَوْسٍ عَنْ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ وَلْیحدَّ أَحَدُکُمْ شَفْرَتَہُ فَلْیُرِحْ ذَبِیحَتَہُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عدی بن حاتم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے عرض کیا یارسول اللّٰہ ! آپ کا کیا خیال ہے ؟ اگر ہم میں سے کسی کو شکار مل جائے اور اس کے پاس چھری نہ ہو تو کیا وہ پتھر اور لاٹھی کی کھپچی سے اس کو ذبح کرسکتا ہے ؟ حضور نے فرمایا اللّٰہ کا نام لے کر جس چیز سے چاہو خون بہاؤ۔ ( ذبح کا حق ادا ہوجائے گا) ۔ (ابوداود، نسائی، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت عدی بن حاتم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ جس کتّے یا باز کو تم نے سکھایا ہو اور پھر اللّٰہ تعالی کا نام لے کر اس کو شکار پر چھوڑ و تو جس جانور کو وہ تمہارے لیے پکڑ رکھے ( اور خود نہ کھائے ) تو اس کو تم کھالو۔ میں نے عرض کیا اگرچہ وہ شکار کو مار ڈالے حضور نے فرمایا جب شکار کو مار ڈالے اور خود اس میں سے کچھ نہ کھائے تو شکار کو اس نے تیرے لیے پکڑ رکھا ہے ۔ (ابوداود، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایاکہ جو شخص مویشی کی حفاظت یا شکار کرنے یا کھیت کی نگہبانی کے مقاصد کے علاوہ صرف شوق کے لیے کتا پالے تو روزانہ ایک قیراط کی مقدار میں اس کا ثواب کم ہوگا۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\nحضرت عبد اللّٰہ بن عمروبن العاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص چڑیا یااس سے بڑے پرندے کو ناحق مارے تو خدائے تعالی اس کے متعلق بھی باز پرس کرے گا۔ عرض کیا گیا یارسول اللّٰہ ! پرندوں کا حق کیا ہے ؟ فرمایا انہیں ذبح کرے تو کھائے نہ یہ کہ سر کاٹ کر پھینک دے ۔ (احمد، نسائی، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ صحابہ کرام نے عرض کیا یارسول اللّٰہ ! یہاں کچھ قومیں رہتی ہیں جن کے شرک کا زمانہ بہت قریب ہے (یعنی نو مسلم ہیں) وہ لوگ ہمارے پاس گوشت لاتے ہیں اور ہم نہیں جانتے کہ ذبح کے وقت وہ خدائے تعالی کا نام لیتے ہیں یا نہیں۔ حضور نے فرمایا کہ تم بسم اللّٰہ کہو اور کھاؤ۔ (بخاری)\n¥ترجمہ حدیث 6:\nحضرت شداد بن اوس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جب (جانور) ذبح کرنا چاہو تو ٹھیک سے ذبح کرو ۔ اپنی چھُری کو تیز کرلو اور ذبیحہ کو تکلیف نہ پہنچاؤ۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Adi Bin Hatim Radiyallahu Anhu ne kaha ke main ne arz kiya Ya Rasoolullah! Aap ka kya khayal hai? Agar hum mein se kisi ko shikar mil jaye aur us ke paas chhuri na ho to kya woh patthar aur lathi ki khapchi se us ko Zibah kar sakta hai? Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya Allah ka naam le kar jis cheez se chaho khoon bahao. (Zibah ka haq ada ho jayega). (Abu Dawood, Nasa'i, Mishkat). Tarjuma Hadees 2: Hazrat Adi Bin Hatim Radiyallahu Anhu se riwayat hai ke Nabi Kareem Sallallahu Alaihi wa Sallam ne farmaya ke jis kutte ya baaz ko tum ne sikhaya ho aur phir Allah Ta'ala ka naam le kar us ko shikar par chhoro to jis janwar ko woh tumhare liye pakad rakhe (aur khud na khaye) to us ko tum khao. Main ne arz kiya agarche woh shikar ko maar dale, Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya jab shikar ko maar dale aur khud us mein se kuch na khaye to shikar ko us ne tere liye pakad rakha hai. (Abu Dawood, Mishkat). Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo Shakhs maweshi ki hifazat ya shikar karne ya khet ki nigahbani ke maqasid ke ilawa sirf shauq ke liye kutta pale to rozana ek qeeraat ki miqdar mein us ka sawab kam hoga. (Bukhari, Muslim). Tarjuma Hadees 4: Hazrat Abdullah Bin Amr Bin Al-Aas Radiyallahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jo Shakhs chidiya ya us se bade parinde ko na-haq mare to Allah Ta'ala us ke mutaliq bhi baaz purs karega. Arz kiya gaya Ya Rasoolullah! Parindon ka haq kya hai? Farmaya unhein Zibah kare to khaye na ye ke sar kaat kar phenk de. (Ahmad, Nasa'i, Mishkat). Tarjuma Hadees 5: Hazrat Aishah Radiyallahu Anha ne farmaya ke Sahabah ne arz kiya Ya Rasoolullah! Yahan kuch qaumein rehti hain jin ke Shirk ka zamana bahut qareeb hai (yani nau-muslim hain) woh log hamare paas gosht late hain aur hum nahi jante ke Zibah ke waqt woh Allah Ta'ala ka naam lete hain ya nahi. Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke tum Bismillah kaho aur khao. (Bukhari). Tarjuma Hadees 6: Hazrat Shaddad Bin Aus Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jab (janwar) Zibah karna chaho to theek se Zibah karo. Apni chhuri ko tez karlo aur Zabeeha ko takleef na pahunchao. (Muslim).", "explanation": "¥اِنتباہ :\n (۱)… ذبح میں چار رگیں کاٹی جاتی ہیں۔ ’’ حلقوم‘‘ جس میں سانس آتی جاتی ہے ۔ ’’مری‘‘ جس سے کھانا پانی اترتا ہے ، ان دونوں کے اغل بغل اور دو رگیں ہوتی ہیں جن میں خون کی روانی ہوتی ہے ۔ ان کو ’’ودجین‘‘ کہتے ہیں۔ ([1]) (درمختار، بہار شریعت)\n (۲)…چار رگوں میں سے تین کٹ گئیں یا ہر ایک کا اکثر حصہ کٹ گیا تو ذبیحہ حلال ہے ۔\n (۳)… مشرک اور وہابی مرتد دہریہ نیچری کا ذبیحہ حرام و مردار ہے ۔\n (۴)… ہندو نے کہا کہ یہ مسلمان کا ذبیحہ ہے تو اس کا کھانا جائز نہیں۔ اور اگر یہ کہا کہ میں مسلمان سے خرید کر لایا ہوں تو اس کا کھانا جائز ہے ۔ درمختارمیں ہے :’’ أَصْلُہُ أَنَّ خَبَرَ الْکَافِرِ مَقْبُولٌ بِالْإِجْمَاعِ فِی الْمُعَامَلاتِ لَا فِی الدِّیَانَاتِ ۔ ‘‘([2])\n (۵)…ذبح کرنے میں قصداً بِسْمِ اللّٰہ اللّٰہ اَکْبَر نہ کہا تو جانور حرام ہے اور بھول کر ایسا ہوا تو حلا ل ہے ۔ ([3]) (ہدایہ، جلد چہارم ص ۴۱۹، بہار شریعت)\n (۶)…اس طرح ذبح کرنا کہ چھری حرام مغز تک پہنچ جائے یا سر کٹ کر جدا ہوجائے مکروہ ہے ۔ مگر وہ ذبیحہ کھایا جائے گا یعنی کراہت اس فعل میں ہے نہ کہ ذبیحہ میں۔ ([4]) (ہدایہ، بہار شریعت)\n (۷)…بکری اور بھینس وغیرہ میں بائیس چیزیں ناجائز ہیں:۱۔ اوجھڑی، ۲۔ آنتیں ، ۳۔ مثانہ، ۴۔ خصیے ، ۵۔ ذکریعنی علامت نر، ۶۔ فرج یعنی علامت مادہ، ۷۔ پاخانہ کا مقام، ۸۔ رگوں کا خون، ۹۔ گوشت کا خون جو ذبح کے بعد گوشت میں نکلتا ہے ، ۱۰۔ دل کا خون ، ۱۱۔ جگر کا خون ، ۱۲۔ طحال کا خون، ۱۳۔ پتہ، ۱۴۔ پت یعنی وہ زرد پانی جو کہ پتہ میںہوتا ہے ، ۱۵۔ غدود ، ۱۶۔ حرام مغز، ۱۷۔ گردن کے دو پٹھے جو شانوں تک کھنچے رہتے ہیں ، ۱۸۔ ناک کی رطوبت ، ۱۹۔ نطفہ خواہ نر کی منی مادہ میں پائی جائے یا خود اس جانور کی منی ہو، ۲۰۔ وہ خون جو رحم میں نطفہ سے بنتا ہے ، ۲۱۔ وہ گوشت کا ٹکڑا جو رحم میں نطفہ سے بنتا ہے چاہے اعضا بنے ہوں یا نہ بنے ہوں ، ۲۲۔ بچہ تام الخلقت یعنی جو رحم میں پورا جانور بن گیا اور مردہ نکلا یا بغیر ذبح مرگیا۔\n (۸)…اولیائے کرام کی نذر و نیاز کے جانور کا گوشت جائز ہے جب کہ بِسْمِ اللّٰہ اللّٰہ اَکْبَر کہہ کرذبح کیا گیا ہو جیسا کہ تفسیرات احمدیہ ص ۴۲پارہ دوم کی آیت کریمہ:{ وَ مَاۤ اُهِلَّ بِهٖ لِغَیْرِ اللّٰهِۚ- }کے تحت ہے :\n’’ اَلْبَقَرَۃُ الْمَنْذُوْرَۃُ لِلْأَوْلِیَاء کَمَا ھُوَ الرَّسْمُ فِیْ زَمَانِنَا حَلاَلٌ طَیبٌ لِأَنَّہُ لَمْ یُذْکَرِ اسْمُ غَیْرِ ا ﷲِ عَلَیْھَا وَقْتَ الذبْح وَإِنْ کَانُوْا یَنْذُرُوْنَھَا لَہُ ‘‘۔ ([5])\n (۹)…شکاری جانور کا کیا ہوا شکار مندرجہ ذیل شرطوں کے ساتھ جائز ہے ۔ اول۔ شکاری جانور مسلمان کا ہو اور سکھایا ہوا ہو۔ دوم۔ اس نے شکار کو زخم لگا کر مارا ہو دبوچ کر نہ مارا ہو۔ سوم۔ شکاری جانور بِسْمِ اللّٰہ اللّٰہ اَکْبَر کہہ کر چھوڑا گیا ہو۔ چہارم۔ اگر شکار کے مرنے سے پہلے شکاری اس کے پاس پہنچا تو اس نے بِسْمِ اللّٰہ اللّٰہ اَکْبَر کہہ کر اسے ذبح کیا ہو۔ ان شرطوں میں سے اگر کوئی شرط نہ پائی گئی تو جانور حلال نہ ہوگا۔ ([6]) (خزائن العرفان)\n (۱۰)…سکھائے ہوئے شکاری جانور کی پہچان یہ ہے کہ اگر شکار پر چھوڑا جائے تو چھٹ جائے اور روکا جائے تو رک جائے اور شکار کیے ہوئے جانور کو مالک کے لیے چھوڑ رکھے اس میں سے کچھ نہ کھائے ۔ تفسیر جلالین ص: ۹۳میں ہے : عَلَامَتُہَا أَنْ تُسْتَرْسَلَ إِذَا أُرْسِلَتْ وَتُنْزَجَرَ إِذَا زُجِرَتْ وَتُمْسِکَ الصَّیْدَ وَلَا تَأْکُلُ مِنْہ ۔ ([7])\n (۱۱)…بندو ق یا غلیل کا کیا ہوا شکار اگر مرجائے تو حرام ہے ۔ ([8]) (رد المحتار، بہارشریعت) اور فتاوی قاضی خاں میں ہے ۔ لَا یَحِلُّ صَیْدُ البندَقۃِ وَالحَجرِ اہـ ([9])\n (۱۲)…جو شکار شوقیہ محض بغرض تفریح ہو، بندوق غلیل کا ہو خواہ مچھلی کا روزانہ ہو خواہ کبھی کبھی مطلقاً بالاتفاق حرام ہے ۔ درمختار، کتاب الصید میں ہے ۔ ہُوَ مُبَاحٌ إلَّا لِلتَّلَہِّی کَمَا ہُوَ ظَاہِرٌ ‘‘۔ ([10])\n (۱۳)…بعض لوگ مچھلیوں کے شکار میں زندہ مچھلی یا زندہ مینڈکی کانٹے میں پرو دیتے ہیں اور اس سے بڑی مچھلی پھنساتے ہیں ایسا کرنا منع ہے ۔ کہ اس سے جانور کو ایذا دینا ہے ۔ اسی طرح زندہ گھنیسا( کیچوا ) کانٹے میں پرو کر شکار کرتے ہیں یہ بھی منع ہے ۔ ([11]) (بہار شریعت، جلد ہفدہم ص ۲۷۳۰)\n (۱۴)…بعض لوگ قصاب کے پیشہ کو مکروہ سمجھتے ہیں حالانکہ اس کی کر اہت کا قول کسی سے منقول نہیں۔ ([12]) (بہار شریعت بحوالہ رد المحتار)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ پانزدہم، ص ۱۱۵، ’’ الدر المختار ‘‘، باب الذبائح ، ج ۹، ص ۴۹۱-۴۹۳۔ \n[2] ’’ الدر المختار ‘‘، کتاب الحظر والإباحۃ ، ج ۹، ص ۵۶۹.\n[3] ’’ بہارِ شریعت‘‘، حصہ پانزدہم، ص ۱۱۹، ’’ الہدایۃ ‘‘، باب الذبائح ، ج ۲، ص ۳۴۷۔ \n[4] ’’بہار ِشریعت‘‘، حصہ پانزدہم ، ص۱۱۸، ’’ الہدایۃ ‘‘، باب الذبائح ، ج ۲، ص ۳۵۰۔ \n[5] ’’ التفسیرات الأحمدیۃ ‘‘، سورۃ البقرۃ ، ص ۴۵.\n[6] ’’ خزائن العرفان ‘‘، ص ۱۹۴.\n[7] ’’ التفسیر الجلالین ‘‘، پارہ ۶، سورۃ المائدۃ ، ص ۹۵.\n[8] ’’بہار شریعت‘‘ ، حصہ ہفدہم، ص۲۷، ’’ رد المحتار ‘‘، ج ۱۰، ص ۴۹۔ \n[9] ’’ الفتاوی القاضی خاں ‘‘، کتاب الصید والذبایح ، ج ۲، ص ۳۳۸.\n[10] ’’ الدر المختار ‘‘، کتاب الصید ، ج ۱۰، ص ۵۳. \n[11] ’’ بہارِ شریعت ‘‘، حصہ ہفدہم ، ص۳۰.\n[12] ’’ بہارِ شریعت ‘‘، حصہ ہفدہم، ص۱۸."}, {"id": 7838, "bookId": 14, "volNo": "1", "hadithNo": 70, "chapter": "قربانی کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ زَیْدِ بْنِ أَرْقَمَ قَالَ قَالَ أَصْحَابُ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَا رَسُولَ اللّٰہ مَا ہَذِہِ الْأَضَاحِیُّ قَالَ سُنَّۃُ أَبِیکُمْ إِبْرَاہِیمَ عَلَیْہِ السَّلَامُ قَالُوا فَمَا لَنَا فِیہَا یَا رَسُولَ اللّٰہ قَالَ بِکُلِّ شَعْرَۃٍ حَسَنَۃٌ قَالُوا فَالصُّوفُ یَا رَسُولَ اللّٰہ قَالَ بِکُلِّ شَعْرَۃٍ مِنْ الصُّوفِ حَسَنَۃٌ‘‘۔ \nحدیث 2:\n’’عَنْ عَائِشَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا عَمِلَ ابْنُ آدَمَ مِنْ عَمَلٍ یَوْمَ النَّحْرِ أَحَبَّ إِلَی اللّٰہ مِنْ إِہْرَاقِ الدَّمِ وَإِنَّہُ لَیَأْتِی یَوْمَ الْقِیَامَۃِ بِقُرُونِہَا وَأَشْعَارِہَا وَأَظْلَافِہَا وَإِنَّ الدَّمَ لَیَقَعُ مِنَ اللّٰہ بِمَکَانٍ قَبْلَ أَنْ یَقَعَ بِالْأَرْضِ ‘‘۔\nحدیث 3:\n’’ عَنْ حَنَشٍ قَالَ رَأَیْتُ عَلِیًّا یُضَحِّی بِکَبْشَیْنِ فَقُلْتُ لَہُ مَا ہَذَا فَقَالَ إِنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَوْصَانِی أَنْ أُضَحِّیَ عَنْہُ فَأَنَا أُضَحِّی عَنْہُ‘‘۔ \nحدیث 4:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ وَجَدَ سَعَۃً وَلَمْ یُضَحِّ فَلَا یَقْرُبَنَّ مُصَلَّانَا‘‘۔\nحدیث 5:\n’’ عَنْ أُمِّ سَلَمَۃَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِذَا رَأَیْتُمْ ہِلَالَ ذِی الْحِجَّۃِ وَأَرَادَ أَحَدُکُمْ أَنْ یُضَحِّیَ فَلْیُمْسِکْ عَنْ شَعْرِہِ وَأَظْفَارِہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت زید بن ارقم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام کے صحابہ نے عرض کیا کہ یارسول اللّٰہ ! یہ قربانیاں کیا ہیں؟ آپ نے فرمایا یہ تمہارے باپ حضرات ابراہیم علیہ السلام کی سنت ہے ۔ صحابہ نے عرض کیا یارسول اللّٰہ ! کیا اس سے ہم کو ثواب ملے گا۔ ؟ فرمایا ہر بال کے بدلے ایک نیکی ہے عرض کیا اور اون یارسول اللّٰہ ! تو آپ نے فرمایا کہ اون کے ہر بال میں بھی ایک نیکی ملے گی۔ (احمد، ا بن ماجہ)\n¥ترجمہ حدیث 2:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ قربانی کے ایام میں ابن آدم کا کوئی عمل خدائے تعالی کے نزدیک خون بہانے (یعنی قربانی کرنے )سے زیادہ پیارا نہیں اور وہ جانور قیامت کے دن اپنے سینگوں ، بالوں، کھروں کے ساتھ آئے گا اور قربانی کا خون زمین پر گرنے سے قبل خدائے تعالی کے نزدیک مقام قبول میں پہنچ جاتا ہے ۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 3:\nحضرت حنش رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضرت علی کرم اللّٰہ تعالی وجہہ کو دو دنبے ذبح کرتے ہوئے دیکھا میں نے پوچھا یہ کیا ہے ؟ انہوں نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے مجھے وصیت فرمائی ہے \n کہ میں حضور کی جانب سے قربانی کیا کروں تو میں ( دوسرا دنبہ حضور کی جانب سے ) قربانی کررہا ہوں۔ (ابوداود)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس میں وسعت ہو اور قربانی نہ کرے تو وہ ہماری عیدگاہ کے قریب ہر گز نہ آئے ۔ (ابن ماجہ)\n¥ترجمہ حدیث 5:\nحضرت اُم سلمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا سے روایت ہے کہ نبی کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جب تم بقرعید کا چاند دیکھو اور تم میں کا کوئی قربانی کرنا چاہے تو اس کو چاہیے کہ بال منڈانے ، ترشوانے اور ناخن کٹوانے سے رکا رہے ۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Zaid Bin Arqam Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alaihi wa Sallam ke Sahabah ne arz kiya ke Ya Rasoolullah! Ye Qurbani kya hain? Aap ne farmaya ye tumhare baap hazrat Ibrahim Alayhis Salam ki Sunnat hai. Sahabah ne arz kiya Ya Rasoolullah! Kya is se hum ko sawab milega? Farmaya har Baal ke badle ek neki hai. Arz kiya aur oon Ya Rasoolullah! To Aap ne farmaya ke oon ke har Baal mein bhi ek neki milegi. (Ahmad, Ibn Majah). Tarjuma Hadees 2: Hazrat Aishah Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke Qurbani ke ayyam mein Ibn-e-Adam ka koi amal Allah Ta'ala ke nazdeek khoon bahane (yani Qurbani karne) se zyada pyara nahi aur woh janwar Qayamat ke din apne seengon, Baalon, khuron ke sath aayega aur Qurbani ka khoon Zameen par girne se qabl Allah Ta'ala ke nazdeek maqam-e-Qubool mein pahunch jata hai. (Tirmidhi, Ibn Majah). Tarjuma Hadees 3: Hazrat Hanish Radiyallahu Anhu ne farmaya ke main ne Hazrat Ali Radiyallahu Anhu ko do dambay Zibah karte hue dekha, main ne poocha ye kya hai? Unhon ne farmaya ke Rasoolullah Sallallahu Alaihi wa Sallam ne mujhe Wasiyat farmayi hai ke main Rasoolullah Sallallahu Alaihi wa Sallam ki janib se Qurbani kiya karoon to main (dusra damba Rasoolullah Sallallahu Alaihi wa Sallam ki janib se) Qurbani kar raha hoon. (Abu Dawood). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jis mein wus'at ho aur Qurbani na kare to woh hamari eid-gah ke qareeb hargiz na aaye. (Ibn Majah). Tarjuma Hadees 5: Hazrat Umm-e-Salamah Radiyallahu Anha se riwayat hai ke Nabi Kareem Sallallahu Alaihi wa Sallam ne farmaya ke jab tum baqra-eid ka chand dekho aur tum mein ka koi Qurbani karna chahe to us ko chahiye ke Baal mundane, tarashwane aur Naakhun katwane se ruka rahe. (Muslim).", "explanation": "¥اِنتباہ :\n (۱)…قربانی کے مسئلے میں صاحبِ نصاب وہ شخص ہے جو ساڑھے باون تولہ چاندی یا ساڑھے سات تولہ سونا کا مالک ہو یا ان میں سے کسی ایک کی قیمت کا سامانِ تجارت یا سامانِ غیر تجارت کا مالک ہو اور مملوکہ چیزیں حاجت اصلیہ سے زائد ہوں۔\n (۲)…جو مالکِ نصاب اپنے نام سے ایک بار قربانی کرچکا ہے اور دوسرے سال بھی وہ صاحبِ نصاب ہے تو پھر اس پر اپنے نام سے قربانی واجب ہے اور یہی حکم ہر سال کا ہے ۔\n حدیث میں ہے ۔ ’’ إِنَّ عَلَی کُلِّ أَہْلِ بَیْتٍ فِی کُلِّ عَامٍ أُضْحِیَّۃً ‘‘۔ ([1]) (ترمذی)\n (۳)…اگر کوئی صاحبِ نصاب اپنی طرف سے قربانی کرنے کے بجائے دوسرے کی طرف سے کردے اور اپنے نام سے نہ کرے تو سخت گنہ گار ہوگا لہذا اگر دوسرے کی طرف سے بھی کرنا چاہتا ہے تو اس کے لیے ایک دوسری قربانی کا انتظام کرے ۔\nٍ (۴)…بعض لوگوں کا جو یہ خیال ہے کہ’’ اپنی طرف سے زندگی میں صرف ایک بار قربانی واجب ہے ‘‘ شرعاً غلط اور بے بنیادہے اس لیے کہ مالکِ نصاب پر ہرسال اپنے نام سے قربانی واجب ہے ۔\n (۵)…دیہات میں دسویں ذی الحجہ کو طلوعِ صبح صادق کے بعد ہی سے قربانی کرناجائز ہے لیکن مستحب یہ ہے کہ سورج نکلنے کے بعد کرے ۔ فتاوی عالمگیری جلد پنجم مصری ص۲۶۰ میں ہے : ’’ وَالْوَقْتُ الْمُسْتَحَبُّ لِلتَّضْحِیَۃِ فِی حَقِّ أَہْلِ السَّوَادِ بَعْدَ طُلُوعِ الشَّمْسِ ‘‘۔ ([2])\n (۶)…شہر میں نماز عید سے پہلے قربانی کرنا جائز نہیں۔ ([3]) (بہار شریعت)\n (۷)… شہری آدمی کو قربانی کاجانور دیہات میں بھیج کر نماز عید سے پہلے قربانی کرا کے گوشت کو شہر میں منگالینا جائز ہے ۔ درمختار مع ردالمحتار جلد پنجم ص۲۰۹ میں ہے ۔ ’’ حِیلَۃُ مِصْرِیٍّ أَرَادَ التَّعْجِیلَ أَنْ یُخْرِجَہَا لِخَارِجِ الْمِصْرِ فَیُضَحِّی بِہَا إذَا طَلَعَ الْفَجْرُ ‘‘۔ ([4]) \n (۸)… قربانی کا چمڑا یا گوشت یا اس میں کی کوئی چیز قصاب یا ذبح کرنے والے کواجرت میں دینا جائز نہیں۔\n درمختار میں ہے : ’’ لَا یُعْطَی أَجْرُ الْجَزَّارِ مِنْہَا ‘‘ ۔ ([5]) \n (۹)…قربانی کا گوشت کا فر کو دینا جائز نہیں۔ ([6]) \n (۱۰)…قربانی کے جانور کو بائیں پہلو پر اس طرح لٹائیں کہ اس کا منہ قبلہ کی طرف ہو اور اپنا داہنا پاؤں اس کے پہلو پر رکھیں اور ذبح سے پہلے یہ دعا پڑھیں۔\n ’’ إنِّی وَجَّہْتُ وَجْہِی لِلَّذِی فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِیفًا وَمَا أَنَا مِنْ الْمُشْرِکِینَ إنَّ صَلَاتِی وَنُسُکِی وَمَحْیَایَ وَمَمَاتِی لِلَّہِ رَبِّ الْعَالَمِینَ لَا شَرِیکَ لَہُ وَبِذَلِکَ أُمِرْتُ وَأَنَا مِنْ الْمُسْلِمِینَ پھر أَللَّہُمَّ مِنْک وَلَکَ بِسْمِ اللّٰہ اللّٰہ أَکْبَرُ ‘‘ پڑھتے ہوئے تیز چھری سے ذبح کریں۔ قربانی اپنی طرف سے ہو تو ذبح کے بعد یہ دعا پڑھیں۔ ’’ أَللَّھُمَّ تَقَبَّلْ مِنِّیْ کَمَا تَقَبَّلْتَ مِنْ خَلِیْلِکَ إِبْرَاھِیْمَ عَلَیْہِ السَّلَامُ وَحَبِیْبِکَ مُحَمَّدٍ صَلَّی اللّٰہتَعَالَی عَلَیْہِ وَسَلَّمَ ‘‘ اور اگردوسرے کی طرف سے ذبح کرتا ہے تو مِنِّیْ کی جگہ مِن ْ کے بعد اس کا نام لے ۔ ([7])\n------------------\n[1] ’’ سنن الترمذی ‘‘، کتاب الأضاحی ، باب الأذان فی أذن المولود ، الحدیث : ۱۵۲۳، ج ۳، ص ۱۷۵.\n[2] ’’ الفتاوی الھندیۃ ‘‘، کتاب الأضحیۃ ، الباب الثالث فی وقت الأضحیۃ ، ج ۵، ص ۲۹۵.\n[3] ’’بہارِ شریعت ‘‘، حصہ پانزدہم، ص۱۳۷.\n[4] ’’ الدر المختار ورد المحتار ‘‘، کتاب الأضحیۃ ، ج ۹، ص ۵۲۹.\n[5] ’’ الدر المختار ‘‘، کتاب الأضحیۃ ، ج ۹، ص ۵۴۳ .\n[6] ’’بہار شریعت ‘‘، حصہ پانزدہم، ص۱۴۴.\n[7] ’’بہار شریعت‘‘، حصہ پانزدہم، ص۱۵۰."}, {"id": 7839, "bookId": 14, "volNo": "1", "hadithNo": 71, "chapter": "عقیقہ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ سَلْمَانَ بْنِ عَامِرٍ الضَّبِّیِّ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَعَ الْغُلَامِ عَقِیقَۃٌ فَأَہْرِیقُوا عَنْہُ دَمًا‘‘۔\nحدیث 2:\n’’عَنْ ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَقَّ عَنِ الْحَسَنِ وَالْحُسَیْنِ کَبْشًا کَبْشًا رَوَاہُ أَبُوْ دَاودَ وَعِنْدَ النَّسَاءِیْ کَبْشَیْنِ کَبْشَیْنِ‘‘۔ \nحدیث 3:\n’’عَنْ عَمْرِو بْنِ شُعَیْب عَنْ أَبِیہِ عَنْ جَدِّہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ وُلِدَ لَہُ وَلَدٌ فَأَحَبَّ أَنْ یَنْسُکَ عَنْہُ فَلْیَنْسُکْ عَنْ الْغُلَامِ شَاتَیْنِ وَعَنِ الْجَارِیَۃِ شَاۃٌ ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت سلمان بن عامر ضبی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ لڑکے ( کی پیدائش) کے ساتھ عقیقہ ہے لہذا اس کی جانب سے جانور ذبح کرو ۔ (بخاری شریف)\n¥ترجمہ حدیث 2:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ماسے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے حضرت امام حسن وامام حسین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما کا عقیقہ ایک ایک مینڈھے سے کیا۔ (ابوداود) اور امام نسائی کی روایت میں دو دو مینڈھے کا ذکر ہے ۔ \n¥ترجمہ حدیث 3:\nحضرت عمرو بن شعیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما اپنے باپ سے اور و ہ اپنے دادا (حضرت عبد اللّٰہ ) سے روایت کرتے ہیں انہوں نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس شخص کے کوئی اولاد پیدا ہوئی پھر اس نے اس کی طرف سے جانور ذبح کرنا چاہا تو وہ لڑکے کی جانب سے دو بکری اور لڑکی کی طرف سے ایک بکری ذبح کرے ۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Salman Bin Aamir Dhabbi Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alaihi wa Sallam ko farmate hue suna ke ladke (ki paidaish) ke sath Aqeeqah hai lehaza us ki janib se janwar Zibah karo. (Bukhari Shareef). Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne Imam Hasan aur Imam Hussain Radiyallahu Anhum ka Aqeeqah ek ek mendhay se kiya. (Abu Dawood) aur Imam Nasa'i ki riwayat mein do do mendhay ka zikr hai. Tarjuma Hadees 3: Hazrat Amr Bin Shuaib Radiyallahu Anhum apne baap se aur woh apne dada (Hazrat Abdullah) se riwayat karte hain, unhon ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jis Shakhs ke koi Aulaad paida hui phir us ne us ki taraf se janwar Zibah karna chaha to woh ladke ki janib se do bakri aur Ladki ki taraf se ek bakri Zibah kare. (Abu Dawood).", "explanation": "¥اِنتباہ :\n (۱)…عقیقہ کے لیے ساتواں دن بہتر ہے اور ساتویں دن نہ کرسکے تو جب چاہے کرسکتا ہے سنت ادا ہوجائے گی۔ ([1])\n (۲)…لڑکے کے عقیقہ میںدوبکرے اور لڑکی کے عقیقہ میںایک بکری ذبح کی جائے یعنی لڑکے میں نر جانور اور لڑکی میں مادہ مناسب ہے لیکن اگر لڑکے کے عقیقہ میں بکریاں اور لڑکی کے عقیقہ میں بکراذبح کیا جب بھی حرج نہیں۔ ([2]) (بہار شریعت)\n (۳)… قربانی کی طرح عقیقہ میں بھی بکرا اور بکری کی عمر ایک سال ہونا ضروری ہے ۔ ([3])(بہار شریعت)\n (۴)…عوام میں جو مشہور ہے کہ ’’ عقیقہ کا گوشت بچہ کے ماں باپ، دادا دادی اور نانانانی نہ کھائیں‘‘ یہ غلط ہے ۔ اس کا کوئی ثبوت نہیں ۔ ([4])(بہار شریعت)\n (۵)…عقیقہ کے جانور کو ذبح کرنے کے لیے بائیں پہلو پر اس طرح لٹائیں کہ اس کا منہ قبلہ کی طرف ہو اور ذبح سے پہلے یہ دعا پڑھے ۔ ’’ أَللَّھُمَّ ھَذِہِ الْعَقِیْقَۃُ لِابْنِیْ فُلانٍ دَمُھَا بِدَمِہِ وَلَحْمُھَا بِلَحْمِہِ وَعَظْمُھَا بِعَظْمِہِ وَجِلْدُھَا بِجِلْدِہِ وَشَعْرُھَا بِشَعْرِہِ أَللَّھُمَّ اجْعَلْھَا فِدَاء لِابْنِیْ مِنَ النَّارِ إنِّی وَجَّہْتُ وَجْہِی لِلَّذِی فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِیفًا وَمَا أَنَا مِنْ الْمُشْرِکِیْنَ ۔ إنَّ صَلَاتِی وَنُسُکِی وَمَحْیَایَ وَمَمَاتِی لِلَّہِ رَبِّ الْعَالَمِیْنَ لَا شَرِیکَ لَہُ وَبِذَلِکَ أُمِرْتُ وَأَنَا مِنْ الْمُسْلِمِینَ پھر أَللَّہُمَّ مِنْک وَلَکَ بِسْمِ اللّٰہ اللّٰہ أَکْبَرُ ‘‘ کہہ کر ذبح کرے ۔ اگر اپنا لڑکا ہو تو دعا میں لابْنِیْ کے بعد فُلان کی جگہ اپنے لڑکے کا نام لے ۔ اور اگر اپنی لڑکی ہو لِاِبْنِی کی جگہ لابْنَتِیْ کہہ کر لڑکی کا نام لے ۔ اور اگر دوسرے کا لڑکا ہو تو اِبنی فلان کی جگہ لڑکے کا نام ولدیت کے ساتھ لے اور لڑکے کے عقیقہ میں دَمُھَا بِدَمِہِ وَلَحْمُھَا بِلَحْمِہِ وغیرہ مذکر کی ضمیر کے ساتھ پڑھا جائے گا اور لڑکی کے عقیقہ میں دُمُھَا بِدَمِھَا وَلَحْمُھَا بِلَحْمِھَا وغیرہ مؤنث کی ضمیر کے ساتھ پڑھا جائے گا۔\n------------------\n[1] ’’بہار شریعت‘‘، حصہ پانزدہم، ص ۱۵۴.\n[2] ’’بہار شریعت‘‘، حصہ پانزدہم، ص۱۵۴.\n[3] ’’بہار شریعت‘‘، حصہ پانزدہم، ص۱۵۵.\n[4] ’’بہار شریعت‘‘، حصہ پانزدہم، ص۱۵۵."}, {"id": 7840, "bookId": 14, "volNo": "1", "hadithNo": 72, "chapter": "اچھے برے نام کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ أَحَبَّ أَسْمَاءِکُمْ إِلَی اللّٰہ عَبْدُ اللّٰہ وَعَبْدُ الرَّحْمٰنِ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی الدَّرْدَاء قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تُدْعَوْنَ یَوْمَ الْقِیَامَۃِ بِأَسْمَاءِکُمْ وَأَسْمَاءِ آبَاءِکُمْ فَأَحْسِنُوا أَسْمَاءَکُمْ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی وَہْبِنِ الْجُشَمِیِّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَسَمَّوْا بِأَسْمَاء الْأَنْبِیَاء ‘‘۔ \nحدیث 4:\n’’عَنْ جَابِرٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ سَمُّوْا بِاِسْمِیْ‘‘۔ \nحدیث 5:\n’’عَن عَبْدِ اللّٰہ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ وُلِدَ لَہُ ثَلاثَۃُ أَوْلَادٍ فَلَمْ یُسَمِّ أَحَدًا مِنْہُمْ مُحَمَّدًا فَقَدْ جَہلَ‘‘۔ \nحدیث 6:\n’’ عَنْ عَائِشَۃَ قَالَتْ إِنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ یُغَیِّرُ الاسْمَ الْقَبِیحَ‘‘۔ \nحدیث 7:\n’’عَنْ ابْنِ عُمَرَ أَنَّ بِنْتًا لِعُمَرَ یُقَالُ لَہُ عَاصِیَۃُ فَسَمَّاہَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ جَمِیلَۃَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالی کے نزدیک تمہارے ناموں میں بہترین نام عبد اللّٰہ اور عبدالرحمن ہے ۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابودرداء رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ قیامت کے دن تم کو تمہارے نام اور تمہارے باپوں کے نام سے پکاراجائے گا۔ لہذا اپنے نام اچھے رکھو۔ (احمد، ابوداود)\n¥ترجمہ حدیث 3:\nحضرت ابووہب جشمی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ انبیاء کے ناموں پر نام رکھو۔ (ابوداود)\n¥ترجمہ حدیث 4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ میرے نام پر نام رکھو۔ (بخاری، مسلم)\n¥ترجمہ حدیث 5:\nحضرت عبد اللّٰہ بن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جس شخص کے تین بیٹے پیدا ہوں اور وہ ان میں سے کسی کا نام بھی محمد نہ رکھے تو وہ بالیقین ( ایمان و عشق) کے تقاضے سے جاہل ہے ۔ (طبرانی کبیر)\n¥ترجمہ حدیث 6:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ انے فرمایا کہ نبی کریم علیہ الصلاۃ والتسلیم برے نام کو ( اچھے نام سے ) بدل دیا کرتے تھے ۔ (ترمذی)\n¥ترجمہ حدیث 7:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما سے روایت ہے کہ حضرت فاروق اعظم کی ایک صاحبز ادی تھیں جن کا نام عاصیہ تھا رسولِ کریم علیہ الصلاۃ والتسلیم نے ان کا نام بدل کر جمیلہ رکھ دیا۔ (مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke Allah Ta'ala ke nazdeek tumhare naamon mein behtareen naam Abdullah aur Abdur Rahman hai. (Muslim). Tarjuma Hadees 2: Hazrat Abu Darda Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke Qayamat ke din tum ko tumhare naam aur tumhare baapon ke naam se pukara jayega. Lehaza apne naam achhe rakho. (Ahmad, Abu Dawood). Tarjuma Hadees 3: Hazrat Abu Wahb Jushmi Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke Ambiya ke naamon par naam rakho. (Abu Dawood). Tarjuma Hadees 4: Hazrat Jabir Radiyallahu Anhu ne kaha ke Sarkaar-e-Aqdas Sallallahu Alaihi wa Sallam ne farmaya ke mere naam par naam rakho. (Bukhari, Muslim). Tarjuma Hadees 5: Hazrat Abdullah Bin Abbas Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya ke jis Shakhs ke teen bete paida hon aur woh un mein se kisi ka naam bhi Muhammad na rakhe to woh bil-yaqeen (imaan-o-ishq) ke taqaze se jahil hai. (Tabarani Kabeer). Tarjuma Hadees 6: Hazrat Aishah Radiyallahu Anha ne farmaya ke Nabi Kareem Sallallahu Alaihi wa Sallam bure naam ko (achhe naam se) badal diya karte the. (Tirmidhi). Tarjuma Hadees 7: Hazrat Ibn Umar Radiyallahu Anhum se riwayat hai ke Farooq-e-Azam ki ek sahibzadi thin jin ka naam Aasiyah tha, Rasoolullah Sallallahu Alaihi wa Sallam ne un ka naam badal kar Jameelah rakh diya. (Muslim).", "explanation": "¥اِنتباہ :\n (۱)…جس کا نام عبدالرحمن ، عبدالخالق ، عبدالمعبود ، عبدالقدوس ، یا عبدالقیوم ہو اسے رحمن ، خالق ، معبود، قدوس، قیوم کہنا حرام ہے اس لیے کہ ان کا اطلاق غیر اللّٰہ پر ناجائز ہے ۔ ہاں اگر عبدالرحیم ، عبدالکریم ، عبدالعزیز کے قسم کا نام ہو تو رحیم، کریم اور عزیز کہہ سکتے ہیں اس لیے کہ ان کا اطلاق غیر اللّٰہ پر جائز ہے ۔\n (۲)…عبدا لمصطفیٰ ، عبدالرسول ، عبدالنبی نام رکھنا جائز ہے کہ اس نسبت کی شرافت مقصود ہے اور عبودیت کے حقیقی معنی یہاں مقصود نہیں ہیں۔ رہی عبد کی اضافت غیر اللّٰہ کی طرف تو یہ قرآن و حدیث سے ثابت ہے ۔ ([1]) (بہار شریعت)\n (۳)…غلام محمد، غلام علی، غلام حسن ، غلام حسین وغیرہ جن میں انبیاء ، صحابہ یا اولیائے کرام کے نام کی طرف غلام کی اضافت کرکے نام رکھا جائے جائز ہے ۔ اسی طرح محمد بخش ، نبی بخش، پیر بخش ، علی بخش، حسین بخش وغیرہ جن میں کسی نبی یا ولی کے نام کے ساتھ بخش کا لفظ ملایا گیا ہو جائز ہے ۔ ([2]) (بہار شریعت)\n (۴)…محمدنبی، احمد نبی، محمد رسول ، رسول اللّٰہ ، نبی اللّٰہ یا نبی الزمان نام رکھنا حرام ہے کہ ان میں حقیقۃً ادعائے نبوت نہ ہونا مسلّم ورنہ خالص کفر ہوتا ۔ مگرصورتِ ادّعا ضرور ہے اور وہ یقیناً حرام ہے ۔ ([3]) (احکام شریعت، بہار شریعت)\n (۵)…انبیائے کرام علیہم الصلاۃ والسلام اور اولیائے عظام رَضِیَ اللّٰہ تَعَالٰی عَنْہُم کی بیویوں اور لڑکیوں نیز صحابیات رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ن کا مبارک سنجیدہ اور پروقار نام چھوڑ کر آج کل لوگوں نے بازاری عورتوں کے بھڑک دار نام پر اپنی لڑکیوں کا نام رکھنا اختیار کر لیا ہے ۔ جیسے نجمہ، ثریا ، مشتری اور پروین وغیرہ ۔ ایسا ہر گز نہ چاہیے ۔\n------------------\n[1] ’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۲۴۷.\n[2] ’’بہارِ شریعت‘‘، حصہ ۱۶، ص ۲۴۷، ’’ الحدیقۃ الندیۃ شرح طریقۃ المحمدیہ ‘‘، ج ۲، ص ۲۷۹.\n[3] ’’بہارِ شریعت‘‘، حصہ۱۶، ص ۲۴۸. ’’احکام شریعت‘‘، حصہ اول، ص۹۰۔"}, {"id": 7841, "bookId": 14, "volNo": "1", "hadithNo": 73, "chapter": "کھانے کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ حُذَیْفَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الشَّیْطَانَ یَسْتَحِلُّ الطَّعَامَ أَنْ لَا یُذْکَرَ اسْمُ اللّٰہ عَلَیْہِ‘‘۔ \nحدیث 2:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَکَلَ أَحَدُکُمْ فَلْیَأْکُلْ بِیَمِیْنِہِ وَإِذَا شَرِبَ فَلْیَشْرَبْ بِیَمِیْنِہِ‘‘۔ \nحدیث 3:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَأْکُلَنَّ أَحَدُکُمْ بِشِمَالِہِ وَلَا یَشْرَبَنَّ بِہَا فَإِنَّ الشَّیْطَانَ یَأْکُلُ بِشِمَالِہِ وَیَشْرَبُ بِہَا‘‘۔ \nحدیث 4:\n’’عَنْ عَائِشَۃَ قَالَتْ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یُحِبُّ الْحَلْوَاء وَالْعَسلَ‘‘۔ \nحدیث 5:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا وَقَعَ الذُّبَابُ فِی إِنَاءِ أَحَدِکُمْ فَامْقُلُوہُ فَإِنَّ فِی أَحَدِ جَنَاحَیْہِ دَاءً وَفِی الْآخَرِ شِفَاءً فَإِنَّہُ یَتَّقِی بِجَنَاحِہِ الَّذِی فِیہِ الدَّاء فَلْیَغْمِسْہُ کُلّہُ‘‘۔ \nحدیث 6:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَال َمَا عَابَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ طَعَامًا قَطُّ إِن اشْتَہَاہُ أَکَلَہُ وَإِنْ کَرِھَہُ تَرَکَہُ‘‘۔\nحدیث 7:\n’’عَنْ عَائِشَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَکَلَ أَحَدُکُمْ فَنَسِیَ أَنْ یَذْکُرَ اللّٰہ عَلَی طَعَامِہِ فَلْیَقُلْ بِسْمِ اللّٰہ أَوَّلَہُ وَآخِرَہِ‘‘۔ \nحدیث 8:\n’’عَنْ أَبِی سَعِیدٍ الْخُدْرِیِّ قَالَ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا فَرَغَ مِنْ طَعَامِہِ قَالَ الْحَمْدُ لِلَّہِ الَّذِی أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِینَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت حذیفہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس کھانے پر بسم اللّٰہ نہ پڑھا جائے اس کھانے کو شیطان اپنے لیے حلال سمجھتا ہے ۔ (مسلم) \n¥ترجمہ حدیث 2:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ تم میں سے جب کوئی شخص کچھ کھانا چاہے تو داہنے ہاتھ سے کھائے اور جب کوئی چیز پینا چاہے تو داہنے ہاتھ سے پیئے ۔ (مسلم شریف)\n¥ترجمہ حدیث 3:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کوئی شخص نہ بائیں ہاتھ سے کچھ کھائے اور نہ کچھ پیئے ۔ اس لیے کہ بائیں ہاتھ سے شیطان کھاتا اور پیتا ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 4:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ حضور علیہ الصلاۃ والسلام حلوا اور شہد پسند فرماتے تھے ۔ (بخاری شریف)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب کھانے میں مکھی گر جائے تواسے غوطہ دے دو(اورپھینک دو) کیونکہ اس کے ایک بازو میں بیماری ہے ۔ اور دوسرے میں شفا ہے اور اسی بازو سے اپنے کو بچاتی ہے جس میں بیماری ہے ( تو وہ کھانے میں پہلے پڑ جاتا ہے ) لہذا اسے پوری ڈبودو۔ (ابوداود)\n¥ترجمہ حدیث 6:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے کبھی کسی کھانے کو عیب نہیں لگایا (یعنی برا نہیں کہا) اگر خواہش ہوتی تو کھالیتے اور خواہش نہ ہوتی تو چھوڑ دیتے ۔ (بخاری)\n¥ترجمہ حدیث 7:\nحضرت عائشہ صدیقہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب کوئی شخص کھانا کھائے اور کھانے پر اللّٰہ کا نام لینا بھول جائے تو اس کو چاہیے کہ درمیان ہی میں یہ دعا پڑھ لے ۔ (ترمذی)\n¥ترجمہ حدیث 8:\nحضرت ابوسعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام جب کھانے سے فارغ ہوتے تو یہ دعا پڑھتے ۔ ’’ الْحَمْدُ لِلَّہِ الَّذِی أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِینَ ‘‘۔ (ترمذی، ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Huzaifah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis khanay par Bismillah na parha jaye us khanay ko shaitan apne liye Halal samajhta hai. (Muslim). Tarjuma Hadees 2: Hazrat Ibn Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke tum mein se jab koi shakhs kuch khana chahe to dahne hath se khaye aur jab koi cheez peena chahe to dahne hath se peeye. (Muslim Shareef). Tarjuma Hadees 3: Hazrat Ibn Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke koi shakhs na bayen hath se kuch khaye aur na kuch peeye. Is liye ke bayen hath se shaitan khata aur peeta hai. (Muslim Shareef). Tarjuma Hadees 4: Aisha Siddiqah Radiyallahu Anha ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam halwa aur shehad pasand farmate thay. (Bukhari Shareef). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab khanay mein makkhi gir jaye to use ghota de do (aur phenk do) kyunke uske ek baal mein bimari hai aur dusre mein shifa hai aur isi baal se apne ko bachati hai jis mein bimari hai (to woh khanay mein pehle par jata hai) lehaza use poori dubo do. (Abu Dawood). Tarjuma Hadees 6: Hazrat Abu Hurairah Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne kabhi kisi khanay ko aib nahi lagaya (yani bura nahi kaha) agar khwahish hoti to kha lete aur khwahish na hoti to chhod dete. (Bukhari). Tarjuma Hadees 7: Aisha Siddiqah Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab koi shakhs khana khaye aur khanay par Allah ka naam lena bhool jaye to usko chahiye ke darmiyan hi mein yeh Dua parh le. (Tirmidhi). Tarjuma Hadees 8: Hazrat Abu Saeed Khudri Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam jab khanay se farigh hote to yeh Dua parhte: 'Alhamdulillahilladhi at'amana wa saqana wa ja'alana muslimeen'. (Tirmidhi, Abu Dawood).", "explanation": "¥شرح حدیث 4:\nاس حدیث کے تحت حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں کہ:\n’’ حلوا بمد وقصر اطلاق کردہ نمی شود مگر برانچہ ساختہ باشند آنرا بصنعت وجامع باشد میاں چربی وشیرینی کذا فی مجمع البحار ‘‘۔ ([1]) ( اشعۃ اللمعات ، جلد سوم ص ۴۹۱)\n یعنی حلوا صرف اس کو کہا جاتا ہے کہ جو مخصوص طریقہ سے بنایا جاتا ہے اور میٹھا و چربی کا مجموعہ ہوتا ہے اسی طرح مجمع البحار میں ہے ۔ ( لہذا حلوا کا ترجمہ محض شیرینی کرنا صحیح نہیں ہے )۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الأطعمۃ ، الفصل الأول ، ج ۳، ص ۵۲۲.\n¥انتباہ :\n بعض دستر خوانوں پر اشعار لکھے رہتے ہیں ان کا بچھانا اور ان پر کھانا منع ہے ۔ ([1]) (بہار شریعت، جلد سوم ص ۳۸۷)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ ۱۶، ص ۶۳."}, {"id": 7842, "bookId": 14, "volNo": "1", "hadithNo": 74, "chapter": "پینے کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تَشْرَبُوا وَاحِدًا کَشُرْبِ الْبَعِیرِ وَلَکِنِ اشْرَبُوا مَثْنَی وَثُلَاثَ وَسَمُّوْا إِذَا أَنْتُمْ شَرِبْتُمْ وَاحْمَدُوْا إِذَا أَنْتُمْ رَفَعْتُمْ‘‘۔ \nحدیث 2:\n’’ عَنْ أَنَسٍ قَالَ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَتَنَفَّسُ فِی الشَّرَابِ ثَلَاثًا مُتَّفَقٌ عَلَیْہِ وَزَادَ مُسْلِمٌ فِیْ رِوَایَۃٍ وَیَقُولُ إِنَّہُ أَرْوَی وَأَبْرَأُ وَأَمْرَأُ ‘‘۔\nحدیث 3:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ نَہَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ یُتَنَفَّسَ فِی الْإِنَاء أَوْ یُنْفَخَ فِیہِ‘‘۔ \nحدیث 4:\n’’عَنْ أَنَسٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَّہُ نَہَی أَنْ یَشْرَبَ الرَّجُلُ قَاءِمًا‘‘۔ \nحدیث 5:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَشْرَبَنَّ أَحَدٌ مِنْکُمْ قَاءِمًا فَمَنْ نَسِیَ فَلْیَسْتَقِیٔ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما نے کہا کہ اونٹ کی طرح ایک سانس میں کوئی چیز نہ پیو۔ بلکہ دو دو تین تین مرتبہ میں پیو۔ اور جب پیو بِسْمِ اللّٰہ کہہ لو اور جب منہ سے ہٹاؤ تو اَلْحَمْدُ لِلّٰہ کہو۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام پینے میں تین بار سانس لیتے تھے ۔ اور امام مسلم کی روایت میں اتنا زیادہ ہے کہ حضور فرماتے تھے اس طرح پینے میں زیادہ سیرابی ہوتی ہے اور صحت کے لیے مفید و خوش گوار ( بھی )ہے ۔ (مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے برتن میں سانس لینے اور پھونکنے سے منع فرمایا۔ (ابوداود)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃو السلام نے کھڑے ہو کر پینے سے منع فرمایا ۔ (مسلم شریف)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کھڑے ہو کر ہر گز کوئی شخص نہ پیئے اور جو بھول کر ایسا کر گزرے تو وہ قے کردے ۔ (مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Abbas Radiyallahu Anhu ne kaha ke oont ki tarah ek saans mein koi cheez na peeyo. Balkay do do teen teen martaba mein peeyo. Aur jab peeyo Bismillah keh lo aur jab munh se hatao to Alhamdulillah kaho. (Tirmidhi). Tarjuma Hadees 2: Hazrat Anas Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam peene mein teen baar saans lete thay. Aur Imam Muslim ki Riwayat mein itna zyada hai ke Rasoolullah farmate thay is tarah peene mein zyada sairabi hoti hai aur sehat ke liye mufeed o khushgawar bhi hai. (Mishkat). Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne bartan mein saans lene aur phoonkne se mana farmaya. (Abu Dawood). Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne khade ho kar peene se mana farmaya. (Muslim Shareef). Tarjuma Hadees 5: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke khade ho kar har giz koi shakhs na peeye aur jo bhool kar aisa kar guzre to woh qai kar de. (Mishkat).", "explanation": "¥شرح حدیث 5:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اسی حدیث کے تحت فرماتے ہیں کہ:\n ’’ چوں حکم نسیان ایں ست در عمد بطریق اولی خواہد بود ‘‘۔ ([1]) ( اشعۃ اللمعات ، جلد سوم ص ۵۲۲)\nیعنی جب بھول کر پینے میں قے کرنے کا حکم ہے تو قصداً پینے میں بدرجۂ اولیٰ یہ حکم ہوگا۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الأطعمۃ ، باب الأشربۃ ، الفصل الأول ، ج ۳، ص ۵۵۷."}, {"id": 7843, "bookId": 14, "volNo": "1", "hadithNo": 75, "chapter": "لباس کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ سَمُرَۃَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ الْبَسُوا الثِّیَابَ الْبِیضَ فَإِنَّہَا أَطْہَرُ وَأَطْیَبُ‘‘۔ \nحدیث 2:\n’’ عن عُبَادَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَلَیْکُمْ بِالْعَمَاءِمِ فَإِنَّھَا سِیْمَاءُ الْمَلَاءِکَۃِ وَارْخُوْھَا خَلْفَ ظُھُوْرِکُمْ‘‘۔\nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَال َکَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا لَبِسَ قَمِیصًا بَدَأَ بِمَیَامِنِہ‘‘۔\nحدیث 4:\n’’عَنْ أَبِی سَعِیدٍ الْخُدْرِیِّ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ إِزْرَۃُ الْمُؤْمِنِ إِلَی أَنْصَافِ سَاقَیْہِ لَا جُنَاحَ عَلَیْہِ فِیْمَا بَیْنَہُ وَبَیْنَ الْکَعْبَیْنِ۔ مَا أَسْفَلَ مِنْ ذَلِکَ فَفِی النَّارِ قَالَ ذَلِکَ ثَلاثَ مَرَّاتٍ وَلَا یَنْظُرُ اللّٰہ یَوْمَ الْقِیَامَۃِ إِلَی مَنْ جَرَّ إِزَارَہُ بَطَرًا‘‘۔\nحدیث 5:\n’’ عَنْ عَمْرِو بْنِ شُعَیْبٍ عَنْ أَبِیہِ عَنْ جَدِّہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ یُحِبُّ أَنْ یرَی أَثَر نِعْمَتِہِ عَلَی عَبْدِہِ‘‘۔ \nحدیث 6:\n’’عَنْ عَائِشَۃَ أَنَّ أَسْمَاء بِنْتَ أَبِی بَکْرٍ دَخَلَتْ عَلَی رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَعَلَیْہَا ثِیَابٌ رِقَاقٌ فَأَعْرَضَ عَنْہَا وَقَالَ یَا أَسْمَاء إِنَّ الْمَرْأَۃَ إِذَا بَلَغَتْ الْمَحِیضَ لَنْ یَصْلحَ أَنْ یُرَی مِنْہَا إِلَّا ہَذَا وَہَذَا وَأَشَارَ إِلَی وَجْہِہِ وَکَفَّیْہِ‘‘۔ \nحدیث 7:\n’’ عَنْ عَلْقَمَۃَ بْنِ أَبِی عَلْقَمَۃَ عَنْ أُمِّہِ قَالَتْ دَخَلَتْ حَفْصَۃُ بِنْت عَبْدِ الرَّحْمَنِ عَلَی عَائِشَۃَ وَعَلَیْھَا خِمَارٌ رَقِیقٌ فَشَقَّتْہُ عَاءِشَۃُ وَکَسَتْہَا خِمَارًا کَثِیفًا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت سمرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ سفید کپڑے پہنا کرو اس لیے کہ وہ بہت پاکیزہ اور پسندیدہ ہے ۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت عبادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ عمامہ ضرور باندھا کرو کہ یہ فرشتوں کا نشان ہے ۔ اور اس (کے شملہ) کو پیٹھ کے پیچھے لٹکالو۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام جب کرتا پہنتے تو دا ہنی جانب سے شروع فرماتے ۔ (ترمذی)\n¥ترجمہ حدیث 4:\nحضرت ابو سعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور علیہ الصلوۃو السلام کو فرماتے ہوئے سنا کہ مومن کا تہبند آدھی پنڈلیوں تک ہے اور آدھی پنڈلی اور ٹخنوں کے درمیان ہو جب بھی کوئی حرج نہیں ۔ جو(کپڑا)ٹخنے سے نیچے ہو وہ آگ میں ہے ۔ حضور نے اس جملہ کو تین بار فرمایا اور اللّٰہ تعالی قیامت کے دن اس کی طرف نظر نہیں فرمائے گاجو تہبند (یا پاجامہ) کو تکبر سے گھسیٹتا چلے ۔ (ابوداود)\n¥ترجمہ حدیث 5:\nحضرت عمرو بن شعیب اپنے باپ سے روایت کرتے ہیں کہ ان کے دادا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اللّٰہ تعالی کو یہ بات پسند ہے کہ اس کی نعمت کا اثر بندہ ( کے لباس اور وضع سے )ظاہر ہو۔ (ترمذی)\n¥ترجمہ حدیث 6:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا سے روایت ہے کہ اسماء بنت ابوبکر( رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ما )باریک کپڑے پہن کر حضور کے سامنے آئیں ۔ حضور نے ان کی جانب سے منہ پھیر لیا اور فرمایا اے اسماء! عورت جب بالغ ہوجائے تو اس کے بدن کا کوئی حصہ ہر گز نہ دکھائی دینا چاہیے سوائے اس کے اور اس کے ۔ اور اشارہ فرمایا اپنے منہ اور ہتھیلیوں کی جانب۔ (ابوداود، مشکوۃ)\n¥ترجمہ حدیث 7:\nحضرت علقمہ بن ابوعلقمہ اپنی ماں سے روایت کرتے ہیں کہ حفصہ بنت عبدالرحمن حضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا کے پاس باریک دوپٹہ اوڑھ کر آئیں تو حضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے ان کا دوپٹہ پھاڑ دیا اور موٹا دوپٹہ اڑھا دیا۔ (مالک ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Samurah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke safed Libaas pehna karo is liye ke woh bahut Paak aur pasandida hai. (Ahmad, Mishkat). Tarjuma Hadees 2: Hazrat Ubadah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke amama zaroor bandha karo ke yeh farishton ka nishan hai. Aur is (ke shamla) ko peeth ke peeche latka lo. (Baihaqi, Mishkat). Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam jab kurta pehente to dahni janib se shuru farmate. (Tirmidhi). Tarjuma Hadees 4: Hazrat Abu Saeed Khudri Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke momin ka tehband aadhi pandliyon tak hai aur aadhi pandli aur takhnon ke darmiyan ho jab bhi koi harj nahi. Jo (kapda) takhne se neeche ho woh aag mein hai. Rasoolullah ne is jumla ko teen baar farmaya aur Allah Ta'ala Qayamat ke din us ki taraf nazar nahi farmaye ga jo tehband (ya pajama) ko takabbur se ghaseetta chale. (Abu Dawood). Tarjuma Hadees 5: Hazrat Amr Bin Shuaib apne baap se Riwayat karte hain ke unke dada ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala ko yeh baat pasand hai ke us ki nemat ka Asar banda (ke Libaas aur waza se) zahir ho. (Tirmidhi). Tarjuma Hadees 6: Aisha Siddiqah Radiyallahu Anha se Riwayat hai ke Asma Bint Abu Bakr Radiyallahu Anha bareek kapde pehen kar Rasoolullah ke samne aayin. Rasoolullah ne un ki janib se munh pher liya aur farmaya ae Asma! Aurat jab Baaligh ho jaye to uske badan ka koi hissa har giz na dikhayi dena chahiye siwaye iske aur iske. Aur ishara farmaya apne munh aur hatheliyon ki janib. (Abu Dawood, Mishkat). Tarjuma Hadees 7: Hazrat Alqamah Bin Abu Alqamah apni maa se Riwayat karte hain ke Hafsah Bint Abdurrahman Aisha Siddiqah Radiyallahu Anha ke paas bareek dupatta odh kar aayin to Aisha Siddiqah Radiyallahu Anha ne unka dupatta phaad diya aur mota dupatta odha diya. (Malik, Mishkat).", "explanation": "¥شرح حدیث 5:\n حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ ازیں جا معلوم می شود کہ پوشیدن نعمت وکتمانِ آں روا نیست وگویا موجب کفرانِ نعمت ست ‘‘۔ ([1])\n یعنی یہاں سے معلوم ہوا کہ نعمت کو پوشیدہ کرنا اور چھپانا جائز نہیں اور گویا نعمت کی ناشکری کا سبب ہے ۔ (اشعۃ اللمعات، جلد سوم ص ۵۴۸)\n------------------\n[1] ’’ اشعۃاللمعات ‘‘، کتاب اللباس ، الفصل الثانی ، ج ۳، ص ۵۸۶.\n¥انتباہ :\n آج کل عورتیں بہت باریک اور چست کپڑا پہننے لگی ہیں جس سے بدن کے اکثر اعضاء ظاہر ہوتے ہیں عورتوں کو ایسا کپڑا پہننا حرام ہے ۔ آج کل مرد بھی اسٹبل وغیرہ کا ہلکا تہبند پہننے لگے ہیں جس سے بدن کی رنگت جھلکتی ہیں اور ستر نہیں ہوتا مردوں کو بھی ایسا تہبند حرام ہے ۔ بعض لوگ اسی کو پہن کر نماز بھی پڑھتے ہیں ان کی نماز نہیں ہوتی۔ اس لیے کہ ستر عورت نماز میں فرض ہے اور بعض لوگ دھوتی باندھتے ہیں۔ دھوتی باندھنا ہندؤوں کا طریقہ ہے اور اس سے ستر بھی نہیں ہوتا کہ چلنے میں ران کا پچھلا حصہ کھل جاتا ہے مسلمانوں کوا س سے بچنا ضروری ہے اور نیکر جانگھیا پہننا کہ جس سے گھٹنا کھلا رہتا ہے حرام ہے۔"}, {"id": 7844, "bookId": 14, "volNo": "1", "hadithNo": 76, "chapter": "جوتا پہننا کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ جَابِرٍ قَالَ کُنَّا مَعَ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی سَفَرٍ فَقَالَ أَکْثِرُوا مِنَ النِّعَالِ فَإِنَّ الرَّجُلَ لَا یَزَالُ رَاکِبًا مَا انْتَعَلَ‘‘۔\nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا انْتَعَلَ أَحَدُکُمْ فَلْیَبْدَأْ بِالْیُمْنَی وَإِذَا نَزَعَ فَلْیَبْدَأْ بِالشِّمَال‘‘۔\nحدیث 3:\n’’ عَنْ فُضَالَۃَ بْنِ عُبَیْدٍ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَأْمُرُنَا أَنْ نَحْتَفِیَ أَحْیَانًا‘‘۔\nحدیث 4:\n’’عَنْ أَبِی مُلَیْکَۃَ قَالَ قِیلَ لِعَائِشَۃَ إِنَّ امْرَأَۃًتَلْبَسُ النَّعْلَ قَالَتْ لَعَنَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الرَّجُلَۃَ مِنَ النِّسَاء‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم حضور علیہ الصلاۃ والسلام کے ساتھ ایک سفر میں تھے تو حضور نے فرمایا کہ جوتے بکثرت استعمال کرو اس لیے کہ آدمی جب تک جوتا پہنے رہتا ہے وہ سوار(کی طرح) ہے ۔ (ابوداود) \n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب جوتا پہنے تو پہلے داہنے پاؤں میں پہنے اور جب اتارے تو پہلے بائیں پاؤں کا اتارے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت فضالہ بن عبید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام ہم کو حکم فرماتے تھے کہ کبھی کبھی ہم ننگے پاؤں رہیں۔ (ابو داود)\n¥ترجمہ حدیث 4:\nحضرت ابو ملیکہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ کسی نے حضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا سے کہا کہ ایک عورت (مردانہ ) جوتا پہنتی ہے ۔ انہوں نے فرمایا کہ حضور نے مر دانی عورتوں پر لعنت فرمائی ہے ۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Jabir Radiyallahu Anhu ne farmaya ke hum Rasoolullah Sallallahu Alayhi wa Sallam ke sath ek safar mein thay to Rasoolullah ne farmaya ke joote bakasrat istemaal karo is liye ke aadmi jab tak joota pehne rehta hai woh sawar (ki tarah) hai. (Abu Dawood). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab joota pehne to pehle dahne paon mein pehne aur jab utare to pehle bayen paon ka utare. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Fazalah Bin Ubaid Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam hum ko Hukm farmate thay ke kabhi kabhi hum nange paon rahen. (Abu Dawood). Tarjuma Hadees 4: Hazrat Abu Mulaikah Radiyallahu Anhu ne farmaya ke kisi ne Aisha Siddiqah Radiyallahu Anha se kaha ke ek Aurat (mardana) joota pehenti hai. Unhon ne farmaya ke Rasoolullah ne mardani aurton par la'nat farmayi hai. (Abu Dawood).", "explanation": "*****"}, {"id": 7845, "bookId": 14, "volNo": "1", "hadithNo": 77, "chapter": "انگوٹھی بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ عَنْ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَّہُ نَہَی عَنْ خَاتَمِ الذَّہَبِ‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَبَّاسٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ رَأَی خَاتَمًا مِنْ ذَہَبٍ فِی یَدِ رَجُلٍ فَنَزَعَہُ فَطَرَحَہُ فَقَالَ یَعْمِدُ أَحَدُکُمْ إِلَی جَمْرَۃٍ مِنْ نَارٍ فَیَجْعَلُہَا فِی یَدِہِ فَقِیلَ لِلرَّجُلِ بَعْدَ مَا ذَہَبَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ خُذْ خَاتَمَکَ انْتَفِعْ بِہِ قَالَ لَا وَاللّٰہ لَا آخُذُہُ أَبَدًا وَقَدْ طَرَحَہُ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ‘‘\nحدیث 3:\n’’عَنْ بُرَیْدَۃَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لِرَجُلٍ عَلَیْہِ خَاتَمٌ مِنْ شَبَہٍ مَا لِی أَجِدُ مِنْکَ رِیحَ الْأَصْنَامِ فَطَرَحَہُ ثُمَّ جَاءَ وَعَلَیْہِ خَاتَمٌ مِنْ حَدِیدٍ فَقَالَ مَا لِی أَرَی عَلَیْکَ حِلْیَۃَ أَہْلِ النَّارِ فَطَرَحَہُ فَقَالَ یَا رَسُولَ اللّٰہ مِنْ أَیِّ شَیْئٍ أَتَّخِذُہُ؟ قَالَ مِنْ وَرِقٍ وَلَا تُتِمَّہُ مِثْقَالاً ‘ ‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے (مردوں کو) سونے کی انگوٹھی سے منع فرمایا۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ماسے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے ایک شخص کے ہاتھ میں سونے کی انگوٹھی دیکھی تو اسے اتار کر پھینک دیا ور فرمایا کہ تم میں سے کوئی شخص جہنم کے انگارے کا ارادہ کرتا ہے یہاں تک کہ اس کو اپنے ہاتھ میں لے لیتا ہے ۔ جب حضور تشریف لے گئے تو کسی نے اس شخص سے کہا کہ اپنی انگوٹھی اٹھا لو کسی اور کام میں لانا۔ انہوں نے کہا خدا کی قسم میں اسے کبھی نہ لوں گا جب کہ رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے پھینک دی ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 3:\nحضرت بریدہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے ایک شخص سے فرمایا جو پیتل کی انگوٹھی پہنے ہوئے تھا کہ کیا بات ہے کہ تجھ سے بتوں کی بُو آتی ہے ۔ انہوں نے وہ انگوٹھی پھینک دی پھر لوہے کی انگوٹھی پہن کر آئے ۔ حضور نے فرمایا کیابات ہے کہ میں دیکھتا ہوں تم جہنمیوں کا زیور پہنے ہوئے ہو؟ اس شخص نے وہ انگوٹھی بھی پھینک دی۔ پھر عرض کیا یارسول اللّٰہ ! کس چیز کی انگوٹھی بنواؤں ؟ فرمایا چاندی کی بناؤ اور ایک مثقال پورا نہ کرویعنی وزن میں پورا ساڑھے چار ماشہ نہ ہو بلکہ کچھ کم ہو۔ (ترمذی)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne (mardon ko) sone ki angoothi se mana farmaya. (Muslim Shareef). Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne ek shakhs ke hath mein sone ki angoothi dekhi to use utar kar phenk diya aur farmaya ke tum mein se koi shakhs jahannam ke angare ka irada karta hai yahan tak ke usko apne hath mein le leta hai. Jab Rasoolullah tashreef le gaye to kisi ne us shakhs se kaha ke apni angoothi utha lo kisi aur kaam mein lana. Unhon ne kaha Khuda ki qasam main ise kabhi na loonga jab ke Rasoolullah Sallallahu Alayhi wa Sallam ne phenk di hai. (Muslim Shareef). Tarjuma Hadees 3: Hazrat Buraidah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne ek shakhs se farmaya jo peetal ki angoothi pehne hue tha ke kya baat hai ke tujh se buton ki boo aati hai. Unhon ne woh angoothi phenk di phir lohe ki angoothi pehen kar aaye. Rasoolullah ne farmaya kya baat hai ke main dekhta hoon tum jahannumiyon ka zevar pehne hue ho? Us shakhs ne woh angoothi bhi phenk di. Phir arz kiya Ya Rasoolullah! Kis cheez ki angoothi banwaoon? Farmaya chandi ki banao aur ek misqal poora na karo yani wazan mein poora sadhe char masha na ho balkay kuch kam ho. (Tirmidhi).", "explanation": "¥شرح حدیث 1:\nنووی شرح مسلم جلد ثانی ص:۱۹۵ میں ہے :\n ’’ أَجْمَعَ الْمُسْلِمُوْنَ عَلَی إِبَاحَۃِ خَاتَمِ الذَّھَبِ لِلنَّسَاءِ وَأَجْمَعُوْا عَلَی تَحْرِیْمِہِ عَلَی الرِّجَالِ ‘‘۔ ([1])\nیعنی مسلمانوں کا اس بات پر اتفاق ہے کہ عورتوں کے لیے سونے کی انگوٹھی جائز ہے اور مردوں کے لیے حرام ہے ۔\n اور اشعۃ اللمعات ، جلد سوم، ص: ۵۵۹ میں ہے :\n ’’ کہ حرمت خاتم ذہب در حق رجال ست اما نساء را حرام نیست ‘‘۔ ([2])\nیعنی سونے کی انگوٹھی کی حرمت مردوں کے لیے ہے لیکن عورتوں کے لیے حرام نہیں ہے ۔\n------------------\n[1] ’’ شرح صحیح مسلم ‘‘ للنووی ، کتاب اللباس والزینۃ ، باب تحریم خاتم الذھب إلخ ، ج ۷، ص ۶۵.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب اللباس ، باب الخاتم ، الفصل الأول ، ج ۳، ص ۵۹۸.\n¥انتباہ:\n مردوں کو ایک سے زیادہ انگوٹھی پہننا یا چھلے پہننا یا ایک سے زائد نگینے والی انگوٹھی پہننااگرچہ چاندی کی ہو ناجائز ہے ۔ ([1]) (بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۷۱."}, {"id": 7846, "bookId": 14, "volNo": "1", "hadithNo": 78, "chapter": "حجامت کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْفِطْرَۃُ خَمْسٌ الْخِتَانُ وَالاسْتِحْدَادُ وَقَصُّ الشَّارِبِ وَتَقْلِیمُ الْأَظْفَارِ وَنَتْفُ الْإِبِطِ‘‘۔ \nحدیث 2:\n’’عَنْ أَنَسٍ قَالَ وُقِّتَ لَنَا فِی قَصِّ الشَّارِبِ وَتَقْلِیمِ الْأَظْفَارِ وَنَتْفِ الْإِبِطِ وَحَلْقِ الْعَانَۃِ أَنْ لَا نَتْرُکَ أَکْثَرَ مِنْ أَرْبَعِینَ لَیْلَۃً‘‘۔\nحدیث 3:\n’’عَنْ عَلِیٍّ رَضِیَ اللّٰہ عَنْہُ قَالَ نَہَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ تَحْلقَ الْمَرْأَۃُ رَأْسَہَا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ پانچ چیزیں فطرت سے ہیں۔ (یعنی انبیائے سابقین علیہم السلام کی سنت ہیں) ختنہ کرنا، موئے زیر ناف مونڈنا ، مونچھیں کتروانا ، ناخن ترشوانا، اور بغل کے بال اکھیڑنا ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ مونچھیں کاٹنے ، بال تراشنے ، بغل کے بال اکھیڑنے ، اور موئے زیر ناف مونڈنے میں ہمارے لیے یہ وقت مقرر کیا گیا ہے کہ ہم چالیس دن سے زیادہ نہ چھوڑیں یعنی چالیس دن کے اندر ہی اندر ان کاموں کو ضرور کرلیں۔ (مسلم شریف)\n¥ترجمہ حدیث 3:\nحضرت علی کرم اللّٰہتعالی وجہہ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے عورت کو سرمنڈانے سے منع فرمایا۔ (نسائی، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke paanch cheezein fitrat se hain. (Yani ambiya-e-sabiqeen alayhimussalam ki Sunnat hain) Khatna karna, mooye Zair-e-Naaf Moondna, Moonchein katrana, Naakhun tarashwana, aur Baghal ke Baal ukherna. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Anas Radiyallahu Anhu ne farmaya ke Moonchein katne, Baal tarashne, Baghal ke Baal ukherne, aur mooye Zair-e-Naaf Moondne mein hamare liye yeh waqt muqarrar kiya gaya hai ke hum chalees din se zyada na chhoden yani chalees din ke andar hi andar in kamon ko zaroor kar len. (Muslim Shareef). Tarjuma Hadees 3: Hazrat Ali Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne Aurat ko sar moondne se mana farmaya. (Nasa'i, Mishkat).", "explanation": "¥شرح حدیث 2:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ باید از چہل روز نہ گزردو اگر کمتر ازاں کنند افضل ست ، وگفتہ اند کہ آنحضرت قص شارب وتقلیم اظفار در جمعہ می کرد ، و حلق عانہ در بست روز ونتف الابط در چہل روز ‘‘۔ ([1])( اشعۃ اللمعات ، جلد سوم ص ۵۶۹)\nیعنی چالیس روز سے زیادہ نہیں گزرنا چاہیے اور اگر اس سے کم میں کرے تو افضل ہے ۔ اوربیان کیا گیا ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم مونچھ اور ناخن ہر جمعہ کو کاٹتے تھے اور ہر بیس روز پر موئے زیر ناف مونڈتے تھے ۔ اور ہر چالیس روز بعد بغل کے بال اکھاڑتے تھے ۔\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب اللباس ، باب الترجل ، الفصل الأول ، ج ۳، ص ۶۰۹.\n¥انتباہ :\n (۱)…ناخن تراشنے میں حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ سے یہ ترتیب مروی ہے کہ داہنے ہاتھ کی کلمہ کی انگلی سے شروع کرے اور چھوٹی انگلی پر ختم کرے پھر بائیں ہاتھ کی چھوٹی انگلی سے شروع کرکے انگوٹھے پر ختم کرے پھر داہنے ہاتھ کے انگوٹھے کا ناخن تراشے ۔ ([1]) ( بہار شریعت )\n (۲)…آج کل عورتیں سر کے بال کٹا کر لونڈوں کی شکل اختیار کرنے لگی ہیں یہ سخت ناجائز و گناہ ہے ۔ حضور سرکارِ دوعالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے ایسی عورتوں پر لعنت فرمائی ہے ۔ العیاذ باللّٰہ تعالی ۔\n (۳)…سنت یہ ہے کہ مرد پورے سر کے بال منڈائے یا بڑھائے اور مانگ نکالے ۔ فتاوی عالمگیری مصری جلد ۵ ص:۳۱۲ میں ہے : ’’ فِی رَوْضِۃِ الزندویستی أَنَّ السُّنَّۃَ فِی شَعْرِ الرَّأْسِ إمَّا الْفَرْقُ وَإِمَّا الْحَلْقُ وَذَکَرَ الطَّحْطَاوِیُّ الْحَلْقُ سُنَّۃٌ وَنُسِبَ ذَلِکَ إلَی الْعُلَمَاء الثَّلَاثَۃِ کَذَا فِی التَّتَارْخَانِیَّۃ ‘‘۔ ([2])\n اور سید الفقہاء ملا جیون رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے لکھا ہے کہ حَلْقُ الرَّأَسِ وَقَصْرُہُ مَسْنُوْنٌ لِلرِّجَالِ عَلَی سَبِیْلِ التَّخْییْرِ ‘‘۔ ([3]) (تفسیرات احمدیہ ص ۳۱)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۲۲۶، ’’ الدر المختار ‘‘، کتاب الحظر والإباحۃ ، ج ۹، ص ۶۷۰.\n[2] ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، الباب التاسع عشر فی الختان إلخ ، ج ۵، ص ۳۵۷.\n[3] ’’ التفسیرات الأحمدیۃ ‘‘، ص ۳۱."}, {"id": 7847, "bookId": 14, "volNo": "1", "hadithNo": 79, "chapter": "ڈاڑھی ، مونچھ کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ خَالِفُوا الْمُشْرِکِینَ أَوْفِرُوا اللِّحَی وَأَحْفُوا الشَّوَارِبَ وَفِیْ رِوَایَۃِ اَنْھِکُو الشَّوارِبَ واعفُوا اللِّحَی‘‘۔ \nحدیث 2:\n’’عَنْ زَیْدِ بْنِ أَرْقَمَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ لَمْ یَأْخُذْ مِنْ شَارِبِہِ فَلَیْسَ مِنَّا‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ جُزُّوا الشَّوَارِبَ وَأَرْخُوا اللِّحَی خَالِفُوا الْمَجُوسَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ مشرکین کی مخالفت کرو (اس طرح کہ) داڑھیوں کو بڑھاؤ اور مونچھوں کو کتراؤ اور ایک روایت میں ہے مونچھوں کو خوب کم کرو اور داڑھیوں کو بڑھاؤ ۔ (بخاری ، مسلم)\n¥ترجمہ حدیث 2:\nحضرت زید بن ارقم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا جو اپنی مونچھ نہ کاٹے وہ ہم میں سے نہیں ہے ۔ ( یعنی ہمارے طریقے کے خلاف ہے )۔ (ترمذی، نسائی)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ مونچھیں کٹاؤ اور داڑھیاں بڑھاؤ ( اس طرح) مجوسیوں کی مخالفت کرو۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke mushrikeen ki mukhalifat karo (is tarah ke) Daadhiyon ko barhao aur Moonchein ko katrao aur ek Riwayat mein hai Moonchein ko khoob kam karo aur Daadhiyon ko barhao. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Zaid Bin Arqam Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya jo apni Moonch na kaate woh hum mein se nahi hai. (Yani hamare tareeqe ke khilaf hai). (Tirmidhi, Nasa'i). Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Moonchein katao aur Daadhiyan barhao (is tarah) majoosiyon ki mukhalifat karo. (Muslim Shareef).", "explanation": "¥ضروری انتباہ:\n (۱) …آج کل مسلمانوں نے داڑھی میں طرح طرح کا فیشن نکال رکھا ہے ۔ اکثر لوگ بالکل صفایا کرادیتے ہیں۔ کچھ لوگ صرف ٹھوڑی پر ذرا سی رکھتے ہیں۔ بعض لوگ ایک دو انگل داڑھی رکھتے ہیں اور اپنے کو متبع شریعت سمجھتے ہیں، حالانکہ داڑھی کا بالکل صفایا کرانے والے اور داڑھی کو ایک مشت سے کم رکھنے والے دونوں شریعت کی نظر میں یکساں ہیں۔ بہارِ شریعت جلد شانزدہم ص:۱۹۷ میں ہے ۔ داڑھی بڑھانا سنن انبیائے سابقین سے ہے ۔ مونڈانا یا ایک مشت سے کم کرانا حرام ہے ۔ ([1])\n اور حضرت شیخ عبدالحق محدث دہلوی رحمۃ اللّٰہ تعالی علیہ اشعۃ اللمعات جلد اول، ص: ۲۱۲ میں فرماتے ہیں کہ :\n’’ حلق کردن لحیہ حرام ست وروش افرنج وہنود وجو القیان ست کہ ایشان را قلندریہ گویند وگذاشتن آن بقدر قبضہ واجب ست وآنکہ آں را سنت گویند بمعنی طریقہ مسلوک در دین ست ، یا بجہت آنکہ ثبوت آں بسنت ست چنانکہ نماز عید راسنت گفتہ اند ‘‘۔ ([2])\nیعنی داڑھی منڈانا حرام ہے اور انگریزوں ، ہندؤوں اور قلندریوں کا طریقہ ہے ۔ اور داڑھی کو ایک مشت تک چھوڑ دینا واجب ہے اور جن فقہاء نے ایک مشت داڑھی رکھنے کو سنت قرار دیا تو وہ اس وجہ سے نہیں کہ ان کے نزدیک واجب نہیں بلکہ اس وجہ سے کہ یا تو یہاں سنت سے مراد دین کا چالو راستہ ہے یا اس وجہ سے کہ ایک مشت کا وجوب حدیث شریف سے ثابت ہے جیسا کہ نمازعید کو مسنون فرمایا ( حالانکہ نماز عید واجب ہے )۔\n اور درمختار مع ردالمحتار جلد دوم ص۱۱۶، رد المحتار جلد دوم ص۱۱۷، بحرالرائق جلد دوم ص:۲۸۰، فتح القدیر جلد دوم ص:۲۷۰ اور طحطاوی ص:۴۱۱ میں ہے :\n ’’ وَاللَّفْظُ لِلطَّحْطَاوِی اَلأَخْذُ مِنَ اللِّحْیَۃِ وَہُوَ دُوْنَ ذَلِکَ ( أَی الْقَدْرُ الْمَسْنُوْنُ وَھُوَ الْقَبْضَۃُ ) کَمَا یَفْعَلُہُ بَعْضُ الْمَغَارِبَۃِ ، وَمُخَنَّثَۃُ الرِّجَالِ لَمْ یُبِحْہُ أَحَدٌ ، وَأَخْذُ کُلِّہَا فِعْلُ یَہُودِ الْہِنْدِ وَمَجُوسِ الْأَعَاجِمِ ‘‘۔ ([3])\n یعنی داڑھی جب کہ ایک مشت سے کم ہو تو اس کو کاٹنا جس طرح کہ بعض مغربی اور زنانے زنخے کرتے ہیں کسی کے نزدیک حلال نہیں ا ور کل داڑھی کا صفایا کرنا یہ کام تو ہندوستان کے یہودیوں اور ایران کے مجوسیوں کا ہے ۔\n (۲) …حد شرع یعنی ایک مشت سے کچھ زائد داڑھی رکھنا جائز ہے لیکن ہمارے آئمہ و جمہور علماء کے نزدیک اس کا طول فاحش کہ جو حدِ تناسب سے خارج اور باعث انگشت نمائی ہو مکروہ وناپسندیدہ ہے ۔ ([4]) ( لمعۃ الضحی )\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۲۲۸، ’’ الدر المختار ‘‘، کتاب الحظر والإباحۃ ، ج ۹، ص ۶۷۱.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب الطہارۃ ، باب السواک ، الفصل الأول ، ج ۱، ص ۲۲۸.\n[3] ’’ الدر المختار ورد المحتار ‘‘، کتاب الصوم ، مطلب فی الأخذ من اللحیۃ ، ج ۳، ص ۴۵۶، ’’ البحر الرائق ‘‘، کتاب الصوم ، باب ما یفسد الصوم وما لایفسدہ ، ج ۲، ص ۴۹۰، ’’ فتح القدیر ‘‘، کتاب الصوم ، باب ما یوجب القضاء والکفارۃ ، ج ۲، ص ۳۵۲، ’’ حاشیۃ الطحطاوی علی مراقی الفلاح ‘‘، کتاب الصوم ، باب مایفسد الصوم ویو جب القضاء ، ص ۶۸۱.\n[4] ’’ الفتاوی الرضویۃ ‘‘، ج ۲۲، ص ۶۵۵."}, {"id": 7848, "bookId": 14, "volNo": "1", "hadithNo": 80, "chapter": "خضاب کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ غَیِّرُوا الشَّیْبَ وَلَا تَشَبَّہُوا بِالْیَہُودِ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی ذَرٍّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ أَحْسَنَ مَا غُیِّرَ بِہِ الشَّیْبُ الْحِنَّاءوَالْکَتَمُ‘‘۔\nحدیث 3:\n’’عَنْ ابْنِ عَبَّاسٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ یَکُونُ قَوْمٌ فِیْ آخِرِ الزَّمَان یَخْضِبُونَ ِ بِھَذَا السَّوَادِ وکَحَوَاصِلِ الْحَمَامِ لَا یَجِدُوْنَ رَاءِحَۃَ الْجَنَّۃِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ بڑھاپے کو بدل ڈالو یعنی خضاب لگاؤ اور یہودیوں کے ساتھ مشابہت نہ کرو۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ابو ذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ سب سے اچھی چیز جس سے سفید بالوں کا رنگ بدلا جائے مہندی اور کتم ہے یعنی مہندی لگائی جائے یا کتم ۔ (ابوداود)\n¥ترجمہ حدیث 3:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے کہ نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ آخر زمانہ میں کچھ لوگ ہوں گے جو کالا خضاب استعمال کریں گے جیسے کبوتر کے پوٹے ۔ وہ لوگ جنت کی خوشبو نہیں پائیں گے ۔ (ابوداود، نسائی، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke barhapay ko badal dalo yani Khizaab lagao aur yahudiyon ke sath mushabihat na karo. (Tirmidhi). Tarjuma Hadees 2: Hazrat Abu Zarr Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke sab se achi cheez jis se safed baalon ka rang badla jaye Mehndi aur katam hai yani Mehndi lagayi jaye ya katam. (Abu Dawood). Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhu se Riwayat hai ke Nabi Kareem Sallallahu Alayhi wa Sallam ne farmaya ke aakhir zamana mein kuch log honge jo kala Khizaab istemaal karenge jaise kabootar ke pote. Woh log jannat ki Khushboo nahi payenge. (Abu Dawood, Nasa'i, Mishkat).", "explanation": "*****"}, {"id": 7849, "bookId": 14, "volNo": "1", "hadithNo": 81, "chapter": "سونا، لیٹنا کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ جَابِرٍ قال نَھَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ یَرْفَعَ الرَّجُلُ إِحْدَی رِجْلَیْہِ عَلَی الْأُخْرَی وَہُوَ مُسْتَلْقٍ عَلَی ظَہْرِہِ‘‘۔\nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ رَأَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ رَجُلًا مُضْطَجِعًا عَلَی بَطْنِہِ فَقَالَ إِنَّ ہَذِہِ ضَجْعَۃٌ لَا یُحِبُّہَا اللّٰہ‘‘۔\nحدیث 3:\n’’عَنْ جَابِرٍ قَالَ نَہَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ یَنَامَ الرَّجُلُ عَلَی سَطْحٍ لَیْسَ بِمَحْجُورٍ عَلَیْہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے پاؤں پر پاؤں رکھنے سے منع فرمایا ہے جب کہ چت لیٹا ہو۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے ایک شخص کو پیٹ کے بل لیٹے ہوئے دیکھا فرمایا اس طرح لیٹنے کو اللّٰہ تعالی پسند نہیں فرماتا ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت جابر ر ضی اللّٰہ تعالیٰ عنہ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے ایسی چھت پر سونے سے منع فرمایا کہ جس پر گرنے سے کوئی روک نہ ہو۔ (ترمذی)", "roman": "Tarjuma Hadees 1: Hazrat Jabir Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne paon par paon rakhne se mana farmaya hai jab ke chit leta ho. (Muslim Shareef). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne ek Shakhs ko pet ke bal lete hue dekha farmaya is tarah letne ko Allah Ta'ala pasand nahi farmata. (Tirmidhi). Tarjuma Hadees 3: Hazrat Jabir Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne aisi chhat par sone se mana farmaya ke jis par girne se koi rok na ho. (Tirmidhi).", "explanation": "¥شرح حدیث 1:\nیہ ممانعت اس وقت ہے جب کہ ایک پاؤں کھڑا ہو کہ اس طرح بے ستری کا اندیشہ ہے اور اگر پاؤں کو پھیلا کر ایک کو دوسرے پر رکھے تو کوئی حرج نہیں ۔ ([1]) (بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۷۷.\n¥انتباہ :\n (۱)…مستحب یہ ہے کہ باطہارت سوئے اور کچھ دیر د ہنی کروٹ پر داہنے ہاتھ کو رخسار کے نیچے رکھ کر قبلہ رو سوئے پھر اس کے بعد بائیں کروٹ پر ۔\n (۲)…جب لڑکی اور لڑکے کی عمر دس سال ہو تو انہیں الگ الگ سلانا چاہیے ۔\n (۳)…میاں بیوی جب ایک چار پائی پر سوئیں تو دس برس کے بچہ کو اپنے ساتھ نہ سلائیں۔\n (۴)…دن کے ابتدائی حصہ میں سونا یا مغرب و عشاء کے درمیان سونا مکروہ ہے ۔ ([1]) (بہار شریعت)\n (۵)…ہندو پاکستان میں شمال یعنی اتر جانب پاؤں پھیلا کر سونا بلاشبہ جائز ہے اسے ناجائز سمجھنا غلطی ہے ۔\n (۶)…جب سو کر اُٹھے تو یہ دعا پڑھے : ’’ اَلْحَمْدُ ِللَّہِ الَّذِیْ أَحْیَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَیْہِ النُّشُوْر ‘‘۔ ([2]) (بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص۷۹.\n[2] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۷۹."}, {"id": 7850, "bookId": 14, "volNo": "1", "hadithNo": 82, "chapter": "خواب کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَنَسِ قََالَ قََالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الرُّؤْیَا الصَّالِحَۃُ جُزْئٌ مِنْ سِتَّۃٍ وَأَرْبَعِینَ جُزْءً مِنْ النُّبُوَّۃِ‘‘۔ \nحدیث 2:\n’’عَنْ أَبِیْ قَتَادَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الرُّؤْیَا الصَّالِحَۃُ مِنَ اللّٰہ وَالْحُلْمُ مِنَ الشَّیْطَانِ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِیْ ھُرَیْرَۃَ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ رَآنِی فِی الْمَنَامِ فَقَدْ رَآنِی فَإِنَّ الشَّیْطَانَ لَا یَتَمَثَّلُ فِیْ صُوْرَتِیْ‘‘۔ (بخاری، مسلم)\nحدیث 4:\n’’عَنْ جَابِرٍ قَالَ َجَاء رَجُلٌ إِلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ رَأَیْتُ فِی الْمَنَامِ کَأَنَّ رَأْسِی قُطِعَ قَالَ فَضَحِکَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَقَالَ إِذَا لَعِبَ الشَّیْطَانُ بِأَحَدِکُمْ فِی مَنَامِہِ فَلَا یُحَدِّث بِہِ النَّاسَ‘‘۔ \nحدیث 5:\n’’عَنْ جَابِرقَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا رَأَی أَحَدُکُمْ الرُّؤْیَا یَکْرَہُہَا فَلْیَبْصُقْ عَنْ یَسَارِہِ ثَلاثًا وَلْیَسْتَعِذْ بِاللّٰہ مِنَ الشَّیْطَانِ ثَلاثًا وَلْیَتَحَوَّلْ عَنْ جَنْبِہِ الَّذِی کَانَ عَلَیْہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایاکہ اچھاخواب نبوت کے چھیالیس حصوں میں سے ایک حصہ ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوقتادہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اچھا خواب خدائے تعالیٰ کی طرف سے ہے اور برا خواب شیطان کی جانب سے ۔ (بخاری، مسلم) \n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جس نے خواب میں مجھ کو دیکھا اس نے ( واقعی) مجھ ہی کو دیکھا اس لیے کہ شیطان میری صورت نہیں اختیار کرسکتا ۔ \n¥ترجمہ حدیث 4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ نبی کریم علیہ الصلاۃ والتسلیم کی خدمت میں ایک شخص نے حاضر ہو کر عرض کیا(یارسول اﷲ !) میں نے خواب میں دیکھاکہ گویا میرا سر کاٹ ڈالا گیا ہے ۔ حضور علیہ الصلاۃ والسلام یہ سن کر مسکرائے اور فرمایا جب خواب میں شیطان کسی کے ساتھ کھیلے تو وہ اس خواب کو لوگوں سے بیان نہ کرے ۔ (مسلم شریف)\n¥ترجمہ حدیث 5:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ تم میں سے جو کوئی برا خواب دیکھے تو اس کو چاہیے کہ بائیں جانب تین بار تھوک دے اور تین بار شیطان سے خدائے تعالیٰ کی پناہ مانگے اور جس کروٹ پر پہلے تھا اسے بدل دے ۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke achha khwab nabuwwat ke chhayalis hisson mein se ek hissa hai. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abu Qatadah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke achha khwab Allah Ta'ala ki taraf se hai aur bura khwab shaitan ki janib se. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis ne khwab mein mujh ko dekha us ne (waqai) mujh hi ko dekha is liye ke shaitan meri surat nahi ikhtiyar kar sakta. Tarjuma Hadees 4: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ki khidmat mein ek Shakhs ne hazir ho kar arz kiya (Ya Rasoolullah!) main ne khwab mein dekha ke goya mera sar kaat dala gaya hai. Rasoolullah Sallallahu Alayhi wa Sallam yeh sun kar muskuraye aur farmaya jab khwab mein shaitan kisi ke sath khele to woh is khwab ko logon se bayan na kare. (Muslim Shareef). Tarjuma Hadees 5: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke tum mein se jo koi bura khwab dekhe to us ko chahiye ke bayin janib teen baar thook de aur teen baar shaitan se Allah Ta'ala ki panah mange aur jis karwat par pehle tha use badal de. (Muslim Shareef).", "explanation": "*****"}, {"id": 7851, "bookId": 14, "volNo": "1", "hadithNo": 83, "chapter": "فال گوئی کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ حَفْصَۃَ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَتَی عَرَّافًا فَسَأَلَہُ عَنْ شَیْئٍ لَمْ تُقْبَلْ لَہُ صَـلَاۃُ أَرْبَـعِیـنَ لَیْلَۃً‘‘۔\nحدیث 2:\n’’ عَنْ أَبِیْ ھُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَتَی کَاہِنًا فَصَدَّقَہُ بِمَا یَقُولُ فَقَدْ بَرِءَ مِمَّا أُنْزِلَ عَلَی مُحَمَّدٍ‘‘۔\nحدیث 3:\n’’ عَنْ عَائِشَۃَ قَالَتْ سَأَلَ أُنَاسٌ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنِ الکُہَّانِ فَقَالَ لَہُمْ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّہُمْ لَیْسُوا بِشَیْئٍ قَالُوا یَا رَسُولَ اللّٰہ فَإِنَّہُمْ یُحَدِّثُونَ أَحْیَانًا بِالشَّیْءِ یَکُونُ حَقًّا فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تِلْکَ الْکَلِمَۃُ مِنَ الْحَقِّ یَخْطَفُہَا الْجِنِّیُّ فَیَقُرُّہَا فِی أُذُنِ وَلِیِّہِ قَرَّ الدَّجَاجَۃِ فَیَخْلِطُونَ فِیہَا أَکْثَرَ مِنْ مِءَۃِ کَذبَۃٍ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت حفصہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جو شخص کاہن اور نجومی کے پاس جا کر کچھ دریافت کرے اس کی چالیس دن کی نمازیں قبول نہیں کی جائیں گی۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص کاہن اور جوتشی کے پاس جائے اور اس کے بیان کو سچا جانے تو وہ قرآن اور دین اسلام سے الگ ہوگیا۔ (احمد، ابوداود)\n¥ترجمہ حدیث 3:\nحضرت عائشہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کچھ لوگوں نے رسولِ کریم علیہ الصلاۃ والتسلیم سے کاہنوں کی بابت پوچھا (کہ ان کی باتیں قابلِ اعتماد ہیں یا نہیں) حضور نے فرمایا وہ بالکل ( قابلِ اعتماد ) نہیں ہیں۔ لوگوں نے عرض کیا یارسول اللّٰہ ! بعض وقت وہ ایسی خبر دیتے ہیں جو سچ ہوجاتی ہیں۔ حضور نے فرمایا وہ کلمۂ حق ہے جس کو ( فرشتوں سے ) شیطان اچک لیتا ہے ۔ اور ا پنے دوست کاہن کے کان میں اس طرح ڈال دیتا ہے جس طرح ایک مرغی دوسری مرغی کے کان میں آواز پہنچاتی ہے پھر وہ کاہن اس کلمۂ حق میں سو سے زیادہ جھوٹی باتیں ملادیتے ہیں۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Hafsah Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo Shakhs kahan aur najoomee ke paas ja kar kuch daryaft kare us ki chalis din ki Namaz Qubool nahi ki jayengi. (Muslim Shareef). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo Shakhs kahan aur jotshi ke paas jaye aur us ke bayan ko sacha jane to woh Quran aur deen-e-Islam se alag ho gaya. (Ahmad, Abu Dawood). Tarjuma Hadees 3: Hazrat Aishah Radiyallahu Anha ne farmaya kuch logon ne Rasoolullah Sallallahu Alayhi wa Sallam se kahanon ki babat pucha (ke un ki baatein qabil-e-aitimad hain ya nahi) Rasoolullah ne farmaya woh bilkul (qabil-e-aitimad) nahi hain. Logon ne arz kiya Ya Rasoolullah! baaz waqt woh aisi khabar dete hain jo sach ho jati hain. Rasoolullah ne farmaya woh kalima-e-haq hai jis ko (farishton se) shaitan achak leta hai aur apne dost kahan ke kaan mein is tarah daal deta hai jis tarah ek murghi dusri murghi ke kaan mein awaz pahunchati hai phir woh kahan us kalima-e-haq mein sau se zyada jhooti baatein mila dete hain. (Bukhari, Muslim).", "explanation": "*****"}, {"id": 7852, "bookId": 14, "volNo": "1", "hadithNo": 84, "chapter": "چھینک ، جماہی کا بیان", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ إِذَا عَطَسَ غَطَّی وَجْہَہُ بِیَدِہِ أَوْ ثَوْبِہِ وَغَضَّ بِہَا صَوْتَہُ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا عَطَسَ أَحَدُکُمْ فَلْیَقُلِ الْحَمْدُ لِلَّہِ وَلْیَقُلْ لَہُ أَخُوہُ أَوْ صَاحِبُہُ یَرْحَمُکَ اللّٰہ فَإِذَا قَالَ لَہُ یَرْحَمُکَ اللّٰہ فَلْیَقُلْ یَہْدِیکُمُ اللّٰہ وَیُصْلِحُ بَالَکُمْ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی سَعِیدٍ الْخُدْرِیِّ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِذَا تَثَاءَ بَ أَحَدُکُمْ فَلْیُمْسِکْ بِیَدِہِ عَلَی فَمِہِ فَإِنَّ الشَّیْطَانَ یَدْخُلُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام کو جب چھینک آتی تو منہ کو ہاتھ یا کپڑے سے چھپالیتے اور آواز کو پست کرتے ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایاکہ جب کسی کو چھینک آئے تو اَلْحَمْدُ لِلَّہِ کہے اور اس کا بھائی یا ساتھ والا یَرْحَمُکَ اللّٰہ کہے جب یَرْحَمُکَ اللّٰہ کہہ لے تو چھینکنے والا اس کے جواب میں یہ کہے یَہْدِیکُمُ اللّٰہ وَیُصْلِحُ بَالَکُمْ ۔ (بخاری)\n¥ترجمہ حدیث 3:\nحضرت ابوسعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب کسی کو جماہی آئے تو اپنا ہاتھ منہ پر رکھ لے کیونکہ شیطان منہ میں گھس جاتا ہے ۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ko jab chheenk aati to munh ko hath ya kapde se chhupa lete aur awaz ko past karte. (Tirmidhi). Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab kisi ko chheenk aaye to Alhamdullilah kahe aur us ka bhai ya sath wala YarhamukAllah kahe jab YarhamukAllah keh le to chheenkne wala us ke Jawab mein yeh kahe Yahdeekumullah wa Yuslihu Baalakum. (Bukhari). Tarjuma Hadees 3: Hazrat Abu Saeed Khudri Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab kisi ko jamahi aaye to apna hath munh par rakh le kyunke shaitan munh mein ghus jata hai. (Muslim Shareef).", "explanation": "¥انتباہ :\n (۱)… انبیائے کرام علیہم الصلاۃ والسلام جماہی سے محفوظ ہیں اس لیے کہ اس میں شیطانی مداخلت ہے اس کے روکنے کی بہتر ترکیب یہ ہے کہ جب جماہی آنے والی ہو تو دل میں خیال کرے کہ انبیائے کرام علیہم الصلاۃوالسلام اس سے محفوظ ہیں۔ فوراً رُک جائے گی۔ ([1]) (بہار شریعت، شامی، جلد اول ص ۳۳۶)\n (۲)…اگر چھینکنے والا اَلحَمْدُ ﷲِ کہے تو سننے والے پر فوراً اس طرح جواب دینا واجب ہے کہ وہ سُن لے ۔\n (۳)…بعض لوگ چھینک کو بدفالی خیال کرتے ہیں مثلاً کسی کام کے لیے جارہا ہے اور کسی کو چھینک آگئی تو سمجھتے ہیں وہ کام انجام نہیں پائے گا۔ یہ جہالت ہے اس لیے کہ بدفالی کوئی چیز نہیں بلکہ ایسے موقع پر چھینک آنا اور اس پر ذکر الہٰی کرنا نیک فالی ہے ۔\n------------------\n[1] ’’بہارِ شریعت ‘‘، ج۱، ص ۶۲۷، ’’ رد المحتار ‘‘، کتاب الصلاۃ ، باب صفۃ الصلاۃ ، ج ۲، ص۴۹۸."}, {"id": 7853, "bookId": 14, "volNo": "1", "hadithNo": 85, "chapter": "اجازت", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ جَابِرٍ قَالَ أَتَیْتُ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَدَقَقْتُ الْبَابَ فَقَالَ مَنْ ذَا؟ قُلْتُ أَنَا فَقَالَ أَنَا أَنَا‘‘۔ \nحدیث 2:\n’’ عَنْ عَبْدِ اللّٰہ بْنِ بُسْرٍ قَالَ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا أَتَی بَابَ قَوْمٍ لَمْ یَسْتَقْبِلِ الْبَابَ مِنْ تِلْقَاءِ وَجْہِہِ وَلَکِنْ مِنْ رُکْنِہِ الْأَیْمَنِ أَوْ الْأَیْسَر‘‘۔ \nحدیث 3:\n’’عَنْ عَطَاءِ بْنِ یَسَارٍ أَنَّ رَجُلًا سَأَلَ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ أَسْتَأْذِنُ عَلَی أُمِّی؟ فَقَالَ نَعَمْ فَقَالَ الرَّجُلُ إِنِّی مَعَہَا فِی الْبَیْتِ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اِسْتَأْذِنْ عَلَیْہَا فَقَالَ الرَّجُلُ إِنِّی خَادِمُہَا فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اِسْتَأْذِنْ عَلَیْہَا أَتُحِبُّ أَنْ تَرَاہَا عُرْیَانَۃً؟ قَالَ لَا قَالَ فَاسْتَأْذِنْ عَلَیْہَا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے نبی کریم علیہ الصلاۃ والتسلیم کے آستانۂ اقدس پر حاضر ہو کر دروازہ کھٹکھٹایا تو حضور نے فرمایا کون ہے ؟ میں نے عرض کی میں ہوں تو آپ نے فرمایا میں ( تو) میں بھی ہوں۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن بسر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم علیہ الصلاۃ والسلام جب کسی کے دروازہ پر تشریف لے جاتے تو دروازہ کے سامنے نہیں کھڑے ہوتے تھے بلکہ داہنے یا بائیں دروازہ سے ہٹ کر کھڑے ہوتے تھے ۔ (ابوداود)\n¥ترجمہ حدیث 3:\nحضرت عطاء بن یسار رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ ایک شخص نے رسولِ کریم علیہ الصلاۃ والتسلیم سے پوچھا کہ کیا میں اپنی ماں کے پاس جاؤں تو اس سے بھی اجازت لوں؟ حضور نے فرمایا ہاں انہوں نے عرض کیا میں تو اس کے ساتھ اسی مکان میں رہتا ہوں۔ حضور علیہ الصلاۃ والسلام نے فرمایا اجازت لے کر اس کے پاس جاؤ۔ انہوں نے کہا میں اپنی ماں کا خادم ہوں۔ (یعنی بار بار آنا جانا ہوتا ہے پھر اجازت کی کیا ضرورت؟) رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایاکہ اجازت لے کر جاؤ۔ کیا تم پسند کرتے ہو کہ اپنی ماں کو برہنہ دیکھو؟ عرض کیا نہیں۔ فرمایا تو اجازت حاصل کرلیا کرو۔ (مالک، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Jabir Radiyallahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ke aastana-e-aqdas par hazir ho kar darwaza khatkhataya to Rasoolullah ne farmaya kaun hai? Main ne arz ki main hoon to aap ne farmaya main (to) main bhi hoon. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abdullah Bin Busr Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam jab kisi ke darwaza par tashreef le jate to darwaza ke samne nahi khade hote the balkeh dahne ya bayin darwaza se hat kar khade hote the. (Abu Dawood). Tarjuma Hadees 3: Hazrat Ataa Bin Yasar Radiyallahu Anhu se Riwayat hai ke ek Shakhs ne Rasoolullah Sallallahu Alayhi wa Sallam se pucha ke kya main apni maa ke paas jaun to us se bhi ijazat lun? Rasoolullah ne farmaya haan unhon ne arz kiya main to us ke sath isi Makaan mein rehta hoon. Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ijazat le kar us ke paas jao. Unhon ne kaha main apni maa ka khadim hoon. (Ya'ni baar baar aana jana hota hai phir ijazat ki kya zaroorat?) Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke ijazat le kar jao. Kya tum pasand karte ho ke apni maa ko barhana dekho? Arz kiya nahi. Farmaya to ijazat hasil kar liya karo. (Malik, Mishkat).", "explanation": "*****"}, {"id": 7854, "bookId": 14, "volNo": "1", "hadithNo": 86, "chapter": "سلام", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَوَلَا أَدُلُّکُمْ عَلَی شَیْئٍ إِذَا فَعَلْتُمُوہُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَیْنَکُمْ‘‘۔ \nحدیث 2:\n’’ عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اَلسَّلَامُ قَبْلَ الْکَلَامِ‘‘۔\nحدیث 3:\n’’ عَنْ عَبْدِاللّٰہ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ اَلْبَادِیُ بِالسَّلَامِ بَرِیٌّ مِنَ الْکِبْرِ‘‘۔ \nحدیث 4:\n’’ عَنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِذَا انْتَہَی أَحَدُکُمْ إِلَی مَجْلِسٍ فَلْیُسَلِّمْ فَإِنْ بَدَأَ لَہُ أَنْ یَجْلِسَ فَلْیَجْلِسْ ثُمَّ إِذَا قَامَ فَلْیُسَلِّمْ ‘‘۔ \nحدیث 5:\n’’ عَنْ أَنَسٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ یَا بُنَیَّ إِذَا دَخَلْتَ عَلَی أَہْلِکَ فَسَلِّمْ یَکُوْنُ بَرَکَۃً عَلَیْکَ وَعَلَی أَہْلِ بَیْتِکَ‘‘َ۔\nحدیث 6:\n’’عَنْ عَمْرِو بْنِ شُعَیْبٍ عَنْ أَبِیہِ عَنْ جَدِّہِ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَیْسَ مِنَّا مَنْ تَشَبَّہَ بِغَیْرِنَا لَا تَشَبَّہُوْا بِالْیَہُودِ وَلَا بِالنَّصَارَی فَإِنَّ تَسْلِیمَ الْیَہُودِ الْإِشَارَۃُ بِالْأَصَابِعِ وَتَسْلِیمَ النَّصَارَی الْإِشَارَۃُ بِالْأَکُفِّ‘‘۔ \nحدیث 7:\n’’ عَن جَابِرٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَاَل إِنْ لَقِیْتُمُوھُمْ فَلا تُسَلِّمُوا عَلَیْھِمْ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کیا میں تم کو ایسی بات نہ بتاؤں کہ جب تم اس پر عمل کرو تو تمہارے درمیان محبت بڑھے اور وہ یہ ہے کہ آپس میں سلام کو رواج دو۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کلام سے پہلے سلام کرنا چاہیے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت عبد اللّٰہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ سلام میں پہل کرنے والا غرو ر و تکبر سے پاک ہے ۔ (بیہقی)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب کوئی تم میں سے کسی مجلس میں پہنچے تو سلام کرے پھر اگر بیٹھنے کی ضرورت ہو تو بیٹھ جائے اور جب چلنے لگے تو دوبارہ سلام کرے ۔ (ترمذی)\n¥ترجمہ حدیث 5:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اے بیٹے ! جب تو گھر میں داخل ہو تو گھر والوں کو سلام کر کیونکہ تیرا سلام تیرے اور تیرے گھر والوں کے لیے برکت کا سبب ہوگا۔ (ترمذی)\n¥ترجمہ حدیث 6:\nحضرت عمرو بن شعیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے اور وہ اپنے داداسے روایت کرتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جوشخص (سلام کرنے میں) غیروں کی مشابہت اختیار کرے وہ ہم سے نہیں ہے ۔ یہود ونصاری کی مشابہت نہ کرو، یہودیوں کاسلام انگلیوں کے اشارہ سے ہے اور نصاری کا سلام ہتھیلیوں کے اشارہ سے ہے ۔ (ترمذی ، مشکوۃ) \n¥ترجمہ حدیث 7:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اگر تمہاری ملاقات بدمذہبوں سے ہو انہیں سلام نہ کرو۔ (ابن ماجہ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke kya main tum ko aisi baat na bataun ke jab tum is par amal karo to tumhare darmiyan Mohabbat badhe aur woh yeh hai ke aapas mein Salam ko riwaj do. (Muslim). Tarjuma Hadees 2: Hazrat Jabir Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke kalam se pehle Salam karna chahiye. (Tirmidhi). Tarjuma Hadees 3: Hazrat Abdullah Radiyallahu Anhu se Marwi hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Salam mein pehal karne wala ghuroor-o-takabbur se Paak hai. (Baihaqi). Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu se Marwi hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab koi tum mein se kisi majlis mein pahunche to Salam kare phir agar baithne ki zaroorat ho to baith jaye aur jab chalne lage to dobara Salam kare. (Tirmidhi). Tarjuma Hadees 5: Hazrat Anas Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke ae bete! jab tu ghar mein dakhil ho to ghar walon ko Salam kar kyunke tera Salam tere aur tere ghar walon ke liye barkat ka sabab hoga. (Tirmidhi). Tarjuma Hadees 6: Hazrat Amr Bin Shuaib Radiyallahu Anhu apne baap se aur woh apne dada se Riwayat karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo Shakhs (Salam karne mein) gairon ki mushabahat ikhtiyar kare woh hum se nahi hai. Yahood-o-Nasara ki mushabahat na karo, Yahudiyon ka Salam ungliyon ke ishara se hai aur Nasara ka Salam hatheliyon ke ishara se hai. (Tirmidhi, Mishkat). Tarjuma Hadees 7: Hazrat Jabir Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke agar tumhari mulaqat bad-mazhabon se ho unhein Salam na karo. (Ibn Majah).", "explanation": "¥انتباہ :\n (۱)…خط میں سلام لکھا ہوتا ہے اس کا بھی جواب دینا واجب ہے اس کی دو صورتیں ہیں۔ ایک تو یہ کہ زبان سے جواب دے ۔ دوسرے یہ کہ سلام کا جواب لکھ کر بھیج دے ۔ ([1]) (بہار شریعت)\n درمختار اور شامی جلد پنجم ص۲۷۵ میں ہے : ’’ یَجِبُ رَدُّ جَوَابِ کِتَابِ التَّحِیَّۃِ ‘‘۔ ([2])\n (۲)…کسی نے خط میں لکھا کہ فلاں کو سلام کہو تو مکتوب الیہ پر اس سلام کا پہنچانا واجب نہیں اگر پہنچائے گا تو ثواب پائے گا۔\n (۳)…کسی نے کہا کہ فلاں کو میرا سلام کہہ دینا اور اس نے وعدہ کرلیا تو سلام پہنچانا واجب ہے اگر نہیں پہنچائے گا تو گنہگار ہوگا۔ فتاویٰ عالمگیری باب السلام میں ہے :’’ إِذَا أَمَرَ رَجُلًا أَنْ یَقْرَأَ سَلَامَہُ عَلَی فُلانٍ یَجِبُ عَلَیْہِ ذَلِکَ ، کَذَا فِی الْغِیَاثِیَّۃِ ‘‘۔ ([3])\n شامی میں ہے :’’ وَالظَّاہِرُ أَنَّ ہَذَا إذَا رَضِیَ بِتَحَمُّلِہَا ‘‘۔ ([4])\n (۴)…کسی نے سلام بھیجا تو اس طرح جواب دے کہ پہلے پہنچانے والے کو پھر اس کو جس نے سلام بھیجا ہے یعنی یوں کہے ۔ ’’ عَلَیْکَ وَعَلَیْہِ السَّلَام ‘‘۔ فتاوی عالمگیری جلد پنجم باب السلام میں ہے : ’’ مَنْ بَلَّغَ إنْسَانًا سَلَامًا مِنْ غَاءِبٍ کَانَ عَلَیْہِ أَنْ یَرُدَّ الْجَوَابَ عَلَی الْمُبَلِّغِ أَوَّلًا ، ثُمَّ عَلَی ذَلِکَ الْغَاءِبِ ، کَذَا فِی الذَّخِیرَۃِ ‘‘۔ ([5])\n شامی میں ہے :’’ وَظَاہِرُہُ الْوُجُوبُ ‘‘۔ ([6])\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم ، (۱۶) ص ۱۰۶، ’’ الدر المختار ورد المحتار ‘‘، ج ۹، ص ۳۸۵.\n[2] ’’ الدر المختار ورد المحتار ‘‘، کتاب الحظر والإباحۃ ، فصل فی البیع ، ج ۹، ص ۶۸۵.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، الباب السابع فی السلام وتشمیت العاطس ، ج ۵، ص ۳۲۶.\n[4] ’’ رد المحتار ‘‘، کتاب الحظر والإباحۃ ، فصل فی البیع ، ج ۹، ص ۶۸۵.\n[5] ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، الباب السابع فی السلام وتشمیت العاطس ، ج ۵، ص ۳۲۶.\n[6] ’’ رد المحتار ‘‘، کتاب الحظر والإباحۃ ، فصل فی البیع ، ج ۹، ص ۶۸۵."}, {"id": 7855, "bookId": 14, "volNo": "1", "hadithNo": 87, "chapter": "مصافحہ", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ الْبَرَاء بْنِ عَازِبٍ قَال قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا بَیْنَ مُسْلِمَیْنِ یَلْتَقِیَانِ فَیَتَصَافَحَانِ إِلَّا غُفِرَ لَہُمَا قَبْلَ أَنْ یَتَفَرَّقَا‘‘۔ \nحدیث 2:\n’’عَنْ عَطَاءِ الْخُرَاسَانِیِّ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ تَصَافَحُوا یَذْہَبُ الْغِلُّ‘‘۔ \nحدیث 3:\n’’عَنْ زَارِعٍ وَکَانَ فِی وَفْدِ عَبْدِ الْقَیْسِ قَالَ لَمَّا قَدِمْنَا الْمَدِینَۃَ فَجَعَلْنَا نَتَبَادَرُ مِنْ رَوَاحِلِنَا فَنُقَبِّلُ یَدَ رَسُوْلِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَرِجْلَہُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت براء بن عازب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کہتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب دو مسلمان آپس میں ملتے ہیں اور مصافحہ کرتے ہیں تو ان دونوں کے جدا ہونے سے پہلے ان کو بخش دیا جاتا ہے ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت عطاء خراسانی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ آپس میں مصافحہ کیا کرو اس سے کینہ دور ہوگا۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت زارع جو ( وفد) عبدالقیس میں شامل تھے فرماتے ہیں کہ جب ہم مدینہ میں آئے تو ہم جلد جلد اپنی سواریوں سے اُتر پڑے اور ہم نے حضور علیہ الصلاۃ والسلام کے دست ِ مبارک اور پائے مبارک کو بوسہ دیا۔ (ابو داود، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Baraa Bin Aazib Radiyallahu Anhu kehte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab do Musalman aapas mein milte hain aur musafaha karte hain to un dono ke juda hone se pehle un ko bakhsh diya jata hai. (Tirmidhi). Tarjuma Hadees 2: Hazrat Ataa Khurasani Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke aapas mein musafaha kiya karo is se keena door hoga. (Tirmidhi). Tarjuma Hadees 3: Hazrat Zaari' jo (wafd) Abdul Qais mein shamil the farmate hain ke jab hum Madinah mein aaye to hum Jild Jild apni sawariyon se utar pade aur hum ne Rasoolullah Sallallahu Alayhi wa Sallam ke dast-e-mubarak aur paye mubarak ko bosa diya. (Abu Dawood, Mishkat).", "explanation": "¥انتباہ :\n (۱)…دینی پیشوا کا ہاتھ اور پاؤں چومنا جائز ہے ۔ حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اشعۃ اللمعات، جلد چہارم، ص: ۲۱ پر فرماتے ہیں کہ:\n ’’ بوسہ دادن دست عالم متورّع را جائز ست وبعضے گفتہ اند مستحب ست ‘‘۔ ([1])\n یعنی پرہیزگار عالم کا ہاتھ چومنا جائز ہے اور بعض علماء نے فرمایا کہ مستحب ہے ۔\n اور وفد عبدالقیس کی حدیث کے تحت فرماتے ہیںکہ:\n ’’ ازیں جا تجویز پائے بوس معلوم شد ‘‘۔ ([2])\n یعنی اس حدیث شریف سے پاؤں چومنے کا جواز ثابت ہوا۔\n اور درمختار بحث مصافحہ میں ہے کہ:\n’’ لَا بَأْسَ بِتَقْبِیلِ یَدِ الرَّجُلِ الْعَالِمِ وَالْمُتَوَرِّعِ عَلَی سَبِیلِ التَّبَرُّکِ ‘‘۔ ([3])\nیعنی برکت کے لیے عالم اور پرہیزگار آدمی کا ہاتھ چومنا جائز ہے ۔\n (۲)…ہر نماز باجماعت کے بعد بھی مصافحہ کرنا جائز ہے ۔ درمختار کتاب الحظر والا باحۃ باب الاستبراء میں ہے :\n ’’ تَجُوْزُ الْمَصَافَحَۃُ وَلَوْ بَعْدَ الْعَصْرِ وَقَوْلُہُمْ إنَّہُ بِدْعَۃٌ أَیْ مُبَاحَۃٌ حَسَنَۃٌ کَمَا أَفَادَہُ النَّوَوِیُّ فِی أَذْکَارِہِ ا ہـ ملخصاً ‘‘۔ ([4])\n یعنی بعد نماز عصر بھی مصافحہ کرنا جائز ہے اور فقہاء نے جو اُسے بدعت فرمایا تو وہ بدعت ِمباحہ حسنہ ہے ۔ جیسا کہ امام نووی نے اپنے اذکار میں فرمایا۔\n اسی کے تحت رد المحتارمیں ہے :\n’’ قَالَ اعْلَمْ أَنَّ الْمُصَافَحَۃَ مُسْتَحَبَّۃٌ عِنْدَ کُلِّ لِقَاء ، وَأَمَّا مَا اعْتَادَہُ النَّاسُ مِنَ الْمُصَافَحَۃِ بَعْدَ صَلَاۃِ الصُّبْحِ وَالْعَصْرِ ، فَلَا أَصْلَ لَہُ فِی الشَّرْعِ عَلَی ہَذَا الْوَجْہِ وَلَکِنْ لَا بَأْسَ بِہِ قَالَ الشَّیْخُ أَبُو الْحَسَنِ الْبِکْرِیُّ وَتَقْیِیْدُہُ بِمَا بَعْدَ الصُّبْحِ وَالْعَصْرِ عَلَی عَادَۃٍ کَانَتْ فِی زَمَنِہِ ، وَإِلَّا فَعَقِبَ الصَّلَوَاتِ کُلِّہَا کَذَلِکَ اہـ ملخصاً ‘‘۔ ([5])\nیعنی امام نووی نے فرمایا کہ ہر ملاقات کے وقت مصافحہ کرنا سنت ہے اور فجر و عصر کی نماز کے بعد جو مصافحہ کا رواج ہے اس کی شریعت میں کوئی اصل نہیں لیکن اس میں کوئی حرج بھی نہیں۔ شیخ ابوالحسن بکری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ صبح و عصر کی قید فقط لوگوں کی عادت کی بنا پر ہے جو امام نووی کے زمانہ میں تھی ورنہ ہرنماز کے بعد مصافحہ کا یہی حکم ہے یعنی جائز ہے ۔ (شامی، جلد پنجم ص ۲۵۲)\n (۳)…وہابی غیر مقلد دونوں ہاتھ سے مصافحہ کرنے کو ناجائز اور خلافِ حدیث بتاتے ہیں یہ ان کی جہالت ہے ۔ حضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اشعۃ اللمعات ترجمہ مشکوۃ، جلد چہارم ، ص۲۰ پر فرماتے ہیں:\n ’’ مصافحہ سنت است نزد ملاقات وباید کہ بہر دو دست بود ‘‘۔ ([6])\nیعنی ملاقات کے وقت مصافحہ کرنا سنت ہے اور دونوں ہاتھ سے کرنا چاہیے ۔\n اور احادیث کریمہ میں جو لفظ ’’ ید ‘‘ مستعمل ہے اس سے صرف ایک ہاتھ سے مصافحہ کا استدلال صحیح نہیں اس لیے کہ ایسی دو چیزیں جو ایک دوسرے کے ساتھ رہتی ہوں جیسے ہاتھ ، پاؤں ، آنکھ ، موزہ ، جوتا اور دستانہ وغیرہ اس میں واحد کا لفظ بول کر دونوں مرا دلیے جاتے ہیں، مثلاً زید نے ہاتھ سے پکڑ ا یعنی دونوں ہاتھ سے ، اور پاؤں سے چلا ، یعنی دونوں پاؤں سے اور آنکھ سے دیکھا۔ یعنی دونوں آنکھ سے اور کہا جاتا ہے زید نے جوتا پہنا یعنی دونوں جوتے ۔ وَقِسْ عَلَی ھَذَا الْبَواقِی ۔\n یہ محاورہ ہند، ایران اور عرب میں سب جگہ مسلّم ہے ورنہ حدیث شریف’’ أَطْیَبُ الْکَسْبِ عَمَلُ الرَّجُلِ بِیَدِہِ ‘‘کا یہ مطلب ہوجائے گا کہ صرف ایک ہاتھ کی کمائی بہتر ہے دونوں ہاتھ کی کمائی بہتر نہیں۔ اور مشہور حدیث ’’ اَلْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِہِ وَیَدِہِ ‘‘کا یہ مطلب ماننا پڑے گا کہ کامل مسلمان وہ شخص ہے جس کے صرف ایک ہاتھ سے مسلمان امان میں رہیں اور دوسرے ہاتھ سے تکلیف میں۔\n مَنْ ([7]) شَاء التَّفْصِیْلَ لِھَذِہِ الْمَسْءَلَۃِ فَلْیُطَالِعْ ’’ صفَاءِحُ اللُّجَیْن فِیْ کَوْنِ التَّصَافُحِ بِکفی الیَدَیْن ‘‘ للإمام أحمد رضا رضی اللّٰہ تعالی عنہ\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الأداب ، باب المصافحۃ والمعانقۃ ، ج ۴، ص ۲۲.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب الأداب ، باب المصافحۃ والمعانقۃ ، الفصل الثانی ، ج ۴، ص ۲۷.\n[3] ’’ الدر المختار ‘‘، کتاب الحظر والإباحۃ ، باب الاستبراء وغیرہ ، ج ۹، ص ۶۳۱.\n[4] ’’ الدر المختار ‘‘، کتاب الحظر والإباحۃ ، باب الاستبراء وغیرہ ، ج ۹، ص ۶۲۸.\n[5] ’’ رد المحتار ‘‘، کتاب الحظر والإباحۃ ، باب الاستبراء وغیرہ ، ج ۹، ص ۶۲۸.\n[6] ’’ اشعۃ اللمعات ‘‘، کتاب الآداب ، باب المصافحۃ والمعانقۃ ، ج ۴، ص ۲۲.\n[7] تفصیل کے لیے اعلی حضرت امام احمد رضا رضی اللّٰہ تعالی عنہ کی کتاب ’’ صفَاءِحُ اللُّجَیْن ‘‘ ملاحظہ کیجیے ۔ ۱۲ منہ"}, {"id": 7856, "bookId": 14, "volNo": "1", "hadithNo": 88, "chapter": "ماں باپ کے حقوق", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَال قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ رَغِمَ أَنْفُہُ رَغِمَ أَنْفُہُ رَغِمَ أَنْفُہُ قِیلَ مَنْ یَا رَسُولَ اللّٰہ قَالَ مَنْ أَدْرَکَ وَالِدَیْہِ عِنْدَ الْکِبَرِ أَحَدَہُمَا أَوْ کِلَاہمَا ثُمَّ لَمْ یَدْخُلِ الْجَنَّۃَ‘‘۔ \nحدیث 2:\n’’عَنْ مُعَاوِیَۃَ بْنِ جَاہِمَۃَ أَنَّ جَاہِمَۃَ جَاءَ إِلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ یَا رَسُولَ اللّٰہ أَرَدْتُ أَنْ أَغْزُوَ وَقَدْ جِئْتُ أَسْتَشِیرُکَ فَقَالَ ہَلْ لَکَ مِنْ أُمٍّ قَالَ نَعَمْ قَالَ فَالْزَمْہَا فَإِنَّ الْجَنَّۃَ عِنْدَ رِجْلِہَا‘‘۔ \nحدیث 3:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَصْبَحَ مُطِیْعاً للَّہِ فِیْ وَالِدَیْہِ أَصْبَحَ لَہ بَابَانِِ مَفْتُوْحَانِِ مِنَ الْجَنَّۃِ وَاِنْ کَانَ وَاحِدًا فَوَاحِدًا وَمَنْ أَصْبَحَ عَاصِیًا للَّہِ فِیْ وَالِدَیْہِ أَصْبَحَ لَہ بَابَانِ مَفتُوْحَانِ مِنَ النَّارِ اِنْ کَانَ وَاحِدًا فَوَاحِدًا قَالَ رَجُلٌ وَإِنْ ظَلَمَاہُ قَالَ وَإِنْ ظَلَمَاہُ وَإِنْ ظَلَمَاہُ وَإِنْ ظَلَمَاہُ‘‘۔ \nحدیث 4:\n’’عَنْ أَبِی أُمَامَۃَ أَنَّ رَجُلًا قَالَ یَا رَسُولَ اللّٰہ مَا حَقُّ الْوَالِدَیْنِ عَلَی وَلَدِہِمَا قَالَ ہُمَا جَنَّتُکَ وَنَارُکَ‘‘۔ (ابن ماجہ)\nحدیث 5:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ رِضَی الرَّبِّ فِی رِضَی الْوَالِدِ وَسَخَطُ الرَّبِّ فِی سَخَطِ الْوَالِدِ‘‘۔\nحدیث 6:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مِنَ الْکَبَاءِرِ شَتْمُ الرَّجُلِ وَالِدَیْہِ قَالُوا یَا رَسُولَ اللّٰہ وَہَلْ یَشْتِمُ الرَّجُلُ وَالِدَیْہِ قَالَ نَعَمْ یَسُبُّ أَبَا الرَّجُلِ فَیَسُبُّ أَبَاہُ وَیَسُبُّ أُمَّہُ فَیَسُبُّ أُمَّہُ‘‘۔ \nحدیث 7:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ زَارَ قَبْرَ أَبَوَیْہِ أَوْ أَحَدِہِمَا فِی کُلِّ جُمُعَۃٍ غَفَرَ اللّٰہ لَہُ وَکُتِبَ بَرًّا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اس کی ناک غبار آلود ہو ، اس کی ناک خاک آلود ہو، اس کی ناک خاک آلود ہو( یعنی ذلیل و رسوا ہو) کسی نے عرض کیا یارسول اللّٰہ وہ کون ہے ؟ حضور نے فرمایا کہ جس نے ماں باپ دونوں کو یا ایک کو پڑھاپے کے وقت میں پایا پھر ( ان کی خدمت کرکے ) جنت میں داخل نہ ہوا۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت معاویہ بن جاہمہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ ان کے والد جاہمہ حضور علیہ الصلاۃ والسلام کی خدمت میں حاضر ہوئے اور عرض کیا یارسول اللّٰہ ! میرا ارادہ جہاد میں جانے کا ہے حضور سے مشورہ لینے کے لیے حاضر ہوا ہوں ارشاد فرمایاکیا تیری ماں ہے ؟ عرض کیا ہاں۔ فرمایا اس کی خدمت اپنے اوپر لازم کرلے کہ جنت ماں کے قدموں کے تلے ہے ۔ (احمد، نسائی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس نے اس حال میں صبح کی کہ ماں باپ کے بارے میں اللّٰہ تعالیٰ کا فرماںبردار رہا توا س کے لیے صبح ہی کو جنت کے دو دروازے کھل جاتے ہیں اور اگر والدین میں سے ایک ہو تو ایک دروازہ کھلتا ہے اور جس نے اس حال میں صبح کی کہ والدین کے بارے میں خدائے تعالیٰ کا نافرمان بندہ رہا تو اس کے لیے صبح ہی کو جہنم کے دو دروازے کھل جاتے ہیں اور ایک ہو توایک دروازہ کھلتا ہے ایک شخص نے کہا اگر چہ ماں باپ اس پر ظلم کریں حضور نے فرمایا اگرچہ ظلم کریں اگرچہ ظلم کریں اگرچہ ظلم کریں۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 4:\nحضرت ابو امامہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ ایک شخص نے عرض کیا یارسول اللّٰہ ! ماں باپ کا اولاد پر کیا حق ہے ؟فرمایا کہ وہ دونوں تیری جنت ودوزخ ہیں یعنی جو لوگ ان کو راضی رکھیں گے جنت پائیں گے اور جو ان کو ناراض رکھیں گے دوزخ کے مستحق ہوں گے ۔ (ابن ماجہ)\n¥ترجمہ حدیث 5:\nحضرت عبد اللّٰہ بن عمرو رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ پروردگار کی خوشنودی باپ کی خوشنودی میں ہے اور پروردگار کی ناراضگی باپ کی ناراضگی میں ہے ۔ (ترمذی)\n¥ترجمہ حدیث 6:\nحضرت عبد اللّٰہ بن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ یہ بات کبیرہ گناہوں میں سے ہے کہ آدمی اپنے ماں باپ کو گالی دے لوگوں نے عرض کیا یارسول اللّٰہ ! کیا کوئی اپنے ماں باپ کو بھی گالی دیتا ہے ؟فرمایا ہاں (اس کی صورت یہ ہوتی ہے کہ) یہ د وسرے کے باپ کو گالی دیتا ہے تووہ اس کے باپ کو گالی دیتا ہے اور یہ دوسرے کی ماں کو گالی دیتا ہے تو وہ اس کی ماں کو گالی دیتا ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 7:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو ماں باپ دونوں یا ان میں سے کسی ایک کی قبرپر ہر جمعہ کو زیارت کے لیے حاضر ہو تو اللّٰہ تعالیٰ اس کے گناہ بخش دے گا اور وہ ماں باپ کے ساتھ اچھا برتاؤ کرنے والا لکھا جائے گا۔", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke us ki Naaf gubar-aalood ho, us ki Naaf khak-aalood ho, us ki Naaf khak-aalood ho (ya'ni zaleel-o-ruswa ho) kisi ne arz kiya Ya Rasoolullah woh kaun hai? Rasoolullah ne farmaya ke jis ne maa baap dono ko ya ek ko budhape ke waqt mein paya phir (un ki khidmat kar ke) jannat mein dakhil na hua. (Muslim Shareef). Tarjuma Hadees 2: Hazrat Muawiyah Bin Jahimah Radiyallahu Anhum se Riwayat hai ke un ke walid Jahimah Rasoolullah Sallallahu Alayhi wa Sallam ki khidmat mein hazir hue aur arz kiya Ya Rasoolullah! mera irada jihad mein jane ka hai Rasoolullah se mashwara lene ke liye hazir hua hoon irshad farmaya kya teri maa hai? Arz kiya haan. Farmaya us ki khidmat apne upar lazim kar le ke jannat maa ke qadmon ke tale hai. (Ahmad, Nasai, Mishkat). Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhum se kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis ne is haal mein subah ki ke maa baap ke bare mein Allah Ta'ala ka farmanbardar raha to us ke liye subah hi ko jannat ke do darwaze khul jate hain aur agar walidain mein se ek ho to ek darwaza khulta hai aur jis ne is haal mein subah ki ke walidain ke bare mein Allah Ta'ala ka nafarman banda raha to us ke liye subah hi ko jahannam ke do darwaze khul jate hain aur ek ho to ek darwaza khulta hai ek Shakhs ne kaha agarche maa baap us par zulm karen Rasoolullah ne farmaya agarche zulm karen agarche zulm karen agarche zulm karen. (Baihaqi, Mishkat). Tarjuma Hadees 4: Hazrat Abu Umamah Radiyallahu Anhu se Riwayat hai ke ek Shakhs ne arz kiya Ya Rasoolullah! maa baap ka Aulaad par kya haq hai? Farmaya ke woh dono teri jannat-o-dozakh hain ya'ni jo log un ko raazi rakhenge jannat payenge aur jo un ko naraaz rakhenge dozakh ke mustahiq honge. (Ibn Majah). Tarjuma Hadees 5: Hazrat Abdullah Bin Amr Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke parwardigar ki khushnudi baap ki khushnudi mein hai aur parwardigar ki narazgi baap ki narazgi mein hai. (Tirmidhi). Tarjuma Hadees 6: Hazrat Abdullah Bin Umar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke yeh baat kabira gunahon mein se hai ke aadmi apne maa baap ko gaali de logon ne arz kiya Ya Rasoolullah! kya koi apne maa baap ko bhi gaali deta hai? Farmaya haan (is ki surat yeh hoti hai ke) yeh dusre ke baap ko gaali deta hai to woh us ke baap ko gaali deta hai aur yeh dusre ki maa ko gaali deta hai to woh us ki maa ko gaali deta hai. (Bukhari, Muslim). Tarjuma Hadees 7: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo maa baap dono ya un mein se kisi ek ki Qabr par har Jumu'ah ko Ziyarat ke liye hazir ho to Allah Ta'ala us ke gunah bakhsh dega aur woh maa baap ke sath achha bartao karne wala likha jayega.", "explanation": "*****"}, {"id": 7857, "bookId": 14, "volNo": "1", "hadithNo": 89, "chapter": "اولاد کے حقوق", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ جَابِرِ بْنِ سَمُرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَأَنْ یُؤَدِّبَ الرَّجُلُ وَلَدَہُ خَیْرٌ لَہُ مِنْ أَنْ یَتَصَدَّقَ بِصَاعٍ‘‘۔ \nحدیث 2:\n’’ عَنْ أَیُّوْبَ بْنِ مُوْسَی عَنْ أَبِیْہِ عَنْ جَدِّہِ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَا نَحَلَ وَالِدٌ وَلَدَہُ مِنْ نُّحْلٍ أَفْضَلَ مِنْ أَدَبٍ حَسَنٍ‘‘۔\nحدیث 3:\n’’عَنْ أَنَسٍِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ عَالَ جَارِیَتَیْنِ حَتَّی تَبْلُغَا جَاءَ یَوْمَ الْقِیَامَۃِ أَنَا وَہُوَ ہَکَذَا وَضَمَّ أَصَابِعَہُ‘‘۔\nحدیث 4:\n’’عَنْ سُرَاقَۃَ بْنِ مَالِکٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَلا أَدُلُّکُمْ عَلَی أَفْضَلِ الصَّدَقَۃِ ابْنَتُکَ مَرْدُودَۃً إِلَیْکَ لَیْسَ لَہَا کَاسِبٌ غَیْرُکَ‘‘۔\nحدیث 5:\n’’ عَنِ ابْنِ عَبََّاس قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ مَنْ عَالَ ثَلاثَ بَنَاتٍ أَوْمِثْلَھُنَّ مِنَ الاخَوَاتِ فَأَدَّبَھُنَّ وَرَحِمَھُنَّ حَتَّی یُغْنِیَھُنَّ اللّٰہ أَوْجَبَ اللّٰہ لَہُ الجَنَّۃَ فََقَالَ رَجُلٌ أَوْاِثْنَتَیْنِ قاَلَ أَوْ اِثْنَتَیْنِ حَتَّی لَوْ قَالُوا أَوْ وَاحِدَۃً لَقَالَ وَاحِدَۃً ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت جابر بن سمرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃوالسلام نے فرمایا کہ کوئی شخص اپنی اولاد کو ادب سکھائے تو اس کے لیے ایک صاع صدقہ کرنے سے بہتر ہے ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ایوب بن موسی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے اور وہ اپنے دادا سے روایت کرتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اولاد کے لیے باپ کا کوئی عطیہ اچھی تربیت سے بہتر نہیں ہے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس کی پرورش میں دو لڑکیاں بلوغ تک رہیں تو وہ قیامت کے دن اس طرح آئے گا کہ میں اور وہ بالکل پاس پاس ہوں گے ، یہ کہتے ہوئے حضور نے اپنی انگلیاں ملا کر فرمایا کہ اس طرح۔ (مسلم)\n¥ترجمہ حدیث 4:\nحضرت سراقہ بن مالک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کیا میں تم کو یہ نہ بتادوں کہ افضل صدقہ کیا ہے ؟ اور وہ اپنی اس لڑکی پر صدقہ کرنا ہے جو تمہاری طرف (مطلقہ یا بیوہ ہونے کے سبب) واپس لوٹ آئی اور تمہارے سوا کوئی اس کا کفیل نہیں۔ (ابن ماجہ، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص تین لڑکیوں یا تین بہنوں کی پرورش کرے پھر ان کو ادب سکھائے اور ان کے ساتھ مہربانی کرے یہاں تک کہ خدا ان کو مستغنی کردے (یعنی وہ بالغ ہوجائیں اور ان کا نکاح ہوجائے ) تو پرورش کرنے والے پر اللّٰہ تعالی جنت کو واجب کردے گا ایک شخص نے عرض کیا یارسول اللّٰہ ! اور دو بیٹیوں یا دو بہنوں کی پرورش پر کیا ثواب ہے ؟ حضور نے فرمایا دو کا ثواب بھی یہی ہے (راوی کہتے ہیں) اگر صحابہ ایک بیٹی یا ایک بہن کے بارے میں دریافت کرتے تو ایک کی نسبت بھی حضور یہی فرماتے ۔ (شرح السنۃ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Jabir bin Samurah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke koi shakhs apni aulaad ko adab sikhaye to us ke liye ek sa'a Sadaqah karne se behtar hai. (Tirmizi) Tarjuma Hadees 2: Hazrat Ayyub bin Musa Radiyallahu Anhu apne baap se aur woh apne dada se riwayat karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke aulaad ke liye baap ka koi atiya achi Tarbiyat se behtar nahi hai. (Baihaqi, Mishkat) Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis ki parwarish mein do ladkiyan Baaligh hone tak rahen to woh Qayamat ke din is tarah aayega ke main aur woh bilkul paas paas honge, yeh kehte hue Rasoolullah Sallallahu Alayhi wa Sallam ne apni ungliyan mila kar farmaya ke is tarah. (Muslim) Tarjuma Hadees 4: Hazrat Suraqah bin Maalik Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke kya main tum ko yeh na bata doon ke afzal Sadaqah kya hai? Aur woh apni us ladki par Sadaqah karna hai jo tumhari taraf (mutallaqa ya bewa hone ke sabab) wapas laut aayi aur tumhare siwa koi us ka kafeel nahi. (Ibn Majah, Mishkat) Tarjuma Hadees 5: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs teen ladkiyon ya teen behnon ki parwarish kare phir un ko adab sikhaye aur un ke sath meharbani kare yahan tak ke Khuda un ko mustaghni karde (yani woh Baaligh ho jayen aur un ka Nikah ho jaye) to parwarish karne wale par Allah Ta'ala Jannat ko Wajib karde ga. Ek shakhs ne arz kiya Ya Rasoolullah! Aur do betiyon ya do behnon ki parwarish par kya sawab hai? Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya do ka sawab bhi yahi hai (Raawi kehte hain) agar Sahabah ek beti ya ek behn ke bare mein daryaft karte to ek ki nisbat bhi Rasoolullah Sallallahu Alayhi wa Sallam yahi farmate. (Sharh us-Sunnah, Mishkat)", "explanation": "¥انتباہ:\n بچہ کا اچھا سا نام رکھے بُرا نام نہ رکھے کہ بُرے نام کا برا اثر ہوگا تو تربیت قبول نہ کرے گا، ماں یا کسی نیک نمازی عورت سے دو سال تک دودھ پلوائے ، پاک کمائی سے ان کی پرورش کرے کہ ناپاک مال ناپاک عادتیں پیدا کرتا ہے ، کھیلنے کے لیے اچھی چیز جو شرعاً جائز ہو دیتا رہے ، بہلانے کے لیے ان سے جھوٹا وعدہ نہ کرے ، جب کچھ ہوشیار ہو تو کھانے پینے ، اٹھنے بیٹھنے ، چلنے پھرنے ، ماں باپ اور استاد وغیرہ کی تعظیم کا طریقہ بتائے ، نیک استاد کے پاس قرآن مجید پڑھائے ، اسلام و سنت سکھائے ، حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کی تعظیم و محبت ان کے دل میں ڈالے کہ یہی اصل ایمان ہے ۔ جب بچہ کی عمر سات برس ہوجائے تو نماز کی تاکید کرے اور جب دس برس کا ہوجائے تو نماز کے لیے سختی کرے اگر نہ پڑھے تو مار کر پڑھائے ۔ وضو ، غسل اور نماز وغیرہ کے مسائل بتائے ۔ لکھنے اور تیرنے کی تعلیم دے ۔ فنِ سپہ گری بھی سکھائے ۔ بری صحبت سے بچائے ۔ عشقیہ ناول اور افسانے وغیرہ ہر گز نہ پڑھنے دے ۔ جب جوان ہوجائے تو نیک شریف النسب لڑکی سے شادی کردے اور وراثت سے اسے ہر گز محروم نہ کرے ۔\n اور لڑکیوں کو سینا پرونا ، کاتنا اور کھانا پکانا سکھائے ، سورۂ نور کی تعلیم دے اور لکھنا ہر گز نہ سکھائے کہ فتنہ کا احتمال غالب ہے ۔ بیٹوں سے زیادہ ان کی دلجوئی کرے ۔ نو برس کی عمر سے ان کی خاص نگہداشت شروع کرے ۔ شادی برات میں جہاں ناچ گانا ہو وہاں ہرگز نہ جانے دے ۔ ریڈیو سے بھی گانابجانا ہر گز نہ سننے دے جب بالغ ہوجائے تو نیک شریف النسب لڑکے کے ساتھ نکاح کردے ۔ فاسق و فاجر خصوصًا بدمذہب کے ساتھ ہر گز نکاح نہ کرے ۔ ([1])\n------------------\n[1] ماخوذ از ’’ مشعلۃ الارشاد فی حقوق الأولاد ‘‘ مصنفہ اعلحضرت إمام أحمد رضا رضی اللّٰہ تعالی عنہ . (’’ الفتاوی الرضویۃ ‘‘، ج ۲۴، ص ۴۵۲)"}, {"id": 7858, "bookId": 14, "volNo": "1", "hadithNo": 90, "chapter": "بھائی وغیرہ کے حقوق", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ سَعِیْدِ بْنِ الْعَاصِ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَقُّ کَبِیْرِ الْإِخْوَۃِ عَلَی صَغِیْرِہِمْ حَقّ الْوَالِدِ عَلَی وَلَدِہِ‘‘۔\nحدیث 2:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَیْسَ مِنَّا مَنْ لَمْ یَرْحَمْ صَغِیرَنَا وَلم یُوَقِّرْ کَبِیرَنَا وَیَأْمُرْ بِالْمَعْرُوفِ وَیَنْہَ عَنِ الْمُنْکَرِ‘‘۔ (ترمذی)\nحدیث 3:\n’’ عَنْہُ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَوَی یَتِیْماً إِلَی طَعَامِہِ وَشَرَابِہِ أَوْجَبَ اللّٰہ لَہُ الْجَنَّۃَ ‘‘۔\nحدیث 4:\n’’ عَنْ أَنَسٍ قَالَ قالَ رَسُولُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ لَا یَدْخُلُ الْجَنَّۃَ مَنْ لَا یَأْمَنُ جَارُہُ بَوَاءِقَہُ‘‘۔ (مسلم)\nحدیث 5:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ سَمِعْتُ رَسُُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ لَیْسَ الْمُؤْمِنُ بِالَّذِیْ یَشْبَعُ وَجَارُہُ جَاءِعٌ إِلَی جَنْبِہِ‘‘ ۔ \nحدیث 6:\n’’عَنْ أَنَس قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَالَّذِی نَفْسِی بِیَدِہِ لَا یُؤْمِنُ عَبْدٌ حَتَّی یُحِبََّ لِأَخِیْہِ مَا یُحِبُّ لِنَفْسِہِ‘‘۔ (بخاری، مسلم)", "urdu": "¥ترجمہ حدیث 1:\nحضرت سعید بن العاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ بڑے بھائی کا حق چھوٹے بھائی پر ایسا ہے جیسا کہ باپ کا حق بیٹے پر ۔ (بیہقی)\n¥ترجمہ حدیث 2:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو ہمارے چھوٹوں پر رحم نہ کرے ، ہمارے بڑوں کی عزت نہ کرے ، نیکی کا حکم نہ دے اور برائی سے منع نہ کرے وہ ہم میں سے نہیں ہے ۔ \n¥ترجمہ حدیث 3:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص یتیم کو اپنے کھانے پینے میں شریک کرے اللّٰہ تعالیٰ اس کے لیے جنت واجب کردے گا۔ (شرح السنۃ)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ وہ شخص جنت میں نہیں جائے گا جس کا پڑوسی اس کی آفتوں سے محفوظ نہ ہو۔ \n¥ترجمہ حدیث 5:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم انے کہا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ وہ مومن نہیں جو خود پیٹ بھر کھائے اور اس کا پڑوسی اس کے پہلو میں بھوکا رہے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 6:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ قسم ہے اس ذات کی جس کے قبضہ میں میری جان ہے کہ بندہ اس وقت تک مومن نہیں ہوتا جب تک کہ اپنے بھائی کے لیے بھی وہ پسند نہ کرے جس کو وہ خود اپنے لیے پسند کرتا ہے ۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Saeed bin Al-Aas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke bade bhai ka haq chhote bhai par aisa hai jaisa ke baap ka haq bete par. (Baihaqi) Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo hamare chhoton par raham na kare, hamare badon ki izzat na kare, neki ka Hukm na de aur burai se mana na kare woh hum mein se nahi hai. Tarjuma Hadees 3: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs yateem ko apne khane peene mein shareek kare Allah Ta'ala us ke liye Jannat Wajib karde ga. (Sharh us-Sunnah) Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke woh shakhs Jannat mein nahi jaye ga jis ka padosi us ki aafton se mehfooz na ho. Tarjuma Hadees 5: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke woh Momin nahi jo khud pet bhar khaye aur us ka padosi us ke pehlu mein bhooka rahe. (Baihaqi, Mishkat) Tarjuma Hadees 6: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke qasam hai us zaat ki jis ke qabza mein meri jaan hai ke banda us waqt tak Momin nahi hota jab tak ke apne bhai ke liye bhi woh pasand na kare jis ko woh khud apne liye pasand karta hai. (Bukhari, Muslim)", "explanation": "*****"}, {"id": 7859, "bookId": 14, "volNo": "1", "hadithNo": 91, "chapter": "چوری اور شراب نوشی", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَعَنَ اللّٰہ السَّارِقَ‘‘۔ \nحدیث 2:\n’’عَنْ فَضَالَۃَ بْنِ عُبَیْدٍ قَالَ أُتِیَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بِسَارِقٍ فَقُطِعَتْ یَدُہُ ثُمَّ أَمَرَ بِہَا فَعُلِّقَتْ فِی عُنُقِہ‘‘۔ \nحدیث 3:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَا یَدْخُلُ الْجَنَّۃَ عَاقٌّ وَ لَا قَمَّارٌ وَلَا مَنَّانٌ وَلَا مُدْمِنُ خَمْرٍ‘‘۔ \nحدیث 4:\n’’ عَنْ أَبِیْ أُمَامَۃَ قَالَ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَلََفَ رَبِیّ عَزَّ وَجَلَّ بِعِزَّتِیْ لَا یَشْرَبُ عَبْدٌ مِنْ عَبِیْدِیْ جَرْعَۃً مِنْ خَمْرٍ إِلَّا سَقَیْتُہُ مِنَ الصَّدِیْدِ مِثْلَھَا وَلَا یَتْرُکُھَا مِنْ مَخَافَتِیْ اِلَّا سَقَیْتُہُ مِنْ حِیَاضٍ الْقُدْسِ‘‘۔ \nحدیث 5:\n’’عَنْ وَائِلِ الْحَضْرَمِیِّ أَنَّ طَارِقَ بْنَ سُوَیْدٍ سَأَلَ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنِ الْخَمْرِ فَنَہَاہُ فَقَالَ إِنَّمَا أَصْنَعُہَا لِلدَّوَاءِ فقَالَ إِنَّہُ لَیْسَ بِدَوَاء وَلَکِنَّہُ دَاء ‘‘۔ \nحدیث 6:\n’’ عَنْ جَابِرٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوہُ فَإِنْ عَادَ فِی الرَّابِعَۃِ فَاقْتُلُوْہُ‘‘۔ \nحدیث 7:", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ چور پر اللّٰہ تعالیٰ نے لعنت فرمائی ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت فضالہ بن عبید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام کے پاس ایک چور لایا گیا تو اس کا ہاتھ کاٹا گیا۔ پھر حضور نے فرمایا کہ وہ کٹا ہوا ہاتھ اس کی گردن میں لٹکا دیا جائے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت عبد اللّٰہ بن عمرو رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ والدین کی نافرمانی کرنے والا، جوا کھیلنے والا، احسان جتانے والا اور شراب کا عادی جنت میں داخل نہ ہوگا۔ \n¥ترجمہ حدیث 4:\nحضرت ابو امامہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اللّٰہ تعالیٰ فرماتا ہے قسم ہے میری عزت کی میرا جو بندہ شراب کا ایک گھونٹ بھی پیے گا میں اس کو اسی کے مثل پیپ پلاؤں گا اور جو بندہ میرے خوف سے شراب پیناچھوڑ دے گا میں اس کو مقدس حوضوں میں سے (شراب طہور) پلاؤں گا۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت وائل حضرمی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ طارق بن سوید نے حضور علیہ الصلاۃ والسلام سے شراب کشید کرنے کی بابت دریافت کیا تو حضور نے منع فرمایا۔ انہوں نے عرض کیا ہم تو اسے صرف دوا کے لیے بناتے ہیں۔ حضور نے فرمایا وہ دوا نہیں ہے بلکہ وہ خود بیماری ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 6:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شرا ب پیئے اسے دُرّے مارو اور جو شخص چوتھی مرتبہ شراب پیئے اسے قتل کردو۔ (ترمذی)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke chor par Allah Ta'ala ne la'nat farmayi hai. (Bukhari, Muslim) Tarjuma Hadees 2: Hazrat Fazalah bin Ubaid Radiyallahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ke paas ek chor laya gaya to us ka haath kaata gaya. Phir Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke woh kata hua haath us ki gardan mein latka diya jaye. (Tirmizi) Tarjuma Hadees 3: Hazrat Abdullah bin Amr Radiyallahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke walidain ki nafarmani karne wala, Jua khelne wala, ehsan jatane wala aur sharab ka aadi Jannat mein dakhil na hoga. Tarjuma Hadees 4: Hazrat Abu Umamah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala farmata hai qasam hai meri izzat ki mera jo banda sharab ka ek ghont bhi piye ga main us ko isi ke misl peep pilaunga aur jo banda mere khauf se sharab peena chhod de ga main us ko muqaddas Hauzon mein se (sharab-e-tahoor) pilaunga. (Ahmad, Mishkat) Tarjuma Hadees 5: Hazrat Wa'il Hazrami Radiyallahu Anhu se riwayat hai ke Tariq bin Suwaid ne Rasoolullah Sallallahu Alayhi wa Sallam se sharab kasheed karne ki babat daryaft kiya to Rasoolullah Sallallahu Alayhi wa Sallam ne mana farmaya. Unhon ne arz kiya hum to ise sirf Dawa ke liye banate hain. Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya woh Dawa nahi hai balki woh khud bimari hai. (Muslim Shareef) Tarjuma Hadees 6: Hazrat Jabir Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo sharab piye use durre maaro aur jo shakhs chauthi martaba sharab piye use qatl kardo. (Tirmizi)", "explanation": "¥انتباہ :\n اگر حکومت ِ اسلامیہ ہوتی تو چوری کرنے والے کا ہاتھ کاٹا جاتا اور شراب پینے والے کوا سی درّے مارے جاتے ۔ موجودہ صورت میں ان کے لیے یہ حکم ہے کہ مسلمان ان کا بائیکاٹ کریں ان کے ساتھ کھانا پینا، اُٹھنا بیٹھنا اور کسی قسم کے اسلامی تعلقات نہ رکھیں تاوقتیکہ وہ لوگ توبہ کرکے اپنے افعال قبیحہ سے باز نہ آجائیں اگر مسلمان ایسا نہ کریں گے تو وہ بھی گنہ گار ہوں گے ۔"}, {"id": 7860, "bookId": 14, "volNo": "1", "hadithNo": 92, "chapter": "جھوٹ", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنِ ابْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الصِّدْقَ بِرٌّ وَإِنَّ الْبِرَّ یَہْدِی إِلَی الْجَنَّۃِ وَإِنَّ الْکَذِبَ فُجُورٌ وَإِنَّ الْفُجُورَ یَہْدِی إِلَی النَّارِ‘‘۔\nحدیث 2:\n’’عَنِ ابْنِ عُمَرَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا کَذَبَ الْعَبْدُ تَبَاعَدَ عَنْہُ الْمَلَکُ مِیْلًا مِنْ نَتْنِ مَا جَاءَ بِہِ‘‘۔ \nحدیث 3:\n’’ عَنْ صُفْوَانَ بْنِ سُلَیْمٍ أَنَّہُ قِیْلَ لِرَسُوْلِ اللّٰہصَلَّی اللّٰہعَلَیْہِ وَسَلَّمَ أَیَکُوْنُ الْمُؤْمِنُ جَبَاناً قَالَ نَعَمْ فَقِیْلَ لَہُ أَیَکُوْنُ الْمُؤْمِنُ بَخِیْلاً قَالَ نَعَمْ فَقِیْلَ لَہُ أَیَکُوْنُ الْمُؤْمِنُ کَذَّابًا قَالَ لَا‘‘۔ \nحدیث 4:\n’’ عَنْ أُمِّ کُلْثُومٍ قَالَتْ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَیْسَ الْکَذَّابُ الَّذِی یُصْلِحُ بَیْنَ النَّاسِ وَیَقُولُ خَیْرًا وَیَنْمِی خَیْرًا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ سچ بولنا نیکی ہے اور نیکی جنت میں لے جاتی ہے ۔ اور جھوٹ بولنا فسق و فجور ہے اور فسق و فجور دوزخ میں لے جاتا ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب بندہ جھوٹ بولتا ہے تو اس کی بدبوسے فرشتہ ایک میل دور ہٹ جاتا ہے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت صفوان بن سلیم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام سے پوچھا گیا کیا مومن بزدل ہوتا ہے ؟ حضور نے فرمایا ہاں(ہوسکتا ہے ) پھر عرض کیا گیا کیا مومن بخیل ہوسکتا ہے ؟ فرمایا ہاں(ہوسکتاہے )پھرپوچھاگیاکیامومن کذّاب یعنی جھوٹا ہوتا ہے ؟ فرمایا نہیں۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 4:\nحضرت اُم کلثوم رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ وہ شخص جھوٹا نہیں ہے جو لوگوں کے درمیان صلح پیدا کرتا ہے اچھی بات کہتا ہے ا ور اچھی بات پہنچاتا ہے ۔", "roman": "Tarjuma Hadees 1: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke sach bolna neki hai aur neki Jannat mein le jaati hai. Aur jhoot bolna fisq-o-fujoor hai aur fisq-o-fujoor dozakh mein le jaata hai. (Muslim Shareef) Tarjuma Hadees 2: Hazrat Ibn Umar Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab banda jhoot bolta hai to us ki Badboo se farishta ek meel door hat jaata hai. (Tirmizi) Tarjuma Hadees 3: Hazrat Safwan bin Saleem Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam se poocha gaya kya Momin buzdil hota hai? Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya haan (ho sakta hai) phir arz kiya gaya kya Momin bakheel ho sakta hai? Farmaya haan (ho sakta hai) phir poocha gaya kya Momin kazzab yani jhoota hota hai? Farmaya nahi. (Baihaqi, Mishkat) Tarjuma Hadees 4: Hazrat Umm-e-Kulsoom Radiyallahu Anha ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke woh shakhs jhoota nahi hai jo logon ke darmiyan sulah paida karta hai, achi baat kehta hai aur achi baat pahunchata hai.", "explanation": "*****"}, {"id": 7861, "bookId": 14, "volNo": "1", "hadithNo": 93, "chapter": "چغلی غیبت", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ حُذَیْفَۃَ قَالَ سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ لَا یَدْخُلُ الْجَنَّۃَ قَتَّاتٌ‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ واَسْمَاء بِنْتِ یزیدَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ شِرَارُ عِبَادِ اللّٰہ الْمَشَّاء وْنَ بِالنَّمِیمَۃِ الْمُفَرِّقُونَ بَیْنَ الْأَحِبَّۃِ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَتَدْرُونَ مَاالْغِیبَۃُ قَالُوا اللّٰہ وَرَسُولُہُ أَعْلَمُ قَالَ ذِکْرُکَ أَخَاکَ بِمَا یَکْرَہُ قِیلَ أَفَرَأَیْتَ إِنْ کَانَ فِی أَخِی مَا أَقُولُ قَالَ إِنْ کَانَ فِیہِ مَا تَقُولُ فَقَدِ اغْتَبْتَہُ وَإِنْ لَمْ یَکُنْ فِیہِ مَا تَقُوْلُ فَقَدْ بَہَتَّہُ‘‘۔ \nحدیث 4:\n’’ عَنْ أَبِی سَعِیْدٍ وَ جَابِرٍ قَالَا قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اَلْغِیْبَۃُ اَشَدُّ مِنَ الزِّنَا قَالُوْا یَارَسُوْلَ اللّٰہ وَکَیْفَ الْغِیْبَۃُ اَشَدُّ مِنَ الزِّنَا قَالَ اِنَّ الرَّجُلَ لَیَزْنِیْ فَیَتُوْبُ فَیَغْفِِرُ اللّٰہ لَہُ وَاِنَّ صَاحِبَ الْغِیْبَۃِ لَا یَغْفِرُلَہُ حَتَّی یَغْفِرَھَا لَہُ صَاحِبُہُ ‘‘۔ \nحدیث 5:\n’’ عَنْ بَھْزِ بْنِ حَکِیْمٍ عَنْ أَبِیْہِ عَنْ جَدِّہِ قَالَ قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَتَرْغَبُوْنَ عَنْ ذِکْْرِ الْفَاجِرِ مَتَی یَعْرِفُہُ النَّاسُ اُذْکُرُوْا الْفَاجِرَ بِمَا فِیْہِ یَحْذُرُہُ النَّاسُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت حذیفہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ چغل خور جنت میں نہیں جائے گا۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت عبدالرحمن بن غنم اور اسماء بنت یزید رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالیٰ کے بدترین بندے وہ ہیں جو لوگوں میں چغلی کھاتے پھرتے ہیں اور دوستوں کے درمیان جدائی ڈالتے ہیں۔ (احمد، بیہقی)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ تمہیں معلوم ہے غیبت کیا چیز ہے ؟ لوگوں نے عرض کیا اللّٰہ و رسول کو اس کا بہتر علم ہے ۔ ارشاد فرمایا غیبت یہ ہے کہ تو اپنے بھائی کے بارے میں ایسی بات کہے جو اسے بری لگے کسی نے عرض کیا اگر میرے بھائی میں وہ برائی موجود ہو تو کیا اس کوبھی غیبت کہاجائے گا؟ فرمایا جو کچھ تم کہتے ہو اگر اس میں موجود ہو جبھی تو غیبت ہے اور اگر تم ایسی بات کہو جو اس میں موجود نہ ہو تو یہ تو بہتان ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 4:\nحضرت ابوسعید و حضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ غیبت زنا سے بدتر ہے ۔ صحابہ نے عرض کیا یارسول اللّٰہ ! غیبت زنا سے بدتر کیوں ہے ؟ فرمایا آدمی زنا کرتا ہے پھر توبہ کرتا ہے تو اللّٰہ تعالیٰ اس کو اپنے فضل سے معاف فرما دیتا ہے لیکن غیبت کرنے والے کو اللّٰہ تعالی معاف نہیں فرماتا جب تک کہ اس کو وہ شخص معاف نہ کردے جس کی غیبت کی گئی ہے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت بہز بن حکیم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ اپنے باپ سے روایت کرتے ہیں اور وہ اپنے دادا سے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کیا تم لوگ فاجر کو بُرا کہنے سے پرہیز کرتے ہو؟آخراسے لوگ کیونکرپہچانیں گے ۔ فاجر کی برائیاں بیان کیا کرو تاکہ لوگ اس سے بچیں۔ (سنن بیہقی)", "roman": "Tarjuma Hadees 1: Hazrat Huzaifah Radiyallahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke chughal khor Jannat mein nahi jaye ga. (Bukhari, Muslim) Tarjuma Hadees 2: Hazrat Abdur Rahman bin Ghanam aur Asma bint Yazeed Radiyallahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Khuda-e-Ta'ala ke badtareen bande woh hain jo logon mein chughli khate phirte hain aur doston ke darmiyan judai daalte hain. (Ahmad, Baihaqi) Tarjuma Hadees 3: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke tumhein maloom hai gheebat kya cheez hai? Logon ne arz kiya Allah-o-Rasool ko is ka behtar Ilm hai. Irshad farmaya gheebat yeh hai ke tu apne bhai ke bare mein aisi baat kahe jo use buri lage. Kisi ne arz kiya agar mere bhai mein woh burai maujood ho to kya us ko bhi gheebat kaha jaye ga? Farmaya jo kuch tum kehte ho agar us mein maujood ho jabhi to gheebat hai aur agar tum aisi baat kaho jo us mein maujood na ho to yeh to bohtan hai. (Muslim Shareef) Tarjuma Hadees 4: Hazrat Abu Saeed aur Hazrat Jabir Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke gheebat zina se badtar hai. Sahabah ne arz kiya Ya Rasoolullah! Gheebat zina se badtar kyun hai? Farmaya aadmi zina karta hai phir Taubah karta hai to Allah Ta'ala us ko apne fazl se maaf farma deta hai lekin gheebat karne wale ko Allah Ta'ala maaf nahi farmata jab tak ke us ko woh shakhs maaf na karde jis ki gheebat ki gayi hai. (Baihaqi, Mishkat) Tarjuma Hadees 5: Hazrat Bahz bin Hakeem Radiyallahu Anhu apne baap se riwayat karte hain aur woh apne dada se ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya kya tum log Faajir ko bura kehne se parhez karte ho? Aakhir use log kyonkar pehchanenge. Faajir ki buraiyan bayan kiya karo taake log us se bachen. (Sunan Baihaqi)", "explanation": "¥انتباہ :\n (۱) …فاسق معلن یا بدمذہب کی برائی بیان کرنا جائز ہے بلکہ اگر لوگوں کو اس کے شر سے بچانا مقصود ہو تو ثواب ملنے کی امید ہے ۔ ([1]) (بہار شریعت بحوالہ رد المحتار)\n (۲) …جو شخص علانیہ برا کام کرتا ہو اور اس کو اس بات کی کوئی پرواہ نہیں کہ لوگ اسے کیا کہیں گے تو اس شخص کی اس بری حرکت کا بیان کرنا غیبت نہیں مگر اس کی دوسری باتیں جو ظاہر نہیں ہیں ان کو ذکر کرنا غیبت ہے ۔ ([2]) (بہار شریعت بحوالہ رد المحتار)\n آج کل بہت سے وہابی اپنی وہابیت چھپاتے اور خود کو سنّی ظاہر کرتے ہیںا ور جب موقع پاتے ہیں تو بدمذہبی کی آہستہ آہستہ تبلیغ کرتے ہیں ان کی بدمذہبی کو ظاہر کرنا غیبت نہیں اس لیے کہ لوگوں کو ان کے مکرو شر سے بچانا ہے ۔ اور اگر وہ اپنی بدمذہبی کو نہیں چھپاتا بلکہ علانیہ ظاہر کرتا ہے جب بھی غیبت نہیں اس لیے کہ وہ علانیہ برائی کرنے والوں میں داخل ہے ۔ ([3]) (بہار شریعت)\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم، (۱۶) ص۱۷۷، ’’ رد المحتار ‘‘ ، کتاب الحظر والإباحۃ ، ج ۹، ص ۶۷۴.\n[2] ’’بہارِ شریعت‘‘، حصہ شانزدہم، (۱۶) ص۱۷۷، ’’ رد المحتار ‘‘ ، کتاب الحظر والإباحۃ ، ج ۹، ص ۶۷۴.\n[3] ’’بہارِ شریعت‘‘، حصہ شانزدہم، (۱۶) ص۱۷۷، ’’ رد المحتار ‘‘ ، کتاب الحظر والإباحۃ ، ج ۹، ص ۶۷۵."}, {"id": 7862, "bookId": 14, "volNo": "1", "hadithNo": 94, "chapter": "حفاظت زبان اور تنہائی وغیرہ", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ صَمَتَ نَجَا‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی ذَرٍّ قَالَ سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ اَلْوَحْدَۃُ خَیْرٌ مِّنْ جَلِیْسِ السُّوْءِ وَالْجَلِیْسُ الصَّالِحُ خَیْرٌ مِّنَ الْوَحْدَۃِوَاِمْلَاءُ الْخَیْرِ خَیْرٌ مِّنَ السّکُوْتِ وَالسُّکُوْتُ خَیْرٌ مِّنْ اِمْلَاءِ الشَّرِّ‘‘۔ \nحدیث 3:\n’’ عَنِ ابْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ سِبَابُ الْمُسْلِمِ فُسُوقٌ‘‘۔ \nحدیث 4:\n’’ عَنْ أَنَسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا مُدِحَ الْفَاسِقُ غَضَبَ الرَّبُّ وَاھْتَزَّ لَہُ الْعَرْشُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عبد اللّٰہ بن عمرو رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص خاموش رہا اس نے نجات پائی ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ابوذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ تنہائی برے ہمنشین سے بہتر ہے اور اچھا ہمنشین بہتر ہے تنہائی سے اور بھلائی کا سکھانا بہتر ہے خاموشی سے ۔ اور خاموشی بہتر ہے برائی کی تعلیم سے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ مسلمان کو گالی دینا فسق و گناہ ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جب فاسق کی تعریف کی جاتی ہے تو اللّٰہ تعالیٰ غضب فرماتا ہے اور فاسق کی تعریف سے عرشِ الہٰی کانپ اٹھتا ہے ۔ (بیہقی)", "roman": "Tarjuma Hadees 1: Hazrat Abdullah bin Amr Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs khamosh raha us ne najaat payi. (Tirmizi) Tarjuma Hadees 2: Hazrat Abu Zar Radiyallahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke tanhai bure hamnasheen se behtar hai aur achha hamnasheen behtar hai tanhai se aur bhalai ka sikhana behtar hai khamoshi se. Aur khamoshi behtar hai burai ki ta'leem se. (Baihaqi, Mishkat) Tarjuma Hadees 3: Hazrat Ibn Mas'ood Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Musalman ko gaali dena fisq-o-gunah hai. (Bukhari, Muslim) Tarjuma Hadees 4: Hazrat Anas Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab Faasiq ki ta'reef ki jaati hai to Allah Ta'ala ghazab farmata hai aur Faasiq ki ta'reef se Arsh-e-Ilahi kaanp uthta hai. (Baihaqi)", "explanation": "¥شرح حدیث 4:\nجب فاسق کی مدح و تعریف کرنے سے عرشِ الہٰی کانپنے لگتا ہے تو بد دین ، بدمذہب کی تعر یف کرنے سے عرش الٰہی کس قدر کانپتا ہوگا۔ ( العیاذ باللّٰہ تعالی )"}, {"id": 7863, "bookId": 14, "volNo": "1", "hadithNo": 95, "chapter": "بغض و حسد", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تُعْرَضُ أَعْمَالُ النَّاسِ فِی کُلِّ جُمُعَۃٍ مَرَّتَیْنِ یَوْمَ الاثْنَیْنِ وَیَوْمَ الْخَمِیسِ فَیُغْفَرُ لِکُلِّ عَبْدٍ مُؤْمِنٍ إِلَّا عَبْدًا بَیْنَہُ وَبَیْنَ أَخِیہِ شَحْنَاءُ فَیُقَالُ اتْرُکُوْا ہَذَیْنِ حَتَّی یَفِیْءَا‘‘۔ \nحدیث 2:\n’’عَنْہُ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَحِلُّ لِمُؤْمِنٍ أَنْ یَہْجُرَ مُؤْمِنًا فَوْقَ ثَلاثٍ فَإِنْ مَرَّتْ بِہِ ثَلاثٌ فَلْیَلْقَہُ فَلْیُسَلِّمْ عَلَیْہِ فَإِنْ رَدَّ عَلَیْہِ السَّلَامَ فَقَدِ اشْتَرَکَا فِی الْأَجْرِ وَإِنْ لَمْ یَرُدَّ عَلَیْہِ فَقَدْ بَاء بِالْإِثْمِ وَخَرَجَ الْمُسَلِّمُ مِنَ الْہِجْرَۃِ‘‘۔\nحدیث 3:\n’’عَنِ الزُّبَیْرِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ دَبَّ إِلَیْکُمْ دَاءُ الْأُمَمِ قَبْلَکُمْ الْحَسَدُ وَالْبَغْضَاءُ ہِیَ الْحَالِقَۃُ لَا أَقُولُ تَحْلِقُ الشَّعَرَ وَلَکِنْ تَحْلِقُ الدِّینَ‘‘۔ \nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِیَّاکُمْ وَالْحَسَدَ فَإِنَّ الْحَسَدَ یَأْکُلُ الْحَسَنَاتِ کَمَا تَأْکُلُ النَّارُ الْحَطَبَ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ بندوں کے اعمال ہر ہفتہ دو مرتبہ پیش کیے جاتے ہیں۔ پیر اور جمعرات کو ، پس ہر بندہ کی مغفرت ہوتی ہے سوا اس بندہ کے جو اپنے کسی مسلمان بھائی سے بغض و کینہ رکھتا ہے اس کے متعلق حکم دیا جاتا ہے کہ ان دونوں کو چھوڑے رہو (یعنی فرشتے ان کے گناہوں کو نہ مٹائیں) یہاں تک کہ وہ آپس کی عداوت سے باز آجائیں۔ (مسلم شریف)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ کسی مسلمان کو جائز نہیں کہ وہ تین دن سے زیادہ کسی مسلمان کو عداوۃً چھوڑ رکھے اگر تین دن گزر جائیں تو اس کو چاہیے کہ اپنے بھائی سے مل کر سلام کرے اگر وہ سلام کا جواب دے دے تو(مصالحت کے )ثواب میں دونوںشریک ہیں اور اگر سلام کا جواب نہ دے تو جواب نہ دینے والا گنہگار ہوا۔ اور سلام کرنے والا ترک ِتعلقات کے گناہ سے بری ہوگیا۔ (ابوداود، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت زبیر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اگلی امتوں کی بیماری تمہاری طرف بھی آگئی وہ بیماری حسد و بغض ہے جو مونڈنے والی ہے ۔ میرا یہ مطلب نہیں کہ وہ بال مونڈتی ہے بلکہ وہ دین کو مونڈتی ہے ۔ (احمد، ترمذی)\n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ حسد سے اپنے آپ کو بچاؤ اس لیے کہ حسد نیکیوں کو اس طرح کھا جاتا ہے جس طرح آگ لکڑی کو ۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke bandon ke a'maal har hafta do martaba pesh kiye jaate hain. Peer aur Jumerat ko, pas har banda ki maghfirat hoti hai siwa us banda ke jo apne kisi Musalman bhai se bughz-o-keena rakhta hai us ke muta'lliq Hukm diya jaata hai ke in donon ko chhoday raho (yani farishtay un ke gunahon ko na mitayen) yahan tak ke woh aapas ki adawat se baaz aajayen. (Muslim Shareef) Tarjuma Hadees 2: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke kisi Musalman ko Jaiz nahi ke woh teen din se zyada kisi Musalman ko adawatan chhod rakhe agar teen din guzar jayen to us ko chahiye ke apne bhai se mil kar Salam kare agar woh Salam ka Jawab de de to (musalahat ke) sawab mein donon shareek hain aur agar Salam ka Jawab na de to Jawab na dene wala gunahgar hua. Aur Salam karne wala tark-e-ta'alluqat ke gunah se bari ho gaya. (Abu Dawood, Mishkat) Tarjuma Hadees 3: Hazrat Zubair Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke agli ummaton ki bimari tumhari taraf bhi aagayi woh bimari hasad-o-bughz hai jo moondne wali hai. Mera yeh matlab nahi ke woh Baal moondti hai balki woh deen ko moondti hai. (Ahmad, Tirmizi) Tarjuma Hadees 4: Hazrat Abu Hurairah Radiyallahu Anhu se riwayat hai ke Nabi-e-Kareem Sallallahu Alayhi wa Sallam ne farmaya ke hasad se apne aap ko bachao is liye ke hasad nekiyon ko is tarah kha jaata hai jis tarah aag lakdi ko. (Abu Dawood)", "explanation": "¥ فائدہ :\n کسی شخص میں کوئی خوبی دیکھ کر یہ آرزو کرنا کہ وہ خوبی اس سے زائل ہو کر میرے پاس آجائے اسے حسد کہتے ہیں۔ حسد کرنا حرام ہے ۔ ([1])\n اور اگر یہ تمنا ہے کہ وہ خوبی مجھ میں بھی ہوجائے تو اسے رشک کہتے ہیں۔ یہ جائز ہے ۔\n------------------\n[1] ’’بہارِ شریعت‘‘، حصہ شانزدہم، (۱۶) ص۱۸۵."}, {"id": 7864, "bookId": 14, "volNo": "1", "hadithNo": 96, "chapter": "الحُبُّ فِی اللّٰہ وَالْبُغْضُ فِی اللّٰہ", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی ذَرٍّ قَالَ خَرَجَ عَلَیْنَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَتَدْرُونَ أَیُّ الْأَعْمَالِ أَحَبُّ إِلَی اللّٰہ تَعَالٰی قَالَ قَاءِلٌ الصَّلَاۃُ وَالزَّکَاۃُ وَقَالَ قَاءِلٌ الْجِہَادُ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ أَحَبَّ الْأَعْمَالِ إِلَی اللّٰہ تَعَالٰی الْحُبُّ فِی اللّٰہ وَالْبُغْضُ فِی اللّٰہ‘‘۔ \nحدیث 2:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لأَبِیْ ذَرٍّ یَا أَبَا ذَرٍّ أَيُّ عُرَی الْإِیْمَانِ أَوْثَقُ؟ قَالَ اللّٰہوَرَسُوْلُہُ أَعْلَمُ قَالَ اَلْمُوَالَاۃُ فِی اللّٰہ وَالْحُبُّ فِی اللّٰہ وَالْبُغْضُ فِی اللّٰہ‘‘۔ (بیہقی)\nحدیث 3:\n’’عَنْ أَبِیْ رَزِیْنَ أَنَّہُ قَالَ لَہُ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَ لَا اَدُلُّکَ عَلَی مِلَاکِ ھَذَا الْأَمْرِ تُصِیْبُ بِہِ خَیْرَ الدُّنْیَا وَالْآخِرَۃِ عَلَیْکَ بِمَجَالِسِ أَھْلِ الذِّکْرِ وَإِذَا خَلَوْتَ فَحَرِّکْ لِسَانَکَ مَاسْتَطَعْتَ بِذِکْرِ اللّٰہ وَاَحِبَّ فِی اللّٰہ وَاَبْغِضْ فِی اللّٰہ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام ہم لوگوں کے پاس تشریف لائے اور فرمایا کہ تم لوگ جانتے ہو کہ خدائے تعالیٰ کے نزدیک کون سا عمل سب سے پسندیدہ ہے ؟ کسی نے کہا نماز اور زکوۃ، کسی نے کہا جہاد ، حضور نے فرمایا اللّٰہ تعالیٰ کے نزدیک سب سے پسندیدہ عمل ’’ الْحُبُّ فِی اللّٰہ وَالْبُغْضُ فِی اللّٰہ ‘‘ہے یعنی خدا ہی کے لیے کسی سے محبت کرنا اور خدا ہی کے لیے کسی سے بیزار رہنا۔ (احمد، ابوداود)\n¥ترجمہ حدیث 2:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا کہ حضور علیہ الصلاۃ والسلام نے ابوذر سے فرمایا کہ اے ابو ذر! ایمان کی کون سی گرہ زیادہ مضبوط ہے ؟ عرض کیا اللّٰہ و رسول کو اس کا بہتر علم ہے ۔ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا اللّٰہ تعالیٰ ہی کے لیے آپس میں دوستی رکھنا اور اللّٰہ ہی کے لیے کسی کو دوست بنانا اور کسی کو دشمن سمجھنا۔ (بیہقی)\n¥ترجمہ حدیث 3:\nحضرت ابور زین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے رو ایت ہے کہ حضور علیہ الصلوۃوالسلام نے ان سے فرمایا کیا میں تجھے دین کی وہ بنیاد نہ بتادوں جس کے ذریعے تو دنیا و آخرت کی بھلائی حاصل کرلے ۔ ( پہلی بات تو یہ ہے کہ) اہلِ ذکر یعنی اللّٰہ والوں کی مجلسوں میں بیٹھنا اپنے لیے لازم کرلے ۔ اور جب تنہائی میسر آئے تو جس قدر ممکن ہوسکے خدائے تعالیٰ کی یاد میں اپنی زبان ہلا اور خدائے تعالیٰ ہی کے لیے دوستی کر اور اسی کے لیے دشمنی کر ۔", "roman": "Tarjuma Hadees 1: Hazrat Abu Zar Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam hum logon ke paas tashreef laye aur farmaya ke tum log jaante ho ke Khuda-e-Ta'ala ke nazdeek kaun sa a'mal sab se pasandeeda hai? Kisi ne kaha Namaz aur Zakat, kisi ne kaha Jihad, Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya Allah Ta'ala ke nazdeek sab se pasandeeda a'mal 'Al-Hubbu fillah wal-bughzu fillah' hai yani Khuda hi ke liye kisi se Mohabbat karna aur Khuda hi ke liye kisi se bezar rehna. (Ahmad, Abu Dawood) Tarjuma Hadees 2: Hazrat Ibn Abbas Radiyallahu Anhum ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne Abu Zar se farmaya ke aye Abu Zar! Imaan ki kaun si girah zyada mazboot hai? Arz kiya Allah-o-Rasool ko is ka behtar Ilm hai. Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya Allah Ta'ala hi ke liye aapas mein dosti rakhna aur Allah hi ke liye kisi ko dost banana aur kisi ko dushman samajhna. (Baihaqi) Tarjuma Hadees 3: Hazrat Abu Razin Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne un se farmaya kya main tujhe deen ki woh bunyad na bata doon jis ke zariye tu duniya-o-aakhirat ki bhalai hasil karle. (Pehli baat to yeh hai ke) Ahl-e-Zikr yani Allah walon ki majlison mein baithna apne liye lazim karle. Aur jab tanhai mayassar aaye to jis qadar mumkin ho sake Khuda-e-Ta'ala ki yaad mein apni zabaan hila aur Khuda-e-Ta'ala hi ke liye dosti kar aur usi ke liye dushmani kar.", "explanation": "¥شرح حدیث 1:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n ’’ ایں جا اشکال می آرند کہ چوں روا باشد کہ حب فی اللّٰہ محبوب تر از صلاۃ وزکوۃ وجہاد باشد وحال آنکہ اینہا افضل اعمال اند علی الاطلاق ۔ جو ابش آنکہ ہر کہ محبت لِوَجْہِ اللّٰہدارد او محبت خواہد داشت انبیاء واولیاء وصالحاں از بندگانِ خدارا ۔ ولابد اتباع واطاعت خواہد کرد ایشاں را وکسیکہ دشمن داشت از برائے خدا دشمن خواہد داشت دشمنان دین را وبذل مجہود خواہد نمود در جہاد وقتال ایشاں ۔ پس دریں جاہمہ طاعات از نماز وزکوۃ وجہاد وجز آں در آمد وچیز ے بدر نہ رفت گویا فرمود اصل ومبنی و مدار اعمال وطاعاتحُبّ لِلَّہِ وَالْبُغْضُ لِلَّہِ است ‘‘۔ ([1])\nیعنی یہاں سوال پیدا ہوتا ہے کہ حُبُّ فی اللّٰہ کا نماز ، زکوۃ اور جہاد سے زیادہ محبوب ہونا کیسے صحیح ہوگا؟ جب کہ یہ چیزیں علی الاطلاق تمام اعمال سے افضل ہیں۔ اس کا جواب یہ ہے کہ جو شخص صرف اللّٰہ تعالیٰ کے لیے محبت کرے گا وہ انبیائے کرام ، اولیائے عظام اور اللّٰہ تعالیٰ کے نیک بندوں سے محبت کرے گا اور ان لوگوں کی پیروی و فرمانبرداری بھی ضرور کرے گا( اس لیے کہ محبت کے لیے اطاعت لازم ہے ) اور جو شخص کہ خدائے تعالیٰ کے لیے دشمنی کرے گا تو دین کے دشمنوں سے یقینا دشمنی کریگا۔ گویا حضور نے فرمایا کہ اعمال و طاعات کا مدار اور جڑ بنیاد حُبُّ لِلَّہِ اور بُغْضُ لِلَّہِ ہے ۔ (اشعۃ اللمعات، جلد چہارم ص ۱۳۸)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الآداب ، الفصل الثالث ، ج ۴، ص ۱۴۹."}, {"id": 7865, "bookId": 14, "volNo": "1", "hadithNo": 97, "chapter": "غصہ اور تکبر", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ بَہْزِ بْنِ حَکِیمٍ عَنْ أَبِیہِ عَنْ جَدِّہِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الْغَضَبَ لَیُفْسِدُ الْإِیْمَانَ کَمَا یُفْسِدُ الصَّبْرُ العَسَلَ‘‘۔ \nحدیث 2:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَیْسَ الشَّدِیدُ بِالصُّرَعَۃِ إِنَّمَا الشَّدِیدُ الَّذِی یَمْلِکُ نَفْسَہُ عِنْدَ الْغَضَبِ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مُوسَی بْنُ عِمْرَانَ عَلَیْہِ السَّلَامُ یَا رَبِّ مَنْ اَعَزُّ عِبَادِکَ عِنْدَکَ؟ قَالَ مَنْ اِذَا قَدَرَ غَفَرَ‘‘۔\nحدیث 4:\n’’عَنِ ابْنِ مَسْعُودٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا یَدْخُلُ الْجَنَّۃَ مَنْ کَانَ فِی قَلْبِہِ مِثْقَالُ ذَرَّۃٍ مِنْ کِبْرٍ فَقَالَ رَجُلٌ إِنَّ الرَّجُلَ یُحِبُّ أَنْ یَکُونَ ثَوْبُہُ حَسَنًا وَنَعْلُہُ حَسَنًا قَالَ إِنَّ اللّٰہ تَعَالَی جَمِیلٌ یُحِبُّ الْجَمَالَ الْکِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ‘‘۔ \nحدیث 5:\n’’ عَنْ عُمَرَ قَالَ وَھُوَ عَلَی الْمِنْبَرِ یَآیُّھَا النَّاسُ تَوَاضَعُوْا فَاِنِّیْ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ مَنْ تَوَاضَعَ لِلَّہِ رَفَعَہُ اللّٰہ فَھُوَ فِیْ نَفْسِہِ صَغِیْرٌ وَفِی أَعْیُنِ النَّاسِ عَظِیْمٌ وَمَنْ تَکَبَّرَ وَضَعَہُ اللّٰہ فَھُوَ فِیْ أَعْیُنِ النّاسِ صَغِیْرٌ وَّفِیْ نَفْسِہِ کَبِیْرٌ حَتَّی لَھُوَ أَھْوَنُ عَلَیْھِمْ مِنْ کَلْبٍ أَوْ خِنْزِیْرٍ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت بہز بن حکیم اپنے باپ سے اور وہ اپنے دادا سے روایت کرتے ہیں کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ غصہ ایمان کو ایسا برباد کردیتا ہے جس طرح ایلو ا شہد کو خراب کردیتا ہے ۔ (بیہقی)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ بہادر وہ نہیں جو پہلوان ہو اور دوسرے کو پچھاڑ دے بلکہ بہادر وہ شخص ہے جو غصہ کے وقت اپنے آپ کو قابو میں رکھے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ حضرت موسیٰ علیہ السلام نے عرض کیا اے میرے پروردگار ! کون بندہ تیرے نزدیک زیادہ عزت والا ہے ؟فرمایا وہ بندہ جو قدرت رکھتے ہوئے معاف کردے ۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 4:\nحضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہاکہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس شخص کے دل میں رائی برابر تکبر ہوگا وہ جنت میں نہیں جائے گا۔ ایک شخص نے عرض کیا ( یارسول اللّٰہ )آدمی اس بات کو پسند کرتا ہے کہ اس کا لباس اچھا ہو اور اس کا جوتا اچھا ہو( کیا یہ بھی تکبر میں داخل ہے ؟) ۔ حضورنے فرمایا خدائے تعالیٰ جمیل ہے اور وہ جمال ( و آرائش ) کو پسند فرماتا ہے اس لیے آرائش و جمال کی خواہش تکبر نہیں ہے اور البتہ تکبر حق کو قبول نہ کرنا اور لوگوں کو حقیر و ذلیل سمجھنا ہے ۔ (مسلم شریف)\n¥ترجمہ حدیث 5:\nحضرت عمر فاروق اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے منبر پر کھڑے ہو کر فرمایااے لوگو! تواضع ( یعنی عاجزی و انکساری) اختیار کرو میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سُنا ہے کہ جو خد اکی رضا حاصل کرنے کے لیے تواضع کرتا ہے خدائے تعالیٰ اسے بلند فرماتا ہے یہاں تک کہ وہ اپنے آپ کو چھوٹا سمجھتا ہے مگر لوگوں کی نظر میں وہ بڑا سمجھا جاتاہے ۔ اورجو گھمنڈ کرتا ہے اللّٰہ تعالیٰ اسے پست کردیتا ہے ۔ یہاں تک کہ وہ لوگوں کی نظروں میں ذلیل و خوار رہتا ہے اور اپنے تئیں اپنے آپ کو بڑا خیال کرتا ہے حالانکہ انجام کار ایک دن وہ لوگوں کی نگاہ میں کتے اور سور سے بھی بدتر ہوجاتا ہے ۔ (بیہقی)", "roman": "Tarjuma Hadees 1: Hazrat Bahz bin Hakeem apne baap se aur woh apne dada se riwayat karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke ghussa imaan ko aisa barbaad kar deta hai jis tarah elwa shehad ko kharab kar deta hai. (Baihaqi). Tarjuma Hadees 2: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke bahadur woh nahi jo pehlwan ho aur dusre ko pachhad de balkay bahadur woh shakhs hai jo ghussay ke waqt apne aap ko qaboo mein rakhay. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Hazrat Musa Alayhis Salam ne arz kiya ae mere parwardigar! Kaun banda tere nazdeek zyada izzat wala hai? Farmaya woh banda jo qudrat rakhte hue maaf kar de. (Baihaqi, Mishkat). Tarjuma Hadees 4: Hazrat Ibn Mas'ood RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis shakhs ke dil mein rai barabar takabbur hoga woh jannat mein nahi jayega. Ek shakhs ne arz kiya (Ya Rasoolullah) aadmi is baat ko pasand karta hai ke uska libaas achha ho aur uska joota achha ho (kya yeh bhi takabbur mein dakhil hai?). Huzoor ne farmaya Allah Ta'ala Jameel hai aur woh jamaal (o aaraish) ko pasand farmata hai is liye aaraish o jamaal ki khwahish takabbur nahi hai aur albatta takabbur haq ko Qubool na karna aur logon ko haqeer o zaleel samajhna hai. (Muslim Shareef). Tarjuma Hadees 5: Hazrat Farooq-e-Azam RadiyAllahu Anhu ne mimbar par kharay ho kar farmaya ae logo! Tawazo (yani aajizi o inkisari) ikhtiyar karo main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna hai ke jo Allah ki raza hasil karne ke liye tawazo karta hai Allah Ta'ala usay buland farmata hai yahan tak ke woh apne aap ko chhota samajhta hai magar logon ki nazar mein woh bada samjha jata hai. Aur jo ghamand karta hai Allah Ta'ala usay past kar deta hai. Yahan tak ke woh logon ki nazron mein zaleel o khwar rehta hai aur apne tayin apne aap ko bada khayal karta hai halankeh anjam-e-kaar ek din woh logon ki nigah mein kuttay aur soor se bhi badtar ho jata hai. (Baihaqi)", "explanation": "*****"}, {"id": 7866, "bookId": 14, "volNo": "1", "hadithNo": 98, "chapter": "ظلم و ستم", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ عُمَرَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ الظُّلْمُ ظُلُمَاتٌ یَوْمَ الْقِیَامَۃِ‘‘۔ (بخاری، مسلم)\nحدیث 2:\n’’ عَنْ أَوْسِ بْنِ شُرَحْبِیلَ أَنَّہُ سَمِعَ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ مَنْ مَشَی مَعْ ظَالِمٍ لِیَقْوِیَہُ وَہُوَ یَعْلَمُ أَنَّہُ ظَالِمٌ فَقَدْ خَرَجَ مِنَ الَْإِسْلَامِ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَتَدْرُونَ مَا الْمُفْلِسُ قَالُوا الْمُفْلِسُ فِینَا مَنْ لَا دِرْہَمَ لَہُ وَلَا مَتَاعَ فَقَالَ إِنَّ الْمُفْلِسَ مِنْ أُمَّتِی مَنْ یَأْتِی یَوْمَ الْقِیَامَۃِ بِصَلَاۃٍ وَصِیَامٍ وَزَکَاۃٍ وَیَأْتِی قَدْ شَتَمَ ہَذَا وَقَذَفَ ہَذَا وَأَکَلَ مَالَ ہَذَا وَسَفَکَ دَمَ ہَذَا وَضَرَبَ ہَذَا فَیُعْطَی ہَذَا مِنْ حَسَنَاتِہِ وَہَذَا مِنْ حَسَنَاتِہِ فَإِنْ فَنِیَتْ حَسَنَاتُہُ قَبْلَ أَنْ یُقْضَی مَا عَلَیْہِ أُخِذَ مِنْ خَطَایَاہُمْ فَطُرِحَتْ عَلَیْہِ ثُمَّ طُرِحَ فِی النَّارِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے فرمایا کہ ظلم قیامت کے دن تاریکیوں کا سبب ہوگا۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت اوس بن شرحبیل سے روایت ہے کہ انہوں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سُنا کہ جو شخص ظالم کو تقویت دینے کے لیے اس کا ساتھ دے یہ جانتے ہوئے کہ وہ ظالم ہے تو وہ اسلام سے خارج ہوجاتا ہے ۔ (بیہقی)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کیا تمہیں معلوم ہے مفلس کون ہے ؟ لوگوں نے عرض کیا ہم میں مفلس وہ شخص ہے جس کے پاس نہ پیسے ہوں نہ سامان ، حضور نے فرمایا میری امت میں دراصل مفلس وہ شخص ہے جو قیامت کے دن نماز، روزہ ، زکوۃ لے کر آئے اس حال میں کہ اس نے کسی کو گالی دی ہو، کسی پر تہمت لگائی ہو، کسی کا مال کھالیا ہو، کسی کا خون بہایا ہو اور کسی کو مارا ہو۔ تو اب انہیں راضی کرنے کے لیے اس شخص کی نیکیاں ان مظلوموں کے درمیان تقسیم کی جائیں گی ۔ پس اس کی نیکیاں ختم ہوجانے کے بعد بھی اگر لوگوں کے حقوق اس پر باقی رہ جائیں گے تو اب حق داروں کے گناہ لاددیئے جائیں گے یہاں تک کہ اسے دوزخ میں پھینک دیا جائے گا۔", "roman": "Tarjuma Hadees 1: Hazrat Ibn Umar RadiyAllahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke zulm qayamat ke din tareekiyon ka sabab hoga. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Aus bin Sharjeel se riwayat hai ke unhon ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke jo shakhs zalim ko taqwiyat dene ke liye uska sath de yeh jante hue ke woh zalim hai to woh Islam se kharij ho jata hai. (Baihaqi). Tarjuma Hadees 3: Hazrat Abu Hurairah RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya kya tumhein maloom hai muflis kaun hai? Logon ne arz kiya hum mein muflis woh shakhs hai jis ke paas na paisay hon na saaman, Huzoor ne farmaya meri ummat mein darasal muflis woh shakhs hai jo qayamat ke din Namaz, Roza, Zakat le kar aaye is haal mein ke us ne kisi ko gaali di ho, kisi par tohmat lagayi ho, kisi ka Maal kha liya ho, kisi ka khoon bahaya ho aur kisi ko mara ho. To ab unhein raazi karne ke liye us shakhs ki nekiyan un mazloomon ke darmiyan taqseem ki jayengi. Pas us ki nekiyan khatam ho jane ke baad bhi agar logon ke huqooq us par baqi reh jayenge to ab haq daron ke gunah lad diye jayenge yahan tak ke usay dozakh mein phenk diya jayega.", "explanation": "¥انتباہ :\n بندوں پر دو قسم کے حقوق عائد ہوتے ہیں حقوق اللّٰہ اور حقوق العباد، ان دونوں کی ادائیگی ضروری ہے لیکن ان میں حقوق العباد بہت اہم ہیں اس لیے کہ خدائے تعالی اپنے فضل و کرم سے اگر چاہے تو اپنے حقوق کو معاف فرمادے لیکن بندوں کے حقوق کو اللّٰہ تعالیٰ ہر گز نہیں معاف فرمائے گا۔ تاوقتیکہ وہ بندے نہ معاف کردیں کہ جن کے حقوق اس پر عائد ہوتے ہیں۔ لہذا حقوق اللّٰہ کے ساتھ حقوق العباد ادا کرنے کی ہر ممکن کوشش کرے ورنہ قیامت کے دن سخت عذاب میں گرفتار ہوگا۔"}, {"id": 7867, "bookId": 14, "volNo": "1", "hadithNo": 99, "chapter": "مال اور اقتدار وغیرہ کی حرص", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ ابْنِ عَبَّاسٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لَوْ کَانَ لابْنِ آدَمَ وَادِیَانِ مِنْ مَالٍ لَابْتَغَی ثَالِثًا وَلاَ یَمْلَأُ جَوْفَ ابْنِ آدَمَ إِلَّا التُّرَابُ‘‘۔ (بخاری، مسلم)\nحدیث 2:\n’’عَنْ کَعْبِ بْنِ مَالِکٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا ذِئْبَانِ جَاءِعَانِ أُرْسِلاَ فِی غَنَمٍ بِأَفْسَدَ لَہَا مِنْ حِرْصِ الْمَرْءِ عَلَی الْمَالِ وَالشَّرَفِ لِدِیْنِہِ‘‘۔ \nحدیث 3:\n’’عَـنْ أَبِی ہُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ لُعِنَ عَبْدُ الدِّیْنَارِ وَلُعِنَ عَبْدُ الدِّرْہَمِ‘‘۔ \nحدیث 4:\n’’ عَنْ أَنَسٍ قَالَ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَہْرَمُ ابْنُ آدَمَ وَیَشِبُّ مِنْہُ اثْنَانِ الْحِرْصُ عَلَی الْمَالِ وَالْحِرْصُ عَلَی الْعُمُرِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرتِ ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم اسے روایت ہے کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ اگر (دنیا دار) آدمی کے پاس مال سے بھرے ہوئے دو جنگل ہوں جب بھی وہ تیسرے جنگل کی آرزوکرے گا اور ایسے (حریص) آدمی کا پیٹ قبر کی مٹی کے سوا اور کوئی چیز نہیں بھر سکتی۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت کعب بن مالک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ دو بھوکے بھیڑیئے جنہیں بکریوں میں چھوڑ دیا جائے وہ اتنا نقصان نہیں پہنچاتے جتنا کہ مال اور مرتبہ کی لالچ انسان کے دین کو نقصان پہنچاتی ہے ۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ درہم و دینار کے بندے پر لعنت کی گئی ہے ۔ (ترمذی)\n¥ترجمہ حدیث 4:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ آدمی بوڑھا ہوتا ہے اور دو باتیں اس کی جوان ہوتی ہیں، مال کا لالچ اور عمر کی زیادتی۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Abbas RadiyAllahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke agar (duniya daar) aadmi ke paas Maal se bhare hue do jangal hon jab bhi woh teesre jangal ki aarzoo karega aur aise (harees) aadmi ka pait Qabr ki mitti ke siwa aur koi cheez nahi bhar sakti. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Ka'ab bin Malik RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke do bhookay bheriye jinhein bakriyon mein chhor diya jaye woh utna nuqsan nahi pahunchate jitna ke Maal aur martaba ki lalach insaan ke deen ko nuqsan pahunchati hai. (Tirmidhi). Tarjuma Hadees 3: Hazrat Abu Hurairah RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke dirham o deenar ke banday par la'nat ki gayi hai. (Tirmidhi). Tarjuma Hadees 4: Hazrat Anas RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke aadmi boodha hota hai aur do baatein us ki jawan hoti hain, Maal ki lalach aur umr ki zyadati. (Bukhari, Muslim)", "explanation": "*****"}, {"id": 7868, "bookId": 14, "volNo": "1", "hadithNo": 100, "chapter": "دُنیا", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ حُذَیْفَۃَ قَالَ قَالَ سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ حُبُّ الدُّنْیَا رَأْسُ کُلِّ خَطِیْءَۃٍ‘‘۔ \nحدیث 2:\n’’عَن أَبِی مُوسَی قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ أَحَبَّ دُنْیَاہُ أَضَرَّ بِآخِرَتِہِ وَمَنْ أَحَبَّ آخِرَتَہُ أَضَرَّ بِدُنْیَاہُ فَآثِرُوا مَا یَبْقَی عَلَی مَا یَفْنی‘‘۔ \nحدیث 3:\n’’عَنْ سَہْلِ بْنِ سَعْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَوْ کَانَتْ الدُّنْیَا تَعْدِلُ عِنْدَ اللّٰہ جَنَاحَ بَعُوضَۃٍ مَا سَقَی کَافِرًا مِنْہَا شَرْبَۃً‘‘۔ (ترمذی)\nحدیث 4:\n’’عَنْ أَبِی ہُرَیْرَۃَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَلاَ إِنَّ الدُّنْیَا مَلْعُونَۃٌ مَلْعُونٌ مَا فِیہَا إِلَّا ذِکْرُ اللّٰہ وَمَا وَالاہُ وَعَالِمٌ أَوْ مُتَعَلِّمٌ‘‘۔ (ترمذی)\nحدیث 5:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الدُّنْیَا سِجْنُ الْمُؤْمِنِ وَجَنَّۃُ الْکَافِرِ‘‘ ۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت حذیفہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے رسولِ کریم علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ دنیا کی محبت ہر بُرائی کی جڑ ہے ۔ (مشکوۃ)\n¥ترجمہ حدیث 2:\nحضرت ابوموسیٰ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص اپنی دُنیا سے محبت کرتا ہے ( ایسی محبت جو اللّٰہ و رسول کی محبت پر غالب ہو) تو وہ اپنی آخرت کو نقصان پہنچاتا ہے اور جو اپنی آخرت سے محبت کرتا ہے وہ اپنی دُنیا کو نقصان پہنچاتا ہے تو ( اے مسلمانو!) فنا ہونے والی چیز( یعنی دُنیا ) کوتج( چھوڑ)کر باقی رہنے والی چیز (یعنی آخرت) کو اختیار کرلو۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت سہل بن سعد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ اگر دُنیا خدائے تعالیٰ کی نظر میں مچھر کے پر برابر بھی وقعت رکھتی تو اس میں سے کافر کو ایک گھونٹ بھی نہ پلاتا۔ \n¥ترجمہ حدیث 4:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ ( کان کھول کر)سُن لو دنیا ملعون ہے اورجو چیزیں اس میں ہیں وہ بھی معلون ہیں۔ مگر ذکرِ الہٰی اور وہ وہ چیزیں جنہیں رب تعالیٰ محبوب رکھتا ہے اور عالم یا متعلم بھی۔ (ترمذی)\n¥ترجمہ حدیث 5:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ دُنیا مومن کا قید خانہ ہے اور کافر کی جنت ہے ۔ (مسلم شریف)", "roman": "Tarjuma Hadees 1: Hazrat Huzaifah RadiyAllahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke duniya ki Mohabbat har burai ki jad hai. (Mishkat). Tarjuma Hadees 2: Hazrat Abu Musa RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs apni duniya se Mohabbat karta hai (aisi Mohabbat jo Allah o Rasool ki Mohabbat par ghalib ho) to woh apni aakhirat ko nuqsan pahunchata hai aur jo apni aakhirat se Mohabbat karta hai woh apni duniya ko nuqsan pahunchata hai to (ae musalmano!) fana hone wali cheez (yani duniya) ko taj (chhor) kar baqi rehne wali cheez (yani aakhirat) ko ikhtiyar kar lo. (Ahmad, Mishkat). Tarjuma Hadees 3: Hazrat Sahl bin Sa'ad RadiyAllahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke agar duniya Allah Ta'ala ki nazar mein machhar ke par barabar bhi waqat rakhti to is mein se Kaafir ko ek ghoont bhi na pilata. Tarjuma Hadees 4: Hazrat Abu Hurairah RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke (kaan khol kar) sun lo duniya mal'oon hai aur jo cheezein is mein hain woh bhi mal'oon hain. Magar zikr-e-Ilahi aur woh cheezein jinhein Rab Ta'ala mehboob rakhta hai aur aalim ya muta'allim bhi. (Tirmidhi). Tarjuma Hadees 5: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke duniya momin ka qaid khana hai aur Kaafir ki jannat hai. (Muslim Shareef)", "explanation": "*****"}, {"id": 7869, "bookId": 14, "volNo": "1", "hadithNo": 101, "chapter": "عمر اور مال کی زیادتی کب نعمت ہے", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ شَدَّادٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَیْسَ أَحَدٌ أَفْضَلَ عِنْدَ اللّٰہ مِنْ مُؤْمِنٍ یُعَمَّرُ فِی الْإِسْلَامِ لِتَسْبِیْحِہِ وَتَکْبِیْرِہِ وَتَہْلِیْلِہِ‘‘۔ \nحدیث 2:\n’’عَنْ أَبِی بَکْرَۃَ أَنَّ رَجُلًا قَالَ یَا رَسُولَ اللّٰہ أَیُّ النَّاسِ خَیْرٌ قَالَ مَنْ طَالَ عُمُرُہُ وَحَسُنَ عَمَلُہُ قَالَ فَأَیُّ النَّاسِ شَرٌّ قَالَ مَنْ طَالَ عُمُرُہُ وَسَاء عَمَلُہُ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی سَعِیدِنِ الْخُدْرِیِّ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ ہَذَا الْمَالَ خَضِرَۃٌ حُلْوَۃٌ فَمَنْ أَخَذَہُ بِحَقِّہِ وَوَضَعَہُ فِی حَقِّہِ فَنِعْمَ الْمَعُونَۃُ‘‘۔ \nحدیث 4:\n’’عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا بَأْسَ بِالْغِنَی لِمَنْ اتَّقَی اللّٰہ عَزَّ وَجَلَّ وَالصِّحَّۃُ لِمَنْ اتَّقَی خَیْرٌ مِنْ الْغِنَی وَطِیبُ النَّفْسِ مِنَ النَّعِیْمِ‘‘۔\nحدیث 5:\n’’عَنْ سُفْیَانَ الثَّوْرِیِّ قَالَ کَانَ الْمَالُ فِیْمَا مَضَی یَکْرَہُ فَأَمَّا الْیَوْمَ فَھُوَ تُرْسُ الْمُؤْمِنِ وَقَالَ لَوْلاَ ھَذِہِ الدَّنَانِیْرُ لَتَمَنْدَلَ بِنَا ہَؤُلَاءِ الْمَلُوْک وَقَالَ مَنْ کَانَ فِیْ یَدِہِ مِنْ ھَذِہِ شَیْئٌ فَلْیُصْلِحْہُ فَإِنَّہُ زَمَانٌ إِنِ احْتَاجَ کَانَ أَوَّلُ مَنْ یَّبْذُلُ دِیْنَہُ وَقَالَ الْحَلَالُ لَا یَحْتَمِلُ السَّرَفَ‘‘۔", "urdu": "¥ترجمہ حدیث 1: \nحضرت ابن شداد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالیٰ کے نزدیک اس مومن سے افضل کوئی نہیں ہے جس نے خدائے تعالیٰ کی تسبیح و تکبیر اور اس کی عبادت و تہلیل کے لیے اسلام میں زیادہ عمر پائی۔ (احمد، مشکوۃ)\n¥ترجمہ حدیث 2: \nحضرت ابوبکرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ ایک شخص نے عرض کیا یارسول اللّٰہ ! کون آدمی بہت اچھا ہے ؟ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ وہ شخص جس کی عمر زیادہ ہو اور عمل اچھے ہوں۔ پھر عرض کیا کہ کون آدمی بہت بُرا ہے ؟ فرمایا وہ شخص جس کی عمر زیادہ ہو اور عمل برے ہوں۔ (ترمذی)\n¥ترجمہ حدیث 3: \nحضرت ابوسعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ (دنیا کا) مال سبز رنگین ترو تازہ اور لذیذ ہے تو جو شخص اس کو جائز طریقے سے حاصل کرے اورجائز مصارف میں صرف کرے تو ایسا مال بہترین مددگار ہے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 4: \nحضور علیہ الصلاۃ والسلام کے ایک صحابی نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ جو شخص اللّٰہ تبارک وتعالیٰ سے ڈرے اس کے لیے مالدار ہونا کوئی حرج نہیں اور پرہیزگار آدمی کے لیے جسمانی تندرستی مالداری سے بہتر ہے اور خوش دلی بھی خدائے تعالیٰ کی نعمتوں میں سے ( ایک عظیم نعمت ) ہے ۔ (مشکوۃ)\n¥ترجمہ حدیث 5: \nحضرت سفیان ثوری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ اگلے زمانہ میں مال کو بُرا سمجھا جاتا تھا لیکن آج کل مال مومن کی ڈھال ہے ۔ اور فرمایا اگر یہ زر و دینار ہمارے پا س نہ ہوتے تو یہ ( ظاہر پرست) بادشاہ ہم لوگوں کو ذلیل و خوار سمجھتے ۔ اور فرمایا کہ جس شخص کے پاس کچھ مال ہو اسے چاہیے کہ اسے ٹھیک سے رکھے ( یعنی اس کے بڑھانے کی تدبیریں کرے ) اس لیے کہ یہ ایسا زمانہ ہے کہ اگر کوئی محتاج ہوجائے گا تو وہی سب سے پہلے اپنے دین کو ( دنیا کے عوض ) بیچ ڈالے گا۔ اور فرمایا کہ حلال مال فضول خرچی میں ضائع نہیں ہوتا۔ (شرح السنۃ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Shaddad RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala ke nazdeek us momin se afzal koi nahi hai jis ne Allah Ta'ala ki tasbeeh o Takbeer aur us ki ibadat o tahleel ke liye Islam mein zyada umr payi. (Ahmad, Mishkat). Tarjuma Hadees 2: Hazrat Abu Bakrah RadiyAllahu Anhu se riwayat hai ke ek shakhs ne arz kiya Ya Rasoolullah! Kaun aadmi bahut achha hai? Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke woh shakhs jis ki umr zyada ho aur amal achhay hon. Phir arz kiya ke kaun aadmi bahut bura hai? Farmaya woh shakhs jis ki umr zyada ho aur amal buray hon. (Tirmidhi). Tarjuma Hadees 3: Hazrat Abu Sa'eed Khudri RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke (duniya ka) Maal sabz rangeen tar o taza aur lazeez hai to jo shakhs is ko Jaiz tareeqay se hasil kare aur Jaiz masarif mein Sarf kare to aisa Maal behtareen madadgar hai. (Bukhari, Muslim). Tarjuma Hadees 4: Rasoolullah Sallallahu Alayhi wa Sallam ke ek Sahabi ne kaha ke Sarkar-e-Aqdas Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs Allah Tabarak wa Ta'ala se daray us ke liye maaldar hona koi haraj nahi aur parhezgar aadmi ke liye jismani tandurusti maaldari se behtar hai aur khush dili bhi Allah Ta'ala ki ne'maton mein se (ek azeem ne'mat) hai. (Mishkat). Tarjuma Hadees 5: Hazrat Sufyan Sawri RadiyAllahu Anhu ne farmaya ke aglay zamana mein Maal ko bura samjha jata tha lekin aaj kal Maal momin ki dhaal hai. Aur farmaya agar yeh zar o deenar hamare paas na hote to yeh (zahir parast) badshah hum logon ko zaleel o khwar samajhte. Aur farmaya ke jis shakhs ke paas kuch Maal ho usay chahiye ke usay theek se rakhay (yani us ke barhane ki tadbeerein kare) is liye ke yeh aisa zamana hai ke agar koi mohtaj ho jayega to wahi sab se pehle apne deen ko (duniya ke ewaz) bech dalega. Aur farmaya ke Halal Maal fazool kharchi mein zaya nahi hota. (Sharh us-Sunnah, Mishkat)", "explanation": "*****"}, {"id": 7870, "bookId": 14, "volNo": "1", "hadithNo": 102, "chapter": "ریاکاری", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ مَحْمُودِ بْنِ لَبِیْدٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ أَخْوَفَ مَا أَخَافُ عَلَیْکُمْ الشِّرْکُ الْأَصْغَرُ قَالُوا یَا رَسُولَ اللّٰہ وَمَا الشِّرْکُ الْأَصْغَرُ قَالَ الرِّیَاء‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو أَنَّہُ سَمِعَ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ مَنْ سَمَّعَ النَّاسَ بِعَمَلِہِ سَمَّعَ اللّٰہ بِہِ اُسَامِعَ( ) خَلْقِہِ وَحَقَّرَہُ وَصَغَّرَہُ‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ الْعَبْدَ إِذَا صَلَّی فِی الْعَلاَنِیَۃِ فَأَحْسَنَ وَصَلَّی فِی السِّرِّ فَأَحْسَنَ قَالَ اللّٰہ تَعَالَی ہَذَا عَبْدِی حَقًّا‘‘۔ \nحدیث 4:\n’’عَنْ شَدَّادِ بْنِ أَوْسٍ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَنْ صَلَّی یُرَاءِی فَقَدْ أَشْرَکَ وَمَنْ صَامَ یُرَاءِی فَقَدْ أَشْرَکَ وَمَنْ تَصَدَّقَ یُرَاءِی فَقَدْ أَشْرَکَ‘‘۔ (احمد، مشکوۃ)", "urdu": "¥ترجمہ حدیث 1:\nحضرت محمود بن لبید رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ تمہارے بارے میں جس چیز سے میں بہت ڈرتا ہوں وہ شرکِ اصغر ہے ۔ صحابہ نے عرض کیا یارسول اللّٰہ ! شرکِ اصغر کیا چیز ہے ؟ فرمایا ریا ( یعنی دکھاوے کے لیے کام کرنا )۔ (احمد)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن عمرو رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ انہوں نے رسولِ کریم علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ جو شخص لوگو ں میں اپنے عمل کا چرچا کر ے گا تو خدائے تعالیٰ اس کی (ریا کاری) کو لوگوںمیں مشہور کردے گا اور اس کو ذلیل و رسوا کرے گا۔ (بیہقی)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ بندہ نے جب علانیہ نماز پڑھی تو خوبی کے ساتھ پڑھی اور جب پوشیدہ طور پر پڑھی تو بھی خوبی کے ساتھ پڑھی تو خدائے تعالی فرماتا ہے کہ میرا یہ بندہ سچا ہے ( یعنی ریا کاری نہیں کرتا)۔ (ابن ماجہ)\n¥ترجمہ حدیث 4:\nحضرت شداد بن اوس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ جس شخص نے دکھاوے کے لیے نماز پڑھی اس نے شرک کیا اور جس شخص نے دکھاوے کے لیے روزہ رکھا تو اس نے شرک کیا اور جس نے دکھاوے کے لیے صدقہ کیا تواس نے شرک کیا۔ (احمد، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Mahmood bin Labeed RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke tumhare bare mein jis cheez se main bahut darta hoon woh Shirk-e-Asghar hai. Sahabah ne arz kiya Ya Rasoolullah! Shirk-e-Asghar kya cheez hai? Farmaya riya (yani dikhawe ke liye kaam karna). (Ahmad). Tarjuma Hadees 2: Hazrat Abdullah bin Amr RadiyAllahu Anhum se riwayat hai ke unhon ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke jo shakhs logon mein apne amal ka charcha karega to Allah Ta'ala us ki (riya kari) ko logon mein mashhoor kar dega aur us ko zaleel o ruswa karega. (Baihaqi). Tarjuma Hadees 3: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke banday ne jab alaniya Namaz parhi to khoobi ke sath parhi aur jab posheeda taur par parhi to bhi khoobi ke sath parhi to Allah Ta'ala farmata hai ke mera yeh banda sacha hai (yani riya kari nahi karta). (Ibn Majah). Tarjuma Hadees 4: Hazrat Shaddad bin Aus RadiyAllahu Anhu ne kaha ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke jis shakhs ne dikhawe ke liye Namaz parhi us ne Shirk kiya aur jis shakhs ne dikhawe ke liye Roza rakha to us ne Shirk kiya aur jis ne dikhawe ke liye Sadaqah kiya to us ne Shirk kiya. (Ahmad, Mishkat)", "explanation": "¥شرح حدیث 4:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث کے تحت فرماتے ہیں کہ:\n’’ ہر عملے کہ بریا کند شرک ست ۔ غایت آنکہ شرک دوقسم جلی ست وخفی ، شرک آشکارا بت پرستی کردن ومرائی کہ برائے غیر خدا عمل سیکند نیز بت پرستی می کند لیکن پنہانی چنانکہ گفتہ اند کُلُّ مَا صَدَّکَ عَنِ اللّٰہ فَھُوَ صَنَمُکَ ‘‘۔ ([1])\nیعنی جو کام دکھاوے کے لیے کرے شرک ہے ۔ خلاصہ یہ کہ شرک کی دو قسمیں ہیں جلی اور خفی بت پرستی کرنا کھلم کھلا شرک ہے ۔ ( یہ شرک جلی ہے ) اور ریا کار جو کہ غیر خدا کے لیے عمل کرتا ہے وہ بھی پوشیدہ طور پر بت پرستی کرتا ہے ( یعنی یہ شرک خفی ہے ) جیسا کہ کہا گیا ہے کہ ہر وہ چیز جو تجھے خدائے تعالیٰ سے روکے وہ تیرا بت ہے ۔ ( اشعۃ اللمعات ، ترجمہ مشکوۃ ، جلد چہارم ، ص ۲۵۰)\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الرقاق ، باب الریا والسمعۃ ، ج ۴، ص ۲۷۲."}, {"id": 7871, "bookId": 14, "volNo": "1", "hadithNo": 103, "chapter": "تصویر سازی", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ أَبِی طَلْحَۃَ قَالَ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تَدْخُلُ الْمَلَاءِکَۃُ بَیْتًا فِیہِ کَلْبٌ وَلَا تَصَاوِیرُ‘‘۔ \nحدیث 2:\n’’عَنْ عَبْدِ اللّٰہ بْنِ مَسْعُودٍ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَشَدُّ النَّاسِ عَذَابًا عِنْدَ اللّٰہ الْمُصَوِّرُونَ‘‘ ۔\nحدیث 3:\n’’عَنِ ابْنِ عَبَّاسٍ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ مَنْ صَوَّرَ صُورَۃً فَإِنَّ اللّٰہ مُعَذِّبُہُ حَتَّی یَنْفُخَ فِیہِ الرُّوحَ وَلَیْسَ بِنَافِخٍ فِیہَا أَبَدًا‘‘۔ (بخاری)\nحدیث 4:\n’’عَنْ عَائِشَۃَ قَالَتْ قَالَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ أُولَءِکَ إِذَا مَاتَ فِیہِمْ الرَّجُلُ الصَّالِحُ بَنَوْا عَلَی قَبْرِہِ مَسْجِدًا ثُمَّ صَوَّرُوا فِیہِ تِلْکَ الصُّوَرَ أُولَءِکَ شِرَارُ خَلْقِ اللّٰہ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابو طلحہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ جس گھر میں کتا یا تصویریں ہوں اس میں رحمت کے فرشتے نہیں آتے ۔ (بخاری، مسلم)\n¥ترجمہ حدیث 2:\nحضرت عبد اللّٰہ بن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے رسولِ کریم علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ خدائے تعالیٰ کے یہاں سب سے زیادہ عذاب ان لوگوں کو دیا جائے گا جو جاندار کی تصویریں بناتے ہیں۔ (بخاری، مسلم)\n¥ترجمہ حدیث 3:\nحضرت ِ ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے فرمایا کہ میں نے رسولِ کریم علیہ الصلاۃ والتسلیم کو فرماتے ہوئے سُنا کہ جو شخص ( جاندار کی) تصویر بنائے گا تو خدائے تعالیٰ بالیقین اسے عذاب دے گا یہاں تک کہ وہ اپنی بنائی ہوئی تصویر میں جان ڈال دے ۔ ا ور یہ حقیقت ہے کہ وہ اس میں کبھی جان نہیں ڈال سکے گا ( اس لیے عذاب کا مستحق ہونا یقینی ہے )۔ (بخاری شریف)\n¥ترجمہ حدیث 4:\nحضرت عائشہ صدیقہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے کہا کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ حبشہ کے لوگوں کا حال یہ ہے کہ جب ان میں کوئی نیک آدمی مرجاتا ہے تو وہ لوگ اس کی قبر پر عبادت خانہ بنالیتے ہیں پھر اس میں ان ( نیک لوگوں کی) تصویر بناتے ہیں یہ لوگ خدائے تعالیٰ کی بدترین مخلوق ہیں۔ (مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Abu Talha RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jis ghar mein kutta ya Tasweer hon us mein rahmat ke farishtay nahi aate. (Bukhari, Muslim). Tarjuma Hadees 2: Hazrat Abdullah bin Mas'ood RadiyAllahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke Allah Ta'ala ke yahan sab se zyada azaab un logon ko diya jayega jo jaandaar ki Tasweer banate hain. (Bukhari, Muslim). Tarjuma Hadees 3: Hazrat Ibn Abbas RadiyAllahu Anhum ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke jo shakhs (jaandaar ki) Tasweer banayega to Allah Ta'ala bil-yaqeen usay azaab dega yahan tak ke woh apni banayi hui Tasweer mein jaan daal de. Aur yeh haqeeqat hai ke woh is mein kabhi jaan nahi daal sakega (is liye azaab ka mustahiq hona yaqeeni hai). (Bukhari Shareef). Tarjuma Hadees 4: Hazrat Aisha Siddiqah RadiyAllahu Anha ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Habsha ke logon ka haal yeh hai ke jab un mein koi nek aadmi mar jata hai to woh log us ki Qabr par ibadat khana bana lete hain phir is mein un (nek logon ki) Tasweer banate hain yeh log Allah Ta'ala ki badtareen makhlooq hain. (Mishkat)", "explanation": "¥ضروری اِنتباہ :\n آج کل بہت سے جاہل گنوار صوفی کہلانے والے اور بزرگان دین سے جھوٹی محبت کا دعویٰ کرنے والے ، حضرت غوث پاک ، حضرت خواجہ غریب نواز، حضرت محبوبِ الہٰی، حضرت صابر کلیری، حضرت کلیم اللّٰہ شاہ جہاں آبادی، حضرت تاج الدین ناگ پوری، حضرت حاجی وارث علی شاہ اور دیگر اولیائے کرام و بزرگانِ دین رَضِیَ اللّٰہ تَعَالٰی عَنْہُم اجمعین کی تصویریں اپنے گھروں اور دوکانوں میں رکھتے ہیں یہ سخت ناجائز اور گناہ ہے اور بعض لوگ بزرگوں کی تصویر کے سامنے با ادب بیٹھ کر ان کا تصور کرتے ہیں یہ بت پرستی کے مشابہ ہے بلکہ اسلام میں بت پرستی کا دروازہ کھولنا ہے تو سخت حرام اور ناجائز ہے ۔"}, {"id": 7872, "bookId": 14, "volNo": "1", "hadithNo": 104, "chapter": "توقف وجلد بازی", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنْ سَہْلِ بْنِ سَعْدِنِ السَّاعِدِیّ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ الْأَنَاۃُ مِنَ اللّٰہ وَالْعَجَلَۃُ مِنَ الشَّیْطَانِ‘‘۔ (ترمذی)\nحدیث 2:\n’’عَنْ أَنَسٍ أَنَّ رَجُلًا قَالَ لِلنَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَوْصِنِی فَقَالَ خُذِ الْأَمْرَ بِالتَّدْبِیْرِ فَإِنْ رَأَیْتَ فِی عَاقِبَتِہِ خَیْرًا فَأَمْضِہِ وَإِنْ خِفْتَ غَیًّا فَأَمْسِکْ‘‘۔ \nحدیث 3:\n’’عَنْ مُصْعَبِ بْنِ سَعْدٍ عَنْ أَبِیہِ قَالَ الْأَعْمَشُ لَا أَعْلَمُہُ إِلَّا عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ التُّؤَدَۃُ فِی کُلِّ شَیْئٍ خَیْرٌ إِلَّا فِی عَمَلِ الْآخِرَۃِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت سہل بن سعد ساعدی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ کاموں میں توقف کرنا یعنی جلد بازی نہ کرنا خدائے تعالیٰ کی جانب سے ہے اور جلد بازی کرنا شیطان کی طرف سے ہے ۔ (ترمذی)\n¥ترجمہ حدیث 2:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ ایک شخص نے نبی کریم علیہ الصلاۃ والسلام سے عرض کیا کہ مجھے نصیحت فرمایئے ، حضور نے فرمایا کہ اپنا کام خوب غور و فکر کے بعد کیا کرو اگر اس کا انجام اچھا نظر آئے تو کر ڈالو اور خرابی کا ڈر ہو تو مت کرو۔ (شرح السنۃ، مشکوۃ)\n¥ترجمہ حدیث 3:\nحضرت مصعب بن سعد اپنے باپ سے روایت کرتے ہیں کہ نبی کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ توقف کرنا ہر چیز میں بہتر ہے لیکن آخرت کے کام میں تاخیر بہتر نہیں۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Sahl bin Sa'ad Sa'idi RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke kaamon mein tawaqquf karna yani jald bazi na karna Allah Ta'ala ki janib se hai aur jald bazi karna shaitan ki taraf se hai. (Tirmidhi). Tarjuma Hadees 2: Hazrat Anas RadiyAllahu Anhu se riwayat hai ke ek shakhs ne Rasoolullah Sallallahu Alayhi wa Sallam se arz kiya ke mujhe nasihat farmayiye, Huzoor ne farmaya ke apna kaam khoob ghaur o fikr ke baad kiya karo agar is ka anjam achha nazar aaye to kar daalo aur kharabi ka dar ho to mat karo. (Sharh us-Sunnah, Mishkat). Tarjuma Hadees 3: Hazrat Mus'ab bin Sa'ad apne baap se riwayat karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke tawaqquf karna har cheez mein behtar hai lekin aakhirat ke kaam mein takheer behtar nahi. (Abu Dawood)", "explanation": "*****"}, {"id": 7873, "bookId": 14, "volNo": "1", "hadithNo": 105, "chapter": "نیکی کا حکم دینا اور برائی سے منع کرنا", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی سَعِیدِنِ الْخُدْرِیِّ عَنْ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ رَأَی مِنْکُمْ مُنْکَرًا فَلْیُغَیِّرْہُ بِیَدِہِ فَإِنْ لَمْ یَسْتَطِعْ فَبِلِسَانِہِ فَإِنْ لَمْ یَسْتَطِعْ فَبِقَلْبِہِ وَذَلِکَ أَضْعَفُ الْإِیمَان‘‘۔ (مسلم)\nحدیث 2:\n’’عَنْ أَبِی بَکْرِنِ الصِّدِّیقِ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ إِنَّ النَّاسَ إِذَا رَأَوْا مُنْکَرًا فَلَمْ یُغَیِّرُوْہُ یُوشِکُ أَنْ یَعُمَّہُمْ اللّٰہ بِعِقَابِہِ‘‘۔\nحدیث 3:\n’’عَنْ الْعُرْسِ بْنِ عَمِیرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِذَا عُمِلَتْ الْخَطِیءَۃُ فِی الْأَرْضِ مَنْ شَہِدَہَا فَکَرِہَہَا کَانَ کَمَنْ غَابَ عَنْہَا وَمَنْ غَابَ عَنْہَا فَرَضِیَہَا کَان کَمَنْ شَہِدَہَا‘‘\nحدیث 4:\n’’ عَنْ جَابِرٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَوْحَی اللّٰہ عَزَّ وَجَلَّ إِلَی جِبْرِیْلَ عَلَیْہِ السَّلَامُ أَنِ اقْلِبْ مَدِیْنَۃ کَذَا وَکَذَا بِأَہْلِہَا فَقَالَ یَا رَبِّ إِنَّ فِیْہِمْ عَبْدَکَ فُلانًا لَمْ یَعْصِکَ طَرْفَۃَ عَیْنٍ قَالَ فَقَالَ اقْلِبْہَا عَلَیْہِ وَعَلَیْہِمْ فَإِنَّ وَجْہَہَ لَمْ یَتَمَعَّرْ فِیّ سَاعَۃً قَطُّ‘‘۔\nحدیث 5:\n’’ عَنْ أَنَسٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ رَأَیْتُ لَیْلَۃَ أُسْرِیَ بِی رِجَالًا تُقْرَضُ شِفَاہُہُمْ بِمَقَارِیضَ مِنْ نَارٍ قُلْتُ مَنْ ہَؤُلَاءِ یَا جِبْرِیلُ؟ قَالَ ہَؤُلَاء خُطَبَاءمِنْ أُمَّتِکَ یَأْمُرُونَ النَّاسَ بِالْبِرِّ وَیَنْسَوْنَ أَنْفُسَہُمْ‘‘۔\nحدیث 6:\n’’ عَنْ أُسَامَۃَ بْنِ زَیْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یُجَاءُ بِالرَّجُلِ یَوْمَ الْقِیَامَۃِ فَیُلْقَی فِی النَّارِ فَتَنْدَلِقُ أَقْتَابُہُ فِی النَّارِ فَیَطْحَنُ فِیہَا کَطَحْنِ الْحِمَارِ بِرَحَاہُ فَیَجْتَمِعُ أَہْلُ النَّارِ عَلَیْہِ فَیَقُولُونَ أَیْ فُلَانُ مَا شَأْنُکَ أَلَیْسَ کُنْتَ تَأْمُرُنَا بِالْمَعْرُوفِ وَتَنْہَانَا عَنِ الْمُنْکَرِ قَالَ کُنْتُ آمُرُکُمْ بِالْمَعْرُوفِ وَلَا آتِیہِ وَأَنْہَاکُمْ عَنِ الْمُنْکَرِ وَآتِیہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوسعید خدری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃوالتسلیم نے فرمایا کہ جو شخص کوئی بات خلافِ شرع دیکھے تو اسے اپنے ہاتھ سے روک دے اور اگر ہاتھ سے روکنے کی قدرت نہ ہو تو زبان سے منع کرے اور اگر زبان سے بھی منع کرنے کی قدرت نہ ہو تو دل سے بُرا جانے اور یہ سب سے کمزور ایمان ہے ۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت ابوبکر صدیق رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سُنا کہ لوگ جب کوئی بات خلافِ شرع دیکھیں اور اس کو نہ مٹائیں تو عنقریب خدائے تعالیٰ ان کو اپنے عذاب میں مبتلا کرے گا۔ (ترمذی، ابن ماجہ)\n¥ترجمہ حدیث 3:\nحضرت عرس بن عمیرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جب کسی جگہ کوئی گناہ کیا جائے تو جو شخص وہاں حاضر ہو مگر اسے وہ ناپسند سمجھتا ہو تو وہ اس آدمی کے مثل ہے جو وہاں موجود نہیں۔ ا ور جو شخص وہاںموجود نہ ہو لیکن اس کو پسند کرتا ہو تو وہ اس آدمی کے مثل ہے جو وہاں موجود ہو۔ (ابوداود)\n¥ترجمہ حدیث 4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالیٰ نے جبریل علیہ السلام کو حکم دیا کہ فلاں شہر کو جو ایسا اور ایسا ہے اس کے باشندوں سمیت الٹ دو۔ جبریل علیہ السلام نے عرض کیا کہ اے میرے پروردگار ! ان باشندوں میں تیرا فلاں بندہ بھی ہے جس نے ایک لمحہ بھی تیری نافرمانی نہیں کی ہے تو خدائے تعالیٰ نے حکم فرمایا کہ مکرر حکم دیتا ہوں کہ اس پر اور کل باشندوں پر شہر کو الٹ دو اس لیے کہ اس کا چہرہ گناہوں کو دیکھ کر میری خوشنودی کے لیے ایک لمحہ بھی متغیر نہیں ہوا۔ (بیہقی، مشکوۃ)\n¥ترجمہ حدیث 5:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ میں نے معراج کی شب میں دیکھا کہ کچھ لوگوں کے ہونٹ آگ کی قینچیوں سے کاٹے جارہے ہیں۔ میں نے پوچھا جبریل یہ کون لوگ ہیں؟ انہوں نے کہا یہ آپ کی امت کے خطیب اور واعظ ہیں جو لوگوں کو نیکی کی ہدایت کرتے تھے اور اپنے آپ کو بھول جاتے تھے یعنی خود نیک کام نہ کرتے تھے ۔ (شرح السنۃ ، مشکوۃ)\n¥ترجمہ حدیث 6:\nحضرت اُسامہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ قیامت کے دن ایک شخص کو لا کر جہنم میں ڈال دیا جائے گا تو اس کی آنتیں فوراً پیٹ سے نکل کر آگ میں گر پڑیں گی پھر وہ انہیں پیسے گا یعنی ان کے گرد چکر کاٹے گا جیسے پن چکی کا گدھا آٹا پیستا ہے ۔ تو دوزخی یہ دیکھ کر اس کے پاس جمع ہوجائیں گے اور اس سے کہیں گے اے فلاں! تیرا کیا حال ہے یعنی یہ تو کیا کررہا ہے ؟ کیا تو ہم کونیک کام کرنے اور برے کام سے باز رہنے کا حکم نہیں دیتا تھا؟ وہ کہے گا ہاں میں تم کو نیک کام کا حکم دیتا تھا اور خود اس کو نہیں کرتا تھا اور برے کام سے تم کو روکتا تھا اور خود اس کو کرتا تھا۔ (بخاری، مسلم)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs koi baat khilaf-e-shara dekhe to use apne haath se rok de aur agar haath se rokne ki qudrat na ho to zabaan se mana kare aur agar zabaan se bhi mana karne ki qudrat na ho to dil se bura jaane aur ye sab se kamzor Imaan hai. (Muslim) Tarjuma Hadees 2: Hazrat Abu Bakr Siddiq RadiyAllahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke log jab koi baat khilaf-e-shara dekhein aur usko na mitayein to anqareeb Allah Ta'ala unko apne azaab mein mubtala karega. (Tirmidhi, Ibn Majah) Tarjuma Hadees 3: Hazrat Urs Bin Umairah RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jab kisi jagah koi gunah kiya jaye to jo shakhs wahan hazir ho magar use woh na-pasand samajhta ho to woh us aadmi ke misl hai jo wahan maujood nahi. Aur jo shakhs wahan maujood na ho lekin usko pasand karta ho to woh us aadmi ke misl hai jo wahan maujood ho. (Abu Dawood) Tarjuma Hadees 4: Hazrat Jabir RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala ne Jibraeel Alayhis Salam ko hukm diya ke falaan shehar ko jo aisa aur aisa hai uske bashindon samet ulat do. Jibraeel Alayhis Salam ne arz kiya ke aye mere Parwardigar! In bashindon mein tera falaan banda bhi hai jisne ek lamha bhi teri nafarmani nahi ki hai to Allah Ta'ala ne hukm farmaya ke mukarrar hukm deta hoon ke us par aur kul bashindon par shehar ko ulat do isliye ke uska chehra gunahon ko dekh kar meri khushnoodi ke liye ek lamha bhi mutaghayyar nahi hua. (Baihaqi, Mishkat) Tarjuma Hadees 5: Hazrat Anas RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke main ne Me'raj ki shab mein dekha ke kuch logon ke hont aag ki qainchiyon se kaate ja rahe hain. Main ne poocha Jibraeel ye kaun log hain? Unhon ne kaha ye aap ki ummat ke khateeb aur wa'iz hain jo logon ko neki ki hidayat karte the aur apne aap ko bhool jaate the yani khud nek kaam na karte the. (Sharh-us-Sunnah, Mishkat) Tarjuma Hadees 6: Hazrat Usamah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Qayamat ke din ek shakhs ko la kar Jahannam mein daal diya jayega to uski aantein foran pait se nikal kar aag mein gir padengi phir woh unhein peesega yani unke gird chakkar kaatega jaise pan-chakki ka gadha aata peesta hai. To dozakhi ye dekh kar uske paas jama ho jayenge aur us se kahenge aye falaan! Tera kya haal hai yani ye to kya kar raha hai? Kya tu hum ko nek kaam karne aur bure kaam se baaz rehne ka hukm nahi deta tha? Woh kahega haan main tum ko nek kaam ka hukm deta tha aur khud usko nahi karta tha aur bure kaam se tum ko rokta tha aur khud usko karta tha. (Bukhari, Muslim)", "explanation": "¥شرح حدیث 6:\nحضرت شیخ عبدالحق محدث دہلوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ اس حدیث شریف کے تحت فرماتے ہیں کہ:\n’’ ازیں جا معلوم شود کہ دیگراں را امر ونہی کردن وخود را بدان عمل نمودن موجب عذاب ست وایں بجہت عمل نہ نمودن ست نہ بجہت امر ونہی کردن کہ اگر ایں راہم نہ کند مستحق ترمی گردد آنرا بہ ترک دو واجب ‘‘۔ ([1])\nیعنی اس حدیث شریف سے معلوم ہوا کہ دوسروں کو امرو نہی کرنا اور خود اس پر عمل نہ کرنا موجب عذاب ہے ۔ لیکن یہ عذاب عمل نہ کرنے کی وجہ سے ہے امرو نہی کی وجہ سے نہیں ہے اس لیے کہ اگر امرو نہی بھی نہیں کرے گا تو دو واجب ترک کرنے کے سبب اور زیادہ مستحق عذاب ہوگا۔ (اشعۃ اللمعات، جلد چہارم ص۱۷۵)\n اور اسی باب الامر بالمعروف کے شروع میں فرماتے ہیں کہ:\n ’’ در وجوب امر بمعروف شرط نیست کہ آمر خود نیز فاعل باشد و بے آن نیز درست ست زیرا کہ امر کردن نفس خود واجب ست وامرکردن غیر واجبے دیگر ۔ اگر یک واجب فوت شود ترک واجب دیگر جائز نہ باشد ، وآنکہ واقع شدہ کہ ’’ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ ‘‘ بر تقدیر تسلیم کہ در ودآں در آمر معروف ونہی منکر باشد مراد زجر ومنع از ناکردن ست نہ ازگفتن ۔ اما شک نیست کہ اگر خود بکند بہتر ست چہ امر ازکسیکہ خود متمثل نیست تاثیرے نہ کند ‘‘۔ ([2])\nیعنی امربالمعروف کے واجب ہونے میں خود آمر کا بھی عامل ہونا شرط نہیں ہے بلکہ بغیر عمل بھی امر بالمعروف جائز ہے اس لیے کہ اپنے آپ کو امر بالمعروف کرنا واجب ہے اور دوسرے کو امر بالمعروف کرنا دوسرا واجب ہے اگر ایک واجب فوت ہوجائے تو دوسرے واجب کا چھوڑنا ہر گز جائز نہ ہوگا اور وہ جو قرآن مجید پارہ ۲۸ میں ’’ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ ‘‘ آیا ہے اگر اسے امربالمعروف اور نہی عن المنکر کے بارے میں تسلیم بھی کرلیا جائے تو عمل نہ کرنے پر زجرو توبیخ مراد ہے نہ کہ کہنے پر ۔ ہاں اس میں شک نہیں ہے کہ اگر خود بھی عمل کرے تو بہتر ہے اس لیے کہ ایسے شخص کا امربالمعروف کرنا اثر نہیں کرتا جو خود بے عمل ہے ۔\n¥انتباہ :\n (۱)…امر بالمعروف کی چند صورتیں ہیں۔ اگر غالب گمان ہو کہ نصیحت کو قبول کرلیں گے اور برائی سے رُک جائیں گے تو ایسی صورت میں نصیحت کرنا واجب ہے خاموش رہنا جائز نہیں۔ اور اگر غالب گمان ہو کہ نصیحت کرنے پر لوگ بُر ابھلا کہیں گے یا مار پیٹ کریں گے جس سے دشمنی اور عداوت پیدا ہوگی تو ان صورتوں میں خاموش رہنا افضل ہے ۔ اور اگر مار پیٹ کو صبر کرلے گا تو مجاہد ہے ایسے شخص کو امر بالمعروف و نہی عن المنکر میں کوئی حرج نہیں اور اگر جانتا ہے کہ نصیحت قبول نہ کریں گے اور مار پیٹ و گالی گلوچ کا اندیشہ بھی نہیں تو نصیحت کرنے نہ کرنے کا اختیار ہے اور بہتر یہ ہے کہ اس صورت میں نصیحت کرے ۔\n جیسا کہ فتاویٰ عالمگیری جلد پنجم ص:۳۰۹میں ہے : ’’ ذَکَرَ الْفَقِیہُ فِی کِتَابِ الْبُسْتَانِ أَنَّ الْأَمْرَ بِالْمَعْرُوفِ عَلَی وُجُوہٍ إنْ کَانَ یَعْلَمُ بِأَکْبَرِ رَأْیِہِ أَنَّہُ لَوْ أَمَرَ بِالْمَعْرُوفِ یَقْبَلُونَ ذَلِکَ مِنْہُ وَیَمْتَنِعُونَ عَنِ الْمُنْکَرِ فَالْأَمْرُ وَاجِبٌ عَلَیْہِ وَلَا یَسَعُہُ تَرْکُہُ وَلَوْ عَلِمَ بِأَکْبَرِ رَأْیِہِ أَنَّہُ لَوْ أَمَرَہُمْ بِذَلِکَ قَذَفُوہُ وَشَتَمُوہُ فَتَرْکُہُ أَفْضَلُ ، وَکَذَلِکَ لَوْ عَلِمَ أَنَّہُمْ یَضْرِبُونَہُ وَلَا یَصْبِرُ عَلَی ذَلِکَ وَیَقَعُ بَیْنَہُمْ عَدَاوَۃٌ وَیَہِیجُ مِنْہُ الْقِتَالُ فَتَرْکُہُ أَفْضَلُ ، وَلَوْ عَلِمَ أَنَّہُمْ لَوْ ضَرَبُوہُ صَبَرَ عَلَی ذَلِکَ وَلَا یَشْکُو إلَی أَحَدٍ فَلَا بَأْسَ بِأَنْ یَنْہَی عَنْ ذَلِکَ وَہُوَ مُجَاہِدٌ وَلَوْ عَلِمَ أَنَّہُمْ لَا یَقْبَلُونَ مِنْہُ وَلَا یَخَافُ مِنْہُ ضَرْبًا وَلَا شَتْمًا فَہُوَ بِالْخِیَارِ وَالْأَمْرُ أَفْضَلُ کَذَا فِی الْمُحِیطِ ‘‘۔ ([3])\n (۲)…برائی دیکھنے والے پرلازم ہے کہ اس سے روکے اگرچہ وہ خود اس برائی میں مبتلا ہو اس لیے کہ شرع نے برائی سے بچنا اور دوسرے کو اس سے روکنا یہ دونوں باتیں لازم کی ہیں۔ تو برائی سے نہ بچنے پر روکنے سے بری الذمہ نہیں ہوگا۔\n جیسا کہ فتاویٰ ہندیہ ، جلد پنجم ص: ۳۰۹میں ہے : ’’ رَجُلٌ رَأَی مُنْکَرًا وَہَذَا الرَّاءِی مِمَّنْ یَرْتَکِبُ ہَذَا الْمُنْکَرَ یَلْزَمُہُ أَنْ یَنْہَی عَنْہُ لِأَنَّ الْوَاجِبَ عَلَیْہِ تَرْکُ الْمُنْکَرِ وَالنَّہْیُ عَنْہُ فَبِتَرْکِ أَحَدِہِمَا لَا یَسْقُطُ عَنْہُ الْآخَرُ کَذَا فِی خِزَانَۃِ الْمُفْتِینَ وَہَکَذَا فِی الْمُلْتَقَطِ وَالْمُحِیطِ ‘‘۔ ([4])\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الآداب ، باب الأمر بالمعروف ، الفصل الأول ، ج ۴، ص ۱۹۱.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب الآداب ، باب الأمر بالمعروف ، ج ۴، ص ۱۸۹.\n[3] ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، الباب السابع عشر فی الغناء إلخ ، ج ۵، ص ۳۵۲.\n[4] ’’ الفتاوی الھندیۃ ‘‘، کتاب الکراھیۃ ، الباب السابع عشر فی الغناء إلخ ، ج ۵، ص ۳۵۳."}, {"id": 7874, "bookId": 14, "volNo": "1", "hadithNo": 106, "chapter": "توکل", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ عَمْرِو بْنِ الْعَاصِ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَنْ تَوَکَّلَ عَلَی اللّٰہ کَفَاہُ ‘‘۔ \nحدیث 2:\n’’ عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ سَمِعْتُ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُولُ لَوْ أَنَّکُمْ تَتَوَکَّلُونَ عَلَی اللّٰہ حَقَّ تَوَکُّلِہِ لَرَزَقَکُمْ کَمَا یَرْزُقُ الطَّیْرَ تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا‘‘۔ \nحدیث 3:\n’’عَنْ أَبِی ذَرٍّ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ الزَّہَادَۃُ فِی الدُّنْیَا لَیْسَتْ بِتَحْرِیمِ الْحَلَالِ وَلَا إِضَاعَۃِ الْمَالِ وَلَکِنَّ الزَّہَادَۃَ فِی الدُّنْیَا أَنْ لَا تَکُونَ بِمَا فِی یَدَیْکَ أَوْثَقَ بِمَا فِی یَدِ اللّٰہ‘‘۔ \nحدیث 4:\n’’ عَنْ صُہَیْبٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَجَبًا لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَہُ کُلَّہُ خَیْرٌ وَلَیْسَ ذَلِکَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ إِنْ أَصَابَتْہُ سَرَّاء شَکَرَ فَکَانَ خَیْرًا لَہُ وَإِنْ أَصَابَتْہُ ضَرَّاءُ صَبَرَ فَکَانَ خَیْرًا لَہُ‘‘۔ \nحدیث 5:\n’’ عَنْ سَعْدٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مِنْ سَعَادَۃِ ابْنِ آدَمَ رِضَاہُ بِمَا قَضَی اللّٰہ لَہُ وَمِنْ شَقَاوَۃِ ابْنِ آدَمَ تَرْکُہُ اسْتِخَارَۃَ اللّٰہ وَمِنْ شَقَاوَۃِ ابْنِ آدَمَ سَخَطُہُ بِمَا قَضَی اللّٰہ لَہُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عمر وبن العاص رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسول کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ جو شخص اللّٰہ تعالیٰ پر توکل کرے اور اپنے تمام کاموں کو خدائے تعالیٰ کے سپرد کردے تو اللّٰہ تعالیٰ اس کے لیے کافی ہے ۔ (ابن ماجہ)\n¥ترجمہ حدیث 2:\nحضرت فاروقِ اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے حضور علیہ الصلاۃ والسلام کو فرماتے ہوئے سنا کہ اگر تم لوگ خدائے تعالیٰ پر توکل کرلو جیسا کہ توکل کا حق ہے تو وہ تم کو اس طرح روزی دے گا جس طرح پرندوں کو روزی دیتا ہے کہ وہ صبح کو بھوکے نکلتے ہیں اور شام کو شکم سیر ہو کر واپس لوٹتے ہیں۔ (ترمذی)\n¥ترجمہ حدیث 3:\nحضرت ابوذر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ حلال کو اپنے اوپر حرام کرلینے اور مال کو ضائع کردینے کا نام ترک ِدنیا نہیں ہے بلکہ دنیا سے بے رغبتی یہ ہے کہ جو کچھ (مال و دولت) تیرے ہاتھوں میں ہے اس پر بھروسہ نہ کر بلکہ اس پر بھروسہ کر جو خدائے تعالیٰ کی دست ِقدرت میں ہے ۔ (ترمذی)\n¥ترجمہ حدیث 4:\nحضرت صہیب رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ مومن کا معاملہ عجیب ہے کہ اس کے ہر کام میں بھلائی ہے اور یہ شرف مومن کے سوا کسی اور کو حاصل نہیں ہے اگر اسے خوشی کا موقع نصیب ہو اور اس پر خدا تعالیٰ کا شکر بجا لائے تو اس میں اس کے لیے بہتری ہے اور اگر کبھی مصیبت پہنچے اور وہ اس پر صبر کرے تو اس میں بھی اس کے لیے بہتری ہے ۔ (مسلم)\n¥ترجمہ حدیث 5:\nحضرت سعد رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ آدمی کی نیک بختی یہ ہے کہ جو کچھ اللّٰہ تعالیٰ نے اس کے لیے مقدر کردیا ہے اس پر راضی رہے ۔ اور آدمی کی بدبختی یہ ہے کہ وہ خدائے تعالیٰ سے بھلائی مانگنا چھوڑ دے ۔ اور آدمی کی بدبختی یہ بھی ہے کہ خدائے تعالیٰ نے (اس کے بارے میں) جو کچھ مقدر فرمادیا ہے وہ اس پر آزردہ ہو۔ (احمد، ترمذی)", "roman": "Tarjuma Hadees 1: Hazrat Amr Bin Al-Aas RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs Allah Ta'ala par tawakkul kare aur apne tamam kaamon ko Allah Ta'ala ke supurd kar de to Allah Ta'ala uske liye kaafi hai. (Ibn Majah) Tarjuma Hadees 2: Hazrat Farooq-e-Azam RadiyAllahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna ke agar tum log Allah Ta'ala par tawakkul kar lo jaisa ke tawakkul ka haq hai to woh tum ko is tarah rozi dega jis tarah parindon ko rozi deta hai ke woh subah ko bhooke nikalte hain aur shaam ko shikam-seer ho kar wapas laut-te hain. (Tirmidhi) Tarjuma Hadees 3: Hazrat Abu Zar RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Halal ko apne upar Haram kar lene aur Maal ko zaya kar dene ka naam tark-e-duniya nahi hai balki duniya se be-raghbati ye hai ke jo kuch (Maal-o-Daulat) tere hathon mein hai us par bharosa na kar balki us par bharosa kar jo Allah Ta'ala ki dast-e-qudrat mein hai. (Tirmidhi) Tarjuma Hadees 4: Hazrat Suhaib RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Momin ka mamla ajeeb hai ke uske har kaam mein bhalai hai aur ye sharaf Momin ke siwa kisi aur ko hasil nahi hai agar use khushi ka mauqa naseeb ho aur us par Allah Ta'ala ka shukr baja laye to us mein uske liye behtari hai aur agar kabhi museebat pahunche aur woh us par sabr kare to us mein bhi uske liye behtari hai. (Muslim) Tarjuma Hadees 5: Hazrat Sa'ad RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke aadmi ki nek-bakhti ye hai ke jo kuch Allah Ta'ala ne uske liye muqaddar kar diya hai us par raazi rahe. Aur aadmi ki bad-bakhti ye hai ke woh Allah Ta'ala se bhalai maangna chhod de. Aur aadmi ki bad-bakhti ye bhi hai ke Allah Ta'ala ne (uske baare mein) jo kuch muqaddar farma diya hai woh us par aazurda ho. (Ahmad, Tirmidhi)", "explanation": "*****"}, {"id": 7875, "bookId": 14, "volNo": "1", "hadithNo": 107, "chapter": "نرمی، حیا اور حسن خلق", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ عَائِشَۃَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ اللّٰہ رَفِیقٌ یُحِبُّ الرِّفْقَ‘‘۔ \nحدیث 2:\n’’عَنْ جَرِیرٍ عَنِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ مَنْ یُحْرَم الرِّفْقَ یُحْرَم الْخَیْرَ‘‘۔ \nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اَلْحَیَاء مِنَ الْإِیمَانِ وَالْإِیمَانُ فِی الْجَنَّۃِ وَالْبَذَاء مِنَ الْجَفَاء وَالْجَفَاءفِی النَّارِ‘‘۔ \nحدیث 4:\n’’ عَنْ عِمْرَانَ بْنِ حُصَیْنٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْحَیَاءُ خَیْرٌ کُلُّہُ‘‘۔ \nحدیث 5:\n’’ عَنِ ابْنِ عُمَرَ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ إِنَّ الْحَیَاءَ وَالْإِیْمَانَ قَرَنَاءجَمِیْعًا فَإِذَا رُفِعَ أَحْدُہُمَا رُفِعَ الْآخَرُ‘‘۔ \nحدیث 6:\n’’ عَنْ مَالِکٍ بَلَغَہُ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ بُعِثْتُ لِأُتَمِّمَ حُسْنَ الْأَخْلَاقِ‘‘۔ (مؤطا، مشکوۃ)\nحدیث 7:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَکْمَلُ الْمُؤْمِنِینَ إِیمَانًا أَحْسَنُہُمْ خُلُقًا‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت عائشہ صدیقہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا سے روایت ہے حضور علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالیٰ مہربان ہے اور مہربانی کو پسند فرماتا ہے ۔ (مسلم )\n¥ترجمہ حدیث 2:\nحضرت جریر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ نبی کریم علیہ الصلاۃ والسلام نے فرمایا کہ جو شخص نرمی سے محروم کیا جاتا ہے ، وہ ( دوسرے لفظوں میں ) بھلائی سے محروم کیا جاتا ہے ۔ (مسلم)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ شرم و حیا ایمان کا حصہ ہے اور ایمان والا جنت میں جائے گا اور بے حیائی و فحش گوئی برائی کا حصہ ہے اور برائی والا دوزخ میں جائے گا۔ (احمد، ترمذی)\n¥ترجمہ حدیث 4:\nحضرت عمران بن حصین رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ حیا کی ساری قسمیں بہتر ہیں۔ (بخاری، مسلم)\n¥ترجمہ حدیث 5:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ نبی کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ ایمان اور حیا دونوں ایک دوسرے کے ساتھی ہیں تو جب ان میں سے ایک اٹھالیا جاتا ہے تو دوسرا بھی اٹھالیا جاتا ہے ۔ (بیہقی)\n¥ترجمہ حدیث 6:\nحضرت مالک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کر یم علیہ الصلاۃ والتسلیم نے فرمایا کہ میں حسنِ اخلاق کے (قدروں) کی تکمیل کے لیے بھیجا گیا ہوں۔ \n¥ترجمہ حدیث 7:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ مسلمانوں میں کامل الایمان وہ لوگ ہیں جن کے اخلاق اچھے ہیں۔ (ابوداود)", "roman": "Tarjuma Hadees 1: Hazrat Aisha Siddiqah RadiyAllahu Anha se riwayat hai, Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala meharban hai aur meharbani ko pasand farmata hai. (Muslim) Tarjuma Hadees 2: Hazrat Jareer RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke jo shakhs narmi se mehroom kiya jaata hai, woh (dusre lafzon mein) bhalai se mehroom kiya jaata hai. (Muslim) Tarjuma Hadees 3: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Haya Imaan ka hissa hai aur Imaan wala Jannat mein jayega aur be-hayai-o-fuhsh goi burai ka hissa hai aur burai wala Dozakh mein jayega. (Ahmad, Tirmidhi) Tarjuma Hadees 4: Hazrat Imran Bin Hussain RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Haya ki saari qismein behtar hain. (Bukhari, Muslim) Tarjuma Hadees 5: Hazrat Ibn Umar RadiyAllahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Imaan aur Haya dono ek dusre ke saathi hain to jab in mein se ek utha liya jaata hai to dusra bhi utha liya jaata hai. (Baihaqi) Tarjuma Hadees 6: Hazrat Malik RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke main Hasan-e-Akhlaq ki takmeel ke liye bheja gaya hoon. Tarjuma Hadees 7: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Musalmanon mein kaamil-ul-Imaan woh log hain jin ke akhlaq achhe hain. (Abu Dawood)", "explanation": "*****"}, {"id": 7876, "bookId": 14, "volNo": "1", "hadithNo": 108, "chapter": "ہنسنا اور مسکرانا", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تُکْثِرِ الضَّحِکَ فَإِنَّ کَثْرَۃَ الضَّحِکِ تُمِیتُ الْقَلْبَ‘‘۔ \nحدیث 2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ أَبُو الْقَاسِم صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَالَّذِی نَفْسِی بِیَدِہِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَکَیْتُمْ کَثِیرًا وَلَضَحِکْتُمْ قَلِیلًا‘‘۔ \nحدیث 3:\n’’ عَنْ عَائِشَۃَ قَالَتْ مَا رَأَیْتُ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مُسْتَجْمِعًا ضَاحِکًا حَتَّی أَرَی مِنْہُ لَہَوَاتِہِ إِنَّمَا کَانَ یَتَبَسَّمُ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم عَلَیْہِ الصَّلَاۃُ وَ التَّسْلِیْم نے فرمایا کہ زیادہ نہ ہنسو اس لیے کہ زیادہ ہنسنا دل کو مردہ بنادیتا ہے ۔ (احمد، ترمذی)\n¥ترجمہ حدیث 2:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ ابوالقاسم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ قسم ہے اس ذات کی جس کے قبضۂ قدرت میں میری جان ہے اگر تم لوگ ان حقیقتوں کو جان لو جنہیں میں جانتا ہوں تو تم بہت زیادہ رؤو اور کم ہنسو۔ (بخاری شریف)\n¥ترجمہ حدیث 3:\nحضرت عائشہ صدیقہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ا نے فرمایا کہ میں نے نبی کریم علیہ الصلاۃ والتسلیم کو ایسا کھل کر ہنستے ہوئے کبھی نہیں دیکھا کہ ان کا تالو نظر آجائے آپ صرف تبسم فرمایا کرتے تھے ۔ (بخاری)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke zyada na hanso isliye ke zyada hansna dil ko murda bana deta hai. (Ahmad, Tirmidhi) Tarjuma Hadees 2: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Abul Qasim Sallallahu Alayhi wa Sallam ne farmaya ke qasam hai us zaat ki jis ke qabza-e-qudrat mein meri jaan hai agar tum log un haqeeqaton ko jaan lo jinhein main jaanta hoon to tum bahut zyada ro'o aur kam hanso. (Bukhari Sharif) Tarjuma Hadees 3: Hazrat Aisha Siddiqah RadiyAllahu Anha ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko aisa khul kar hanste hue kabhi nahi dekha ke unka taalu nazar aa jaye, aap sirf tabassum farmaya karte the. (Bukhari)", "explanation": "*****"}, {"id": 7877, "bookId": 14, "volNo": "1", "hadithNo": 109, "chapter": "فضائل سید المرسلین علیہ الصلاۃ والسلام", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ ثَوْبَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَا خَاتَمُ النَّبِیِّینَ لَا نَبِیَّ بَعْدِی‘‘۔ (ابوداود، ترمذی، مشکوۃ ص ۴۶۵)\nحدیث 2:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ خُتِمَ بِیَ الرُّسُلُ‘‘۔ (بخاری، مسلم، مشکوۃ ص۵۱۱)\nحدیث 3:\n’’ عَنِ الْعِرْبَاضِ بْنِ سَارِیَۃَ عَنْ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَّہُ قَالَ إِنِّی عِنْدَ اللّٰہ مَکْتُوْبٌ خَاتَمُ النَّبِیِّیْنَ وَإِنَّ آدَمَ لَمُنْجَدِلٌ فِی طِیْنِہِ‘‘۔ \nحدیث 4:\n’’ عَنْ أَبِی ہُرَیْرَۃَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ بَیْنَا أَنَا نَاءِمٌ رَأَیْتُنِیْ أُتِیتُ بِمَفَاتِیحِ خَزَاءِنِ الْأَرْضِ فَوُضِعَتْ فِی یَدَیَّ‘‘۔ \nحدیث 5:\n’’ عَنْ عَلِیٍّ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أُعْطِیتُ مَا لَمْ یُعْطَ أَحَدٌ مِنَ الْأَنْبِیَاءِ قَبْلِیْ نُصِرْتُ بِالرُّعْبِ وَأُعْطِیتُ مَفَاتِیحَ الْأَرْض‘‘۔ (احمد، الأمن والعلی ص۵۷)\nحدیث 6:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَا سَیِّدُ وَلَدِ آدَمَ یَوْمَ الْقِیَامَۃِ وَأَوَّلُ مَنْ یَنْشَقُّ عَنْہُ الْقَبْرُ وَأَوَّلُ شَافِعٍ وَأَوَّلُ مُشَفَّعٍ‘‘۔\nحدیث 7:\n’’ عَنْ جَابِرٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أَنَا أَوَّلُ شَافِعٍ وَمُشَفَّع وَلا فَخْرَ‘‘۔\nحدیث 8:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنَا أَکْرَمُ الأَوَّلِینَ وَالآخِرِینَ عَلَی اللّٰہ وَلاَ فَخْرَ‘‘۔\nحدیث 9:\n’’ عَنْ جَابِرِ بْنِ سَمُرَۃَ قَالَ رَأَیْتُ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی لَیْلَۃِ إِضْحِیَانٍ فَجَعَلْتُ أَنْظُرُ إِلَی رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَإِلَی الْقَمَرِ وَعَلَیْہِ حُلَّۃٌ حَمْرَاءُ فَإِذَا ہُوَ أَحْسَنُ عِنْدِی مِنْ الْقَمَرِ‘‘۔\nحدیث 10:\n’’ عَنْ أَنَسٍ قَالَ کَانَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَزْہَرَ اللَّوْنِ کَأَنَّ عَرَقَہُ اللُّؤْلُؤُ وَمَا مَسِسْتُ دِیبَاجَۃً وَلَا حَرِیْرًَا أَلْیَنَ مِنْ کَفِّ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَلَا شَمِمْتُ مِسْکاً وَلَا عَنْبَرَۃً أَطْیَبَ مِنْ رَاءِحَۃِ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ‘‘۔\nحدیث 11:\n’’ عَنْ جَابِرٍ أَنَّ النَّبِیَّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَمْ یَسْلُکْ طَرِیقاً فَیَتْبَعُہُ أَحَدٌ إِلاَّ عَرَفَ أَنَّہُ قَدْ سَلَکَہُ مِنْ طِیبِ عَرْقِہِ أَوْ قَالَ مِنْ رِیحِ عَرَقِہٖ‘‘۔", "urdu": "¥ترجمہ حدیث 1: \nحضرت ثوبان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے کہ انہوں نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ میں خاتم النبیین ہوں میرے بعد کوئی نبی نہیں ہوگا۔ \n¥ترجمہ حدیث 2: \nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ رسولوں کا سلسلہ مجھ پر ختم کردیا گیا۔ \n¥ترجمہ حدیث 3: \nحضرت عرباض بن ساریہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے وہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم سے روایت کرتے ہیں کہ حضور نے فرمایا کہ میں خدائے تعالیٰ کے تئیں اس وقت خاتم النبیین لکھا گیا جب کہ حضرت آدم علیہ السلام اپنی گندھی ہوئی مٹی میں تھے ( یعنی ان کا پتلا اس وقت تک تیار نہیں ہوا تھا)۔ (شرح السنۃ، مشکوۃ ص۵۱۳)\n¥ترجمہ حدیث 4: \nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ اس درمیان میں کہ سورہا تھا میں نے دیکھا کہ زمین کے خزانوں کی کنجیاں لائی گئیں اور میرے دونوں ہاتھوں میں رکھ دی گئیں۔ (بخاری، مسلم ، مشکوۃ ص۵۱۲)\n¥ترجمہ حدیث 5: \nحضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ مجھے وہ عطا ہوا جو مجھ سے پہلے کسی نبی کو نہ عطا ہوا تھا رعب سے میری مدد فرمائی گئی اور مجھے ساری زمین کی کنجیاں عطا ہوئیں۔ \n¥ترجمہ حدیث 6: \nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ میں قیامت کے دن اولاد آدم علیہ السلام کا سردار ہوں گا اور میں سب سے پہلے قبر سے اُٹھوں گا اور سب سے پہلے میں ہی شفاعت کروں گا اور سب سے پہلے میری ہی شفاعت قبول کی جائے گی۔ \n¥ترجمہ حدیث 7: \nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے فرمایا کہ میں سب سے پہلے شفاعت کروں گا اور میری شفاعت سب سے پہلے قبول کی جائے گی اور مجھے اس پر فخر نہیں۔ (دارمی، مشکوۃ ص ۵۱۴)\n¥ترجمہ حدیث 8: \nحضرت ابنِ عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نے کہا رسولِ کریم علیہ الصلاۃ والسلام نے فرمایا کہ خدائے تعالیٰ کے تئیں میں اولین و آخرین میں سب سے زیادہ عزت و بزرگی والا ہوں۔ (ترمذی، دارمی، مشکوۃ ص۵۱۴)\n¥ترجمہ حدیث 9: \nحضرت جابر بن سمرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ میں نے سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو چاندنی رات میں دیکھا تو کبھی میں حضور کی طرف دیکھتا تھا اور کبھی چاند کی طرف ، حضور اس وقت سُرخ لباس پہنے ہوئے تھے تو (آخر میں نے فیصلہ کیا کہ) وہ چاند سے بڑھ کر حسین ہیں۔ (ترمذی، دارمی، مشکوۃ ص ۵۱۷)\n¥ترجمہ حدیث 10: \nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کا رنگ روشن اور چمک دار تھا اور حضور کا پسینہ گویا موتی تھا۔ اور کسی دیباج وریشم کے کپڑے کو میں نے حضور کی مُبارک ہتھیلیوں سے نرم نہیں پایا۔ اور میں نے کوئی ایسا مشک وعنبر نہیں سونگھا جس کی خوشبو حضور کے جسم مبارک کی خوشبو سے بڑھ کر ہو۔ (بخاری، مسلم، مشکوۃ ص۵۱۶)\n¥ترجمہ حدیث 11: \nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے ر وایت ہے کہ نبی کریم علیہ الصلاۃ والسلام جب کسی راستہ سے گزرتے پھر حضور کے بعد جو بھی اس راستہ سے گزرتا تو حضور کے پسینہ کی خوشبو محسوس کرلیتا کہ حضور ادھر سے تشریف لے گئے ہیں۔ (دارمی، مشکوۃ ص ۵۱۷)", "roman": "Tarjuma Hadees 1: Hazrat Thauban RadiyAllahu Anhu se marwi hai ke unhon ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke main Khatam-un-Nabiyyeen hoon mere baad koi Nabi nahi hoga. Tarjuma Hadees 2: Hazrat Abu Hurairah RadiyAllahu Anhu se riwayat hai unhon ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Rasoolon ka silsila mujh par khatam kar diya gaya. Tarjuma Hadees 3: Hazrat Irbaad Bin Sariyah RadiyAllahu Anhu se marwi hai woh Rasoolullah Sallallahu Alayhi wa Sallam se riwayat karte hain ke Huzoor ne farmaya ke main Allah Ta'ala ke tayin us waqt Khatam-un-Nabiyyeen likha gaya jab ke Hazrat Adam Alayhis Salam apni gandhi hui mitti mein the (yani unka putla us waqt tak tayyar nahi hua tha). (Sharh-us-Sunnah, Mishkat) Tarjuma Hadees 4: Hazrat Abu Hurairah RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke is darmiyan mein ke so raha tha main ne dekha ke Zameen ke khazanon ki kunjiyan layi gayin aur mere dono hathon mein rakh di gayin. (Bukhari, Muslim, Mishkat) Tarjuma Hadees 5: Hazrat Ali RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke mujhe woh ata hua jo mujh se pehle kisi Nabi ko na ata hua tha, ra'ab se meri madad farmayi gayi aur mujhe saari Zameen ki kunjiyan ata huin. Tarjuma Hadees 6: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke main Qayamat ke din Aulaad-e-Adam Alayhis Salam ka sardar hoon ga aur main sab se pehle Qabr se uthunga aur sab se pehle main hi Shafa'at karunga aur sab se pehle meri hi Shafa'at qubool ki jayegi. Tarjuma Hadees 7: Hazrat Jabir RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke main sab se pehle Shafa'at karunga aur meri Shafa'at sab se pehle qubool ki jayegi aur mujhe is par fakhr nahi. (Darimi, Mishkat) Tarjuma Hadees 8: Hazrat Ibn Abbas RadiyAllahu Anhum ne kaha Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke Allah Ta'ala ke tayin main awwaleen-o-akhireen mein sab se zyada izzat-o-buzurgi wala hoon. (Tirmidhi, Darimi, Mishkat) Tarjuma Hadees 9: Hazrat Jabir Bin Samurah RadiyAllahu Anhu ne farmaya ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko chandni raat mein dekha to kabhi main Huzoor ki taraf dekhta tha aur kabhi chand ki taraf, Huzoor us waqt surkh Libaas pehne hue the to (aakhir main ne faisla kiya ke) woh chand se badh kar haseen hain. (Tirmidhi, Darimi, Mishkat) Tarjuma Hadees 10: Hazrat Anas RadiyAllahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ka rang roshan aur chamak-dar tha aur Huzoor ka paseena goya moti tha. Aur kisi deebaj-o-resham ke kapde ko main ne Huzoor ki mubarak hatheliyon se narm nahi paya. Aur main ne koi aisa mushk-o-ambar nahi soongha jis ki khushboo Huzoor ke jism-e-mubarak ki khushboo se badh kar ho. (Bukhari, Muslim, Mishkat) Tarjuma Hadees 11: Hazrat Jabir RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam jab kisi raasta se guzarte phir Huzoor ke baad jo bhi us raasta se guzarta to Huzoor ke paseena ki khushboo mehsoos kar leta ke Huzoor idhar se tashreef le gaye hain. (Darimi, Mishkat)", "explanation": "¥انتباہ([1]):\n (۱)…حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کا چہرئہ اقدس ایسا روشن و تابناک تھا کہ بقول راویانِ حدیث آپ کے چہرے میں چاند و سورج تیرتے تھے جس نے بحالت ِ ایمان ایک بار چہرہ دیکھ لیا وہ صحابی ہوگیا جو نبوت کے بعد سب سے بڑا درجہ ہے ۔\n (۲)…سرِ مُبارک بڑا اور بزرگ تھا جس سے سطوت و عظمت ٹپکتی تھی اور جو خشیت الہٰی سے ہر وقت جھکا رہتا تھا۔\n (۳)… قد مُبارک نہ زیادہ لانبا تھا اور نہ زیادہ کوتاہ۔ مگر انسانوں کے مجمع میں کھڑے ہوتے تو سب سے اونچے نظر آتے ۔\n (۴)…جسم پاک نورانی تھا اس لیے اس کا سایہ نہ سورج کی روشنی میں پڑ تا تھا اور نہ چاندنی میں ۔ جسم پر مکھی کبھی نہیں بیٹھی۔\n (۵)…موئے مبارک کچھ بل کھائے ہوئے تھے جو اکثر کندھے تک لٹکتے رہتے تھے اور جب کبھی چہرہ انور پر بکھر جاتے تو ’’ وَالضُّحَی وَاللَّیْلِ إِذَا سَجَی ‘‘کی تفسیر بن جاتے ۔\n (۶)…داڑھی شریف گھنی تھی اور چہرۂ انور اس کے گھیرے میں ایسا معلوم ہوتا تھا جیسے آبنوسی رحل پرقرآن مجید رکھا ہو۔ ناک سڈول اور پتلی قدرے اٹھی ہوئی جو اچانک دیکھنے پر شعلہ نور معلوم ہوتی تھی۔\n (۷)…سینہ مبارک کشادہ تھا جس میں ناف تک بالوں کی ایک ہلکی تحریر تھی۔ شکم مبارک کی سطح سینہ کے برابر تھی جسے چار بار فرشتوں نے چاک کرکے علم و حکمت کا نور بھرا تھا۔ اسی کی شان میں اَلَمْ نَشْرَحْ کی آیت اتری۔\n (۸)… گردن شریف نہایت لطیف و شفاف تھی بقول حضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ چاندی کی ڈھلی ہوئی تھی۔\n (۹)…پیشانی کشادہ اور صبحِ ازل کی طرح روشن تھی جسے لوگ چاند کا ٹکڑا کہتے تھے جو راتوں کو خدائے تعالیٰ کے حضور میں سجدہ ریز رہا کرتی تھی۔\n (۱۰)… گوش مبارک نہایت موزوں اور سبک، دورو نزدیک سے یکساں سنتے تھے ۔ وحوش و طیور کی بول چال اور شجر وحجر کی زبانِ حال سے باخبر۔\n (۱۱)…دندانِ مبارک موتیوں سے زیادہ چمک دار جن سے مسکراتے وقت روشنی پھوٹ پڑتی تھی اور درو دیوار چمک اُٹھتے تھے ۔\nٍ (۱۲)…پشت مبارک ہموار اور سفید و شفاف تھی جیسے چاندی کی ڈھلی ہوئی جس پر شانوں( کندھوں) کے بیچ میں کبوتر کے انڈے کے برابر اُبھری ہوئی مہرِ نبوت تھی۔\n (۱۳-۱۴)…آنکھیں سیاہ و سرمگیں اور پلکیں بڑی تھیں۔ جو ہر وقت غیب کا مشاہدہ کرتی تھیں اور آگے پیچھے یکساں دیکھتی تھیں۔ ساری کائنات میں صرف اِنہی آنکھوں نے خدائے پاک کو بے حجاب دیکھا تھا۔\n (۱۵)…دست ِمبارک کشادہ اور پر گوشت تھاجو مصافحہ کرتا اس کا ہاتھ معطر ہوجاتا انہی ہاتھوں کو خدائے تعالیٰ نے اپنا ہاتھ فرمایا تھا۔\n (۱۶)…انگلیاں لمبی اور بخشش و عطا کے لیے پھیلی ہوئی رہتی تھیں۔ جن کے بیچ سے ضرورت کے وقت پانی کا چشمہ اُبلنے لگتا تھا۔ اورجن کے اشارہ سے چاند کا سینہ شق ہوا اور ڈوبا ہواسورج پلٹ آیا۔\n (۱۷)…پنڈلیاں ہموار اور شیشہ کی طرح لطیف و شفاف تھیں۔\n (۱۸)… کلائیاں قدرے لمبی اور گداز ، رنگ نکھرا ہوا صاف وشفاف تھا۔\n (۱۹)…ابرو محرابِ حرم کی طرح کماندار تھے جن سے مقام قاب قوسین کا راز آشکار ا تھا۔\n (۲۰)…لب مبارک گلِ قدس کی پتیوں کی طرح پتلے پتلے اور گلاب کی پنکھڑیوں سے زیادہ نرم و نازک جن کی جنبش پر کارکنانِ قضا وقدر ہر وقت کان لگائے رہتے تھے ۔\n (۲۱)…آواز انتہائی دلکش وشیریں کہ دشمنوں کو بھی پیار آجائے اور اتنی بلند کہ فاران سے گونجے تو ساری دنیا میں پھیل جائے ۔ رحمت وکرم کے موقع پر گل ولالہ کے جگر کی ٹھنڈک اور کبھی غیرت ِحق کو جلال آجائے تو پہاڑوں کے کلیجے دہل جائیں۔\n (۲۲)…گریہ مبارک سسکتی ہوئی دبی دبی آواز خشیت الہی کے غلبہ سے سیہ کار اُمت کے غم میں رقت انگیز آیتیں پڑھ کر اور شبینہ دعاؤں میں بھیگی بھیگی پلکوں پر آنسوؤں کے جھلکتے ہوئے موتی۔\n (۲۳)…ہنسی انتہائی مسرت و شادمانی کے موقع پر لبوں پر صرف ایک ہلکا سا تبسم پھیل جاتا نور کی ایک کرن پھوٹتی اور درو دیوار وشن ہوجاتے ۔ اسی ر وشنی میں ایک بار حضرت عائشہ صدیقہ رَضِیَ اللّٰہ تَعَالٰی عَنْہا نے اپنی سوئی تلاش کرلی تھی۔\n (۲۴)…پسینہ مبارک انتہائی خوشبودار اور عطر انگیز تھا جدھر سے گزر جاتے فضا معطر ہوجاتی۔ بغل شریف کے پسینہ سے ایک دلہن معطر کی گئی تو پشت در پشت اس کی اولاد میں خوشبو کا اثر تھا۔\n (۲۵)…لعابِ دہن زخمیوں اور بیماروں کے لیے مرہم شفا تھا۔ کھاری کنویں اس کی برکت سے شیریں ہوجاتے ، شیر خوار بچے کے منہ میں پڑ جاتا تو دن بھر ماں کے دودھ کے بغیر آسودہ رہتے ۔ ([2]) (ماخوذ از مدارج النبوۃ، شمائل ترمذی، نسیم الریاض، خصائص کبری، جواھر البحار)\nالغرض ان کے ہر موپہ دائم درود\nان کی ہر خوو خصلت پہ لاکھوں سلام (اعلی حضرت بریلوی)\n------------------\n[1] از صحیفۂ جمال مرتبہ حضرت علامہ ارشد القادری صاحب مدظلہ العالی فاتح جمشیدپور۔ \n[2] ’’ مدارج النبوۃ ‘‘ مترجم ، باب در بیان حسن خلقت جمال إلخ ، ج ۱، ص ۱۵، ’’ نسیم الریاض ‘‘، القسم الأول فی تعظیم العلی الأعلی إلخ ، ص ۵۰۹ ، ’’ الخصائص الکبری ‘‘، باب جامع فی صفۃ خلقہ صلی اللّٰہ علیہ وسلم ، ج ۱، ص ۱۲۲، ’’ جواہر البحار ‘‘ مترجم ، باب فطری محاسن واخلاقی کمالات ، ص ۶۹."}, {"id": 7878, "bookId": 14, "volNo": "1", "hadithNo": 110, "chapter": "حضور کے مثل کوئی نہیں", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ نَہَی رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ عَنْ الْوِصَالِ فِی الصَّوْمِ فَقَالَ لَہُ رَجُلٌ إِنَّکَ تُوَاصِلُ یَا رَسُولَ اللّٰہ قَالَ وَأَیُّکُمْ مِثْلِی إِنِّی أَبِیتُ یُطْعِمُنِی رَبِّی وَیَسْقِینِی‘‘۔\nحدیث 2:\n’’ عَنِ ابْنِ عُمَرَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَاصَلَ فِی رَمَضَانَ فَوَاصَلَ النَّاسُ فَنَہَاہُمْ قِیلَ لَہُ أَنْتَ تُوَاصِلُ قَالَ إِنِّی لَسْتُ مِثْلَکُمْ إِنِّی أُطْعَمُ وَأُسْقَی‘‘۔\nحدیث 3:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ قَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ لَا تُوَاصِلُوا قَالُوا إِنَّکَ تُوَاصِلُ قَالَ إِنِّی لَسْتُ مِثْلَکُمْ إِنِّی أَبِیتُ یُطْعِمُنِی رَبِّی وَیَسْقِینِی‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے انہوں نے فرمایا کہ سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے رات دن پے درپے روزہ رکھنے سے منع فرمایا تو ایک شخص نے حضور ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) سے عرض کیا یارسول اللّٰہ ! آپ تو رات دن پے درپے روزہ رکھتے ہیں۔ حضور نے فرمایا کہ میرے مثل تم میں کون ہے بے شک میں اس حال میں رات گزارتا ہوں کہ میرا پروردگار مجھے کھلاتا پلاتا ہے ۔ (بخاری ج۱ ص ۲۶۳، مسلم ص ۳۵۲، مشکوۃ ص ۱۷۵)\n¥ترجمہ حدیث 2:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے ماہِ رمضان میں رات دن پے درپے روزہ رکھا تو لوگوں نے بھی رات دن پے درپے روزہ رکھا تو حضور نے لوگوں کو ایسا کرنے سے منع فرمایا عرض کیا گیا حضور تو رات دن پے درپے روزہ رکھتے ہیں۔ سرکار نے فرمایا کہ میں تمہارے مثل نہیں ہوں میں کھلایا اور پلایا جاتا ہوں۔ (مسلم ، ج۱ ص ۳۵۱)\n¥ترجمہ حدیث 3:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ نبی کریم علیہ الصلاۃ والسلام نے (صحابہ سے )فرمایا کہ تم لوگ رات دن پے درپے روزہ مت رکھو۔ صحابہ نے عرض کیا حضور تو رات دن پے درپے روزہ رکھتے ہیں۔ سرکار نے فرمایا کہ میں تمہارے مثل ہر گز نہیں ہوں ۔ بے شک میں اس حال میں رات گزارتا ہوں کہ میرا رب مجھے کھلاتا اور پلاتا ہے ۔ (بخاری، ج۲ ص ۱۰۸۴)", "roman": "Tarjuma Hadees 1: Hazrat Abu Hurairah RadiyAllahu Anhu se marwi hai unhon ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ne raat din pe-dar-pe Roza rakhne se mana farmaya to ek shakhs ne Huzoor se arz kiya Ya Rasoolullah! Aap to raat din pe-dar-pe Roza rakhte hain. Huzoor ne farmaya ke mere misl tum mein kaun hai beshak main is haal mein raat guzarta hoon ke mera Parwardigar mujhe khilata pilata hai. (Bukhari, Muslim, Mishkat) Tarjuma Hadees 2: Hazrat Ibn Umar RadiyAllahu Anhum se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne maah-e-Ramzan mein raat din pe-dar-pe Roza rakha to logon ne bhi raat din pe-dar-pe Roza rakha to Huzoor ne logon ko aisa karne se mana farmaya arz kiya gaya Huzoor to raat din pe-dar-pe Roza rakhte hain. Sarkar ne farmaya ke main tumhare misl nahi hoon main khilaya aur pilaya jaata hoon. (Muslim) Tarjuma Hadees 3: Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Sallallahu Alayhi wa Sallam ne (Sahabah se) farmaya ke tum log raat din pe-dar-pe Roza mat rakho. Sahabah ne arz kiya Huzoor to raat din pe-dar-pe Roza rakhte hain. Sarkar ne farmaya ke main tumhare misl har-giz nahi hoon. Beshak main is haal mein raat guzarta hoon ke mera Rabb mujhe khilata aur pilata hai. (Bukhari)", "explanation": "¥شرح حدیث 1:\nحضرت امام نووی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں:\n ’’ قَوْلُہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنِّی أَبِیْتُ یُطْعِمُنِی رَبِّی وَیَسْقِینِی مَعْنَاہُ یَجْعَلُ اللّٰہ تَعَالَی فِیَّ قُوَّۃَ الطَّاعِم وَالشَّارِبِ ‘‘۔ ([1])\n یعنی حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے قول ’’ إِنِّی أَبِیْتُ یُطْعِمُنِی رَبِّی وَیَسْقِینِی ‘‘ کا مطلب یہ ہے کہ خدائے تعالیٰ مجھے وہ طاقت دیتا ہے جو اوروں کو کھا پی کر حاصل ہوتی ہے ۔ (نووی مع مسلم ج۱ ص۳۵۱)\n------------------\n[1] ’’ شرح صحیح مسلم ‘‘ للنووی ، کتاب الصیام ، باب النھی عن الوصال فی الصوم ، ج ۴، ص ۲۱۲.\n¥انتباہ:\nحضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو اپنے مثل بشر نہیں کہنا چاہیے اس لیے کہ انبیائے سابقین علیہم الصلوۃ والتسلیم کو ان کے زمانے کے کفار اپنے مثل بشر کہا کرتے تھے جیسا کہ پارہ ۱۲ ، رکوع ۳ میں ہے ۔ فَقَالَ الْمَلَأُ الَّذِینَ کَفَرُوا مِنْ قَوْمِہِ مَا نَرَاکَ إِلَّا بَشَرًا مِثْلَنَا یعنی حضرت نوح علیہ السلام کی قوم کے کافروں نے کہا کہ ہم تمہیں اپنے ہی مثل بشر سمجھتے ہیں اور پارہ ۱۳ ، رکوع ۱۴ میں ہے قَالُوا إِنْ أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا یعنی کافروں نے حضرت موسی علیہ السلام سے کہا کہ تم ہمارے ہی مثل بشر ہو، اور پارہ ۱۹ ، رکوع ۱۲میں ہے مَا أَنْتَ إِلَّا بَشَرٌ مِثْلُنَا یعنی کافروںنے حضرت صالح علیہ السلام سے کہا کہ تم ہمارے ہی مثل بشر ہو۔ اور پارہ ۱۹ ، رکوع ۱۴ میں ہے مَا أَنْتَ إِلَّا بَشَرٌ مِثْلُنَا یعنی کافروں نے حضرت شعیب علیہ السلام سے کہا کہ تم ہمارے ہی مثل بشر ہو۔ اِن آیات کریمہ سے معلوم ہوا کہ انبیائے کرام علیہم السلام کو ازراہِ توہین اپنے مثل بشر کہنا کافروں کا شیوہ ہے ۔"}, {"id": 7879, "bookId": 14, "volNo": "1", "hadithNo": 111, "chapter": "معراج", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَنَسِ بْنِ مَالِکٍ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ أُتِیتُ بِالْبُرَاقِ (وَہُوَ دَابَّۃٌ أَبْیَضُ طَوِیلٌ فَوْقَ الْحِمَارِ وَدُونَ الْبَغْلِ یَضَعُ حَافِرَہُ عِنْدَ مُنْتَہَی طَرْفِہِ) قَالَ فَرَکِبْتُہُ حَتَّی أَتَیْتُ بَیْتَ الْمَقْدِسِ قَالَ فَرَبَطْتُہُ بِالْحَلْقَۃِ الَّتِی یَرْبِطُ بِہِ الْأَنْبِیَاء قَالَ ثُمَّ دَخَلْتُ الْمَسْجِدَ فَصَلَّیْتُ فِیہِ رَکْعَتَیْنِ ثُمَّ خَرَجْتُ فَجَاء نِی جِبْرِیلُ عَلَیْہِ السَّلَام بِإِنَائٍ مِنْ خَمْرٍ وَإِنَائٍ مِنْ لَبَنٍ فَاخْتَرْتُ اللَّبَنَ فَقَالَ جِبْرِیلُ اخْتَرْتَ الْفِطْرَۃَ ثُمَّ عَرَجَ بِنَا إِلَی السَّمَاءِ فَاسْتَفْتَحَ جِبْرِیلُ فَقِیلَ مَنْ أَنْتَ؟ قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ؟ قَالَ مُحَمَّدٌ قِیلَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِآدَمَ فَرَحَّبَ بِی وَدَعَا لِی بِخَیْرٍ ثُمَّ عَرَجَ بِنَا إِلَی السَّمَاءِ الثَّانِیَۃِ فَاسْتَفْتَحَ جِبْرِیلُ عَلَیْہِ السَّلَام فَقِیلَ مَنْ أَنْتَ؟ قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ؟ قَالَ مُحَمَّدٌ قِیلَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِابْنَیْ الْخَالَۃِ عِیسَی ابْنِ مَرْیَمَ وَیَحْیَی بْنِ زَکَرِیَّا صَلَوَاتُ اللّٰہ عَلَیْہِمَا فَرَحَّبَا وَدَعَوَا لِی بِخَیْرٍ ثُمَّ عَرَجَ بِی إِلَی السَّمَاء الثَّالِثَۃِ فَاسْتَفْتَحَ جِبْرِیلُ فَقِیلَ مَنْ أَنْتَ؟ قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ قَالَ مُحَمَّدٌ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قِیلَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِیُوسُفَ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا ہُوَ قَدْ أُعْطِیَ شَطْرَ الْحُسْنِ فَرَحَّبَ وَدَعَا لِی بِخَیْرٍ ثُمَّ عَرَجَ بِنَا إِلَی السَّمَاء الرَّابِعَۃِ فَاسْتَفْتَحَ جِبْرِیلُ عَلَیْہِ السَّلَام قِیلَ مَنْ ہَذَا قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ قَالَ مُحَمَّدٌ قَالَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِإِدْرِیسَ فَرَحَّبَ وَدَعَا لِی بِخَیْرٍ قَالَ اللّٰہ عَزَّ وَجَلَّ {وَرَفَعْنَاہُ مَکَانًا عَلِیًّا} ثُمَّ عَرَجَ بِنَا إِلَی السَّمَاءِ الْخَامِسَۃِ فَاسْتَفْتَحَ جِبْرِیلُ قِیلَ مَنْ ہَذَا؟ قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ؟ قَالَ مُحَمَّدٌ قِیلَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِہَارُونَ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَرَحَّبَ وَدَعَا لِی بِخَیْرٍ ثُمَّ عَرَجَ بِنَا إِلَی السَّمَاءِ السَّادِسَۃِ فَاسْتَفْتَحَ جِبْرِیلُ عَلَیْہِ السَّلَام قِیلَ مَنْ ہَذَا قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ؟ قَالَ مُحَمَّدٌ قِیلَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِمُوسَی صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَرَحَّبَ وَدَعَا لِی بِخَیْرٍ ثُمَّ عَرَجَ إِلَی السَّمَاء السَّابِعَۃِ فَاسْتَفْتَحَ جِبْرِیلُ فَقِیلَ مَنْ ہَذَا؟ قَالَ جِبْرِیلُ قِیلَ وَمَنْ مَعَکَ؟ قَالَ مُحَمَّدٌ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قِیلَ وَقَدْ بُعِثَ إِلَیْہِ قَالَ قَدْ بُعِثَ إِلَیْہِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِإِبْرَاہِیمَ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مُسْنِدًا ظَہْرَہُ إِلَی الْبَیْتِ الْمَعْمُورِ وَإِذَا ہُوَ یَدْخُلُہُ کُلَّ یَوْمٍ سَبْعُونَ أَلْفَ مَلَکٍ لَا یَعُودُونَ إِلَیْہِ ثُمَّ ذَہَبَ بِی إِلَی السِّدْرَۃِ الْمُنْتَہَی وَإِذَا وَرَقُہَا کَآذَانِ الْفِیَلَۃِ وَإِذَا ثَمَرُہَا کَالْقِلَالِ قَالَ فَلَمَّا غَشِیَہَا مِنْ أَمْرِ اللّٰہ مَا غَشِیَ تَغَیَّرَتْ فَمَا أَحَدٌ مِنْ خَلْقِ اللّٰہ یَسْتَطِیعُ أَنْ یَنْعَتَہَا مِنْ حُسْنِہَا فَأَوْحَی اللّٰہ إِلَیَّ مَا أَوْحَی فَفَرَضَ عَلَیَّ خَمْسِینَ صَلَاۃً فِی کُلِّ یَوْمٍ وَلَیْلَۃٍ فَنَزَلْتُ إِلَی مُوسَی صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقَالَ مَا فَرَضَ رَبُّکَ عَلَی أُمَّتِکَ قُلْتُ خَمْسِینَ صَلَاۃً قَالَ ارْجِعْ إِلَی رَبِّکَ فَاسْأَلْہُ التَّخْفِیفَ فَإِنَّ أُمَّتَکَ لَا یُطِیقُونَ ذَلِکَ فَإِنِّی قَدْ بَلَوْتُ بَنِی إِسْرَاءِیلَ وَخَبَرْتُہُمْ قَالَ فَرَجَعْتُ إِلَی رَبِّی فَقُلْتُ یَا رَبِّ خَفِّفْ عَلَی أُمَّتِی فَحَطَّ عَنِّی خَمْسًا فَرَجَعْتُ إِلَی مُوسَی فَقُلْتُ حَطَّ عَنِّی خَمْسًا قَالَ إِنَّ أُمَّتَکَ لَا یُطِیقُونَ ذَلِکَ فَارْجِعْ إِلَی رَبِّکَ فَاسْأَلْہُ التَّخْفِیفَ قَالَ فَلَمْ أَزَلْ أَرْجِعُ بَیْنَ رَبِّی تَبَارَکَ وَتَعَالَی وَبَیْنَ مُوسَی عَلَیْہِ السَّلَام حَتَّی قَالَ یَا مُحَمَّدُ إِنَّہُنَّ خَمْسُ صَلَوَاتٍ کُلَّ یَوْمٍ وَلَیْلَۃٍ لِکُلِّ صَلَاۃٍعَشْرٌ فَذَلِکَ خَمْسُونَ صَلَاۃً وَمَنْ ہَمَّ بِحَسَنَۃٍ فَلَمْ یَعْمَلْہَا کُتِبَتْ لَہُ حَسَنَۃً فَإِنْ عَمِلَہَا کُتِبَتْ لَہُ عَشْرًا وَمَنْ ہَمَّ بِسَیِّءَۃٍ فَلَمْ یَعْمَلْہَا لَمْ تُکْتَبْ شَیْءًا فَإِنْ عَمِلَہَا کُتِبَتْ سَیِّءَۃً وَاحِدَۃً قَالَ فَنَزَلْتُ حَتَّی انْتَہَیْتُ إِلَی مُوسَی صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَأَخْبَرْتُہُ فَقَالَ ارْجِعْ إِلَی رَبِّکَ فَاسْأَلْہُ التَّخْفِیفَ فَقَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَقُلْتُ قَدْ رَجَعْتُ إِلَی رَبِّی حَتَّی اسْتَحْیَیْتُ مِنْہ‘‘ ۔\nحدیث 2:\n’’ عَنْ جَابِرٍ أَنَّہُ سَمِعَ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقُوْلُ لَمَّا کَذَّبَنِی قُرَیْشٌ قُمْتُ فِی الْحِجْرِ فَجَلَّی اللّٰہ لِی بَیْتَ الْمَقْدِسِ فَطَفِقْتُ أُخْبِرُہُمْ عَنْ آیَاتِہِ وَأَنَا أَنْظُرُ إِلَیْہِ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس بن مالک رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ میرے پاس ایک براق لایا گیا یہ ایک سفید رنگ کا جانور تھا جس کا قد گدھے سے اونچا اور خچر سے نیچا تھا اس کا قدم اس مقام پر پڑتا تھا جہاں تک نگاہ پہنچتی ہے ۔ حضور نے فرمایا تو میں اس پر سوار ہوا یہاںتک کہ بیت المقدس میں آیا حضور نے فرمایا تو میں نے براق کو اس حلقہ سے باندھ دیا جس سے انبیائے کرام علیہم السلام اپنی سواریوں کو باندھا کرتے تھے ، حضور نے فرمایا پھر میں مسجد میں داخل ہوا اور دو رکعت نماز پڑھی پھر باہر نکلا تو جبریل میرے پاس ایک پیالہ شراب کا اور ایک پیالہ دودھ کا لائے ، میں نے دودھ کا پیالہ لے لیا۔ جبریل نے کہا کہ آپ نے فطرت (اسلام) کو اختیار کرلیا۔ پھر جبریل مجھ کو آسمان کی طرف لے چلے ۔ جبریل نے (آسمان کا دروازہ ) کھولنے کے لیے کہا تو پوچھا گیا آپ کون ہیں؟ فرمایا میں جبریل ہوں۔ پھر پوچھا گیا آپ کے ساتھ کون ہے ؟ انہوں نے کہا سرکار ِ مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم )ہیں، پھر پوچھاگیاان کو بلایا گیا ہے فرمایا (ہاں) بلایا گیا ہے ۔ پھر آسمان کا دروازہ ہمارے لیے کھول دیا گیا تو میں نے آدم علیہ السلام کو دیکھا انہوں نے مجھے مرحبا کہا اور میرے لیے دعائے خیر فرمائی۔ پھر جبریل مجھے دوسرے آسمان کی طرف لے چلے ۔ انہوں نے (آسمان کا دروازہ) کھولنے کے لیے کہا تو پوچھا گیا آپ کون ہیں۔ فرمایا میں جبریل ہوں۔ پھر پوچھا گیا اور آپ کے ساتھ کون ہے ؟ فرمایا سرکار ِ مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم )ہیں، پھر پوچھا گیا ان کو بلایا گیا ہے ؟ فرمایا (ہاں) بلایا گیا ہے ، حضور نے فرمایا پھر آسمان کا دروازہ ہمارے لیے کھول دیا گیا تو میں نے دو خالہ زاد بھائیوں یعنی عیسی بن مریم اور یحیی بن زکریا علیہما الصلاۃ والسلام کو دیکھا تو انہوں نے مجھے مرحبا کہا اور میرے لیے دُعائے خیر فرمائی۔ پھر جبریل مجھے تیسرے آسمان کی طرف لے چلے ۔ انہوں نے (آسمان کا دروازہ) کھولنے کے لیے کہا تو پوچھا گیا آپ کون ہیں؟ فرمایا میں جبریل ہوں، پھر پوچھا گیا اورآپ کے ساتھ کون ہے ؟ کہا سرکار ِ مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ )، پھر پوچھا گیا ان کو بلایا گیا ہے ؟ فرمایا (ہاں) بلایا گیا ہے پھر آسمان کا دروازہ ہمارے لیے کھول دیا گیا وہاں مجھ کو یوسف علیہ السلام نظر آئے جنہیں ( سارے جہاںکا)آدھا حسن عطا فرمایا گیا ہے انہوں نے مجھے مرحبا کہا اور میرے لیے دعائے خیر فرمائی۔ پھر جبریل مجھے چوتھے آسمان کی طرف لے چلے تو جبریل علیہ السلام نے ( آسمان کا دروازہ) کھولنے کے لیے کہا۔ پوچھا گیا یہ کون ہے ؟ فرمایا میں جبریل ہوں کہا گیا اور آپ کے ساتھ کون ہے ۔ فرمایا سرکار مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) ہیں پھر پوچھا گیا ان کو بلایا گیا ہے ؟ فرمایا ( ہاں) بلایا گیا ہے تو آسمان کا دروازہ ہمارے لیے کھول دیا گیا تو میں نے ادریس علیہ الصلاۃ والسلام کو دیکھا تو انہوں نے مرحبا کہا اور میرے لیے دعائے خیر فرمائی۔ جن کے بارے میں خدائے تعالیٰ نے فرمایا کہ اور ہم نے اسے بلند مکان پر اٹھالیا۔ پھر جبریل مجھے پانچویں آسمان کی طر ف لے چلے تو انہوں نے ( آسمان کا دروازہ) کھولنے کے لیے فرمایا تو پوچھا گیا یہ کون ہے ۔ ؟ فرمایا میں جبریل ہوں۔ پھر پوچھا گیا اور آپ کے ساتھ کون ہے ؟ فرمایا سرکارِ مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) ہیں پھر کہا گیا ان کو بلایا گیا ہے ؟ فرمایا (ہاں) بلایا گیا ہے تو ہمارے لیے آسمان کا دروازہ کھول دیا گیا تو اچانک مجھ کو ہارون علیہ الصلاۃ والسلام نظر آئے انہوں نے مرحبا کہا اور میرے لیے دعائے خیر فرمائی ۔ پھر جبریل ہم کو چھٹے آسمان کی طرف لے چلے انہوں نے آسمان کا دروزاہ کھولنے کے لیے کہا پوچھا گیا یہ کون ہے ؟۔ فرمایا میں جبریل ہوں پھر پوچھا گیا اور آپ کے ساتھ کون ہے ؟ فرمایا سرکارِ مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) ہیں پھر کہا گیا اور ان کو بلایا گیا ہے ؟ فرمایا (ہاں)بلایاگیاہے تو آسمان کا دروازہ ہمارے لیے کھول دیا گیا تو میں نے موسی علیہ السلام کو دیکھا انہوں نے مرحبا فرمایا اور میرے لیے دعائے خیر کی۔ پھر جبریل ہمیںساتویں آسمان کی طرف لے چلے تو انہوں نے ( آسمان کا دروازہ) کھولنے کے لیے کہا تو پوچھا گیا یہ کون ہے ؟ فرمایا میں جبریل ہوں پھر پوچھا گیا اور آپ کے ساتھ کون ہے ؟ فرمایا سرکار ِ مصطفے ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) ہیں پھر پوچھا گیا اور ان کو بلایا گیا ہے ؟ فرمایا (ہاں) بلایا گیا ہے تو ہمارے لیے آسمان کا دروازہ کھول دیا گیا تو ہم نے حضرت ابراہیم علیہ الصلاۃ والسلام کو دیکھا جو بیت المعمور سے اپنی پیٹھ کی ٹیک لگائے ہوئے تھے اور بیت المعمور میں روزانہ ستر ہزار ایسے فرشتے داخل ہوتے ہیں جو دوبارہ نہیں آتے ( یعنی روز نئے نئے فرشتے آتے ہیں) پھر مجھ کو سدرۃ المنتہیٰ پر لے گئے اس کے پتے ہاتھی کے کانوں کے مثل ہیں اور اس کے پھل بڑے مٹکوں کے مانند ہیں تو جب سدرۃ المنتہیٰ کو خدائے تعالیٰ کے حکم سے ایک چیز نے ڈھانپ لی تو اس کا رنگ بدل گیا خدائے تعالیٰ کی مخلوقات میں سے کوئی اس کی خوبصورتی بیان کرنے کی استطاعت نہیں رکھتا پھر خدائے تعالیٰ نے میری جانب وحی فرمائی جو کچھ وحی فرمائی پھر اس نے رات اور دن میں پچاس نمازیں میرے اوپر فرض فرمائیں۔ میں واپسی میں موسی علیہ الصلاۃ والسلام کے پاس آیا انہوں نے پوچھا آپ کے پروردگار نے آپ کی امت پر کیا فرض فرمایا ہے ؟ میں نے کہا رات دن میں پچاس نمازیں۔ موسی علیہ ا لسلام نے کہا اپنے پروردگار کے پاس جا کر تخفیف کی درخواست پیش کریں اس لیے کہ آپ کی امت اتنی طاقت نہیں رکھتی میں نے بنی اسرائیل کی آزمائش کی ہے اور اس کا امتحان لیا ہے ۔ حضور نے فرمایا تو میں نے واپس جا کر عرض کیا اے میرے پروردگار میری امت پر آسانی فرما تو خدائے تعالیٰ نے میری امت سے پانچ نمازیں کم کردیں میں پھر موسیٰ علیہ السلام کے پاس آیااور کہا کہ مجھ سے پانچ نمازیں کم کردی گئیں۔ انہوں نے کہا کہ آپ کی امت اس کی بھی طاقت نہیں رکھتی آپ پھر اپنے پروردگار کے پاس جا کر تخفیف چاہیں۔ حضور نے فرمایا کہ میں اپنے پروردگار اور موسیٰ علیہ السلام کے درمیان آتا جاتا رہا اور نماز کی تخفیف کا سلسلہ جاری رہا، یہاں تک کہ خدائے تعالیٰ نے فرمایا اے محمد( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) یہ رات اور دن کی کل پانچ نمازیں ہیں، ہر نماز کے لیے دس نمازوں کا ثواب ہے تو وہ پانچ نمازیں ثواب میں پچاس نمازوں کے برابر ہیں۔ جس شخص نے نیکی کا ارادہ کیا اور اس کو نہ کیا تو صرف ارادہ ہی سے اس کے لیے ایک نیکی لکھ دی جاتی ہے اور اگر کر لیا تو اس کے لیے دس نیکیاں لکھی جاتی ہیں اور جو شخص برے کام کا ارادہ کرے اور اس کو نہ کرے تو کچھ نہیں لکھا جاتا اور کر لیا تو اس کے لیے ایک برائی لکھی جاتی ہے ۔ حضور نے فرمایا اس کے بعد میں اتر کر موسیٰ علیہ السلام کے پاس پہنچا تو ان کو حقیقت ِحال سے آگاہ کیا انہوں نے کہا کہ اپنے رب کے پاس جا کر اور تخفیف چاہیں تو رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کہ میں نے مو سیٰ علیہ السلام سے کہا کہ میں اپنے رب کے پاس (نماز کی تخفیف کے لیے ) اتنی بار حاضر ہوا ہوں کہ اب مجھ کو وہاں جاتے ہوئے شرم آتی ہے ۔ (مسلم)\n¥ترجمہ حدیث 2:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے رسولِ کریم علیہ الصلاوۃ والسلام کو فرماتے ہوئے سنا ہے کہ جب قریش نے ( واقعہ معراج کی بابت) میری تکذیب کی تو میں ( ان کے سوالات کا جواب دینے کے لیے ) مقامِ حجر میں کھڑا ہوا تو خدائے تعالیٰ نے بیت المقدس کو میری نگاہوں کے سامنے کردیا میں بیت المقدس کی طرف دیکھ رہا تھا اور اس کی نشانیوں کے بارے میں قریش کے سوالات کا جواب دے رہا تھا۔ (بخاری، مسلم ، مشکوۃ)", "roman": "Tarjuma Hadees 1: Hazrat Anas Bin Malik RadiyAllahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke mere paas ek Buraq laya gaya ye ek safed rang ka janwar tha jis ka qad gadhe se ooncha aur khachchar se neecha tha us ka qadam us maqam par padta tha jahan tak nigah pahunchti hai. Huzoor ne farmaya to main is par sawar hua yahan tak ke Bait-ul-Muqaddas mein aaya Huzoor ne farmaya to main ne Buraq ko us halqa se baandh diya jis se Anbiya-e-Kiram Alayhimus Salam apni sawariyon ko baandha karte the, Huzoor ne farmaya phir main Masjid mein dakhil hua aur do rakat Namaz padhi phir bahar nikla to Jibraeel mere paas ek pyala sharab ka aur ek pyala Doodh ka laye, main ne Doodh ka pyala le liya. Jibraeel ne kaha ke aap ne fitrat (Islam) ko ikhtiyar kar liya. Phir Jibraeel mujh ko aasman ki taraf le chale. Jibraeel ne (aasman ka darwaza) kholne ke liye kaha to poocha gaya aap kaun hain? Farmaya main Jibraeel hoon. Phir poocha gaya aap ke saath kaun hai? Unhon ne kaha Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam hain, phir poocha gaya in ko bulaya gaya hai farmaya (haan) bulaya gaya hai. Phir aasman ka darwaza hamare liye khol diya gaya to main ne Adam Alayhis Salam ko dekha unhon ne mujhe marhaba kaha aur mere liye Dua-e-khair farmayi. Phir Jibraeel mujhe dusre aasman ki taraf le chale. Unhon ne (aasman ka darwaza) kholne ke liye kaha to poocha gaya aap kaun hain. Farmaya main Jibraeel hoon. Phir poocha gaya aur aap ke saath kaun hai? Farmaya Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam hain, phir poocha gaya in ko bulaya gaya hai? Farmaya (haan) bulaya gaya hai, Huzoor ne farmaya phir aasman ka darwaza hamare liye khol diya gaya to main ne do khala-zad bhaiyon yani Isa Bin Maryam aur Yahya Bin Zakariya Alayhimus Salam ko dekha to unhon ne mujhe marhaba kaha aur mere liye Dua-e-khair farmayi. Phir Jibraeel mujhe teesre aasman ki taraf le chale. Unhon ne (aasman ka darwaza) kholne ke liye kaha to poocha gaya aap kaun hain? Farmaya main Jibraeel hoon, phir poocha gaya aur aap ke saath kaun hai? Kaha Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam, phir poocha gaya in ko bulaya gaya hai? Farmaya (haan) bulaya gaya hai phir aasman ka darwaza hamare liye khol diya gaya wahan mujh ko Yusuf Alayhis Salam nazar aaye jinhein (saare jahan ka) aadha Hasan ata farmaya gaya hai unhon ne mujhe marhaba kaha aur mere liye Dua-e-khair farmayi. Phir Jibraeel mujhe chauthe aasman ki taraf le chale to Jibraeel Alayhis Salam ne (aasman ka darwaza) kholne ke liye kaha. Poocha gaya ye kaun hai? Farmaya main Jibraeel hoon kaha gaya aur aap ke saath kaun hai. Farmaya Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam hain phir poocha gaya in ko bulaya gaya hai? Farmaya (haan) bulaya gaya hai to aasman ka darwaza hamare liye khol diya gaya to main ne Idrees Alayhis Salam ko dekha to unhon ne marhaba kaha aur mere liye Dua-e-khair farmayi. Jin ke baare mein Allah Ta'ala ne farmaya ke aur hum ne use buland Makaan par utha liya. Phir Jibraeel mujhe paanchvein aasman ki taraf le chale to unhon ne (aasman ka darwaza) kholne ke liye farmaya to poocha gaya ye kaun hai? Farmaya main Jibraeel hoon. Phir poocha gaya aur aap ke saath kaun hai? Farmaya Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam hain phir kaha gaya in ko bulaya gaya hai? Farmaya (haan) bulaya gaya hai to hamare liye aasman ka darwaza khol diya gaya to achanak mujh ko Haroon Alayhis Salam nazar aaye unhon ne marhaba kaha aur mere liye Dua-e-khair farmayi. Phir Jibraeel hum ko chhathe aasman ki taraf le chale unhon ne aasman ka darwaza kholne ke liye kaha poocha gaya ye kaun hai? Farmaya main Jibraeel hoon phir poocha gaya aur aap ke saath kaun hai? Farmaya Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam hain phir kaha gaya aur in ko bulaya gaya hai? Farmaya (haan) bulaya gaya hai to aasman ka darwaza hamare liye khol diya gaya to main ne Musa Alayhis Salam ko dekha unhon ne marhaba farmaya aur mere liye Dua-e-khair ki. Phir Jibraeel hamein saatvein aasman ki taraf le chale to unhon ne (aasman ka darwaza) kholne ke liye kaha to poocha gaya ye kaun hai? Farmaya main Jibraeel hoon phir poocha gaya aur aap ke saath kaun hai? Farmaya Sarkar-e-Mustafa Sallallahu Alayhi wa Sallam hain phir poocha gaya aur in ko bulaya gaya hai? Farmaya (haan) bulaya gaya hai to hamare liye aasman ka darwaza khol diya gaya to hum ne Hazrat Ibrahim Alayhis Salam ko dekha jo Bait-ul-Ma'moor se apni peeth ki tek lagaye hue the aur Bait-ul-Ma'moor mein rozana sattar hazaar aise farishte dakhil hote hain jo dobara nahi aate (yani roz naye naye farishte aate hain) phir mujh ko Sidrat-ul-Muntaha par le gaye us ke patte haathi ke kaanon ke misl hain aur us ke phal bade matkon ke manind hain to jab Sidrat-ul-Muntaha ko Allah Ta'ala ke hukm se ek cheez ne dhanp li to us ka rang badal gaya Allah Ta'ala ki makhlooqat mein se koi us ki khoobsurti bayan karne ki istita'at nahi rakhta phir Allah Ta'ala ne meri jaanib wahi farmayi jo kuch wahi farmayi phir us ne raat aur din mein pachaas Namazein mere upar Farz farmayin. Main wapsi mein Musa Alayhis Salam ke paas aaya unhon ne poocha aap ke Parwardigar ne aap ki ummat par kya Farz farmaya hai? Main ne kaha raat din mein pachaas Namazein. Musa Alayhis Salam ne kaha apne Parwardigar ke paas ja kar takhfeef ki darkhwast pesh karein isliye ke aap ki ummat itni taqat nahi rakhti main ne Bani Israel ki aazmaish ki hai aur us ka imtehan liya hai. Huzoor ne farmaya to main ne wapas ja kar arz kiya aye mere Parwardigar meri ummat par aasani farma to Allah Ta'ala ne meri ummat se paanch Namazein kam kar dein main phir Musa Alayhis Salam ke paas aaya aur kaha ke mujh se paanch Namazein kam kar di gayin. Unhon ne kaha ke aap ki ummat is ki bhi taqat nahi rakhti aap phir apne Parwardigar ke paas ja kar takhfeef chahein. Huzoor ne farmaya ke main apne Parwardigar aur Musa Alayhis Salam ke darmiyan aata jaata raha aur Namaz ki takhfeef ka silsila jaari raha, yahan tak ke Allah Ta'ala ne farmaya aye Muhammad Sallallahu Alayhi wa Sallam ye raat aur din ki kul paanch Namazein hain, har Namaz ke liye das Namazon ka sawab hai to woh paanch Namazein sawab mein pachaas Namazon ke barabar hain. Jis shakhs ne neki ka irada kiya aur us ko na kiya to sirf irada hi se us ke liye ek neki likh di jaati hai aur agar kar liya to us ke liye das nekiyan likhi jaati hain aur jo shakhs bure kaam ka irada kare aur us ko na kare to kuch nahi likha jaata aur kar liya to us ke liye ek burai likhi jaati hai. Huzoor ne farmaya is ke baad main utar kar Musa Alayhis Salam ke paas pahuncha to un ko haqeeqat-e-haal se aagah kiya unhon ne kaha ke apne Rabb ke paas ja kar aur takhfeef chahein to Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke main ne Musa Alayhis Salam se kaha ke main apne Rabb ke paas (Namaz ki takhfeef ke liye) itni baar hazir hua hoon ke ab mujh ko wahan jaate hue sharm aati hai. (Muslim) Tarjuma Hadees 2: Hazrat Jabir RadiyAllahu Anhu se riwayat hai unhon ne Rasoolullah Sallallahu Alayhi wa Sallam ko farmate hue suna hai ke jab Quraish ne (waqea Me'raj ki baabat) meri takzeeb ki to main (un ke sawaalat ka jawab dene ke liye) Maqam-e-Hijr mein khada hua to Allah Ta'ala ne Bait-ul-Muqaddas ko meri nigahon ke samne kar diya main Bait-ul-Muqaddas ki taraf dekh raha tha aur us ki nishaniyon ke baare mein Quraish ke sawaalat ka jawab de raha tha. (Bukhari, Muslim, Mishkat)", "explanation": "¥اِنتباہ :\n (۱)…حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو جاگتے میں معراج جسمانی ہوئی تھی ا س لیے کہ اگر معراج منامی یا روحانی ہوتی تو کفار قریش حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو ہر گز نہ جھٹلاتے اور نہ بعض ضعیف الایمان مسلمان مرتد ہوتے ۔\n شرح عقائد نسفی ص:۱۰۵ میں ہے : ’’ أَنَّ الْمِعْرَاجَ فِی الْمَنَامِ أَوْبِالرُّوْحِ لَیْسَ مِمَّا یُنْکَرُ کُلَّ الْإِنْکَارِ وَالْکَفَرَۃُ أَنْکَرُوْا أَمْرَ الْمِعْرَاجِ غَایَۃَ الْإِنْکَارِ بَلْ کَثِیْرٌ مِنَ الْمُسْلِمِیْنَ قَدِ ارْتَدُّوْا بِسَبَبِ ذَلِکَ اھـ ‘‘۔ ([1])\n (۲)…حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو جاگتے میں جسمانی معراج ہونا برحق ہے ۔ مکہ معظمہ سے بیت المقدس تک کی سیر کا انکار کرنے والا کافر ہے اور آسمانوں کی سیر کا انکار کرنے والا گمراہ بددین ہے ۔\n اشعۃ اللمعات جلد چہارم ص :۵۲۷ میں ہے :\n ’’ اسراء از مسجد حرام ست تا مسجد اقصٰی ومعراج از مسجد اقصٰی ست تا آسمان و اسراء ثابت ست بہ نص قرآن و منکرآں کافر است ومعراج باحادیث مشہورہ کہ منکر آں ضال ومبتدع ست ‘‘۔ ([2])\n یعنی مسجد حرام سے مسجد ِ اقصٰی تک اسراء ہے اور مسجد اقصی سے آسمان تک معراج ہے ۔ اسراء نص قرآنی سے ثابت ہے اس کا انکار کرنے والا کافر ہے اور معراج احادیث مشہورہ سے ثابت ہے اس کا انکار کرنے والا گمراہ اور بددین ہے ۔\nاور شرح عقائد نسفی ص :۱۰۰ میں ہے :\n ’’ اَلْمِعْرَاجُ لِرَسُوْلِ اللّٰہ علیہ الصلاۃ والسلام فِی الْیَقَظَۃِ بِشَخْصِہِ إِلَی السَّمَاءثُمَّ إِلَی مَا شَاءَ اللّٰہ تَعَالَی مِنَ الْعُلَی حَقٌّ أَیْ ثَابِتٌ بِالْخَبَرِ الْمَشْھُوْرِ حَتَّی أَنَّ مُنْکِرَہُ یَکُوْنُ مُبْتَدِعًا ‘‘۔ ([3])\nیعنی حالت ِبیداری میں جسمِ اطہر کے ساتھ آسمان اور اس کے اوپر جہاں تک خدائے تعالیٰ نے چاہا سرکار ِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کا تشریف لے جانا احادیث مشہورہ سے ثابت ہے اس کا انکار کرنے والا بددین ہے ۔\n اور اسی کتاب کے ص ۱۰۱ پر ہے :\n’’ الْإِ سْرَاءوَھُوَ مِنَ الْمَسْجِدِ الْحَرَامِ إِلَی بَیْتِ الْمَقْدِسِ قَطْعِیٌّ ثَبَتَ بِالْکِتَابِ وَالْمِعْرَاجُ مِنَ الْأَرْضِ إِلَی السَّمَاءِ مَشْہُوْرٌ ‘‘۔ ([4])\nیعنی مسجد حرام سے بیت المقدس تک رات میں سیر فرماناقطعی ہے قرآن مجید سے ثابت ہے (اس کا منکر کافرہے )اورزمین سے آسمان تک سیرفرمانا احادیث مشہورہ سے ثابت ہے ۔ (اس کا منکر گمراہ ہے )۔\n اور سید الفقہاء حضرت ملّا جیون رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں:\n ’’ أَنَّ الْمِعْرَاجَ إِلَی الْمَسْجِدِ الْأَقْصَی قَطْعِیٌّ ثَابِتٌ بِالْکِتَابِ وَإِلَی سَمَاء الدُّنْیَا ثَابِتٌ بِالْخَبْرِ الْمَشْھُوْرِ وَإِلَی مَا فَوْقَہُ مِنَ السَّمَوَاتِ ثَابِتٌ بِالْأَحَادِ فَمُنْکِرُ الْأَوَّلِ کَافِرٌ اَلْبَتَّۃَ وَمُنْکِرُ الثَّانِی مُبْتَدِعٌ مُضِلّ وَمُنْکِرُ الثَّالِثِ فَاسِقٌ ‘‘۔ ([5])\n یعنی مسجد اقصٰی تک معراجِ قطعی ہے قرآن سے ثابت ہے ۔ اور آسمانِ دنیا تک حدیث مشہور سے ثابت ہے ۔ اور آسمانوں سے اوپر تک آحاد سے ثابت ہے تو پہلے کا منکر قطعی کافر ہے اور ثانی کا بددین گمراہ ہے اور تیسرے کا منکر فاسق ہے ۔ (تفسیرات احمدیہ، ص ۳۲۸)\nحضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کو حالت ِبیداری میں جسمِ اطہر کے ساتھ ایک بار اور خواب میں کئی بار معراج ہوئی ۔ اشعۃ اللمعات جلد چہارم ص: ۵۲۷ میں ہے :\n’’ مختلف آمدہ است واقوال علماء دریں باب کہ در خواب بود یا در بیداری ویک بار بود یا بار ہا ۔ صحیح ومختار جمہور آن ست کہ بار ہا بود یک بار در بیداری بود وبار ہائے دیگر در خواب ‘‘۔\nیعنی معراج خواب میں ہوئی تھی یا بیداری میں اور ایک بار ہوئی تھی یا بار بار ؟ اس باب میں علماء کے اقوال مختلف ہیں۔ صحیح اور جمہور علماء کا مختار یہ ہے کہ معراج کئی بار ہوئی تھی ایک بار بیداری میںاور کئی بار خواب میں۔\n پھر دو سطر کے بعد فرمایا کہ:\n’’ تحقیق آن ست کہ یکباردر یقظہ بود بجسد شریف از مسجد حرام تا مسجد اقصٰی واز آنجا تا آسمان واز آسمان تا آنجا کہ خدا خواست ۔ اگر درمنام بودے باعث ایں ہمہ فتنہ وغوغا نمی شد وباعث اختلاف وارتداد نمی گشت ‘‘۔ ([6])\n یعنی تحقیق یہ ہے کہ معراج ایک بار حالت بیداری میں جسمِ اطہر کے ساتھ ہوئی۔ مسجد حرام سے مسجد اقصی تک اور وہاں سے آسمان تک اور آسمان سے جہاں تک کہ خدائے تعالیٰ نے چاہا۔ اگر واقعۂ معراج خواب میں ہوتا تو اس قدر فتنہ و فساد و شور و غوغا کا باعث نہ ہوتا۔ اور کافروں کے جھگڑنے اور بعض مسلمانوں کے مرتد ہونے کا سبب نہ بنتا۔ (اشعۃ اللمعات، ج۴ ص ۵۲۷)\n اور تفسیر خازن جلد رابع ص: ۱۳۴ میں ہے :\n ’’ اَلْحَقُّ الَّذِیْ عَلَیْہِ أَکْثَرُ النَّاسِ ، وَمُعظمُ السَّلَفِ وَعَامَّۃُ الْخَلَفِ مِنَ الْمُتَأخرِینَ مِن الْفُقَہاءِ وَالمُحَدِّثینَ وَالْمُتَکلِّمِین أَنّہ أَسْرَی بِرُوحِہِ وَجَسَدِہِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ‘‘۔ ([7])\nیعنی حق وہی ہے کہ جس پر کثیر صحابہ اکابر تابعین اور عامہ متاخرین فقہا محدثین اور متکلمین ہیں کہ سرکار اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو روح اور جسم کے ساتھ معراج ہوئی۔\n اور حضرت مُلّا جیون رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں:\n ’’ اَلأَصَحُّ أَنَّہُ کَانَ فِی الْیَقَظَۃِ وَکَانَ بِجَسَدِہِ مَعْ رُوْحِہِ وَعَلَیْہِ أَھْلُ السَّنَۃِ وَالْجَمَاعَۃِ فَمَنْ قَالَ أَنَّہُ بِالرُّوْحِ فَقَطْ أَوْ فِی النَّوْمِ فَقَطْ فَمُبْتَدِعٌ ضَالٌّ مُضِلّ فَاسِقٌ ‘‘۔ ([8])\nیعنی صحیح یہ ہے کہ معراج جاگتے میں جسم اطہر کے ساتھ مع روح کے ہوئی۔ اہلِ سنت و جماعت کا یہی مسلک ہے تو جس نے کہا کہ معراج صرف روح کے ساتھ ہوئی یا صرف خواب میں ہوئی تو وہ بددین ، گمراہ ، گمراہ گو، اور فاسق ہے ۔ (تفسیرات احمدیہ، ص ۳۳۰)\n------------------\n[1] ’’ شرح العقائد النسفیۃ ‘‘، ص ۱۴۵.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب فی المعراج ، ج ۴، ص ۵۵۰.\n[3] ’’ شرح العقائد النسفیۃ ‘‘، ص ۱۴۴.\n[4] ’’ شرح العقائد النسفیۃ ‘‘، ص ۱۴۵.\n[5] ’’ التفسیرات الأحمدیۃ ‘‘، سورۃ بنی اسرائیل ، ص ۵۰۳.\n[6] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب فی المعراج ، ج ۴، ص ۵۵۰۔ ۵۵۱.\n[7] ’’ تفسیر الخازن ‘‘، ج ۳، ص ۱۵۸.\n[8] ’’ التفسیرات الأحمدیۃ ‘‘، ص ۵۰۵."}, {"id": 7880, "bookId": 14, "volNo": "1", "hadithNo": 112, "chapter": "معجزات", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ أَنَسٍ قَالَ إِنَّ أَہْلَ مَکَّۃَ سَأَلُوا رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَنْ یُرِیَہُمْ آیَۃً فَأَرَاہُمْ الْقَمَرَ شِقَّتَیْنِ حَتَّی رَأَوْا حِرَاء بَیْنَہُمَا‘‘۔ \nحدیث 2:\n’’ عَنِ ابْنِ مَسْعُودٍ قَالَ اِنْشَقَّ الْقَمَرُ عَلَی عَہْدِ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِرْقَتَیْنِ فِرْقَۃً فَوْقَ الْجَبَلِ وَفِرْقَۃً دُونَہُ‘‘۔\nحدیث 3:\n’’ عَنْ أَسْمَاء بِنْتِ عُمَیْسٍ أَنَّہُ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ یُوْحَی إِلَیْہِ وَرَأْسُہُ فِی حِجْرِ عَلِیٍّ فَلَمْ یُصَلِّ حَتَّی غَرَبَتِ الشَّمْسُ فَقَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَصَلَّیْتَ یَاعَلِیّ قَالَ لَا فَقَالَ أَللَّھُمَّ إِنَّہُ کَانَ فِی طَاعَتِکَ وَطَاعَۃِ رَسُوْلِکَ فَارْدُدْ عَلَیْہِ الشَّمْسَ قَالَتْ أَسْمَاءُ فَرَأَیْتُھَا غَرَبَتْ ثُمَّ رَأَیْتُھَا طَلَعَتْ وَوَقَفَتْ عَلَی الْجِبَالِ وَالْأَرْضِ وَذَلِکَ بِالصَّھْبَاءِ فِی خَیْبَرَ‘‘۔\nحدیث 4:\n’’عَنْ جَابِرٍ أَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَمَرَ الشَّمْسَ فَتَأَخَّرَتْ سَاعَۃً مِنَ النَّہَارِ رَوَاہُ الطَّبَرَانِی فِی مُعْجَمَۃِ الْأَوْسَطِ بِسَنَدٍ حَسَنٍ ‘‘۔\nحدیث 5:\n’’عَنْ جَابِرٍ قَالَ کَانَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِذَا خَطَبَ اِسْتَنَدَ إِلَی جِذْعٍ نَخْلَۃٍ مِنْ سَوَارِی الْمَسْجِدِ فَلَمَّا صُنِعَ لَہُ الْمِنْبَرُ فَاسْتَوَی عَلَیْہِ صَاحَتْ النَّخْلَۃُ الَّتِی کَانَ یَخْطُبُ عِنْدَہَا حَتَّی کَادَتْ أَنْ تَنْشَقَّ فَنَزَلَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَتَّی أَخَذَہَا فَضَمَّہَا إِلَیْہِ فَجَعَلَتْ تَءِنُّ أَنِینَ الصَّبِیِّ الَّذِی یُسَکَّتُ حَتَّی اسْتَقَرَّتْ ‘‘۔\nحدیث 6:\n’’ عَنِ ابْنِ عُمَرَ قَالَ کُنَّا مَعَ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی سَفَرٍ فَأَقْبَلَ أَعْرَابِیٌّ، فَلَمَّا دَنَا قَالَ لَہُ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ تَشْہَدُ أَنْ لاَ إِلَہَ إِلاَّ اللّٰہ وَحْدَہُ لاَ شَرِیکَ لَہُ، وَأَنَّ مُحَمَّداً عَبْدُہُ وَرَسُولُہُ قَالَ وَمَنْ یَشْہَدُ عَلَی مَا تَقُولُ؟ قَالَ ہَذِہِ السَّلَمَۃُ فَدَعَاہَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ وَہُوَ بِشَاطِیِٔ الْوَادِی، فَأَقْبَلَتْ تُخُدُّ الأَرْضَ حَتَّی قَامَتْ بَیْنَ یَدَیْہِ، فَاسْتَشْہَدَہَا ثَلاَثاً فَشَہِدَتْ ثَلاَثاً أَنَّہُ کَمَا قَالَ، ثُمَّ رَجَعَتْ إِلَی مَنْبَتِہَا ‘‘۔\nحدیث 7:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ جَاءَ أَعْرَابِیٌّ إِلَی رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ بِمَ أَعْرِفُ أَنَّکَ نَبِیٌّ قَالَ إِنْ دَعَوْتُ ہَذَا الْعِذْقَ مِنْ ہَذِہِ النَّخْلَۃِ یَشْہَدُ أَنِّی رَسُولُ اللّٰہ فَدَعَاہُ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَجَعَلَ یَنْزِلُ مِنْ النَّخْلَۃِ حَتَّی سَقَطَ إِلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ثُمَّ قَالَ ارْجِعْ فَعَادَ فَأَسْلَمَ الْأَعْرَابِیُّ‘‘۔\nحدیث 8:\n’’ عَنْ عَبْدِ اللّٰہ قَالَ کُنَّا نَعُدُّ الْآیَاتِ بَرَکَۃً وَأَنْتُمْ تَعُدُّونَہَا تَخْوِیفًا کُنَّا مَعَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی سَفَرٍ فَقَلَّ الْمَاء فَقَالَ اطْلُبُوا فَضْلَۃً مِنْ مَائٍ فَجَاءُ وا بِإِنَائٍ فِیہِ مَائٌ قَلِیلٌ فَأَدْخَلَ یَدَہُ فِی الْإِنَاءِ ثُمَّ قَالَ حَیَّ عَلَی الطَّہُورِ الْمُبَارَکِ وَالْبَرَکَۃُ مِنْ اللّٰہ وَلَقَدْ رَأَیْتُ الْمَاء یَنْبُعُ مِنْ بَیْنِ أَصَابِعِ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ ‘‘۔\nحدیث 9:\n’’ عَنْ جَابِرِ بْنِ عَبْدِ اللّٰہ قَالَ عَطِشَ النَّاسُ یَوْمَ الْحُدَیْبِیَۃِ وَالنَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بَیْنَ یَدَیْہِ رِکْوَۃٌ فَتَوَضَّأَ فَجَہِشَ النَّاسُ نَحْوَہُ قَالَ مَا لَکُمْ قَالُوا لَیْسَ عِنْدَنَا مَاء نَتَوَضَّأُ وَلَا نَشْرَبُ إِلَّا مَا بَیْنَ یَدَیْکَ فَوَضَعَ یَدَہُ فِی الرِّکْوَۃِ فَجَعَلَ الْمَاءُ یَثُورُ بَیْنَ أَصَابِعِہِ کَأَمْثَالِ الْعُیُونِ فَشَرِبْنَا وَتَوَضَّأْنَا قُلْتُ کَمْ کُنْتُمْ قَالَ لَوْ کُنَّا مِءَۃَ أَلْفٍ لَکَفَانَا کُنَّا خَمْسَ عَشْرَۃَ مِاءَۃً‘‘ ۔ \nحدیث 10:\n’’عَنْ أَنَسٍ قَالَ أُتِیَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بِإِنَائٍ وَہُوَ بِالزَّوْرَاءِ فَوَضَعَ یَدَہُ فِی الْإِنَاء فَجَعَلَ الْمَاء یَنْبُعُ مِنْ بَیْنِ أَصَابِعِہِ فَتَوَضَّأَ الْقَوْمُ قَالَ قَتَادَۃُ قُلْتُ لِأَنَسٍ کَمْ کُنْتُمْ قَالَ ثَلَاثَ مِاءَۃٍ أَوْ زُہَاءَ ثَلاثِ مِاءَۃٍ‘‘۔\nحدیث 11:\n’’ عَنْ عَلِیِّ بْنِ أَبِی طَالِبٍ قَالَ کُنْتُ مَعَ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بِمَکَّۃَ فَخَرَجْنَا فِی بَعْضِ نَوَاحِیہَا فَمَا اسْتَقْبَلَہُ جَبَلٌ وَلَا شَجَرٌ إِلَّا وَہُوَ یَقُولُ السَّلَامُ عَلَیْکَ یَا رَسُولَ اللّٰہ‘‘۔ \nحدیث 12:\n’’ عَنْ جَابِرٍ قَال سِرْنَا مَعَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ حَتَّی نَزَلْنَا وَادِیًا أَفْیَحَ فَذَہَبَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَقْضِی حَاجَتَہُ فَلَمْ یَرَ شَیْءًا یَسْتَتِرُ بِہِ وَإِذَا شَجَرَتَانِ بِشَاطِیِٔ الْوَادِی فَانْطَلَقَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِلَی إِحْدَاہُمَا فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِہَا فَقَالَ انْقَادِی عَلَیَّ بِإِذْنِ اللّٰہ فَانْقَادَتْ مَعَہُ کَالْبَعِیرِ الْمَخْشُوشِ الَّذِی یُصَانِعُ قَاءِدَہُ حَتَّی أَتَی الشَّجَرَۃَ الْأُخْرَی فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِہَا فَقَالَ انْقَادِی عَلَیَّ بِإِذْنِ اللّٰہ فَانْقَادَتْ مَعَہُ کَذَلِکَ حَتَّی إِذَا کَانَ بِالْمَنْصَفِ مِمَّا بَیْنَہُمَا قَالَ الْتَءِمَا عَلَیَّ بِإِذْنِ اللّٰہ فَالْتَأَمَتَا فَجَلَسْتُ أُحَدِّثُ نَفْسِی فَحَانَتْ مِنِّی لَفْتَۃٌ فَإِذَا أَنَا بِرَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مُقْبِلًا وَإِذَا الشَّجَرَتَانِ قَدْ افْتَرَقَتَا فَقَامَتْ کُلُّ وَاحِدَۃٍ مِنْہُمَا عَلَی سَاقٍ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت انس ر ضی اللّٰہ تعالیٰ عنہ سے مروی ہے انہوں نے فرمایا کہ مکہ والوں نے حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم سے کہا کہ آپ کوئی معجزہ دکھائیں تو سرکارِ اقدس نے چاند کے دو ٹکڑے فرما کر انہیں دکھادیا یہاں تک کہ مکہ والوں نے حرا پہاڑ کو چاند کے دو ٹکڑوں کے درمیان دیکھا۔ (بخاری، مسلم، مشکوۃ ص ۵۲۴)\n¥ترجمہ حدیث 2:\n حضرت ابن مسعود رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے فرمایا کہ رسولِ کریم علیہ الصلاۃ والتسلیم کے زمانہ مبارکہ میں چاند دو ٹکڑے ہوگیا ایک ٹکڑا پہاڑ سے اوپر تھا اور دوسرا ٹکڑا اس کے نیچے ۔ (بخاری، مسلم، مشکوۃ ص ۵۲۴)\n¥ترجمہ حدیث 3:\nحضرت اسماء بنت عمیس رَضِیَ اللّٰہ تَعَالٰی عَنْہا سے روایت ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم پر اس حال میں وحی نازل ہورہی تھی کہ آپ کا مبارک سر حضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کی گود میں تھا تو حضرت علی رَضِیَ اللّٰہ تَعَالٰی عَنْہُ (عصر کی) نماز نہیں پڑھ سکے یہاں تک کہ سورج ڈوب گیا۔ بعدہ حضور علیہ الصلاۃ و السلام نے فرمایا کہ اے علی! کیا تم نے نماز پڑھی؟ انہوں نے عرض کیا نہیں تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم نے بارگاہِ الہی میں دعا کی۔ یَا إلٰہَ الْعٰلَمِیْنَ علی تیرے اور تیرے رسول کی اطاعت و فرمانبرداری میں تھے (اس لیے ان کی نماز عصر قضا ہوگئی) لہذا تو ان کے لیے سورج کو لوٹا دے ۔ حضرت اسماء بنت عمیس فرماتی ہیں کہ میں نے دیکھا کہ سورج ڈوب گیا تھا پھر ( دعائے نبوی کے بعد) میں نے دیکھا کہ وہ طلوع ہوگیا اور اس کی کرنیں پہاڑوں اور زمینوں پر پھیل گئیں۔ یہ واقعہ مقام صہبا میں پیش آیا جو خیبر سے قریب ہے ۔ (شفا مع نسیم الریاض، جلد سوم ص ۱۰)\n¥ترجمہ حدیث 4:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے مروی ہے کہ حضور علیہ الصلاۃ والسلام نے سورج کو حکم دیا کہ کچھ دیر کے لیے چلنے سے رک جائے وہ فوراً ر ک گیا ۔ (طبرانی شرح الشفا للملا علی قاری، مع نسیم الریاض، جلد سوم ص ۱۳)\n¥ترجمہ حدیث 5:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ نبی کریم علیہ الصلاۃ والتسلیم جب مسجد میںخطبہ پڑھتے تو کھجور کے اس تنہ پر جو ستون ( کھمبا) کے طور پر مسجد میںکھڑا تھا کمرلگالیتے پھر جب منبر تیار ہوگیا اور حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ اس پر خطبہ پڑھنے کے لیے رونق افروز ہوئے تو وہ ستون جس سے ٹیک لگا کر آپ خطبہ فرمایا کرتے تھے فراقِ نبی میں چیخ اٹھا اور قریب تھا کہ وہ شدتِ اضطراب سے پھٹ جائے تو رسول اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم منبر سے اترے یہاں تک کہ اس ستون کو پکڑ کر اپنے سینے سے لگالیا پھر اس ستون نے اس بچہ کی طرح رونا اور بلبلانا شروع کیا جس کو تسلی دے کر خاموش کیا جاتا ہے ۔ یہاں تک کہ اس ستون کو قرار حاصل ہوا۔ (بخاری شریف، مشکوۃ ص ۵۳۶)\n¥ترجمہ حدیث 6:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے فرمایا کہ ہم رسولِ کریم علیہ الصلاۃ والسلام کے ساتھ سفر کررہے تھے کہ ایک دیہاتی آیا جب وہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے قریب پہنچا تو آپ نے اس سے فرمایا کیا تو اس بات کی گواہی دیتا ہے کہ خدائے واحد کے سوا کوئی معبود نہیں اور محمد ( صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ ) خدائے تعالیٰ کے بندے اور اس کے رسول ہیں۔ دیہاتی نے کہا آپ کی باتوں پر میرے سوا اور کون گواہی دے گا؟حضور نے فرمایا یہ ببول کا درخت گواہی دے گا۔ یہ فرما کر آپ نے اس درخت کو بلایا آپ وادی کے کنارے تھے وہ درخت زمین کو پھاڑتا ہوا چلا یہاں تک کہ آپ کے سامنے کھڑا ہوگیاحضور علیہ الصلاۃ والسلام نے اس سے تین بار گواہی طلب فرمائی اس درخت نے تینوں بار گواہی دی کہ حقیقت میں ایسا ہی ہے جیسا کہ آپ نے فرمایا اس کے بعد وہ درخت اپنی جگہ واپس چلا گیا۔ (دارمی، مشکوۃ ص ۵۴۱)\n¥ترجمہ حدیث 7:\nحضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما نے فرمایا کہ ایک دیہاتی حضور علیہ الصلاۃ والسلام کی خدمت میں حاضر ہوا اور عرض کیا کہ کیونکر میں یقین کروں کہ آپ سچے نبی ہیں۔ حضورنے فرمایا کہ کھجور کے اس خوشہ کو اگر میں بلاؤں اور وہ میرے پاس آکر اس بات کی گواہی دے کہ میں خدائے تعالیٰ کا رسول ہوں جب تجھے یقین آجائے گا۔ چنانچہ حضور نے اس خوشہ کو بُلایا تو وہ کھجور کے درخت سے اترنے لگایہاں تک کہ حضور علیہ الصلاۃ والسلام کے قریب زمین پر آکر گرا پھر آپ نے فرمایا کہ واپس چلا جا تو وہ خوشہ واپس چلا گیا یہ دیکھ کر وہ اعرابی مسلمان ہوگیا۔ (ترمذی، مشکوۃ ص ۵۴۱)\n¥ترجمہ حدیث 8:\nحضرت عبداللّٰہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم تو معجزات کو باعث ِبرکت سمجھتے تھے اور تم ان کو تخفیف کا باعث سمجھتے ہو ہم ایک سفر میں رسولِ کریم علیہ الصلاۃ والتسلیم کے ساتھ تھے ۔ پانی کم ہوگیا تو حضور نے فرمایا کہ تھوڑا سا بچا ہوا پانی تلاش کرلاؤ تو لوگ ایک برتن لائے جس میں تھوڑا سا پانی موجود تھا۔ حضور نے اپنا مقدس ہاتھ برتن میں ڈالدیا اور اس کے بعد فرمایا برکت والے پانی کے پاس آؤ ۔ اور برکت خدائے تعالیٰ کی طرف سے ہے پس میں نے قطعی طور پر دیکھا کہ حضور کی مقدس انگلیوں کی گھائیوں سے پانی اُبل رہا تھا۔ (بخاری ج۱ ص ۵۰۵، مشکوۃ ص ۵۳۸)\n¥ترجمہ حدیث 9:\nحضر ت جابر بن عبد اللّٰہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ صلح حدیبیہ کے دن لوگ پیاسے تھے اور حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے سامنے ایک پیالہ تھا جس سے آپ نے وضو فرمایا۔ تو لوگ آپ کی جانب دوڑے حضور نے فرمایا کیا بات ہے ؟ لوگوں نے عرض کیا ہمارے پاس وضو کرنے اور پینے کے لیے پانی نہیں ہے مگر صرف یہی جو آپ کے سامنے ہے توحضور علیہ الصلاۃوالسلام نے اپنا دستِ مبارک اسی پیالہ میں رکھ دیاتو آپ کی انگلیوں کے درمیان سے چشموں کی طرح پانی ابلنے لگا حضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کا بیان ہے کہ ہم تمام لوگوں نے پانی پیا اور وضو کیا حضرت سالم فرماتے ہیں کہ میں نے حضرت جابر سے پوچھا آپ حضرات کتنی تعداد میں تھے ؟انہوں نے فرمایا کہ اگر ہم ایک لاکھ بھی ہوتے تب بھی وہ پانی کافی ہوتا۔ ( اس وقت) تو ہماری تعداد پندرہ سو تھی۔ (بخاری، ج۱، ص ۵۰۵، مشکوۃ ص ۵۳۲)\n¥ترجمہ حدیث 10:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے فرمایا کہ نبی کریم علیہ الصلاۃ والتسلیم کے پاس پانی کا ایک برتن لایا گیا حضور اس وقت مقام زوراء میں تشریف فر ماتھے ۔ آپ نے اپنا مقدس ہاتھ اس برتن میں رکھ دیا تو پانی حضور کی انگلیوں کے درمیان سے ابلنے لگا جس سے تمام لوگوں نے وضوکر لیا۔ حضرت قتادہ فرماتے ہیں کہ میں نے حضرت انس سے پوچھا کہ اس وقت آپ کتنے تھے ؟ انہوں نے فرمایا تین سو یا تین سو کے قریب ۔ (بخاری، ج۱، ص ۵۰۴، مشکوۃ ص ۵۳۷)\n¥ترجمہ حدیث 11:\nحضرت علی بن ابی طالب کرم اللّٰہ تعالیٰ وجہہ نے فرمایا کہ میں نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کے ہمراہ مکہ میں تھا پھر سرکارِ اقدس اور ہم مکہ شریف کے گردو نواح میں گئے تو جس پہاڑ اور درخت کا بھی سامنا ہوتا تو وہ عرض کرتا ’’ السَّلَامُ عَلَیْکَ یَا رَسُولَ اللّٰہ ‘‘۔ (ترمذی، دارمی، مشکوۃ ص ۵۴۰)\n¥ترجمہ حدیث 12:\nحضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ہم حضور علیہ الصلاۃ والسلام کے ساتھ جارہے تھے کہ ایک بے آب وگیاہ وادی یعنی میدان میں اُترے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم قضائے حاجت کے لیے تشریف لے گئے لیکن پردہ کی کوئی جگہ آپ کو نہ ملی۔ اچانک آپ کی نظراس وادی کے کنارے دو درختوں پر پڑی حضور ان میں سے ایک کے پاس گئے اور اس کی ایک شاخ کو پکڑ کر (درخت سے ) فرمایا کہ بحکم خدا میرے ساتھ چل تو وہ درخت اس اونٹ کی طرح چل پڑا جس کی ناک میں نکیل بندھی رہتی ہے اور اپنے ساربان کی اطاعت کرتا ہے یہاں تک کہ حضور اس دوسرے درخت کے پاس تشریف لے گئے اور اس کی ایک شاخ پکڑ کر فرمایا کہ اے (درخت) تو بھی بحکمِ الہٰی میرے ساتھ چل ۔ تو وہ بھی پہلے درخت کی طرح حضور کے ساتھ چل پڑا یہاں تک کہ حضور جب ان درختوں کے درمیان کی جگہ میں پہنچے تو فرمایا کہ ( اے درختو) تم دونوں بحکمِ الہی آپس میں مل کر میرے لیے پردہ بن جاؤ تو دونوں ایک دوسرے سے مل گئے ( اور حضور نے ان درختوں کیآڑ میں قضائے حاجت فرمائی)۔ حضرت جابر کا بیان ہے کہ اس عجیب واقعہ کو دیکھ کر میں بیٹھا سوچ رہا تھا کہ میری نگاہ اٹھی تو اچانک میں نے دیکھا کہ حضور اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم تشریف لارہے ہیں اور دیکھا کہ دفعۃًوہ دونوں درخت جدا ہو کر چلے اور اپنے تنے پر کھڑے ہوگئے ۔ (مسلم، مشکوۃ ص ۵۳۳)", "roman": "Tarjuma Hadees 1: Hazrat Anas RadiyAllahu Anhu se marwi hai unhon ne farmaya ke Makkah walon ne Huzoor Sayyid-e-Aalam Sallallahu Alayhi wa Sallam se kaha ke aap koi Mu'jizah dikhayen to Sarkar-e-Aqdas ne chand ke do tukde farma kar unhein dikha diya yahan tak ke Makkah walon ne Hira pahad ko chand ke do tukdon ke darmiyan dekha. (Bukhari, Muslim, Mishkat) Tarjuma Hadees 2: Hazrat Ibn Mas'ood RadiyAllahu Anhu se riwayat hai unhon ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ke zamana-e-mubarakah mein chand do tukde ho gaya ek tukda pahad se upar tha aur dusra tukda us ke neeche. (Bukhari, Muslim, Mishkat) Tarjuma Hadees 3: Hazrat Asma Bint Umais RadiyAllahu Anha se riwayat hai ke Huzoor Sallallahu Alayhi wa Sallam par is haal mein wahi nazil ho rahi thi ke aap ka mubarak sar Hazrat Ali RadiyAllahu Anhu ki god mein tha to Hazrat Ali RadiyAllahu Anhu (Asr ki) Namaz nahi padh sake yahan tak ke suraj doob gaya. Ba'dah Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke aye Ali! Kya tum ne Namaz padhi? Unhon ne arz kiya nahi to Huzoor Sallallahu Alayhi wa Sallam ne bargah-e-Ilahi mein Dua ki. Ya Ilahal Aalameen Ali tere aur tere Rasool ki ita'at-o-farmanbardari mein the (isliye un ki Namaz Asr Qaza ho gayi) lehaza tu un ke liye suraj ko lauta de. Hazrat Asma Bint Umais farmati hain ke main ne dekha ke suraj doob gaya tha phir (Dua-e-Nabawi ke baad) main ne dekha ke woh tulu ho gaya aur us ki kirnein pahadon aur zameeno par phail gayin. Ye waqea Maqam-e-Sahba mein pesh aaya jo Khaibar se qareeb hai. (Shifa, Jild-e-Suwwam) Tarjuma Hadees 4: Hazrat Jabir RadiyAllahu Anhu se marwi hai ke Huzoor Sallallahu Alayhi wa Sallam ne suraj ko hukm diya ke kuch der ke liye chalne se ruk jaye woh foran ruk gaya. (Tabarani, Sharh-ush-Shifa) Tarjuma Hadees 5: Hazrat Jabir RadiyAllahu Anhu ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam jab Masjid mein Khutbah padhte to khajoor ke us tana par jo sutoon (khamba) ke taur par Masjid mein khada tha kamar laga lete phir jab Mimbar tayyar ho gaya aur Huzoor Sallallahu Alayhi wa Sallam us par Khutbah padhne ke liye raunaq-afroz hue to woh sutoon jis se tek laga kar aap Khutbah farmaya karte the firaq-e-Nabi mein cheekh utha aur qareeb tha ke woh shiddat-e-iztirab se phat jaye to Rasoolullah Sallallahu Alayhi wa Sallam Mimbar se utre yahan tak ke us sutoon ko pakad kar apne seene se laga liya phir us sutoon ne us bachah ki tarah rona aur bilbilana shuru kiya jis ko tasalli de kar khamosh kiya jaata hai. Yahan tak ke us sutoon ko qarar hasil hua. (Bukhari Sharif, Mishkat) Tarjuma Hadees 6: Hazrat Ibn Umar RadiyAllahu Anhum ne farmaya ke hum Rasoolullah Sallallahu Alayhi wa Sallam ke saath safar kar rahe the ke ek dehati aaya jab woh Huzoor Sallallahu Alayhi wa Sallam ke qareeb pahuncha to aap ne us se farmaya kya tu is baat ki gawah deta hai ke Allah-e-Wahid ke siwa koi Mabood nahi aur Muhammad Sallallahu Alayhi wa Sallam Allah Ta'ala ke bande aur us ke Rasool hain. Dehati ne kaha aap ki baaton par mere siwa aur kaun gawah dega? Huzoor ne farmaya ye babool ka darakht gawah dega. Ye farma kar aap ne us darakht ko bulaya aap wadi ke kinare the woh darakht zameen ko phadta hua chala yahan tak ke aap ke samne khada ho gaya Huzoor Sallallahu Alayhi wa Sallam ne us se teen baar gawah talab farmayi us darakht ne teenon baar gawah di ke haqeeqat mein aisa hi hai jaisa ke aap ne farmaya is ke baad woh darakht apni jagah wapas chala gaya. (Darimi, Mishkat) Tarjuma Hadees 7: Hazrat Ibn Abbas RadiyAllahu Anhum ne farmaya ke ek dehati Huzoor Sallallahu Alayhi wa Sallam ki khidmat mein hazir hua aur arz kiya ke kyonkar main yaqeen karoon ke aap sachche Nabi hain. Huzoor ne farmaya ke khajoor ke is khosha ko agar main bulaoon aur woh mere paas aa kar is baat ki gawah de ke main Allah Ta'ala ka Rasool hoon jab tujhe yaqeen aa jaye ga. Chunancha Huzoor ne us khosha ko bulaya to woh khajoor ke darakht se utarne laga yahan tak ke Huzoor Sallallahu Alayhi wa Sallam ke qareeb zameen par aa kar gira phir aap ne farmaya ke wapas chala ja to woh khosha wapas chala gaya ye dekh kar woh a'rabi Musalman ho gaya. (Tirmidhi, Mishkat) Tarjuma Hadees 8: Hazrat Abdullah RadiyAllahu Anhu ne farmaya ke hum to mu'jizaat ko ba'is-e-barkat samajhte the aur tum un ko takhfeef ka ba'is samajhte ho hum ek safar mein Rasoolullah Sallallahu Alayhi wa Sallam ke saath the. Paani kam ho gaya to Huzoor ne farmaya ke thoda sa bacha hua paani talash kar lao to log ek bartan laye jis mein thoda sa paani maujood tha. Huzoor ne apna muqaddas haath bartan mein daal diya aur us ke baad farmaya barkat wale paani ke paas aao. Aur barkat Allah Ta'ala ki taraf se hai pas main ne qat'i taur par dekha ke Huzoor ki muqaddas ungliyon ki ghaiyon se paani ubal raha tha. (Bukhari, Mishkat) Tarjuma Hadees 9: Hazrat Jabir Bin Abdullah RadiyAllahu Anhu ne farmaya ke Sulh-e-Hudaibiyah ke din log pyase the aur Huzoor Sallallahu Alayhi wa Sallam ke samne ek pyala tha jis se aap ne Wazu farmaya. To log aap ki jaanib daude Huzoor ne farmaya kya baat hai? Logon ne arz kiya hamare paas Wazu karne aur peene ke liye paani nahi hai magar sirf yahi jo aap ke samne hai to Huzoor Sallallahu Alayhi wa Sallam ne apna dast-e-mubarak usi pyala mein rakh diya to aap ki ungliyon ke darmiyan se chashmon ki tarah paani ubalne laga Hazrat Jabir RadiyAllahu Anhu ka bayan hai ke hum tamam logon ne paani piya aur Wazu kiya Hazrat Saalim farmate hain ke main ne Hazrat Jabir se poocha aap hazraat kitni tadaad mein the? Unhon ne farmaya ke agar hum ek laakh bhi hote tab bhi woh paani kaafi hota. (Us waqt) to hamari tadaad pandrah sau thi. (Bukhari, Mishkat) Tarjuma Hadees 10: Hazrat Anas RadiyAllahu Anhu se riwayat hai unhon ne farmaya ke Rasoolullah Sallallahu Alayhi wa Sallam ke paas paani ka ek bartan laya gaya Huzoor us waqt Maqam-e-Zoura mein tashreef farma the. Aap ne apna muqaddas haath us bartan mein rakh diya to paani Huzoor ki ungliyon ke darmiyan se ubalne laga jis se tamam logon ne Wazu kar liya. Hazrat Qatadah farmate hain ke main ne Hazrat Anas se poocha ke us waqt aap kitne the? Unhon ne farmaya teen sau ya teen sau ke qareeb. (Bukhari, Mishkat) Tarjuma Hadees 11: Hazrat Ali Bin Abi Talib RadiyAllahu Anhu ne farmaya ke main Rasoolullah Sallallahu Alayhi wa Sallam ke hamrah Makkah mein tha phir Sarkar-e-Aqdas aur hum Makkah Sharif ke gird-o-nawah mein gaye to jis pahad aur darakht ka bhi samna hota to woh arz karta ''Assalamu Alayka Ya Rasoolullah''. (Tirmidhi, Darimi, Mishkat) Tarjuma Hadees 12: Hazrat Jabir RadiyAllahu Anhu ne farmaya ke hum Huzoor Sallallahu Alayhi wa Sallam ke saath ja rahe the ke ek be-aab-o-giyah wadi yani maidan mein utre Huzoor Sallallahu Alayhi wa Sallam Qaza-e-Hajat ke liye tashreef le gaye lekin Pardah ki koi jagah aap ko na mili. Achanak aap ki nazar us wadi ke kinare do darakhton par padi Huzoor un mein se ek ke paas gaye aur us ki ek shaakh ko pakad kar (darakht se) farmaya ke bahukm-e-Khuda mere saath chal to woh darakht us oont ki tarah chal pada jis ki naak mein nakeel bandhi rehti hai aur apne sarban ki ita'at karta hai yahan tak ke Huzoor us dusre darakht ke paas tashreef le gaye aur us ki ek shaakh pakad kar farmaya ke aye (darakht) tu bhi bahukm-e-Ilahi mere saath chal. To woh bhi pehle darakht ki tarah Huzoor ke saath chal pada yahan tak ke Huzoor jab un darakhton ke darmiyan ki jagah mein pahunche to farmaya ke (aye darakhto) tum dono bahukm-e-Ilahi aapas mein mil kar mere liye Pardah ban jao to dono ek dusre se mil gaye (aur Huzoor ne un darakhton ki aad mein Qaza-e-Hajat farmayi). Hazrat Jabir ka bayan hai ke is ajeeb waqea ko dekh kar main baitha soch raha tha ke meri nigah uthi to achanak main ne dekha ke Huzoor-e-Aqdas Sallallahu Alayhi wa Sallam tashreef la rahe hain aur dekha ke daf'atan woh dono darakht juda ho kar chale aur apne tana par khade ho gaye. (Muslim, Mishkat)", "explanation": "¥شرح حدیث 2:\nحضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے فرمایا کہ:\n ’’ انشقاق قمر بہ تحقیق واقع شدہ مرآں حضرت را صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ وروایت کردہ آند آں راجمعے کثیر از صحابہ وتابعین وروایت کردہ اند از ایشاں جم غفیر از آئمہ حدیث ، و مفسران اجماع دارند کہ مراد درآیت کریمہ { اِقْتَرَبَتِ السَّاعَةُ وَ انْشَقَّ الْقَمَرُ(۱) } ہمیں انشقاق ست کہ معجزۂ آں حضرت واقع شد نہ آنکہ در قیامت واقع شود و سیاق آیت کریمہ کہ فرمودہ { وَ اِنْ یَّرَوْا اٰیَةً یُّعْرِضُوْا وَ یَقُوْلُوْا سِحْرٌ مُّسْتَمِرٌّ(۲) } دلالت دارد برآں ‘‘ ۔ ([1])\nیعنی حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کے لیے چاند کا ٹکڑے ہونا یقینا واقع ہے جس کو صحابہ و تابعین رضوان اللّٰہ تعالی علیہم اجمعین کی کثیر جماعت نے بیان کیا ہے اور پھر ان سے محدثین کے جمِ غفیر نے روایت کیا ہے اور مفسرین کرام کا اتفاق ہے کہ آیت کریمہ { اِقْتَرَبَتِ السَّاعَةُ وَ انْشَقَّ الْقَمَرُ(۱) }میں یہی چاند کا دو ٹکڑے ہونا مراد ہے جو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کا معجزہ واقع ہوا وہ انشقاق مراد نہیں ہے جو قرب قیامت میں واقع ہوگا اور اسی سے متصل دوسری آیت کریمۂ { وَ اِنْ یَّرَوْا اٰیَةً یُّعْرِضُوْا وَ یَقُوْلُوْا سِحْرٌ مُّسْتَمِرٌّ(۲) }([2])اسی مضمون کو بتاتی ہے کہ حضور علیہ الصلاۃ والسلام نے چاند کو دو ٹکڑے کیا ہے ۔ (اشعۃ اللمعات، جلد چہارم ص ۵۱۸ )\n------------------\n[1] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب علامات النبوۃ ، ج ۴، ص ۵۴۲.\n[2] اور اگر دیکھتے ہیں کوئی نشانی تو منہ پھیرتے اور کہتے ہیں یہ تو جادو ہے ( جو پہلے سے ) چلا آرہا ہے ۔ ۱۲ منہ\n¥انتباہ :\n (۱)… انبیائے کرام علیہم الصلاۃ والسلام سے دعوائے نبوت کی تائید میں جوبات خلافِ عادت ظاہر ہواسے معجزہ کہتے ہیں۔ حضرت میر سید شریف جرجانی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں :’’ اَلْمُعْجِزَۃُ أَمْرٌ خَارِقٌ لِلْعَادَۃِ دَاعِیَۃٌ إِلَی الْخَیْرِ وَالسَّعَادَۃِ مَقْرُوْنَۃٌ بِدَعْوَی النَّبُوَّۃِ قُصِدَ بِہِ إِظْھَارُ صِدْقِ مَنِ ادَّعَی أَنَّہُ رَسُوْلٌ مِنَ اللّٰہ ‘‘۔ ([1]) (التعریفات ص ۱۹۵)\n (۲)…حضرات انبیاء کرام علیہم الصلوۃ والسلام کے معجزات کا مطلقاً انکار کرنے والا کافر، ملحد اور زندیق ہے ۔\n (۳)…جو معجزہ دلیل قطعی سے ثابت ہو جیسے معراج کی رات میں حضور سید عالم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کا مسجد حرام سے مسجد اقصی تک کی سیر فرمانا ۔ اس پر ایمان لانا فرض اور اس کا انکار کر نے والا کافر ہے ۔ ([2])\n (اشعۃ اللمعات ، ج۴، ص ۵۲۷)\n (۴)…جو معجزہ احادیث ِمشہورہ سے ثابت ہو ۔ جیسے سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کا معراج کی رات میں آسمانوں کی سیر فرمانا۔ اس کا ماننا لازم و ضروری ہے ۔ اور اس کا منکر گمراہ بدمذہب ہے ۔ ([3]) (تفسیرات احمدیہ، ص ۳۲۸)\n (۵)…جو معجزہ خبر واحد سے ثابت ہو خواہ علی وجہ القوۃ یا علی وجہ الضعف فضائل میں وہ بھی معتبر ہے ۔\n (۶)…انبیائے کرام علیہم الصلاۃ والسلام سے قبل نبوت جو بات خرقِ عادت کے طور پر صادر ہو اسے ارہاص کہتے ہیں حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ فرماتے ہیں: ’’ خوارق عادت کہ پیش از ظہور نبوت ظاہر شدآں را ارہاصات گویند ‘‘۔ ([4]) (اشعۃ اللمعات، جلد چہارم ص ۵۴۱)\n------------------\n[1] ’’ التعریفات ‘‘ للجرجانی ، ص ۱۵۳.\n[2] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب فی المعراج ، ج ۴، ص ۵۵۰.\n[3] ’’ التفسیرات الأحمدیۃ ‘‘، ص ۵۰۳.\n[4] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب المعجزات ، ج ۴، ص ۵۶۲."}, {"id": 7881, "bookId": 14, "volNo": "1", "hadithNo": 114, "chapter": "کرامت", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’عَنِ ابْنِ عُمَرَ أَنَّ عُمَرَ رَضِیَ اللّٰہ تَعَالَی عَنْہُ بَعَثَ جَیْشًا وَأَمَرَّ عَلَیْہِمْ رَجُلًا یُدْعَی سَارِیَۃُ فَبَیْنَمَا عُمَرُ یَخْطُبُ فَجَعَلَ یَصِیْحُ یَا سَارِیَۃُ الْجَبَلَ فَقَدِمَ رَسُوْلٌ مِنَ الْجَیْشِ فَقَالَ یَا أَمِیْرَ الْمُؤْمِنِیْنَ لَقِیَنَا عَدُوُّنَا فَہَزَمُوْنَا فَإِذَا بِصَاءِحٍ یَصِیْحُ یَا سَارِیَۃُ الْجَبَلَ فَأَسْنَدَنَا ظَہُوْرَنَا إِلَی الْجَبَلِ فَہَزَمَہُمُ اللّٰہ تَعَالَی‘‘۔ \nحدیث 2:\n’’عَنِ ابْنِ الْمُنْکَدِرْ أَنَّ سَفِیْنَۃَ مَوْلَی رَسُوْلِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ أَخْطَأَ الْجَیْشَ بِأَرْضِ الرُّوْمِ أَوْ أُسِرَ فَانْطَلَقَ ہَارِبًا یَلْتَمِسُ الْجَیْشَ فَإِذَا ہُوَ بِالْأَسَدِ فَقَالَ یَا أَبَا الْحَارِثِ أَنَا مَوْلَی رَسُوْلِ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ کَانَ مِنْ أَمْرِی کَیْتَ وَکَیْتَ فَأَقْبَلَ الْأَسَدُ لَہُ بَصْبَصَۃٌ حَتَّی قَامَ إِلَی جَنْبِہِ کُلَّمَا سَمِعَ صَوْتًا أَہْوَی إِلَیْہِ ثُمَّ أَقْبَلَ یَمْشِی إِلَی جَنْبِہِ حَتَّی بَلَغَ الْجَیْشَ ثُمَّ رَجَعَ الْأَسَدُ‘‘۔\nحدیث 3:\n’’ عَنْ أَنَسٍ أَنَّ أُسَیْدَ بْنَ حُضَیْرٍ وَعَبَّادَ بْنَ بِشْرٍ تَحَدَّثَا عِنْدَ النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فِی حَاجَۃٍ لَہُمَا حَتَّی ذَہَبَ مِنَ اللَّیْلِ سَاعَۃٌ فِی لَیْلَۃٍ شَدِیدَۃِ الظُّلْمَۃِ ثُمَّ خَرَجَا مِنْ عِنْدَ رَسُولِ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ یَنْقَلِبَانِ وَبِیَدِ کُلِّ وَاحِدٍ مِنْہُمَا عُصَیَّۃٌ فَأَضَاءتْ عَصَا أَحَدِہِمَا لَہُمَا حَتَّی مَشَیَا فِی ضَوْءِ ہَا حَتَّی إِذَا افْتَرَقَتْ بِہِمَا الطَّرِیقُ أَضَاءَ تْ لِلْآخَرِ عَصَاہُ فَمَشَی کُلُّ وَاحِدٍ مِنْہُمَا فِی ضَوْءعَصَاہُ حَتَّی بَلَغَ أَہْلَہُ ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت ابن عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے کہ حضرت فاروق اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے ایک لشکر (نہاوند( )کی طرف) بھیجا اور اس لشکر پر ایک مرد کو سپہ سالار مقرر فرمایا جن کو ساریہ کہا جاتاتھا تو (ایک روز) جب کہ حضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ ( مدینہ شریف میں) خطبہ پڑھ رہے تھے یکایک آپ بلند آواز فرمانے لگے اے ساریہ ! پہاڑکی پناہ لو۔ (چند روز کے بعد) لشکر سے ایک قاصد آیا تو اس نے عرض کیا اے امیر المؤمنین! ہمارے دشمن نے ہم پر حملہ کیا تو ہم کو شکست دی پھر اچانک ہم نے ایک پکارنے والے کی آواز سنی کہ اے ساریہ ! پہاڑ کی پناہ لو۔ تو ہم نے پہاڑ کی طرف اپنی پشت کرلی ( اور دشمن سے لڑے ) پھر خدائے تعالیٰ نے دشمنوں کو شکست دی۔ (بیہقی، مشکوۃ ص ۵۴۶)\n¥ترجمہ حدیث 2:\nحضرت ابن منکدر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ حضرت سفینہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ جو رسولِ کریم علیہ الصلاۃ والتسلیم کے غلام تھے (ایک مرتبہ) سرزمین روم میں اسلامی لشکر(تک پہنچنے )کا راستہ بھول گئے ۔ یا قید کر دیئے گئے تھے تو اسلامی لشکر کی تلاش میں نکل بھاگے ۔ اچانک ایک شیر سے ان کا سامنا ہوگیا تو آپ نے شیر سے فرمایا اے ابو حارث! میں سرکارِ اقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلہٖ وَسَلَّم کا غلام ہوں میرے ساتھ ایسا ایسا واقعہ پیش آیا ہے تو شیر (کتّے کی طرح) دُم ہلاتا ہوا قریب آکر حضرت سفینہ کے پہلو میں کھڑا ہو گیا ( اور ساتھ ساتھ چلتا رہا) جب شیر کسی چیز کی آواز سنتا تو اس کی طرف دوڑ پڑتا پھر واپس آکر ان کے پہلو میں چلنے لگتا یہاں تک کہ حضرت سفینہ اسلامی لشکر تک پہنچ گئے پھر شیر واپس ہوگیا۔ (مشکوۃ ص ۵۴۵)\n¥ترجمہ حدیث 3:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ سے روایت ہے کہ اسید بن حضیر اور عباد بن بشیر رَضِیَ اللّٰہ تَعَالٰی عَنْہُم ا نبی کریم علیہ الصلاۃ والتسلیم سے اپنے کسی معاملہ میں ایک پہر رات گزرنے تک گفتگو کرتے رہے وہ رات بہت تاریک تھی۔ پھر وہ لوگ اپنے گھروں کو واپس ہونے کے لیے رسولِ کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کی بارگاہ سے نکلے اور دونوں حضر ات کے ہاتھ میں چھوٹی چھوٹی لاٹھیاں تھیں پھر ان میں سے ایک صاحب کی لاٹھی دونوں کے لیے روشن ہوگئی بعدہ وہ دونوں حضرات لاٹھیوں کی روشنی میں چلتے رہے یہاں تک کہ جب دونوں کا راستہ علیحدہ علیحدہ ہوا تو دوسرے کی لاٹھی بھی روشن ہوگئی پھر ہر ایک اپنی اپنی لاٹھی کی روشنی میں اپنے گھر والوں تک پہنچ گیا۔ (بخاری، مشکوۃ ص ۵۴۴)", "roman": "Tarjuma Hadees 1: Hazrat Ibn Abbas Radiyallahu Anhu se riwayat hai ke Hazrat Farooq-e-Azam Radiyallahu Anhu ne ek lashkar (Nihawand ki taraf) bheja aur is lashkar par ek shakhs ko sipah-salar muqarrar farmaya jin ko Sariyah kaha jata tha to (ek roz) jab ke Hazrat Umar Radiyallahu Anhu (Madina Shareef mein) Khutbah parh rahe thay yak-ayak aap buland aawaz farmane lage ae Sariyah! Pahar ki panah lo. (Chand roz ke baad) lashkar se ek qasid aaya to us ne arz kiya ae Ameer-ul-Momineen! Hamare dushman ne hum par hamla kiya to hum ko shikast di phir achanak hum ne ek pukarne wale ki aawaz suni ke ae Sariyah! Pahar ki panah lo. To hum ne pahar ki taraf apni pusht kar li (aur dushman se lare) phir Khuda-e-Ta'ala ne dushmanon ko shikast di. (Baihaqi, Mishkat s 546). Tarjuma Hadees 2: Hazrat Ibn Munkadir Radiyallahu Anhu se riwayat hai ke Hazrat Safinah Radiyallahu Anhu jo Rasoolullah Sallallahu Alaihi wa Sallam ke ghulam thay (ek martaba) sarzameen-e-Room mein Islami lashkar (tak pahunchne) ka rasta bhool gaye. Ya qaid kar diye gaye thay to Islami lashkar ki talash mein nikal bhage. Achanak ek sher se un ka samna ho gaya to aap ne sher se farmaya ae Abu Haris! Main Sarkar-e-Aqdas Sallallahu Alaihi wa Sallam ka ghulam hoon mere sath aisa aisa waqia pesh aaya hai to sher (kutte ki tarah) Damm hilata hua qareeb aa kar Hazrat Safinah ke pehlu mein khara ho gaya (aur sath sath chalta raha) jab sher kisi cheez ki aawaz sunta to us ki taraf dor parta phir wapas aa kar un ke pehlu mein chalne lagta yahan tak ke Hazrat Safinah Islami lashkar tak pahunch gaye phir sher wapas ho gaya. (Mishkat s 545). Tarjuma Hadees 3: Hazrat Anas Radiyallahu Anhu se riwayat hai ke Usaid bin Huzair aur Abbad bin Bashir Radiyallahu Anhum Nabi Kareem Sallallahu Alaihi wa Sallam se apne kisi mamla mein ek pehar raat guzarne tak guftagu karte rahe woh raat bohat tareek thi. Phir woh log apne gharon ko wapas hone ke liye Rasoolullah Sallallahu Alaihi wa Sallam ki bargah se nikle aur dono hazrat ke hath mein choti choti lathiyan thin phir un mein se ek sahib ki lathi dono ke liye roshan ho gayi ba'dah woh dono hazrat lathiyon ki roshni mein chalte rahe yahan tak ke jab dono ka rasta alaihda alaihda hua to dusre ki lathi bhi roshan ho gayi phir har ek apni apni lathi ki roshni mein apne ghar walon tak pahunch gaya. (Bukhari, Mishkat s 544).", "explanation": "¥انتباہ :\n (۱)… ولی سے جوبات خلافِ عادت ظاہر ہو اسے کرامت کہتے ہیں اور عام مؤمنین سے ایسی بات صادر ہو تو اسے معونت کہتے ہیں ۔ اور بیباک فاسق و فاجر یا کافرسے جو اُن کے موافق ظاہر ہو تو اس کو استدراج کہتے ہیں اور ان کے خلاف ظاہر ہو تو اہانت کہتے ہیں۔ ([1]) (بہار شریعت، حصہ اول)\n (۲)…کرامت حق ہے اس کا انکار کرنے والا گمراہ بدمذہب ہے ۔ شرح فقہ اکبر ص ۹۵ میں ہے : اَلْکَرَامَاتُ لِلأَوْلِیَاءِ حَقٌّ أَيْ ثَابِتٌ بِالْکِتَابِ وَالسُّنَّۃِ ا ولیائے کرام سے کرامتوں کا صادر ہونا حق ہے ۔ یعنی قرآن و حدیث سے ثابت ہے ۔ ([2]) \n اور حضرت شیخ عبدالحق محدث دہلوی بخاری رَحْمَۃُ اللّٰہ عَلَیْہِ فرماتے ہیں:\n’’ اہلِ حق اتفاق دارند برجواز وقوع کرامت از اولیاء ودلیل بر وقوع کرامت کتاب وسنت وتواتر اخبار ست از صحابہ ومن بعد ہم تواتر معنی ‘‘ ۔ ([3]) \nیعنی اہلِ حق اس بات پر متفق ہیں کہ اولیائے کرام سے کرامت کا ظہور ہوسکتا ہے ۔ اور اللّٰہ والوں سے کرامتوں کا صادر ہونا قرآن و حدیث سے ثابت ہے ، اورصحابہ و تابعین کی مسلسل خبروں سے بھی واضح ہے ۔ (اشعۃ اللمعات، جلد چہارم ص ۵۹۵)\n (۳)…ولی وہ مسلمان ہے جو بقدرِ طاقت بشری ذات و صفات باری تعالیٰ کا عارف ہو، احکام شرع کا پابند ہو اور لذات و شہوات میں انہماک نہ رکھتا ہو۔ جیسا کہ شرع عقائد نسفی میں ہے :’’ اَلْوَلِیُّ ھُوَالْعَارِفُ بِاللّٰہ تَعَالَی وَصِفَاتِہِ حَسْب مَا یُمْکِنُ الْمُوَاظب عَلَی الطَّاعَاتِ ، الْمُجْتَنِبُ عَنِ الْمَعَاصِی ، الْمُعْرِضُ عَنِ الْاِنْھِمَاکِ فِی اللَّذاتِ وَالشَّھَوَاتِ ۔ ‘‘([4]) \n اور اشعۃ اللمعات جلد چہارم ص :۵۹۵میں ہے : ’’ ولی کسے ست کہ عارف باشد بذات وصفات حق بر قدر طاقت بشری ومواظب باشد بر اتیاں طاعت وترک منہیات در لذات وشہوات وکامل باشد در تقویٰ واتباع بر حسب تفاوت ومراتب آن ‘‘۔ ([5]) \n (۴)…ولی وہی شخص ہوسکتا ہے جس کا عقیدہ مذہب اہلِ سنت و جماعت کے مطابق ہو کوئی مرتد یا بدمذہب مثلاً دیوبندی ، وہابی ، قادیانی ، رافضی اور نیچری وغیرہ ہر گز ولی نہیں ہوسکتا۔\n (۵)…اولیائے کرام وصالحین عظام کا فیض بعد وصال جار ی رہتا ہے ۔ تفسیر عزیزی پارہ عم ص ۵۰ میں ہے : ’’ از اولیائے مدفونین ودیگر صلحائے مؤمنین انتفاع واستفادہ جاری ست و آنہارا افادہ و اعانت نیز متصور ‘‘۔\n اولیاء راہست قدرت ازالہ \n تیر جستہ باز گرد انندز راہ\n------------------\n[1] ’’بہار شریعت‘‘، ج۱، ص ۵۸.\n[2] ’’ شرح الفقہ الأکبر ‘‘، ص ۷۹.\n[3] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب الکرامات ، ج ۴، ص ۶۰۹.\n[4] ’’ شرح العقائد النسفیۃ ‘‘، ص ۱۴۵.\n[5] ’’ اشعۃ اللمعات ‘‘، کتاب الفتن ، باب الکرامات ، ج ۴، ص ۶۰۹."}, {"id": 7882, "bookId": 14, "volNo": "1", "hadithNo": 115, "chapter": "علم غیب", "subChapter": "", "narrator": "", "hadeesName": "", "arabic": "حدیث 1:\n’’ عَنْ عُمَرَ قَالَ قَامَ فِینَا رَسُوْلُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَقَامًا فَأَخْبَرَنَا عَنْ بَدْء الْخَلْقِ حَتَّی دَخَلَ أَہْلُ الْجَنَّۃِ مَنَازِلَہُمْ وَأَہْلُ النَّارِ مَنَازِلَہُمْ حَفِظَ ذَلِکَ مَنْ حَفِظَہُ وَنَسِیَہُ مَنْ نَسِیَہُ‘‘۔\nحدیث 2:\n’’ عَنْ أَبِی زَیْدٍ یَعْنِی عَمْرَو بْنَ أَخْطَبَ الْاَنْصَارِی قَالَ صَلَّی بِنَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ الْفَجْرَ وَصَعِدَ الْمِنْبَرَ فَخَطَبَنَا حَتَّی حَضَرَتِ الظُّہْرُ فَنَزَلَ فَصَلَّی ثُمَّ صَعِدَ الْمِنْبَرَ فَخَطَبَنَا حَتَّی حَضَرَتِ الْعَصْرُ ثُمَّ نَزَلَ فَصَلَّی ثُمَّ صَعِدَ الْمِنْبَرَ فَخَطَبَنَا حَتَّی غَرَبَتِ الشَّمْسُ فَأَخْبَرَنَا بِمَا کَانَ وَبِمَا ہُوَ کَاءِنٌ فَأَعْلَمُنَا أَحْفَظُنَا ‘‘۔\nحدیث 3:\n’’ عَنْ ثَوْبَانَ قَالَ قَالَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ إِنَّ اللّٰہ زَوَی لِی الْأَرْضَ فَرَأَیْتُ مَشَارِقَہَا وَمَغَارِبَہَا‘‘۔ \nحدیث 4:\n’’ عَنْ حُذَیْفَۃَ قَالَ وَاللّٰہ مَا أَدْرِی أَنَسِیَ أَصْحَابِی أَمْ تَنَاسَوْا وَاللّٰہ مَا تَرَکَ رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مِنْ قَاءِدِ فِتْنَۃٍ إِلَی أَنْ تَنْقَضِیَ الدُّنْیَا یَبْلُغُ مَنْ مَعَہُ ثَلَاثَ مِاءَۃٍ فَصَاعِدًا إِلَّا قَدْ سَمَّاہُ لَنَا بِاسْمِہِ وَاسْمِ أَبِیہِ وَاسْمِ قَبِیلَتِہِ‘‘\nحدیث 5:\n’’ عَنْ أَنَسٍ قَالَ نَعَی النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ زَیْدًا وَجَعْفَرًا وَابْنَ رَوَاحَۃَ لِلنَّاسِ قَبْلَ أَنْ یَأْتِیَہُمْ خَبرُہُمْ فَقَالَ أَخَذَ الرَّایَۃَ زَیْدٌ فَأُصِیبَ ثُمَّ أَخَذَ جَعْفَرٌ فَأُصِیبَ ثُمَّ أَخَذَ ابْنُ رَوَاحَۃَ فَأُصِیبَ وَعَیْنَاہُ تَذْرِفَانِ حَتَّی أَخَذَ الرَّایَۃَ سَیْفٌ مِنْ سُیُوفِ اللّٰہ یَعْنِی خَالِدَ بْنَ الْوَلِیْدِ حَتَّی فَتَحَ اللّٰہ عَلَیْہِمْ‘‘۔ \nحدیث 6:\n’’ عَنِ ابْنِ عَبَّاسٍ قَالَ مَرَّ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ بِحَاءِطٍ مِنْ حِیطَانِ الْمَدِینَۃِ أَوْ مَکَّۃَ فَسَمِعَ صَوْتَ إِنْسَانَیْنِ یُعَذَّبَانِ فِی قُبُورِہِمَا فَقَالَ النَّبِیُّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ مَا یُعَذَّبَانِ فِی کَبِیرٍ ثُمَّ قَالَ بَلَی کَانَ أَحَدُہُمَا لَا یَسْتَتِرُ مِنْ بَوْلِہِ وَکَانَ الْآخَرُ یَمْشِی بِالنَّمِیمَۃِ ثُمَّ دَعَا بِجَرِیدَۃٍ فَکَسَرَہَا کِسْرَتَیْنِ فَوَضَعَ عَلَی کُلِّ قَبْرٍ مِنْہُمَا کِسْرَۃً فَقِیلَ لَہُ یَا رَسُولَ اللّٰہ لِمَ فَعَلْتَ ہَذَا قَالَ لَعَلَّہُ أَنْ یُخَفَّفَ عَنْہُمَا مَا لَمْ تَیْبَسَا‘‘۔\nحدیث 7:\n’’ عَنْ أَبِی ہُرَیْرَۃَ أَنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ ہَلْ تَرَوْنَ قِبْلَتِی ہَاہُنَا فَوَاللّٰہ مَا یَخْفَی عَلَیَّ خُشُوعُکُمْ وَلَا رُکُوعُکُمْ إِنِّی لَأَرَاکُمْ مِنْ وَرَاء ظَھْرِیْ‘‘۔\nحدیث 8:\n’’ عَنْ أَبِی ہُرَیْرَۃَ قَالَ جَاءَ ذِئْبٌ إِلَی رَاعِی غَنَمٍ فَأَخَذَ مِنْہَا شَاۃً فَطَلَبَہُ الرَّاعِی حَتَّی انْتَزَعَہَا مِنْہُ قَالَ فَصَعِدَ الذِّئْبُ عَلَی تَلٍّ فَأَقْعَی وَاسْتَثْـفَرَ وَقَالَ عَمَدْتُ إِلَی رِزْقٍ رَزَقَنِیہِ اللّٰہ عَزَّ وَجَلَّ أَخَذْتُہُ ثُمَّ انْتَزَعْتَہُ مِنِّی فَقَالَ الرَّجُلُ تَاللّٰہ إِنْ رَأَیْتُ کَالْیَوْمِ ذِئْبٌ یَتَکَلَّمُ فَقَالَ الذِّئْبُ أَعْجَبُ مِنْ ہَذَا رَجُلٌ فِی النَّخَلَاتِ بَیْنَ الْحَرَّتَیْنِ یُخْبِرُکُمْ بِمَا مَضَی وَبِمَا ہُوَ کَاءِنٌ بَعْدَکُمْ قَالَ فَکَانَ الرَّجُلُ یَہُودِیًّا فَجَاءَ إِلَی النَّبِیِّ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ فَأَخْبَرَہُ وَأَسْلَمَ ‘‘۔ \nحدیث 9:\n’’ عَنْ أَنَسٍ قَالَ قَالَ عُمَرُ إِنَّ رَسُولَ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ کَانَ یُرِینَا مَصَارِعَ أَہْلِ بَدْرٍ بِالْأَمْسِ یَقُولُ ہَذَا مَصْرَعُ فُلَانٍ غَدًا إِنْ شَاءَ اللّٰہ وَہَذَا مَصْرَعُ فُلَانٍ غَدًا إِنْ شَاءَ اللّٰہ قَالَ عُمَرُ فَوَالَّذِی بَعَثَہُ بِالْحَقِّ مَا أَخْطَؤا الْحُدُودَ الَّتِی حَدَّہَا رَسُولُ اللّٰہ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ قَالَ فَجُعِلُوا فِی بِئْرٍ بَعْضُہُمْ عَلَی بَعْضٍ‘‘۔", "urdu": "¥ترجمہ حدیث 1:\nحضرت فاروق اعظم رَضِیَ اللّٰہ تَعَالٰی عَنْہُ فرماتے ہیں کہ ایک بار حضور علیہ الصلاۃ والسلام ہم لوگوں (کے مجمع) میں کھڑے ہوئے تو حضور نے ابتدائے آفرنیش سے جنتیوں کے جنت میں اور دوزخیوں کے دوزخ میں داخل ہونے تک کے سارے حالات کی ہمیں خبر دے دی۔ ( حضور سے سننے والوں میں) جس نے اس بیان کو یاد رکھا اس نے یاد رکھا اور جو بھول گیا وہ بھول گیا۔ (بخاری، ج۱ ص۴۵۳، مشکوۃ ص ۵۱۶)\n¥ترجمہ حدیث 2:\nحضرت ابوزید یعنی عمرو بن اخطب انصاری رَضِیَ اللّٰہ تَعَالٰی عَنْہُ فرماتے ہیں کہ حضور علیہ الصلاۃ والسلام نے ہمیں فجر کی نماز پڑھائی اور منبر پر رونق افروز ہو کر ہمارے سامنے تقریر فرمائی یہاں تک کہ ظہر کی نماز کا وقت آگیا پھر منبر سے تشریف لاکر نمازپڑھائی اس کے بعد منبر پر تشریف لے گئے پھر ہمارے سامنے تقریر فرمائی یہاں تک کہ عصر کی نماز کا وقت آگیاپھر منبرسے اُتر کر نماز پڑھائی اس کے بعد منبرپر تشریف لے گئے یہاں تک کہ سورج ڈوب گیا تو اس تقریر میں جو کچھ ہوا اور جو کچھ ہونے والا ہے تمام واقعات کی حضور نے ہمیں خبر دے دی تو ہم لوگوں میں سب سے بڑا عالم وہ شخص ہے جسے حضور کی بتائی ہوئی خبریں زیادہ یاد ہیں۔ (مسلم، جلد دوم ص ۳۹۰)\n¥ترجمہ حدیث 3:\nحضرت ثوبان رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ حضور علیہ الصلاۃ والسلام نے فرمایا کہ اللّٰہ تعالیٰ نے میرے لیے زمین سمیٹ دی تو میں نے مشرق سے مغرب تک زمین کا تمام حصہ دیکھ لیا۔ (مسلم، مشکوۃ ص ۵۱۲)\n¥ترجمہ حدیث 4:\nحضرت حذیفہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ خدا تعالیٰ کی قسم میں نہیں کہہ سکتا کہ میرے ساتھی بھول گئے ہیں یا بھول جانے کا اظہار کرتے ہیں( آج سے ) دنیا کے ختم ہونے تک جتنے فتنے انگیز لوگ پیدا ہوں گے جن کے ساتھیوں کی تعداد تین سو سے زائد ہوگی خدائے تعالیٰ کی قسم حضور نے ہمیں ان کا نام ان کے باپ کا نام اور ان کے خاندان کا نام ( سب کچھ) بتادیا۔ (ابوداود، مشکوۃ ص ۴۶۳)\n¥ترجمہ حدیث 5:\nحضرت انس رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ سرکار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ نے حضرت زید، حضرت جعفر اور حضرت ابن رواحہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم کی شہادت کی خبر آنے سے پہلے ان لوگوں کے شہید ہوجانے کی اطلاع دیتے ہوئے فرمایا کہ زید نے جھنڈا ہاتھ میں لیا اور شہید کیے گئے پھر جھنڈے کو جعفر نے سنبھالااور وہ بھی شہید ہوئے پھر ابن رواحہ نے جھنڈے کو لیا اور وہ بھی شہید کیے گئے ۔ آپ یہ واقعہ بیان فرما رہے تھے اور آنکھوں سے آنسو جاری تھے ۔ پھر آپ نے فرمایا کہ اس کے بعد جھنڈے کو اس شخص نے لیا جو خدائے تعالیٰ کی تلواروں میں سے ایک تلوار ہے یعنی حضرت خالد بن ولید ( نے جھنڈا لیا اور خوب گھمسان کی لڑائی لڑتے رہے ) یہاں تک کہ اللّٰہ تعالیٰ نے مسلمانوں کو فتح عطا فرمائی۔ (بخاری، مشکوۃ ص ۵۳۳)\n¥ترجمہ حدیث 6:\nحضرتِ ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے کہ نبی کریم علیہ الصلاۃ والتسلیم مدینہ یا مکہ کے باغات میں سے کسی باغ میں تشریف لے گئے تو دوآدمیوں کی آواز سنی جن پر ان کی قبروں میںعذاب ہو رہا تھا آپ نے فرمایا ان دونوں پر عذاب ہورہا ہے ۔ مگر کسی بڑی بات پر نہیں۔ پھر فرمایا ہاں (خدائے تعالیٰ کے نزدیک بڑی بات ہے ) اِن میں سے ایک تو اپنے پیشاب سے نہیں بچتا تھا اور دوسرا چغلی کھایا کرتا تھا۔ پھر آپ نے کھجور کی ایک تر شاخ منگوائی اور اس کے دو ٹکڑے کیے اور ہر ایک کی قبر پر ایک ایک ٹکڑا رکھ دیا۔ حضور سے عرض کیا گیا یارسول اللّٰہ ! یہ آپ نے کیوں کیا؟فرمایا امید ہے کہ جب تک یہ شاخیں خشک نہ ہوجائیں ان دونوں پر عذاب کم رہے گا۔ (بخاری، ج۱ ص ۳۵)\n¥ترجمہ حدیث 7:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے کہا کہ رسولِ کریم علیہ الصلاۃ والتسلیم نے فرمایا کیا تم یہ سمجھتے ہو کہ میرا قبلہ یہ ہے بخدا مجھ پر نہ تمہارا خشوع پوشیدہ ہے اور نہ رکوع۔ میں تمہیں اپنی پیٹھ کے پیچھے سے بھی دیکھتا ہوں۔ (بخاری، ج۱ ص ۱۰۲)\n¥ترجمہ حدیث 8:\nحضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ ایک بھیڑیا بکریوں کے چرواہے کی جانب آیا پھر اس کے ریوڑ میں سے ایک بکری اٹھالے گیا۔ چرواہے نے اس کا پیچھا کیا یہاں تک کہ بکری کو اس سے چھین لیا۔ حضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ فرماتے ہیں کہ پھر وہ بھیڑیا ایک ٹیلہ پر چڑھ کر اپنی دم پر بیٹھا اور بولا کہ میں نے اپنے رزق کا قصد کیا تھا جو مجھ کو خدائے تعالیٰ نے دیا میں نے اس پر قبضہ کیا تھا لیکن اے چروا ہے !تو نے اس کو مجھ سے چھین لیا۔ چرواہے نے کہا خدا کی قسم ( ایسی عجیب بات) میں نے آج کی طرح کبھی نہ دیکھی کہ بھیڑیا بولتا ہے ۔ \nبھیڑیئے نے کہا اس سے زیادہ عجیب ان صاحب ( یعنی حضور صلی اللّٰہ تعالیٰ علیہ وسلم ) کا حال ہے جو دو سنگستانوں کے درمیانی نخلستان ( مدینہ) میں تشریف فرما ہو کر تم لوگوں سے ان تمام ( غیبی) واقعات کو بیان کررہے ہیں جو گزر چکے اور جو واقعات تمہارے بعد ہونے والے ہیں ان کو بھی بتاتے ہیں۔ حضرت ابوہریرہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُ کا بیان ہے کہ وہ چرواہا یہودی تھا بھیڑیئے سے یہ بات سُن کر حضور کی خدمت میں حاضر ہوا۔ واقعہ بیان کیا اور مسلمان ہوگیا۔ (مشکوۃ ص ۵۴۱)\n¥ترجمہ حدیث 9:\nحضرت انس رضی اللّٰہ تعالی عنہ نے کہا حضرت عمر رَضِیَ اللّٰہ تَعَالٰی عَنْہُ نے فرمایا کہ حضور علیہ الصلاۃ والسلام نے جنگ بدر سے ایک روز پہلے ہم لوگوں کو وہ تمام مقامات دکھا دیئے تھے جہاں بدر کی لڑائی میں شریک ہونے والے مشرکین قتل ہوئے چنانچہ آپ نے فرمایا دیکھو کل ان شاء اللّٰہ تعالیٰ یہاں فلاں مشرک گر کر مرے گا اور کل ان شاء اللّٰہ تعالیٰ یہاں فلاں شخص قتل ہو کر گرے گا۔ حضرت عمر رضی اللّٰہ تعالی عنہ نے فرمایا قسم ہے اس ذات کی جس نے رسول اللّٰہ صلی اللّٰہ تعالیٰ علیہ وسلم کو حق کے ساتھ بھیجا ہے کہ جو مقامات حضور علیہ الصلاۃ والسلام نے بتادیئے تھے ان سے ذرا بھی تجاوز نہیں ہوا۔ یعنی وہ کافر اسی جگہ مارے گئے جو جگہ حضور علیہ الصلاۃ والسلام نے بتادی تھی۔ پھر ان کافروں کو کنوئیں کے اندر تلے اوپر ڈال دیا گیا۔ (مشکوۃ ص ۵۴۳)", "roman": "Tarjuma Hadees 1: Hazrat Farooq-e-Azam Radiyallahu Anhu farmate hain ke ek baar Huzoor Sallallahu Alaihi wa Sallam hum logon (ke majmay) mein khare hue to Huzoor ne ibtida-e-afrinish se jannatiyon ke jannat mein aur dozakhiyon ke dozakh mein dakhil hone tak ke saare halaat ki hamain khabar de di. (Huzoor se sunne walon mein) jis ne is bayan ko yaad rakha us ne yaad rakha aur jo bhool gaya woh bhool gaya. (Bukhari, Jild 1 s 453, Mishkat s 516). Tarjuma Hadees 2: Hazrat Abu Zaid yani Amr bin Akhtab Ansari Radiyallahu Anhu farmate hain ke Huzoor Sallallahu Alaihi wa Sallam ne hamain Fajr ki Namaz parhai aur Mimbar par ronaq afroz ho kar hamare samne taqreer farmayi yahan tak ke Zuhr ki Namaz ka waqt aa gaya phir Mimbar se tashreef la kar Namaz parhai us ke baad Mimbar par tashreef le gaye phir hamare samne taqreer farmayi yahan tak ke Asr ki Namaz ka waqt aa gaya phir Mimbar se utar kar Namaz parhai us ke baad Mimbar par tashreef le gaye yahan tak ke suraj doob gaya to is taqreer mein jo kuch hua aur jo kuch hone wala hai tamam waqiat ki Huzoor ne hamain khabar de di to hum logon mein sab se bara aalim woh shakhs hai jise Huzoor ki batayi hui khabrain zyada yaad hain. (Muslim, Jild 2 s 390). Tarjuma Hadees 3: Hazrat Sauban Radiyallahu Anhu ne kaha ke Huzoor Sallallahu Alaihi wa Sallam ne farmaya ke Allah Ta'ala ne mere liye Zameen samet di to main ne mashriq se Maghrib tak Zameen ka tamam hissa dekh liya. (Muslim, Mishkat s 512). Tarjuma Hadees 4: Hazrat Huzaifah Radiyallahu Anhu ne farmaya ke Khuda Ta'ala ki qasam main nahi keh sakta ke mere sathi bhool gaye hain ya bhool jaane ka izhaar karte hain (aaj se) duniya ke khatam hone tak jitne fitne angez log paida honge jin ke sathiyon ki tadaad teen sau se zaid hogi Khuda-e-Ta'ala ki qasam Huzoor ne hamain un ka naam un ke baap ka naam aur un ke khandan ka naam (sab kuch) bata diya. (Abu Dawood, Mishkat s 463). Tarjuma Hadees 5: Hazrat Anas Radiyallahu Anhu ne farmaya ke Sarkar-e-Aqdas Sallallahu Alaihi wa Sallam ne Hazrat Zaid, Hazrat Jafar aur Hazrat Ibn Rawahah Radiyallahu Anhum ki Shahadat ki khabar aane se pehle un logon ke Shaheed ho jaane ki ittila dete hue farmaya ke Zaid ne jhanda hath mein liya aur Shaheed kiye gaye phir jhande ko Jafar ne sambhala aur woh bhi Shaheed hue phir Ibn Rawahah ne jhande ko liya aur woh bhi Shaheed kiye gaye. Aap yeh waqia bayan farma rahe thay aur aankhon se aansu jaari thay. Phir aap ne farmaya ke is ke baad jhande ko us shakhs ne liya jo Khuda-e-Ta'ala ki talwaron mein se ek talwar hai yani Hazrat Khalid bin Waleed (ne jhanda liya aur khoob ghamsan ki larai larte rahe) yahan tak ke Allah Ta'ala ne musalmanon ko fatah ata farmayi. (Bukhari, Mishkat s 533). Tarjuma Hadees 6: Hazrat Ibn Abbas Radiyallahu Anhu se riwayat hai ke Nabi Kareem Sallallahu Alaihi wa Sallam Madina ya Makkah ke baghat mein se kisi bagh mein tashreef le gaye to do aadmiyon ki aawaz suni jin par un ki Qabr mein azab ho raha tha aap ne farmaya in dono par azab ho raha hai. Magar kisi bari baat par nahi. Phir farmaya haan (Khuda-e-Ta'ala ke nazdeek bari baat hai) in mein se ek to apne Peshaab se nahi bachta tha aur dusra chughli khaya karta tha. Phir aap ne khajoor ki ek tar shakh mangwayi aur us ke do tukre kiye aur har ek ki Qabr par ek ek tukra rakh diya. Huzoor se arz kiya gaya Ya Rasoolullah! Yeh aap ne kyun kiya? Farmaya umeed hai ke jab tak yeh shakhein khushk na ho jayain in dono par azab kam rahega. (Bukhari, Jild 1 s 35). Tarjuma Hadees 7: Hazrat Abu Hurairah Radiyallahu Anhu ne kaha ke Rasoolullah Sallallahu Alaihi wa Sallam ne farmaya kya tum yeh samajhte ho ke mera Qiblah yeh hai bakhuda mujh par na tumhara khushoo posheeda hai aur na Rukoo. Main tumhain apni peeth ke peeche se bhi dekhta hoon. (Bukhari, Jild 1 s 102). Tarjuma Hadees 8: Hazrat Abu Hurairah Radiyallahu Anhu ne farmaya ke ek bheriya bakriyon ke charwahe ki janib aaya phir us ke rewar mein se ek bakri utha le gaya. Charwahe ne us ka peecha kiya yahan tak ke bakri ko us se cheen liya. Hazrat Abu Hurairah Radiyallahu Anhu farmate hain ke phir woh bheriya ek teela par charh kar apni Damm par baitha aur bola ke main ne apne rizq ka qasd kiya tha jo mujh ko Khuda-e-Ta'ala ne diya main ne us par qabza kiya tha lekin ae charwahe! Tu ne us ko mujh se cheen liya. Charwahe ne kaha Khuda ki qasam (aisi ajeeb baat) main ne aaj ki tarah kabhi na dekhi ke bheriya bolta hai. Bheriye ne kaha is se zyada ajeeb in sahib (yani Huzoor Sallallahu Alaihi wa Sallam) ka haal hai jo do sangistanon ke darmiyani nakhlistan (Madina) mein tashreef farma ho kar tum logon se un tamam (ghaibi) waqiat ko bayan kar rahe hain jo guzar chuke aur jo waqiat tumhare baad hone wale hain un ko bhi batate hain. Hazrat Abu Hurairah Radiyallahu Anhu ka bayan hai ke woh charwaha Yahudi tha bheriye se yeh baat sun kar Huzoor ki khidmat mein hazir hua. Waqia bayan kiya aur musalman ho gaya. (Mishkat s 541). Tarjuma Hadees 9: Hazrat Anas Radiyallahu Anhu ne kaha Hazrat Umar Radiyallahu Anhu ne farmaya ke Huzoor Sallallahu Alaihi wa Sallam ne jang-e-Badr se ek roz pehle hum logon ko woh tamam maqamat dikha diye thay jahan Badr ki larai mein shareek hone wale mushrikeen qatl hue chunancha aap ne farmaya dekho kal Insha Allah Ta'ala yahan falan mushrik gir kar marega aur kal Insha Allah Ta'ala yahan falan shakhs qatl ho kar girega. Hazrat Umar Radiyallahu Anhu ne farmaya qasam hai us zaat ki jis ne Rasoolullah Sallallahu Alaihi wa Sallam ko haq ke sath bheja hai ke jo maqamat Huzoor Sallallahu Alaihi wa Sallam ne bata diye thay un se zara bhi tajawuz nahi hua. Yani woh Kaafir usi jagah mare gaye jo jagah Huzoor Sallallahu Alaihi wa Sallam ne bata di thi. Phir un kafiron ko kunwein ke andar tale oopar daal diya gaya. (Mishkat s 543).", "explanation": "¥شرح حدیث 1:\nمعلوم ہوا کہ سرکار ِاقدس صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ کو مخلوقات کی پیدائش سے لے کر جنتیوں کے جنت میں اور دوزخیوں کے دوزخ میں داخل ہونے تک کے سارے حالات کا علم ہے ۔ \n¥شرح حدیث 2:\nمعلوم ہوا کہ حضور سید عالم صلی اللّٰہ تعالیٰ علیہ وسلم کو ’’ مَاکَان وَمَا یَکُونُ ‘‘ کا علم ہے یعنی آپ گزشتہ اور آئندہ کے تمام واقعات جانتے ہیں۔ \n¥شرح حدیث 3:\nاس حدیث شریف سے معلوم ہوا کہ پورب سے پچھم تک زمین کا ہر حصہ حضورصلی اللّٰہ تعالیٰ علیہ وسلم کی نگاہ کے سامنے ہے ۔ \n¥شرح حدیث 4:\nمعلوم ہوا کہ حضور کا علم تمام کلیّات اور جزئیات کو گھیرے ہوئے ہے ۔ کہ آپ نے آئندہ پیدا ہونے والے فتنہ انگیزوں کے نام، ان کے باپ کا نام اور ان کے قبیلہ کا نام لوگوں سے بیان فرمایا۔ \n¥شرح حدیث 5:\nمعلوم ہوا کہ ساری دنیا کے حالات حضور کی نگاہ کے سامنے ہیں کہ جنگ موتہ جو ملک شام میں ہورہی تھی حضور اس کے حالات مدینہ منورہ میں بیٹھے ہوئے ملاحظہ فرمارہے تھے ۔ \n¥شرح حدیث 6:\nاس حدیث سے معلوم ہوا کہ:\n (۱)… حضور کی نگاہ کے لیے کوئی چیز آڑ نہیں بن سکتی یہاں تک کہ زمین کے اندر جو عذاب ہوتا ہے اسے آپ ملاحظہ فرماتے رہتے ہیں۔\n (۲)… حضور مخلوقات کے ہر کھلے اور چھپے کام کو دیکھ رہے ہیں کہ اس وقت کون کیا کررہا ہے اور پہلے کیا کرتا تھا چنانچہ آپ نے فرمادیا کہ ایک چغلی کرتا تھا اور دوسرا پیشاب سے نہیں بچتا تھا۔\n (۳)…حضور ہر گناہ کا علاج بھی جانتے ہیں کہ قبر پر شاخیں رکھ دیں تاکہ عذاب ہلکا ہو۔\n (۴)…قبروں پر سبزہ اور پھول وغیرہ ڈالنا سنت سے ثابت ہے کہ اس کی تسبیح سے مردہ کو راحت ہوتی ہے ۔\n (۵)…قبر پر قرآن پاک کی تلاوت کے لیے حافظ بٹھانا بہتر ہے کہ جب سبزہ کے ذکر سے عذاب ہلکا ہوتا ہے تو انسان کے ذکر سے ضرور ہلکا ہوگا۔\n (۶)…اگرچہ ہر خشک وترچیز تسبیح پڑھتی ہے مگر سبزے کی تسبیح سے مردہ کو راحت نصیب ہوتی ہے ایسے ہی بے دین کی تلاوتِ قرآن پاک کا کوئی فائدہ نہیں کہ اس میں کفر کی خشکی ہے اور مومن کی تلاوت مفید ہے کہ اس میں ایمان کی تری ہے ۔\n (۷)…سبزہ گنہگاروں کی قبر پر عذاب ہلکا کرے گا اور بزرگوں کی قبروں پر ثواب و درجہ بڑھائے گا۔ \n¥شرح حدیث 7:\nمعلوم ہوا کہ حضور کی مقدس آنکھیں عام آنکھوں کی طرح نہ تھیں۔ بلکہ حضور آگے پیچھے اوپر نیچے اور اندھیرے اجالے میں یکساں دیکھتے تھے یہاں تک کہ خشوع جو دل کی ایک کیفیت کا نام ہے حضور اسے بھی ملاحظہ فرماتے تھے ۔ \n¥شرح حدیث 8:\nمعلوم ہوا کہ جانور کا بھی عقیدہ ہے کہ حضور صلی اللّٰہ تعالیٰ علیہ وسلم کو ’’ مَاکَانَ وَمَا یَکُوْنُ ‘‘ کا علم ہے ۔ \n¥شرح حدیث 9:\nمعلوم ہوا کہ حضور کو ’’ بِأَیِّ أَرْضٍ تَمُوتُ ‘‘کا بھی علم ہے چنانچہ میدانِ بدر میں آپ نے فرمادیا کہ ان شاء اللّٰہ کل یہاں فلاں شخص قتل ہوگا۔ اور یہاں فلاں شخص مرے گا۔ پھر دوسرے روز حضور کے فرمانے کے مطابق ہوا یعنی جو مقامات آپ نے بتادیئے تھے ان سے ذرا بھی تجاوز نہیں ہوا۔\n¥اِنتباہ:\n (۱)… علمِ غیب ان باتوں کے جاننے کو کہتے ہیں جن کو بندے عادی طور پر اپنی عقل اور اپنے حواس سے معلوم نہ کرسکیں۔ تفسیر کبیر جلد اول ص: ۱۷۴ میں ہے :’’ اَلْغَیْبُ ھُوَالَّذِی یَکُوْنُ غَاءِبًا عَنِ الْحَاسَّۃِ ‘‘۔ اہـ ([1])\n (۲)…قرآن مجید پارہ ۲۹ ، رکوع بارہ میں ہے { عٰلِمُ الْغَیْبِ فَلَا یُظْهِرُ عَلٰى غَیْبِهٖۤ اَحَدًاۙ(۲۶) اِلَّا مَنِ ارْتَضٰى مِنْ رَّسُوْلٍ } یعنی غیب کا جاننے والا ( اللّٰہ تعالیٰ) تو وہ صرف اپنے پسندیدہ رسولوںکو ہی غیب پر قابو دیتا ہے ۔ معلوم ہوا کہ اللّٰہ تعالیٰ اپنے رسولو ں کو غیب پر قابو دیتا ہے ۔ اور جسے غیب پر قابو ہوتا ہے وہ غیب ضرور جانتا ہے تو ثابت ہوا کہ رسول غیب ضرور جانتے ہیں۔ ا س لیے کہ آیت ِ کریمہ کا خلاصہ ۔ ’’ اَلرَّسُوْلُ مُظْھَرٌ (صغریٰ) عَلَی الْغَیْبِ ‘‘ہے اور اس سے بھی کوئی انکار نہیں کرسکتاکہ’’ کُلُّ مُظْھَرٍ (کبریٰ) عَلَی الْغَیْب یَعْلَمُ الْغَیْبَ ‘‘تو ثابت ہوا کہ ’’ الرَّسُوْلُ یَعْلَمُ الْغَیْبَ ‘‘۔\n (۳)…امام غزالی رحمۃ اللّٰہ تعالیٰ علیہ فرماتے ہیں۔ ’’ إِنَّ لَہُ صِفَۃً بِھَا یُدْرِکُ مَا سَیَکُوْنُ فِی الْغَیْبِ ‘‘ یعنی نبی کے لیے ایک ایسی صفت ہوتی ہے کہ جس سے وہ آئندہ غیب کی باتیں جان لیا کرتے ہیں۔ ([2]) (زرقانی، جلد اول ص ۲۰)\n بارگاہِ رب العالمین جل جلالہ میں دعا ہے کہ اے مولائے کریم! احادیث و مسائل کے اس مجموعہ کو پیارے مصطفے صلی اللّٰہ تعالیٰ علیہ وسلم کے صدقہ میں اپنی رضا کے لیے قبول فرما۔ ہمیں اور ہمارے تمام برادرانِ اہل سنت کو اتباعِ سنت کی توفیق عطا فرما۔ اور اس مجموعہ سے بدمذہبوں اور بے عملوں کو توبہ کی توفیق عطا فرما کر ایمان وعمل کی نعمت نصیب فرما۔ ’’ إِنَّکَ عَلَی کُلِّ شَیْئٍ قَدِیْرٌ وَبِاِجَابَۃِ دُعَاءِنَا جَدِیْرٌ ‘‘۔ ’’ أَللَّھُمَّ بَدِیْعَ السَّمَوَاتِ وَالْأَرْضِ ذَا الْجَلَالِ وَالْاکْرَامِ خَالِقَ اللَّیْلِ وَالنَّھَارِ أَسْءَلُکَ أَنْ تُصَلِّیَ وَتُسَلِّمَ عَلَی أَوَّلِ خَلْقِ اللّٰہسَیِّدِنَا مُحَمَّدِن الْمُصْطَفَی وَعَلَی آلِہِ وَصَحْبِہِ وَأُصُوْلِہِ وَفُرُوْعِہِ وَابْنِہِ الْغَوْثِ الْأَعْظَمِ الْجِیْلَانِیِّ أَجْمَعِیْنَ وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ ﷲِ رَبِّ الْعَالَمِیْنَ ‘‘۔\n------------------\n[1] ’’ التفسیر الکبیر ‘‘، سورۃ البقرۃ ، آیۃ ۳، ج ۱، ص ۲۷۳.\n[2] ’’ الزرقانی ‘‘، ج ۱، ص ۲۰."}];
